def fbp_geometry_nodes_library_path():
    return Path(__file__).resolve().parent / "assets" / FBP_GN_LIBRARY_FILENAME


def _fbp_animation_key(effect_id, suffix):
    return fbp_effect_storage_key(
        "fbp_anim_", fbp_normalize_effect_id(effect_id), f"_{suffix}"
    )


def _fbp_effect_evolution_speed_property(effect_id, definition=None):
    """Return the cached visible Speed property for one Evolution contract."""
    effect_id = fbp_normalize_effect_id(effect_id)
    cached = _FBP_EFFECT_EVOLUTION_SPEED_KEY_CACHE.get(effect_id)
    if cached is not None:
        return cached
    definition = definition or fbp_effect_definition(effect_id)
    explicit = str((definition or {}).get("evolve_speed_property", "") or "")
    cached = explicit or _fbp_animation_key(effect_id, "speed")
    _FBP_EFFECT_EVOLUTION_SPEED_KEY_CACHE[effect_id] = cached
    return cached


_FBP_NOISE_MASK_64 = (1 << 64) - 1


def _fbp_stable_string_seed(value):
    """Return a stable process-independent 64-bit seed for an effect id."""
    result = 1469598103934665603
    for byte in str(value or "").encode("utf8", "replace"):
        result ^= int(byte)
        result = (result * 1099511628211) & _FBP_NOISE_MASK_64
    return result


def _fbp_mix64(value):
    """SplitMix64 finalizer used as a non-periodic frame hash."""
    value = int(value) & _FBP_NOISE_MASK_64
    value ^= value >> 30
    value = (value * 0xBF58476D1CE4E5B9) & _FBP_NOISE_MASK_64
    value ^= value >> 27
    value = (value * 0x94D049BB133111EB) & _FBP_NOISE_MASK_64
    value ^= value >> 31
    return value & _FBP_NOISE_MASK_64


def _fbp_effect_noise_u01(effect_id, stream_seed, step_index):
    """Deterministic random value for an unbounded timeline step.

    There is deliberately no modulo/loop length: every held timeline step is
    hashed independently, so Evolve does not return to an earlier phase.
    """
    value = _fbp_stable_string_seed(effect_id)
    value ^= (int(stream_seed) * 0x9E3779B97F4A7C15) & _FBP_NOISE_MASK_64
    value ^= (int(step_index) * 0xD1B54A32D192ED03) & _FBP_NOISE_MASK_64
    mixed = _fbp_mix64(value)
    return float(mixed >> 11) / float(1 << 53)


# Precomputed once at import time: frame-change handlers must avoid rebuilding
# registry-derived lists on every evaluated frame.
FBP_EVOLVE_EFFECT_PROPERTIES = tuple(
    (effect_id, _fbp_animation_key(effect_id, "evolve"))
    for effect_id, definition in FBP_EFFECT_REGISTRY.items()
    if definition.get("evolve_property")
)
FBP_FRAME_SYNC_GEOMETRY_EFFECT_IDS = tuple(
    effect_id
    for effect_id, definition in FBP_EFFECT_REGISTRY.items()
    if definition.get("kind") == "GEOMETRY"
    and (
        definition.get("alpha_aware")
        or definition.get("image_aware")
        or definition.get("procedural_frame_sync")
    )
)
FBP_PROCEDURAL_FRAME_SYNC_EFFECT_IDS = tuple(
    effect_id
    for effect_id, definition in FBP_EFFECT_REGISTRY.items()
    if definition.get("kind") == "GEOMETRY" and definition.get("procedural_frame_sync")
)
FBP_FRAME_SYNC_SHADER_EFFECT_IDS = tuple(
    effect_id
    for effect_id, definition in FBP_EFFECT_REGISTRY.items()
    if definition.get("kind") == "SHADER"
    and (definition.get("image_aware") or definition.get("mask_source_aware"))
)
# Hot-path sets: avoid rebuilding temporary sets in frame-change and render
# handlers. Keep the public tuples above for deterministic diagnostics/output.
FBP_GEOMETRY_EFFECT_ID_SET = frozenset(
    effect_id
    for effect_id, definition in FBP_EFFECT_REGISTRY.items()
    if definition.get("kind") == "GEOMETRY"
)
FBP_SHADER_EFFECT_ID_SET = frozenset(
    effect_id
    for effect_id, definition in FBP_EFFECT_REGISTRY.items()
    if definition.get("kind") == "SHADER"
)
FBP_FRAME_SYNC_GEOMETRY_EFFECT_ID_SET = frozenset(FBP_FRAME_SYNC_GEOMETRY_EFFECT_IDS)
FBP_PROCEDURAL_FRAME_SYNC_EFFECT_ID_SET = frozenset(FBP_PROCEDURAL_FRAME_SYNC_EFFECT_IDS)
FBP_FRAME_SYNC_SHADER_EFFECT_ID_SET = frozenset(FBP_FRAME_SYNC_SHADER_EFFECT_IDS)


def _fbp_effect_animatable_properties(definition):
    """Return RNA properties whose keyframes must be pushed into effect sockets."""
    properties = list((definition.get("property_map", {}) or {}).keys())
    properties.extend(definition.get("extra_properties", ()))
    return tuple(dict.fromkeys(str(name) for name in properties if name))


FBP_ANIMATED_PROPERTY_EFFECTS = {}
for _effect_id, _definition in FBP_EFFECT_REGISTRY.items():
    for _prop_name in _fbp_effect_animatable_properties(_definition):
        FBP_ANIMATED_PROPERTY_EFFECTS.setdefault(_prop_name, []).append(_effect_id)
# Mesh Wiggle exposes seed outside its socket map but still needs real keyframe playback.
for _prop_name in ("fbp_mesh_wiggle_seed", "fbp_mesh_wiggle_unique_seed"):
    FBP_ANIMATED_PROPERTY_EFFECTS.setdefault(_prop_name, []).append(FBP_EFFECT_MESH_WIGGLE)
FBP_ANIMATED_PROPERTY_EFFECTS = {
    key: tuple(dict.fromkeys(value)) for key, value in FBP_ANIMATED_PROPERTY_EFFECTS.items()
}


def _fbp_scene_camera_binding_is_animated(scene, active_effect_ids):
    """Return whether camera-aware sockets can change between rendered frames.

    Object transforms are evaluated natively by Geometry Nodes. Python work is
    needed only for camera switches or numeric projection sockets driven by an
    animated Camera datablock.
    """
    camera_effects = [
        fbp_effect_definition(effect_id)
        for effect_id in active_effect_ids
        if fbp_effect_definition(effect_id).get("camera_aware")
    ]
    if not camera_effects:
        return False

    try:
        if any(getattr(marker, "camera", None) is not None for marker in scene.timeline_markers):
            return True
    except FBP_DATA_ERRORS:
        pass

    projection_sockets = any(
        any(
            str((definition.get("camera_contract", {}) or {}).get(key, "") or "")
            for key in (
                "lens_socket", "sensor_width_socket", "ortho_scale_socket",
                "perspective_socket", "shift_x_socket", "shift_y_socket",
            )
        )
        for definition in camera_effects
    )
    if not projection_sockets:
        return False

    camera = _fbp_scene_camera(scene)
    camera_data = getattr(camera, "data", None) if camera else None
    if camera_data is None:
        return False
    animated_paths = {"type", "lens", "sensor_width", "ortho_scale", "shift_x", "shift_y"}
    try:
        curves = fbp_action_fcurves(camera_data)
        if any(
            not bool(getattr(curve, "mute", False))
            and str(getattr(curve, "data_path", "") or "") in animated_paths
            for curve in curves or ()
        ):
            return True
    except FBP_DATA_ERRORS:
        pass
    try:
        animation_data = getattr(camera_data, "animation_data", None)
        for curve in getattr(animation_data, "drivers", ()) or ():
            if str(getattr(curve, "data_path", "") or "") in animated_paths:
                return True
    except FBP_DATA_ERRORS:
        pass
    return False


def _fbp_effect_evolution_is_visible(rig, effect_id):
    """Return False when Evolution cannot change the visible result.

    Heavy geometry effects such as Cutout Outline previously rebuilt every held
    frame even with a zero wiggle amount. Definitions may declare one numeric
    property that must be non-zero before their procedural Evolution needs any
    socket synchronization. Shader warps also short-circuit when their mix or
    temporal speed makes frame-to-frame writes visually inert.
    """
    definition = fbp_effect_definition(effect_id)
    try:
        speed_property = _fbp_effect_evolution_speed_property(effect_id, definition)
        if abs(float(getattr(rig, speed_property, 1.0) or 0.0)) <= 1.0e-8:
            return False
        if effect_id == FBP_EFFECT_WAVE_WARP:
            return (
                abs(float(getattr(rig, "fbp_wave_warp_amplitude", 0.0) or 0.0)) > 1.0e-8
                and abs(float(getattr(rig, "fbp_wave_warp_factor", 0.0) or 0.0)) > 1.0e-8
            )
        if effect_id == FBP_EFFECT_RIPPLE_DISTORTION:
            return (
                abs(float(getattr(rig, "fbp_ripple_distortion_amplitude", 0.0) or 0.0)) > 1.0e-8
                and abs(float(getattr(rig, "fbp_ripple_distortion_factor", 0.0) or 0.0)) > 1.0e-8
            )
    except FBP_DATA_ERRORS:
        return True
    property_name = str((definition or {}).get("evolve_active_property", "") or "")
    if not property_name:
        return True
    try:
        return abs(float(getattr(rig, property_name, 0.0) or 0.0)) > 1.0e-8
    except FBP_DATA_ERRORS:
        return True


def _fbp_effect_instance_evolution_is_visible(rig, effect_id, instance_id, item=None):
    """Return whether one concrete MULTI instance can visibly evolve."""
    effect_id = fbp_normalize_effect_id(effect_id)
    instance_id = str(instance_id or "")
    definition = fbp_effect_definition(effect_id)
    state = fbp_read_effect_instance_animation_state(rig, effect_id, instance_id)
    if item is not None:
        try:
            state = {
                name: getattr(item, name)
                for name in ("evolve", "speed", "step", "seed", "unique", "layer_seed", "amount")
            }
        except FBP_DATA_ERRORS:
            pass
    try:
        if not bool(state.get("evolve", False)):
            return False
        if abs(float(state.get("speed", 1.0) or 0.0)) <= 1.0e-8:
            return False
        if effect_id == FBP_EFFECT_WAVE_WARP:
            amplitude = fbp_effect_instance_channel(
                rig, effect_id, instance_id, "fbp_wave_warp_amplitude", ensure=False
            )
            factor = fbp_effect_instance_channel(
                rig, effect_id, instance_id, "fbp_wave_warp_factor", ensure=False
            )
            return (
                abs(float(fbp_effect_instance_channel_value(amplitude) or 0.0)) > 1.0e-8
                and abs(float(fbp_effect_instance_channel_value(factor) or 0.0)) > 1.0e-8
            )
    except FBP_DATA_ERRORS:
        return True
    property_name = str((definition or {}).get("evolve_active_property", "") or "")
    if not property_name:
        return True
    channel = fbp_effect_instance_channel(
        rig, effect_id, instance_id, property_name, ensure=False
    )
    try:
        return abs(float(fbp_effect_instance_channel_value(channel) or 0.0)) > 1.0e-8
    except FBP_DATA_ERRORS:
        return True


def _fbp_image_user_has_animation(image_node):
    """Return whether ImageUser timing is evaluated by F-Curves or drivers.

    A copied Image Texture node follows ordinary sequence playback natively when
    its ImageUser settings are constant. Python synchronization is required only
    when the source ImageUser itself is animated, because private effect nodes do
    not share the source node's F-Curves or drivers.
    """
    if image_node is None:
        return False
    try:
        image_user = getattr(image_node, "image_user", None)
        id_data = getattr(image_node, "id_data", None)
        if image_user is None or id_data is None:
            return False
        paths = {
            image_user.path_from_id(name)
            for name in (
                "frame_offset", "frame_start", "frame_duration",
                "use_cyclic", "use_auto_refresh",
            )
        }
        animation_data = getattr(id_data, "animation_data", None)
        for curve in getattr(animation_data, "drivers", ()) or ():
            if str(getattr(curve, "data_path", "") or "") in paths:
                return True
        return any(
            not bool(getattr(curve, "mute", False))
            and str(getattr(curve, "data_path", "") or "") in paths
            for curve in (fbp_action_fcurves(id_data) or ())
        )
    except FBP_DATA_ERRORS:
        return True


def _fbp_geometry_source_requires_frame_sync(rig):
    """Return whether Geometry Nodes needs an explicit source Frame update."""
    _material, source_node = _fbp_material_image_node(rig)
    try:
        source_image = getattr(source_node, "image", None) if source_node else None
        return str(getattr(source_image, "source", "") or "").upper() in {"SEQUENCE", "MOVIE"}
    except FBP_DATA_ERRORS:
        return True


def _fbp_shader_source_requires_frame_sync(rig, active_effect_ids):
    """Return whether private shader samplers need evaluated timing/runtime data."""
    active_effect_ids = set(active_effect_ids or ())
    if FBP_EFFECT_DEPTH_BLUR in active_effect_ids:
        try:
            if str(getattr(rig, "fbp_depth_blur_mode", "MANUAL") or "MANUAL").upper() == "DEPTH":
                return True
        except FBP_DATA_ERRORS:
            return True

    _material, source_node = _fbp_material_image_node(rig)
    try:
        source_image = getattr(source_node, "image", None) if source_node else None
        source_kind = str(getattr(source_image, "source", "") or "").upper()
    except FBP_DATA_ERRORS:
        source_kind = ""
    if source_kind in {"SEQUENCE", "MOVIE"} and _fbp_image_user_has_animation(source_node):
        return True

    for effect_id in active_effect_ids:
        definition = fbp_effect_definition(effect_id)
        if not bool(definition.get("mask_source_aware", False)):
            continue
        source_property = str(definition.get("mask_source_property", "") or "")
        if not source_property:
            continue
        try:
            source_rig = getattr(rig, source_property, None)
        except FBP_DATA_ERRORS:
            return True
        if source_rig is None:
            continue
        _source_material, mask_node = _fbp_material_image_node(source_rig)
        try:
            mask_image = getattr(mask_node, "image", None) if mask_node else None
            mask_kind = str(getattr(mask_image, "source", "") or "").upper()
        except FBP_DATA_ERRORS:
            mask_kind = ""
        if mask_kind in {"SEQUENCE", "MOVIE"} and _fbp_image_user_has_animation(mask_node):
            return True
        animated_bounds = {
            "fbp_crop_left", "fbp_crop_right", "fbp_crop_top", "fbp_crop_bottom",
            "fbp_extend_left", "fbp_extend_right", "fbp_extend_top", "fbp_extend_bottom",
            "fbp_opacity",
        }
        try:
            animation_data = getattr(source_rig, "animation_data", None)
            action_curves = tuple(fbp_action_fcurves(source_rig) or ())
            driver_curves = tuple(getattr(animation_data, "drivers", ()) or ()) if animation_data else ()
            if any(
                not bool(getattr(curve, "mute", False))
                and str(getattr(curve, "data_path", "") or "") in animated_bounds
                for curve in action_curves + tuple(
                    curve for curve in driver_curves if curve not in action_curves
                )
            ):
                return True
        except FBP_DATA_ERRORS:
            return True
    return False


def _fbp_effect_evolve_step_signature(rig, active_evolve_pairs, scene):
    """Return the held state for prefiltered, visible Evolution effects."""
    try:
        frame = int(getattr(scene, "frame_current", 1))
        start = int(getattr(scene, "frame_start", 1))
    except FBP_DATA_ERRORS:
        return None
    result = []
    for effect_id, _property_key in active_evolve_pairs or ():
        try:
            state = fbp_read_effect_animation_state(rig, effect_id)
            step = max(1, int(state.get("step", 4) or 4))
            step_index = max(0, math.floor((frame - start) / step))
            definition = fbp_effect_definition(effect_id)
            speed_property = _fbp_effect_evolution_speed_property(effect_id, definition)
            speed = float(getattr(rig, speed_property, 1.0) or 0.0)
            result.append((
                effect_id,
                step_index,
                int(state.get("seed", 0) or 0),
                bool(state.get("unique", False)),
                int(state.get("layer_seed", 0) or 0),
                round(float(state.get("amount", definition.get("evolve_amount", 1.0)) or 0.0), 9),
                round(speed, 9),
            ))
        except FBP_DATA_ERRORS:
            return None
    return tuple(result)


def _fbp_effect_instance_evolve_step_signature(active_pairs, scene):
    """Return held-frame state for concrete MULTI animation records."""
    try:
        frame = int(getattr(scene, "frame_current", 1))
        start = int(getattr(scene, "frame_start", 1))
    except FBP_DATA_ERRORS:
        return None
    result = []
    for effect_id, instance_id, item in active_pairs or ():
        try:
            step = max(1, int(getattr(item, "step", 4) or 4))
            step_index = max(0, math.floor((frame - start) / step))
            result.append((
                effect_id,
                instance_id,
                step_index,
                int(getattr(item, "seed", 0) or 0),
                bool(getattr(item, "unique", False)),
                int(getattr(item, "layer_seed", 0) or 0),
                round(float(getattr(item, "amount", 1.0) or 0.0), 9),
                round(float(getattr(item, "speed", 1.0) or 0.0), 9),
            ))
        except FBP_DATA_ERRORS:
            return None
    return tuple(result)


def _fbp_effect_procedural_frame_signature(rig, effect_ids, scene):
    """Return held-frame state for procedural effects that animate without Evolution."""
    try:
        frame = int(getattr(scene, "frame_current", 1) or 1)
        start = int(getattr(scene, "frame_start", 1) or 1)
    except FBP_DATA_ERRORS:
        return None
    result = []
    for effect_id in effect_ids or ():
        effect_id = fbp_normalize_effect_id(effect_id)
        try:
            if effect_id == FBP_EFFECT_MESH_WIGGLE:
                hold = max(1, int(getattr(rig, "fbp_mesh_wiggle_hold", 1) or 1))
                step_index = math.floor((frame - start) / hold)
                result.append((
                    effect_id,
                    step_index,
                    round(float(getattr(rig, "fbp_mesh_wiggle_speed", 0.0) or 0.0), 9),
                    round(float(getattr(rig, "fbp_mesh_wiggle_w", 0.0) or 0.0), 9),
                    int(getattr(rig, "fbp_mesh_wiggle_seed", 0) or 0),
                    bool(getattr(rig, "fbp_mesh_wiggle_unique_seed", False)),
                    int(getattr(rig, "fbp_mesh_wiggle_layer_seed", 0) or 0),
                ))
            else:
                result.append((effect_id, frame))
        except FBP_DATA_ERRORS:
            return None
    return tuple(result)

def fbp_scene_requires_effect_frame_sync(scene, rigs=None):
    """Return whether active effects require Python writes for rendered frames.

    Camera transforms and ordinary native ImageUser playback remain fully native.
    The render session only keeps this handler active for image-aware effects,
    animated effect properties, procedural Evolve controls, or camera projection
    values that are passed through modifier sockets.
    """
    if scene is None:
        return False
    try:
        from .motion_runtime import scene_has_runtime_motion
        if scene_has_runtime_motion(scene):
            return True
    except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
        # Motion writes delta transforms from a frame handler. If preflight is
        # uncertain, keep the managed/interface-locked render path.
        return True
    if rigs is None:
        try:
            from .layers import iter_scene_fbp_rigs
            rigs = iter_scene_fbp_rigs(scene)
        except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
            # Unknown effect state must never opt a render into native pass-through.
            return True

    geometry_sync_ids = FBP_FRAME_SYNC_GEOMETRY_EFFECT_ID_SET
    shader_sync_ids = FBP_FRAME_SYNC_SHADER_EFFECT_ID_SET
    procedural_sync_ids = FBP_PROCEDURAL_FRAME_SYNC_EFFECT_ID_SET
    evolve_pairs = FBP_EVOLVE_EFFECT_PROPERTIES
    for rig in rigs:
        try:
            active_effect_ids = set(_fbp_runtime_effect_ids(rig))
            if not active_effect_ids:
                continue
            if FBP_EFFECT_LATTICE in active_effect_ids and _fbp_lattice_live_enabled(rig):
                return True
            if (
                active_effect_ids.intersection(geometry_sync_ids)
                and _fbp_geometry_source_requires_frame_sync(rig)
            ):
                return True
            if (
                active_effect_ids.intersection(shader_sync_ids)
                and _fbp_shader_source_requires_frame_sync(rig, active_effect_ids)
            ):
                return True
            if _fbp_scene_camera_binding_is_animated(scene, active_effect_ids):
                return True
            if active_effect_ids.intersection(procedural_sync_ids):
                return True
            if any(
                effect_id in active_effect_ids
                and bool(getattr(rig, property_key, False))
                and _fbp_effect_evolution_is_visible(rig, effect_id)
                for effect_id, property_key in evolve_pairs
            ):
                return True
            instance_animation_items = tuple(
                item for item in getattr(rig, "fbp_effect_instance_animations", ())
                if bool(getattr(item, "active", True))
            )
            if any(
                fbp_normalize_effect_id(getattr(item, "effect_id", "")) in active_effect_ids
                and _fbp_effect_instance_evolution_is_visible(
                    rig,
                    getattr(item, "effect_id", ""),
                    getattr(item, "instance_id", ""),
                    item,
                )
                for item in instance_animation_items
            ):
                return True

            animation_data = getattr(rig, "animation_data", None)
            action_curves = tuple(fbp_action_fcurves(rig) or ())
            driver_curves = tuple(getattr(animation_data, "drivers", ()) or ()) if animation_data else ()
            curves = action_curves + tuple(
                curve for curve in driver_curves if curve not in action_curves
            )
            for curve in curves:
                if bool(getattr(curve, "mute", False)):
                    continue
                data_path = str(getattr(curve, "data_path", "") or "")
                if any(
                    effect_id in active_effect_ids
                    for effect_id in FBP_ANIMATED_PROPERTY_EFFECTS.get(data_path, ())
                ):
                    return True
                for channel in getattr(rig, "fbp_effect_instance_channels", ()):
                    if not bool(getattr(channel, "active", True)):
                        continue
                    effect_id, instance_id, _prop_name = _fbp_effect_instance_channel_identity(channel)
                    if effect_id not in active_effect_ids or not instance_id:
                        continue
                    if data_path == str(
                        channel.path_from_id(_fbp_instance_channel_value_attr(channel)) or ""
                    ):
                        return True
                for item in instance_animation_items:
                    effect_id = fbp_normalize_effect_id(getattr(item, "effect_id", ""))
                    if effect_id not in active_effect_ids:
                        continue
                    if data_path in {
                        str(item.path_from_id(name) or "")
                        for name in ("evolve", "speed", "step", "seed", "unique", "amount")
                    }:
                        return True
        except FBP_DATA_ERRORS:
            # A preflight read failure is not evidence that frame sync is
            # unnecessary. Keep the conservative managed render path enabled.
            return True
    return False


def _fbp_set_custom_property_ui(rig, key, *, default, minimum=None, maximum=None, description=""):
    try:
        if key not in rig:
            rig[key] = default
        ui = rig.id_properties_ui(key)
        kwargs = {"default": default}
        if minimum is not None:
            kwargs["min"] = minimum
        if maximum is not None:
            kwargs["max"] = maximum
        if description:
            kwargs["description"] = description
        ui.update(**kwargs)
    except FBP_DATA_ERRORS:
        try:
            if key not in rig:
                rig[key] = default
        except FBP_DATA_ERRORS:
            pass


def fbp_assign_effect_layer_seed(rig, effect_id, *, force=False):
    """Return a persistent per-layer seed for a specific effect."""
    if not rig:
        return 0
    key = _fbp_animation_key(effect_id, "layer_seed")
    try:
        current = int(getattr(rig, key, 0) or 0) if hasattr(rig, key) else int(rig.get(key, 0) or 0)
    except FBP_DATA_ERRORS:
        current = 0
    if force or current <= 0:
        current = int(uuid.uuid4().int % 2147483646) + 1
        try:
            if hasattr(rig, key):
                fbp_set_rna_property_silent(rig, key, current)
            else:
                rig[key] = current
        except FBP_DATA_ERRORS:
            pass
    return current


def _fbp_effect_animation_defaults(definition):
    return {
        "evolve": (
            False, None, None,
            "Animate the effect over time."
        ),
        "speed": (
            1.0, -20.0, 20.0,
            "Animation speed. 0 freezes it, negative values reverse it."
        ),
        "step": (
            4, 1, 240,
            "Frames to hold each step. 1 = smooth, 4 = stepped, 12 = stop-motion."
        ),
        "seed": (
            0, 0, 999999,
            "Change the random pattern without changing intensity."
        ),
        "unique": (
            False, None, None,
            "Give each layer its own offset so copies do not move in sync."
        ),
        "layer_seed": (
            0, 0, 2147483647,
            "Internal per-layer seed used by Per Layer."
        ),
        # Hidden increment shared by the current progressive effect stack.
        "amount": (
            float(definition.get("evolve_amount", 1.0)), -100000.0, 100000.0,
            "Internal amount added at each Evolution step. Advanced diagnostic value; normal users should edit Evolution, Stepped and Seed instead."
        ),
    }


def _fbp_effect_animation_contract(effect_id, definition=None):
    """Return precompiled keys/defaults used by frame and UI hot paths."""
    effect_id = fbp_normalize_effect_id(effect_id)
    cached = _FBP_EFFECT_ANIMATION_CONTRACT_CACHE.get(effect_id)
    if cached is not None:
        return cached
    definition = definition or fbp_effect_definition(effect_id)
    if not definition:
        return ()
    entries = []
    for suffix, values in _fbp_effect_animation_defaults(definition).items():
        key = (
            _fbp_effect_evolution_speed_property(effect_id, definition)
            if suffix == "speed"
            else _fbp_animation_key(effect_id, suffix)
        )
        entries.append((suffix, key, *values))
    cached = tuple(entries)
    _FBP_EFFECT_ANIMATION_CONTRACT_CACHE[effect_id] = cached
    return cached


def fbp_read_effect_animation_state(rig, effect_id):
    """Read procedural animation state without mutating Blender datablocks.

    This variant is safe inside frame handlers and UI drawing. Registered RNA
    properties already expose their defaults; only the hidden ``amount`` may be
    absent. A deterministic fallback seed avoids assigning ID properties from a
    frame callback when an older/current file has Unique enabled but no seed.
    """
    definition = fbp_effect_definition(effect_id)
    if rig is None or not definition:
        return {}
    result = {}
    for suffix, key, default, _minimum, _maximum, _description in (
        _fbp_effect_animation_contract(effect_id, definition)
    ):
        try:
            if hasattr(rig, key):
                result[suffix] = getattr(rig, key)
            else:
                result[suffix] = rig.get(key, default)
        except FBP_DATA_ERRORS:
            result[suffix] = default
    if bool(result.get("unique", False)) and int(result.get("layer_seed", 0) or 0) <= 0:
        try:
            stable_name = str(getattr(rig, "name_full", getattr(rig, "name", "")) or "")
        except FBP_DATA_ERRORS:
            stable_name = ""
        result["layer_seed"] = int(
            _fbp_stable_string_seed(f"{stable_name}:{fbp_normalize_effect_id(effect_id)}")
            % 2147483646
        ) + 1
    return result


def fbp_ensure_effect_animation_state(rig, effect_id):
    """Initialize missing persistent animation state from a mutation-safe path."""
    definition = fbp_effect_definition(effect_id)
    if rig is None or not definition:
        return {}
    for _suffix, key, default, minimum, maximum, description in (
        _fbp_effect_animation_contract(effect_id, definition)
    ):
        if hasattr(rig, key):
            continue
        _fbp_set_custom_property_ui(
            rig,
            key,
            default=default,
            minimum=minimum,
            maximum=maximum,
            description=description,
        )
    state = fbp_read_effect_animation_state(rig, effect_id)
    if bool(state.get("unique", False)):
        try:
            current_seed = int(getattr(rig, _fbp_animation_key(effect_id, "layer_seed"), 0) or 0)
        except FBP_DATA_ERRORS:
            current_seed = 0
        if current_seed <= 0:
            state["layer_seed"] = fbp_assign_effect_layer_seed(rig, effect_id)
    return state


def fbp_reset_effect_animation_state(rig, effect_id):
    """Restore registered animation controls and remove hidden ID properties."""
    definition = fbp_effect_definition(effect_id)
    if rig is None or not definition:
        return False
    changed = False
    for _suffix, key, default, _minimum, _maximum, _description in (
        _fbp_effect_animation_contract(effect_id, definition)
    ):
        try:
            if hasattr(rig, key):
                current = getattr(rig, key)
                if current != default:
                    changed = fbp_set_rna_property_silent(rig, key, default) or changed
                continue
            if key in rig:
                del rig[key]
                changed = True
        except (AttributeError, ReferenceError, RuntimeError, TypeError, ValueError, KeyError):
            continue
    return changed

def _fbp_quality_contracts(definition):
    """Return normalized quality contracts declared by an effect definition."""
    if not definition:
        return ()
    try:
        cache_key = (
            id(definition),
            str(definition.get("asset_id", "") or definition.get("canonical_name", "") or ""),
            len(definition.get("quality_contracts", ()) or ()),
        )
    except (AttributeError, TypeError, ValueError):
        cache_key = None
    cached = _FBP_QUALITY_CONTRACTS_CACHE.get(cache_key) if cache_key is not None else None
    if cached is not None:
        return cached
    contracts = tuple(
        contract for contract in definition.get("quality_contracts", ()) or ()
        if isinstance(contract, dict)
    )
    if cache_key is not None:
        if len(_FBP_QUALITY_CONTRACTS_CACHE) >= 512 and cache_key not in _FBP_QUALITY_CONTRACTS_CACHE:
            _FBP_QUALITY_CONTRACTS_CACHE.clear()
        _FBP_QUALITY_CONTRACTS_CACHE[cache_key] = contracts
    return contracts


def _fbp_quality_value(value, contract):
    """Clamp one quality value while preserving documented Auto sentinels."""
    try:
        raw = int(value)
        if bool(contract.get("zero_is_auto", False)) and raw <= 0:
            return 0
        return max(int(contract.get("minimum", 0)), raw)
    except (TypeError, ValueError, AttributeError):
        return value


def _fbp_geometry_effect_has_visible_work(rig, effect_id):
    """Return whether a heavy Geometry Nodes effect needs evaluation.

    This is a performance gate only: the user-facing effect remains enabled and
    its stored viewport/render visibility is preserved. When the driving
    strength becomes non-zero again, the modifier is re-enabled automatically by
    the next property update.
    """
    try:
        if effect_id == FBP_EFFECT_STOP_MOTION_CRUMPLE:
            return abs(float(getattr(rig, "fbp_stop_motion_strength", 0.0) or 0.0)) > 1.0e-8
        if effect_id == FBP_EFFECT_WIND_BENDER:
            mode = str(getattr(rig, "fbp_wind_motion_mode", "SWAY") or "SWAY").upper()
            if mode == "SWAY":
                return abs(float(getattr(rig, "fbp_wind_bend_amount", 0.0) or 0.0)) > 1.0e-8
            return abs(float(getattr(rig, "fbp_wind_wave_amplitude", 0.0) or 0.0)) > 1.0e-8
        if effect_id == FBP_EFFECT_IMAGE_RELIEF:
            base_depth = float(getattr(rig, "fbp_image_relief_depth", 0.0) or 0.0)
            depth = _fbp_effect_runtime_value(
                rig,
                effect_id,
                "fbp_image_relief_depth",
                base_depth,
                scene=getattr(bpy.context, "scene", None),
            )
            return abs(float(depth or 0.0)) > 1.0e-8
        if effect_id == FBP_EFFECT_SURFACE_CONFORM:
            return bool(
                getattr(rig, "fbp_surface_conform_target", None) is not None
                and abs(float(getattr(rig, "fbp_surface_conform_factor", 0.0) or 0.0)) > 1.0e-8
            )
        if effect_id == FBP_EFFECT_ACCORDION_FOLD:
            return abs(float(getattr(rig, "fbp_accordion_depth", 0.0) or 0.0)) > 1.0e-8
        if effect_id == FBP_EFFECT_SCULPT_WAVES:
            return abs(float(getattr(rig, "fbp_sculpt_waves_amplitude", 0.0) or 0.0)) > 1.0e-8
        if effect_id == FBP_EFFECT_KINETIC_TILES:
            return any(
                abs(float(getattr(rig, prop_name, 0.0) or 0.0)) > 1.0e-8
                for prop_name in (
                    "fbp_kinetic_tiles_gap",
                    "fbp_kinetic_tiles_thickness",
                    "fbp_kinetic_tiles_motion",
                )
            )
    except FBP_DATA_ERRORS:
        return True
    return True


def _fbp_sync_geometry_effect_eval_visibility(rig, effect_id, modifier):
    """Mute heavy modifiers only when their current settings are visually inert."""
    if modifier is None:
        return False
    if effect_id not in {
        FBP_EFFECT_STOP_MOTION_CRUMPLE,
        FBP_EFFECT_WIND_BENDER,
        FBP_EFFECT_IMAGE_RELIEF,
        FBP_EFFECT_SURFACE_CONFORM,
        FBP_EFFECT_ACCORDION_FOLD,
        FBP_EFFECT_SCULPT_WAVES,
        FBP_EFFECT_KINETIC_TILES,
    }:
        return False
    try:
        has_work = _fbp_geometry_effect_has_visible_work(rig, effect_id)
        viewport_target = bool(_fbp_stored_effect_visibility(rig, effect_id, True)) and has_work
        render_target = bool(_fbp_stored_effect_render_visibility(rig, effect_id, True)) and has_work
        changed = False
        if bool(getattr(modifier, "show_viewport", True)) != viewport_target:
            modifier.show_viewport = viewport_target
            changed = True
        if bool(getattr(modifier, "show_render", True)) != render_target:
            modifier.show_render = render_target
            changed = True
        return changed
    except FBP_DATA_ERRORS:
        return False


def _fbp_effective_quality_value(rig, effect_id, prop_name, value):
    """Resolve viewport quality, including temporary playback overrides."""
    definition = fbp_effect_definition(effect_id)
    for contract in _fbp_quality_contracts(definition):
        if prop_name != str(contract.get("viewport_property", "")):
            continue
        viewport_value = _fbp_quality_value(value, contract)
        if not _FBP_EFFECT_PLAYBACK_ACTIVE:
            return viewport_value
        if effect_id == FBP_EFFECT_TEXT_MATRIX and not bool(
            getattr(rig, "fbp_text_matrix_auto_playback_limit", True)
        ):
            return viewport_value
        playback_property = str(contract.get("playback_property", ""))
        if not playback_property:
            return viewport_value
        try:
            playback_value = _fbp_quality_value(getattr(rig, playback_property), contract)
        except FBP_DATA_ERRORS:
            return viewport_value
        if bool(contract.get("zero_is_auto", False)) and playback_value == 0:
            return viewport_value
        if str(contract.get("playback_mode", "REPLACE")).upper() == "LIMIT":
            if bool(contract.get("zero_is_auto", False)) and viewport_value == 0:
                return 0
            try:
                return min(int(viewport_value), int(playback_value))
            except (TypeError, ValueError):
                return viewport_value
        return playback_value
    return value


def _fbp_refresh_effect_quality(scene=None):
    """Refresh only the sockets participating in playback quality contracts."""
    try:
        from .layers import iter_scene_fbp_rigs
        rigs = iter_scene_fbp_rigs(scene or getattr(bpy.context, "scene", None))
    except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
        return
    for rig in rigs:
        for effect_id in _fbp_runtime_effect_ids(rig):
            definition = fbp_effect_definition(effect_id)
            contracts = _fbp_quality_contracts(definition)
            if not contracts:
                continue
            properties = {
                str(contract.get("viewport_property", ""))
                for contract in contracts
                if str(contract.get("viewport_property", ""))
            }
            if not properties:
                continue
            try:
                fbp_update_geometry_effect(
                    rig, effect_id, scene=scene, sync_alpha=False,
                    property_names=properties,
                )
            except FBP_DATA_ERRORS:
                continue


def _fbp_schedule_effect_quality_refresh(scene=None):
    """Publish playback-quality socket changes outside animation handlers."""
    target_scene = scene or getattr(bpy.context, "scene", None)
    scene_key = fbp_obj_runtime_key(target_scene)
    if scene_key is None:
        return False
    try:
        scene_name = str(
            getattr(target_scene, "name_full", getattr(target_scene, "name", "")) or ""
        )
    except FBP_DATA_ERRORS:
        scene_name = ""

    def _publish():
        if fbp_undo_guard_active() or fbp_render_mutation_blocked():
            return 0.20
        if not fbp_depsgraph_quiet_for(0.15):
            return 0.08
        current_scene = fbp_find_id_by_runtime_key(
            getattr(bpy.data, "scenes", ()), scene_key, scene_name
        )
        if current_scene is not None:
            _fbp_refresh_effect_quality(current_scene)
        return None

    try:
        from .safe_tasks import schedule_once
        return bool(schedule_once(
            f"effects.playback_quality:{scene_key}",
            _publish,
            first_interval=0.04,
        ))
    except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
        return False


@persistent
def fbp_effect_playback_pre(scene, depsgraph=None):
    """Apply playback-specific quality contracts for all active effects."""
    playback_depsgraph = depsgraph
    global _FBP_EFFECT_PLAYBACK_ACTIVE
    _FBP_EFFECT_PLAYBACK_ACTIVE = True
    # Keyframes may have been added since the previous playback session. Build
    # one fresh property map now, then reuse it throughout playback.
    _FBP_EFFECT_RUNTIME_PROFILE_CACHE.clear()
    try:
        fbp_suspend_heavy_effects_for_playback(scene, playback_depsgraph)
    except FBP_DATA_ERRORS as exc:
        fbp_warn("Could not pause heavy effects for playback", exc)
    _fbp_schedule_effect_quality_refresh(scene)


@persistent
def fbp_effect_playback_post(scene, depsgraph=None):
    """Restore viewport quality contracts after animation playback."""
    del depsgraph
    global _FBP_EFFECT_PLAYBACK_ACTIVE
    _FBP_EFFECT_PLAYBACK_ACTIVE = False
    try:
        fbp_restore_playback_suspended_effects()
    except FBP_DATA_ERRORS as exc:
        fbp_warn("Could not restore effects paused for playback", exc)
    _fbp_schedule_effect_quality_refresh(scene)


# Light Playback: Mesh effects whose last viewport evaluation took longer than
# this are switched off in the viewport while the timeline plays. Render
# visibility, stored effect visibility and the effect settings never change.
FBP_PLAYBACK_LIGHT_THRESHOLD_MS = 4.0
FBP_PLAYBACK_SUSPENDED_KEY = "fbp_playback_suspended_modifiers"


def fbp_playback_light_mode(scene):
    try:
        mode = str(getattr(scene, "fbp_playback_light_mode", "HEAVY") or "HEAVY").upper()
    except FBP_DATA_ERRORS:
        mode = "HEAVY"
    return mode if mode in {"OFF", "HEAVY", "ALL"} else "HEAVY"


def _fbp_playback_suspend_candidates(plane, mode, depsgraph=None):
    """Viewport-visible Mesh effect modifiers worth pausing on ``plane``."""
    names = []
    evaluated_modifiers = None
    if mode == "HEAVY":
        # Blender records the evaluation time on the evaluated copy only.
        try:
            evaluated_modifiers = plane.evaluated_get(depsgraph).modifiers if depsgraph else None
        except FBP_DATA_ERRORS:
            evaluated_modifiers = None
    for modifier in tuple(getattr(plane, "modifiers", ()) or ()):
        try:
            if getattr(modifier, "type", "") != "NODES" or not bool(modifier.show_viewport):
                continue
            if not _fbp_geometry_effect_id_for_modifier(modifier):
                continue
            if mode == "HEAVY":
                timed = evaluated_modifiers.get(modifier.name) if evaluated_modifiers is not None else None
                cost_ms = float(getattr(timed or modifier, "execution_time", 0.0) or 0.0) * 1000.0
                if cost_ms < FBP_PLAYBACK_LIGHT_THRESHOLD_MS:
                    continue
            names.append(str(modifier.name))
        except FBP_DATA_ERRORS:
            continue
    return names


def fbp_suspend_heavy_effects_for_playback(scene, depsgraph=None):
    """Pause heavy Mesh effects in the viewport for the length of playback."""
    mode = fbp_playback_light_mode(scene)
    if mode == "OFF" or scene is None:
        return 0
    if depsgraph is None and mode == "HEAVY":
        try:
            depsgraph = bpy.context.evaluated_depsgraph_get()
        except FBP_DATA_ERRORS:
            depsgraph = None
    try:
        from .layers import iter_scene_fbp_rigs
        rigs = tuple(iter_scene_fbp_rigs(scene))
    except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
        return 0
    suspended = 0
    for rig in rigs:
        plane = _fbp_plane(rig, repair=False)
        if plane is None:
            continue
        names = _fbp_playback_suspend_candidates(plane, mode, depsgraph)
        if not names:
            continue
        try:
            previous = [str(name) for name in plane.get(FBP_PLAYBACK_SUSPENDED_KEY, ()) or ()]
            plane[FBP_PLAYBACK_SUSPENDED_KEY] = sorted(set(previous) | set(names))
            for name in names:
                modifier = plane.modifiers.get(name)
                if modifier is not None:
                    modifier.show_viewport = False
                    suspended += 1
        except FBP_DATA_ERRORS:
            continue
    return suspended


def fbp_playback_suspended_modifier(plane, modifier_name):
    try:
        return str(modifier_name) in {
            str(name) for name in plane.get(FBP_PLAYBACK_SUSPENDED_KEY, ()) or ()
        }
    except FBP_DATA_ERRORS:
        return False


def fbp_forget_playback_suspended_modifier(plane, modifier_name):
    """The user changed this effect's visibility: playback no longer owns it."""
    try:
        names = [str(name) for name in plane.get(FBP_PLAYBACK_SUSPENDED_KEY, ()) or ()]
        if str(modifier_name) not in names:
            return False
        names.remove(str(modifier_name))
        if names:
            plane[FBP_PLAYBACK_SUSPENDED_KEY] = names
        else:
            del plane[FBP_PLAYBACK_SUSPENDED_KEY]
        return True
    except FBP_DATA_ERRORS:
        return False


def fbp_draw_playback_light_settings(self, context):
    """Light Playback row in the Timeline's Playback popover."""
    scene = getattr(context, "scene", None)
    if scene is None or not hasattr(scene, "fbp_playback_light_mode"):
        return
    layout = self.layout
    layout.separator()
    layout.prop(scene, "fbp_playback_light_mode", text="Light Playback")
    try:
        from .playback_cache import fbp_draw_playback_cache
        fbp_draw_playback_cache(layout, context)
    except ImportError:
        pass


def _fbp_playback_popover():
    return getattr(bpy.types, "TIME_PT_playback", None)


def fbp_restore_playback_suspended_effects():
    """Show every effect paused by Light Playback again.

    The paused modifier names live on the plane, so a file saved while the
    timeline was playing is repaired on load as well.
    """
    restored = 0
    for obj in tuple(getattr(bpy.data, "objects", ()) or ()):
        try:
            if FBP_PLAYBACK_SUSPENDED_KEY not in obj:
                continue
            names = [str(name) for name in obj.get(FBP_PLAYBACK_SUSPENDED_KEY, ()) or ()]
            del obj[FBP_PLAYBACK_SUSPENDED_KEY]
        except FBP_DATA_ERRORS:
            continue
        for name in names:
            try:
                modifier = obj.modifiers.get(name)
                if modifier is not None and not bool(modifier.show_viewport):
                    modifier.show_viewport = True
                    restored += 1
            except FBP_DATA_ERRORS:
                continue
    return restored

def _fbp_effect_runtime_value(rig, effect_id, prop_name, value, scene=None, node=None):
    effect_id = fbp_normalize_effect_id(effect_id)
    definition = fbp_effect_definition(effect_id)
    if effect_id == FBP_EFFECT_MESH_WIGGLE and prop_name == "fbp_mesh_wiggle_w":
        value = fbp_mesh_wiggle_effective_w(rig, scene=scene)
    if not definition or prop_name != definition.get("evolve_property"):
        return value
    instance_id = ""
    if node is not None and _fbp_effect_uses_multi_instances(effect_id):
        instance_id = effect_instance_id(node)
    state = (
        fbp_read_effect_instance_animation_state(rig, effect_id, instance_id)
        if instance_id else {}
    ) or fbp_read_effect_animation_state(rig, effect_id)
    if not bool(state.get("evolve", False)):
        return value
    try:
        base = float(value)
        stepped_frames = max(1, int(state.get("step", 4)))
        stream_seed = int(state.get("seed", 0))
        if bool(state.get("unique", False)):
            stream_seed += int(state.get("layer_seed", 0) or 0)
        evolve_mode = str(definition.get("evolve_mode", "") or "").upper()
        amount_source = (
            definition.get("evolve_amount", 1.0)
            if evolve_mode in {"WRAP", "PING_PONG"}
            else state.get("amount", definition.get("evolve_amount", 1.0))
        )
        amount = float(amount_source)
        amount *= float(state.get("speed", 1.0) or 0.0)
        scene = scene or getattr(bpy.context, "scene", None)
        frame = int(getattr(scene, "frame_current", 1))
        start = int(getattr(scene, "frame_start", 1))
        step_index = max(0, math.floor((frame - start) / stepped_frames))

        # Evolution advances once per held step. Seed-like parameters remain
        # deterministic integers; bounded artistic controls can wrap or ping-pong
        # instead of clamping permanently at their RNA/socket limits.
        evolve_property = str(definition.get("evolve_property", "") or "").lower()
        seed_step = bool(
            str(definition.get("evolve_mode", "") or "").upper() == "SEED_STEP"
            or evolve_property.endswith("_seed")
            or evolve_property.endswith("seed")
        )
        if seed_step:
            unique_offset = stream_seed if (stream_seed or bool(state.get("unique", False))) else 0
            seed_value = int(round(base + unique_offset + (amount * step_index)))
            # Do not let long playback or a negative speed pin an integer Seed
            # against its RNA limits. Wrap only finite practical ranges; very
            # large/unbounded Float seeds remain unrestricted.
            try:
                prop = rig.bl_rna.properties.get(str(prop_name))
                minimum = int(math.ceil(float(getattr(prop, "hard_min", -1.0e30))))
                maximum = int(math.floor(float(getattr(prop, "hard_max", 1.0e30))))
                span = maximum - minimum + 1
                if 0 < span <= 2_147_483_648:
                    seed_value = minimum + ((seed_value - minimum) % span)
            except (AttributeError, ReferenceError, RuntimeError, TypeError, ValueError, OverflowError):
                pass
            return seed_value

        phase = 0.0
        if stream_seed or bool(state.get("unique", False)):
            phase = _fbp_effect_noise_u01(effect_id, stream_seed, 0)
        progressed = base + (amount * (step_index + phase))
        if evolve_mode in {"WRAP", "PING_PONG"}:
            minimum = float(definition.get("evolve_min", 0.0))
            maximum = float(definition.get("evolve_max", 1.0))
            span = maximum - minimum
            if span > 1.0e-9:
                offset = (progressed - minimum) % (span * (2.0 if evolve_mode == "PING_PONG" else 1.0))
                if evolve_mode == "PING_PONG" and offset > span:
                    offset = (span * 2.0) - offset
                progressed = minimum + offset
        return progressed
    except (AttributeError, ReferenceError, RuntimeError, TypeError, ValueError, ZeroDivisionError):
        return value


def _fbp_effect_profile_enabled():
    return bool(
        _FBP_PROFILE_ENV_ENABLED
        or fbp_runtime_get("fbp_profile_enabled", False)
    )


def _fbp_effect_stat_add(key, amount=1):
    try:
        _FBP_EFFECT_RUNTIME_STATS[key] = int(
            _FBP_EFFECT_RUNTIME_STATS.get(key, 0) or 0
        ) + int(amount)
    except (AttributeError, TypeError, ValueError, OverflowError):
        pass


def _fbp_effect_handler_record(milliseconds):
    try:
        value = max(0.0, float(milliseconds))
    except (TypeError, ValueError, OverflowError):
        return
    _FBP_EFFECT_HANDLER_SAMPLES_MS.append(value)


def fbp_effect_runtime_profile_metrics(*, reset=False):
    """Return local handler measurements without retaining Blender RNA."""
    samples = tuple(float(value) for value in _FBP_EFFECT_HANDLER_SAMPLES_MS)
    result = dict(_FBP_EFFECT_RUNTIME_STATS)
    result.update({
        "profile_enabled": bool(_fbp_effect_profile_enabled()),
        "timed_samples": len(samples),
        "avg_ms": (sum(samples) / len(samples)) if samples else 0.0,
        "p50_ms": _fbp_percentile(samples, 0.50),
        "p95_ms": _fbp_percentile(samples, 0.95),
        "max_ms": max(samples, default=0.0),
    })
    if reset:
        _FBP_EFFECT_RUNTIME_STATS.clear()
        _FBP_EFFECT_RUNTIME_STATS.update(_FBP_EFFECT_RUNTIME_STAT_DEFAULTS)
        _FBP_EFFECT_HANDLER_SAMPLES_MS.clear()
    return result


def _fbp_evolve_property_names(effect_id, *, with_speed=True):
    """The Evolve (and Speed) settings of one effect, as a set of names."""
    definition = fbp_effect_definition(effect_id)
    keys = ("evolve_property", "evolve_speed_property") if with_speed else ("evolve_property",)
    return {name for name in (str(definition.get(key, "") or "") for key in keys) if name}


class _FrameEffectPush:
    """Writes one layer's per-frame effect values during a frame change.

    Every write goes through here, so a deleted or rebuilt datablock retires
    the layer's runtime profile (the next frame resolves fresh targets)
    instead of stopping the updates of the other layers.
    """

    __slots__ = ("rig", "scene", "profile", "count")

    def __init__(self, rig, scene, profile, count):
        self.rig = rig
        self.scene = scene
        self.profile = profile
        self.count = count

    def _failed(self):
        _fbp_invalidate_effect_runtime_profile(self.rig)
        return False

    def effect(self, effect_id, property_names, *, refresh_composites=False, geometry_only=False):
        """Push an effect's values; Evolve and procedural inputs of Mesh
        effects never reach the materials, so their composites stay."""
        rig, profile = self.rig, self.profile
        try:
            if fbp_effect_definition(effect_id).get("kind") == "GEOMETRY" or geometry_only:
                fbp_update_geometry_effect(
                    rig,
                    effect_id,
                    modifier=profile.get("geometry_modifiers", {}).get(effect_id),
                    scene=self.scene,
                    sync_alpha=False,
                    property_names=property_names,
                    refresh_composites=refresh_composites,
                )
                if self.count:
                    _fbp_effect_stat_add("geometry_effect_updates")
                return True
            fbp_update_shader_effect(
                rig,
                effect_id,
                scene=self.scene,
                property_names=property_names,
                nodes=profile.get("shader_nodes", {}).get(effect_id),
            )
            if effect_id == FBP_EFFECT_PIXELATE:
                _fbp_refresh_extrude_pixel_dependency(
                    rig,
                    modifier=profile.get("geometry_modifiers", {}).get(FBP_EFFECT_THICKNESS),
                    scene=self.scene,
                )
            if self.count:
                _fbp_effect_stat_add("shader_effect_updates")
            return True
        except FBP_DATA_ERRORS:
            return self._failed()

    def instance(self, effect_id, instance_id):
        """Push the Evolve and Speed values of one concrete shader instance."""
        try:
            fbp_update_shader_effect(
                self.rig,
                effect_id,
                scene=self.scene,
                property_names=_fbp_evolve_property_names(effect_id) or None,
                instance_id=instance_id,
                nodes=self.profile.get("shader_nodes_by_instance", {}).get(
                    effect_instance_token(effect_id, instance_id)
                ),
            )
            if self.count:
                _fbp_effect_stat_add("shader_effect_updates")
            return True
        except FBP_DATA_ERRORS:
            return self._failed()


@persistent
def fbp_effect_evolve_frame_change(scene, depsgraph=None):
    """Refresh animated effect values after Blender commits the new frame."""
    del depsgraph
    global _FBP_EVOLVE_HANDLER_ACTIVE
    if _FBP_EVOLVE_HANDLER_ACTIVE or fbp_undo_guard_active():
        if _fbp_effect_profile_enabled():
            _fbp_effect_stat_add("handler_guard_skips")
        return
    render_guard_active = bool(fbp_runtime_get("fbp_render_guard_active", False))
    if (
        render_guard_active
        and not bool(fbp_runtime_get("fbp_render_needs_effect_frame_sync", False))
    ):
        if _fbp_effect_profile_enabled():
            _fbp_effect_stat_add("handler_guard_skips")
        return
    if not render_guard_active and fbp_render_mutation_blocked(include_guard=False):
        # Do not update node trees when an external render is active or Blender
        # cannot confirm its job state. Managed renders are handled above.
        if _fbp_effect_profile_enabled():
            _fbp_effect_stat_add("handler_guard_skips")
        return
    profile_enabled = _fbp_effect_profile_enabled()
    profile_started = time.perf_counter() if profile_enabled else 0.0
    _FBP_EVOLVE_HANDLER_ACTIVE = True
    try:
        try:
            _FBP_EFFECT_RUNTIME_STATS["handler_runs"] = int(
                _FBP_EFFECT_RUNTIME_STATS.get("handler_runs", 0) or 0
            ) + 1
        except (AttributeError, TypeError, ValueError):
            pass
        try:
            # Resolve only rigs with an active effect stack. The index is rebuilt
            # on structural changes and periodically self-heals external edits.
            rigs = _fbp_scene_effect_runtime_rigs(scene)
        except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
            return

        if not rigs:
            _FBP_EFFECT_RUNTIME_STATS["scene_idle_skips"] = int(
                _FBP_EFFECT_RUNTIME_STATS.get("scene_idle_skips", 0) or 0
            ) + 1
            return

        if profile_enabled:
            _fbp_effect_stat_add("rigs_scanned", len(rigs))
            _fbp_effect_stat_add("camera_binding_passes")
        _fbp_sync_scene_camera_bindings(scene, rigs)
        deferred_composite_rigs = []
        global _FBP_COMPOSITE_REFRESH_PENDING
        _FBP_COMPOSITE_REFRESH_PENDING = {}

        for rig in rigs:
            try:
                if not bool(getattr(rig, "is_fbp_control", False)):
                    continue

                # Discover the real effect stack once per rig. The previous
                # implementation rescanned modifiers/materials separately for
                # every alpha-aware and Evolve-capable effect on every frame.
                runtime_profile = _fbp_effect_runtime_profile(rig)
                active_effect_ids = runtime_profile.get("active_ids", frozenset())
                if not active_effect_ids or runtime_profile.get("frame_idle", False):
                    continue
                geometry_source_sync = bool(runtime_profile.get("geometry_source_sync", False))
                shader_source_sync = bool(
                    runtime_profile.get("shader_source_sync", False)
                )
                animated_effect_properties = runtime_profile.get(
                    "animated_effect_properties", {}
                ) or {}
                animated_instance_channels = runtime_profile.get(
                    "animated_instance_channels", ()
                ) or ()
                instance_animation_pairs = runtime_profile.get(
                    "instance_animation_pairs", ()
                ) or ()
                animated_instance_animation_pairs = runtime_profile.get(
                    "animated_instance_animation_pairs", ()
                ) or ()
                instance_speed_fcurve_pairs = runtime_profile.get(
                    "instance_speed_fcurve_pairs", ()
                ) or ()
                has_animated_effects = bool(
                    animated_effect_properties
                    or animated_instance_channels
                    or animated_instance_animation_pairs
                )
                lattice_live = bool(
                    FBP_EFFECT_LATTICE in active_effect_ids
                    and _fbp_lattice_live_enabled(rig)
                )
                if lattice_live:
                    if profile_enabled:
                        _fbp_effect_stat_add("lattice_updates")
                    _fbp_apply_lattice_live(rig, scene=scene, force=False)
                evolve_pairs = runtime_profile.get("evolve_pairs", ()) or ()
                active_evolve_pairs = tuple(
                    (effect_id, property_key)
                    for effect_id, property_key in evolve_pairs
                    if bool(getattr(rig, property_key, False))
                    and _fbp_effect_evolution_is_visible(rig, effect_id)
                )
                active_instance_evolve_pairs = tuple(
                    (effect_id, instance_id, item)
                    for effect_id, instance_id, item in instance_animation_pairs
                    if _fbp_effect_instance_evolution_is_visible(
                        rig, effect_id, instance_id, item
                    )
                )
                evolve_enabled = bool(active_evolve_pairs or active_instance_evolve_pairs)
                active_evolve_ids = frozenset(
                    effect_id for effect_id, _property_key in active_evolve_pairs
                )
                procedural_frame_effects = runtime_profile.get("procedural_frame_effects", ()) or ()
                procedural_frame_sync = bool(procedural_frame_effects)
                if not (geometry_source_sync or shader_source_sync or has_animated_effects or evolve_enabled or procedural_frame_sync or lattice_live):
                    continue

                profile_key = _fbp_effect_ids_cache_key(rig)
                if (
                    (evolve_enabled or procedural_frame_sync)
                    and not geometry_source_sync
                    and not shader_source_sync
                    and not has_animated_effects
                ):
                    shared_evolve_signature = (
                        _fbp_effect_evolve_step_signature(
                            rig, active_evolve_pairs, scene
                        )
                        if active_evolve_pairs else ()
                    )
                    instance_evolve_signature = (
                        _fbp_effect_instance_evolve_step_signature(
                            active_instance_evolve_pairs, scene
                        )
                        if active_instance_evolve_pairs else ()
                    )
                    evolve_signature = (
                        shared_evolve_signature, instance_evolve_signature
                    )
                    procedural_signature = (
                        _fbp_effect_procedural_frame_signature(rig, procedural_frame_effects, scene)
                        if procedural_frame_sync else ()
                    )
                    if evolve_signature is not None and procedural_signature is not None:
                        evolve_signature = (evolve_signature, procedural_signature)
                    else:
                        evolve_signature = None
                    if (
                        profile_key and profile_key[0]
                        and evolve_signature is not None
                        and _FBP_EFFECT_EVOLVE_STEP_CACHE.get(profile_key) == evolve_signature
                    ):
                        _FBP_EFFECT_RUNTIME_STATS["held_step_skips"] = int(
                            _FBP_EFFECT_RUNTIME_STATS.get("held_step_skips", 0) or 0
                        ) + 1
                        continue
                    if profile_key and profile_key[0] and evolve_signature is not None:
                        if (
                            len(_FBP_EFFECT_EVOLVE_STEP_CACHE) >= 512
                            and profile_key not in _FBP_EFFECT_EVOLVE_STEP_CACHE
                        ):
                            _FBP_EFFECT_EVOLVE_STEP_CACHE.clear()
                        _FBP_EFFECT_EVOLVE_STEP_CACHE[profile_key] = evolve_signature
                elif profile_key and profile_key[0]:
                    _FBP_EFFECT_EVOLVE_STEP_CACHE.pop(profile_key, None)

                _FBP_EFFECT_RUNTIME_STATS["rig_updates"] = int(
                    _FBP_EFFECT_RUNTIME_STATS.get("rig_updates", 0) or 0
                ) + 1

                # Matrix effects follow the evaluated source image/sequence
                # even when no procedural Evolve control is enabled.
                if geometry_source_sync:
                    if profile_enabled:
                        _fbp_effect_stat_add("geometry_source_updates")
                    _fbp_sync_geometry_alpha_frame_offset(
                        rig,
                        scene=scene,
                        effect_modifiers=runtime_profile.get("frame_geometry_modifiers", ()),
                    )
                if shader_source_sync:
                    if profile_enabled:
                        _fbp_effect_stat_add("shader_source_updates")
                    _fbp_sync_shader_image_sources(
                        rig,
                        active_effect_ids,
                        target_nodes=runtime_profile.get("frame_shader_targets", ()),
                        scene=scene,
                    )
                if geometry_source_sync or shader_source_sync:
                    # Composite materials mirror static socket values of the
                    # layer material; sequence timing inside them is native
                    # animation. A frame change only moves values that are
                    # keyed, driven or written from Python (effect settings,
                    # Evolve, procedural frames), so a plain stack skips the
                    # rescan (several ms per layer) while scrubbing or playing.
                    # Evolve and procedural frames of Mesh effects write
                    # modifier inputs, never the layer material, and shader
                    # writes below queue their own refresh, so only keyed or
                    # driven materials (and renders) refresh here. Queued
                    # refreshes run once per layer after every write of the
                    # frame, so the composites never lag one frame behind.
                    if (
                        render_guard_active
                        or has_animated_effects
                        or _fbp_layer_material_frame_dependent(rig)
                    ):
                        _fbp_refresh_geometry_source_materials(rig)
                    elif not _FBP_EFFECT_PLAYBACK_ACTIVE:
                        deferred_composite_rigs.append(rig)

            except FBP_DATA_ERRORS:
                _fbp_invalidate_effect_runtime_profile(rig)
                continue

            # Keyframes on registered Object properties are evaluated by Blender,
            # but socket values are not RNA-linked and update callbacks are not
            # called during animation evaluation. The profile caches only the
            # topology (effect -> property names); evaluated values remain live.
            for channel in animated_instance_channels:
                try:
                    effect_id, instance_id, _prop_name = _fbp_effect_instance_channel_identity(channel)
                    if effect_id not in active_effect_ids or not instance_id:
                        continue
                    if _fbp_apply_effect_instance_channel(rig, channel, scene=scene):
                        _fbp_refresh_geometry_source_materials(rig)
                except FBP_DATA_ERRORS:
                    _fbp_invalidate_effect_runtime_profile(rig)
                    continue

            push = _FrameEffectPush(rig, scene, runtime_profile, profile_enabled)
            for effect_id, instance_id, _item in instance_speed_fcurve_pairs:
                push.instance(effect_id, instance_id)

            updated_effect_ids = set()
            for animated_effect_id, animated_properties in animated_effect_properties.items():
                if animated_effect_id not in active_effect_ids:
                    continue
                property_names = set(animated_properties or ())
                if animated_effect_id in active_evolve_ids:
                    property_names |= _fbp_evolve_property_names(animated_effect_id)
                if animated_effect_id == FBP_EFFECT_CAMERA_BILLBOARD:
                    try:
                        _fbp_apply_track_to_camera_constraint(rig, scene)
                    except FBP_DATA_ERRORS:
                        _fbp_invalidate_effect_runtime_profile(rig)
                        continue
                # Keyed values may feed generated materials, so the
                # composites follow them.
                elif not push.effect(animated_effect_id, property_names, refresh_composites=True):
                    continue
                updated_effect_ids.add(animated_effect_id)

            for effect_id in (procedural_frame_effects or ()):
                if effect_id in active_effect_ids and effect_id not in updated_effect_ids:
                    if push.effect(
                        effect_id,
                        _fbp_evolve_property_names(effect_id, with_speed=False) or None,
                        geometry_only=True,
                    ):
                        updated_effect_ids.add(effect_id)

            if not evolve_enabled:
                continue

            for effect_id, _property_key in active_evolve_pairs:
                if effect_id in active_effect_ids and effect_id not in updated_effect_ids:
                    push.effect(
                        effect_id,
                        _fbp_evolve_property_names(effect_id, with_speed=False) or None,
                    )

            for effect_id, instance_id, _item in active_instance_evolve_pairs:
                if effect_id in active_effect_ids:
                    push.instance(effect_id, instance_id)
        _fbp_flush_composite_refreshes()
        if deferred_composite_rigs:
            # Settle the skipped composites once the timeline stops moving.
            _fbp_schedule_composite_catchup(scene, deferred_composite_rigs)
    finally:
        if _FBP_COMPOSITE_REFRESH_PENDING is not None:
            _fbp_flush_composite_refreshes()
        _FBP_EVOLVE_HANDLER_ACTIVE = False
        if profile_started:
            _fbp_effect_handler_record(
                (time.perf_counter() - profile_started) * 1000.0
            )


_FBP_NATIVE_TIMING_PATHS = (
    "image_user.frame_offset", "image_user.frame_start", "image_user.frame_duration",
)


def _fbp_layer_material_frame_dependent(rig):
    """True when the layer material has keys or drivers, or is a color plane
    whose frames are written from Python, so its values move with the frame."""
    try:
        if bool(getattr(rig, "fbp_is_color_plane", False)):
            return True
        for material in _fbp_plane_materials(rig):
            for owner in (material, getattr(material, "node_tree", None)):
                animation = getattr(owner, "animation_data", None) if owner is not None else None
                if animation is None:
                    continue
                # Sequence timing (ImageUser offsets) is animated natively in
                # the composites too; any other key or driver moves values.
                for curve in tuple(animation.drivers) + tuple(fbp_action_fcurves(owner) or ()):
                    if not str(getattr(curve, "data_path", "") or "").endswith(_FBP_NATIVE_TIMING_PATHS):
                        return True
    except FBP_DATA_ERRORS:
        return True
    return False


def _fbp_schedule_composite_catchup(scene, rigs):
    """Refresh composite materials skipped on frame changes, once, when idle."""
    scene_key = fbp_obj_runtime_key(scene)
    if scene_key is None:
        return False
    try:
        scene_name = str(getattr(scene, "name_full", getattr(scene, "name", "")) or "")
    except FBP_DATA_ERRORS:
        scene_name = ""
    rig_keys = tuple(
        key for key in (fbp_obj_runtime_key(rig) for rig in rigs) if key is not None
    )

    def _publish():
        if fbp_undo_guard_active() or fbp_render_mutation_blocked():
            return 0.20
        if _FBP_EFFECT_PLAYBACK_ACTIVE:
            return None
        if not fbp_depsgraph_quiet_for(0.15):
            return 0.10
        current_scene = fbp_find_id_by_runtime_key(
            getattr(bpy.data, "scenes", ()), scene_key, scene_name
        )
        if current_scene is None:
            return None
        wanted = set(rig_keys)
        try:
            rigs_now = _fbp_scene_effect_runtime_rigs(current_scene)
        except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
            return None
        for rig in rigs_now:
            try:
                if fbp_obj_runtime_key(rig) in wanted:
                    _fbp_refresh_geometry_source_materials(rig)
            except FBP_DATA_ERRORS:
                continue
        return None

    try:
        from .safe_tasks import schedule_once
        return bool(schedule_once(
            f"effects.composite_catchup:{scene_key}",
            _publish,
            first_interval=0.25,
        ))
    except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
        return False


def _fbp_selected_rigs_fn():
    global _FBP_SELECTED_RIGS_FN
    if _FBP_SELECTED_RIGS_FN is None:
        from .layers import get_selected_rigs
        _FBP_SELECTED_RIGS_FN = get_selected_rigs
    return _FBP_SELECTED_RIGS_FN


def _fbp_selected_rigs(context):
    try:
        return list(_fbp_selected_rigs_fn()(context) or [])
    except FBP_DATA_ERRORS:
        return []
    except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
        return []


def _fbp_capture_rig_targets(rigs):
    payload = []
    for rig in rigs or ():
        token = fbp_obj_runtime_token(rig)
        if not token:
            continue
        payload.append({
            "name": str(getattr(rig, "name", "") or ""),
            "key": token,
        })
    return json.dumps(payload, separators=(",", ":"))


def _fbp_resolve_rig_targets(payload):
    try:
        descriptors = json.loads(str(payload or "[]"))
    except (TypeError, ValueError, json.JSONDecodeError):
        return []
    rigs = []
    seen = set()
    for descriptor in descriptors if isinstance(descriptors, list) else ():
        if not isinstance(descriptor, dict):
            continue
        rig = fbp_find_id_by_runtime_key(
            bpy.data.objects,
            str(descriptor.get("key", "") or ""),
            str(descriptor.get("name", "") or ""),
        )
        key = fbp_obj_runtime_key(rig) if rig is not None else None
        if rig is not None and key not in seen:
            seen.add(key)
            rigs.append(rig)
    return rigs


def _fbp_plane(rig, *, repair=True):
    """Resolve the mesh plane owned by ``rig`` and repair recoverable pointers.

    The explicit pointer remains authoritative, but generated test scenes,
    duplicated rigs and older files can briefly retain only the parent/metadata
    relation. Lattice and other mesh-only tools should recover that plane rather
    than reporting a false compatibility error.
    """
    if not rig:
        return None
    try:
        plane = getattr(rig, "fbp_plane_target", None)
        if plane and getattr(plane, "type", "") == "MESH":
            return plane
    except FBP_DATA_ERRORS:
        plane = None

    tagged = []
    fallback = []
    owner_name = str(getattr(rig, "name", "") or "")
    candidates = ()
    try:
        from .fbp_index import iter_scene_fbp_planes
        scene = getattr(getattr(bpy, "context", None), "scene", None)
        candidates = tuple(iter_scene_fbp_planes(scene, fallback=True)) if scene is not None else ()
    except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
        candidates = ()
    if not candidates:
        # Cross-scene recovery is intentionally the last resort. The
        # indexed scene path above covers normal Undo, duplication and UI draws
        # without scanning every Object in the .blend.
        try:
            candidates = tuple(getattr(bpy.data, "objects", ()) or ())
        except FBP_DATA_ERRORS:
            candidates = ()
    try:
        for child in candidates:
            if str(getattr(child, "type", "") or "") != "MESH":
                continue
            is_parented = getattr(child, "parent", None) is rig
            try:
                stored_owner = str(child.get("fbp_parent_rig_name", "") or "")
            except FBP_DATA_ERRORS:
                stored_owner = ""
            if not is_parented and stored_owner != owner_name:
                continue
            fallback.append(child)
            if bool(getattr(child, "is_fbp_plane", False)) or stored_owner == owner_name:
                tagged.append(child)
    except FBP_DATA_ERRORS:
        return None

    candidate = tagged[0] if len(tagged) == 1 else (fallback[0] if not tagged and len(fallback) == 1 else None)
    if candidate is None:
        return None
    if repair and not fbp_render_mutation_blocked():
        try:
            rig.fbp_plane_target = candidate
            candidate.is_fbp_plane = True
            try:
                if getattr(candidate, "data", None) is not None:
                    candidate.data["fbp_plane_mesh"] = True
            except (AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
                pass
            candidate["fbp_parent_rig_name"] = str(rig.name)
        except FBP_DATA_ERRORS:
            pass
    return candidate


def _fbp_lattice_compatibility_issue(rig):
    """Return a user-facing reason when Lattice cannot be created."""
    if rig is None:
        return "Select a Frame By Plane layer"
    plane = _fbp_plane(rig, repair=True)
    if plane is None:
        return "The selected rig has no recoverable mesh plane. Run Tools > Repair Safe Issues"
    try:
        if getattr(plane, "data", None) is None:
            return "The linked plane has no mesh datablock"
        if len(getattr(plane.data, "vertices", ())) < 3:
            return "The linked mesh has insufficient geometry for a Lattice"
    except FBP_DATA_ERRORS:
        return "The linked mesh is temporarily unavailable"
    if fbp_render_mutation_blocked():
        return "Lattice cannot be created while Blender is rendering or rebuilding data"
    return ""


_FBP_LATTICE_OWNER_KEY = "fbp_lattice_owner"
_FBP_LATTICE_EFFECT_KEY = "fbp_lattice_effect"
_FBP_LATTICE_SCHEMA_KEY = "fbp_lattice_schema"
_FBP_LATTICE_MODE_KEY = "fbp_lattice_mode"
_FBP_LATTICE_BAKED_KEY = "fbp_lattice_baked"
_FBP_LATTICE_SCHEMA_VERSION = 9
_FBP_LATTICE_MODIFIER_NAME = "FBP • Lattice"
_FBP_LATTICE_DETAIL_MODIFIER_NAME = "FBP • Lattice Detail"

# Blender 5.2 exposes Geometry Nodes modifier inputs through the generated
# ``modifier.properties.inputs`` RNA interface. Stable effect ownership lives
# on the node group and rig; modifier ID properties are not part of the 5.2
# contract.
_FBP_LATTICE_MODIFIER_REF_KEY = "fbp_lattice_modifier_name"
_FBP_LATTICE_DETAIL_REF_KEY = "fbp_lattice_detail_modifier_name"
_FBP_LATTICE_HELPER_NAME_KEY = "fbp_lattice_helper_name"
_FBP_LATTICE_FLATTEN_CACHE = {}
_FBP_LATTICE_UPDATE_PENDING = set()
_FBP_LATTICE_LAST_ACTIVITY = {}
_FBP_LATTICE_LAST_ERROR = {}
# Helper resolution is called by UI drawing, stack syncing and audits. Cache
# both positive and negative scans so a missing cage never causes a full
# bpy.data.objects walk on every redraw. The cache is naturally invalidated
# when the object count changes and explicitly cleared on load/undo/rebuild.
_FBP_LATTICE_HELPER_RESOLVE_CACHE = {}
_FBP_LATTICE_REPAIR_PENDING = set()
_FBP_LATTICE_REPAIR_ATTEMPTED = {}
# Live Camera Flatten rigs are indexed per Scene. Freeform cages are fully native
# and therefore keep an indefinitely reusable empty index until an explicit
# effect/property/object-count change invalidates it.
_FBP_LATTICE_LIVE_SCENE_CACHE = {}


def _fbp_lattice_error_key(rig):
    try:
        key = fbp_obj_runtime_key(rig)
        if key is not None:
            return ("PTR", int(key))
    except FBP_DATA_ERRORS:
        pass
    try:
        return ("NAME", str(getattr(rig, "name_full", getattr(rig, "name", "")) or ""))
    except FBP_DATA_ERRORS:
        return ("NAME", "")


def _fbp_set_lattice_error(rig, message, exc=None):
    text = str(message or "Lattice setup failed").strip() or "Lattice setup failed"
    if exc is not None:
        detail = str(exc).strip()
        if detail and detail.lower() not in text.lower():
            text = f"{text}: {detail}"
    if len(text) > 240:
        text = text[:239].rstrip() + "…"
    key = _fbp_lattice_error_key(rig)
    if len(_FBP_LATTICE_LAST_ERROR) >= 512 and key not in _FBP_LATTICE_LAST_ERROR:
        _FBP_LATTICE_LAST_ERROR.clear()
    _FBP_LATTICE_LAST_ERROR[key] = text
    fbp_warn(text, exc)
    return text


def _fbp_clear_lattice_error(rig):
    _FBP_LATTICE_LAST_ERROR.pop(_fbp_lattice_error_key(rig), None)


def _fbp_last_lattice_error(rig):
    return str(_FBP_LATTICE_LAST_ERROR.get(_fbp_lattice_error_key(rig), "") or "")


def _fbp_stabilize_lattice_helper(helper):
    """Keep the cage in a stable native Lattice coordinate space.

    A previous bridge watched Object Mode transforms, baked them into every
    control point, and then restored the object matrix. Both writes generated
    new depsgraph updates, so Blender could alternate forever between the rig
    transform and the temporary cage transform. Native Lattice deformation is
    reliable when the cage object remains fixed and its planar points are edited
    in Edit Mode. A single point controls one visible cage intersection; pressing
    A still selects the entire cage for whole-grid G/R/S transforms.
    """
    if helper is None:
        return False
    changed = False
    try:
        locked = (True, True, True)
        for attribute in ("lock_location", "lock_rotation", "lock_scale"):
            if tuple(bool(value) for value in getattr(helper, attribute, (False, False, False))) != locked:
                setattr(helper, attribute, locked)
                changed = True
    except FBP_DATA_ERRORS:
        return changed
    return changed


def _fbp_lattice_contract_is_valid(rig, plane=None, helper=None, modifier=None):
    """Return True only when the complete generated Lattice contract is usable."""
    if rig is None:
        return False
    plane = plane or _fbp_plane(rig, repair=False)
    helper = helper or _fbp_lattice_object(rig)
    modifier = modifier or _fbp_lattice_modifier(plane)
    try:
        return bool(
            plane is not None
            and getattr(plane, "type", "") == "MESH"
            and getattr(plane, "data", None) is not None
            and helper is not None
            and getattr(helper, "type", "") == "LATTICE"
            and getattr(helper, "data", None) is not None
            and modifier is not None
            and getattr(modifier, "type", "") == "LATTICE"
            and getattr(modifier, "object", None) is helper
        )
    except FBP_DATA_ERRORS:
        return False


def _fbp_scene_collections(scene):
    """Yield Scene collections once without relying on the active UI context."""
    if scene is None:
        return
    try:
        stack = [scene.collection]
    except FBP_DATA_ERRORS:
        return
    seen = set()
    while stack:
        collection = stack.pop()
        try:
            key = int(collection.as_pointer())
        except FBP_DATA_ERRORS:
            key = id(collection)
        if key in seen:
            continue
        seen.add(key)
        yield collection
        try:
            stack.extend(tuple(collection.children))
        except FBP_DATA_ERRORS:
            pass


def _fbp_collection_in_scene(scene, collection):
    if scene is None or collection is None:
        return False
    try:
        return any(candidate is collection for candidate in _fbp_scene_collections(scene))
    except FBP_DATA_ERRORS:
        return False


def _fbp_lattice_target_collection(rig, plane, context=None):
    """Choose a writable collection that belongs to the current Scene.

    The old implementation blindly used ``plane.users_collection[0]``. A plane
    can be linked into multiple Scenes, so that collection may be outside the
    active View Layer; the later visibility call then raises and leaves a
    half-created cage behind. Prefer collections owned by the active Scene and
    fall back to its root collection.
    """
    context = context or getattr(bpy, "context", None)
    scene = getattr(context, "scene", None) if context is not None else None
    candidates = []
    for obj in (plane, rig):
        try:
            candidates.extend(tuple(getattr(obj, "users_collection", ()) or ()))
        except FBP_DATA_ERRORS:
            pass
    try:
        active_collection = getattr(context, "collection", None)
        if active_collection is not None:
            candidates.append(active_collection)
    except FBP_DATA_ERRORS:
        pass
    seen = set()
    for collection in candidates:
        if collection is None:
            continue
        try:
            key = int(collection.as_pointer())
        except FBP_DATA_ERRORS:
            key = id(collection)
        if key in seen:
            continue
        seen.add(key)
        if scene is None or _fbp_collection_in_scene(scene, collection):
            return collection
    try:
        return scene.collection if scene is not None else None
    except FBP_DATA_ERRORS:
        return None


def _fbp_ensure_lattice_link(helper, rig, plane, context=None):
    context = context or getattr(bpy, "context", None)
    target_collection = _fbp_lattice_target_collection(rig, plane, context)
    if helper is None or target_collection is None:
        _fbp_set_lattice_error(rig, "No writable Scene collection is available for the Lattice cage")
        return False
    first_error = None
    candidates = [target_collection]
    try:
        scene_root = getattr(getattr(context, "scene", None), "collection", None)
        if scene_root is not None and scene_root is not target_collection:
            candidates.append(scene_root)
    except FBP_DATA_ERRORS:
        pass
    for collection in candidates:
        try:
            if not any(existing is collection for existing in helper.users_collection):
                collection.objects.link(helper)
            try:
                view_layer = getattr(context, "view_layer", None)
                if view_layer is not None:
                    view_layer.update()
            except FBP_DATA_ERRORS:
                pass
            return True
        except FBP_DATA_ERRORS as exc:
            if first_error is None:
                first_error = exc
    _fbp_set_lattice_error(rig, "Could not link the Lattice cage to the active Scene", first_error)
    return False


def _fbp_cleanup_incomplete_lattice_setup(rig, *, force=False):
    """Remove owned partial Lattice data, including failed previous attempts.

    A merely linked helper/modifier pair is not enough to count as healthy. The
    previous early return preserved broken cages after a visibility or View
    Layer error, which explains the common pattern where the first click created
    something but reported an error and every following click failed again.
    """
    if rig is None:
        return False
    plane = _fbp_plane(rig, repair=False)
    helper = _fbp_lattice_object(rig)
    modifier = _fbp_lattice_modifier(plane)
    if not force and _fbp_lattice_contract_is_valid(rig, plane, helper, modifier):
        return False

    changed = False
    if plane is not None:
        stored_names = set()
        for key in (_FBP_LATTICE_MODIFIER_REF_KEY, _FBP_LATTICE_DETAIL_REF_KEY):
            try:
                name = str(plane.get(key, "") or "")
                if name:
                    stored_names.add(name)
            except FBP_DATA_ERRORS:
                pass
        for owned in tuple(getattr(plane, "modifiers", ()) or ()):
            try:
                name = str(getattr(owned, "name", "") or "")
                is_owned = (
                    name in stored_names
                    or (getattr(owned, "type", "") == "LATTICE" and _fbp_modifier_name_matches(
                        owned, _FBP_LATTICE_MODIFIER_NAME
                    ))
                    or (getattr(owned, "type", "") == "SUBSURF" and _fbp_modifier_name_matches(
                        owned, _FBP_LATTICE_DETAIL_MODIFIER_NAME
                    ))
                )
                if is_owned:
                    plane.modifiers.remove(owned)
                    changed = True
            except FBP_DATA_ERRORS:
                continue
        _fbp_store_modifier_reference(plane, _FBP_LATTICE_MODIFIER_REF_KEY, None)
        _fbp_store_modifier_reference(plane, _FBP_LATTICE_DETAIL_REF_KEY, None)

    try:
        # One armature holds every handle and bone: drop it, then its Hooks.
        from .lattice_bones import remove_armature
        changed = bool(remove_armature(rig, helper)) or changed
        from .lattice_pins import remove_all_pins
        changed = bool(remove_all_pins(rig, helper)) or changed
    except (ImportError,) + FBP_DATA_ERRORS:
        pass

    owner_name = str(getattr(rig, "name", "") or "")
    helpers = []
    if helper is not None:
        helpers.append(helper)
    try:
        for obj in tuple(getattr(bpy.data, "objects", ()) or ()):
            if getattr(obj, "type", "") != "LATTICE" or obj in helpers:
                continue
            try:
                owned = (
                    str(obj.get(_FBP_LATTICE_OWNER_KEY, "") or "") == owner_name
                    or (
                        getattr(obj, "parent", None) is rig
                        and str(obj.get(_FBP_LATTICE_EFFECT_KEY, "") or "") == FBP_EFFECT_LATTICE
                    )
                )
            except FBP_DATA_ERRORS:
                owned = False
            if owned:
                helpers.append(obj)
    except FBP_DATA_ERRORS:
        pass

    for owned_helper in helpers:
        data = getattr(owned_helper, "data", None)
        try:
            bpy.data.objects.remove(owned_helper, do_unlink=True)
            changed = True
        except FBP_DATA_ERRORS:
            pass
        try:
            if data is not None and data.users == 0:
                bpy.data.lattices.remove(data)
        except FBP_DATA_ERRORS:
            pass
    try:
        if getattr(rig, "fbp_lattice_object", None) is not None:
            rig.fbp_lattice_object = None
            changed = True
        if _FBP_LATTICE_HELPER_NAME_KEY in rig:
            del rig[_FBP_LATTICE_HELPER_NAME_KEY]
            changed = True
    except FBP_DATA_ERRORS:
        pass
    repair_key = _fbp_lattice_error_key(rig)
    _FBP_LATTICE_HELPER_RESOLVE_CACHE.pop(repair_key, None)
    _FBP_LATTICE_REPAIR_ATTEMPTED.pop(repair_key, None)
    _FBP_LATTICE_REPAIR_PENDING.discard(repair_key)
    return changed

def _fbp_claim_lattice_helper(rig, helper, *, trusted=False):
    """Repair and return a cage owned by ``rig``.

    A rig pointer, parent relation or Lattice modifier binding is authoritative.
    Older builds stored only a readable owner name, which becomes stale after a
    layer rename and previously made a perfectly valid cage look missing.
    """
    if rig is None or helper is None:
        return None
    try:
        if getattr(helper, "type", "") != "LATTICE" or getattr(helper, "data", None) is None:
            return None
        owner_name = str(getattr(rig, "name", "") or "")
        stored_owner = str(helper.get(_FBP_LATTICE_OWNER_KEY, "") or "")
        helper_parent = getattr(helper, "parent", None)
        parent_matches = helper_parent is rig
        # Duplicating a layer can temporarily copy PointerProperties and modifier
        # bindings to the original cage. Never steal a cage that is still owned
        # by another live Frame By Plane rig; the transactional apply path will
        # instead remove the copied binding and create a private helper.
        foreign_parent = bool(
            helper_parent is not None
            and helper_parent is not rig
            and bool(getattr(helper_parent, "is_fbp_control", False))
        )
        foreign_owner = None
        if stored_owner and stored_owner != owner_name:
            foreign_owner = bpy.data.objects.get(stored_owner)
        foreign_owner_live = bool(
            foreign_owner is not None
            and foreign_owner is not rig
            and bool(getattr(foreign_owner, "is_fbp_control", False))
        )
        if (foreign_parent or foreign_owner_live) and not parent_matches:
            return None
        if not trusted and stored_owner not in {"", owner_name} and not parent_matches:
            return None
        # Resolver calls happen during every sidebar redraw. Write Blender data
        # only when repair is actually needed; assigning an unchanged ID property
        # still tags the datablock and can trigger unnecessary depsgraph work.
        if stored_owner != owner_name:
            helper[_FBP_LATTICE_OWNER_KEY] = owner_name
        if str(helper.get(_FBP_LATTICE_EFFECT_KEY, "") or "") != FBP_EFFECT_LATTICE:
            helper[_FBP_LATTICE_EFFECT_KEY] = FBP_EFFECT_LATTICE
        if not parent_matches:
            world = helper.matrix_world.copy()
            helper.parent = rig
            helper.matrix_world = world
        if getattr(rig, "fbp_lattice_object", None) is not helper:
            rig.fbp_lattice_object = helper
        try:
            from .ownership import tag_lattice_helper_contract
            tag_lattice_helper_contract(helper, rig)
        except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
            pass
        try:
            if str(rig.get(_FBP_LATTICE_HELPER_NAME_KEY, "") or "") != str(helper.name):
                rig[_FBP_LATTICE_HELPER_NAME_KEY] = str(helper.name)
        except FBP_DATA_ERRORS:
            pass
        cache_key = _fbp_lattice_error_key(rig)
        try:
            object_count = len(bpy.data.objects)
        except FBP_DATA_ERRORS:
            object_count = -1
        _FBP_LATTICE_HELPER_RESOLVE_CACHE[cache_key] = (object_count, str(helper.name))
        return helper
    except FBP_DATA_ERRORS:
        return None


def _fbp_lattice_object(rig):
    """Resolve the owned cage with O(1) common paths and one cached recovery scan."""
    if rig is None:
        return None

    # 1. The saved pointer is the fastest and strongest ownership signal.
    try:
        helper = _fbp_claim_lattice_helper(
            rig, getattr(rig, "fbp_lattice_object", None), trusted=True
        )
        if helper is not None:
            return helper
    except FBP_DATA_ERRORS:
        pass

    # Cached recovery resolution comes before any collection/property walks. The
    # common missing-cage UI state then costs only two dictionary lookups.
    cache_key = _fbp_lattice_error_key(rig)
    try:
        object_count = len(bpy.data.objects)
    except FBP_DATA_ERRORS:
        object_count = -1
    cached = _FBP_LATTICE_HELPER_RESOLVE_CACHE.get(cache_key)
    if cached is not None and int(cached[0]) == object_count:
        cached_name = str(cached[1] or "")
        if not cached_name:
            return None
        helper = _fbp_claim_lattice_helper(
            rig, bpy.data.objects.get(cached_name), trusted=True
        )
        if helper is not None:
            return helper

    # 2. The modifier binding is authoritative even when rename/undo invalidated
    # the rig pointer or readable owner metadata. This is the main recovery path
    # after rename, duplication or Undo.
    try:
        plane = _fbp_plane(rig, repair=False)
        modifier = _fbp_lattice_modifier(plane)
        candidate = getattr(modifier, "object", None) if modifier is not None else None
        helper = _fbp_claim_lattice_helper(rig, candidate, trusted=True)
        if helper is not None:
            return helper
    except FBP_DATA_ERRORS:
        pass

    # 3. Stored helper name survives PointerProperty recovery failures cheaply.
    try:
        helper_name = str(rig.get(_FBP_LATTICE_HELPER_NAME_KEY, "") or "")
        if helper_name:
            helper = _fbp_claim_lattice_helper(
                rig, bpy.data.objects.get(helper_name), trusted=True
            )
            if helper is not None:
                return helper
    except FBP_DATA_ERRORS:
        pass

    # 4. Metadata-only recovery requires one global scan. Cache the negative
    # result as well: this function is called from panel draw and must stay O(1)
    # after the first recovery attempt. ``Object.children`` is intentionally not
    # used here because Blender computes it by scanning every Object.
    owner_name = str(getattr(rig, "name", "") or "")
    if not owner_name:
        return None
    cached = _FBP_LATTICE_HELPER_RESOLVE_CACHE.get(cache_key)
    if cached is not None and int(cached[0]) == object_count:
        cached_name = str(cached[1] or "")
        if not cached_name:
            return None
        helper = _fbp_claim_lattice_helper(
            rig, bpy.data.objects.get(cached_name), trusted=True
        )
        if helper is not None:
            return helper

    helper = None
    try:
        for obj in tuple(getattr(bpy.data, "objects", ()) or ()):
            try:
                if getattr(obj, "type", "") != "LATTICE":
                    continue
                metadata_owner = str(obj.get(_FBP_LATTICE_OWNER_KEY, "") or "") == owner_name
                parent_owner = (
                    getattr(obj, "parent", None) is rig
                    and str(obj.get(_FBP_LATTICE_EFFECT_KEY, "") or "") == FBP_EFFECT_LATTICE
                )
                if not (metadata_owner or parent_owner):
                    continue
            except FBP_DATA_ERRORS:
                continue
            helper = _fbp_claim_lattice_helper(rig, obj, trusted=True)
            if helper is not None:
                break
    except FBP_DATA_ERRORS:
        helper = None
    _FBP_LATTICE_HELPER_RESOLVE_CACHE[cache_key] = (
        object_count, str(getattr(helper, "name", "") or "")
    )
    return helper


def _fbp_modifier_name_matches(modifier, base_name):
    """Match an addon-owned modifier without relying on unsupported ID props."""
    try:
        name = str(getattr(modifier, "name", "") or "")
        return name == base_name or name.startswith(f"{base_name}.")
    except FBP_DATA_ERRORS:
        return False


def _fbp_stored_modifier(plane, key, modifier_type):
    if plane is None:
        return None
    try:
        name = str(plane.get(key, "") or "")
        if not name:
            return None
        modifier = plane.modifiers.get(name)
        if modifier is not None and str(getattr(modifier, "type", "") or "") == modifier_type:
            return modifier
    except FBP_DATA_ERRORS:
        pass
    return None


def _fbp_store_modifier_reference(plane, key, modifier):
    if plane is None:
        return False
    try:
        if modifier is None:
            if key in plane:
                del plane[key]
        else:
            plane[key] = str(modifier.name)
        return True
    except FBP_DATA_ERRORS:
        return False


def _fbp_lattice_modifier(plane):
    if plane is None:
        return None
    stored = _fbp_stored_modifier(plane, _FBP_LATTICE_MODIFIER_REF_KEY, "LATTICE")
    if stored is not None:
        return stored
    for modifier in tuple(getattr(plane, "modifiers", ())):
        try:
            if getattr(modifier, "type", "") == "LATTICE" and _fbp_modifier_name_matches(
                modifier, _FBP_LATTICE_MODIFIER_NAME
            ):
                _fbp_store_modifier_reference(plane, _FBP_LATTICE_MODIFIER_REF_KEY, modifier)
                return modifier
        except FBP_DATA_ERRORS:
            continue
    return None


def _fbp_lattice_detail_modifier(plane):
    if plane is None:
        return None
    stored = _fbp_stored_modifier(plane, _FBP_LATTICE_DETAIL_REF_KEY, "SUBSURF")
    if stored is not None:
        return stored
    for modifier in tuple(getattr(plane, "modifiers", ())):
        try:
            if getattr(modifier, "type", "") == "SUBSURF" and _fbp_modifier_name_matches(
                modifier, _FBP_LATTICE_DETAIL_MODIFIER_NAME
            ):
                _fbp_store_modifier_reference(plane, _FBP_LATTICE_DETAIL_REF_KEY, modifier)
                return modifier
        except FBP_DATA_ERRORS:
            continue
    return None


def _fbp_lattice_mesh_detail_mode(rig):
    try:
        mode = str(getattr(rig, "fbp_lattice_mesh_detail_mode", "AUTO") or "AUTO").upper()
    except FBP_DATA_ERRORS:
        mode = "AUTO"
    return mode if mode in {"AUTO", "CUSTOM"} else "AUTO"


def _fbp_lattice_mesh_density_multiplier(rig):
    try:
        density = str(getattr(rig, "fbp_lattice_mesh_density", "DOUBLE") or "DOUBLE").upper()
    except FBP_DATA_ERRORS:
        density = "DOUBLE"
    return {"MATCH": 1.0, "DOUBLE": 2.0, "QUADRUPLE": 4.0}.get(density, 2.0)


_FBP_LATTICE_GRID_PRESET_LOOPS = {
    "CORNERS": (0, 0),
    "BASIC": (1, 1),
    "LOOPS_2": (2, 2),
    "LOOPS_4": (4, 4),
}


def _fbp_lattice_grid_loops(rig):
    """Return internal loop counts; corner control points are not counted."""
    try:
        preset = str(getattr(rig, "fbp_lattice_grid_preset", "LOOPS_2") or "LOOPS_2").upper()
    except FBP_DATA_ERRORS:
        preset = "LOOPS_2"
    if preset in _FBP_LATTICE_GRID_PRESET_LOOPS:
        return _FBP_LATTICE_GRID_PRESET_LOOPS[preset]
    try:
        loops_u = max(0, min(62, int(getattr(rig, "fbp_lattice_custom_loops_u", 6) or 0)))
        loops_v = max(0, min(62, int(getattr(rig, "fbp_lattice_custom_loops_v", 6) or 0)))
    except FBP_DATA_ERRORS:
        loops_u = loops_v = 6
    return loops_u, loops_v


def _fbp_apply_lattice_grid_settings(rig):
    """Translate user-facing internal loops to Blender Lattice point counts."""
    if rig is None:
        return False
    loops_u, loops_v = _fbp_lattice_grid_loops(rig)
    target_u = max(2, min(64, loops_u + 2))
    target_v = max(2, min(64, loops_v + 2))
    changed = False
    try:
        if int(getattr(rig, "fbp_lattice_points_u", 4) or 4) != target_u:
            fbp_set_rna_property_silent(rig, "fbp_lattice_points_u", target_u)
            changed = True
        if int(getattr(rig, "fbp_lattice_points_v", 4) or 4) != target_v:
            fbp_set_rna_property_silent(rig, "fbp_lattice_points_v", target_v)
            changed = True
    except FBP_DATA_ERRORS:
        return False
    return changed


def _fbp_lattice_mesh_detail_levels(rig):
    """Return Simple Subdivision levels for the requested planar mesh density.

    Blender's Simple Subdivision doubles the number of face segments per level,
    so automatic mode converts the cage cell count into the smallest power-of-two
    mesh grid meeting the requested density. Custom mode exposes Blender's native
    levels directly.
    """
    if _fbp_lattice_mesh_detail_mode(rig) == "CUSTOM":
        try:
            return max(0, min(6, int(getattr(rig, "fbp_lattice_mesh_subdivisions", 2) or 0)))
        except FBP_DATA_ERRORS:
            return 2
    try:
        cage_cells = max(
            1,
            int(getattr(rig, "fbp_lattice_points_u", 2) or 2) - 1,
            int(getattr(rig, "fbp_lattice_points_v", 2) or 2) - 1,
        )
    except FBP_DATA_ERRORS:
        cage_cells = 1
    target_segments = max(1, int(math.ceil(cage_cells * _fbp_lattice_mesh_density_multiplier(rig))))
    return max(0, min(6, int(math.ceil(math.log2(target_segments)))))


def _fbp_sync_lattice_detail_modifier(rig, plane, lattice_modifier=None):
    """Create or update the lightweight Simple Subdivision before Lattice."""
    levels = _fbp_lattice_mesh_detail_levels(rig)
    detail = _fbp_lattice_detail_modifier(plane)
    if levels <= 0:
        if detail is not None:
            try:
                plane.modifiers.remove(detail)
                _fbp_store_modifier_reference(plane, _FBP_LATTICE_DETAIL_REF_KEY, None)
                return None
            except FBP_DATA_ERRORS:
                return detail
        _fbp_store_modifier_reference(plane, _FBP_LATTICE_DETAIL_REF_KEY, None)
        return None
    if detail is None:
        try:
            detail = plane.modifiers.new(_FBP_LATTICE_DETAIL_MODIFIER_NAME, "SUBSURF")
        except FBP_DATA_ERRORS as exc:
            fbp_warn("Could not add Lattice detail modifier", exc)
            return None
    try:
        detail.subdivision_type = 'SIMPLE'
        detail.levels = levels
        detail.render_levels = levels
        # SIMPLE subdivision has no smoothing cost. Hide generated interior
        # control edges and disable edit-cage evaluation to keep dense planes
        # responsive while the user manipulates the Lattice points.
        detail.show_only_control_edges = True
        detail.show_in_editmode = False
        detail.show_on_cage = False
        detail.show_viewport = _fbp_stored_effect_visibility(rig, FBP_EFFECT_LATTICE, True)
        detail.show_render = _fbp_stored_effect_render_visibility(rig, FBP_EFFECT_LATTICE, True)
        _fbp_store_modifier_reference(plane, _FBP_LATTICE_DETAIL_REF_KEY, detail)
        if lattice_modifier is not None:
            detail_index = next((i for i, item in enumerate(plane.modifiers) if item == detail), -1)
            lattice_index = next((i for i, item in enumerate(plane.modifiers) if item == lattice_modifier), -1)
            if detail_index >= 0 and lattice_index >= 0 and detail_index > lattice_index:
                plane.modifiers.move(detail_index, lattice_index)
    except FBP_DATA_ERRORS:
        pass
    return detail


def _fbp_lattice_local_bounds(plane):
    """Return stable undeformed local bounds for the image plane.

    Read the mesh data first: ``Object.bound_box`` reports the evaluated
    object, so a deformed cage (or a Thickness effect) would otherwise refit
    the Lattice around its own deformation.
    """
    try:
        points = [vertex.co.copy() for vertex in plane.data.vertices]
    except FBP_DATA_ERRORS:
        points = []
    if not points:
        try:
            points = [Vector(point) for point in tuple(plane.bound_box or ())]
        except (AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
            points = []
    if not points:
        points = [Vector((-0.5, -0.5, 0.0)), Vector((0.5, 0.5, 0.0))]
    minimum = Vector((
        min(point.x for point in points),
        min(point.y for point in points),
        min(point.z for point in points),
    ))
    maximum = Vector((
        max(point.x for point in points),
        max(point.y for point in points),
        max(point.z for point in points),
    ))
    return minimum, maximum


def _fbp_lattice_fit_matrix(plane, bounds=None):
    """Return a world transform enclosing the plane in its own local axes."""
    minimum, maximum = bounds or _fbp_lattice_local_bounds(plane)
    center = (minimum + maximum) * 0.5
    size = maximum - minimum
    size.x = max(abs(float(size.x)), 0.001)
    size.y = max(abs(float(size.y)), 0.001)
    # Keep a small non-zero local Z scale even for the planar one-layer cage.
    # This preserves an invertible object transform without adding overlapping
    # front/back control points.
    size.z = max(abs(float(size.z)), min(size.x, size.y) * 0.08, 0.01)
    local = Matrix.Translation(center) @ Matrix.Diagonal((size.x, size.y, size.z, 1.0))
    return plane.matrix_world @ local


def _fbp_lattice_runtime_key(rig):
    try:
        return fbp_obj_runtime_key(rig)
    except FBP_DATA_ERRORS:
        return None


def _fbp_lattice_matrix_signature(matrix, precision=7):
    try:
        return tuple(round(float(value), precision) for row in matrix for value in row)
    except (AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
        return ()


def _fbp_lattice_bounds_signature(plane, precision=7):
    try:
        minimum, maximum = _fbp_lattice_local_bounds(plane)
        return tuple(round(float(value), precision) for value in (*minimum, *maximum))
    except (AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
        return ()


def _fbp_lattice_scene_camera(scene=None):
    scene = scene or getattr(bpy.context, "scene", None)
    try:
        camera = getattr(scene, "camera", None)
        if camera is not None and getattr(camera, "type", "") == "CAMERA":
            return camera
    except FBP_DATA_ERRORS:
        pass
    return None


def _fbp_lattice_mode(rig):
    try:
        return str(getattr(rig, "fbp_lattice_mode", "FREEFORM") or "FREEFORM").upper()
    except FBP_DATA_ERRORS:
        return "FREEFORM"


def _fbp_lattice_camera_flatten_enabled(rig):
    try:
        return (
            _fbp_is_enabled(rig, FBP_EFFECT_LATTICE)
            and _fbp_lattice_mode(rig) == "CAMERA_FLATTEN"
        )
    except FBP_DATA_ERRORS:
        return False


def _fbp_lattice_live_enabled(rig):
    """True for cages Python rewrites on motion and frame change."""
    try:
        if not _fbp_is_enabled(rig, FBP_EFFECT_LATTICE):
            return False
        mode = _fbp_lattice_mode(rig)
        if mode == "CORNER_PIN":
            return True
        return mode == "CAMERA_FLATTEN" and bool(getattr(rig, "fbp_lattice_live_update", True))
    except FBP_DATA_ERRORS:
        return False


def _fbp_apply_lattice_corner_pin(rig, *, force=False):
    """Map the cage onto the four corner handles with a true perspective."""
    if rig is None or _fbp_lattice_mode(rig) != "CORNER_PIN":
        return False
    helper = _fbp_lattice_object(rig)
    plane = _fbp_plane(rig, repair=False)
    if helper is None or plane is None:
        return False
    try:
        # Handles are only created by Set Up (it needs Edit Mode); a live
        # update with no handles leaves the cage as it is.
        from .lattice_corner_pin import apply
        return bool(apply(rig, helper, force=force))
    except (ImportError,) + FBP_DATA_ERRORS as exc:
        fbp_warn("Could not update the Corner Pin", exc)
        return False


def _fbp_apply_lattice_live(rig, *, scene=None, force=False):
    if _fbp_lattice_mode(rig) == "CORNER_PIN":
        return _fbp_apply_lattice_corner_pin(rig, force=force)
    return _fbp_apply_lattice_camera_flatten(rig, scene=scene, force=force)


def schedule_lattice_corner_pin_update(rig):
    """Rewrite a Corner Pin cage right after its handles moved (no debounce)."""
    rig_name = str(getattr(rig, "name", "") or "")
    if not rig_name:
        return False

    def _run():
        current = bpy.data.objects.get(rig_name)
        if current is not None:
            _fbp_apply_lattice_corner_pin(current, force=False)
        return None

    try:
        from .safe_tasks import schedule_once
        return bool(schedule_once(f"lattice.corner_pin.{rig_name}", _run, first_interval=0.0))
    except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
        return False


def schedule_lattice_bones_rebind(rig):
    """Rebuild bone weights once the rest bones changed (after Edit Mode)."""
    rig_name = str(getattr(rig, "name", "") or "")
    if not rig_name:
        return False

    def _run():
        current = bpy.data.objects.get(rig_name)
        if current is None:
            return None
        helper = _fbp_lattice_object(current)
        plane = _fbp_plane(current, repair=False)
        try:
            from .lattice_bones import bind
            bind(current, helper, plane, force=False)
        except (ImportError,) + FBP_DATA_ERRORS:
            pass
        return None

    try:
        from .safe_tasks import schedule_once
        return bool(schedule_once(f"lattice.bones.rebind.{rig_name}", _run, first_interval=0.05))
    except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
        return False


def _fbp_update_lattice_data(rig, helper):
    """Synchronize cage topology and interpolation.

    Return True only when the point topology changed. Interpolation changes are
    deliberately excluded: older builds treated every interpolation update as a
    topology rebuild and silently reset all manual cage deformation.
    """
    data = getattr(helper, "data", None) if helper else None
    if data is None:
        return False
    # Frame By Plane layers are planar, therefore the cage uses one depth
    # layer. Each visible grid intersection is one selectable control point: a
    # 2 × 2 cage has exactly four corner points rather than front/back pairs.
    # Resizing resamples the current shape and its poses instead of resetting
    # them (Blender also locks the resolution while poses exist).
    try:
        from .lattice_poses import resize_preserving_shape
        topology_changed = resize_preserving_shape(
            helper,
            max(2, int(getattr(rig, "fbp_lattice_points_u", 4) or 4)),
            max(2, int(getattr(rig, "fbp_lattice_points_v", 4) or 4)),
        )
    except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError) as exc:
        fbp_warn("Could not resize the Lattice cage", exc)
        topology_changed = False
    interpolation = (
        "KEY_LINEAR"
        if _fbp_lattice_mode(rig) in {"CAMERA_FLATTEN", "CORNER_PIN"}
        else {
            "LINEAR": "KEY_LINEAR",
            "CARDINAL": "KEY_CARDINAL",
            "CATMULL_ROM": "KEY_CATMULL_ROM",
            "BSPLINE": "KEY_BSPLINE",
        }.get(str(getattr(rig, "fbp_lattice_interpolation", "BSPLINE") or "BSPLINE"), "KEY_BSPLINE")
    )
    for attribute in ("interpolation_type_u", "interpolation_type_v", "interpolation_type_w"):
        try:
            if str(getattr(data, attribute, "")) != interpolation:
                setattr(data, attribute, interpolation)
        except (AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
            pass
    return topology_changed


def _fbp_lattice_point_index(u_index, v_index, w_index, points_u, points_v):
    # Blender stores U as the fastest axis, followed by V and then W.
    return (
        int(u_index)
        + int(v_index) * int(points_u)
        + int(w_index) * int(points_u) * int(points_v)
    )


def _fbp_reset_lattice_points(helper):
    """Restore a regular undeformed lattice without replacing the datablock."""
    data = getattr(helper, "data", None) if helper else None
    if data is None:
        return False
    try:
        points_u = max(2, int(data.points_u))
        points_v = max(2, int(data.points_v))
        points_w = max(1, int(data.points_w))
        coordinates = [0.0] * (points_u * points_v * points_w * 3)
        for u_index in range(points_u):
            x = u_index / float(points_u - 1) - 0.5
            for v_index in range(points_v):
                y = v_index / float(points_v - 1) - 0.5
                for w_index in range(points_w):
                    z = 0.0 if points_w == 1 else (w_index / float(points_w - 1)) - 0.5
                    index = _fbp_lattice_point_index(
                        u_index, v_index, w_index, points_u, points_v
                    ) * 3
                    coordinates[index:index + 3] = (x, y, z)
        # Poses keep their own deformation on top of the reset rest cage.
        from .lattice_poses import write_rest_cage
        write_rest_cage(helper, coordinates)
        return True
    except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError, IndexError):
        return False


def _fbp_lattice_flatten_signature(rig, plane, helper, camera, bounds=None):
    data = getattr(helper, "data", None)
    camera_data = getattr(camera, "data", None)
    try:
        influence = round(float(getattr(rig, "fbp_lattice_flatten_influence", 1.0) or 0.0), 7)
        dimensions = (
            int(getattr(data, "points_u", 0) or 0),
            int(getattr(data, "points_v", 0) or 0),
            int(getattr(data, "points_w", 0) or 0),
        )
        if bounds is None:
            bounds_signature = _fbp_lattice_bounds_signature(plane)
        else:
            minimum, maximum = bounds
            bounds_signature = tuple(
                round(float(value), 7) for value in (*minimum, *maximum)
            )
        return (
            _fbp_lattice_matrix_signature(plane.matrix_world),
            bounds_signature,
            _fbp_lattice_matrix_signature(camera.matrix_world),
            str(getattr(camera_data, "type", "PERSP") or "PERSP"),
            influence,
            dimensions,
            int(getattr(helper, "as_pointer", lambda: 0)()),
        )
    except FBP_DATA_ERRORS:
        return None


def _fbp_apply_lattice_camera_flatten(rig, *, scene=None, force=False):
    """Bake camera-space perspective using one projection setup per cage.

    Earlier builds rebuilt the camera basis for every control point and sampled
    plane bounds three times per update. A 64 × 64 cage therefore performed
    thousands of redundant matrix copies and quaternion conversions.
    """
    if not _fbp_lattice_camera_flatten_enabled(rig):
        return False
    plane = _fbp_plane(rig, repair=False)
    helper = _fbp_lattice_object(rig)
    camera = _fbp_lattice_scene_camera(scene)
    if plane is None or helper is None or camera is None:
        return False
    data = getattr(helper, "data", None)
    if data is None:
        return False

    try:
        expected_u = max(2, int(getattr(rig, "fbp_lattice_points_u", 4) or 4))
        expected_v = max(2, int(getattr(rig, "fbp_lattice_points_v", 4) or 4))
        if (int(data.points_u), int(data.points_v), int(data.points_w)) != (expected_u, expected_v, 1):
            _fbp_update_lattice_data(rig, helper)

        minimum, maximum = _fbp_lattice_local_bounds(plane)
        bounds = (minimum, maximum)
        signature = _fbp_lattice_flatten_signature(
            rig, plane, helper, camera, bounds=bounds
        )
        cache_key = _fbp_lattice_runtime_key(rig)
        if not force and cache_key is not None and _FBP_LATTICE_FLATTEN_CACHE.get(cache_key) == signature:
            return False

        fit_matrix = _fbp_lattice_fit_matrix(plane, bounds=bounds)
        if _fbp_lattice_matrix_signature(helper.matrix_world) != _fbp_lattice_matrix_signature(fit_matrix):
            helper.matrix_world = fit_matrix
        inverse_fit = fit_matrix.inverted_safe()
        plane_matrix = plane.matrix_world.copy()
        center_local = (minimum + maximum) * 0.5
        pivot_world = plane_matrix @ center_local

        camera_matrix = camera.matrix_world.copy()
        camera_forward = camera_matrix.to_quaternion() @ Vector((0.0, 0.0, -1.0))
        if camera_forward.length_squared <= 1.0e-12:
            return False
        camera_forward.normalize()
        camera_origin = camera_matrix.translation.copy()
        camera_type = str(getattr(getattr(camera, "data", None), "type", "PERSP") or "PERSP").upper()
        if camera_type not in {"PERSP", "ORTHO"}:
            return False
        perspective_plane_distance = (pivot_world - camera_origin).dot(camera_forward)
        influence = max(0.0, min(1.0, float(getattr(rig, "fbp_lattice_flatten_influence", 1.0) or 0.0)))

        points_u = max(2, int(data.points_u))
        points_v = max(2, int(data.points_v))
        points_w = max(1, int(data.points_w))
        min_x, max_x = float(minimum.x), float(maximum.x)
        min_y, max_y = float(minimum.y), float(maximum.y)
        center_z = float(center_local.z)
        span_x = max_x - min_x
        span_y = max_y - min_y
        inv_u = 1.0 / float(points_u - 1)
        inv_v = 1.0 / float(points_v - 1)
        layer_stride = points_u * points_v
        coordinates = [0.0] * (layer_stride * points_w * 3)

        for v_index in range(points_v):
            local_y = min_y + span_y * (v_index * inv_v)
            row_offset = v_index * points_u
            for u_index in range(points_u):
                local_x = min_x + span_x * (u_index * inv_u)
                source_world = plane_matrix @ Vector((local_x, local_y, center_z))
                if camera_type == "ORTHO":
                    target_world = source_world + camera_forward * (
                        (pivot_world - source_world).dot(camera_forward)
                    )
                else:
                    direction = source_world - camera_origin
                    denominator = direction.dot(camera_forward)
                    if abs(float(denominator)) <= 1.0e-10:
                        return False
                    target_world = camera_origin + direction * (
                        perspective_plane_distance / denominator
                    )
                if influence < 1.0:
                    target_world = source_world.lerp(target_world, influence)
                surface = inverse_fit @ target_world
                base_index = row_offset + u_index
                if points_w == 1:
                    target = base_index * 3
                    coordinates[target] = float(surface.x)
                    coordinates[target + 1] = float(surface.y)
                    coordinates[target + 2] = float(surface.z)
                else:
                    for w_index in range(points_w):
                        depth = (w_index / float(points_w - 1)) - 0.5
                        target = (base_index + w_index * layer_stride) * 3
                        coordinates[target] = float(surface.x)
                        coordinates[target + 1] = float(surface.y)
                        coordinates[target + 2] = float(surface.z + depth)

        # One bulk RNA write replaces thousands of individual co_deform
        # assignments and is the dominant Camera Flatten performance gain.
        # With poses the Basis key is rewritten too (Blender evaluates keys).
        from .lattice_poses import write_rest_cage
        write_rest_cage(helper, coordinates)

        helper[_FBP_LATTICE_SCHEMA_KEY] = _FBP_LATTICE_SCHEMA_VERSION
        helper[_FBP_LATTICE_MODE_KEY] = "CAMERA_FLATTEN"
        if bool(getattr(rig, "fbp_lattice_live_update", True)):
            helper[_FBP_LATTICE_BAKED_KEY] = False
        data.update_tag()
        helper.update_tag(refresh={'DATA'})
        if cache_key is not None and signature is not None:
            if len(_FBP_LATTICE_FLATTEN_CACHE) >= 512 and cache_key not in _FBP_LATTICE_FLATTEN_CACHE:
                _FBP_LATTICE_FLATTEN_CACHE.clear()
            _FBP_LATTICE_FLATTEN_CACHE[cache_key] = signature
        return True
    except FBP_DATA_ERRORS as exc:
        fbp_warn("Could not flatten Lattice to camera", exc)
        return False


def _fbp_configure_lattice_visibility(rig, plane, helper, modifier, detail_modifier=None, *, context=None):
    """Apply presentation state without making cosmetic failures transactional."""
    viewport_visible = _fbp_stored_effect_visibility(rig, FBP_EFFECT_LATTICE, True)
    render_visible = _fbp_stored_effect_render_visibility(rig, FBP_EFFECT_LATTICE, True)
    show_cage = bool(getattr(rig, "fbp_lattice_show_cage", True))
    for owned_modifier in (modifier, detail_modifier):
        if owned_modifier is None:
            continue
        try:
            owned_modifier.show_viewport = viewport_visible
            owned_modifier.show_render = render_visible
        except FBP_DATA_ERRORS:
            pass
    try:
        helper.hide_render = True
        helper.display_type = "WIRE"
        helper.show_in_front = True
        # Only disable evaluation when the effect itself is disabled. Cage
        # drawing is controlled separately through hide_set.
        helper.hide_viewport = not viewport_visible
    except FBP_DATA_ERRORS:
        pass

    context = context or getattr(bpy, "context", None)
    try:
        view_layer = getattr(context, "view_layer", None)
        if view_layer is not None and view_layer.objects.get(helper.name) is not None:
            active = getattr(context, "active_object", None) or getattr(context, "object", None)
            selected = bool(
                (rig is not None and rig.select_get())
                or (plane is not None and plane.select_get())
                or helper.select_get()
                or active is helper
                or active is rig
                or active is plane
            )
            helper.hide_set(not bool(viewport_visible and show_cage and selected))
    except FBP_DATA_ERRORS:
        # An object outside the active View Layer can still evaluate correctly;
        # do not destroy a valid modifier just because its drawing state failed.
        pass


def fbp_focus_lattice_ui(context, rig):
    """Keep the Lattice row selected while its cage is active."""
    if context is None or rig is None:
        return False
    changed = False
    try:
        changed = _fbp_select_effect_row(rig, FBP_EFFECT_LATTICE, [rig]) or changed
    except FBP_DATA_ERRORS:
        pass
    return changed


def _fbp_select_lattice_helper(rig, helper, *, context=None):
    context = context or getattr(bpy, "context", None)
    if rig is None or helper is None or context is None:
        return False
    try:
        view_layer = getattr(context, "view_layer", None)
        if view_layer is None or view_layer.objects.get(helper.name) is None:
            return False
        if getattr(context, "mode", "OBJECT") != "OBJECT":
            bpy.ops.object.mode_set(mode="OBJECT")
        for obj in tuple(getattr(context, "selected_objects", ()) or ()):
            try:
                obj.select_set(False)
            except FBP_DATA_ERRORS:
                pass
        helper.hide_viewport = False
        helper.hide_set(False)
        helper.select_set(True)
        view_layer.objects.active = helper
        fbp_focus_lattice_ui(context, rig)
        return True
    except FBP_DATA_ERRORS:
        return False


def _fbp_apply_lattice_effect(rig, *, select=False):
    """Create or repair a complete, editable Lattice setup transactionally."""
    issue = _fbp_lattice_compatibility_issue(rig)
    if issue:
        _fbp_set_lattice_error(rig, issue)
        return False
    plane = _fbp_plane(rig, repair=True)
    if plane is None:
        _fbp_set_lattice_error(rig, "The selected layer has no recoverable mesh plane")
        return False

    helper = _fbp_lattice_object(rig)
    modifier = _fbp_lattice_modifier(plane)
    detail_modifier = _fbp_lattice_detail_modifier(plane)
    # Never reuse a half-created pair from a previous failed attempt.
    if any(item is not None for item in (helper, modifier, detail_modifier)) and not _fbp_lattice_contract_is_valid(
        rig, plane, helper, modifier
    ):
        _fbp_cleanup_incomplete_lattice_setup(rig, force=True)
        helper = None
        modifier = None
        detail_modifier = None

    created_helper = False
    created_modifier = False
    data = None
    try:
        if helper is None:
            data = bpy.data.lattices.new(f"FBP Lattice • {rig.name}")
            helper = bpy.data.objects.new(f"FBP Lattice • {rig.name}", data)
            created_helper = True
            # Claim ownership before linking so rollback can still find and
            # remove the object when collection linking itself fails.
            helper[_FBP_LATTICE_OWNER_KEY] = str(rig.name)
            helper[_FBP_LATTICE_EFFECT_KEY] = FBP_EFFECT_LATTICE
            helper[_FBP_LATTICE_SCHEMA_KEY] = _FBP_LATTICE_SCHEMA_VERSION
            helper[_FBP_LATTICE_MODE_KEY] = _fbp_lattice_mode(rig)
            helper[_FBP_LATTICE_BAKED_KEY] = False
            rig.fbp_lattice_object = helper
            if not _fbp_ensure_lattice_link(helper, rig, plane, getattr(bpy, "context", None)):
                raise RuntimeError(_fbp_last_lattice_error(rig) or "No writable Scene collection is available")
            helper.hide_render = True
            helper.display_type = "WIRE"
            helper.show_in_front = True
            helper.parent = rig
            helper.matrix_world = _fbp_lattice_fit_matrix(plane)
        else:
            if not _fbp_ensure_lattice_link(helper, rig, plane, getattr(bpy, "context", None)):
                raise RuntimeError(_fbp_last_lattice_error(rig) or "Could not relink the existing cage")

        helper_data = getattr(helper, "data", None)
        if helper_data is None:
            raise RuntimeError("The Lattice cage has no datablock")
        if int(getattr(helper_data, "users", 1) or 1) > 1:
            helper.data = helper_data.copy()
            helper_data = helper.data
        resolution_changed = _fbp_update_lattice_data(rig, helper)
        if created_helper or resolution_changed:
            helper.matrix_world = _fbp_lattice_fit_matrix(plane)
            if created_helper and not _fbp_reset_lattice_points(helper):
                raise RuntimeError("Could not initialize the Lattice control points")
            _fbp_stabilize_lattice_helper(helper)

        helper[_FBP_LATTICE_OWNER_KEY] = str(rig.name)
        helper[_FBP_LATTICE_EFFECT_KEY] = FBP_EFFECT_LATTICE
        helper[_FBP_LATTICE_SCHEMA_KEY] = _FBP_LATTICE_SCHEMA_VERSION
        helper[_FBP_LATTICE_MODE_KEY] = _fbp_lattice_mode(rig)
        try:
            from .ownership import tag_lattice_helper_contract
            tag_lattice_helper_contract(helper, rig)
        except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
            pass
        _fbp_stabilize_lattice_helper(helper)
        if _fbp_lattice_mode(rig) == "CAMERA_FLATTEN" and bool(getattr(rig, "fbp_lattice_live_update", True)):
            helper[_FBP_LATTICE_BAKED_KEY] = False

        modifier = _fbp_lattice_modifier(plane)
        if modifier is None:
            modifier = plane.modifiers.new(_FBP_LATTICE_MODIFIER_NAME, "LATTICE")
            created_modifier = True
        modifier.object = helper
        _fbp_store_modifier_reference(plane, _FBP_LATTICE_MODIFIER_REF_KEY, modifier)

        # Mesh detail improves deformation but is not allowed to invalidate an
        # otherwise functional cage. A failed Subdivision modifier can be
        # repaired later without blocking the Lattice itself.
        try:
            detail_modifier = _fbp_sync_lattice_detail_modifier(rig, plane, modifier)
        except FBP_DATA_ERRORS as exc:
            detail_modifier = None
            fbp_warn("Could not update optional Lattice mesh detail", exc)

        if not _fbp_lattice_contract_is_valid(rig, plane, helper, modifier):
            raise RuntimeError("Blender did not accept the Lattice modifier binding")

        _fbp_configure_lattice_visibility(
            rig, plane, helper, modifier, detail_modifier, context=getattr(bpy, "context", None)
        )
        if _fbp_lattice_mode(rig) == "CAMERA_FLATTEN":
            _fbp_apply_lattice_camera_flatten(
                rig,
                scene=getattr(getattr(bpy, "context", None), "scene", None),
                force=bool(created_helper or created_modifier or resolution_changed),
            )
        elif _fbp_lattice_mode(rig) == "CORNER_PIN":
            _fbp_stabilize_lattice_helper(helper)
            _fbp_apply_lattice_corner_pin(
                rig, force=bool(created_helper or created_modifier or resolution_changed)
            )
        else:
            _fbp_stabilize_lattice_helper(helper)

        try:
            # The cage may have moved or changed resolution: keep pins bound.
            from .lattice_pins import sync_after_cage_change
            sync_after_cage_change(rig, helper, plane)
        except (ImportError,) + FBP_DATA_ERRORS as exc:
            fbp_warn("Could not rebind the Lattice pins", exc)

        if select:
            _fbp_select_lattice_helper(rig, helper, context=getattr(bpy, "context", None))
        _fbp_invalidate_live_lattice_cache()
        repair_key = _fbp_lattice_error_key(rig)
        _FBP_LATTICE_REPAIR_ATTEMPTED.pop(repair_key, None)
        _FBP_LATTICE_REPAIR_PENDING.discard(repair_key)
        _fbp_clear_lattice_error(rig)
        return True
    except Exception as exc:
        # This is the transaction boundary for Blender RNA calls. Keep the exact
        # reason for the UI and always remove generated partial state.
        _fbp_set_lattice_error(rig, "Lattice setup failed", exc)
        if created_helper or created_modifier or not _fbp_lattice_contract_is_valid(rig, plane, helper, modifier):
            _fbp_cleanup_incomplete_lattice_setup(rig, force=True)
        else:
            _fbp_configure_lattice_visibility(
                rig, plane, helper, modifier, detail_modifier, context=getattr(bpy, "context", None)
            )
        try:
            if data is not None and data.users == 0:
                bpy.data.lattices.remove(data)
        except FBP_DATA_ERRORS:
            pass
        return False

def _fbp_lattice_repair_signature(rig):
    """Cheap signature used to attempt automatic repair once per broken state."""
    plane = _fbp_plane(rig, repair=False)
    modifier = _fbp_lattice_modifier(plane)
    try:
        helper_pointer = getattr(rig, "fbp_lattice_object", None)
        helper_name = str(getattr(helper_pointer, "name", "") or "")
    except FBP_DATA_ERRORS:
        helper_name = ""
    try:
        stored_name = str(rig.get(_FBP_LATTICE_HELPER_NAME_KEY, "") or "")
    except FBP_DATA_ERRORS:
        stored_name = ""
    try:
        bound_name = str(getattr(getattr(modifier, "object", None), "name", "") or "")
    except FBP_DATA_ERRORS:
        bound_name = ""
    try:
        object_count = len(bpy.data.objects)
    except FBP_DATA_ERRORS:
        object_count = -1
    return (
        object_count,
        str(getattr(plane, "name", "") or ""),
        str(getattr(modifier, "name", "") or ""),
        helper_name,
        stored_name,
        bound_name,
    )


def _fbp_schedule_lattice_contract_repair(rig, *, first_interval=0.02):
    """Queue one non-recursive repair for an active incomplete Lattice."""
    if rig is None or fbp_render_mutation_blocked():
        return False
    try:
        active = bool(
            _fbp_is_enabled(rig, FBP_EFFECT_LATTICE)
            or getattr(rig, "fbp_lattice_object", None)
            or _fbp_lattice_modifier(_fbp_plane(rig, repair=False))
        )
    except FBP_DATA_ERRORS:
        active = False
    if not active:
        return False
    plane = _fbp_plane(rig, repair=False)
    helper = _fbp_lattice_object(rig)
    modifier = _fbp_lattice_modifier(plane)
    if _fbp_lattice_contract_is_valid(rig, plane, helper, modifier):
        return False

    key = _fbp_lattice_error_key(rig)
    signature = _fbp_lattice_repair_signature(rig)
    if key in _FBP_LATTICE_REPAIR_PENDING:
        return True
    if _FBP_LATTICE_REPAIR_ATTEMPTED.get(key) == signature:
        return False
    _FBP_LATTICE_REPAIR_PENDING.add(key)
    _FBP_LATTICE_REPAIR_ATTEMPTED[key] = signature
    rig_key = _fbp_lattice_runtime_key(rig)
    rig_name = str(getattr(rig, "name", "") or "")

    def _run():
        _FBP_LATTICE_REPAIR_PENDING.discard(key)
        active_rig = fbp_find_id_by_runtime_key(bpy.data.objects, rig_key, rig_name)
        if active_rig is None or fbp_render_mutation_blocked():
            return None
        try:
            _fbp_set_enabled(active_rig, FBP_EFFECT_LATTICE, True)
            if _fbp_apply_lattice_effect(active_rig, select=False):
                _FBP_LATTICE_REPAIR_ATTEMPTED.pop(key, None)
        except FBP_DATA_ERRORS:
            pass
        return None

    try:
        from .safe_tasks import schedule_once
        if schedule_once(
            f"lattice.contract_repair.{rig_key or rig_name}",
            _run,
            first_interval=max(0.0, float(first_interval)),
        ):
            return True
        # An equivalent safe task may already exist after module reload.
        return True
    except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
        _FBP_LATTICE_REPAIR_PENDING.discard(key)
        _run()
        return _fbp_lattice_contract_is_valid(rig)


def fbp_repair_existing_lattice_contracts():
    """Repair enabled/owned Lattice effects once after register or file load."""
    repaired = 0
    seen = set()
    try:
        from .layers import iter_scene_fbp_rigs
    except (ImportError, AttributeError):
        iter_scene_fbp_rigs = None
    for scene in tuple(getattr(bpy.data, "scenes", ()) or ()):
        rigs = iter_scene_fbp_rigs(scene, fallback=True) if iter_scene_fbp_rigs else ()
        for rig in rigs:
            try:
                key = fbp_obj_runtime_key(rig)
                if key is None or key in seen or not bool(getattr(rig, "is_fbp_control", False)):
                    continue
                seen.add(key)
                plane = _fbp_plane(rig, repair=False)
                modifier = _fbp_lattice_modifier(plane)
                active = bool(
                    _fbp_is_enabled(rig, FBP_EFFECT_LATTICE)
                    or getattr(rig, "fbp_lattice_object", None)
                    or modifier
                )
                if not active:
                    continue
                helper = _fbp_lattice_object(rig)
                if _fbp_lattice_contract_is_valid(rig, plane, helper, modifier):
                    _fbp_stabilize_lattice_helper(helper)
                    continue
                _fbp_set_enabled(rig, FBP_EFFECT_LATTICE, True)
                repaired += int(_fbp_apply_lattice_effect(rig, select=False))
            except FBP_DATA_ERRORS:
                continue
    return repaired


def _fbp_remove_lattice_effect(rig):
    # Deleting the active cage datablock while Blender is in Lattice Edit Mode
    # is unreliable. Return to Object Mode first, then remove only the generated
    # helper and modifiers and finally restore the layer rig selection.
    helper = _fbp_lattice_object(rig)
    context = getattr(bpy, "context", None)
    try:
        if (
            helper is not None
            and context is not None
            and getattr(context, "active_object", None) is helper
            and str(getattr(context, "mode", "OBJECT") or "OBJECT") != "OBJECT"
        ):
            bpy.ops.object.mode_set(mode="OBJECT")
    except FBP_DATA_ERRORS:
        pass
    cache_key = _fbp_lattice_runtime_key(rig)
    if cache_key is not None:
        _FBP_LATTICE_FLATTEN_CACHE.pop(cache_key, None)
    changed = _fbp_cleanup_incomplete_lattice_setup(rig, force=True)
    try:
        if context is not None and rig is not None:
            for obj in tuple(getattr(context, "selected_objects", ()) or ()):
                obj.select_set(False)
            rig.hide_set(False)
            rig.select_set(True)
            context.view_layer.objects.active = rig
    except FBP_DATA_ERRORS:
        pass
    _fbp_invalidate_live_lattice_cache()
    _fbp_clear_lattice_error(rig)
    return changed


def fbp_lattice_contract_report(rig, *, repair=False):
    """Return lightweight release-audit data for one active Lattice effect."""
    result = {
        "active": False,
        "valid": True,
        "repaired": 0,
        "issues": [],
        "warnings": [],
    }
    if rig is None:
        return result
    try:
        plane_hint = _fbp_plane(rig, repair=False)
        result["active"] = bool(
            _fbp_is_enabled(rig, FBP_EFFECT_LATTICE)
            or _fbp_lattice_object(rig)
            or _fbp_lattice_modifier(plane_hint)
        )
    except FBP_DATA_ERRORS:
        return result
    if not result["active"]:
        return result

    issue = _fbp_lattice_compatibility_issue(rig)
    if issue:
        result["valid"] = False
        result["issues"].append(issue)
        return result

    plane = _fbp_plane(rig, repair=bool(repair))
    helper = _fbp_lattice_object(rig)
    modifier = _fbp_lattice_modifier(plane)
    if repair and not _fbp_lattice_contract_is_valid(rig, plane, helper, modifier):
        if _fbp_apply_lattice_effect(rig, select=False):
            result["repaired"] += 1
            plane = _fbp_plane(rig, repair=False)
            helper = _fbp_lattice_object(rig)
            modifier = _fbp_lattice_modifier(plane)

    if not _fbp_lattice_contract_is_valid(rig, plane, helper, modifier):
        result["valid"] = False
        result["issues"].append("Lattice cage or modifier binding is incomplete")
        return result

    if repair:
        try:
            if getattr(helper, "parent", None) is not rig:
                world_matrix = helper.matrix_world.copy()
                helper.parent = rig
                helper.matrix_world = world_matrix
                result["repaired"] += 1
            owner_name = str(getattr(rig, "name", "") or "")
            if str(helper.get(_FBP_LATTICE_OWNER_KEY, "") or "") != owner_name:
                helper[_FBP_LATTICE_OWNER_KEY] = owner_name
                result["repaired"] += 1
            helper_data = getattr(helper, "data", None)
            if helper_data is not None and int(getattr(helper_data, "points_w", 0) or 0) != 1:
                if _fbp_apply_lattice_effect(rig, select=False):
                    helper = _fbp_lattice_object(rig)
                    modifier = _fbp_lattice_modifier(plane)
                    result["repaired"] += 1
            if _fbp_stabilize_lattice_helper(helper):
                result["repaired"] += 1
            previous_detail = _fbp_lattice_detail_modifier(plane)
            synced_detail = _fbp_sync_lattice_detail_modifier(rig, plane, modifier)
            if previous_detail is not synced_detail:
                result["repaired"] += 1
            _fbp_configure_lattice_visibility(
                rig, plane, helper, modifier, synced_detail,
                context=getattr(bpy, "context", None),
            )
        except FBP_DATA_ERRORS as exc:
            result["warnings"].append(f"Lattice safe repair was incomplete: {exc}")

    try:
        if getattr(helper, "parent", None) is not rig:
            result["warnings"].append("Lattice cage is not parented to the layer rig")
        if str(helper.get(_FBP_LATTICE_OWNER_KEY, "") or "") != str(getattr(rig, "name", "") or ""):
            result["warnings"].append("Lattice cage owner metadata is stale")
        if tuple(bool(value) for value in getattr(helper, "lock_location", ())) != (True, True, True):
            result["warnings"].append("Lattice Object Mode location is not locked")
        if tuple(bool(value) for value in getattr(helper, "lock_rotation", ())) != (True, True, True):
            result["warnings"].append("Lattice Object Mode rotation is not locked")
        if tuple(bool(value) for value in getattr(helper, "lock_scale", ())) != (True, True, True):
            result["warnings"].append("Lattice Object Mode scale is not locked")
        helper_data = getattr(helper, "data", None)
        if helper_data is not None and int(getattr(helper_data, "points_w", 0) or 0) != 1:
            result["issues"].append("Lattice cage still uses overlapping depth layers instead of the planar contract")
        detail = _fbp_lattice_detail_modifier(plane)
        if detail is not None:
            modifiers = tuple(getattr(plane, "modifiers", ()) or ())
            if modifiers.index(detail) > modifiers.index(modifier):
                result["issues"].append("Lattice mesh detail modifier is evaluated after the Lattice")
    except (AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
        result["warnings"].append("Lattice metadata could not be fully inspected")

    result["valid"] = not bool(result["issues"])
    return result


def _fbp_invalidate_live_lattice_cache():
    _FBP_LATTICE_LIVE_SCENE_CACHE.clear()


def _fbp_live_lattice_rigs(scene):
    """Return live Camera Flatten rigs through a persistent Scene index.

    The old 0.75-second expiry repeatedly rescanned every object even when a
    project contained only Freeform cages. Effect callbacks, object-count
    changes, load and undo already provide deterministic invalidation, so an
    empty result can safely remain cached and makes Freeform cost zero at idle.
    """
    if scene is None:
        return ()
    try:
        scene_key = fbp_obj_runtime_key(scene)
        object_count = len(scene.objects)
    except FBP_DATA_ERRORS:
        scene_key = 0
        object_count = -1
    cached = _FBP_LATTICE_LIVE_SCENE_CACHE.get(scene_key) if scene_key else None
    if cached is not None and int(cached.get("object_count", -2)) == object_count:
        try:
            resolved = tuple(
                scene.objects.get(name)
                for name in tuple(cached.get("rig_names", ()) or ())
            )
            if all(rig is not None for rig in resolved):
                return resolved
        except FBP_DATA_ERRORS:
            pass

    result = []
    try:
        objects = tuple(getattr(scene, "objects", ()) or ())
    except FBP_DATA_ERRORS:
        objects = ()
    for rig in objects:
        try:
            if not bool(getattr(rig, "is_fbp_control", False)):
                continue
            if not _fbp_lattice_live_enabled(rig):
                continue
            result.append(rig)
        except FBP_DATA_ERRORS:
            continue
    result = tuple(result)
    if scene_key:
        if len(_FBP_LATTICE_LIVE_SCENE_CACHE) >= 64 and scene_key not in _FBP_LATTICE_LIVE_SCENE_CACHE:
            _FBP_LATTICE_LIVE_SCENE_CACHE.clear()
        _FBP_LATTICE_LIVE_SCENE_CACHE[scene_key] = {
            "object_count": object_count,
            "rig_names": tuple(str(getattr(rig, "name", "") or "") for rig in result),
        }
    return result


def fbp_update_live_lattices(scene=None, *, force=False):
    """Update only live Camera Flatten cages.

    Freeform cages are fully native and require no Python transform polling.
    This prevents recursive depsgraph writes while reducing idle scene scans.
    """
    scene = scene or getattr(bpy.context, "scene", None)
    if scene is None or fbp_undo_guard_active():
        return 0
    updated = 0
    for rig in _fbp_live_lattice_rigs(scene):
        try:
            if not _fbp_lattice_live_enabled(rig):
                continue
            helper = _fbp_lattice_object(rig)
            if helper is None:
                if not _fbp_apply_lattice_effect(rig, select=False):
                    continue
                helper = _fbp_lattice_object(rig)
            updated += int(_fbp_apply_lattice_live(rig, scene=scene, force=force))
        except FBP_DATA_ERRORS:
            continue
    return updated


def schedule_live_lattice_updates(scene=None, *, force=False):
    """Defer live Camera Flatten writes outside depsgraph callbacks."""
    scene = scene or getattr(bpy.context, "scene", None)
    if scene is None:
        return False
    if not force and not _fbp_live_lattice_rigs(scene):
        return False
    scene_key = fbp_obj_runtime_key(scene)
    if scene_key is None:
        return False
    pending_key = (scene_key, bool(force))
    _FBP_LATTICE_LAST_ACTIVITY[scene_key] = time.monotonic()
    if pending_key in _FBP_LATTICE_UPDATE_PENDING:
        return False
    _FBP_LATTICE_UPDATE_PENDING.add(pending_key)

    def _run():
        # Debounce layer/camera motion before recalculating Camera Flatten.
        # Freeform point editing never enters this timer.
        elapsed = time.monotonic() - float(_FBP_LATTICE_LAST_ACTIVITY.get(scene_key, 0.0) or 0.0)
        if elapsed < 0.12:
            return max(0.02, 0.12 - elapsed)
        _FBP_LATTICE_UPDATE_PENDING.discard(pending_key)
        _FBP_LATTICE_LAST_ACTIVITY.pop(scene_key, None)
        active_scene = fbp_find_id_by_runtime_key(
            getattr(bpy.data, "scenes", ()), scene_key
        )
        if active_scene is not None:
            fbp_update_live_lattices(active_scene, force=force)
        return None

    try:
        from .safe_tasks import schedule_once
        return bool(schedule_once(
            f"lattice.update.{scene_key}.{int(bool(force))}",
            _run,
            first_interval=0.12,
        ))
    except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
        _FBP_LATTICE_UPDATE_PENDING.discard(pending_key)
        _FBP_LATTICE_LAST_ACTIVITY.pop(scene_key, None)
        return False


def update_lattice_effect_cb(rig, context=None):
    """Debounce structural Lattice updates triggered by slider drags.

    A single drag can emit many RNA updates. Rebuilding topology and subdivision
    for every sample made the sidebar feel sticky and could reset a cage several
    times before the mouse was released.
    """
    if fbp_is_silent_property_update(rig):
        return None
    if fbp_render_mutation_blocked() or not rig:
        return None
    try:
        enabled = _fbp_is_enabled(rig, FBP_EFFECT_LATTICE)
    except FBP_DATA_ERRORS:
        enabled = False
    if not enabled:
        return None

    _fbp_invalidate_live_lattice_cache()
    _FBP_LATTICE_REPAIR_ATTEMPTED.pop(_fbp_lattice_error_key(rig), None)
    rig_key = _fbp_lattice_runtime_key(rig)
    rig_name = str(getattr(rig, "name", "") or "")

    def _run():
        active_rig = fbp_find_id_by_runtime_key(bpy.data.objects, rig_key, rig_name)
        if active_rig is None or not _fbp_is_enabled(active_rig, FBP_EFFECT_LATTICE):
            return None
        # The transactional apply path already performs one forced Camera
        # Flatten when topology changed. Do not calculate the same cage twice.
        _fbp_apply_lattice_effect(active_rig, select=False)
        return None

    try:
        from .safe_tasks import schedule_once
        if schedule_once(
            f"lattice.property.{rig_key or rig_name}",
            _run,
            first_interval=0.06,
        ):
            return None
    except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
        pass
    if not fbp_undo_guard_active() and not fbp_render_mutation_blocked():
        _run()
    return None


def update_lattice_grid_preset_cb(rig, context=None):
    """Apply a named planar-grid preset without counting the corner points."""
    if fbp_is_silent_property_update(rig) or not rig:
        return None
    _fbp_apply_lattice_grid_settings(rig)
    return update_lattice_effect_cb(rig, context)


def update_lattice_custom_loops_cb(rig, context=None, axis="U"):
    """Synchronize linked custom loop counts and rebuild the planar cage once."""
    if fbp_is_silent_property_update(rig) or not rig:
        return None
    try:
        if bool(getattr(rig, "fbp_lattice_link_loops", True)):
            source_name = "fbp_lattice_custom_loops_v" if str(axis).upper() == "V" else "fbp_lattice_custom_loops_u"
            target_name = "fbp_lattice_custom_loops_u" if str(axis).upper() == "V" else "fbp_lattice_custom_loops_v"
            value = max(0, min(62, int(getattr(rig, source_name, 6) or 0)))
            if int(getattr(rig, target_name, value) or 0) != value:
                fbp_set_rna_property_silent(rig, target_name, value)
    except FBP_DATA_ERRORS:
        pass
    try:
        preset = str(getattr(rig, "fbp_lattice_grid_preset", "LOOPS_2") or "LOOPS_2").upper()
    except FBP_DATA_ERRORS:
        preset = "LOOPS_2"
    if preset != "CUSTOM":
        return None
    _fbp_apply_lattice_grid_settings(rig)
    return update_lattice_effect_cb(rig, context)


def update_lattice_loop_link_cb(rig, context=None):
    """When the chain is enabled, immediately make both custom axes equal."""
    if fbp_is_silent_property_update(rig) or not rig:
        return None
    try:
        linked = bool(getattr(rig, "fbp_lattice_link_loops", True))
    except FBP_DATA_ERRORS:
        linked = True
    if linked:
        try:
            value = max(0, min(62, int(getattr(rig, "fbp_lattice_custom_loops_u", 6) or 0)))
            fbp_set_rna_property_silent(rig, "fbp_lattice_custom_loops_v", value)
        except FBP_DATA_ERRORS:
            pass
    try:
        custom = str(getattr(rig, "fbp_lattice_grid_preset", "LOOPS_2") or "LOOPS_2").upper() == "CUSTOM"
    except FBP_DATA_ERRORS:
        custom = False
    if custom:
        _fbp_apply_lattice_grid_settings(rig)
        return update_lattice_effect_cb(rig, context)
    return None


def update_lattice_mesh_detail_cb(rig, context=None):
    """Debounce only the optional Simple Subdivision modifier.

    Mesh density changes do not touch cage topology or control points, so they
    must not run the complete Lattice transaction.
    """
    if fbp_is_silent_property_update(rig) or fbp_render_mutation_blocked() or not rig:
        return None
    try:
        if not _fbp_is_enabled(rig, FBP_EFFECT_LATTICE):
            return None
    except FBP_DATA_ERRORS:
        return None
    rig_key = _fbp_lattice_runtime_key(rig)
    rig_name = str(getattr(rig, "name", "") or "")

    def _run():
        active_rig = fbp_find_id_by_runtime_key(bpy.data.objects, rig_key, rig_name)
        if active_rig is None or not _fbp_is_enabled(active_rig, FBP_EFFECT_LATTICE):
            return None
        plane = _fbp_plane(active_rig, repair=False)
        helper = _fbp_lattice_object(active_rig)
        modifier = _fbp_lattice_modifier(plane)
        if not _fbp_lattice_contract_is_valid(active_rig, plane, helper, modifier):
            _fbp_apply_lattice_effect(active_rig, select=False)
            return None
        detail = _fbp_sync_lattice_detail_modifier(active_rig, plane, modifier)
        _fbp_configure_lattice_visibility(
            active_rig, plane, helper, modifier, detail, context=getattr(bpy, "context", None)
        )
        return None

    try:
        from .safe_tasks import schedule_once
        schedule_once(
            f"lattice.mesh_detail.{rig_key or rig_name}",
            _run,
            first_interval=0.04,
        )
    except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
        _run()
    return None


def update_lattice_camera_settings_cb(rig, context=None):
    """Update mode/live/influence without rebuilding cage or mesh detail."""
    if fbp_is_silent_property_update(rig) or fbp_render_mutation_blocked() or not rig:
        return None
    try:
        if not _fbp_is_enabled(rig, FBP_EFFECT_LATTICE):
            return None
    except FBP_DATA_ERRORS:
        return None
    _fbp_invalidate_live_lattice_cache()
    rig_key = _fbp_lattice_runtime_key(rig)
    rig_name = str(getattr(rig, "name", "") or "")
    scene_name = str(getattr(getattr(context, "scene", None), "name", "") or "") if context else ""

    def _run():
        active_rig = fbp_find_id_by_runtime_key(bpy.data.objects, rig_key, rig_name)
        if active_rig is None or not _fbp_is_enabled(active_rig, FBP_EFFECT_LATTICE):
            return None
        plane = _fbp_plane(active_rig, repair=False)
        helper = _fbp_lattice_object(active_rig)
        modifier = _fbp_lattice_modifier(plane)
        if not _fbp_lattice_contract_is_valid(active_rig, plane, helper, modifier):
            _fbp_apply_lattice_effect(active_rig, select=False)
            return None
        mode = _fbp_lattice_mode(active_rig)
        try:
            helper[_FBP_LATTICE_MODE_KEY] = mode
        except FBP_DATA_ERRORS:
            pass
        if mode != "CORNER_PIN":
            # Leaving Corner Pin keeps the current shape and drops its handles.
            try:
                from .lattice_corner_pin import remove_handles
                remove_handles(active_rig, helper)
            except (ImportError,) + FBP_DATA_ERRORS:
                pass
        if mode == "CAMERA_FLATTEN":
            scenes = getattr(bpy.data, "scenes", None)
            scene = scenes.get(scene_name) if scene_name and scenes is not None else getattr(bpy.context, "scene", None)
            _fbp_apply_lattice_camera_flatten(active_rig, scene=scene, force=True)
        elif mode == "CORNER_PIN":
            _fbp_update_lattice_data(active_rig, helper)
            _fbp_apply_lattice_corner_pin(active_rig, force=True)
        else:
            cache_key = _fbp_lattice_runtime_key(active_rig)
            if cache_key is not None:
                _FBP_LATTICE_FLATTEN_CACHE.pop(cache_key, None)
            _fbp_stabilize_lattice_helper(helper)
        return None

    try:
        from .safe_tasks import schedule_once
        schedule_once(
            f"lattice.camera_settings.{rig_key or rig_name}",
            _run,
            first_interval=0.04,
        )
    except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
        _run()
    return None


def update_lattice_visibility_cb(rig, context=None):
    """Apply cage visibility immediately without rebuilding its topology."""
    if fbp_is_silent_property_update(rig) or not rig:
        return None
    plane = _fbp_plane(rig, repair=False)
    helper = _fbp_lattice_object(rig)
    modifier = _fbp_lattice_modifier(plane)
    if helper is not None and modifier is not None:
        _fbp_configure_lattice_visibility(
            rig,
            plane,
            helper,
            modifier,
            _fbp_lattice_detail_modifier(plane),
            context=context,
        )
    return None


def update_lattice_pins_cb(rig, context=None):
    """Rebuild puppet pin weights after a pin setting changed."""
    if fbp_is_silent_property_update(rig) or not rig:
        return None
    helper = _fbp_lattice_object(rig)
    plane = _fbp_plane(rig, repair=False)
    if helper is None or plane is None:
        return None
    try:
        from .lattice_pins import bind
        bind(rig, helper, plane, force=True)
    except (ImportError,) + FBP_DATA_ERRORS as exc:
        fbp_warn("Could not rebind the Lattice pins", exc)
    return None


def update_lattice_handle_size_cb(rig, context=None):
    """Resize the layer's handles; their shapes and transforms are untouched."""
    if fbp_is_silent_property_update(rig) or not rig:
        return None
    try:
        from .lattice_bones import restyle_handles
        restyle_handles(rig, _fbp_plane(rig, repair=False))
    except (ImportError,) + FBP_DATA_ERRORS as exc:
        fbp_warn("Could not resize the Lattice handles", exc)
    return None


def update_lattice_pin_stiffness_cb(pin, context=None):
    """Rebuild the weights of a pin's layer after its Stiff Area changed."""
    try:
        from .lattice_pins import pin_owner
        rig = pin_owner(pin)
    except (ImportError,) + FBP_DATA_ERRORS:
        rig = None
    if rig is not None:
        update_lattice_pins_cb(rig, context)
        # The pin's dashed circle shows its Stiff Area.
        update_lattice_handle_size_cb(rig, context)
    return None


def update_lattice_interpolation_cb(rig, context=None):
    """Update interpolation without rebuilding modifiers or resetting points."""
    if fbp_is_silent_property_update(rig) or not rig:
        return None
    try:
        if not _fbp_is_enabled(rig, FBP_EFFECT_LATTICE):
            return None
    except FBP_DATA_ERRORS:
        return None
    helper = _fbp_lattice_object(rig)
    if helper is None:
        # A missing cage still needs the normal transactional setup path.
        _fbp_apply_lattice_effect(rig, select=False)
        return None
    _fbp_update_lattice_data(rig, helper)
    try:
        helper.data.update_tag()
        helper.update_tag(refresh={'DATA'})
    except FBP_DATA_ERRORS:
        pass
    return None


def _fbp_node_group_cache_key(node_group):
    """Return a Blender 5.2 session-identity key for a node group."""
    if node_group is None:
        return None
    try:
        return (
            fbp_obj_runtime_key(node_group),
            str(getattr(node_group, "name_full", getattr(node_group, "name", "")) or ""),
        )
    except FBP_DATA_ERRORS:
        return None


def _fbp_interface_inputs(node_group):
    """Return ``display name -> identifier`` descriptors for GN inputs.

    Blender RNA wrappers become invalid when Undo or file loading replaces Main.
    Cache plain strings only; this preserves the O(1) modifier hot path without
    retaining references to NodeTreeInterfaceSocket objects across history.
    """
    interface = getattr(node_group, "interface", None) if node_group else None
    if not interface:
        return {}
    try:
        cache_key = _fbp_node_group_cache_key(node_group)
        if cache_key is None:
            return {}
        items = interface.items_tree
        signature = (len(items),)
        cached = _FBP_INTERFACE_INPUT_CACHE.get(cache_key)
        if (
            cached
            and cached[0] == signature
            and time.monotonic() - float(cached[1]) <= _FBP_INTERFACE_INPUT_CACHE_SECONDS
        ):
            return cached[2]
        result = {}
        ambiguous_names = set()
        for item in items:
            if (
                getattr(item, "item_type", "") != "SOCKET"
                or getattr(item, "in_out", "") != "INPUT"
            ):
                continue
            name = str(getattr(item, "name", "") or "")
            identifier = str(getattr(item, "identifier", "") or "")
            if not name or not identifier or name in ambiguous_names:
                continue
            previous = result.get(name)
            if previous is not None and previous != identifier:
                result.pop(name, None)
                ambiguous_names.add(name)
                continue
            result[name] = identifier
        if len(_FBP_INTERFACE_INPUT_CACHE) >= 512 and cache_key not in _FBP_INTERFACE_INPUT_CACHE:
            _FBP_INTERFACE_INPUT_CACHE.clear()
        _FBP_INTERFACE_INPUT_CACHE[cache_key] = (signature, time.monotonic(), result)
        return result
    except FBP_DATA_ERRORS:
        return {}


def _fbp_node_group_geometry_contract(node_group):
    """Return primitive geometry input/output availability for a live node group.

    This is intentionally not cached: the check runs only while an operator is
    applying a Generic Mesh effect, and retaining interface socket RNA wrappers
    across Undo, file-load or extension reload would be unsafe.
    """
    has_input = False
    has_output = False
    if node_group is None:
        return has_input, has_output
    try:
        for item in node_group.interface.items_tree:
            if getattr(item, "item_type", "") != "SOCKET":
                continue
            if str(getattr(item, "socket_type", "") or "") != "NodeSocketGeometry":
                continue
            direction = str(getattr(item, "in_out", "") or "")
            has_input = has_input or direction == "INPUT"
            has_output = has_output or direction == "OUTPUT"
            if has_input and has_output:
                break
    except FBP_DATA_ERRORS:
        return False, False
    return has_input, has_output


def _fbp_interface_input_identifier(node_group, socket_name):
    inputs = _fbp_interface_inputs(node_group)
    return str(_fbp_interface_socket_for_name(inputs, socket_name) or "")


def _fbp_interface_input(node_group, socket_name):
    """Resolve a live interface socket only for operations that need its RNA."""
    identifier = _fbp_interface_input_identifier(node_group, socket_name)
    if not identifier:
        return None
    try:
        for item in node_group.interface.items_tree:
            if (
                getattr(item, "item_type", "") == "SOCKET"
                and getattr(item, "in_out", "") == "INPUT"
                and str(getattr(item, "identifier", "") or "") == identifier
            ):
                return item
    except FBP_DATA_ERRORS:
        pass
    return None


def _fbp_node_socket(sockets, socket_name, fallback_index=None):
    # Blender nodes often expose several sockets with the same display name
    # (for example both Math operands are named ``Value``).  An explicit
    # index must therefore win over name lookup; otherwise ``sockets.get``
    # silently returns the first socket and later links replace each other.
    if fallback_index is not None:
        try:
            return sockets[fallback_index]
        except (AttributeError, IndexError, ReferenceError, RuntimeError, TypeError, ValueError):
            pass
    try:
        found = sockets.get(socket_name)
        if found is not None:
            return found
    except FBP_DATA_ERRORS:
        pass
    try:
        for item in sockets:
            if getattr(item, "name", "") == socket_name:
                return item
    except FBP_DATA_ERRORS:
        pass
    return None


def _fbp_effect_values_equal(current, value, tolerance=1e-6):
    """Compare socket values without dirtying Blender data for no-op writes."""
    if current is value:
        return True
    try:
        if isinstance(current, (int, float, bool)) and isinstance(value, (int, float, bool)):
            return abs(float(current) - float(value)) <= tolerance
    except (TypeError, ValueError, OverflowError):
        pass
    if not isinstance(current, (str, bytes)) and not isinstance(value, (str, bytes)):
        try:
            current_values = tuple(current)
            value_values = tuple(value)
            if len(current_values) == len(value_values):
                return all(
                    abs(float(a) - float(b)) <= tolerance
                    for a, b in zip(current_values, value_values, strict=True)
                )
        except (TypeError, ValueError, OverflowError):
            pass
    try:
        return bool(current == value)
    except FBP_DATA_ERRORS:
        return False


def _fbp_set_attr_if_changed(owner, attribute, value, *, tolerance=1e-6):
    """Assign one RNA property only when its effective value changed.

    Blender 5.2 material, node and modifier setters tag the owning ID for
    evaluation. Repeating an identical assignment can therefore restart Cycles
    synchronization even though the rendered result is unchanged.
    """
    if owner is None:
        return False
    try:
        if _fbp_effect_values_equal(getattr(owner, attribute), value, tolerance):
            return False
        setattr(owner, attribute, value)
        return True
    except FBP_DATA_ERRORS:
        return False


def _fbp_set_socket_default_if_changed(socket, value, *, tolerance=1e-6):
    if socket is None:
        return False
    return _fbp_set_attr_if_changed(
        socket, "default_value", value, tolerance=tolerance
    )


def _fbp_set_idprop_if_changed(owner, key, value, *, tolerance=1e-6):
    if owner is None:
        return False
    try:
        current = owner.get(key, None)
        if current is not None and _fbp_effect_values_equal(current, value, tolerance):
            return False
        owner[key] = value
        return True
    except FBP_DATA_ERRORS:
        return False


def _fbp_normalized_socket_label(value):
    try:
        return "".join(ch for ch in str(value or "").lower() if ch.isalnum())
    except (TypeError, ValueError):
        return ""


def _fbp_interface_socket_for_name(inputs, socket_name):
    """Resolve a Geometry Nodes modifier input socket with tolerant aliases.

    Bundled and user-saved node groups occasionally rename public sockets from
    labels like "Base Seed" to "Seed". Exact lookup remains the fast path,
    but this fallback prevents UI sliders from becoming visually dead after a
    node-group contract rename.
    """
    name = str(socket_name or "")
    if not inputs:
        return None
    exact = inputs.get(name)
    if exact is not None:
        return exact
    aliases = []
    stripped = name.strip()
    if stripped.lower().startswith("base "):
        aliases.append(stripped[5:].strip())
    elif stripped.lower() == "seed":
        # Saved 7.1 files may still expose the former Felt Fuzz label.
        aliases.append("Base Seed")
    if stripped.lower().endswith(" seed"):
        aliases.append("Seed")
    if stripped.lower() in {"base w", "animate w"}:
        aliases.append("W")
    for alias in aliases:
        found = inputs.get(alias)
        if found is not None:
            return found
    target_norms = [_fbp_normalized_socket_label(name)] + [
        _fbp_normalized_socket_label(alias) for alias in aliases
    ]
    normalized_matches = set()
    for item_name, item in inputs.items():
        item_norm = _fbp_normalized_socket_label(item_name)
        if item_norm and item_norm in target_norms:
            normalized_matches.add(item)
    return next(iter(normalized_matches)) if len(normalized_matches) == 1 else None


def _fbp_set_modifier_input(modifier, node_group, socket_name, value, interface_inputs=None):
    inputs = (
        interface_inputs
        if interface_inputs is not None
        else _fbp_interface_inputs(node_group)
    )
    identifier = str(_fbp_interface_socket_for_name(inputs, socket_name) or "")
    if not identifier:
        return False
    try:
        return _fbp_modifier_input_set(modifier, identifier, value)
    except FBP_DATA_ERRORS as exc:
        fbp_warn(f"Could not set effect input {socket_name}", exc)
        return False


def _fbp_modifier_input_handle(modifier, identifier):
    """Return the 5.2 dynamic RNA object for one GN interface input."""
    if not modifier or not identifier:
        return None
    try:
        inputs = getattr(getattr(modifier, "properties", None), "inputs", None)
        return getattr(inputs, str(identifier), None) if inputs is not None else None
    except FBP_DATA_ERRORS:
        return None


def _fbp_modifier_input_has(modifier, identifier):
    return _fbp_modifier_input_handle(modifier, identifier) is not None


def _fbp_modifier_input_is_visible(modifier, identifier):
    """Return visibility of a Blender 5.2 generated GN input when exposed.

    ``NodesModifier.is_input_visible`` is not part of Blender 5.2. The input
    itself is generated under ``modifier.properties.inputs``. Some generated
    PropertyGroup builds expose ``is_property_hidden``; otherwise presence is
    the only stable non-destructive signal.
    """
    handle = _fbp_modifier_input_handle(modifier, identifier)
    if handle is None:
        return False
    try:
        hidden = getattr(handle, "is_property_hidden", None)
        if callable(hidden):
            return not bool(hidden("value"))
    except FBP_DATA_ERRORS:
        pass
    return True


def _fbp_modifier_input_is_used(modifier, identifier):
    """Blender 5.2 has no public per-input ``is_input_used`` modifier method."""
    return _fbp_modifier_input_handle(modifier, identifier) is not None

def _fbp_modifier_input_get(modifier, identifier, default=None):
    handle = _fbp_modifier_input_handle(modifier, identifier)
    if handle is not None and hasattr(handle, "value"):
        try:
            return handle.value
        except FBP_DATA_ERRORS:
            return default
    return default


def fbp_modifier_input_get(modifier, identifier, default=None):
    """Public read-only bridge for diagnostics and extension integrations."""
    return _fbp_modifier_input_get(modifier, identifier, default)


def fbp_node_group_interface_52_issues(node_group):
    """Audit the RNA identifier contract introduced for node interfaces in 5.2."""
    if node_group is None:
        return ("Missing node group",)
    issues = []
    seen = set()
    input_labels = set()
    try:
        items = node_group.interface.items_tree
    except FBP_DATA_ERRORS:
        return ("Node-group interface is unavailable",)
    for item in items:
        try:
            if getattr(item, "item_type", "") != "SOCKET":
                continue
            identifier = str(getattr(item, "identifier", "") or "")
            label = str(getattr(item, "name", "") or "<unnamed>")
            if getattr(item, "in_out", "") == "INPUT":
                if label in input_labels:
                    issues.append(
                        f"Input label '{label}' is duplicated and cannot be resolved safely"
                    )
                input_labels.add(label)
            if not identifier:
                issues.append(f"Socket '{label}' has no RNA identifier")
                continue
            if not identifier.isascii() or not identifier.isidentifier():
                issues.append(f"Socket '{label}' has invalid RNA identifier '{identifier}'")
            if identifier in seen:
                issues.append(f"Socket identifier '{identifier}' is duplicated")
            seen.add(identifier)
        except FBP_DATA_ERRORS:
            continue
    return tuple(dict.fromkeys(issues))


def fbp_geometry_modifier_52_issues(modifier, effect_id=""):
    """Return non-destructive Blender 5.2 contract issues for one GN effect."""
    if modifier is None or getattr(modifier, "type", "") != "NODES":
        return ("Geometry Nodes modifier is missing",)
    node_group = getattr(modifier, "node_group", None)
    issues = list(fbp_node_group_interface_52_issues(node_group))
    try:
        dynamic_inputs = getattr(getattr(modifier, "properties", None), "inputs", None)
    except FBP_DATA_ERRORS:
        dynamic_inputs = None
    if dynamic_inputs is None:
        issues.append("Blender 5.2 generated modifier input RNA is unavailable")
        return tuple(dict.fromkeys(issues))
    definition = fbp_effect_definition(effect_id) if effect_id else {}
    descriptors = _fbp_interface_inputs(node_group)
    public_socket_names = tuple((definition.get("property_map", {}) or {}).values())
    duplicate_names = sorted({name for name in public_socket_names if public_socket_names.count(name) > 1})
    for socket_name in duplicate_names:
        issues.append(f"Public input label '{socket_name}' is mapped by multiple properties")
    for socket_name in public_socket_names:
        identifier = str(_fbp_interface_socket_for_name(descriptors, socket_name) or "")
        if not identifier:
            issues.append(f"Public input '{socket_name}' is missing from the node group")
            continue
        handle = _fbp_modifier_input_handle(modifier, identifier)
        if handle is None:
            issues.append(f"Generated RNA input '{identifier}' is unavailable")
            continue
        try:
            value = handle.value
        except FBP_DATA_ERRORS:
            issues.append(f"Generated RNA input '{identifier}' cannot be read")
            continue
        if isinstance(value, float) and not math.isfinite(value):
            issues.append(f"Generated RNA input '{identifier}' contains a non-finite value")
    return tuple(dict.fromkeys(issues))


def fbp_geometry_modifier_52_warnings(modifier):
    """Return Blender 5.2 Geometry Nodes evaluation messages.

    ``NodesModifier.node_warnings`` is runtime evaluation output, not a stable
    node-group contract. Keep it separate from :func:`fbp_geometry_modifier_52_issues`
    so Project Health can report the native severity without suggesting a
    destructive rebuild for informational messages.
    """
    if modifier is None or getattr(modifier, "type", "") != "NODES":
        return ()
    try:
        warnings = tuple(getattr(modifier, "node_warnings", ()) or ())
    except FBP_DATA_ERRORS:
        return ()
    result = []
    seen = set()
    for warning in warnings:
        try:
            message = str(getattr(warning, "message", "") or "").strip()
            warning_type = str(getattr(warning, "type", "WARNING") or "WARNING").upper()
        except FBP_DATA_ERRORS:
            continue
        if not message:
            continue
        item = (warning_type, message)
        if item in seen:
            continue
        seen.add(item)
        result.append(item)
    return tuple(result)


def _fbp_modifier_input_set(modifier, identifier, value):
    """Set one Geometry Nodes input through Blender 5.2 dynamic RNA."""
    handle = _fbp_modifier_input_handle(modifier, identifier)
    if handle is not None and hasattr(handle, "value"):
        current = handle.value
        if _fbp_effect_values_equal(current, value):
            return False
        handle.value = value
        try:
            _FBP_EFFECT_NATIVE_VISIBILITY_CACHE.clear()
        except NameError:
            pass
        return True
    return False


def _fbp_modifier_input_unset(modifier, identifier):
    """Blender 5.2 inputs are intrinsic RNA values and cannot be deleted."""
    del modifier, identifier
    return False





def _fbp_scene_camera(scene=None):
    scene = scene or getattr(bpy.context, "scene", None)
    camera = getattr(scene, "camera", None) if scene else None
    try:
        return camera if camera and getattr(camera, "type", "") == "CAMERA" else None
    except FBP_DATA_ERRORS:
        return None


_FBP_TRACK_TO_CAMERA_CONSTRAINT_NAME = "FBP • Track to Camera"


def _fbp_track_to_camera_constraint(rig):
    if not rig:
        return None
    try:
        for constraint in rig.constraints:
            if str(getattr(constraint, "name", "") or "") == _FBP_TRACK_TO_CAMERA_CONSTRAINT_NAME:
                return constraint
    except FBP_DATA_ERRORS:
        pass
    return None


def _fbp_remove_track_to_camera_constraint(rig):
    constraint = _fbp_track_to_camera_constraint(rig)
    if not constraint:
        return False
    try:
        rig.constraints.remove(constraint)
        return True
    except FBP_DATA_ERRORS:
        return False


def _fbp_apply_track_to_camera_constraint(rig, scene=None):
    """Track the complete rig, not only its generated plane geometry."""
    if not rig:
        return False
    camera = _fbp_scene_camera(scene)
    if not camera:
        return False
    mode = str(getattr(rig, "fbp_camera_billboard_mode", "FULL") or "FULL")
    constraint_type = "TRACK_TO" if mode == "FULL" else "LOCKED_TRACK"
    constraint = _fbp_track_to_camera_constraint(rig)
    if constraint is not None and str(getattr(constraint, "type", "") or "") != constraint_type:
        _fbp_remove_track_to_camera_constraint(rig)
        constraint = None
    created = constraint is None
    if constraint is None:
        try:
            constraint = rig.constraints.new(type=constraint_type)
            constraint.name = _FBP_TRACK_TO_CAMERA_CONSTRAINT_NAME
        except FBP_DATA_ERRORS as exc:
            fbp_warn("Could not create Track to Camera constraint", exc)
            return False
    changed = created
    try:
        if getattr(constraint, "target", None) != camera:
            constraint.target = camera
            changed = True
        track_axis = "TRACK_NEGATIVE_Z" if bool(getattr(rig, "fbp_camera_billboard_flip", False)) else "TRACK_Z"
        if str(getattr(constraint, "track_axis", "") or "") != track_axis:
            constraint.track_axis = track_axis
            changed = True
        if constraint_type == "TRACK_TO":
            if str(getattr(constraint, "up_axis", "") or "") != "UP_Y":
                constraint.up_axis = "UP_Y"
                changed = True
        else:
            lock_axis = "LOCK_Y" if mode == "HORIZONTAL" else "LOCK_X"
            if str(getattr(constraint, "lock_axis", "") or "") != lock_axis:
                constraint.lock_axis = lock_axis
                changed = True
        influence = max(0.0, min(1.0, float(getattr(rig, "fbp_camera_billboard_influence", 1.0) or 0.0)))
        if abs(float(getattr(constraint, "influence", 1.0) or 0.0) - influence) > 1e-6:
            constraint.influence = influence
            changed = True
    except FBP_DATA_ERRORS as exc:
        fbp_warn("Could not update Track to Camera constraint", exc)
        return False
    return changed


def fbp_update_track_to_camera(rig, scene=None):
    if not rig or not _fbp_is_enabled(rig, FBP_EFFECT_CAMERA_BILLBOARD):
        return False
    return _fbp_apply_track_to_camera_constraint(rig, scene)


def _fbp_camera_contract_values(camera, contract):
    """Return standardized active-camera values keyed by declared socket name."""
    values = {}
    object_socket = str(contract.get("object_socket", "Camera") or "Camera")
    if object_socket:
        values[object_socket] = camera
    data = getattr(camera, "data", None) if camera else None
    camera_type = str(getattr(data, "type", "PERSP") or "PERSP") if data else "PERSP"
    bindings = (
        ("lens_socket", float(getattr(data, "lens", 50.0) or 50.0) if data else 50.0),
        ("sensor_width_socket", float(getattr(data, "sensor_width", 36.0) or 36.0) if data else 36.0),
        ("ortho_scale_socket", float(getattr(data, "ortho_scale", 6.0) or 6.0) if data else 6.0),
        ("perspective_socket", 1.0 if camera is not None and camera_type == "PERSP" else 0.0),
        ("shift_x_socket", float(getattr(data, "shift_x", 0.0) or 0.0) if data else 0.0),
        ("shift_y_socket", float(getattr(data, "shift_y", 0.0) or 0.0) if data else 0.0),
    )
    for key, value in bindings:
        socket_name = str(contract.get(key, "") or "")
        if socket_name:
            values[socket_name] = value
    return values


def _fbp_camera_binding_signature(scene):
    camera = _fbp_scene_camera(scene)
    camera_key = fbp_obj_runtime_key(camera) if camera else 0
    data = getattr(camera, "data", None) if camera else None
    try:
        return (
            camera_key,
            str(getattr(data, "type", "") or ""),
            round(float(getattr(data, "lens", 0.0) or 0.0), 6),
            round(float(getattr(data, "sensor_width", 0.0) or 0.0), 6),
            round(float(getattr(data, "ortho_scale", 0.0) or 0.0), 6),
            round(float(getattr(data, "shift_x", 0.0) or 0.0), 6),
            round(float(getattr(data, "shift_y", 0.0) or 0.0), 6),
        )
    except FBP_DATA_ERRORS:
        return (camera_key,)


def _fbp_bind_geometry_camera_input(rig, effect_id, modifier, node_group=None, scene=None):
    """Bind standardized active-camera inputs without rebuilding the node group."""
    definition = fbp_effect_definition(effect_id)
    if not definition.get("camera_aware") or not modifier:
        return False
    contract = definition.get("camera_contract", {}) or {}
    node_group = node_group or getattr(modifier, "node_group", None)
    if not node_group:
        return False
    interface_inputs = _fbp_interface_inputs(node_group)
    camera = _fbp_scene_camera(scene)
    changed = False
    for socket_name, value in _fbp_camera_contract_values(camera, contract).items():
        changed = _fbp_set_modifier_input(
            modifier, node_group, socket_name, value, interface_inputs
        ) or changed
    return changed


def _fbp_scene_camera_cache_key(scene):
    """Return a Scene cache key that cannot alias a newly-created Scene."""
    try:
        identity = fbp_obj_runtime_key(scene)
        return (
            identity if identity is not None else 0,
            str(getattr(scene, "name_full", getattr(scene, "name", "")) or ""),
        )
    except FBP_DATA_ERRORS:
        return (0, "")


def _fbp_sync_scene_camera_bindings(scene, rigs):
    """Refresh declared projection values only when the active camera data changes.

    Camera-object transforms remain live through Geometry Nodes Object Info, so
    ordinary camera or layer movement does not require Python socket writes.
    """
    if scene is None:
        return False
    scene_key = _fbp_scene_camera_cache_key(scene)
    if not scene_key[0]:
        return False
    signature = _fbp_camera_binding_signature(scene)
    if _FBP_CAMERA_BINDING_CACHE.get(scene_key) == signature:
        return False
    changed = False
    for rig in rigs or ():
        try:
            if _fbp_is_enabled(rig, FBP_EFFECT_CAMERA_BILLBOARD):
                changed = _fbp_apply_track_to_camera_constraint(rig, scene) or changed
            for effect_id in _fbp_runtime_effect_ids(rig):
                definition = fbp_effect_definition(effect_id)
                if not definition.get("camera_aware"):
                    continue
                modifier = fbp_find_effect_modifier(rig, effect_id)
                if not modifier:
                    continue
                changed = _fbp_bind_geometry_camera_input(
                    rig, effect_id, modifier, scene=scene
                ) or changed
        except FBP_DATA_ERRORS:
            continue
    if len(_FBP_CAMERA_BINDING_CACHE) >= 64 and scene_key not in _FBP_CAMERA_BINDING_CACHE:
        _FBP_CAMERA_BINDING_CACHE.clear()
    _FBP_CAMERA_BINDING_CACHE[scene_key] = signature
    return changed


def fbp_sync_scene_camera_bindings(scene=None, *, force=False):
    """Safely refresh camera-aware effect sockets from timer or handler code."""
    scene = scene or getattr(bpy.context, "scene", None)
    if scene is None:
        return False
    scene_key = _fbp_scene_camera_cache_key(scene)
    if force:
        _FBP_CAMERA_BINDING_CACHE.pop(scene_key, None)
    try:
        from .layers import iter_scene_fbp_rigs
        rigs = iter_scene_fbp_rigs(scene)
    except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
        rigs = ()
    return _fbp_sync_scene_camera_bindings(scene, rigs)


def fbp_camera_distance_for_rig(rig, scene=None):
    """Return positive camera-space depth from the active camera to one FBP plane."""
    camera = _fbp_scene_camera(scene)
    target = _fbp_plane(rig) or rig
    if not camera or not target:
        return 0.0
    try:
        camera_location = camera.matrix_world.translation
        target_location = target.matrix_world.translation
        camera_forward = camera.matrix_world.to_quaternion() @ Vector((0.0, 0.0, -1.0))
        depth = (target_location - camera_location).dot(camera_forward)
        return max(0.0001, float(depth))
    except FBP_DATA_ERRORS:
        return 0.0


def _fbp_set_enabled(rig, effect_id, enabled):
    definition = fbp_effect_definition(effect_id)
    key = str(definition.get("enabled_key", "") or "")
    if not rig or not key:
        return False
    enabled = bool(enabled)
    try:
        if key in rig and bool(rig.get(key, False)) == enabled:
            return False
        rig[key] = enabled
        return True
    except FBP_DATA_ERRORS:
        return False


def _fbp_is_enabled(rig, effect_id):
    definition = fbp_effect_definition(effect_id)
    key = str(definition.get("enabled_key", "") or "")
    try:
        return bool(rig and key and rig.get(key, False))
    except FBP_DATA_ERRORS:
        return False


def _fbp_node_group_asset_id(node_group):
    try:
        return str(node_group.get("fbp_geometry_effect_id", "") or "") if node_group else ""
    except FBP_DATA_ERRORS:
        return ""


def _fbp_group_matches(node_group, effect_id):
    """Match only explicitly tagged Frame by Plane node groups."""
    if not node_group:
        return False
    effect_id = fbp_normalize_effect_id(effect_id)
    definition = fbp_effect_definition(effect_id)
    asset_id = str(definition.get("asset_id", "") or "")
    if not definition or not asset_id:
        return False
    try:
        tagged_effect = fbp_normalize_effect_id(node_group.get("fbp_effect_id", ""))
        tagged_asset = str(node_group.get("fbp_effect_asset_id", "") or "")
        geometry_asset = _fbp_node_group_asset_id(node_group)
        # Programmatically generated groups must match the exact current asset
        # revision. Reusing a stale generated group can preserve an invalid
        # socket layout and corrupt the active effect graph.
        if bool(definition.get("builtin", False)):
            return tagged_asset == asset_id or geometry_asset == asset_id
        return tagged_effect == effect_id or tagged_asset == asset_id or geometry_asset == asset_id
    except FBP_DATA_ERRORS:
        return False


def _fbp_group_declares_effect(node_group, effect_id):
    """Return True when a node group belongs to an effect, even if stale.

    Asset revisions are intentionally ignored here. This helper is used only
    to discover an existing modifier so the strict health check can replace
    its outdated node group without losing modifier order or animated inputs.
    """
    if not node_group:
        return False
    try:
        return (
            fbp_normalize_effect_id(node_group.get("fbp_effect_id", ""))
            == fbp_normalize_effect_id(effect_id)
        )
    except FBP_DATA_ERRORS:
        return False


def _fbp_effect_group_health_signature(node_group):
    """Return a cheap structural signature for a cached canonical node group."""
    if node_group is None:
        return None
    try:
        interface = getattr(node_group, "interface", None)
        interface_items = getattr(interface, "items_tree", ()) if interface else ()
        return (
            str(node_group.get("fbp_effect_asset_id", "") or ""),
            str(getattr(node_group, "bl_idname", "") or ""),
            len(getattr(node_group, "nodes", ()) or ()),
            len(interface_items or ()),
        )
    except FBP_DATA_ERRORS:
        return None


def _fbp_invalidate_effect_group_asset_index():
    _FBP_EFFECT_GROUP_ASSET_INDEX["node_group_count"] = -1
    _FBP_EFFECT_GROUP_ASSET_INDEX["by_asset"] = {}
    _FBP_EFFECT_GROUP_ASSET_INDEX["miss_checked_at"] = {}


def _fbp_effect_groups_by_asset(asset_id):
    """Resolve canonical groups through a primitive asset-id index.

    The cache stores names rather than NodeTree wrappers. A same-count Undo or
    replacement can therefore be detected while resolving fresh datablocks,
    without dereferencing an object from the previous Blender Main generation.
    """
    asset_id = str(asset_id or "")
    try:
        node_groups = getattr(bpy.data, "node_groups", None)
        group_count = len(node_groups or ())
    except FBP_DATA_ERRORS:
        return ()

    def rebuild_names():
        rebuilt = {}
        try:
            for node_group in node_groups or ():
                if bool(node_group.get("fbp_private_effect_group", False)):
                    continue
                tagged_asset = str(node_group.get("fbp_effect_asset_id", "") or "")
                name = str(getattr(node_group, "name_full", getattr(node_group, "name", "")) or "")
                if tagged_asset and name:
                    rebuilt.setdefault(tagged_asset, []).append(name)
        except FBP_DATA_ERRORS:
            rebuilt = {}
        normalized = {key: tuple(value) for key, value in rebuilt.items()}
        _FBP_EFFECT_GROUP_ASSET_INDEX["node_group_count"] = group_count
        _FBP_EFFECT_GROUP_ASSET_INDEX["by_asset"] = normalized
        _FBP_EFFECT_GROUP_ASSET_INDEX["miss_checked_at"] = {}
        return normalized

    cached_count = int(_FBP_EFFECT_GROUP_ASSET_INDEX.get("node_group_count", -1) or -1)
    by_asset = _FBP_EFFECT_GROUP_ASSET_INDEX.get("by_asset", {})
    rebuilt_now = False
    if cached_count != group_count or not isinstance(by_asset, dict):
        by_asset = rebuild_names()
        rebuilt_now = True

    # A delete+create or Undo can replace one group with another while keeping
    # the collection count unchanged. Positive entries validate themselves by
    # name and asset tag below; absent assets need a short primitive miss TTL so
    # they can become visible without rescanning all node groups every draw.
    miss_checked_at = _FBP_EFFECT_GROUP_ASSET_INDEX.get("miss_checked_at", {})
    if not isinstance(miss_checked_at, dict):
        miss_checked_at = {}
        _FBP_EFFECT_GROUP_ASSET_INDEX["miss_checked_at"] = miss_checked_at
    if asset_id not in by_asset:
        now = time.monotonic()
        last_miss = float(miss_checked_at.get(asset_id, 0.0) or 0.0)
        if not rebuilt_now and (not last_miss or now - last_miss > 0.75):
            by_asset = rebuild_names()
            miss_checked_at = _FBP_EFFECT_GROUP_ASSET_INDEX.get("miss_checked_at", {})
        if asset_id not in by_asset and isinstance(miss_checked_at, dict):
            miss_checked_at[asset_id] = now

    def resolve(names):
        result = []
        stale = False
        for name in tuple(names or ()):
            try:
                node_group = node_groups.get(str(name))
                if node_group is None:
                    stale = True
                    continue
                if bool(node_group.get("fbp_private_effect_group", False)):
                    stale = True
                    continue
                if str(node_group.get("fbp_effect_asset_id", "") or "") != asset_id:
                    stale = True
                    continue
                result.append(node_group)
            except FBP_DATA_ERRORS:
                stale = True
        return tuple(result), stale

    groups, stale = resolve(by_asset.get(asset_id, ()))
    if stale:
        by_asset = rebuild_names()
        groups, _stale = resolve(by_asset.get(asset_id, ()))
    return groups


def _fbp_invalidate_node_group_caches(node_group):
    """Forget cached RNA references before a node-group datablock is removed."""
    if node_group is None:
        return
    try:
        pointer = int(node_group.as_pointer())
    except FBP_DATA_ERRORS:
        pointer = None
    if pointer is not None:
        _FBP_EFFECT_GROUP_HEALTH_SIGNATURES.pop(pointer, None)
        for cache in (
            _FBP_INTERFACE_INPUT_CACHE,
            _FBP_MATRIX_IMAGE_NODE_CACHE,
            _FBP_PRIVATE_IMAGE_SOURCE_SYNC_CACHE,
            _FBP_CUSTOM_GEOMETRY_SOCKET_CACHE,
        ):
            for key in tuple(cache):
                if isinstance(key, tuple) and key and key[0] == pointer:
                    cache.pop(key, None)
        for key in tuple(_FBP_CUSTOM_SHADER_SOCKET_CACHE):
            if isinstance(key, tuple) and len(key) > 2 and key[2] == pointer:
                _FBP_CUSTOM_SHADER_SOCKET_CACHE.pop(key, None)
    try:
        node_group_name = str(getattr(node_group, "name_full", getattr(node_group, "name", "")) or "")
    except FBP_DATA_ERRORS:
        node_group_name = ""
    for effect_id, cached_name in list(_FBP_EFFECT_GROUP_CACHE.items()):
        if node_group_name and str(cached_name or "") == node_group_name:
            _FBP_EFFECT_GROUP_CACHE.pop(effect_id, None)
    _fbp_invalidate_effect_group_asset_index()


FBP_PRIVATE_EFFECT_OWNER_ID_KEY = "fbp_effect_private_owner_id"
FBP_PRIVATE_MATERIAL_OWNER_ID_KEY = "fbp_effect_private_material_owner_id"


def _fbp_private_material_owner_id(rig, material):
    """Return a rename-safe identity for one material inside an effect stack."""
    if material is None:
        return ""
    try:
        material_id = str(material.get(FBP_PRIVATE_MATERIAL_OWNER_ID_KEY, "") or "")
    except FBP_DATA_ERRORS:
        return ""
    if not material_id:
        material_id = fbp_unique_token_hex()
        try:
            material[FBP_PRIVATE_MATERIAL_OWNER_ID_KEY] = material_id
        except FBP_DATA_ERRORS:
            return ""

    # Blender copies ID properties with duplicated materials. Repair collisions
    # only inside this rig's small material set; the stack UUID handles copies
    # belonging to other rigs without a project-wide scan.
    plane = _fbp_plane(rig)
    try:
        materials = tuple(getattr(getattr(plane, "data", None), "materials", ()) or ())
    except FBP_DATA_ERRORS:
        materials = ()
    for candidate in materials:
        if candidate is None or candidate is material:
            continue
        try:
            if str(candidate.get(FBP_PRIVATE_MATERIAL_OWNER_ID_KEY, "") or "") == material_id:
                material_id = fbp_unique_token_hex()
                material[FBP_PRIVATE_MATERIAL_OWNER_ID_KEY] = material_id
                break
        except FBP_DATA_ERRORS:
            continue
    stack_id = _fbp_effect_stack_owner_id(rig)
    return f"{stack_id}:{material_id}" if stack_id else material_id


def _fbp_refresh_private_effect_group_identity(
    node_group, *, owner, owner_id, owner_kind="", desired_name=""
):
    """Refresh managed display metadata without invalidating a live group."""
    if node_group is None:
        return False
    try:
        node_group[FBP_PRIVATE_EFFECT_OWNER_ID_KEY] = str(owner_id or "")
        if owner_kind == "GEOMETRY":
            node_group["fbp_effect_owner"] = str(owner or "")
        else:
            node_group["fbp_effect_private_owner"] = str(owner or "")
            node_group["fbp_effect_private_owner_kind"] = str(owner_kind or "")
            node_group["fbp_effect_material_owner"] = str(owner or "")
        if desired_name and str(node_group.name or "") != str(desired_name):
            node_group.name = str(desired_name)
        return True
    except FBP_DATA_ERRORS:
        return False


def _fbp_remove_node_group(node_group):
    """Quarantine an invalid generated group instead of freeing its ID.

    Blender 5.2 Undo can still reference zero-user IDs from a previous history
    state. Private per-layer groups retain their ownership/effect metadata so a
    later re-add can safely reuse the same ID instead of leaking one copy per
    add/remove cycle. Canonical groups still clear their public asset identity.
    """
    _fbp_invalidate_node_group_caches(node_group)
    if node_group is None:
        return False
    try:
        is_private = bool(node_group.get("fbp_private_effect_group", False))
        node_group["fbp_orphan_candidate"] = True
        node_group["fbp_quarantined"] = True
        if not is_private:
            node_group["fbp_effect_asset_id"] = ""
            node_group["fbp_effect_id"] = ""
            node_group["fbp_geometry_effect_id"] = ""
            node_group["fbp_shader_effect_id"] = ""
        node_group.use_fake_user = False
        if " • Orphan" not in str(node_group.name or ""):
            node_group.name = f"{node_group.name} • Orphan"
        return True
    except FBP_DATA_ERRORS:
        return False


def _fbp_reactivate_private_effect_group(
    node_group,
    *,
    effect_id,
    asset_id,
    owner,
    owner_id="",
    owner_kind="",
    desired_name="",
):
    """Re-adopt one zero-user private group retired by effect removal."""
    if node_group is None:
        return None
    try:
        if not bool(node_group.get("fbp_private_effect_group", False)):
            return None
        if int(getattr(node_group, "users", 0) or 0) != 0:
            return None
        node_group["fbp_effect_id"] = fbp_normalize_effect_id(effect_id)
        node_group["fbp_effect_asset_id"] = str(asset_id or "")
        node_group["fbp_effect_schema_version"] = FBP_EFFECT_SCHEMA_VERSION
        node_group["fbp_orphan_candidate"] = False
        node_group["fbp_quarantined"] = False
        _fbp_refresh_private_effect_group_identity(
            node_group,
            owner=owner,
            owner_id=owner_id,
            owner_kind=owner_kind,
            desired_name=desired_name,
        )
        node_group.use_fake_user = False
        return node_group
    except FBP_DATA_ERRORS:
        return None


def _fbp_cached_effect_group(effect_id, asset_id):
    """Return a live canonical effect group without rescanning bpy.data."""
    name = str(_FBP_EFFECT_GROUP_CACHE.get(str(effect_id or ""), "") or "")
    if not name:
        return None
    try:
        cached = bpy.data.node_groups.get(name)
        if cached is None:
            raise ReferenceError
        if bool(cached.get("fbp_private_effect_group", False)):
            raise ReferenceError
        if str(cached.get("fbp_effect_asset_id", "") or "") != str(asset_id or ""):
            raise ReferenceError
        pointer = int(cached.as_pointer())
        current_signature = _fbp_effect_group_health_signature(cached)
        expected_signature = _FBP_EFFECT_GROUP_HEALTH_SIGNATURES.get(pointer)
        if expected_signature is not None and current_signature != expected_signature:
            raise ReferenceError
        if expected_signature is None and current_signature is not None:
            _FBP_EFFECT_GROUP_HEALTH_SIGNATURES[pointer] = current_signature
        return cached
    except FBP_DATA_ERRORS:
        _FBP_EFFECT_GROUP_CACHE.pop(str(effect_id or ""), None)
        return None


def _fbp_store_effect_group_cache(effect_id, node_group):
    if node_group is None:
        _FBP_EFFECT_GROUP_CACHE.pop(str(effect_id or ""), None)
        return None
    # Lay the group out before its health signature is taken: frames count
    # as nodes there. Already tidy groups return after one property read.
    fbp_tidy_effect_group(node_group, effect_id)
    _FBP_EFFECT_GROUP_CACHE[str(effect_id or "")] = str(getattr(node_group, "name_full", getattr(node_group, "name", "")) or "")
    try:
        pointer = int(node_group.as_pointer())
        signature = _fbp_effect_group_health_signature(node_group)
        if signature is not None:
            _FBP_EFFECT_GROUP_HEALTH_SIGNATURES[pointer] = signature
    except FBP_DATA_ERRORS:
        pass
    return node_group


def _fbp_append_effect_group_from_library(
    effect_id, definition, canonical_name, source_names, asset_id, *, warn=True
):
    """Append one canonical effect group from the bundled asset library."""
    library_path = fbp_geometry_nodes_library_path()
    if not library_path.is_file():
        if warn:
            fbp_warn(f"Effect library not found: {library_path}")
        return None

    candidates = tuple(
        dict.fromkeys(
            name for name in (canonical_name, *tuple(source_names or ())) if name
        )
    )
    loaded = []
    try:
        with bpy.data.libraries.load(str(library_path), link=False) as (data_from, data_to):
            available = set(getattr(data_from, "node_groups", []) or [])
            source_name = next((name for name in candidates if name in available), None)
            if source_name is None:
                if warn:
                    raise RuntimeError(
                        f"The bundled .blend does not contain {definition.get('label', effect_id)}"
                    )
                return None
            data_to.node_groups = [source_name]
            loaded = data_to.node_groups
    except (OSError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError) as exc:
        if warn:
            fbp_warn(f"Could not append {definition.get('label', effect_id)}", exc)
        return None

    node_group = loaded[0] if loaded else None
    if not node_group:
        return None
    try:
        if canonical_name:
            node_group.name = canonical_name
        node_group.use_fake_user = False
        node_group["fbp_effect_id"] = effect_id
        node_group["fbp_effect_asset_id"] = asset_id
        node_group["fbp_effect_schema_version"] = FBP_EFFECT_SCHEMA_VERSION
        if definition.get("kind") == "GEOMETRY":
            node_group["fbp_geometry_effect_id"] = asset_id
        else:
            node_group["fbp_shader_effect_id"] = asset_id
    except FBP_DATA_ERRORS as exc:
        if warn:
            fbp_warn("Could not tag appended effect group", exc)
    return node_group


def _fbp_patch_grain_clamp(node_group):
    """Keep bundled Grain from writing negative colors.

    The bundled group adds centered noise (-0.18..0.18) without clamping, so
    dark pixels became negative emission. Every built-in color effect clamps
    its mix, and Grain now does the same.
    """
    try:
        node = node_group.nodes.get("Add Grain")
        if node is not None and getattr(node, "bl_idname", "") == "ShaderNodeMix" and not node.clamp_result:
            node.clamp_result = True
    except FBP_DATA_ERRORS:
        pass
    return node_group


def _fbp_prepare_canonical_effect_group(effect_id, node_group):
    """Upgrade bundled contracts once, before per-rig private copies exist."""
    if node_group is None:
        return None
    if effect_id == FBP_EFFECT_FELT_FUZZ and not _fbp_patch_alpha_mask(node_group):
        return None
    if effect_id == FBP_EFFECT_GRAIN:
        _fbp_patch_grain_clamp(node_group)
    return node_group


def _fbp_load_effect_group(effect_id):
    effect_id = fbp_normalize_effect_id(effect_id)
    definition = fbp_effect_definition(effect_id)
    if not definition:
        return None

    asset_id = str(definition.get("asset_id", "") or "")
    if bool(definition.get("custom", False)):
        if bool(definition.get("custom_invalid", False)):
            return None
        node_group = find_custom_effect_group(effect_id)
        if node_group is None:
            return None
        try:
            node_group.use_fake_user = True
            node_group["fbp_effect_id"] = effect_id
            node_group["fbp_effect_asset_id"] = asset_id
            node_group["fbp_effect_schema_version"] = FBP_EFFECT_SCHEMA_VERSION
            if definition.get("kind") == "GEOMETRY":
                node_group["fbp_geometry_effect_id"] = asset_id
            else:
                node_group["fbp_shader_effect_id"] = asset_id
        except FBP_DATA_ERRORS:
            return None
        return _fbp_store_effect_group_cache(effect_id, node_group)

    canonical_name = str(definition.get("canonical_name", "") or "")
    source_names = tuple(definition.get("source_names", ()))

    cached = _fbp_cached_effect_group(effect_id, asset_id)
    if cached is not None:
        prepared = _fbp_prepare_canonical_effect_group(effect_id, cached)
        if prepared is not None:
            return prepared
        _FBP_EFFECT_GROUP_CACHE.pop(effect_id, None)

    candidates = []
    # Exact-name lookup is O(1); the shared asset index handles renamed groups
    # and recovered files without repeating a full node-group scan per effect.
    try:
        exact = bpy.data.node_groups.get(canonical_name) if canonical_name else None
    except FBP_DATA_ERRORS:
        exact = None
    if exact is not None:
        try:
            if (
                not bool(exact.get("fbp_private_effect_group", False))
                and str(exact.get("fbp_effect_asset_id", "") or "") == asset_id
            ):
                candidates.append((0, exact))
        except FBP_DATA_ERRORS:
            pass
    for node_group in _fbp_effect_groups_by_asset(asset_id):
        if node_group is exact:
            continue
        priority = 0 if getattr(node_group, "name", "") == canonical_name else 1
        candidates.append((priority, node_group))

    if candidates:
        node_group = min(candidates, key=lambda item: item[0])[1]
        unprepared_group = node_group
        node_group = _fbp_prepare_canonical_effect_group(effect_id, node_group)
        if node_group is None:
            try:
                if int(getattr(unprepared_group, "users", 0) or 0) == 0:
                    _fbp_remove_node_group(unprepared_group)
            except FBP_DATA_ERRORS:
                pass
        if bool(definition.get("builtin", False)) and not _builtin_group_is_complete(node_group, definition):
            try:
                if int(getattr(node_group, "users", 0) or 0) == 0:
                    _fbp_remove_node_group(node_group)
            except FBP_DATA_ERRORS:
                pass
            node_group = None
        if node_group is not None:
            try:
                node_group.use_fake_user = False
                node_group["fbp_effect_id"] = effect_id
                node_group["fbp_effect_asset_id"] = asset_id
                node_group["fbp_effect_schema_version"] = FBP_EFFECT_SCHEMA_VERSION
                if definition.get("kind") == "GEOMETRY":
                    node_group["fbp_geometry_effect_id"] = asset_id
                else:
                    node_group["fbp_shader_effect_id"] = asset_id
            except FBP_DATA_ERRORS:
                pass
            return _fbp_store_effect_group_cache(effect_id, node_group)

    if bool(definition.get("prebundled", False)):
        node_group = _fbp_append_effect_group_from_library(
            effect_id, definition, canonical_name, source_names, asset_id, warn=False
        )
        node_group = _fbp_prepare_canonical_effect_group(effect_id, node_group)
        if node_group is not None:
            if _builtin_group_is_complete(node_group, definition):
                return _fbp_store_effect_group_cache(effect_id, node_group)
            try:
                node_group.use_fake_user = False
                if int(getattr(node_group, "users", 0) or 0) == 0:
                    _fbp_remove_node_group(node_group)
            except FBP_DATA_ERRORS:
                pass

    if bool(definition.get("builtin", False)):
        try:
            node_group = create_builtin_effect_group(
                effect_id,
                definition,
                Path(__file__).resolve().parent / "assets",
            )
        except FBP_DATA_ERRORS as exc:
            fbp_warn(f"Could not build {definition.get('label', effect_id)} effect", exc)
            node_group = None
        if node_group:
            try:
                node_group.use_fake_user = False
            except FBP_DATA_ERRORS:
                pass
            return _fbp_store_effect_group_cache(effect_id, node_group)

    node_group = _fbp_append_effect_group_from_library(
        effect_id, definition, canonical_name, source_names, asset_id, warn=True
    )
    node_group = _fbp_prepare_canonical_effect_group(effect_id, node_group)
    return _fbp_store_effect_group_cache(effect_id, node_group) if node_group else None


# ---------------------------------------------------------------------------
# Mesh Wiggle effect loading
# ---------------------------------------------------------------------------


def fbp_load_mesh_wiggle_group():
    return _fbp_load_effect_group(FBP_EFFECT_MESH_WIGGLE)


def fbp_assign_mesh_wiggle_layer_seed(rig, *, force=False):
    if not rig:
        return 0
    try:
        current = int(getattr(rig, "fbp_mesh_wiggle_layer_seed", 0) or 0)
    except FBP_DATA_ERRORS:
        current = 0
    if force or current <= 0:
        current = int(uuid.uuid4().int % 2147483646) + 1
        fbp_set_rna_property_silent(rig, "fbp_mesh_wiggle_layer_seed", current)
    return current


def fbp_mesh_wiggle_effective_w(rig, scene=None):
    try:
        phase = float(getattr(rig, "fbp_mesh_wiggle_w", 0.0) or 0.0)
        seed = int(getattr(rig, "fbp_mesh_wiggle_seed", 0) or 0)
        unique = bool(getattr(rig, "fbp_mesh_wiggle_unique_seed", False))
        speed = float(getattr(rig, "fbp_mesh_wiggle_speed", 0.0) or 0.0)
        hold = max(1, int(getattr(rig, "fbp_mesh_wiggle_hold", 1) or 1))
    except FBP_DATA_ERRORS:
        return 0.0
    value = phase + (float(seed) * 13.731)
    if unique:
        layer_seed = fbp_assign_mesh_wiggle_layer_seed(rig)
        value += float(layer_seed % 1000003) * 0.017
    if abs(speed) > 1e-9:
        try:
            scene = scene or getattr(bpy.context, "scene", None)
            frame = int(getattr(scene, "frame_current", 1) or 1)
            start = int(getattr(scene, "frame_start", 1) or 1)
            held_frame = start + (math.floor((frame - start) / hold) * hold)
            value += float(held_frame - start) * speed * 0.1
        except FBP_DATA_ERRORS:
            pass
    return value


# ---------------------------------------------------------------------------
# Alpha-aware geometry group copies
# ---------------------------------------------------------------------------


def _fbp_add_interface_socket(node_group, name, socket_type, default, minimum=None, maximum=None):
    existing = _fbp_interface_input(node_group, name)
    if existing is not None:
        return existing
    interface_socket = node_group.interface.new_socket(
        name=name, in_out="INPUT", socket_type=socket_type
    )
    for attr, value in (
        ("default_value", default),
        ("min_value", minimum),
        ("max_value", maximum),
    ):
        if value is None:
            continue
        try:
            setattr(interface_socket, attr, value)
        except FBP_DATA_ERRORS:
            pass
    return interface_socket


def _fbp_patch_fuzz_alpha_mask(node_group):
    """Mask only the strand distribution, never the original plane geometry.

    A destructive alpha-mask layout can feed thousands of invisible surfaces
    through the Fuzz graph and make the original image appear to vanish. Keep
    the plane on an untouched output branch and use image alpha only as a
    boolean field for point distribution and opaque-area measurement.
    """
    if not node_group:
        return False

    try:
        if int(node_group.get("fbp_alpha_mask_patch_version", 0) or 0) >= FBP_ALPHA_MASK_PATCH_VERSION:
            return True
    except FBP_DATA_ERRORS:
        pass

    _fbp_add_interface_socket(node_group, "Alpha Threshold", "NodeSocketFloat", 0.05, 0.0, 1.0)
    _fbp_add_interface_socket(node_group, "Alpha Resolution", "NodeSocketInt", 2, 0, 6)
    _fbp_add_interface_socket(node_group, "Use Alpha Mask", "NodeSocketBool", True)

    nodes = node_group.nodes
    links = node_group.links
    group_input = next(
        (
            node for node in nodes
            if getattr(node, "bl_idname", "") == "NodeGroupInput"
            and _fbp_node_socket(node.outputs, "Geometry") is not None
        ),
        None,
    )
    distribute = nodes.get("Distribute Fibers")
    area_stats = nodes.get("Total Surface Area")
    if group_input is None or distribute is None or area_stats is None:
        return False

    # Remove only the old geometry links feeding the Fuzz-generation branch.
    # The direct Group Input -> Join Base and Fuzz link remains untouched.
    for target in (
        _fbp_node_socket(distribute.inputs, "Mesh", 0),
        _fbp_node_socket(area_stats.inputs, "Geometry", 0),
        _fbp_node_socket(distribute.inputs, "Selection", 1),
        _fbp_node_socket(area_stats.inputs, "Selection", 1),
    ):
        if target is None:
            continue
        for link in list(target.links):
            links.remove(link)

    subdivide = nodes.new("GeometryNodeSubdivideMesh")
    subdivide.name = "FBP Fuzz Alpha Subdivide"
    subdivide.label = "Fuzz Alpha Detail"
    subdivide.location = (-820, -520)

    named_uv = nodes.new("GeometryNodeInputNamedAttribute")
    named_uv.name = "FBP Fuzz Alpha UV"
    named_uv.label = "UVMap"
    named_uv.location = (-820, -760)
    try:
        named_uv.data_type = "FLOAT_VECTOR"
    except (AttributeError, TypeError, ValueError):
        pass
    uv_name = _fbp_node_socket(named_uv.inputs, "Name")
    if uv_name is not None:
        uv_name.default_value = "UVMap"

    image_texture = nodes.new("GeometryNodeImageTexture")
    image_texture.name = "FBP Alpha Image Texture"
    image_texture.label = "Current FBP Image Alpha"
    image_texture.location = (-560, -720)
    image_texture["fbp_alpha_image_node"] = True
    try:
        image_texture.extension = "EXTEND"
        image_texture.interpolation = "Linear"
    except (AttributeError, TypeError, ValueError):
        pass

    compare = nodes.new("ShaderNodeMath")
    compare.name = "FBP Fuzz Alpha Visible"
    compare.label = "Visible Pixels"
    compare.operation = "GREATER_THAN"
    compare.location = (-300, -680)

    selection_switch = nodes.new("GeometryNodeSwitch")
    selection_switch.name = "FBP Fuzz Use Alpha Mask"
    selection_switch.label = "Use Alpha Mask"
    selection_switch.location = (-50, -620)
    try:
        selection_switch.input_type = "BOOLEAN"
    except (AttributeError, TypeError, ValueError):
        pass
    false_input = _fbp_node_socket(selection_switch.inputs, "False", 1)
    if false_input is not None:
        false_input.default_value = True

    geometry_source = _fbp_node_socket(group_input.outputs, "Geometry")
    resolution_source = _fbp_node_socket(group_input.outputs, "Alpha Resolution")
    threshold_source = _fbp_node_socket(group_input.outputs, "Alpha Threshold")
    use_source = _fbp_node_socket(group_input.outputs, "Use Alpha Mask")

    subdivide_mesh = _fbp_node_socket(subdivide.inputs, "Mesh", 0)
    subdivide_level = _fbp_node_socket(subdivide.inputs, "Level", 1)
    if geometry_source is None or subdivide_mesh is None:
        return False
    links.new(geometry_source, subdivide_mesh)
    if resolution_source is not None and subdivide_level is not None:
        links.new(resolution_source, subdivide_level)

    uv_output = _fbp_node_socket(named_uv.outputs, "Attribute", 0)
    vector_input = _fbp_node_socket(image_texture.inputs, "Vector")
    if uv_output is not None and vector_input is not None:
        links.new(uv_output, vector_input)

    alpha_output = _fbp_node_socket(image_texture.outputs, "Alpha")
    compare_a = _fbp_node_socket(compare.inputs, "Value", 0)
    compare_b = _fbp_node_socket(compare.inputs, "Value", 1)
    if alpha_output is not None and compare_a is not None:
        links.new(alpha_output, compare_a)
    if threshold_source is not None and compare_b is not None:
        links.new(threshold_source, compare_b)

    switch_toggle = _fbp_node_socket(selection_switch.inputs, "Switch", 0)
    switch_true = _fbp_node_socket(selection_switch.inputs, "True", 2)
    if use_source is not None and switch_toggle is not None:
        links.new(use_source, switch_toggle)
    visible_output = _fbp_node_socket(compare.outputs, "Value", 0)
    if visible_output is not None and switch_true is not None:
        links.new(visible_output, switch_true)

    subdivided_geometry = _fbp_node_socket(subdivide.outputs, "Mesh", 0)
    distribute_mesh = _fbp_node_socket(distribute.inputs, "Mesh", 0)
    area_geometry = _fbp_node_socket(area_stats.inputs, "Geometry", 0)
    if subdivided_geometry is not None:
        if distribute_mesh is not None:
            links.new(subdivided_geometry, distribute_mesh)
        if area_geometry is not None:
            links.new(subdivided_geometry, area_geometry)

    selection_output = _fbp_node_socket(selection_switch.outputs, "Output", 0)
    distribute_selection = _fbp_node_socket(distribute.inputs, "Selection", 1)
    area_selection = _fbp_node_socket(area_stats.inputs, "Selection", 1)
    if selection_output is not None:
        if distribute_selection is not None:
            links.new(selection_output, distribute_selection)
        if area_selection is not None:
            links.new(selection_output, area_selection)

    node_group["fbp_alpha_mask_patch_version"] = FBP_ALPHA_MASK_PATCH_VERSION
    return True


def _fbp_patch_alpha_mask(node_group):
    if not node_group:
        return False
    try:
        effect_id = fbp_normalize_effect_id(node_group.get("fbp_effect_id", ""))
    except FBP_DATA_ERRORS:
        effect_id = ""
    if effect_id == FBP_EFFECT_FELT_FUZZ:
        return _fbp_patch_fuzz_alpha_mask(node_group)
    try:
        if int(node_group.get("fbp_alpha_mask_patch_version", 0) or 0) >= FBP_ALPHA_MASK_PATCH_VERSION:
            return True
    except FBP_DATA_ERRORS:
        pass

    _fbp_add_interface_socket(node_group, "Alpha Threshold", "NodeSocketFloat", 0.05, 0.0, 1.0)
    _fbp_add_interface_socket(
        node_group,
        "Alpha Resolution",
        "NodeSocketInt",
        2 if fbp_normalize_effect_id(node_group.get("fbp_effect_id", "")) == FBP_EFFECT_FELT_FUZZ else 4,
        0,
        6,
    )
    _fbp_add_interface_socket(node_group, "Use Alpha Mask", "NodeSocketBool", True)

    group_inputs = [
        node for node in node_group.nodes
        if getattr(node, "bl_idname", "") == "NodeGroupInput"
        and _fbp_node_socket(node.outputs, "Geometry") is not None
    ]
    if not group_inputs:
        return False

    outgoing_targets = []
    for input_node in group_inputs:
        geometry_output = _fbp_node_socket(input_node.outputs, "Geometry")
        for link in list(node_group.links):
            if link.from_socket != geometry_output:
                continue
            target_node = getattr(link, "to_node", None)
            try:
                preserve_original = bool(
                    target_node and target_node.get("fbp_preserve_unmasked_geometry", False)
                )
            except FBP_DATA_ERRORS:
                preserve_original = False
            if preserve_original:
                continue
            outgoing_targets.append(link.to_socket)
            node_group.links.remove(link)
    if not outgoing_targets:
        return False

    primary = group_inputs[0]
    nodes = node_group.nodes
    links = node_group.links

    subdivide = nodes.new("GeometryNodeSubdivideMesh")
    subdivide.name = "FBP Alpha Subdivide"
    subdivide.label = "Alpha Mask Resolution"
    subdivide.location = (-780, -520)

    named_uv = nodes.new("GeometryNodeInputNamedAttribute")
    named_uv.name = "FBP Alpha UV"
    named_uv.label = "UVMap"
    named_uv.location = (-780, -760)
    try:
        named_uv.data_type = "FLOAT_VECTOR"
    except (AttributeError, TypeError, ValueError):
        pass
    name_input = _fbp_node_socket(named_uv.inputs, "Name")
    if name_input:
        name_input.default_value = "UVMap"

    image_texture = nodes.new("GeometryNodeImageTexture")
    image_texture.name = "FBP Alpha Image Texture"
    image_texture.label = "Current FBP Image Alpha"
    image_texture.location = (-520, -720)
    image_texture["fbp_alpha_image_node"] = True
    try:
        image_texture.extension = "EXTEND"
        image_texture.interpolation = "Linear"
    except (AttributeError, TypeError, ValueError):
        pass

    compare = nodes.new("ShaderNodeMath")
    compare.name = "FBP Alpha Below Threshold"
    compare.label = "Transparent Pixels"
    compare.operation = "LESS_THAN"
    compare.location = (-260, -660)

    use_mask = nodes.new("FunctionNodeBooleanMath")
    use_mask.name = "FBP Use Alpha Mask"
    use_mask.label = "Use Alpha Mask"
    use_mask.operation = "AND"
    use_mask.location = (-40, -600)

    delete_geometry = nodes.new("GeometryNodeDeleteGeometry")
    delete_geometry.name = "FBP Delete Transparent Geometry"
    delete_geometry.label = "Delete Transparent Pixels"
    delete_geometry.location = (180, -500)
    try:
        delete_geometry.domain = "FACE"
    except (AttributeError, TypeError, ValueError):
        pass

    geometry_source = _fbp_node_socket(primary.outputs, "Geometry")
    resolution_source = _fbp_node_socket(primary.outputs, "Alpha Resolution")
    threshold_source = _fbp_node_socket(primary.outputs, "Alpha Threshold")
    use_source = _fbp_node_socket(primary.outputs, "Use Alpha Mask")

    links.new(geometry_source, _fbp_node_socket(subdivide.inputs, "Mesh", 0))
    if resolution_source:
        links.new(resolution_source, _fbp_node_socket(subdivide.inputs, "Level", 1))

    attribute_output = _fbp_node_socket(named_uv.outputs, "Attribute", 0)
    vector_input = _fbp_node_socket(image_texture.inputs, "Vector")
    if attribute_output and vector_input:
        links.new(attribute_output, vector_input)

    alpha_output = _fbp_node_socket(image_texture.outputs, "Alpha")
    if alpha_output:
        links.new(alpha_output, _fbp_node_socket(compare.inputs, "Value", 0))
    if threshold_source:
        links.new(threshold_source, _fbp_node_socket(compare.inputs, "Value", 1))
    links.new(_fbp_node_socket(compare.outputs, "Value", 0), _fbp_node_socket(use_mask.inputs, "Boolean", 0))
    if use_source:
        links.new(use_source, _fbp_node_socket(use_mask.inputs, "Boolean", 1))

    links.new(_fbp_node_socket(subdivide.outputs, "Mesh", 0), _fbp_node_socket(delete_geometry.inputs, "Geometry", 0))
    links.new(_fbp_node_socket(use_mask.outputs, "Boolean", 0), _fbp_node_socket(delete_geometry.inputs, "Selection", 1))
    masked_output = _fbp_node_socket(delete_geometry.outputs, "Geometry", 0)
    for target in outgoing_targets:
        links.new(masked_output, target)

    node_group["fbp_alpha_mask_patch_version"] = FBP_ALPHA_MASK_PATCH_VERSION
    return True


def _fbp_material_image_node(rig):
    plane = _fbp_plane(rig)
    if not plane or not getattr(plane, "data", None):
        return None, None
    try:
        materials = [mat for mat in plane.data.materials if mat and getattr(mat, "node_tree", None)]
    except FBP_DATA_ERRORS:
        materials = []
    for material in materials:
        node_tree = getattr(material, "node_tree", None)
        if not node_tree:
            continue
        for preferred_name in ("FBP_Native_Media_Texture", "FBP_AlphaHoldout_Texture"):
            preferred = node_tree.nodes.get(preferred_name)
            if preferred and getattr(preferred, "type", "") == "TEX_IMAGE" and getattr(preferred, "image", None):
                return material, preferred
        for node in node_tree.nodes:
            try:
                is_owned = bool(node.get("fbp_native_sequence_node", False)) or bool(
                    node.get("fbp_holdout_image_node", False)
                )
            except FBP_DATA_ERRORS:
                is_owned = False
            if is_owned and getattr(node, "type", "") == "TEX_IMAGE" and getattr(node, "image", None):
                return material, node
    return None, None


def _fbp_geometry_image_frame(src_user, scene_frame):
    """Return the 1-based sequence frame expected by Geometry Image Texture.

    Shader Image Texture timing is expressed as timeline frame plus
    ``ImageUser.frame_offset``. Geometry Nodes uses an explicit 1-based Frame
    input, so omitting the final +1 evaluates the first source frame as frame
    zero and returns transparent alpha.
    """
    if src_user is None:
        return 1
    try:
        return int(
            int(scene_frame)
            - int(getattr(src_user, "frame_start", 1) or 1)
            + int(getattr(src_user, "frame_offset", 0) or 0)
            + 1
        )
    except FBP_DATA_ERRORS:
        return 1


def _fbp_copy_image_user(src_owner, src_node, dst_owner, dst_node):
    """Initialize direct Geometry Image Texture timing from the material ImageUser.

    Geometry Nodes exposes an integer Frame input instead of an ImageUser.
    Frame by Plane updates that input from the frame-change handler; nested RNA
    drivers are removed once and are not rescanned on every material refresh.
    """
    del src_owner
    src_user = getattr(src_node, "image_user", None)
    frame_input = _fbp_node_socket(getattr(dst_node, "inputs", ()), "Frame")
    if src_user is None or frame_input is None:
        return False

    initialized = False
    try:
        initialized = bool(dst_owner.get("fbp_alpha_frame_direct", False))
    except FBP_DATA_ERRORS:
        pass
    if not initialized:
        try:
            dst_path = frame_input.path_from_id("default_value")
            animation_data = getattr(dst_owner, "animation_data", None)
            if animation_data:
                for curve in list(getattr(animation_data, "drivers", ()) or ()):
                    if curve.data_path == dst_path:
                        dst_owner.driver_remove(dst_path)
                        break
                fbp_remove_action_fcurves(dst_owner, dst_path)
            dst_owner["fbp_alpha_frame_direct"] = True
        except FBP_DATA_ERRORS:
            pass

    try:
        current_frame = int(getattr(getattr(bpy.context, "scene", None), "frame_current", 1))
        value = _fbp_geometry_image_frame(src_user, current_frame)
        if int(getattr(frame_input, "default_value", 0) or 0) == value:
            return False
        frame_input.default_value = value
        dst_owner.update_tag()
        return True
    except FBP_DATA_ERRORS:
        return False


def _fbp_alpha_image_node(node_group):
    if not node_group:
        return None
    try:
        for name in ("FBP Alpha Image Texture", "Text Matrix Source Image"):
            node = node_group.nodes.get(name)
            if node and bool(node.get("fbp_alpha_image_node", False)):
                return node
        for node in node_group.nodes:
            if bool(node.get("fbp_alpha_image_node", False)):
                return node
    except FBP_DATA_ERRORS:
        pass
    return None


def _fbp_sync_geometry_plane_uv_sampling(node_group, source_node, *, exclude=None):
    """Mirror the plane image sampling contract to auxiliary Geometry Nodes images.

    Crystal's Influence Map is a separate image datablock, but it occupies the
    same UV space as the source plane. Crop is encoded in the plane UVMap and
    Extend is encoded by UV values outside 0..1 plus the image-node extension
    mode. Auxiliary maps must therefore use the source texture's interpolation
    and extension settings without inheriting its Image or ImageUser.
    """
    if not node_group or source_node is None:
        return False
    try:
        desired_interpolation = getattr(source_node, "interpolation", None)
        desired_extension = getattr(source_node, "extension", None)
    except FBP_DATA_ERRORS:
        return False
    changed = False
    try:
        nodes = tuple(node_group.nodes)
    except FBP_DATA_ERRORS:
        return False
    for node in nodes:
        try:
            if node is exclude or not bool(node.get("fbp_plane_uv_aux_image_node", False)):
                continue
            if desired_interpolation is not None and getattr(node, "interpolation", None) != desired_interpolation:
                node.interpolation = desired_interpolation
                changed = True
            if desired_extension is not None and getattr(node, "extension", None) != desired_extension:
                node.extension = desired_extension
                changed = True
        except FBP_DATA_ERRORS:
            continue
    return changed


def _fbp_sync_geometry_alpha(rig, modifier):
    node_group = getattr(modifier, "node_group", None) if modifier else None
    if not node_group:
        return False
    image_node = _fbp_alpha_image_node(node_group)
    if not image_node:
        return False
    interface_inputs = _fbp_interface_inputs(node_group)
    source_material, source_node = _fbp_material_image_node(rig)
    source_image = getattr(source_node, "image", None) if source_node else None
    has_image = bool(source_image)
    changed = False
    try:
        image_input = _fbp_node_socket(image_node.inputs, "Image")
        if image_input is not None:
            if getattr(image_input, "default_value", None) is not source_image:
                image_input.default_value = source_image
                changed = True
        elif hasattr(image_node, "image") and getattr(image_node, "image", None) is not source_image:
            image_node.image = source_image
            changed = True
        if has_image:
            try:
                is_text_matrix = bool(image_node.get("fbp_text_matrix_image_node", False))
                interpolation = (
                    "Closest"
                    if is_text_matrix
                    else getattr(source_node, "interpolation", image_node.interpolation)
                )
                extension = (
                    "EXTEND"
                    if is_text_matrix
                    else getattr(source_node, "extension", image_node.extension)
                )
                if getattr(image_node, "interpolation", None) != interpolation:
                    image_node.interpolation = interpolation
                    changed = True
                if getattr(image_node, "extension", None) != extension:
                    image_node.extension = extension
                    changed = True
            except FBP_DATA_ERRORS:
                pass
            changed = _fbp_copy_image_user(
                source_material.node_tree, source_node, node_group, image_node
            ) or changed
            changed = _fbp_sync_geometry_plane_uv_sampling(
                node_group, source_node, exclude=image_node
            ) or changed
        if "Use Alpha Mask" in interface_inputs:
            changed = _fbp_set_modifier_input(
                modifier, node_group, "Use Alpha Mask", has_image, interface_inputs
            ) or changed
        if changed:
            try:
                node_group.update_tag()
            except FBP_DATA_ERRORS:
                pass
        return changed
    except FBP_DATA_ERRORS as exc:
        fbp_warn("Could not synchronize geometry alpha image", exc)
        if "Use Alpha Mask" in interface_inputs:
            return _fbp_set_modifier_input(
                modifier, node_group, "Use Alpha Mask", False, interface_inputs
            )
        return False


_FBP_FRAME_STACK_TIMING_CACHE = {}
_FBP_FRAME_STACK_TABLE_CACHE = {}


def _fbp_frame_stack_native_timing(material):
    """Return the cached playback cycle of a native sequence material."""
    try:
        key = (
            int(material.as_pointer()),
            str(material.get("fbp_native_playback_signature", "") or ""),
            int(material.get("fbp_native_frame_start", 1) or 1),
            str(material.get("fbp_native_loop_mode", "") or ""),
            str(material.get("fbp_native_source_indices_json", "") or ""),
            int(material.get("fbp_native_frame_number_base", 1) or 1),
        )
    except FBP_DATA_ERRORS:
        return None
    if key in _FBP_FRAME_STACK_TIMING_CACHE:
        return _FBP_FRAME_STACK_TIMING_CACHE[key]
    try:
        from .native_backend import fbp_native_playback_timing
        timing = fbp_native_playback_timing(material)
    except (ImportError, *FBP_DATA_ERRORS):
        timing = None
    if len(_FBP_FRAME_STACK_TIMING_CACHE) >= 256:
        _FBP_FRAME_STACK_TIMING_CACHE.clear()
    _FBP_FRAME_STACK_TIMING_CACHE[key] = timing
    return timing


_FBP_FRAME_STACK_IMAGE_NAMES = {}


def _fbp_frame_stack_find_image(tag, owner):
    """Return the layer's generated Frame Stack image, remembering its name.

    Scanning ``bpy.data.images`` on every frame change costs more than the
    rest of the sync once a file holds many images.
    """
    key = (tag, owner)
    name = _FBP_FRAME_STACK_IMAGE_NAMES.get(key)
    if name is not None:
        candidate = bpy.data.images.get(name)
        try:
            if (
                candidate is not None
                and bool(candidate.get(tag, False))
                and str(candidate.get("fbp_effect_material_owner", "") or "") == owner
            ):
                return candidate
        except FBP_DATA_ERRORS:
            pass
        _FBP_FRAME_STACK_IMAGE_NAMES.pop(key, None)
    for candidate in bpy.data.images:
        if (
            bool(candidate.get(tag, False))
            and str(candidate.get("fbp_effect_material_owner", "") or "") == owner
        ):
            if len(_FBP_FRAME_STACK_IMAGE_NAMES) >= 1024:
                _FBP_FRAME_STACK_IMAGE_NAMES.clear()
            _FBP_FRAME_STACK_IMAGE_NAMES[key] = candidate.name
            return candidate
    return None


def _fbp_frame_stack_table_image(rig, timing):
    """Write the sequence timing table read by the Frame Stack group.

    One float pixel per playback position: R is the file frame number, G is 1
    for a drawn frame and 0 for a blank one. The image is generated, so its
    pixels are rebuilt from the material metadata after a reload or Undo.
    """
    from .builtin_effects import FBP_FRAME_STACK_TABLE_WIDTH as width
    plane = _fbp_plane(rig)
    if not plane or not timing:
        return None, 1
    files = timing["files"]
    visible = timing["visible"]
    rows = max(1, -(-len(files) // width))
    owner = str(getattr(plane, "name", "") or "")
    name = f"FBP Frame Stack Timing • {owner}"
    try:
        image = _fbp_frame_stack_find_image("fbp_frame_stack_timing", owner)
        if image is None:
            image = bpy.data.images.new(name, width, rows, alpha=True, float_buffer=True, is_data=True)
            image.use_fake_user = False
            image["fbp_frame_stack_timing"] = True
            image["fbp_owned"] = True
            image["fbp_effect_material_owner"] = owner
        elif tuple(image.size) != (width, rows):
            image.scale(width, rows)
        signature = (files, visible)
        key = int(image.as_pointer())
        if _FBP_FRAME_STACK_TABLE_CACHE.get(key) != signature:
            pixels = [0.0, 0.0, 0.0, 1.0] * (width * rows)
            for position, (frame_number, shown) in enumerate(zip(files, visible)):
                pixels[position * 4] = float(frame_number)
                pixels[position * 4 + 1] = 1.0 if shown else 0.0
            image.pixels.foreach_set(pixels)
            image.update()
            if len(_FBP_FRAME_STACK_TABLE_CACHE) >= 256:
                _FBP_FRAME_STACK_TABLE_CACHE.clear()
            _FBP_FRAME_STACK_TABLE_CACHE[key] = signature
    except FBP_DATA_ERRORS as exc:
        fbp_warn("Could not write the Frame Stack timing table", exc)
        return None, 1
    return image, rows


# Frame Stack light path: one small thumbnail per slice, packed into one
# stack image. Thumbnails are decoded with OpenImageIO (no datablocks, so it
# is safe from render handlers) and kept in a byte-budgeted cache, so a
# drawing is read from disk once per session and size instead of once per
# slice as a full-resolution float buffer.
_FBP_FRAME_STACK_THUMBS = OrderedDict()
_FBP_FRAME_STACK_THUMB_BYTES = [0]
_FBP_FRAME_STACK_THUMB_BUDGET = 256 * 1024 * 1024
_FBP_FRAME_STACK_PATHS_CACHE = {}
_FBP_FRAME_STACK_CELLS_CACHE = {}
_FBP_FRAME_STACK_CANVASES = {}
_FBP_FRAME_STACK_IMAGE_STATE = {}
_FBP_FRAME_STACK_OCIO = {}
_FBP_FRAME_STACK_FAILED_PATHS = {}


def _fbp_frame_stack_source_paths(material):
    """Return ``(frame_number_base, paths)`` of a native sequence, cached."""
    try:
        key = (
            int(material.as_pointer()),
            str(material.get("fbp_native_source_sequence_json", "") or ""),
            int(material.get("fbp_native_frame_number_base", 1) or 1),
        )
    except FBP_DATA_ERRORS:
        return None
    if key in _FBP_FRAME_STACK_PATHS_CACHE:
        return _FBP_FRAME_STACK_PATHS_CACHE[key]
    result = None
    try:
        from . import native_backend as _native
        directory, files = _native._source_sequence_from_material(material)
        if directory and files:
            base = int(_native._material_frame_number_base(material))
            result = (
                base,
                tuple(os.path.abspath(str(_native._media_path(directory, name))) for name in files),
            )
    except (ImportError, AttributeError, OSError, *FBP_DATA_ERRORS):
        result = None
    if len(_FBP_FRAME_STACK_PATHS_CACHE) >= 256:
        _FBP_FRAME_STACK_PATHS_CACHE.clear()
    _FBP_FRAME_STACK_PATHS_CACHE[key] = result
    return result


def _fbp_frame_stack_cell_size(width, height, detail):
    """Thumbnail size that resolves the slice grid of ``detail`` twice over."""
    width = max(1, int(width))
    height = max(1, int(height))
    root = math.sqrt(width / height)
    base = 2.0 ** max(0, min(8, int(detail)))
    segments_x = max(1, min(512, int(round(base * root))))
    segments_y = max(1, min(512, int(round(base / root))))
    return (
        max(2, min(width, 2 * segments_x + 2)),
        max(2, min(height, 2 * segments_y + 2)),
    )


_FBP_FRAME_STACK_SIZES = {}
# Pixels of one stack image; larger stacks get smaller cells.
_FBP_FRAME_STACK_PIXEL_BUDGET = 8 * 1024 * 1024


def _fbp_frame_stack_source_size(path):
    """Return the pixel size of a source file from its header, cached."""
    try:
        stat = os.stat(path)
    except OSError:
        return None
    key = (path, int(stat.st_mtime_ns), int(stat.st_size))
    if key in _FBP_FRAME_STACK_SIZES:
        return _FBP_FRAME_STACK_SIZES[key]
    size = None
    try:
        import OpenImageIO as oiio
        source = oiio.ImageInput.open(path)
        if source:
            try:
                spec = source.spec()
                if spec.width > 0 and spec.height > 0:
                    size = (int(spec.width), int(spec.height))
            finally:
                source.close()
    except Exception:  # OIIO raises its own error types.
        size = None
    if len(_FBP_FRAME_STACK_SIZES) >= 4096:
        _FBP_FRAME_STACK_SIZES.clear()
    _FBP_FRAME_STACK_SIZES[key] = size
    return size


def _fbp_frame_stack_ocio_config():
    """Path of Blender's OCIO config, so thumbnails convert like Blender."""
    if "config" not in _FBP_FRAME_STACK_OCIO:
        path = ""
        try:
            candidate = os.path.join(
                bpy.utils.resource_path("LOCAL"), "datafiles", "colormanagement", "config.ocio",
            )
            path = candidate if os.path.isfile(candidate) else ""
        except (AttributeError, OSError, RuntimeError, TypeError, ValueError):
            path = ""
        _FBP_FRAME_STACK_OCIO["config"] = path
    return _FBP_FRAME_STACK_OCIO["config"]


def _fbp_frame_stack_ocio_convert(pixels, colorspace):
    """Convert straight RGB(A) pixels to scene linear with Blender's OCIO."""
    import numpy as np
    import OpenImageIO as oiio
    ocio = _fbp_frame_stack_ocio_config()
    if not ocio:
        raise ValueError("Blender colour configuration not found")
    height, width = pixels.shape[0], pixels.shape[1]
    buffer = oiio.ImageBuf(oiio.ImageSpec(width, height, 4, oiio.FLOAT))
    buffer.set_pixels(oiio.ROI(0, width, 0, height, 0, 1, 0, 4), np.ascontiguousarray(pixels, dtype=np.float32))
    linear = oiio.ImageBufAlgo.colorconvert(
        buffer, str(colorspace), "scene_linear", unpremult=False, colorconfig=ocio,
    )
    if linear.has_error:
        raise ValueError(linear.geterror())
    return np.asarray(linear.get_pixels(oiio.FLOAT), dtype=np.float32).reshape(height, width, 4)


def _fbp_frame_stack_byte_lut(colorspace):
    """Per-channel tables from 8-bit codes to scene-linear RGB.

    Loading the OCIO config costs tens of milliseconds per call, so each
    colour space is converted once: one ramp per input channel, whose
    outputs add up for the usual curve-then-matrix colour spaces.
    """
    key = ("lut", str(colorspace))
    lut = _FBP_FRAME_STACK_OCIO.get(key)
    if lut is None:
        import numpy as np
        ramp = np.zeros((3, 256, 4), dtype=np.float32)
        codes = np.arange(256, dtype=np.float32) / 255.0
        for channel in range(3):
            ramp[channel, :, channel] = codes
        ramp[..., 3] = 1.0
        converted = _fbp_frame_stack_ocio_convert(ramp, colorspace)
        black = converted[0, 0, :3].copy()
        lut = tuple(
            converted[channel, :, :3] - (black * (2.0 / 3.0)) for channel in range(3)
        )
        _FBP_FRAME_STACK_OCIO[key] = lut
    return lut


def _fbp_frame_stack_convert_float(pixels, colorspace):
    """Bring a float thumbnail to scene linear; linear sources pass through."""
    try:
        role = _FBP_FRAME_STACK_OCIO.get("scene_linear")
        if role is None:
            import OpenImageIO as oiio
            ocio = _fbp_frame_stack_ocio_config()
            role = str(oiio.ColorConfig(ocio).getColorSpaceNameByRole("scene_linear") or "") if ocio else ""
            _FBP_FRAME_STACK_OCIO["scene_linear"] = role
    except Exception:  # OIIO raises its own error types.
        role = ""
    if str(colorspace) in {role, "Linear Rec.709", "scene_linear"}:
        return pixels
    return _fbp_frame_stack_ocio_convert(pixels, colorspace)


def _fbp_frame_stack_thumbnail(path, width, height, colorspace="sRGB", is_data=False):
    """Return ``(pixels, width, height, key)`` for one source file.

    ``pixels`` is a bottom-up float32 RGBA array in scene linear holding
    exactly what the Geometry Image Texture node returns for the full
    frame, so the stack image (alpha mode Premultiplied, read as stored)
    matches the Repeat Zone path.
    ``colorspace`` is the source image's colour space; data images are not
    converted. Returns ``None`` when the file cannot be read.
    """
    try:
        stat = os.stat(path)
    except OSError:
        return None
    file_key = (path, int(stat.st_mtime_ns), int(stat.st_size))
    if _FBP_FRAME_STACK_FAILED_PATHS.get(path) == file_key:
        return None
    key = (*file_key, int(width), int(height), str(colorspace or ""), bool(is_data))
    cached = _FBP_FRAME_STACK_THUMBS.get(key)
    if cached is not None:
        _FBP_FRAME_STACK_THUMBS.move_to_end(key)
        return cached
    try:
        import numpy as np
        import OpenImageIO as oiio
        config = oiio.ImageSpec()
        # Keep straight alpha as stored, like Blender reads a PNG.
        config.attribute("oiio:UnassociatedAlpha", 1)
        source = oiio.ImageBuf(path, 0, 0, config)
        spec = source.spec()
        if source.has_error or spec.width < 1 or spec.height < 1:
            raise ValueError(source.geterror() or "unreadable image")
        roi = oiio.ROI(0, width, 0, height, 0, 1, 0, max(1, int(spec.nchannels)))
        small = oiio.ImageBufAlgo.resize(source, filtername="box", roi=roi)
        if small.has_error:
            raise ValueError(small.geterror())
        # Float files (EXR) arrive premultiplied, the others straight.
        is_float = str(spec.format).lower() in {"float", "half", "double"}
        pixels = np.asarray(small.get_pixels(oiio.FLOAT), dtype=np.float32)
        pixels = pixels.reshape(height, width, -1)
        channels = pixels.shape[2]
        rgba = np.ones((height, width, 4), dtype=np.float32)
        if channels >= 3:
            rgba[..., :3] = pixels[..., :3]
            if channels >= 4:
                rgba[..., 3] = pixels[..., 3]
        else:
            rgba[..., :3] = pixels[..., :1]
            if channels == 2:
                rgba[..., 3] = pixels[..., 1]
        if not is_float:
            # Quantize like the byte buffer Blender would hold.
            rgba = np.rint(np.clip(rgba, 0.0, 1.0) * 255.0) * (1.0 / 255.0)
        if not is_data and colorspace:
            if is_float:
                rgba = _fbp_frame_stack_convert_float(rgba, colorspace)
            else:
                lut = _fbp_frame_stack_byte_lut(colorspace)
                codes = np.rint(rgba[..., :3] * 255.0).astype(np.intp)
                rgb = lut[0][codes[..., 0]] + lut[1][codes[..., 1]] + lut[2][codes[..., 2]]
                rgba = np.concatenate([rgb.astype(np.float32), rgba[..., 3:4]], axis=-1)
        rgba = np.array(rgba[::-1], dtype=np.float32)
        if not is_float:
            # Match what the Geometry Image Texture node returns for a
            # straight byte image: Blender premultiplies it on conversion and
            # the node premultiplies once more, so soft edges keep the look
            # the Repeat Zone path always had.
            rgba[..., :3] *= rgba[..., 3:4] * rgba[..., 3:4]
        data = np.ascontiguousarray(rgba)
    except Exception as exc:  # OIIO raises its own error types.
        if not _FBP_FRAME_STACK_FAILED_PATHS:
            fbp_warn("Frame Stack could not read a thumbnail; using full frames", exc)
        if len(_FBP_FRAME_STACK_FAILED_PATHS) > 4096:
            _FBP_FRAME_STACK_FAILED_PATHS.clear()
        _FBP_FRAME_STACK_FAILED_PATHS[path] = file_key
        return None
    result = (data, width, height, key)
    _FBP_FRAME_STACK_THUMBS[key] = result
    _FBP_FRAME_STACK_THUMB_BYTES[0] += int(data.nbytes)
    while _FBP_FRAME_STACK_THUMB_BYTES[0] > _FBP_FRAME_STACK_THUMB_BUDGET and len(_FBP_FRAME_STACK_THUMBS) > 1:
        _old_key, old = _FBP_FRAME_STACK_THUMBS.popitem(last=False)
        _FBP_FRAME_STACK_THUMB_BYTES[0] -= int(old[0].nbytes)
    return result


def _fbp_frame_stack_slice_positions(position, cycle, loop, step, count):
    """Playback position of every slice, or ``None`` where it stays empty.

    Mirrors the Repeat Zone path: looping layers wrap around the cycle,
    otherwise positions before the first or past the last frame are empty.
    """
    result = []
    for index in range(count):
        q = int(position) - index * int(step)
        if loop and cycle > 0:
            q %= cycle
        if q < 0 or (cycle > 0 and q >= cycle):
            result.append(None)
        else:
            result.append(q)
    return result


def _fbp_frame_stack_prepare_cells_image(image, owner, width, height):
    """Create the float stack image or bring its size in line.

    The image is float and scene linear on purpose: once Geometry Nodes has
    sampled a byte image it carries a float buffer too, and later pixel
    writes land in that buffer without any colour conversion.
    """
    if image is not None and not bool(image.is_float):
        # A byte image from an earlier build. Removing image datablocks from
        # here is unsafe, so untag it and leave it to orphan cleanup.
        try:
            image["fbp_frame_stack_cells"] = False
            image.name = f"{image.name} (retired)"
        except FBP_DATA_ERRORS:
            pass
        image = None
    if image is None:
        image = bpy.data.images.new(
            f"FBP Frame Stack Cells • {owner}", width, height,
            alpha=True, float_buffer=True,
        )
        image.use_fake_user = False
        image["fbp_frame_stack_cells"] = True
        image["fbp_owned"] = True
        image["fbp_effect_material_owner"] = owner
    elif tuple(image.size) != (width, height):
        image.scale(width, height)
    _fbp_set_attr_if_changed(image, "alpha_mode", "PREMUL")
    return image


def _fbp_frame_stack_cells_image(rig, modifier, node_group, interface_inputs, material, timing, position):
    """Write one thumbnail per slice into the layer's stack image.

    Returns ``(image, columns, rows, cells, cell_width, cell_height)`` or
    ``None`` when the light path is unavailable (no OpenImageIO, unreadable
    files), in which case the group keeps decoding full frames.
    """
    plane = _fbp_plane(rig)
    paths = _fbp_frame_stack_source_paths(material) if material is not None else None
    if not plane or not paths or not timing:
        return None
    base, files = paths

    def socket_value(name, default):
        identifier = _fbp_interface_input_identifier(node_group, name)
        value = _fbp_modifier_input_get(modifier, identifier, None) if identifier else None
        return default if value is None else value

    try:
        count = max(1, min(512, int(socket_value("Slices", 1))))
        step = int(socket_value("Frame Step", 1))
        detail = max(0, min(8, int(socket_value("Detail", 5))))
    except (TypeError, ValueError):
        return None
    cycle = len(timing["files"])
    loop = timing["loop_mode"] in {"REPEAT", "PINGPONG"}
    slots = []
    for q in _fbp_frame_stack_slice_positions(position, cycle, loop, step, count):
        if q is None or not timing["visible"][q]:
            slots.append(None)
            continue
        index = int(timing["files"][q]) - int(base)
        if index < 0 or index >= len(files):
            slots.append(None)
            continue
        slots.append(files[index])
    reference = next((path for path in slots if path is not None), None)
    if reference is None:
        reference = files[0] if files else None
    source_size = _fbp_frame_stack_source_size(reference) if reference else None
    if source_size is None:
        return None
    cell_w, cell_h = _fbp_frame_stack_cell_size(source_size[0], source_size[1], detail)
    overflow = (count * cell_w * cell_h) / float(_FBP_FRAME_STACK_PIXEL_BUDGET)
    if overflow > 1.0:
        shrink = 1.0 / math.sqrt(overflow)
        cell_w = max(2, int(cell_w * shrink))
        cell_h = max(2, int(cell_h * shrink))
    _src_material, source_node = _fbp_material_image_node(rig)
    source_image = getattr(source_node, "image", None) if source_node else None
    try:
        settings = source_image.colorspace_settings if source_image else None
        colorspace = str(settings.name) if settings else "sRGB"
        is_data = bool(getattr(settings, "is_data", False)) if settings else False
    except FBP_DATA_ERRORS:
        colorspace, is_data = "sRGB", False
    thumbs = {}
    for path in slots:
        if path is None or path in thumbs:
            continue
        thumb = _fbp_frame_stack_thumbnail(path, cell_w, cell_h, colorspace, is_data)
        if thumb is None:
            return None
        thumbs[path] = thumb
    columns = max(1, int(math.ceil(math.sqrt(count))))
    rows = max(1, -(-count // columns))
    width, height = columns * cell_w, rows * cell_h

    owner = str(getattr(plane, "name", "") or "")
    try:
        image = _fbp_frame_stack_find_image("fbp_frame_stack_cells", owner)
        state = (width, height)
        key = int(image.as_pointer()) if image is not None else 0
        if image is None or _FBP_FRAME_STACK_IMAGE_STATE.get(key) != state:
            # Reading is_float or size acquires the image buffer, which costs
            # more than the rest of a playback frame: check only on changes.
            image = _fbp_frame_stack_prepare_cells_image(image, owner, width, height)
            key = int(image.as_pointer())
            if len(_FBP_FRAME_STACK_IMAGE_STATE) >= 256:
                _FBP_FRAME_STACK_IMAGE_STATE.clear()
            _FBP_FRAME_STACK_IMAGE_STATE[key] = state
        signature = (
            tuple(slots), columns, rows, cell_w, cell_h,
            tuple(sorted(thumb[3] for thumb in thumbs.values())),
        )
        if _FBP_FRAME_STACK_CELLS_CACHE.get(key) != signature:
            import numpy as np
            canvas = _FBP_FRAME_STACK_CANVASES.get(key)
            if canvas is None or canvas.shape != (height, width, 4):
                canvas = np.zeros((height, width, 4), dtype=np.float32)
                if len(_FBP_FRAME_STACK_CANVASES) >= 64:
                    _FBP_FRAME_STACK_CANVASES.clear()
                _FBP_FRAME_STACK_CANVASES[key] = canvas
            for index, path in enumerate(slots):
                column, row = index % columns, index // columns
                target = canvas[row * cell_h:(row + 1) * cell_h, column * cell_w:(column + 1) * cell_w]
                if path is None:
                    target.fill(0.0)
                else:
                    target[...] = thumbs[path][0]
            image.pixels.foreach_set(canvas.ravel())
            image.update()
            if len(_FBP_FRAME_STACK_CELLS_CACHE) >= 256:
                _FBP_FRAME_STACK_CELLS_CACHE.clear()
            _FBP_FRAME_STACK_CELLS_CACHE[key] = signature
    except (ImportError, *FBP_DATA_ERRORS) as exc:
        fbp_warn("Could not write the Frame Stack cells", exc)
        return None
    return image, columns, rows, count, cell_w, cell_h


def _fbp_sync_frame_stack_timing(rig, modifier, scene=None):
    """Point Frame Stack at the playback position of the layer's source.

    Slices step through what the plane plays, not through file numbers: an
    image sequence follows its timing order (reordered and repeated rows,
    loops, blank frames) through the timing table, a video steps through its
    frames. Fixed Range reads the position shown at the Start Frame.
    """
    node_group = getattr(modifier, "node_group", None) if modifier else None
    if not node_group:
        return False
    interface_inputs = _fbp_interface_inputs(node_group)
    if "Stack Position" not in interface_inputs:
        return False
    scene = scene or getattr(bpy.context, "scene", None)
    try:
        timeline_frame = int(getattr(scene, "frame_current", 1))
        if bool(getattr(rig, "fbp_frame_stack_fixed_start", False)):
            timeline_frame = int(getattr(rig, "fbp_frame_stack_start_frame", timeline_frame))
    except FBP_DATA_ERRORS:
        timeline_frame = 1
    material, source_node = _fbp_material_image_node(rig)
    try:
        source_image = getattr(source_node, "image", None) if source_node else None
        source_kind = str(getattr(source_image, "source", "") or "").upper()
        src_user = getattr(source_node, "image_user", None) if source_node else None
    except FBP_DATA_ERRORS:
        source_image, source_kind, src_user = None, "", None

    timing = (
        _fbp_frame_stack_native_timing(material)
        if source_kind == "SEQUENCE" and material is not None
        else None
    )
    table_image = None
    table_rows = 1
    if timing:
        from .native_backend import fbp_native_playback_position
        position = fbp_native_playback_position(timing, timeline_frame)
        cycle = len(timing["files"])
        loop = timing["loop_mode"] in {"REPEAT", "PINGPONG"}
    elif source_kind == "MOVIE" and src_user is not None:
        try:
            cycle = max(1, int(getattr(source_image, "frame_duration", 0) or 0))
            loop = bool(getattr(src_user, "use_cyclic", False))
        except FBP_DATA_ERRORS:
            cycle, loop = 0, False
        position = _fbp_geometry_image_frame(src_user, timeline_frame) - 1
        if cycle:
            position = position % cycle if loop else max(0, min(cycle - 1, position))
    elif source_kind == "SEQUENCE" and src_user is not None:
        # A sequence without native timing metadata steps through file numbers.
        position = _fbp_geometry_image_frame(src_user, timeline_frame) - 1
        cycle, loop = 0, False
    else:
        position, cycle, loop = 0, 1, False

    cells = None
    if timing and "Use Stack Image" in interface_inputs:
        cells = _fbp_frame_stack_cells_image(
            rig, modifier, node_group, interface_inputs, material, timing, position,
        )
    use_cells = cells is not None
    if timing and not use_cells:
        # Only the Repeat Zone path reads the timing table.
        table_image, table_rows = _fbp_frame_stack_table_image(rig, timing)
    use_table = table_image is not None
    changed = False
    cells_node = None
    try:
        cells_node = next(
            (node for node in node_group.nodes if bool(node.get("fbp_frame_stack_cells_node", False))),
            None,
        )
    except FBP_DATA_ERRORS:
        cells_node = None
    if cells_node is not None:
        image_input = _fbp_node_socket(getattr(cells_node, "inputs", ()), "Image")
        target = cells[0] if use_cells else None
        try:
            if image_input is not None and getattr(image_input, "default_value", None) is not target:
                image_input.default_value = target
                changed = True
        except FBP_DATA_ERRORS:
            use_cells = False
    else:
        use_cells = False
    if use_cells:
        _image, columns, rows, cell_count, cell_w, cell_h = cells
        for socket_name, value in (
            ("Stack Columns", int(columns)),
            ("Stack Rows", int(rows)),
            ("Stack Cells", int(cell_count)),
            ("Cell Width", int(cell_w)),
            ("Cell Height", int(cell_h)),
        ):
            changed = _fbp_set_modifier_input(
                modifier, node_group, socket_name, value, interface_inputs,
            ) or changed
    if "Use Stack Image" in interface_inputs:
        changed = _fbp_set_modifier_input(
            modifier, node_group, "Use Stack Image", bool(use_cells), interface_inputs,
        ) or changed
    table_node = None
    try:
        table_node = next(
            (node for node in node_group.nodes if bool(node.get("fbp_frame_stack_table_node", False))),
            None,
        )
    except FBP_DATA_ERRORS:
        table_node = None
    if table_node is not None:
        image_input = _fbp_node_socket(getattr(table_node, "inputs", ()), "Image")
        try:
            if image_input is not None and getattr(image_input, "default_value", None) is not table_image:
                image_input.default_value = table_image
                changed = True
        except FBP_DATA_ERRORS:
            use_table = False
    else:
        use_table = False
    for socket_name, value in (
        ("Stack Position", int(position)),
        ("Cycle Length", int(cycle)),
        ("Loop", bool(loop)),
        ("Frame Base", 1),
        ("Use Timing Table", bool(use_table)),
        ("Table Rows", int(table_rows)),
    ):
        changed = _fbp_set_modifier_input(
            modifier, node_group, socket_name, value, interface_inputs,
        ) or changed
    if changed:
        try:
            node_group.update_tag()
        except FBP_DATA_ERRORS:
            pass
    return changed


def fbp_sync_frame_stack_scene(scene):
    """Rebuild Frame Stack timing for every layer, e.g. after loading a file."""
    # Generated pixels are not saved: write every stack image again.
    _FBP_FRAME_STACK_CELLS_CACHE.clear()
    _FBP_FRAME_STACK_IMAGE_STATE.clear()
    try:
        from .layers import iter_scene_fbp_rigs
        rigs = tuple(iter_scene_fbp_rigs(scene))
    except (ImportError, *FBP_DATA_ERRORS):
        return False
    synced = False
    for rig in rigs:
        plane = _fbp_plane(rig)
        if not plane:
            continue
        try:
            modifiers = [
                modifier for modifier in plane.modifiers
                if getattr(modifier, "type", "") == "NODES"
                and _fbp_geometry_effect_id_for_modifier(modifier) == FBP_EFFECT_FRAME_STACK
            ]
        except FBP_DATA_ERRORS:
            continue
        for modifier in modifiers:
            if _fbp_sync_frame_stack_timing(rig, modifier, scene=scene):
                synced = True
                try:
                    plane.update_tag()
                except FBP_DATA_ERRORS:
                    pass
    return synced


def _fbp_sync_geometry_alpha_frame_offset(rig, scene=None, effect_modifiers=None):
    """Keep image-aware Geometry Nodes bound to the current FBP source.

    Besides sequence timing, this also refreshes the image datablock itself.
    Text Matrix therefore follows material/image replacements and every frame of
    native image sequences instead of retaining the image that was active when
    the modifier was first created.
    """
    plane = _fbp_plane(rig)
    if not plane:
        return False

    _source_material, source_node = _fbp_material_image_node(rig)
    try:
        source_image = getattr(source_node, "image", None) if source_node else None
        source_kind = str(getattr(source_image, "source", "") or "")
        src_user = getattr(source_node, "image_user", None) if source_node else None
    except FBP_DATA_ERRORS:
        source_image = None
        source_kind = ""
        src_user = None

    if effect_modifiers is None:
        resolved_modifiers = []
        try:
            for modifier in plane.modifiers:
                if getattr(modifier, "type", "") != "NODES":
                    continue
                tagged = _fbp_geometry_effect_id_for_modifier(modifier)
                if tagged in FBP_FRAME_SYNC_GEOMETRY_EFFECT_IDS:
                    resolved_modifiers.append(modifier)
        except FBP_DATA_ERRORS:
            return False
    else:
        resolved_modifiers = list(effect_modifiers or ())
    if not resolved_modifiers:
        return False

    scene = scene or getattr(bpy.context, "scene", None)
    scene_frame = int(getattr(scene, "frame_current", 1))
    sequence_frame = (
        _fbp_geometry_image_frame(src_user, scene_frame)
        if source_kind in {"SEQUENCE", "MOVIE"} and src_user is not None
        else 1
    )
    synced = False
    plane_changed = False

    for modifier in resolved_modifiers:
        node_group = getattr(modifier, "node_group", None)
        image_node = _fbp_alpha_image_node(node_group) if node_group else None
        if image_node is None:
            continue
        interface_inputs = _fbp_interface_inputs(node_group)
        changed = False
        try:
            image_input = _fbp_node_socket(getattr(image_node, "inputs", ()), "Image")
            if image_input is not None:
                if getattr(image_input, "default_value", None) is not source_image:
                    image_input.default_value = source_image
                    changed = True
            elif hasattr(image_node, "image") and getattr(image_node, "image", None) is not source_image:
                image_node.image = source_image
                changed = True

            is_text_matrix = bool(image_node.get("fbp_text_matrix_image_node", False))
            if source_node is not None:
                interpolation = "Closest" if is_text_matrix else getattr(source_node, "interpolation", None)
                extension = "EXTEND" if is_text_matrix else getattr(source_node, "extension", None)
                if interpolation is not None and getattr(image_node, "interpolation", None) != interpolation:
                    image_node.interpolation = interpolation
                    changed = True
                if extension is not None and getattr(image_node, "extension", None) != extension:
                    image_node.extension = extension
                    changed = True
                changed = _fbp_sync_geometry_plane_uv_sampling(
                    node_group, source_node, exclude=image_node
                ) or changed

            frame_input = _fbp_node_socket(getattr(image_node, "inputs", ()), "Frame")
            if frame_input is not None and int(getattr(frame_input, "default_value", 0) or 0) != sequence_frame:
                frame_input.default_value = sequence_frame
                changed = True
            if "Source Frame" in interface_inputs:
                changed = _fbp_set_modifier_input(
                    modifier, node_group, "Source Frame", sequence_frame, interface_inputs,
                ) or changed
            if "Stack Position" in interface_inputs:
                # Frame Stack derives one frame per slice from the playback position.
                changed = _fbp_sync_frame_stack_timing(rig, modifier, scene=scene) or changed

            if "Use Alpha Mask" in interface_inputs:
                changed = _fbp_set_modifier_input(
                    modifier,
                    node_group,
                    "Use Alpha Mask",
                    bool(source_image),
                    interface_inputs,
                ) or changed

            if changed:
                node_group.update_tag()
                plane_changed = True
            synced = bool(source_image) or synced or changed
        except FBP_DATA_ERRORS:
            continue
    if plane_changed:
        try:
            plane.update_tag()
        except FBP_DATA_ERRORS:
            pass
    return synced

def _fbp_owned_geometry_group(rig, effect_id, source_group, current=None):
    plane = _fbp_plane(rig)
    if not plane or not source_group:
        return None
    effect_id = fbp_normalize_effect_id(effect_id)
    definition = fbp_effect_definition(effect_id)
    asset_id = str(definition.get("asset_id", "") or "")
    canonical_source = source_group
    try:
        if bool(source_group.get("fbp_private_effect_group", False)):
            canonical_source = next(
                iter(_fbp_effect_groups_by_asset(asset_id)), source_group
            )
    except FBP_DATA_ERRORS:
        canonical_source = source_group
    owner = str(getattr(plane, "name", "") or "")
    owner_id = _fbp_effect_stack_owner_id(rig)
    desired_name = f"{canonical_source.name} • {owner}"

    def matches(candidate):
        if candidate is None:
            return False
        try:
            if not bool(candidate.get("fbp_private_effect_group", False)):
                return False
            stored_owner_id = str(
                candidate.get(FBP_PRIVATE_EFFECT_OWNER_ID_KEY, "") or ""
            )
            if stored_owner_id:
                if stored_owner_id != owner_id:
                    return False
            elif str(candidate.get("fbp_effect_owner", "") or "") != owner:
                return False
            tagged_effect = fbp_normalize_effect_id(
                candidate.get("fbp_effect_id", "")
            )
            tagged_asset = str(candidate.get("fbp_effect_asset_id", "") or "")
            current_match = tagged_effect == effect_id and tagged_asset == asset_id
            quarantined_recovery = bool(candidate.get("fbp_quarantined", False)) and str(
                getattr(candidate, "name", "") or ""
            ).startswith(desired_name)
            return bool(
                current_match
                or (
                    quarantined_recovery
                    and _builtin_group_is_complete(candidate, definition)
                )
            )
        except FBP_DATA_ERRORS:
            return False

    candidate = current if matches(current) else None
    if candidate is None:
        for item in tuple(bpy.data.node_groups):
            if matches(item):
                candidate = item
                break
    if candidate is not None:
        if bool(candidate.get("fbp_quarantined", False)):
            candidate = _fbp_reactivate_private_effect_group(
                candidate,
                effect_id=effect_id,
                asset_id=asset_id,
                owner=owner,
                owner_id=owner_id,
                owner_kind="GEOMETRY",
                desired_name=desired_name,
            )
        if candidate is not None:
            _fbp_refresh_private_effect_group_identity(
                candidate,
                owner=owner,
                owner_id=owner_id,
                owner_kind="GEOMETRY",
                desired_name=desired_name,
            )
            # Effects with their own alpha-geometry contract already build and
            # sample a dedicated cutout mesh. Applying the generic alpha patch
            # would insert a second mask in front of that graph.
            if (
                not bool(definition.get("alpha_aware"))
                or bool(definition.get("requires_alpha_geometry_contract"))
                or _fbp_patch_alpha_mask(candidate)
            ):
                return candidate

    try:
        node_group = canonical_source.copy()
        node_group.name = desired_name
        node_group.use_fake_user = False
        node_group["fbp_effect_id"] = effect_id
        node_group["fbp_effect_asset_id"] = asset_id
        node_group["fbp_effect_schema_version"] = FBP_EFFECT_SCHEMA_VERSION
        node_group["fbp_effect_owner"] = owner
        node_group[FBP_PRIVATE_EFFECT_OWNER_ID_KEY] = owner_id
        node_group["fbp_private_effect_group"] = True
        if (
            bool(definition.get("alpha_aware"))
            and not bool(definition.get("requires_alpha_geometry_contract"))
        ):
            if not _fbp_patch_alpha_mask(node_group):
                _fbp_remove_node_group(node_group)
                return None
        fbp_tidy_effect_group(node_group, effect_id)
        return node_group
    except FBP_DATA_ERRORS as exc:
        fbp_warn("Could not create alpha-aware effect group", exc)
        return None

def _fbp_find_owned_effect_material(rig, effect_id, label=""):
    plane = _fbp_plane(rig)
    owner = str(getattr(plane, "name", "") or "")
    effect_id = fbp_normalize_effect_id(effect_id)
    role = str(label or "")

    # Current materials use a deterministic name. Resolve that directly before
    # falling back to a global scan, which is costly during animated effects.
    if role and owner:
        try:
            candidate = bpy.data.materials.get(f"FBP {role} • {owner}")
            if (
                candidate
                and candidate.get("fbp_effect_material_owner", "") == owner
                and fbp_normalize_effect_id(candidate.get("fbp_effect_material_id", "")) == effect_id
            ):
                return candidate
        except FBP_DATA_ERRORS:
            pass

    for material in bpy.data.materials:
        try:
            if (
                material.get("fbp_effect_material_owner", "") == owner
                and fbp_normalize_effect_id(material.get("fbp_effect_material_id", "")) == effect_id
                and (not role or str(material.get("fbp_effect_material_role", "") or "") == role)
            ):
                return material
        except FBP_DATA_ERRORS:
            continue
    return None


def _fbp_ensure_owned_effect_material(rig, effect_id, label, color):
    """Create one lightweight solid material owned by an effect on one plane."""
    plane = _fbp_plane(rig)
    if not plane:
        return None
    owner = str(getattr(plane, "name", "") or "")
    effect_id = fbp_normalize_effect_id(effect_id)
    material = _fbp_find_owned_effect_material(rig, effect_id, label)
    if material is None:
        try:
            material = bpy.data.materials.new(name=f"FBP {label} • {owner}")
            material.use_fake_user = False
            material["fbp_owned"] = True
            material["fbp_effect_material_owner"] = owner
            material["fbp_effect_material_id"] = effect_id
            material["fbp_effect_material_role"] = str(label or "")
        except FBP_DATA_ERRORS as exc:
            fbp_warn(f"Could not create {label} material", exc)
            return None

    try:
        color = tuple(color)
        if not _fbp_effect_values_equal(getattr(material, "diffuse_color", ()), color):
            material.diffuse_color = color
        node_tree = material.node_tree
        if not node_tree:
            node_tree = material.node_tree
        nodes = node_tree.nodes
        links = node_tree.links
        principled = next(
            (node for node in nodes if getattr(node, "type", "") == "BSDF_PRINCIPLED"),
            None,
        )
        output = next(
            (node for node in nodes if getattr(node, "type", "") == "OUTPUT_MATERIAL"),
            None,
        )
        if principled is None:
            principled = nodes.new("ShaderNodeBsdfPrincipled")
            principled.name = "FBP Effect Material"
        if output is None:
            output = nodes.new("ShaderNodeOutputMaterial")
        base_color = _fbp_node_socket(principled.inputs, "Base Color")
        roughness = _fbp_node_socket(principled.inputs, "Roughness")
        metallic = _fbp_node_socket(principled.inputs, "Metallic")
        if base_color is not None and not _fbp_effect_values_equal(base_color.default_value, color):
            base_color.default_value = color
        if roughness is not None and not _fbp_effect_values_equal(roughness.default_value, 0.8):
            roughness.default_value = 0.8
        if metallic is not None and not _fbp_effect_values_equal(metallic.default_value, 0.0):
            metallic.default_value = 0.0
        surface = _fbp_node_socket(output.inputs, "Surface")
        bsdf = _fbp_node_socket(principled.outputs, "BSDF")
        if surface is not None and bsdf is not None:
            linked = (
                len(surface.links) == 1
                and surface.links[0].from_socket == bsdf
            )
            if not linked:
                for link in list(surface.links):
                    links.remove(link)
                links.new(bsdf, surface)
        if material.get("fbp_effect_material_owner", "") != owner:
            material["fbp_effect_material_owner"] = owner
        if fbp_normalize_effect_id(material.get("fbp_effect_material_id", "")) != effect_id:
            material["fbp_effect_material_id"] = effect_id
        role = str(label or "")
        if str(material.get("fbp_effect_material_role", "") or "") != role:
            material["fbp_effect_material_role"] = role
        try:
            if material.surface_render_method != "DITHERED":
                material.surface_render_method = "DITHERED"
            if material.use_transparency_overlap:
                material.use_transparency_overlap = False
        except FBP_DATA_ERRORS:
            pass
    except FBP_DATA_ERRORS as exc:
        fbp_warn(f"Could not update {label} material", exc)
    return material


def _fbp_ensure_attribute_color_material(
    rig,
    effect_id,
    role,
    attribute_name,
    *,
    emission_strength=0.0,
):
    """Create one instancer-attribute material for sampled source-image color."""
    plane = _fbp_plane(rig)
    if not plane:
        return None
    owner = str(getattr(plane, "name", "") or "")
    effect_id = fbp_normalize_effect_id(effect_id)
    role = str(role or "Sampled Color")
    attribute_name = str(attribute_name or "fbp_source_color")
    material = _fbp_find_owned_effect_material(rig, effect_id, role)
    if material is None:
        try:
            material = bpy.data.materials.new(name=f"FBP {role} • {owner}")
            material.use_fake_user = False
        except FBP_DATA_ERRORS as exc:
            fbp_warn(f"Could not create {role} material", exc)
            return None

    try:
        _fbp_set_attr_if_changed(material, "diffuse_color", (1.0, 1.0, 1.0, 1.0))
        _fbp_set_idprop_if_changed(material, "fbp_owned", True)
        _fbp_set_idprop_if_changed(material, "fbp_effect_material_owner", owner)
        _fbp_set_idprop_if_changed(material, "fbp_effect_material_id", effect_id)
        _fbp_set_idprop_if_changed(material, "fbp_effect_material_role", role)
        _fbp_set_idprop_if_changed(material, "fbp_attribute_color_name", attribute_name)
        node_tree = material.node_tree
        nodes = node_tree.nodes
        links = node_tree.links
        attribute = nodes.get("FBP Sampled Instance Color")
        principled = nodes.get("FBP Sampled Color Surface")
        output = nodes.get("FBP Sampled Color Output")
        structure_version = int(material.get("fbp_attribute_material_version", 0) or 0)
        if structure_version != 1 or attribute is None or principled is None or output is None:
            nodes.clear()
            attribute = nodes.new("ShaderNodeAttribute")
            attribute.name = "FBP Sampled Instance Color"
            attribute.label = "Sampled Source Color"
            principled = nodes.new("ShaderNodeBsdfPrincipled")
            principled.name = "FBP Sampled Color Surface"
            output = nodes.new("ShaderNodeOutputMaterial")
            output.name = "FBP Sampled Color Output"
            attribute.location = (-420.0, 40.0)
            principled.location = (-140.0, 40.0)
            output.location = (160.0, 40.0)
            links.new(attribute.outputs["Color"], principled.inputs["Base Color"])
            emission_color = _fbp_node_socket(principled.inputs, "Emission Color")
            if emission_color is not None:
                links.new(attribute.outputs["Color"], emission_color)
            links.new(principled.outputs["BSDF"], output.inputs["Surface"])
            material["fbp_attribute_material_version"] = 1

        _fbp_set_attr_if_changed(attribute, "attribute_name", attribute_name)
        if hasattr(attribute, "attribute_type"):
            _fbp_set_attr_if_changed(attribute, "attribute_type", "INSTANCER")
        roughness = _fbp_node_socket(principled.inputs, "Roughness")
        metallic = _fbp_node_socket(principled.inputs, "Metallic")
        emission = _fbp_node_socket(principled.inputs, "Emission Strength")
        _fbp_set_socket_default_if_changed(roughness, 0.55)
        _fbp_set_socket_default_if_changed(metallic, 0.0)
        _fbp_set_socket_default_if_changed(
            emission, max(0.0, float(emission_strength or 0.0))
        )
        _fbp_set_attr_if_changed(material, "surface_render_method", "DITHERED")
        _fbp_set_attr_if_changed(material, "use_transparency_overlap", False)
    except FBP_DATA_ERRORS as exc:
        fbp_warn(f"Could not update {role} sampled-color material", exc)
    return material


def _fbp_ensure_frame_stack_material(rig):
    """Shadeless material for Frame Stack slices and outline.

    Colour, alpha and Glow come from attributes written by the effect, so the
    material never needs rebuilding. Over mixes Emission with Transparent by
    alpha; Glow adds the emission over a transparent surface, which does not
    depend on draw order and stays noise-free in Eevee.
    """
    plane = _fbp_plane(rig)
    if not plane:
        return None
    owner = str(getattr(plane, "name", "") or "")
    role = "Frame Stack"
    material = _fbp_find_owned_effect_material(rig, FBP_EFFECT_FRAME_STACK, role)
    if material is None:
        try:
            material = bpy.data.materials.new(name=f"FBP {role} • {owner}")
            material.use_fake_user = False
        except FBP_DATA_ERRORS as exc:
            fbp_warn("Could not create Frame Stack material", exc)
            return None
    try:
        _fbp_set_idprop_if_changed(material, "fbp_owned", True)
        _fbp_set_idprop_if_changed(material, "fbp_effect_material_owner", owner)
        _fbp_set_idprop_if_changed(material, "fbp_effect_material_id", FBP_EFFECT_FRAME_STACK)
        _fbp_set_idprop_if_changed(material, "fbp_effect_material_role", role)
        if int(material.get("fbp_frame_stack_material_version", 0) or 0) != 1:
            node_tree = material.node_tree
            nodes = node_tree.nodes
            links = node_tree.links
            nodes.clear()

            def attribute(name, label, y):
                node = nodes.new("ShaderNodeAttribute")
                node.name = label
                node.label = label
                node.attribute_type = "GEOMETRY"
                node.attribute_name = name
                node.location = (-700.0, y)
                return node

            color = attribute("fbp_frame_stack_color", "FBP Frame Stack Color", 200.0)
            alpha = attribute("fbp_frame_stack_alpha", "FBP Frame Stack Alpha", 0.0)
            glow = attribute("fbp_frame_stack_glow", "FBP Frame Stack Glow", -200.0)
            emission = nodes.new("ShaderNodeEmission")
            emission.location = (-420.0, 200.0)
            glow_emission = nodes.new("ShaderNodeEmission")
            glow_emission.location = (-420.0, -40.0)
            transparent = nodes.new("ShaderNodeBsdfTransparent")
            transparent.location = (-420.0, -260.0)
            over = nodes.new("ShaderNodeMixShader")
            over.location = (-160.0, 120.0)
            add = nodes.new("ShaderNodeAddShader")
            add.location = (-160.0, -120.0)
            result = nodes.new("ShaderNodeMixShader")
            result.location = (80.0, 0.0)
            output = nodes.new("ShaderNodeOutputMaterial")
            output.location = (320.0, 0.0)
            links.new(color.outputs["Color"], emission.inputs["Color"])
            links.new(color.outputs["Color"], glow_emission.inputs["Color"])
            links.new(alpha.outputs["Fac"], glow_emission.inputs["Strength"])
            links.new(alpha.outputs["Fac"], over.inputs["Fac"])
            links.new(transparent.outputs["BSDF"], over.inputs[1])
            links.new(emission.outputs["Emission"], over.inputs[2])
            links.new(transparent.outputs["BSDF"], add.inputs[0])
            links.new(glow_emission.outputs["Emission"], add.inputs[1])
            links.new(glow.outputs["Fac"], result.inputs["Fac"])
            links.new(over.outputs["Shader"], result.inputs[1])
            links.new(add.outputs["Shader"], result.inputs[2])
            links.new(result.outputs["Shader"], output.inputs["Surface"])
            material["fbp_frame_stack_material_version"] = 1
        _fbp_set_attr_if_changed(material, "surface_render_method", "DITHERED")
        _fbp_set_attr_if_changed(material, "use_transparency_overlap", False)
    except FBP_DATA_ERRORS as exc:
        fbp_warn("Could not update Frame Stack material", exc)
    return material


def _fbp_ensure_knit_crochet_material(rig):
    """Wool material for Knit & Crochet, driven by per-stitch attributes.

    ``fbp_yarn_color`` is the sampled stitch colour and ``fbp_yarn_shading``
    carries Fuzz (sheen) and Self Light, so the material never needs a
    rebuild. Self Light is an emission lit by a fixed key direction, which
    keeps the twisted plies readable in unlit Frame By Plane scenes.
    """
    plane = _fbp_plane(rig)
    if not plane:
        return None
    owner = str(getattr(plane, "name", "") or "")
    role = "Knit & Crochet"
    material = _fbp_find_owned_effect_material(rig, FBP_EFFECT_KNIT_CROCHET, role)
    if material is None:
        try:
            material = bpy.data.materials.new(name=f"FBP {role} • {owner}")
            material.use_fake_user = False
        except FBP_DATA_ERRORS as exc:
            fbp_warn("Could not create Knit & Crochet material", exc)
            return None
    try:
        _fbp_set_idprop_if_changed(material, "fbp_owned", True)
        _fbp_set_idprop_if_changed(material, "fbp_effect_material_owner", owner)
        _fbp_set_idprop_if_changed(material, "fbp_effect_material_id", FBP_EFFECT_KNIT_CROCHET)
        _fbp_set_idprop_if_changed(material, "fbp_effect_material_role", role)
        if int(material.get("fbp_yarn_material_version", 0) or 0) != 1:
            node_tree = material.node_tree
            nodes = node_tree.nodes
            links = node_tree.links
            nodes.clear()
            color = nodes.new("ShaderNodeAttribute")
            color.attribute_type = "INSTANCER"
            color.attribute_name = "fbp_yarn_color"
            color.location = (-900.0, 300.0)
            shading = nodes.new("ShaderNodeAttribute")
            shading.attribute_type = "INSTANCER"
            shading.attribute_name = "fbp_yarn_shading"
            shading.location = (-900.0, 0.0)
            split = nodes.new("ShaderNodeSeparateXYZ")
            split.location = (-680.0, 0.0)
            links.new(shading.outputs["Vector"], split.inputs[0])
            noise = nodes.new("ShaderNodeTexNoise")
            noise.location = (-900.0, -300.0)
            noise.inputs["Scale"].default_value = 600.0
            noise.inputs["Detail"].default_value = 4.0
            bump = nodes.new("ShaderNodeBump")
            bump.location = (-680.0, -300.0)
            bump.inputs["Strength"].default_value = 0.25
            links.new(noise.outputs["Fac"], bump.inputs["Height"])
            principled = nodes.new("ShaderNodeBsdfPrincipled")
            principled.location = (-420.0, 300.0)
            principled.inputs["Roughness"].default_value = 0.9
            principled.inputs["Sheen Roughness"].default_value = 0.45
            links.new(color.outputs["Color"], principled.inputs["Base Color"])
            links.new(split.outputs["X"], principled.inputs["Sheen Weight"])
            links.new(bump.outputs["Normal"], principled.inputs["Normal"])
            key = nodes.new("ShaderNodeVectorMath")
            key.operation = "DOT_PRODUCT"
            key.location = (-420.0, -200.0)
            key.inputs[1].default_value = (-0.35, 0.55, 0.76)
            links.new(bump.outputs["Normal"], key.inputs[0])
            lit = nodes.new("ShaderNodeMapRange")
            lit.location = (-200.0, -200.0)
            lit.inputs["From Min"].default_value = -0.2
            lit.inputs["To Min"].default_value = 0.25
            links.new(key.outputs["Value"], lit.inputs["Value"])
            lit_color = nodes.new("ShaderNodeVectorMath")
            lit_color.operation = "SCALE"
            lit_color.location = (20.0, -100.0)
            links.new(color.outputs["Color"], lit_color.inputs[0])
            links.new(lit.outputs["Result"], lit_color.inputs["Scale"])
            emission = nodes.new("ShaderNodeEmission")
            emission.location = (240.0, -100.0)
            links.new(lit_color.outputs["Vector"], emission.inputs["Color"])
            links.new(split.outputs["Y"], emission.inputs["Strength"])
            add = nodes.new("ShaderNodeAddShader")
            add.location = (460.0, 100.0)
            links.new(principled.outputs["BSDF"], add.inputs[0])
            links.new(emission.outputs["Emission"], add.inputs[1])
            output = nodes.new("ShaderNodeOutputMaterial")
            output.location = (680.0, 100.0)
            links.new(add.outputs["Shader"], output.inputs["Surface"])
            material["fbp_yarn_material_version"] = 1
    except FBP_DATA_ERRORS as exc:
        fbp_warn("Could not update Knit & Crochet material", exc)
    return material


def _fbp_sync_volume_output(node_tree, volume_node, output_node, enabled):
    """Connect volume shading only while it can contribute to the render."""
    if node_tree is None or volume_node is None or output_node is None:
        return False
    volume_input = _fbp_node_socket(output_node.inputs, "Volume")
    volume_output = _fbp_node_socket(volume_node.outputs, "Volume")
    if volume_input is None or volume_output is None:
        return False
    expected = None
    changed = False
    for link in tuple(volume_input.links):
        if bool(enabled) and link.from_socket == volume_output and expected is None:
            expected = link
            continue
        try:
            node_tree.links.remove(link)
            changed = True
        except FBP_DATA_ERRORS:
            pass
    if bool(enabled) and expected is None:
        try:
            node_tree.links.new(volume_output, volume_input)
            changed = True
        except FBP_DATA_ERRORS:
            pass
    return changed


def _fbp_ensure_glass_material(rig):
    """Create and synchronize the Broken Glass refractive material."""
    plane = _fbp_plane(rig)
    if not plane:
        return None
    owner = str(getattr(plane, "name", "") or "")
    role = "Broken Glass"
    material = _fbp_find_owned_effect_material(rig, FBP_EFFECT_GLASS, role)
    if material is None:
        # Reuse the material created by 6.10's former Glass effect so upgrading
        # a file does not leave a detached owned material behind.
        material = _fbp_find_owned_effect_material(rig, FBP_EFFECT_GLASS, "Glass")
        if material is not None:
            try:
                material["fbp_effect_material_role"] = role
                material.name = f"FBP {role} • {owner}"
            except FBP_DATA_ERRORS:
                pass
    if material is None:
        try:
            material = bpy.data.materials.new(name=f"FBP {role} • {owner}")
            material.use_fake_user = False
        except FBP_DATA_ERRORS as exc:
            fbp_warn("Could not create Broken Glass material", exc)
            return None

    try:
        _fbp_set_idprop_if_changed(material, "fbp_owned", True)
        _fbp_set_idprop_if_changed(material, "fbp_effect_material_owner", owner)
        _fbp_set_idprop_if_changed(material, "fbp_effect_material_id", FBP_EFFECT_GLASS)
        _fbp_set_idprop_if_changed(material, "fbp_effect_material_role", role)
        node_tree = material.node_tree
        nodes = node_tree.nodes
        links = node_tree.links
        required = (
            "FBP Glass Source Color", "FBP Glass Alpha", "FBP Glass Height",
            "FBP Glass Normal", "FBP Glass Tint",
            "FBP Glass Source Mix", "FBP Glass Edge Fresnel", "FBP Glass Edge Facing Invert",
            "FBP Glass Edge Tint Strength", "FBP Glass Edge Tint Mix",
            "FBP Glass Normal Map", "FBP Glass Bump",
            "FBP Glass Normal Select", "FBP Glass Volume Absorption",
            "FBP Glass Surface", "FBP Glass Transparent", "FBP Glass Alpha Mix",
            "FBP Glass Output",
        )
        structure_version = int(material.get("fbp_glass_material_version", 0) or 0)
        if structure_version != 6 or any(nodes.get(name) is None for name in required):
            nodes.clear()
            source_color = nodes.new("ShaderNodeAttribute")
            source_color.name = "FBP Glass Source Color"
            source_color.attribute_name = "fbp_glass_color"
            alpha = nodes.new("ShaderNodeAttribute")
            alpha.name = "FBP Glass Alpha"
            alpha.attribute_name = "fbp_glass_alpha"
            height = nodes.new("ShaderNodeAttribute")
            height.name = "FBP Glass Height"
            height.attribute_name = "fbp_glass_height"
            normal = nodes.new("ShaderNodeAttribute")
            normal.name = "FBP Glass Normal"
            normal.attribute_name = "fbp_glass_normal"
            tint = nodes.new("ShaderNodeRGB")
            tint.name = "FBP Glass Tint"
            source_mix = nodes.new("ShaderNodeMixRGB")
            source_mix.name = "FBP Glass Source Mix"
            source_mix.blend_type = "MIX"
            edge_fresnel = nodes.new("ShaderNodeLayerWeight")
            edge_fresnel.name = "FBP Glass Edge Fresnel"
            edge_inverse = nodes.new("ShaderNodeMath")
            edge_inverse.name = "FBP Glass Edge Facing Invert"
            edge_inverse.operation = "SUBTRACT"
            edge_inverse.inputs[0].default_value = 1.0
            edge_strength = nodes.new("ShaderNodeMath")
            edge_strength.name = "FBP Glass Edge Tint Strength"
            edge_strength.operation = "MULTIPLY"
            edge_mix = nodes.new("ShaderNodeMixRGB")
            edge_mix.name = "FBP Glass Edge Tint Mix"
            edge_mix.blend_type = "MIX"
            normal_map = nodes.new("ShaderNodeNormalMap")
            normal_map.name = "FBP Glass Normal Map"
            normal_map.space = "TANGENT"
            bump = nodes.new("ShaderNodeBump")
            bump.name = "FBP Glass Bump"
            normal_select = nodes.new("ShaderNodeMixRGB")
            normal_select.name = "FBP Glass Normal Select"
            normal_select.blend_type = "MIX"
            # Principled transmission is shared by Eevee and Cycles in Blender
            # 5.2. It gives Broken Glass a useful real-time preview while Cycles
            # remains available for physically accurate background refraction.
            glass = nodes.new("ShaderNodeBsdfPrincipled")
            glass.name = "FBP Glass Surface"
            glass.inputs["Transmission Weight"].default_value = 1.0
            glass.inputs["Thin Wall"].default_value = False
            absorption = nodes.new("ShaderNodeVolumeAbsorption")
            absorption.name = "FBP Glass Volume Absorption"
            transparent = nodes.new("ShaderNodeBsdfTransparent")
            transparent.name = "FBP Glass Transparent"
            mix = nodes.new("ShaderNodeMixShader")
            mix.name = "FBP Glass Alpha Mix"
            output = nodes.new("ShaderNodeOutputMaterial")
            output.name = "FBP Glass Output"

            source_color.location = (-900.0, 300.0)
            alpha.location = (-650.0, -520.0)
            height.location = (-900.0, -120.0)
            normal.location = (-900.0, 40.0)
            tint.location = (-900.0, 520.0)
            source_mix.location = (-380.0, 360.0)
            edge_fresnel.location = (-380.0, 600.0)
            edge_inverse.location = (-160.0, 600.0)
            edge_strength.location = (40.0, 600.0)
            edge_mix.location = (260.0, 440.0)
            normal_map.location = (-620.0, 20.0)
            bump.location = (-360.0, -80.0)
            normal_select.location = (-80.0, 20.0)
            glass.location = (520.0, 260.0)
            absorption.location = (520.0, -40.0)
            transparent.location = (520.0, -240.0)
            mix.location = (760.0, 160.0)
            output.location = (1020.0, 160.0)

            links.new(tint.outputs["Color"], source_mix.inputs[1])
            # Source Color = 1 must mean the unmodified source, not source ×
            # Tint. The old multiply made Tint permanently visible at 100%.
            links.new(source_color.outputs["Color"], source_mix.inputs[2])
            links.new(edge_fresnel.outputs["Facing"], edge_inverse.inputs[1])
            links.new(edge_inverse.outputs[0], edge_strength.inputs[0])
            links.new(edge_strength.outputs[0], edge_mix.inputs[0])
            links.new(source_mix.outputs["Color"], edge_mix.inputs[1])
            links.new(tint.outputs["Color"], edge_mix.inputs[2])
            links.new(edge_mix.outputs["Color"], glass.inputs["Base Color"])
            links.new(normal.outputs["Color"], normal_map.inputs["Color"])
            links.new(height.outputs["Fac"], bump.inputs["Height"])
            links.new(bump.outputs["Normal"], normal_select.inputs[1])
            links.new(normal_map.outputs["Normal"], normal_select.inputs[2])
            links.new(normal_select.outputs["Color"], glass.inputs["Normal"])
            links.new(tint.outputs["Color"], absorption.inputs["Color"])
            links.new(alpha.outputs["Fac"], mix.inputs[0])
            links.new(transparent.outputs["BSDF"], mix.inputs[1])
            links.new(glass.outputs["BSDF"], mix.inputs[2])
            links.new(mix.outputs["Shader"], output.inputs["Surface"])
            links.new(absorption.outputs["Volume"], output.inputs["Volume"])
            material["fbp_glass_material_version"] = 6
            organize_node_tree(node_tree)

        tint = tuple(getattr(rig, "fbp_glass_tint", (0.72, 0.92, 1.0, 1.0)))
        source_factor = max(0.0, min(1.0, float(getattr(rig, "fbp_glass_source_color", 0.35) or 0.0)))
        tint_weight = 1.0 - source_factor
        roughness = max(0.0, min(1.0, float(getattr(rig, "fbp_glass_roughness", 0.12) or 0.0)))
        ior = max(1.0, float(getattr(rig, "fbp_glass_ior", 1.45) or 1.45))
        edge_tint = max(0.0, min(1.0, float(getattr(rig, "fbp_glass_edge_tint", 0.55) or 0.0)))
        absorption_density = max(0.0, float(getattr(rig, "fbp_glass_absorption", 0.35) or 0.0))
        tint_node = nodes.get("FBP Glass Tint")
        source_mix = nodes.get("FBP Glass Source Mix")
        normal_map = nodes.get("FBP Glass Normal Map")
        bump = nodes.get("FBP Glass Bump")
        normal_select = nodes.get("FBP Glass Normal Select")
        edge_strength = nodes.get("FBP Glass Edge Tint Strength")
        absorption = nodes.get("FBP Glass Volume Absorption")
        glass = nodes.get("FBP Glass Surface")
        _fbp_set_socket_default_if_changed(tint_node.outputs["Color"], tint)
        _fbp_set_socket_default_if_changed(source_mix.inputs[0], source_factor)
        _fbp_set_socket_default_if_changed(normal_map.inputs["Strength"], 0.0)
        _fbp_set_socket_default_if_changed(normal_select.inputs[0], 0.0)
        # Shards are flat triangles, so there is no crack height to bump.
        _fbp_set_socket_default_if_changed(bump.inputs["Strength"], 0.0)
        _fbp_set_socket_default_if_changed(bump.inputs["Distance"], 0.1)
        _fbp_set_socket_default_if_changed(edge_strength.inputs[1], edge_tint * tint_weight)
        # At Source Color 100%, Tint is absent from both the surface and the
        # volume. Otherwise absorption would keep a residual color cast.
        _fbp_set_socket_default_if_changed(absorption.inputs["Density"], absorption_density * tint_weight)
        _fbp_set_socket_default_if_changed(glass.inputs["Roughness"], roughness)
        _fbp_set_socket_default_if_changed(glass.inputs["IOR"], ior)
        glass_thickness = max(
            0.0, float(getattr(rig, "fbp_glass_thickness", 0.0) or 0.0)
        )
        _fbp_sync_volume_output(
            node_tree,
            absorption,
            nodes.get("FBP Glass Output"),
            absorption_density * tint_weight > 1.0e-6 and glass_thickness > 1.0e-6,
        )
        _fbp_set_attr_if_changed(
            material,
            "diffuse_color",
            tuple(
                (float(tint[index]) * tint_weight) + source_factor
                for index in range(3)
            ) + ((float(tint[3]) * tint_weight) + source_factor,),
        )
        _fbp_set_attr_if_changed(material, "surface_render_method", "DITHERED")
        _fbp_set_attr_if_changed(material, "use_transparency_overlap", False)
    except FBP_DATA_ERRORS as exc:
        fbp_warn("Could not update Broken Glass material", exc)
    return material


def _fbp_ensure_crystal_material(rig):
    """Create one source-colored refractive Crystal material per layer."""
    plane = _fbp_plane(rig)
    if not plane:
        return None
    owner = str(getattr(plane, "name", "") or "")
    role = "Crystal"
    material = _fbp_find_owned_effect_material(rig, FBP_EFFECT_CRYSTAL, role)
    if material is None:
        try:
            material = bpy.data.materials.new(name=f"FBP {role} • {owner}")
            material.use_fake_user = False
        except FBP_DATA_ERRORS as exc:
            fbp_warn("Could not create Crystal material", exc)
            return None

    try:
        _fbp_set_idprop_if_changed(material, "fbp_owned", True)
        _fbp_set_idprop_if_changed(material, "fbp_effect_material_owner", owner)
        _fbp_set_idprop_if_changed(material, "fbp_effect_material_id", FBP_EFFECT_CRYSTAL)
        _fbp_set_idprop_if_changed(material, "fbp_effect_material_role", role)
        node_tree = material.node_tree
        nodes = node_tree.nodes
        links = node_tree.links
        required = (
            "FBP Crystal Source Color",
            "FBP Crystal Pattern", "FBP Crystal Influence", "FBP Crystal Tint",
            "FBP Crystal Source Mix",
            "FBP Crystal Distortion Mask", "FBP Crystal Bump",
            "FBP Crystal Opaque Surface", "FBP Crystal Surface",
            "FBP Crystal Surface Mix", "FBP Crystal Absorption", "FBP Crystal Output",
        )
        if (
            int(material.get("fbp_crystal_material_version", 0) or 0) != 6
            or any(nodes.get(name) is None for name in required)
        ):
            nodes.clear()
            source_color = nodes.new("ShaderNodeAttribute")
            source_color.name = "FBP Crystal Source Color"
            source_color.attribute_name = "fbp_crystal_color"
            pattern = nodes.new("ShaderNodeAttribute")
            pattern.name = "FBP Crystal Pattern"
            pattern.attribute_name = "fbp_crystal_pattern"
            influence = nodes.new("ShaderNodeAttribute")
            influence.name = "FBP Crystal Influence"
            influence.attribute_name = "fbp_crystal_influence"
            tint = nodes.new("ShaderNodeRGB")
            tint.name = "FBP Crystal Tint"
            source_mix = nodes.new("ShaderNodeMixRGB")
            source_mix.name = "FBP Crystal Source Mix"
            source_mix.blend_type = "MIX"
            distortion_mask = nodes.new("ShaderNodeMath")
            distortion_mask.name = "FBP Crystal Distortion Mask"
            distortion_mask.operation = "MULTIPLY"
            bump = nodes.new("ShaderNodeBump")
            bump.name = "FBP Crystal Bump"
            opaque = nodes.new("ShaderNodeBsdfPrincipled")
            opaque.name = "FBP Crystal Opaque Surface"
            opaque.inputs["Roughness"].default_value = 0.45
            glass = nodes.new("ShaderNodeBsdfPrincipled")
            glass.name = "FBP Crystal Surface"
            glass.inputs["Transmission Weight"].default_value = 1.0
            glass.inputs["Thin Wall"].default_value = False
            surface_mix = nodes.new("ShaderNodeMixShader")
            surface_mix.name = "FBP Crystal Surface Mix"
            absorption = nodes.new("ShaderNodeVolumeAbsorption")
            absorption.name = "FBP Crystal Absorption"
            output = nodes.new("ShaderNodeOutputMaterial")
            output.name = "FBP Crystal Output"

            source_color.location = (-760.0, 260.0)
            pattern.location = (-760.0, 40.0)
            influence.location = (-760.0, -180.0)
            tint.location = (-760.0, 480.0)
            source_mix.location = (-260.0, 360.0)
            distortion_mask.location = (-500.0, -120.0)
            bump.location = (-240.0, 20.0)
            opaque.location = (20.0, 480.0)
            glass.location = (20.0, 220.0)
            surface_mix.location = (280.0, 340.0)
            absorption.location = (20.0, -40.0)
            output.location = (540.0, 260.0)

            links.new(tint.outputs["Color"], source_mix.inputs[1])
            links.new(source_color.outputs["Color"], source_mix.inputs[2])
            links.new(source_mix.outputs["Color"], glass.inputs["Base Color"])
            links.new(source_color.outputs["Color"], opaque.inputs["Base Color"])
            links.new(pattern.outputs["Fac"], bump.inputs["Height"])
            links.new(influence.outputs["Fac"], distortion_mask.inputs[0])
            links.new(distortion_mask.outputs[0], bump.inputs["Strength"])
            links.new(bump.outputs["Normal"], glass.inputs["Normal"])
            links.new(tint.outputs["Color"], absorption.inputs["Color"])
            links.new(influence.outputs["Fac"], surface_mix.inputs[0])
            links.new(opaque.outputs["BSDF"], surface_mix.inputs[1])
            links.new(glass.outputs["BSDF"], surface_mix.inputs[2])
            links.new(surface_mix.outputs["Shader"], output.inputs["Surface"])
            links.new(absorption.outputs["Volume"], output.inputs["Volume"])
            material["fbp_crystal_material_version"] = 6
            organize_node_tree(node_tree)

        tint_value = tuple(getattr(rig, "fbp_crystal_tint", (0.48, 0.82, 1.0, 1.0)))
        _fbp_set_socket_default_if_changed(nodes["FBP Crystal Tint"].outputs["Color"], tint_value)
        source_factor = max(
            0.0, min(1.0, float(getattr(rig, "fbp_crystal_source_color", 0.4) or 0.0))
        )
        tint_weight = 1.0 - source_factor
        _fbp_set_socket_default_if_changed(nodes["FBP Crystal Source Mix"].inputs[0], source_factor)
        bump = nodes["FBP Crystal Bump"]
        _fbp_set_socket_default_if_changed(
            nodes["FBP Crystal Distortion Mask"].inputs[1],
            max(0.0, float(getattr(rig, "fbp_crystal_distortion", 0.8) or 0.0)),
        )
        _fbp_set_socket_default_if_changed(bump.inputs["Distance"], 0.1)
        glass = nodes["FBP Crystal Surface"]
        _fbp_set_socket_default_if_changed(
            glass.inputs["Roughness"],
            max(0.0, min(1.0, float(getattr(rig, "fbp_crystal_roughness", 0.1) or 0.0))),
        )
        _fbp_set_socket_default_if_changed(
            glass.inputs["IOR"],
            max(1.0, float(getattr(rig, "fbp_crystal_ior", 1.47) or 1.47)),
        )
        # Thin Wall is an artistic choice: Blender 5.2's implementation changes
        # image distortion substantially, so never infer it from mesh thickness.
        # Volume absorption still requires an explicitly thick shell.
        crystal_thickness = max(
            0.0, float(getattr(rig, "fbp_crystal_thickness", 0.0) or 0.0)
        )
        _fbp_set_socket_default_if_changed(
            glass.inputs["Thin Wall"],
            bool(getattr(rig, "fbp_crystal_thin_wall", False)),
        )
        absorption_density = max(
            0.0, float(getattr(rig, "fbp_crystal_absorption", 0.7) or 0.0)
        ) * tint_weight if crystal_thickness > 1.0e-6 else 0.0
        absorption = nodes["FBP Crystal Absorption"]
        _fbp_set_socket_default_if_changed(absorption.inputs["Density"], absorption_density)
        _fbp_sync_volume_output(
            node_tree,
            absorption,
            nodes.get("FBP Crystal Output"),
            absorption_density > 1.0e-6 and crystal_thickness > 1.0e-6,
        )
        _fbp_set_attr_if_changed(
            material,
            "diffuse_color",
            tuple(
                (float(tint_value[index]) * tint_weight) + source_factor
                for index in range(3)
            ) + ((float(tint_value[3]) * tint_weight) + source_factor,),
        )
        _fbp_set_attr_if_changed(material, "surface_render_method", "DITHERED")
        _fbp_set_attr_if_changed(material, "use_transparency_overlap", False)
    except FBP_DATA_ERRORS as exc:
        fbp_warn("Could not update Crystal material", exc)
    return material


def _fbp_ensure_text_matrix_material(rig, color):
    """Return one lightweight per-cell-color material for Text Matrix.

    Geometry Nodes stores ``fbp_text_matrix_color`` on the instancing points.
    The shader reads it from the instancer while glyphs remain instances, and
    from geometry after Realize Instances transfers the attribute to the mesh.
    Emission preserves sampled RGB without one material per glyph or light tint.
    """
    plane = _fbp_plane(rig)
    if not plane:
        return None
    owner = str(getattr(plane, "name", "") or "")
    role = "Text Matrix Text"
    material = _fbp_find_owned_effect_material(rig, FBP_EFFECT_TEXT_MATRIX, role)
    if material is None:
        try:
            material = bpy.data.materials.new(name=f"FBP {role} • {owner}")
            material.use_fake_user = False
        except FBP_DATA_ERRORS as exc:
            fbp_warn("Could not create Text Matrix material", exc)
            return None

    try:
        color = tuple(color)
        _fbp_set_attr_if_changed(material, "diffuse_color", color)
        _fbp_set_idprop_if_changed(material, "fbp_owned", True)
        _fbp_set_idprop_if_changed(material, "fbp_effect_material_owner", owner)
        _fbp_set_idprop_if_changed(material, "fbp_effect_material_id", FBP_EFFECT_TEXT_MATRIX)
        _fbp_set_idprop_if_changed(material, "fbp_effect_material_role", role)
        _fbp_set_idprop_if_changed(material, "fbp_text_matrix_color_attribute", "fbp_text_matrix_color")

        node_tree = material.node_tree
        nodes = node_tree.nodes
        links = node_tree.links
        structure_version = int(material.get("fbp_text_matrix_material_version", 0) or 0)
        attribute = nodes.get("FBP Text Matrix Color")
        emission = nodes.get("FBP Text Matrix Emission")
        output = nodes.get("FBP Text Matrix Output")
        color_linked = bool(
            attribute is not None
            and emission is not None
            and any(link.from_node == attribute and link.to_node == emission for link in links)
        )
        surface_linked = bool(
            emission is not None
            and output is not None
            and any(link.from_node == emission and link.to_node == output for link in links)
        )
        if (
            structure_version != 3
            or attribute is None
            or emission is None
            or output is None
            or not color_linked
            or not surface_linked
        ):
            nodes.clear()
            attribute = nodes.new("ShaderNodeAttribute")
            attribute.name = "FBP Text Matrix Color"
            attribute.label = "Per-cell Source Color"
            emission = nodes.new("ShaderNodeEmission")
            emission.name = "FBP Text Matrix Emission"
            emission.label = "Unlit Glyph Color"
            output = nodes.new("ShaderNodeOutputMaterial")
            output.name = "FBP Text Matrix Output"
            attribute.location = (-420.0, 40.0)
            emission.location = (-160.0, 40.0)
            output.location = (100.0, 40.0)
            links.new(attribute.outputs["Color"], emission.inputs["Color"])
            links.new(emission.outputs["Emission"], output.inputs["Surface"])
            material["fbp_text_matrix_material_version"] = 3

        _fbp_set_attr_if_changed(attribute, "attribute_name", "fbp_text_matrix_color")
        attribute_type = (
            "GEOMETRY"
            if bool(getattr(rig, "fbp_text_matrix_realize", False))
            else "INSTANCER"
        )
        _fbp_set_idprop_if_changed(material, "fbp_text_matrix_attribute_type", attribute_type)
        if hasattr(attribute, "attribute_type"):
            _fbp_set_attr_if_changed(attribute, "attribute_type", attribute_type)
        color_input = _fbp_node_socket(emission.inputs, "Color")
        strength_input = _fbp_node_socket(emission.inputs, "Strength")
        _fbp_set_socket_default_if_changed(color_input, color)
        _fbp_set_socket_default_if_changed(strength_input, 1.0)
        _fbp_set_attr_if_changed(material, "surface_render_method", "DITHERED")
        _fbp_set_attr_if_changed(material, "use_transparency_overlap", False)
    except FBP_DATA_ERRORS as exc:
        fbp_warn("Could not configure Text Matrix source-color material", exc)
    return material


def _fbp_material_is_owned(material):
    try:
        return bool(material and material.get("fbp_owned", False))
    except FBP_DATA_ERRORS:
        return False


def _fbp_plane_source_material(rig):
    """Return the exact FBP-owned material evaluated by the animated mesh."""
    plane = _fbp_plane(rig)
    mesh = getattr(plane, "data", None) if plane else None
    materials = getattr(mesh, "materials", None) if mesh else None
    if not materials:
        return None

    try:
        if mesh.polygons:
            index = int(getattr(mesh.polygons[0], "material_index", 0) or 0)
            if 0 <= index < len(materials):
                material = materials[index]
                if _fbp_material_is_owned(material):
                    return material
    except (AttributeError, ReferenceError, RuntimeError, TypeError, ValueError, IndexError):
        pass

    try:
        for material in materials:
            if _fbp_material_is_owned(material):
                return material
    except FBP_DATA_ERRORS:
        pass
    return None


def _fbp_geometry_composite_shader_tokens(rig, boundary_token):
    """Shader instances below one 3D row, in their mixed-stack order."""
    order = _fbp_mixed_effect_tokens(rig)
    if boundary_token not in order:
        return ()
    below = order[order.index(boundary_token) + 1:]
    # The Effect Stack is a conventional layer stack: evaluation starts at
    # the bottom and climbs upward.
    return tuple(
        token
        for token in reversed(below)
        if fbp_effect_definition(
            _fbp_effect_ref_effect_id(token)
        ).get("kind") == "SHADER"
    )


def _fbp_paired_sockets(source_sockets, target_sockets):
    """Yield ``(target, source)`` socket pairs that carry a default value.

    A node copy has the same sockets in the same order, so they pair by
    index. Name lookup is only the fallback: Math and Mix nodes repeat socket
    names (both Math operands are "Value"), and matching by name copied the
    first operand into the second.
    """
    try:
        source_list = tuple(source_sockets)
        target_list = tuple(target_sockets)
    except FBP_DATA_ERRORS:
        return
    same_layout = len(source_list) == len(target_list)
    for index, target in enumerate(target_list):
        if not hasattr(target, "default_value"):
            continue
        source = source_list[index] if same_layout else None
        if source is None or getattr(source, "identifier", None) != getattr(target, "identifier", None):
            source = _fbp_node_socket(source_sockets, str(getattr(target, "name", "") or ""))
        if source is None or not hasattr(source, "default_value"):
            continue
        yield target, source


# (owner id, boundary token) -> material name. Each hit is re-validated, so a
# stale entry (rename, Undo, file load) only costs one fallback scan.
_FBP_COMPOSITE_MATERIAL_INDEX = {}


def _fbp_composite_material_matches(material, owner_id, boundary_token):
    try:
        return (
            str(material.get("fbp_effect_composite_owner_id", "") or "") == owner_id
            and str(material.get("fbp_effect_composite_boundary", "") or "")
            == boundary_token
            and not bool(material.get("fbp_orphan_candidate", False))
        )
    except FBP_DATA_ERRORS:
        return False


def _fbp_find_composite_material(owner_id, boundary_token):
    """The live composite material for one stack boundary, or ``None``.

    Frame changes refresh every composite of every layer, so scanning all of
    ``bpy.data.materials`` per boundary grew with the square of the layer
    count. A small name index answers the common case directly.
    """
    key = (str(owner_id or ""), str(boundary_token or ""))
    name = _FBP_COMPOSITE_MATERIAL_INDEX.get(key)
    if name:
        material = bpy.data.materials.get(name)
        if material is not None and _fbp_composite_material_matches(material, *key):
            return material
        _FBP_COMPOSITE_MATERIAL_INDEX.pop(key, None)
    for material in tuple(bpy.data.materials):
        if _fbp_composite_material_matches(material, *key):
            if len(_FBP_COMPOSITE_MATERIAL_INDEX) > 4096:
                _FBP_COMPOSITE_MATERIAL_INDEX.clear()
            try:
                _FBP_COMPOSITE_MATERIAL_INDEX[key] = str(material.name)
            except FBP_DATA_ERRORS:
                pass
            return material
    return None


def _fbp_geometry_composite_material(
    rig,
    effect_id,
    instance_id="",
    *,
    boundary_token_override="",
    desired_shader_tokens=None,
    base_material_override=None,
    uv_attribute_override="",
    uv_attribute_type="GEOMETRY",
):
    """Build the cumulative material consumed at one Mesh-effect boundary."""
    source = _fbp_plane_source_material(rig)
    if source is None:
        return None
    base = base_material_override or source
    if getattr(base, "node_tree", None) is None:
        return None
    effect_id = fbp_normalize_effect_id(effect_id)
    instance_id = (
        str(instance_id or "") if _fbp_effect_uses_multi_instances(effect_id) else ""
    )
    boundary_token = str(boundary_token_override or "") or _fbp_effect_ref(
        effect_id, instance_id
    )
    desired = (
        tuple(desired_shader_tokens)
        if desired_shader_tokens is not None
        else _fbp_geometry_composite_shader_tokens(rig, boundary_token)
    )
    owner_id = _fbp_effect_stack_owner_id(rig, ensure=True)
    signature = repr(
        (
            str(getattr(source, "name_full", getattr(source, "name", "")) or ""),
            str(getattr(base, "name_full", getattr(base, "name", "")) or ""),
            desired,
            str(uv_attribute_override or ""),
            str(uv_attribute_type or "GEOMETRY"),
        )
    )
    existing = _fbp_find_composite_material(owner_id, boundary_token)

    if existing is not None:
        try:
            topology_matches = (
                str(existing.get("fbp_effect_composite_signature", "") or "")
                == signature
            )
        except FBP_DATA_ERRORS:
            topology_matches = False
        if topology_matches:
            # A Material copy owns its node instances. Mirror the live base
            # source (image frame, procedural colors, mappings and ramps)
            # before syncing the effect-group inputs.
            base_by_name = {
                str(getattr(node, "name", "") or ""): node
                for node in getattr(base.node_tree, "nodes", ())
            }
            for node in getattr(existing.node_tree, "nodes", ()):
                source_node = base_by_name.get(
                    str(getattr(node, "name", "") or "")
                )
                if (
                    source_node is None
                    or getattr(source_node, "bl_idname", "")
                    != getattr(node, "bl_idname", "")
                    # Effect group nodes are synced below, by stack token.
                    or _fbp_shader_effect_id(node)
                ):
                    continue
                try:
                    if hasattr(node, "image") and node.image != source_node.image:
                        node.image = source_node.image
                    for target_socket, source_socket in _fbp_paired_sockets(
                        getattr(source_node, "inputs", ()), getattr(node, "inputs", ())
                    ):
                        _fbp_copy_socket_default(source_socket, target_socket)
                    for target_socket, source_socket in _fbp_paired_sockets(
                        getattr(source_node, "outputs", ()), getattr(node, "outputs", ())
                    ):
                        _fbp_copy_socket_default(source_socket, target_socket)
                    source_ramp = getattr(source_node, "color_ramp", None)
                    target_ramp = getattr(node, "color_ramp", None)
                    if source_ramp is not None and target_ramp is not None:
                        while len(target_ramp.elements) < len(source_ramp.elements):
                            target_ramp.elements.new(0.5)
                        while len(target_ramp.elements) > len(source_ramp.elements):
                            target_ramp.elements.remove(target_ramp.elements[-1])
                        for source_element, target_element in zip(
                            source_ramp.elements, target_ramp.elements
                        ):
                            if target_element.position != source_element.position:
                                target_element.position = source_element.position
                            color = tuple(source_element.color)
                            if tuple(target_element.color) != color:
                                target_element.color = color
                        if target_ramp.interpolation != source_ramp.interpolation:
                            target_ramp.interpolation = source_ramp.interpolation
                except FBP_DATA_ERRORS:
                    continue
            source_nodes = {
                _fbp_shader_node_token(node): node
                for node in _fbp_shader_effect_nodes(source)
                if _fbp_shader_node_token(node)
            }
            mask_mute_changed = False
            for node in _fbp_shader_effect_nodes(existing):
                source_node = source_nodes.get(_fbp_shader_node_token(node))
                if source_node is None:
                    continue
                _fbp_copy_shader_instance_inputs(source_node, node)
                try:
                    if node.mute != bool(source_node.mute):
                        node.mute = bool(source_node.mute)
                        if fbp_effect_definition(_fbp_shader_effect_id(node)).get("stage") == "MASK":
                            mask_mute_changed = True
                except FBP_DATA_ERRORS:
                    pass
            if mask_mute_changed:
                # Hidden masks must leave the copied Mask Stack, as on the plane.
                _fbp_rebuild_shader_stage(existing, "MASK")
            boundary_image = existing.node_tree.nodes.get(
                "FBP Effect Boundary Source Image"
            )
            source_image = _fbp_shader_image_node(source)
            if boundary_image is not None and source_image is not None:
                try:
                    boundary_image.image = source_image.image
                    for attribute in (
                        "frame_start",
                        "frame_duration",
                        "frame_offset",
                        "use_auto_refresh",
                        "use_cyclic",
                    ):
                        if hasattr(boundary_image.image_user, attribute):
                            setattr(
                                boundary_image.image_user,
                                attribute,
                                getattr(source_image.image_user, attribute),
                            )
                except FBP_DATA_ERRORS:
                    pass
            return existing

    try:
        composite = base.copy()
        composite.name = (
            f"FBP Composite \u2022 {getattr(rig, 'name', 'Layer')} \u2022 "
            f"{fbp_effect_definition(effect_id).get('label', effect_id) or boundary_token}"
        )
        composite.use_fake_user = False
        composite["fbp_owned"] = True
        composite["fbp_effect_composite_owner_id"] = owner_id
        composite["fbp_effect_composite_boundary"] = boundary_token
        composite["fbp_effect_composite_signature"] = signature
        composite["fbp_effect_composite_source"] = str(
            getattr(source, "name_full", getattr(source, "name", "")) or ""
        )
        composite["fbp_effect_composite_base"] = str(
            getattr(base, "name_full", getattr(base, "name", "")) or ""
        )
        composite["fbp_effect_rig_owner"] = str(
            getattr(rig, "name", "") or ""
        )
        # Effect-owned materials (Glass, Crystal and similar) retain their
        # custom surface, but also need a live source texture so UV effects
        # below the Mesh row are evaluated before refraction/tinting.
        if base != source and uv_attribute_override:
            source_image = _fbp_shader_image_node(source)
            if source_image is not None:
                boundary_image = composite.node_tree.nodes.new(
                    "ShaderNodeTexImage"
                )
                boundary_image.name = "FBP Effect Boundary Source Image"
                boundary_image.label = "Cumulative Lower Stack Source"
                boundary_image.location = (-1160.0, 120.0)
                boundary_image["fbp_native_sequence_node"] = True
                try:
                    boundary_image.image = source_image.image
                    boundary_image.interpolation = source_image.interpolation
                    boundary_image.extension = source_image.extension
                    boundary_image.projection = source_image.projection
                    for attribute in (
                        "frame_start",
                        "frame_duration",
                        "frame_offset",
                        "use_auto_refresh",
                        "use_cyclic",
                    ):
                        if hasattr(boundary_image.image_user, attribute):
                            setattr(
                                boundary_image.image_user,
                                attribute,
                                getattr(source_image.image_user, attribute),
                            )
                except FBP_DATA_ERRORS:
                    pass
        # A copied effect-owned base is a derived boundary material, not the
        # canonical owned material found and edited by its effect controls.
        for key in (
            "fbp_effect_material_owner",
            "fbp_effect_material_id",
            "fbp_effect_material_role",
        ):
            try:
                if key in composite:
                    del composite[key]
            except FBP_DATA_ERRORS:
                pass
        desired_set = set(desired)
        for node in list(_fbp_shader_effect_nodes(composite)):
            node_effect_id = _fbp_shader_effect_id(node)
            node_token = (
                _fbp_shader_node_token(node)
                if _fbp_effect_uses_multi_instances(node_effect_id)
                else node_effect_id
            )
            if node_token not in desired_set:
                composite.node_tree.nodes.remove(node)
        existing_tokens = {
            _fbp_shader_node_token(node)
            for node in _fbp_shader_effect_nodes(composite)
            if _fbp_shader_node_token(node)
        }
        source_nodes = {
            _fbp_shader_node_token(node): node
            for node in _fbp_shader_effect_nodes(source)
            if _fbp_shader_node_token(node)
        }
        for token in desired:
            if token in existing_tokens:
                continue
            source_node = source_nodes.get(token)
            if source_node is None:
                continue
            try:
                node = composite.node_tree.nodes.new("ShaderNodeGroup")
                node.node_tree = source_node.node_tree
                node.name = str(getattr(source_node, "name", "") or token)
                node.label = str(getattr(source_node, "label", "") or "")
                for key in source_node.keys():
                    node[key] = source_node[key]
                _fbp_copy_shader_instance_inputs(source_node, node)
                node.mute = bool(getattr(source_node, "mute", False))
                existing_tokens.add(token)
            except FBP_DATA_ERRORS:
                continue
        boundary_uv_source = None
        uv_attribute_override = str(uv_attribute_override or "")
        if uv_attribute_override:
            attribute = composite.node_tree.nodes.get(
                "FBP Effect Boundary UV"
            )
            if attribute is None:
                attribute = composite.node_tree.nodes.new(
                    "ShaderNodeAttribute"
                )
                attribute.name = "FBP Effect Boundary UV"
                attribute.label = "Generated Geometry Source UV"
                attribute.location = (-980.0, -360.0)
            attribute.attribute_name = uv_attribute_override
            if hasattr(attribute, "attribute_type"):
                attribute.attribute_type = str(
                    uv_attribute_type or "GEOMETRY"
                )
            boundary_uv_source = _fbp_node_socket(
                getattr(attribute, "outputs", ()), "Vector", 1
            )

        for stage in ("UV", "COLOR", "MASK"):
            stage_order = [
                token
                for token in desired
                if str(
                    fbp_effect_definition(
                        _fbp_effect_ref_effect_id(token)
                    ).get("stage", "")
                ) == stage
            ]
            _fbp_set_shader_stage_order(composite, stage, stage_order)
            _fbp_rebuild_shader_stage(
                composite,
                stage,
                source_override=(
                    boundary_uv_source if stage == "UV" else None
                ),
            )
        if existing is not None:
            existing["fbp_orphan_candidate"] = True
            existing["fbp_effect_composite_owner_id"] = ""
            existing["fbp_effect_composite_boundary"] = ""
        return composite
    except FBP_DATA_ERRORS as exc:
        fbp_warn(
            "Could not build the mixed-stack material composite",
            exc,
            event="effects.composite_material",
        )
        return source


def _fbp_geometry_material_bases(rig, effect_id):
    """Return native material sockets generated or replaced by a Mesh effect."""
    effect_id = fbp_normalize_effect_id(effect_id)
    definition = fbp_effect_definition(effect_id)
    result = []

    source_socket = str(definition.get("source_material_socket", "") or "")
    if source_socket:
        result.append((source_socket, _fbp_plane_source_material(rig)))

    attribute_socket = str(
        definition.get("attribute_material_socket", "") or ""
    )
    if attribute_socket:
        emission_property = str(
            definition.get("attribute_material_emission_property", "") or ""
        )
        emission_strength = (
            float(getattr(rig, emission_property, 0.0) or 0.0)
            if emission_property else 0.0
        )
        result.append((
            attribute_socket,
            _fbp_ensure_attribute_color_material(
                rig,
                effect_id,
                str(
                    definition.get(
                        "attribute_material_role",
                        definition.get("label", effect_id),
                    ) or effect_id
                ),
                str(
                    definition.get(
                        "attribute_material_name", "fbp_source_color"
                    ) or "fbp_source_color"
                ),
                emission_strength=emission_strength,
            ),
        ))

    if effect_id == FBP_EFFECT_TEXT_MATRIX:
        result.extend((
            (
                "Text Material",
                _fbp_ensure_text_matrix_material(
                    rig,
                    tuple(getattr(
                        rig,
                        "fbp_text_matrix_text_color",
                        (0.1, 1.0, 0.2, 1.0),
                    )),
                ),
            ),
            (
                "Background Material",
                _fbp_ensure_owned_effect_material(
                    rig,
                    effect_id,
                    "Text Matrix Background",
                    tuple(getattr(
                        rig,
                        "fbp_text_matrix_background_color",
                        (0.0, 0.0, 0.0, 1.0),
                    )),
                ),
            ),
        ))
    elif effect_id == FBP_EFFECT_FRAME_STACK:
        result.append(("Stack Material", _fbp_ensure_frame_stack_material(rig)))
    elif effect_id == FBP_EFFECT_KNIT_CROCHET:
        result.append(("Yarn Material", _fbp_ensure_knit_crochet_material(rig)))
    elif effect_id == FBP_EFFECT_GLASS:
        result.append(("Glass Material", _fbp_ensure_glass_material(rig)))
    elif effect_id == FBP_EFFECT_CRYSTAL:
        result.append(("Crystal Material", _fbp_ensure_crystal_material(rig)))

    deduplicated = []
    seen = set()
    for socket_name, material in result:
        if not socket_name or material is None or socket_name in seen:
            continue
        seen.add(socket_name)
        deduplicated.append((socket_name, material))
    return tuple(deduplicated)


def _fbp_apply_geometry_material_composites(
    rig,
    modifier,
    effect_id,
    instance_id="",
):
    """Feed every generated-material socket the complete stack result below."""
    node_group = getattr(modifier, "node_group", None)
    if node_group is None:
        return False
    effect_id = fbp_normalize_effect_id(effect_id)
    instance_id = (
        str(instance_id or "")
        if _fbp_effect_uses_multi_instances(effect_id)
        else ""
    )
    boundary = _fbp_effect_ref(effect_id, instance_id)
    desired = _fbp_geometry_composite_shader_tokens(rig, boundary)
    changed = False
    interface_inputs = _fbp_interface_inputs(node_group)
    for socket_name, base_material in _fbp_geometry_material_bases(
        rig, effect_id
    ):
        material = base_material
        # Earlier slices carry their own sampled frame; the shader stack below
        # only exists for the current frame, so their materials stay as built.
        if desired and effect_id not in {FBP_EFFECT_FRAME_STACK, FBP_EFFECT_KNIT_CROCHET}:
            uv_attribute = ""
            uv_attribute_type = "GEOMETRY"
            composite_base = base_material
            attribute_socket = str(
                fbp_effect_definition(effect_id).get(
                    "attribute_material_socket", ""
                ) or ""
            )
            if socket_name == attribute_socket:
                uv_attribute = str(
                    fbp_effect_definition(effect_id).get(
                        "attribute_material_uv_name", ""
                    ) or ""
                )
                if uv_attribute:
                    # Attribute-color materials only know the original sampled
                    # pixel. Start from the real plane material when a lower
                    # stack exists, then evaluate that stack at the UV captured
                    # on the generated points/instances.
                    composite_base = _fbp_plane_source_material(rig)
                    uv_attribute_type = "INSTANCER"
            if (
                effect_id == FBP_EFFECT_TEXT_MATRIX
                and socket_name == "Text Material"
                and bool(getattr(rig, "fbp_text_matrix_use_source_color", True))
            ):
                composite_base = _fbp_plane_source_material(rig)
                uv_attribute = "fbp_text_matrix_uv"
                uv_attribute_type = (
                    "GEOMETRY"
                    if bool(getattr(rig, "fbp_text_matrix_realize", False))
                    else "INSTANCER"
                )
            if effect_id in {FBP_EFFECT_GLASS, FBP_EFFECT_CRYSTAL} and socket_name in {
                "Glass Material",
                "Crystal Material",
            }:
                # These effects keep their refractive material, while the
                # boundary material injects the animated source image and reads
                # the UVMap preserved by their remeshed geometry.
                uv_attribute = "UVMap"
                uv_attribute_type = "GEOMETRY"
            material = _fbp_geometry_composite_material(
                rig,
                effect_id,
                instance_id,
                boundary_token_override=(
                    f"{boundary}::MATERIAL::{socket_name}"
                ),
                desired_shader_tokens=desired,
                base_material_override=composite_base,
                uv_attribute_override=uv_attribute,
                uv_attribute_type=uv_attribute_type,
            )
        if material is None:
            continue
        changed = _fbp_set_modifier_input(
            modifier,
            node_group,
            socket_name,
            material,
            interface_inputs,
        ) or changed
    return changed


# While a frame change runs, refresh requests are queued here (runtime key ->
# rig) and run once per layer at the end, instead of once per changed effect.
_FBP_COMPOSITE_REFRESH_PENDING = None


def _fbp_flush_composite_refreshes():
    global _FBP_COMPOSITE_REFRESH_PENDING
    pending = _FBP_COMPOSITE_REFRESH_PENDING
    _FBP_COMPOSITE_REFRESH_PENDING = None
    for rig in (pending or {}).values():
        try:
            _fbp_refresh_geometry_source_materials(rig)
        except FBP_DATA_ERRORS:
            continue


# Set to a dict while one refresh pass runs, so the stack order (which costs a
# full instance-record discovery) is computed once per rig instead of once per
# Mesh effect and stage material. No stack edits happen inside such a pass.
_FBP_MIXED_TOKENS_MEMO = None


def _fbp_mixed_effect_tokens(rig):
    """Return the one persisted Image / Mask / Mesh evaluation order."""
    memo = _FBP_MIXED_TOKENS_MEMO
    if memo is not None:
        try:
            key = rig.as_pointer()
        except FBP_DATA_ERRORS:
            key = None
        if key is not None:
            cached = memo.get(key)
            if cached is None:
                cached = memo[key] = tuple(_fbp_mixed_effect_tokens_uncached(rig))
            return list(cached)
    return _fbp_mixed_effect_tokens_uncached(rig)


def _fbp_refresh_geometry_source_materials(rig):
    """Refresh every Geometry Nodes material input after stack/node changes."""
    global _FBP_MIXED_TOKENS_MEMO
    pending = _FBP_COMPOSITE_REFRESH_PENDING
    if pending is not None:
        key = fbp_obj_runtime_key(rig)
        if key is not None:
            pending[key] = rig
            return False
    if _FBP_MIXED_TOKENS_MEMO is not None:
        return _fbp_refresh_geometry_source_materials_pass(rig)
    _FBP_MIXED_TOKENS_MEMO = {}
    try:
        return _fbp_refresh_geometry_source_materials_pass(rig)
    finally:
        _FBP_MIXED_TOKENS_MEMO = None


def _fbp_refresh_geometry_source_materials_pass(rig):
    plane = _fbp_plane(rig, repair=False)
    if plane is None:
        return False
    changed = False
    try:
        modifiers = tuple(plane.modifiers)
    except FBP_DATA_ERRORS:
        return False
    # Ensure every instance id before the first composite reads the stack
    # order, which is memoised for the rest of this pass.
    targets = []
    for modifier in modifiers:
        effect_id = _fbp_geometry_effect_id_for_modifier(modifier)
        node_group = getattr(modifier, "node_group", None)
        if not effect_id or node_group is None:
            continue
        instance_id = (
            _fbp_geometry_modifier_instance_id(
                rig, modifier, effect_id, ensure=True
            )
            if _fbp_effect_uses_multi_instances(effect_id) else ""
        )
        targets.append((modifier, effect_id, instance_id))
    for modifier, effect_id, instance_id in targets:
        changed = _fbp_apply_geometry_material_composites(
            rig, modifier, effect_id, instance_id
        ) or changed
    # Mixed Image/Mesh stacks also contain lightweight Set Material stages.
    # Refresh their copied inputs during animation without changing topology.
    try:
        changed = _fbp_refresh_mixed_shader_stage_materials(rig) or changed
    except NameError:
        pass
    return changed


def _fbp_cleanup_owned_effect_materials(rig, effect_id):
    """Detach retired effect materials without freeing Undo-visible IDs."""
    plane = _fbp_plane(rig)
    owner = str(getattr(plane, "name", "") or "")
    effect_id = fbp_normalize_effect_id(effect_id)
    changed = False
    for material in list(bpy.data.materials):
        try:
            if (
                material.get("fbp_effect_material_owner", "") == owner
                and fbp_normalize_effect_id(material.get("fbp_effect_material_id", "")) == effect_id
                and material.users == 0
            ):
                material["fbp_orphan_candidate"] = True
                material["fbp_effect_material_owner"] = ""
                material["fbp_effect_material_id"] = ""
                material.use_fake_user = False
                changed = True
        except FBP_DATA_ERRORS:
            pass
    return changed


# ---------------------------------------------------------------------------
# Geometry effect modifiers
# ---------------------------------------------------------------------------


def fbp_find_effect_modifier(rig, effect_id, instance_id=""):
    effect_id = fbp_normalize_effect_id(effect_id)
    definition = fbp_effect_definition(effect_id)
    if definition.get("kind") != "GEOMETRY":
        return None
    plane = _fbp_plane(rig)
    if not plane:
        return None
    try:
        for modifier in plane.modifiers:
            if getattr(modifier, "type", "") != "NODES":
                continue
            node_group = getattr(modifier, "node_group", None)
            if (
                _fbp_group_declares_effect(node_group, effect_id)
                or _fbp_group_matches(node_group, effect_id)
            ):
                if instance_id and effect_instance_id(modifier) != str(instance_id or ""):
                    continue
                return modifier
    except FBP_DATA_ERRORS:
        pass
    return None


def _fbp_find_all_effect_modifiers(rig, effect_id):
    effect_id = fbp_normalize_effect_id(effect_id)
    definition = fbp_effect_definition(effect_id)
    plane = _fbp_plane(rig)
    if not plane or definition.get("kind") != "GEOMETRY":
        return []
    result = []
    try:
        for modifier in plane.modifiers:
            if getattr(modifier, "type", "") != "NODES":
                continue
            node_group = getattr(modifier, "node_group", None)
            if (
                _fbp_group_declares_effect(node_group, effect_id)
                or _fbp_group_matches(node_group, effect_id)
            ):
                result.append(modifier)
    except FBP_DATA_ERRORS:
        return []
    return result


def _fbp_remove_duplicate_effect_modifiers(rig, effect_id, keep):
    plane = _fbp_plane(rig)
    if not plane:
        return
    for modifier in _fbp_find_all_effect_modifiers(rig, effect_id):
        if modifier == keep:
            continue
        node_group = getattr(modifier, "node_group", None)
        try:
            plane.modifiers.remove(modifier)
        except FBP_DATA_ERRORS:
            continue
        try:
            if node_group and bool(node_group.get("fbp_private_effect_group", False)) and node_group.users == 0:
                _fbp_remove_node_group(node_group)
        except FBP_DATA_ERRORS:
            pass


def _fbp_cast_effect_value(prop_name, value):
    if prop_name == "fbp_infinite_rotation_direction" and isinstance(value, str):
        return -1.0 if value == "RIGHT" else 1.0
    enum_values = {
        "fbp_wind_pin_edge": {"LEFT": 0.0, "RIGHT": 1.0, "BOTTOM": 2.0, "TOP": 3.0, "ALL": 4.0, "VERTEX_GROUP": 5.0},
        "fbp_wind_motion_mode": {"SWAY": 0.0, "FLOW": 1.0, "RIPPLE": 2.0},
        "fbp_wind_ripple_direction": {"X": 0.0, "Y": 1.0, "RADIAL": 2.0},
        "fbp_wind_direction_space": {"LOCAL": 0.0, "WORLD": 1.0},
        "fbp_halftone_pattern": {"DOT": 0.0, "BLENDED": 1.0},
        "fbp_halftone_color_mode": {"CMYK": 0.0, "RGB": 1.0, "BW_LIGHT": 2.0, "BW_DARK": 3.0},
        "fbp_halftone_shape": {"CIRCLE": 0.0, "SQUARE": 1.0, "DIAMOND": 2.0, "LINE": 3.0},
        "fbp_dot_matrix_shape": {"CIRCLE": 0.0, "SQUARE": 1.0, "DIAMOND": 2.0, "LINE": 3.0},
        "fbp_camera_billboard_mode": {"FULL": 0.0, "HORIZONTAL": 1.0, "VERTICAL": 2.0},
        "fbp_thickness_mode": {"VOLUME": 0.0, "ARRAY": 1.0},
        "fbp_gradient_mask_type": {"LINEAR": 0.0, "RADIAL": 1.0},
        "fbp_channel_mask_channel": {"RED": 0.0, "GREEN": 1.0, "BLUE": 2.0, "ALPHA": 3.0, "LUMINANCE": 4.0},
        "fbp_shadow_mode": {"OUTER": 0.0, "INNER": 1.0},
        "fbp_shadow_blend_mode": {"NORMAL": 0.0, "MULTIPLY": 1.0, "SCREEN": 2.0, "OVERLAY": 3.0, "SOFT_LIGHT": 4.0, "HARD_LIGHT": 5.0, "ADD": 6.0, "DIFFERENCE": 7.0},
        "fbp_rim_mode": {"INNER": 0.0, "OUTER": 1.0, "BOTH": 2.0},
        "fbp_rim_blend_mode": {"NORMAL": 0.0, "MULTIPLY": 1.0, "SCREEN": 2.0, "OVERLAY": 3.0, "SOFT_LIGHT": 4.0, "HARD_LIGHT": 5.0, "ADD": 6.0, "DIFFERENCE": 7.0},
        "fbp_dither_style": {"ORDERED": 0.0, "PLUS_X": 1.0, "PLUS": 2.0, "XPIXELS": 3.0, "LINES": 4.0},
        "fbp_sphere_screen_shape": {"SPHERE": 0, "CUBE": 1, "CYLINDER": 2, "CONE": 3},
        "fbp_sphere_screen_depth_mode": {"LIGHTS": 0, "SHADOWS": 1, "SATURATION": 2, "CUSTOM": 3},
        "fbp_image_relief_depth_mode": {"LIGHTS": 0, "SHADOWS": 1, "SATURATION": 2, "CUSTOM": 3},
        "fbp_glass_pattern": {"SHARDS": 0, "IMPACT": 1},
        "fbp_crystal_texture_type": {"VORONOI": 0, "NOISE": 1, "WAVE": 2, "BRICK": 3},
        "fbp_crystal_pattern_mode": {"DIAMOND": 0, "CRYSTAL": 1, "LIQUID": 2},
        "fbp_sculpt_waves_style": {"RADIAL": 0, "MOIRE": 1, "SPIRAL": 2},
        "fbp_kinetic_tiles_pattern": {"WAVE": 0, "CHECKER": 1, "RIPPLE": 2},
        "fbp_yarn_stitch_type": {"KNIT": 0, "CROCHET": 1},
    }
    if prop_name in enum_values:
        return enum_values[prop_name].get(str(value), 0.0)
    if prop_name in {"fbp_gaussian_blur_samples", "fbp_directional_blur_samples"}:
        samples = max(3, min(25, int(value or 3)))
        return samples if samples % 2 else min(25, samples + 1)
    if prop_name == "fbp_felt_curl_amount":
        # The bundled group treats Curl Amount almost linearly. A quadratic
        # response creates actual self-turning coils at the upper half of the
        # slider while keeping subtle fuzz controllable near zero.
        curl = max(0.0, float(value or 0.0))
        return curl * (1.0 + curl * 0.85)
    if isinstance(value, bool):
        return bool(value)
    if isinstance(value, int):
        # Preserve RNA IntProperty values for integer Geometry Nodes sockets.
        # Converting every numeric value to float breaks columns/rows and other
        # discrete controls because modifier IDProperties are strongly typed.
        return int(value)
    if prop_name.endswith(("subdivisions", "subdivision", "resolution")) or prop_name in {
        "fbp_felt_render_density",
        "fbp_mesh_wiggle_hold",
        "fbp_stop_motion_step_frames",
        "fbp_wind_stepped",
        "fbp_infinite_rotation_stepped",
        "fbp_felt_seed",
        "fbp_felt_alpha_resolution",
        "fbp_text_matrix_viewport_columns",
        "fbp_text_matrix_viewport_rows",
        "fbp_text_matrix_render_columns",
        "fbp_text_matrix_render_rows",
        "fbp_text_matrix_playback_columns",
        "fbp_text_matrix_playback_rows",
        "fbp_text_matrix_character_count",
        "fbp_cutout_outline_viewport_resolution",
        "fbp_cutout_outline_playback_resolution",
        "fbp_cutout_outline_render_resolution",
        "fbp_thickness_viewport_pixels_x",
        "fbp_thickness_viewport_pixels_y",
        "fbp_thickness_playback_pixels_x",
        "fbp_thickness_playback_pixels_y",
        "fbp_thickness_render_pixels_x",
        "fbp_thickness_render_pixels_y",
    }:
        return int(value)
    if prop_name.endswith("shade_smooth"):
        return bool(value)
    if isinstance(value, (tuple, list)):
        return tuple(value)
    try:
        return float(value)
    except (TypeError, ValueError):
        return value


def _fbp_ensure_geometry_effect_group(rig, effect_id, modifier):
    """Restore a missing/outdated effect group without replacing the modifier."""
    if not rig or not modifier:
        return None
    effect_id = fbp_normalize_effect_id(effect_id)
    definition = fbp_effect_definition(effect_id)
    current = getattr(modifier, "node_group", None)
    if current and _fbp_group_matches(current, effect_id):
        if not (definition.get("alpha_aware") or definition.get("private_group")):
            return current
        owned = _fbp_owned_geometry_group(rig, effect_id, current, current)
        if owned:
            return owned

    source = (
        fbp_load_mesh_wiggle_group()
        if effect_id == FBP_EFFECT_MESH_WIGGLE
        else _fbp_load_effect_group(effect_id)
    )
    if not source:
        return None
    target = source
    if definition.get("alpha_aware") or definition.get("private_group"):
        target = _fbp_owned_geometry_group(rig, effect_id, source, current)
    if not target:
        return None

    try:
        modifier.node_group = target
        instance_id = _fbp_geometry_modifier_instance_id(
            rig, modifier, effect_id, ensure=True
        )
        _fbp_store_effect_instance_id(rig, effect_id, instance_id)
        modifier.name = str(
            definition.get("modifier_name", definition.get("label", effect_id))
        )
        visible = _fbp_stored_effect_visibility(rig, effect_id, True)
        render_visible = _fbp_stored_effect_render_visibility(rig, effect_id, True)
        modifier.show_viewport = visible
        modifier.show_render = render_visible
        if current and current != target:
            try:
                if bool(current.get("fbp_private_effect_group", False)) and current.users == 0:
                    _fbp_remove_node_group(current)
            except FBP_DATA_ERRORS:
                pass
        return target
    except FBP_DATA_ERRORS as exc:
        fbp_warn(f"Could not restore {definition.get('label', effect_id)} asset", exc)
        return None


def _fbp_default_vector_font():
    """Return Blender's built-in vector font without rescanning on every edit."""
    global _FBP_DEFAULT_FONT_CACHE
    cached = _FBP_DEFAULT_FONT_CACHE
    if cached is not None:
        try:
            name = str(getattr(cached, "name_full", getattr(cached, "name", "")) or "")
            if name and bpy.data.fonts.get(name) is cached:
                return cached
        except FBP_DATA_ERRORS:
            pass
        _FBP_DEFAULT_FONT_CACHE = None
    try:
        for font in bpy.data.fonts:
            if str(getattr(font, "name", "")).startswith("Bfont"):
                _FBP_DEFAULT_FONT_CACHE = font
                return font
    except FBP_DATA_ERRORS:
        pass
    curve = None
    try:
        curve = bpy.data.curves.new("FBP_Default_Font_Loader", type="FONT")
        font = getattr(curve, "font", None)
        _FBP_DEFAULT_FONT_CACHE = font
        return font
    except FBP_DATA_ERRORS:
        return None
    finally:
        if curve is not None:
            try:
                bpy.data.curves.remove(curve)
            except FBP_DATA_ERRORS:
                pass

def _fbp_update_text_matrix_charset(node_group, rig):
    if not node_group or not rig:
        return False
    preset = str(getattr(rig, "fbp_text_matrix_charset", "CLASSIC") or "CLASSIC")
    custom = str(getattr(rig, "fbp_text_matrix_custom_charset", "") or "")
    count = max(2, min(ASCII_TEXT_GLYPH_LIMIT, int(getattr(rig, "fbp_text_matrix_character_count", ASCII_TEXT_GLYPH_LIMIT) or ASCII_TEXT_GLYPH_LIMIT)))
    chars = ascii_level_gradient(preset, levels=count, custom=custom)
    # The group always contains sixteen branches; repeat the densest glyph for
    # unused slots so changing Character Count cannot expose stale characters.
    chars = (chars + chars[-1] * ASCII_TEXT_GLYPH_LIMIT)[:ASCII_TEXT_GLYPH_LIMIT]
    signature = f"{preset}|{count}|{custom}|{chars}"
    try:
        if str(node_group.get("fbp_text_matrix_charset_signature", "") or "") == signature:
            return False
    except FBP_DATA_ERRORS:
        pass
    changed = False
    for node in getattr(node_group, "nodes", ()):
        try:
            glyph_index = int(node.get("fbp_text_matrix_glyph_index", -1))
        except FBP_DATA_ERRORS:
            continue
        if glyph_index < 0 or glyph_index >= len(chars):
            continue
        socket = _fbp_node_socket(getattr(node, "inputs", ()), "String")
        if socket is None or str(getattr(socket, "default_value", "")) == chars[glyph_index]:
            continue
        try:
            socket.default_value = chars[glyph_index]
            changed = True
        except FBP_DATA_ERRORS:
            pass
    try:
        node_group["fbp_text_matrix_charset_signature"] = signature
    except FBP_DATA_ERRORS:
        pass
    return changed


# Values Frame By Plane last wrote to a mesh effect's modifier inputs, keyed by
# (modifier pointer, rig property). An input that moved since was edited in
# the Modifiers panel and goes back to the layer setting. Inputs whose value
# is computed (quality per viewport/render, animated Evolution, Mesh Wiggle's
# W) are left out: editing them there would be undone by the next update.
_FBP_GEOMETRY_INPUT_WRITTEN = {}


def _fbp_remember_geometry_input(rig, modifier, prop_name, value):
    try:
        key = (int(modifier.as_pointer()), str(prop_name))
        raw = _fbp_cast_effect_value(prop_name, getattr(rig, prop_name))
    except FBP_DATA_ERRORS:
        return
    if _fbp_effect_values_equal(raw, value):
        _FBP_GEOMETRY_INPUT_WRITTEN[key] = tuple(value) if hasattr(value, "__len__") and not isinstance(value, str) else value
    else:
        _FBP_GEOMETRY_INPUT_WRITTEN.pop(key, None)


def fbp_pull_geometry_modifier_edits(rig):
    """Write mesh effect inputs edited in the Modifiers panel to the layer."""
    if not rig:
        return 0
    pulled = 0
    for effect_id in tuple(fbp_effect_ids_for_rig(rig)):
        definition = fbp_effect_definition(effect_id)
        if definition.get("kind") != "GEOMETRY" or bool(definition.get("custom", False)):
            continue
        modifier = fbp_find_effect_modifier(rig, effect_id)
        node_group = getattr(modifier, "node_group", None) if modifier else None
        if node_group is None:
            continue
        try:
            pointer = int(modifier.as_pointer())
        except FBP_DATA_ERRORS:
            continue
        try:
            from .effect_shells import fbp_sync_geometry_panel_inputs
            pulled += fbp_sync_geometry_panel_inputs(rig, effect_id, modifier)
        except ImportError:
            pass
        inputs = None
        for prop_name, socket_name in (definition.get("property_map", {}) or {}).items():
            key = (pointer, prop_name)
            if key not in _FBP_GEOMETRY_INPUT_WRITTEN:
                continue
            if inputs is None:
                inputs = _fbp_interface_inputs(node_group)
            identifier = str(_fbp_interface_socket_for_name(inputs, socket_name) or "")
            current = _fbp_modifier_input_get(modifier, identifier) if identifier else None
            if current is None:
                continue
            if hasattr(current, "__len__") and not isinstance(current, str):
                current = tuple(current)
            if _fbp_effect_values_equal(current, _FBP_GEOMETRY_INPUT_WRITTEN[key]):
                continue
            _FBP_GEOMETRY_INPUT_WRITTEN[key] = current
            try:
                rna = rig.bl_rna.properties.get(prop_name)
                value = current
                if rna is not None and rna.type == "BOOLEAN":
                    value = bool(value)
                elif rna is not None and rna.type == "INT":
                    value = int(round(float(value)))
                elif rna is not None and rna.type == "ENUM":
                    continue
                elif rna is not None and getattr(rna, "is_array", False):
                    value = tuple(value)[:int(rna.array_length)]
                else:
                    value = float(value)
                if not _fbp_effect_values_equal(getattr(rig, prop_name), value):
                    setattr(rig, prop_name, value)
                    pulled += 1
            except FBP_DATA_ERRORS as exc:
                fbp_warn(f"Could not apply {prop_name} from its modifier", exc)
    return pulled


def fbp_update_geometry_effect(
    rig,
    effect_id,
    modifier=None,
    scene=None,
    *,
    sync_alpha=True,
    property_names=None,
    refresh_composites=True,
):
    """Push effect values into one Geometry Nodes modifier.

    ``property_names`` limits interactive RNA callbacks to the sockets that
    actually changed. Full updates are still used after asset repair, file load,
    frame evaluation and explicit stack rebuilds. Frame changes that only move
    Evolve or procedural inputs pass ``refresh_composites=False``: those values
    never reach the materials, so the boundary composites stay as they are.
    """
    effect_id = fbp_normalize_effect_id(effect_id)
    definition = fbp_effect_definition(effect_id)
    if definition.get("kind") != "GEOMETRY" or not rig:
        return False
    modifier = modifier or fbp_find_effect_modifier(rig, effect_id)
    if not modifier:
        return False
    previous_group = getattr(modifier, "node_group", None)
    node_group = _fbp_ensure_geometry_effect_group(rig, effect_id, modifier)
    if not node_group:
        return False
    if not bool(definition.get("custom", False)):
        try:
            # The rest of the panel (Animate, quality, shading) as inputs.
            from .effect_shells import fbp_extend_geometry_group
            fbp_extend_geometry_group(node_group, effect_id)
        except ImportError:
            pass

    requested = None if property_names is None else {
        str(name) for name in property_names if str(name or "")
    }
    # Mesh Wiggle folds its Seed and Unique Seed controls into the effective W
    # socket. A property-scoped update must therefore refresh W as a dependency.
    if effect_id == FBP_EFFECT_MESH_WIGGLE and requested is not None:
        if requested & {
            "fbp_mesh_wiggle_seed",
            "fbp_mesh_wiggle_unique_seed",
            "fbp_mesh_wiggle_speed",
            "fbp_mesh_wiggle_hold",
        }:
            requested.add("fbp_mesh_wiggle_w")
    # A repaired/replaced group contains defaults and needs one complete sync.
    if node_group is not previous_group:
        requested = None
    full_update = requested is None
    interface_inputs = _fbp_interface_inputs(node_group)
    extrude_grid = None
    if effect_id == FBP_EFFECT_THICKNESS and (
        full_update
        or bool(
            requested
            & {
                "fbp_thickness_viewport_pixels_x",
                "fbp_thickness_viewport_pixels_y",
            }
        )
    ):
        profile = "PLAYBACK" if _FBP_EFFECT_PLAYBACK_ACTIVE else "VIEWPORT"
        extrude_grid = _fbp_extrude_grid(rig, profile)

    updated = False
    for prop_name, socket_name in (definition.get("property_map", {}) or {}).items():
        if requested is not None and prop_name not in requested:
            continue
        try:
            value = getattr(rig, prop_name)
        except (AttributeError, ReferenceError):
            continue
        if extrude_grid is not None and prop_name in {
            "fbp_thickness_viewport_pixels_x",
            "fbp_thickness_viewport_pixels_y",
        }:
            value = (
                extrude_grid[0]
                if prop_name.endswith("_x") else extrude_grid[1]
            )
        else:
            value = _fbp_effect_runtime_value(
                rig, effect_id, prop_name, value, scene=scene
            )
            value = _fbp_effective_quality_value(
                rig, effect_id, prop_name, value
            )
        value = _fbp_cast_effect_value(prop_name, value)
        updated = _fbp_set_modifier_input(
            modifier,
            node_group,
            socket_name,
            value,
            interface_inputs,
        ) or updated
        _fbp_remember_geometry_input(rig, modifier, prop_name, value)

    if definition.get("camera_aware"):
        updated = _fbp_bind_geometry_camera_input(
            rig, effect_id, modifier, node_group=node_group, scene=scene
        ) or updated

    if effect_id == FBP_EFFECT_CUTOUT_OUTLINE and (
        full_update or "fbp_cutout_outline_color" in (requested or set())
    ):
        material = _fbp_ensure_owned_effect_material(
            rig,
            effect_id,
            "Cutout Outline",
            tuple(getattr(rig, "fbp_cutout_outline_color", (0.02, 0.02, 0.02, 1.0))),
        )
        if material:
            updated = _fbp_set_modifier_input(
                modifier, node_group, "Outline Material", material, interface_inputs
            ) or updated

    if effect_id == FBP_EFFECT_THICKNESS and (
        full_update
        or bool(
            requested
            & {
                "fbp_thickness_side_material",
                "fbp_thickness_side_color",
                "fbp_thickness_use_plane_colors",
            }
        )
    ):
        source_material = _fbp_plane_source_material(rig)
        if source_material is None:
            source_material, _source_image_node = _fbp_material_image_node(rig)
        if source_material is None:
            plane = _fbp_plane(rig)
            source_material = getattr(plane, "active_material", None) if plane else None
        try:
            use_plane_colors = bool(
                getattr(rig, "fbp_thickness_use_plane_colors", False)
            )
            material = source_material if use_plane_colors else getattr(
                rig, "fbp_thickness_side_material", None
            )
            if material is None:
                material = _fbp_ensure_owned_effect_material(
                    rig,
                    effect_id,
                    "Extrude",
                    tuple(getattr(rig, "fbp_thickness_side_color", (0.18, 0.12, 0.08, 1.0))),
                )
        except FBP_DATA_ERRORS:
            material = None
        if material:
            updated = _fbp_set_modifier_input(
                modifier,
                node_group,
                "Side Material",
                material,
                interface_inputs,
            ) or updated

    attribute_material_socket = str(definition.get("attribute_material_socket", "") or "")
    emission_property = str(definition.get("attribute_material_emission_property", "") or "")
    if attribute_material_socket and (
        full_update or bool(emission_property and requested and emission_property in requested)
    ):
        emission_strength = (
            float(getattr(rig, emission_property, 0.0) or 0.0)
            if emission_property else 0.0
        )
        material = _fbp_ensure_attribute_color_material(
            rig,
            effect_id,
            str(definition.get("attribute_material_role", definition.get("label", effect_id)) or effect_id),
            str(definition.get("attribute_material_name", "fbp_source_color") or "fbp_source_color"),
            emission_strength=emission_strength,
        )
        if material:
            updated = _fbp_set_modifier_input(
                modifier,
                node_group,
                attribute_material_socket,
                material,
                interface_inputs,
            ) or updated

    if full_update and effect_id in {FBP_EFFECT_FRAME_STACK, FBP_EFFECT_KNIT_CROCHET}:
        socket_name, material = (
            ("Stack Material", _fbp_ensure_frame_stack_material(rig))
            if effect_id == FBP_EFFECT_FRAME_STACK
            else ("Yarn Material", _fbp_ensure_knit_crochet_material(rig))
        )
        if material:
            updated = _fbp_set_modifier_input(
                modifier, node_group, socket_name, material, interface_inputs,
            ) or updated

    if effect_id == FBP_EFFECT_TEXT_MATRIX:
        text_material_props = {"fbp_text_matrix_text_color", "fbp_text_matrix_realize"}
        if full_update or bool(requested & text_material_props):
            text_material = _fbp_ensure_text_matrix_material(
                rig,
                tuple(getattr(rig, "fbp_text_matrix_text_color", (0.1, 1.0, 0.2, 1.0))),
            )
            if text_material:
                updated = _fbp_set_modifier_input(
                    modifier,
                    node_group,
                    "Text Material",
                    text_material,
                    interface_inputs,
                ) or updated

        if full_update or "fbp_text_matrix_background_color" in requested:
            background_material = _fbp_ensure_owned_effect_material(
                rig,
                effect_id,
                "Text Matrix Background",
                tuple(getattr(rig, "fbp_text_matrix_background_color", (0.0, 0.0, 0.0, 1.0))),
            )
            if background_material:
                updated = _fbp_set_modifier_input(
                    modifier,
                    node_group,
                    "Background Material",
                    background_material,
                    interface_inputs,
                ) or updated

        if full_update or "fbp_text_matrix_font" in requested:
            font = getattr(rig, "fbp_text_matrix_font", None)
            if font is None:
                font = _fbp_default_vector_font()
            if font is not None:
                updated = _fbp_set_modifier_input(
                    modifier,
                    node_group,
                    "Font",
                    font,
                    interface_inputs,
                ) or updated

        charset_props = {
            "fbp_text_matrix_charset",
            "fbp_text_matrix_custom_charset",
            "fbp_text_matrix_character_count",
        }
        if full_update or bool(requested & charset_props):
            updated = _fbp_update_text_matrix_charset(node_group, rig) or updated

    if effect_id == FBP_EFFECT_GLASS:
        glass_material_properties = {
            "fbp_glass_use_glass",
            "fbp_glass_roughness", "fbp_glass_ior", "fbp_glass_tint",
            "fbp_glass_source_color", "fbp_glass_edge_tint", "fbp_glass_absorption",
            "fbp_glass_thickness",
        }
        if full_update or bool((requested or set()) & glass_material_properties):
            material = _fbp_ensure_glass_material(rig)
            if material:
                updated = _fbp_set_modifier_input(
                    modifier, node_group, "Glass Material", material, interface_inputs
                ) or updated

    if effect_id == FBP_EFFECT_CRYSTAL:
        crystal_material_properties = {
            "fbp_crystal_distortion", "fbp_crystal_roughness", "fbp_crystal_ior",
            "fbp_crystal_tint", "fbp_crystal_source_color", "fbp_crystal_absorption",
            "fbp_crystal_thickness", "fbp_crystal_thin_wall",
        }
        if full_update or bool((requested or set()) & crystal_material_properties):
            material = _fbp_ensure_crystal_material(rig)
            if material:
                updated = _fbp_set_modifier_input(
                    modifier, node_group, "Crystal Material", material, interface_inputs
                ) or updated

    # Replace every native/generated material input with a boundary composite.
    # This runs after the native material has been updated, so Text Matrix,
    # Image Solids, Fiber, Paper, Glass, Crystal and Felt all consume the exact
    # cumulative Image/Mask result below their Mesh row.
    if refresh_composites or node_group is not previous_group:
        updated = _fbp_apply_geometry_material_composites(
            rig,
            modifier,
            effect_id,
            (
                _fbp_geometry_modifier_instance_id(
                    rig, modifier, effect_id, ensure=True
                )
                if _fbp_effect_uses_multi_instances(effect_id)
                else ""
            ),
        ) or updated

    alpha_changed = False
    if (definition.get("alpha_aware") or definition.get("image_aware")) and sync_alpha:
        alpha_changed = _fbp_sync_geometry_alpha(rig, modifier)
    if effect_id == FBP_EFFECT_FRAME_STACK:
        # Fixed Range and Start Frame move the stack position.
        alpha_changed = _fbp_sync_frame_stack_timing(rig, modifier) or alpha_changed

    visibility_changed = _fbp_sync_geometry_effect_eval_visibility(rig, effect_id, modifier)

    if updated or alpha_changed or visibility_changed:
        try:
            plane = _fbp_plane(rig)
            if plane:
                plane.update_tag()
        except FBP_DATA_ERRORS:
            pass
    return updated or alpha_changed or visibility_changed


def fbp_update_mesh_wiggle_modifier(rig, modifier=None):
    return fbp_update_geometry_effect(rig, FBP_EFFECT_MESH_WIGGLE, modifier)


def fbp_apply_geometry_effect(rig, effect_id, *, sync_items=True):
    effect_id = fbp_normalize_effect_id(effect_id)
    definition = fbp_effect_definition(effect_id)
    plane = _fbp_plane(rig)
    if definition.get("kind") != "GEOMETRY" or not plane:
        return False
    source_group = fbp_load_mesh_wiggle_group() if effect_id == FBP_EFFECT_MESH_WIGGLE else _fbp_load_effect_group(effect_id)
    if not source_group:
        return False

    modifier = fbp_find_effect_modifier(rig, effect_id)
    created_modifier = modifier is None
    if modifier is None:
        try:
            modifier = plane.modifiers.new(
                name=str(definition.get("modifier_name", definition.get("label", effect_id))),
                type="NODES",
            )
        except FBP_DATA_ERRORS as exc:
            fbp_warn(f"Could not add {definition.get('label', effect_id)}", exc)
            return False

    _fbp_remove_duplicate_effect_modifiers(rig, effect_id, modifier)

    previous_group = getattr(modifier, "node_group", None)
    node_group = source_group
    if definition.get("alpha_aware") or definition.get("private_group"):
        node_group = _fbp_owned_geometry_group(
            rig, effect_id, source_group, previous_group
        )
        if not node_group:
            if created_modifier:
                plane.modifiers.remove(modifier)
            return False

    try:
        modifier.name = str(definition.get("modifier_name", definition.get("label", effect_id)))
        modifier.node_group = node_group
        visible = _fbp_stored_effect_visibility(rig, effect_id, True)
        render_visible = _fbp_stored_effect_render_visibility(rig, effect_id, True)
        modifier.show_viewport = visible
        modifier.show_render = render_visible
        instance_id = _fbp_geometry_modifier_instance_id(
            rig, modifier, effect_id, ensure=True
        )
        _fbp_store_effect_instance_id(rig, effect_id, instance_id)
        if bool(definition.get("custom", False)):
            _fbp_initialize_custom_geometry_inputs(modifier, node_group)
    except FBP_DATA_ERRORS as exc:
        fbp_warn("Could not configure Geometry Nodes effect", exc)
        return False

    if previous_group and previous_group != node_group:
        try:
            if bool(previous_group.get("fbp_private_effect_group", False)) and previous_group.users == 0:
                _fbp_remove_node_group(previous_group)
        except FBP_DATA_ERRORS:
            pass

    if effect_id == FBP_EFFECT_MESH_WIGGLE:
        fbp_assign_mesh_wiggle_layer_seed(rig)
        fbp_set_rna_property_silent(rig, "fbp_mesh_wiggle_enabled", True)
    if effect_id == FBP_EFFECT_CAMERA_SCALE_LOCK and created_modifier:
        reference_distance = fbp_camera_distance_for_rig(rig)
        camera = _fbp_scene_camera()
        camera_data = getattr(camera, "data", None) if camera else None
        if reference_distance > 0.0:
            fbp_set_rna_property_silent(
                rig, "fbp_camera_scale_lock_reference_distance", reference_distance
            )
        if camera_data:
            fbp_set_rna_property_silent(
                rig, "fbp_camera_scale_lock_reference_lens",
                float(getattr(camera_data, "lens", 50.0) or 50.0),
            )
            fbp_set_rna_property_silent(
                rig, "fbp_camera_scale_lock_reference_sensor_width",
                float(getattr(camera_data, "sensor_width", 36.0) or 36.0),
            )
    _fbp_set_enabled(rig, effect_id, True)
    if (
        effect_id == FBP_EFFECT_GRADIENT_LIGHT
        and getattr(rig, "fbp_gradient_light_controller", None) is not None
    ):
        fbp_bind_gradient_light_controller(
            rig, rig.fbp_gradient_light_controller
        )
    stored_group = _fbp_stored_effect_group_id(rig, effect_id)
    if stored_group:
        fbp_set_effect_group_id(rig, effect_id, stored_group)
    # A False return here means that every socket already matched its target,
    # not that the modifier failed. Keeping a newly created modifier is required
    # when the bundled node-group defaults already equal the layer settings.
    fbp_update_geometry_effect(rig, effect_id, modifier)
    if effect_id == FBP_EFFECT_FELT_FUZZ:
        _fbp_cleanup_owned_effect_materials(rig, effect_id)
    _fbp_invalidate_effect_ids_cache(rig)
    if sync_items:
        fbp_sync_effect_items(rig)
    return True


def fbp_apply_mesh_wiggle(rig):
    return fbp_apply_geometry_effect(rig, FBP_EFFECT_MESH_WIGGLE)


def fbp_remove_geometry_effect(rig, effect_id, *, sync_items=True):
    effect_id = fbp_normalize_effect_id(effect_id)
    definition = fbp_effect_definition(effect_id)
    plane = _fbp_plane(rig)
    modifiers = _fbp_find_all_effect_modifiers(rig, effect_id)
    if not plane or not modifiers:
        cleaned = _fbp_set_enabled(rig, effect_id, False)
        cleaned = _fbp_clear_effect_visibility(rig, effect_id) or cleaned
        cleaned = _fbp_clear_effect_render_visibility(rig, effect_id) or cleaned
        if bool(definition.get("owned_material", False)) or effect_id in {
            FBP_EFFECT_CUTOUT_OUTLINE, FBP_EFFECT_THICKNESS,
            FBP_EFFECT_FELT_FUZZ, FBP_EFFECT_TEXT_MATRIX,
        }:
            cleaned = _fbp_cleanup_owned_effect_materials(rig, effect_id) or cleaned
        if cleaned:
            _fbp_invalidate_effect_ids_cache(rig)
        if rig and sync_items:
            fbp_sync_effect_items(rig)
        return cleaned

    # Snapshot the original slots because Geometry Nodes evaluation must not
    # replace the image material.
    try:
        material_snapshot = list(plane.data.materials) if getattr(plane, "data", None) else []
        active_material_index = int(getattr(plane, "active_material_index", 0) or 0)
    except FBP_DATA_ERRORS:
        material_snapshot = []
        active_material_index = 0

    removed_groups = []
    removed = False
    for modifier in list(modifiers):
        removed_groups.append(getattr(modifier, "node_group", None))
        try:
            plane.modifiers.remove(modifier)
            removed = True
        except FBP_DATA_ERRORS as exc:
            fbp_warn("Could not remove Geometry Nodes effect", exc)

    if not removed:
        return False

    try:
        current_materials = list(plane.data.materials) if getattr(plane, "data", None) else []
        if current_materials != material_snapshot:
            plane.data.materials.clear()
            for material in material_snapshot:
                if material:
                    plane.data.materials.append(material)
        if material_snapshot:
            plane.active_material_index = min(active_material_index, len(material_snapshot) - 1)
    except FBP_DATA_ERRORS as exc:
        fbp_warn("Could not restore the plane material after removing an effect", exc)

    if effect_id == FBP_EFFECT_MESH_WIGGLE:
        fbp_set_rna_property_silent(rig, "fbp_mesh_wiggle_enabled", False)
    if bool(definition.get("owned_material", False)) or effect_id in {
        FBP_EFFECT_CUTOUT_OUTLINE, FBP_EFFECT_THICKNESS,
        FBP_EFFECT_FELT_FUZZ, FBP_EFFECT_TEXT_MATRIX,
    }:
        _fbp_cleanup_owned_effect_materials(rig, effect_id)
    _fbp_set_enabled(rig, effect_id, False)
    _fbp_clear_effect_visibility(rig, effect_id)
    _fbp_clear_effect_render_visibility(rig, effect_id)

    for node_group in removed_groups:
        try:
            if node_group and bool(node_group.get("fbp_private_effect_group", False)) and node_group.users == 0:
                _fbp_remove_node_group(node_group)
        except FBP_DATA_ERRORS:
            pass
    _fbp_invalidate_effect_ids_cache(rig)
    if sync_items:
        fbp_sync_effect_items(rig)
    return True


def fbp_remove_mesh_wiggle(rig):
    return fbp_remove_geometry_effect(rig, FBP_EFFECT_MESH_WIGGLE)


# ---------------------------------------------------------------------------
# Shader effect nodes and routing
# ---------------------------------------------------------------------------


def _fbp_plane_materials(rig):
    plane = _fbp_plane(rig)
    if not plane or not getattr(plane, "data", None):
        return []
    try:
        return [
            mat
            for mat in plane.data.materials
            if (
                mat
                and _fbp_material_is_owned(mat)
                and getattr(mat, "node_tree", None)
                and mat.node_tree
            )
        ]
    except FBP_DATA_ERRORS:
        return []


def _fbp_shader_image_node(material):
    """Return only the image node owned by the current FBP native material."""
    if not material or not material.node_tree:
        return None
    preferred = material.node_tree.nodes.get("FBP_Native_Media_Texture")
    if preferred and getattr(preferred, "type", "") == "TEX_IMAGE":
        return preferred
    for node in material.node_tree.nodes:
        try:
            if (
                getattr(node, "type", "") == "TEX_IMAGE"
                and bool(node.get("fbp_native_sequence_node", False))
            ):
                return node
        except FBP_DATA_ERRORS:
            continue
    return None


def _fbp_gradient_ramp_node(material):
    if not material or not material.node_tree:
        return None
    node = material.node_tree.nodes.get("FBP_ColorRamp")
    if node and getattr(node, "type", "") == "VALTORGB":
        return node
    for candidate in material.node_tree.nodes:
        try:
            if getattr(candidate, "type", "") == "VALTORGB" and bool(candidate.get("fbp_gradient_ramp", False)):
                return candidate
        except FBP_DATA_ERRORS:
            continue
    return None


def _fbp_procedural_color_source(material, *, create=False):
    """Return a stable color source for solid and gradient FBP materials."""
    if not material or not material.node_tree:
        return None
    image_node = _fbp_shader_image_node(material)
    if image_node:
        return _fbp_node_socket(image_node.outputs, "Color")
    ramp = _fbp_gradient_ramp_node(material)
    if ramp:
        return _fbp_node_socket(ramp.outputs, "Color")

    nodes = material.node_tree.nodes
    # Mesh effects that generate new faces or instances store the sampled
    # source result in named attributes. Use that real per-element color as the
    # input to every Image/Mask effect below the Mesh row.
    attribute_node_names = []
    try:
        if str(material.get("fbp_attribute_color_name", "") or ""):
            attribute_node_names.append("FBP Sampled Instance Color")
        if str(material.get("fbp_text_matrix_color_attribute", "") or ""):
            attribute_node_names.append("FBP Text Matrix Color")
    except FBP_DATA_ERRORS:
        pass
    attribute_node_names.extend((
        "FBP Glass Source Color",
        "FBP Crystal Source Color",
    ))
    for node_name in attribute_node_names:
        attribute = nodes.get(node_name)
        if attribute is None:
            continue
        color_output = _fbp_node_socket(
            getattr(attribute, "outputs", ()), "Color"
        )
        if color_output is not None:
            return color_output

    source = nodes.get("FBP_Procedural_Color_Source")
    if source and getattr(source, "type", "") == "RGB":
        return _fbp_node_socket(source.outputs, "Color", 0)
    if not create:
        return None

    shader = _fbp_primary_color_shader(material)
    color_input = None
    if shader:
        color_input = (
            _fbp_node_socket(shader.inputs, "Color")
            or _fbp_node_socket(shader.inputs, "Base Color")
            or _fbp_node_socket(shader.inputs, "Base Color", 0)
        )
    raw_color = getattr(color_input, "default_value", (1.0, 1.0, 1.0, 1.0))
    try:
        color = tuple(raw_color)
    except TypeError:
        # Holdout and other non-color shaders can expose a scalar first input.
        # A procedural color source is still allowed to fall back safely.
        color = (1.0, 1.0, 1.0, 1.0)
    if len(color) < 4:
        color = tuple(color[:3]) + (1.0,)
    try:
        stored = tuple(material.get("fbp_color_value", color))
        if len(stored) >= 4:
            color = stored
    except FBP_DATA_ERRORS:
        pass
    try:
        source = nodes.new("ShaderNodeRGB")
        source.name = "FBP_Procedural_Color_Source"
        source.label = "Frame by Plane Color Source"
        source.location = (-380.0, 80.0)
        source["fbp_procedural_color_source"] = True
        source.outputs[0].default_value = color
        return source.outputs[0]
    except FBP_DATA_ERRORS:
        return None


def _fbp_material_color_source(material, *, create=False):
    return _fbp_procedural_color_source(material, create=create)


def _fbp_material_color_target(material):
    shader = _fbp_primary_color_shader(material)
    if not shader:
        return None
    return (
        _fbp_node_socket(shader.inputs, "Color")
        or _fbp_node_socket(shader.inputs, "Base Color")
        or _fbp_node_socket(shader.inputs, "Base Color", 0)
    )


def _fbp_material_uv_target(material):
    image_node = _fbp_shader_image_node(material)
    if image_node:
        return _fbp_node_socket(image_node.inputs, "Vector")
    if material and material.node_tree:
        center = material.node_tree.nodes.get("FBP_GradientCenter")
        if center:
            return _fbp_node_socket(center.inputs, "Vector", 0)
    return None


def _fbp_effect_texcoord_source(material, anchor=None):
    if not material or not material.node_tree:
        return None
    nodes = material.node_tree.nodes
    tex_coord = nodes.get("FBP_Effect_Texture_Coordinates")
    if tex_coord is None:
        try:
            tex_coord = nodes.new("ShaderNodeTexCoord")
            tex_coord.name = "FBP_Effect_Texture_Coordinates"
            tex_coord.label = "Frame by Plane Effect UV"
            x = float(getattr(anchor, "location", (0.0, 0.0))[0]) if anchor else -700.0
            y = float(getattr(anchor, "location", (0.0, 0.0))[1]) if anchor else -180.0
            tex_coord.location = (x - 420.0, y - 180.0)
        except FBP_DATA_ERRORS:
            return None
    return _fbp_node_socket(tex_coord.outputs, "UV", 2)


def _fbp_shader_effect_id(node):
    try:
        return fbp_normalize_effect_id(node.get("fbp_shader_effect_id", ""))
    except FBP_DATA_ERRORS:
        return ""


def _fbp_shader_effect_nodes(material, effect_id=None, stage=None, instance_id=""):
    if not material or not material.node_tree:
        return []
    effect_id = fbp_normalize_effect_id(effect_id) if effect_id else ""
    instance_id = str(instance_id or "")
    result = []
    for node in material.node_tree.nodes:
        node_effect_id = _fbp_shader_effect_id(node)
        if not node_effect_id:
            continue
        if effect_id and node_effect_id != effect_id:
            continue
        if instance_id and effect_instance_id(node) != instance_id:
            continue
        if stage and fbp_effect_definition(node_effect_id).get("stage") != stage:
            continue
        result.append(node)
    return result


def _fbp_find_shader_effect_nodes_for_rig(rig, effect_id, instance_id=""):
    result = []
    for material in _fbp_plane_materials(rig):
        result.extend(
            _fbp_shader_effect_nodes(
                material, effect_id=effect_id, instance_id=instance_id
            )
        )
    return result


def _fbp_shader_order_key(stage):
    return f"fbp_shader_effect_order_{str(stage or '').lower()}"


def _fbp_shader_node_token(node):
    """Return the concrete stack token for one shader node."""
    effect_id = _fbp_shader_effect_id(node)
    if not effect_id:
        return ""
    instance_id = effect_instance_id(node)
    return (
        effect_instance_token(effect_id, instance_id)
        if instance_id and _fbp_effect_uses_multi_instances(effect_id)
        else effect_id
    )


def _fbp_shader_token_effect_id(token):
    """Resolve current effect IDs and concrete instance tokens uniformly."""
    effect_id, _instance_id = split_effect_instance_token(str(token or ""))
    return fbp_normalize_effect_id(effect_id or token)


def _fbp_canonical_shader_order_token(token):
    """Collapse ghost instance tokens for effects whose policy is SINGLE."""
    raw = str(token or "").strip()
    effect_id, instance_id = split_effect_instance_token(raw)
    effect_id = fbp_normalize_effect_id(effect_id or raw)
    if not effect_id:
        return ""
    if _fbp_effect_uses_multi_instances(effect_id) and instance_id:
        return effect_instance_token(effect_id, instance_id)
    return effect_id


def _fbp_stage_node_tokens(material, stage):
    """Scan one material stage once for its concrete node tokens.

    Returns ``(node_by_token, tokens_by_effect, node_tokens)`` where
    ``node_tokens`` keeps node-tree order and ``node_by_token`` keeps the last
    node for a repeated token, matching the previous dict-comprehension scans.
    """
    node_by_token = {}
    tokens_by_effect = {}
    node_tokens = []
    for node in _fbp_shader_effect_nodes(material, stage=stage):
        token = _fbp_shader_node_token(node)
        if not token:
            continue
        node_by_token[token] = node
        node_tokens.append(token)
        tokens_by_effect.setdefault(_fbp_shader_effect_id(node), []).append(token)
    return node_by_token, tokens_by_effect, node_tokens


def _fbp_get_rig_shader_stage_order(rig, stage):
    try:
        raw = str(rig.get(_fbp_shader_order_key(stage), "") or "")
    except FBP_DATA_ERRORS:
        raw = ""
    result = []
    for raw_token in raw.split("|"):
        token = _fbp_canonical_shader_order_token(raw_token)
        effect_id = _fbp_shader_token_effect_id(token)
        definition = fbp_effect_definition(effect_id)
        if (
            definition.get("kind") == "SHADER"
            and definition.get("stage") == stage
            and token not in result
        ):
            result.append(token)
    return result


def _fbp_set_rig_shader_stage_order(rig, stage, order):
    normalized = []
    for raw_token in order:
        token = _fbp_canonical_shader_order_token(raw_token)
        effect_id = _fbp_shader_token_effect_id(token)
        definition = fbp_effect_definition(effect_id)
        if definition.get("kind") != "SHADER" or definition.get("stage") != stage:
            continue
        if token not in normalized:
            normalized.append(token)
    value = "|".join(normalized)
    key = _fbp_shader_order_key(stage)
    try:
        if str(rig.get(key, "") or "") != value:
            rig[key] = value
    except FBP_DATA_ERRORS:
        pass
    return normalized


def _fbp_get_shader_stage_order(material, stage):
    stage = str(stage or "")
    active_by_token, tokens_by_effect, node_tokens = _fbp_stage_node_tokens(
        material, stage
    )
    raw = ""
    try:
        raw = str(material.get(_fbp_shader_order_key(stage), "") or "")
    except FBP_DATA_ERRORS:
        pass
    order = []
    for raw_token in raw.split("|"):
        token = _fbp_canonical_shader_order_token(raw_token)
        if token in active_by_token and token not in order:
            order.append(token)
    for effect_id in FBP_SHADER_STAGE_ORDER.get(stage, ()):
        for token in tokens_by_effect.get(effect_id, ()):
            if token not in order:
                order.append(token)
    for token in node_tokens:
        if token not in order:
            order.append(token)
    return order


def _fbp_set_shader_stage_order(material, stage, order):
    active_by_token, tokens_by_effect, node_tokens = _fbp_stage_node_tokens(
        material, stage
    )
    normalized = []
    for raw_token in order:
        token = _fbp_canonical_shader_order_token(raw_token)
        if token in active_by_token:
            if token not in normalized:
                normalized.append(token)
            continue
        effect_id = fbp_normalize_effect_id(token)
        for candidate in tokens_by_effect.get(effect_id, ()):
            if candidate not in normalized:
                normalized.append(candidate)
                break
    for token in node_tokens:
        if token not in normalized:
            normalized.append(token)
    value = "|".join(normalized)
    key = _fbp_shader_order_key(stage)
    try:
        if str(material.get(key, "") or "") != value:
            material[key] = value
    except FBP_DATA_ERRORS:
        pass
    return normalized


def _fbp_stage_effect_nodes(material, stage):
    nodes_by_token = _fbp_stage_node_tokens(material, stage)[0]
    return [
        nodes_by_token[token]
        for token in _fbp_get_shader_stage_order(material, stage)
        if token in nodes_by_token
    ]


def _fbp_local_mask_helper_nodes(material, kind=None):
    if not material or not material.node_tree:
        return []
    result = []
    for node in material.node_tree.nodes:
        try:
            if not bool(node.get("fbp_local_effect_mask_helper", False)):
                continue
            if kind and str(node.get("fbp_local_effect_mask_kind", "") or "") != kind:
                continue
            result.append(node)
        except FBP_DATA_ERRORS:
            continue
    return result


def _fbp_follow_local_mask_chain(material, socket):
    if not material or not material.node_tree or socket is None:
        return None
    current = socket
    visited = set()
    for _ in range(64):
        links = [link for link in material.node_tree.links if link.from_socket == current]
        if not links:
            return None
        link = links[0]
        node = link.to_node
        if node in visited:
            return link.to_socket
        visited.add(node)
        try:
            is_helper = bool(node.get("fbp_local_effect_mask_helper", False))
        except FBP_DATA_ERRORS:
            is_helper = False
        if not is_helper:
            return link.to_socket
        current = _fbp_node_socket(node.outputs, "Color", 0) or _fbp_node_socket(node.outputs, "Value", 0)
        if current is None:
            return link.to_socket
    return None


def _fbp_remove_local_mask_helpers(material, kind=None):
    if not material or not material.node_tree:
        return False
    changed = False
    for node in list(_fbp_local_mask_helper_nodes(material, kind=kind)):
        try:
            material.node_tree.nodes.remove(node)
            changed = True
        except FBP_DATA_ERRORS:
            pass
    return changed


def _fbp_mask_output_socket(node):
    if node is None:
        return None
    definition = fbp_effect_definition(_fbp_shader_effect_id(node))
    name = str(definition.get("mask_output_socket", "Mask Out") or "Mask Out")
    return _fbp_node_socket(node.outputs, name)


def _fbp_local_masks_by_target(rig, mask_nodes):
    """Return active local mask nodes grouped by concrete receiver token."""
    nodes_by_id = {}
    for node in tuple(mask_nodes or ()):
        mask_id = _fbp_shader_effect_id(node)
        if not mask_id:
            continue
        try:
            if bool(getattr(node, "mute", False)):
                continue
        except FBP_DATA_ERRORS:
            pass
        if _fbp_mask_output_socket(node) is not None:
            nodes_by_id[mask_id] = node
    if not rig or not nodes_by_id:
        return {}
    result = {}
    for target, mask_ids in _fbp_mask_target_map(rig).items():
        if target == "LAYER":
            continue
        # Combine in visible Mask-stage order (the order of ``mask_nodes``),
        # not the cached effect-id order: Subtract/Difference depend on it.
        wanted = set(mask_ids)
        resolved = [node for mask_id, node in nodes_by_id.items() if mask_id in wanted]
        if resolved:
            result[target] = resolved
    return result



def _fbp_connect_local_mask_uv_inputs(material, mask_nodes, source):
    """Connect procedural/image mask sampling to the correct pre-effect UV.

    Local masks on UV effects must sample the vector entering that specific UV
    effect. Masks on color effects sample the stable layer UV. Never feed a
    color socket into a mask UV input: Blender will coerce it to a vector and
    produce masks that appear frozen, uniform or dependent on image colors.
    """
    if not material or not material.node_tree or source is None:
        return False
    changed = False
    links = material.node_tree.links
    for node in tuple(mask_nodes or ()):
        definition = fbp_effect_definition(_fbp_shader_effect_id(node))
        socket_name = str(definition.get("uv_input_socket", "") or "")
        if not socket_name:
            continue
        target = _fbp_node_socket(node.inputs, socket_name)
        if target is None:
            continue
        try:
            if len(target.links) == 1 and target.links[0].from_socket == source:
                continue
            for link in list(target.links):
                links.remove(link)
            links.new(source, target)
            changed = True
        except FBP_DATA_ERRORS:
            continue
    return changed


def _fbp_local_mask_preview_socket(rig, mask_nodes):
    """Return the visible debug output of the last local mask in stack order."""
    if not rig:
        return None, ""
    preview_socket = None
    preview_id = ""
    for node in tuple(mask_nodes or ()):
        mask_id = _fbp_shader_effect_id(node)
        if not mask_id or fbp_effect_mask_target(rig, mask_id) == "LAYER":
            continue
        try:
            if bool(getattr(node, "mute", False)):
                continue
        except FBP_DATA_ERRORS:
            pass
        if fbp_effect_debug_mode(rig, mask_id) == "FINAL":
            continue
        definition = fbp_effect_definition(mask_id)
        socket = _fbp_node_socket(
            node.outputs, str(definition.get("output_socket", "Alpha Out") or "Alpha Out")
        ) or _fbp_mask_output_socket(node)
        if socket is not None:
            preview_socket = socket
            preview_id = mask_id
    return preview_socket, preview_id


def _fbp_apply_local_mask_preview(material, rig, mask_nodes, current, *, x=0.0, y=0.0):
    """Replace the color result with a grayscale local-mask diagnostic preview."""
    if not material or not material.node_tree or current is None:
        return current
    preview_socket, preview_id = _fbp_local_mask_preview_socket(rig, mask_nodes)
    if preview_socket is None:
        return current
    try:
        preview = material.node_tree.nodes.new("ShaderNodeMixRGB")
        preview.blend_type = "MIX"
        preview.name = f"FBP Local Mask Preview • {preview_id}"
        preview.label = "Local Mask Preview"
        preview.location = (x, y)
        preview.inputs[1].default_value = (0.0, 0.0, 0.0, 1.0)
        preview.inputs[2].default_value = (1.0, 1.0, 1.0, 1.0)
        preview["fbp_local_effect_mask_helper"] = True
        preview["fbp_local_effect_mask_kind"] = "COLOR"
        preview["fbp_local_effect_mask_preview"] = preview_id
        material.node_tree.links.new(preview_socket, preview.inputs[0])
        return preview.outputs[0]
    except FBP_DATA_ERRORS:
        return current


def _fbp_combine_mask_sockets(
    material,
    current,
    socket,
    operation,
    *,
    kind,
    index,
    x=0.0,
    y=0.0,
):
    """Build one bounded boolean-matte operation and return its result socket."""
    if (
        material is None
        or material.node_tree is None
        or current is None
        or socket is None
    ):
        return current
    operation = str(operation or "INTERSECT").upper()
    links = material.node_tree.links

    def helper(math_operation, label, offset=0):
        node = material.node_tree.nodes.new("ShaderNodeMath")
        node.operation = math_operation
        node.name = f"FBP Mask Stack {label} {kind} {index}.{offset}"
        node.label = label
        node.location = (
            x + index * 105.0 + offset * 70.0,
            y - 120.0,
        )
        node["fbp_local_effect_mask_helper"] = True
        node["fbp_local_effect_mask_kind"] = kind
        node["fbp_mask_stack_operation"] = operation
        return node

    if operation == "ADD":
        combine = helper("MAXIMUM", "Add Masks")
        links.new(current, combine.inputs[0])
        links.new(socket, combine.inputs[1])
        return combine.outputs[0]
    if operation == "SUBTRACT":
        combine = helper("SUBTRACT", "Subtract Mask")
        combine.use_clamp = True
        links.new(current, combine.inputs[0])
        links.new(socket, combine.inputs[1])
        return combine.outputs[0]
    if operation == "DIFFERENCE":
        subtract = helper("SUBTRACT", "Mask Difference", 0)
        absolute = helper("ABSOLUTE", "Absolute Difference", 1)
        links.new(current, subtract.inputs[0])
        links.new(socket, subtract.inputs[1])
        links.new(subtract.outputs[0], absolute.inputs[0])
        return absolute.outputs[0]
    combine = helper("MULTIPLY", "Intersect Masks")
    links.new(current, combine.inputs[0])
    links.new(socket, combine.inputs[1])
    return combine.outputs[0]


def _fbp_combined_mask_factor(
    material,
    mask_nodes,
    *,
    kind,
    x=0.0,
    y=0.0,
):
    active_nodes = []
    for node in tuple(mask_nodes or ()):
        try:
            if bool(getattr(node, "mute", False)):
                continue
        except FBP_DATA_ERRORS:
            pass
        if _fbp_mask_output_socket(node) is not None:
            active_nodes.append(node)
    if not active_nodes:
        return None
    rig = None
    try:
        owner_name = str(material.get("fbp_effect_rig_owner", "") or "")
        rig = bpy.data.objects.get(owner_name) if owner_name else None
    except FBP_DATA_ERRORS:
        rig = None
    current = _fbp_mask_output_socket(active_nodes[0])
    for index, node in enumerate(active_nodes[1:], 1):
        current = _fbp_combine_mask_sockets(
            material,
            current,
            _fbp_mask_output_socket(node),
            fbp_mask_stack_operation(rig, _fbp_shader_effect_id(node)),
            kind=kind,
            index=index,
            x=x,
            y=y,
        )
    return current


def _fbp_stage_external_target(material, _source_node, stage, effect_nodes):
    """Return the socket after an effect stage for image or procedural materials."""
    if stage != "COLOR" or not material or not material.node_tree:
        return None
    effect_set = set(effect_nodes)
    color_pass_nodes = set(_fbp_mask_color_pass_nodes(material))
    source = _fbp_material_color_source(material, create=True)
    candidate_sources = [source]
    candidate_sources.extend(
        _fbp_node_socket(
            node.outputs,
            fbp_effect_definition(_fbp_shader_effect_id(node)).get("output_socket", ""),
        )
        for node in effect_nodes
    )
    for candidate in reversed(candidate_sources):
        if candidate is None:
            continue
        for link in material.node_tree.links:
            if link.from_socket != candidate:
                continue
            if link.to_node in effect_set:
                continue
            try:
                is_helper = bool(link.to_node.get("fbp_local_effect_mask_helper", False))
            except FBP_DATA_ERRORS:
                is_helper = False
            target_socket = (
                _fbp_follow_local_mask_chain(material, candidate)
                if is_helper else link.to_socket
            )
            if target_socket is None or getattr(target_socket, "node", None) in effect_set:
                continue
            if getattr(target_socket, "node", None) in color_pass_nodes:
                # Color Key passes always sit after the stage and are rewired
                # by the rebuild; the stage itself ends at the shader input.
                break
            return target_socket
    return _fbp_material_color_target(material)


def _fbp_stage_external_uv_source(material, _source_node=None, effect_nodes=()):
    if not material or not material.node_tree:
        return None
    target = _fbp_material_uv_target(material)
    effect_set = set(effect_nodes)
    targets = [target] if target is not None else []
    targets.extend(
        _fbp_node_socket(
            node.inputs,
            fbp_effect_definition(_fbp_shader_effect_id(node)).get("input_socket", ""),
        )
        for node in effect_nodes
    )
    def through_mask_mixers(socket):
        # Local-mask UV mixers are deleted and rebuilt with the stage; follow
        # them back to their unmasked input instead of returning a socket that
        # is about to disappear (e.g. after the masked effect was removed).
        seen = set()
        while socket is not None and socket.node.get("fbp_local_effect_mask_helper"):
            if socket.node in seen or len(socket.node.inputs) < 2:
                return None
            seen.add(socket.node)
            unmasked = socket.node.inputs[1]
            socket = unmasked.links[0].from_socket if unmasked.is_linked else None
        if socket is None or socket.node in effect_set:
            return None
        return socket

    for link in material.node_tree.links:
        if link.to_socket in targets and link.from_node not in effect_set:
            source = through_mask_mixers(link.from_socket)
            if source is not None:
                return source
    anchor = _fbp_shader_image_node(material) or _fbp_gradient_ramp_node(material)
    return _fbp_effect_texcoord_source(material, anchor)


def _fbp_auxiliary_uv_source(material, _source_node=None):
    """Return the vector used by UV-aware color effects on every FBP material."""
    if not material or not material.node_tree:
        return None
    target = _fbp_material_uv_target(material)
    if target is not None and getattr(target, "is_linked", False):
        try:
            return target.links[0].from_socket
        except (AttributeError, IndexError, ReferenceError, RuntimeError, TypeError, ValueError):
            pass
    source = _fbp_effect_texcoord_source(
        material,
        _fbp_shader_image_node(material) or _fbp_gradient_ramp_node(material),
    )
    if source is not None and target is not None:
        try:
            material.node_tree.links.new(source, target)
        except FBP_DATA_ERRORS:
            pass
    return source


def _fbp_connect_color_aux_uv(material, _source_node=None, source=None):
    if not material or not material.node_tree:
        return False
    source = source or _fbp_auxiliary_uv_source(material)
    if source is None:
        return False
    changed = False
    for node in _fbp_stage_effect_nodes(material, "COLOR"):
        definition = fbp_effect_definition(_fbp_shader_effect_id(node))
        socket_name = str(definition.get("uv_input_socket", "") or "")
        if not socket_name:
            continue
        target = _fbp_node_socket(node.inputs, socket_name)
        if target is None:
            continue
        try:
            if len(target.links) == 1 and target.links[0].from_socket == source:
                continue
            for link in list(target.links):
                material.node_tree.links.remove(link)
            material.node_tree.links.new(source, target)
            changed = True
        except FBP_DATA_ERRORS:
            pass
    return changed


def _fbp_remove_stage_links(material, _source_node, stage, effect_nodes):
    if not material or not material.node_tree:
        return
    links = material.node_tree.links
    effect_set = set(effect_nodes)
    if stage == "COLOR":
        source = _fbp_material_color_source(material, create=True)
        target = _fbp_material_color_target(material)
        for link in list(links):
            if (
                link.from_socket == source
                or link.from_node in effect_set
                or link.to_node in effect_set
                or (target is not None and link.to_socket == target and link.from_node in effect_set)
            ):
                try:
                    links.remove(link)
                except FBP_DATA_ERRORS:
                    pass
        return

    if stage == "MASK":
        targets = set(_fbp_material_alpha_targets(material))
        for link in list(links):
            if (
                link.from_node in effect_set
                or link.to_node in effect_set
                or link.to_socket in targets
            ):
                try:
                    links.remove(link)
                except FBP_DATA_ERRORS:
                    pass
        return

    if stage == "UV":
        target = _fbp_material_uv_target(material)
        for link in list(links):
            if (
                (target is not None and link.to_socket == target)
                or link.from_node in effect_set
                or link.to_node in effect_set
            ):
                try:
                    links.remove(link)
                except FBP_DATA_ERRORS:
                    pass


def _fbp_apply_global_mask_stack(material, rig, mask_nodes, base_alpha):
    """Combine ordered raw mattes, then apply the result to layer alpha."""
    if (
        material is None
        or material.node_tree is None
        or base_alpha is None
    ):
        return base_alpha, False
    factor = _fbp_combined_mask_factor(
        material,
        mask_nodes,
        kind="ALPHA",
        x=180.0,
        y=-620.0,
    )
    if factor is None:
        return base_alpha, False
    try:
        apply = material.node_tree.nodes.new("ShaderNodeMath")
        apply.operation = "MULTIPLY"
        apply.name = "FBP Mask Stack Layer Alpha"
        apply.label = "Apply Mask Stack"
        apply.location = (520.0, -620.0)
        apply["fbp_local_effect_mask_helper"] = True
        apply["fbp_local_effect_mask_kind"] = "ALPHA"
        apply["fbp_mask_stack_final"] = True
        material.node_tree.links.new(base_alpha, apply.inputs[0])
        material.node_tree.links.new(factor, apply.inputs[1])
        return apply.outputs[0], True
    except FBP_DATA_ERRORS:
        return base_alpha, False


def _fbp_clear_mask_alpha_chain_links(material, mask_nodes):
    """Remove invalid global-alpha links without touching local Mask Out links.

    A mask moved from Layer to one specific effect used to keep its previous
    Alpha In/Alpha Out chain. The local receiver then worked, but the same mask
    could still clip the complete layer. Preserve UV and diagnostic-preview
    links while removing only links that belong to the alpha chain.
    """
    if not material or not material.node_tree:
        return False
    alpha_inputs = set()
    alpha_outputs = set()
    for node in tuple(mask_nodes or ()):
        definition = fbp_effect_definition(_fbp_shader_effect_id(node))
        input_socket = _fbp_node_socket(
            node.inputs, str(definition.get("input_socket", "") or "")
        )
        output_socket = _fbp_node_socket(
            node.outputs, str(definition.get("output_socket", "") or "")
        )
        if input_socket is not None:
            alpha_inputs.add(input_socket)
        if output_socket is not None:
            alpha_outputs.add(output_socket)
    if not alpha_inputs and not alpha_outputs:
        return False
    alpha_targets = set(_fbp_material_alpha_targets(material))
    changed = False
    for link in list(material.node_tree.links):
        remove = link.to_socket in alpha_inputs
        if not remove and link.from_socket in alpha_outputs:
            helper_kind = ""
            try:
                helper_kind = str(link.to_node.get("fbp_local_effect_mask_kind", "") or "")
            except FBP_DATA_ERRORS:
                pass
            remove = (
                link.to_socket in alpha_inputs
                or link.to_socket in alpha_targets
                or helper_kind == "ALPHA"
            )
        if not remove:
            continue
        try:
            material.node_tree.links.remove(link)
            changed = True
        except FBP_DATA_ERRORS:
            pass
    return changed


def _fbp_local_target_by_mask(rig):
    """Return ``{mask_effect_id: target_ref}`` for locally targeted masks."""
    if not rig:
        return {}
    return {
        mask_id: target
        for target, mask_ids in _fbp_mask_target_map(rig).items()
        for mask_id in mask_ids
    }


def _fbp_connect_base_mask_uv_inputs(
    material, rig, mask_nodes, uv_source, *, local_target_by_mask=None
):
    """Feed the final layer UV into every mask that does not target a UV effect.

    Masks attached to a UV effect receive that effect's incoming vector while
    the UV stage is rebuilt. Every other mask samples the final layer UV, which
    changes whenever the UV stage is reordered or rebuilt.
    """
    if local_target_by_mask is None:
        local_target_by_mask = _fbp_local_target_by_mask(rig)
    base_uv_masks = []
    for node in tuple(mask_nodes or ()):
        target_effect_id = local_target_by_mask.get(_fbp_shader_effect_id(node), "LAYER")
        if str(fbp_effect_definition(target_effect_id).get("stage", "") or "") != "UV":
            base_uv_masks.append(node)
    return _fbp_connect_local_mask_uv_inputs(material, base_uv_masks, uv_source)


def _fbp_relink_effect_alpha(material, effect_nodes, base_alpha):
    """Route effect alpha through local masks, then the global Mask Stack."""
    if not material or not material.node_tree:
        return False
    changed = _fbp_remove_local_mask_helpers(material, kind="ALPHA")
    links = material.node_tree.links
    rig = None
    try:
        owner_name = str(material.get("fbp_effect_rig_owner", "") or "")
        rig = bpy.data.objects.get(owner_name) if owner_name else None
    except FBP_DATA_ERRORS:
        rig = None
    mask_nodes = _fbp_stage_effect_nodes(material, "MASK")
    changed = _fbp_clear_mask_alpha_chain_links(material, mask_nodes) or changed
    local_by_target = _fbp_local_masks_by_target(rig, mask_nodes)
    current = base_alpha
    for node in effect_nodes:
        effect_id = _fbp_shader_effect_id(node)
        definition = fbp_effect_definition(effect_id)
        previous = current
        alpha_input = _fbp_node_socket(node.inputs, str(definition.get("alpha_input_socket", "") or ""))
        if alpha_input is not None and current is not None:
            try:
                if len(alpha_input.links) != 1 or alpha_input.links[0].from_socket != current:
                    for link in list(alpha_input.links):
                        links.remove(link)
                    links.new(current, alpha_input)
                    changed = True
            except FBP_DATA_ERRORS:
                pass
        effect_alpha = _fbp_node_socket(node.outputs, str(definition.get("alpha_output_socket", "") or "")) or current
        target_token = _fbp_effect_ref(
            effect_id,
            (
                effect_instance_id(node)
                if _fbp_effect_uses_multi_instances(effect_id)
                else ""
            ),
        )
        masks = local_by_target.get(target_token, ())
        if masks and previous is not None and effect_alpha is not None:
            factor = _fbp_combined_mask_factor(
                material, masks, kind="ALPHA", x=float(node.location.x), y=float(node.location.y) - 220.0
            )
            if factor is not None:
                inv = material.node_tree.nodes.new("ShaderNodeMath")
                inv.operation = "SUBTRACT"
                inv.inputs[0].default_value = 1.0
                inv.name = f"FBP Local Alpha Mask Invert • {effect_id}"
                inv["fbp_local_effect_mask_helper"] = True
                inv["fbp_local_effect_mask_kind"] = "ALPHA"
                a = material.node_tree.nodes.new("ShaderNodeMath")
                a.operation = "MULTIPLY"
                a.name = f"FBP Local Alpha Original • {effect_id}"
                a["fbp_local_effect_mask_helper"] = True
                a["fbp_local_effect_mask_kind"] = "ALPHA"
                b = material.node_tree.nodes.new("ShaderNodeMath")
                b.operation = "MULTIPLY"
                b.name = f"FBP Local Alpha Effect • {effect_id}"
                b["fbp_local_effect_mask_helper"] = True
                b["fbp_local_effect_mask_kind"] = "ALPHA"
                add = material.node_tree.nodes.new("ShaderNodeMath")
                add.operation = "ADD"
                add.name = f"FBP Local Alpha Result • {effect_id}"
                add["fbp_local_effect_mask_helper"] = True
                add["fbp_local_effect_mask_kind"] = "ALPHA"
                for helper_index, helper in enumerate((inv, a, b, add)):
                    helper.location = (float(node.location.x) + 90.0 + helper_index * 70.0, float(node.location.y) - 260.0)
                links.new(factor, inv.inputs[1])
                links.new(previous, a.inputs[0])
                links.new(inv.outputs[0], a.inputs[1])
                links.new(effect_alpha, b.inputs[0])
                links.new(factor, b.inputs[1])
                links.new(a.outputs[0], add.inputs[0])
                links.new(b.outputs[0], add.inputs[1])
                current = add.outputs[0]
            else:
                current = effect_alpha
        else:
            current = effect_alpha

    global_masks = []
    local_target_by_mask = _fbp_local_target_by_mask(rig)
    for index, node in enumerate(mask_nodes):
        node.location = (180.0 + index * 190.0, -420.0)
        if local_target_by_mask.get(_fbp_shader_effect_id(node), "LAYER") == "LAYER":
            global_masks.append(node)
    changed = _fbp_connect_base_mask_uv_inputs(
        material, rig, mask_nodes, _fbp_auxiliary_uv_source(material),
        local_target_by_mask=local_target_by_mask,
    ) or changed
    current, mask_changed = _fbp_apply_global_mask_stack(
        material,
        rig,
        global_masks,
        current,
    )
    changed = mask_changed or changed
    if current is None:
        return changed
    has_alpha_effect = bool(global_masks) or any(
        bool(fbp_effect_definition(_fbp_shader_effect_id(node)).get("alpha_output_socket"))
        for node in effect_nodes
    )
    targets = _fbp_material_alpha_targets(material)
    if has_alpha_effect and not targets:
        targets = _fbp_ensure_effect_alpha_targets(material)
    for target in targets:
        try:
            if len(target.links) == 1 and target.links[0].from_socket == current:
                continue
            for link in list(target.links):
                links.remove(link)
            links.new(current, target)
            changed = True
        except FBP_DATA_ERRORS:
            pass
    return changed

def _fbp_color_stage_evaluation_nodes(material, rig=None):
    """Return color effect nodes in their real evaluation order."""
    effect_nodes = _fbp_stage_effect_nodes(material, "COLOR")
    if rig is None:
        try:
            owner_name = str(material.get("fbp_effect_rig_owner", "") or "")
            rig = bpy.data.objects.get(owner_name) if owner_name else None
        except FBP_DATA_ERRORS:
            rig = None
    regular_nodes = []
    final_nodes = []
    for node in effect_nodes:
        effect_id = _fbp_shader_effect_id(node)
        instance_id = effect_instance_id(node)
        if rig and fbp_effect_input_source(rig, effect_id, instance_id) == "FINAL":
            final_nodes.append(node)
        else:
            regular_nodes.append(node)
    return regular_nodes + final_nodes


def _fbp_mask_color_pass_nodes(material, mask_nodes=None):
    """Return mask nodes that also filter color (Color Key despill)."""
    if mask_nodes is None:
        mask_nodes = _fbp_stage_effect_nodes(material, "MASK")
    result = []
    for node in tuple(mask_nodes or ()):
        definition = fbp_effect_definition(_fbp_shader_effect_id(node))
        if (
            _fbp_node_socket(node.inputs, str(definition.get("color_input_socket", "") or "")) is not None
            and _fbp_node_socket(node.outputs, str(definition.get("color_output_socket", "") or "")) is not None
        ):
            result.append(node)
    return result


def _fbp_apply_mask_color_passes(material, rig, mask_nodes, current):
    """Route the final layer color through every Layer-targeted color pass.

    Masks normally only shape alpha. Color Key also greys the leftover key
    color (Despill), so when it targets the whole layer the completed color
    chain flows through its ``Color In``/``Color Out`` pair. Locally targeted
    keys leave the color untouched: their matte already blends one effect.
    """
    if not material or not material.node_tree or current is None:
        return current
    tree = material.node_tree
    local_target_by_mask = _fbp_local_target_by_mask(rig)
    for node in _fbp_mask_color_pass_nodes(material, mask_nodes):
        effect_id = _fbp_shader_effect_id(node)
        definition = fbp_effect_definition(effect_id)
        color_in = _fbp_node_socket(node.inputs, str(definition.get("color_input_socket", "") or ""))
        color_out = _fbp_node_socket(node.outputs, str(definition.get("color_output_socket", "") or ""))
        try:
            for link in list(color_in.links):
                tree.links.remove(link)
        except FBP_DATA_ERRORS:
            continue
        if local_target_by_mask.get(effect_id, "LAYER") != "LAYER":
            continue
        try:
            tree.links.new(current, color_in)
            current = color_out
        except FBP_DATA_ERRORS:
            continue
    try:
        material["fbp_mask_color_pass"] = bool(_fbp_mask_color_pass_nodes(material, mask_nodes))
    except FBP_DATA_ERRORS:
        pass
    return current


def _fbp_rebuild_local_mask_receivers(material):
    """Rebuild every shader stage that can receive a local mask."""
    changed = _fbp_rebuild_shader_stage(material, "UV")
    changed = _fbp_rebuild_shader_stage(material, "COLOR") or changed
    try:
        if int(material.get("fbp_local_effect_mask_wiring_version", 0) or 0) != FBP_LOCAL_EFFECT_MASK_WIRING_VERSION:
            material["fbp_local_effect_mask_wiring_version"] = FBP_LOCAL_EFFECT_MASK_WIRING_VERSION
            changed = True
    except FBP_DATA_ERRORS:
        pass
    return changed


def _fbp_rebuild_shader_stage(material, stage, source_override=None, target_override=None):
    """Rebuild one shader stage, then restore the links modifiers drive."""
    result = _fbp_rebuild_shader_stage_links(material, stage, source_override, target_override)
    if material is not None and getattr(material, "node_tree", None) is not None:
        try:
            from .effect_shells import fbp_shell_relink_material
            fbp_shell_relink_material(material)
        except (ImportError, *FBP_DATA_ERRORS):
            pass
        fbp_tidy_layer_material(material)
    return result


# Shared coordinates stay in the Source section even when one effect uses them.
_FBP_NODE_VIEW_SOURCE_TYPES = {"ShaderNodeTexCoord", "ShaderNodeUVMap", "ShaderNodeNewGeometry"}


def _fbp_node_view_owned(node):
    """True for nodes Frame By Plane generated in a layer material."""
    try:
        if node.bl_idname == "NodeFrame":
            return False
        name = str(node.name or "")
        if name.startswith(("FBP", "fbp")) or str(node.label or "").startswith("Frame by Plane"):
            return True
        return any(str(key).startswith("fbp_") for key in node.keys())
    except FBP_DATA_ERRORS:
        return False


def fbp_layer_material_view_sections(material):
    """Group a layer material's generated nodes into readable sections.

    Returns ``{section: [(label, nodes), ...]}`` for
    :func:`node_layout.layout_layer_material`. Each effect becomes one block
    with the nodes that only feed it (its modifier inputs, local mask mix).
    """
    tree = getattr(material, "node_tree", None)
    if tree is None:
        return {}
    owned = []
    for node in tree.nodes:
        if not _fbp_node_view_owned(node):
            continue
        parent = getattr(node, "parent", None)
        if parent is not None and not is_node_view_helper(parent):
            continue  # inside an artist's own frame
        owned.append(node)
    if not owned:
        return {}
    members = set(owned)
    producers = {node: set() for node in owned}
    consumers = {node: set() for node in owned}
    for link in tuple(tree.links):
        try:
            source, target = link.from_node, link.to_node
        except FBP_DATA_ERRORS:
            continue
        if source in members and target in members and source is not target:
            producers[target].add(source)
            consumers[source].add(target)

    rig = None
    try:
        owner_name = str(material.get("fbp_effect_rig_owner", "") or "")
        rig = bpy.data.objects.get(owner_name) if owner_name else None
    except FBP_DATA_ERRORS:
        rig = None
    stage_of = {}
    order_of = {}
    for stage in ("UV", "COLOR", "MASK"):
        try:
            ordered = (
                _fbp_color_stage_evaluation_nodes(material, rig)
                if stage == "COLOR" else _fbp_stage_effect_nodes(material, stage)
            )
        except FBP_DATA_ERRORS:
            ordered = []
        for index, node in enumerate(ordered):
            if node in members:
                stage_of[node] = stage
                order_of[node] = index
    for node in owned:
        if node in stage_of:
            continue
        effect_id = _fbp_shader_effect_id(node)
        if effect_id:
            stage = str(fbp_effect_definition(effect_id).get("stage", "") or "COLOR")
            stage_of[node] = stage if stage in {"UV", "COLOR", "MASK"} else "COLOR"
            order_of[node] = 10_000 + len(order_of)

    block_of = {node: node for node in stage_of}
    token_owner = {}
    for node in stage_of:
        effect_id = _fbp_shader_effect_id(node)
        token = _fbp_effect_ref(
            effect_id,
            effect_instance_id(node) if _fbp_effect_uses_multi_instances(effect_id) else "",
        )
        token_owner.setdefault(token, node)
        token_owner.setdefault(effect_id, node)
    by_name = {node.name: node for node in owned}
    image_nodes = [node for node in owned if node.bl_idname == "ShaderNodeTexImage" and node not in block_of]
    for node in image_nodes:
        block_of[node] = "IMAGE"
    for node in owned:
        if node in block_of:
            continue
        try:
            target_name = str(node.get("fbp_shell_target", "") or "")
            target_token = str(node.get("fbp_local_effect_mask_target", "") or "")
        except FBP_DATA_ERRORS:
            target_name = target_token = ""
        anchor = by_name.get(target_name) if target_name else token_owner.get(target_token)
        if anchor is not None and anchor in block_of:
            block_of[node] = block_of[anchor]

    # Nodes whose only neighbours belong to one block join that block.
    changed = True
    while changed:
        changed = False
        for node in owned:
            if node in block_of or node.bl_idname in _FBP_NODE_VIEW_SOURCE_TYPES:
                continue
            outs = consumers[node]
            ins = producers[node]
            if not outs:
                continue
            blocks = {block_of[item] for item in outs if item in block_of}
            blocks.update(block_of[item] for item in ins if item in block_of)
            if len(blocks) != 1:
                continue
            if any(item not in block_of for item in outs):
                continue
            if any(item not in block_of and producers[item] for item in ins):
                continue
            block_of[node] = next(iter(blocks))
            changed = True

    def upstream_stages(node):
        seen = set()
        stack = list(producers[node])
        stages = set()
        while stack:
            item = stack.pop()
            if item in seen:
                continue
            seen.add(item)
            block = block_of.get(item)
            if block == "IMAGE" or item in image_nodes:
                stages.add("IMAGE")
            elif block is not None:
                stages.add(stage_of.get(block, "COLOR"))
            stack.extend(producers[item])
        return stages

    sections = {key: [] for key in ("SOURCE", "UV", "IMAGE", "COLOR", "MASK", "OUTPUT")}
    leftovers = {"SOURCE": [], "MASK": [], "OUTPUT": []}
    for node in owned:
        if node in block_of:
            continue
        if not producers[node]:
            leftovers["SOURCE"].append(node)
            continue
        stages = upstream_stages(node)
        leftovers["MASK" if stages and stages <= {"MASK", "UV"} and "MASK" in stages else "OUTPUT"].append(node)

    grouped = defaultdict(list)
    for node, block in block_of.items():
        grouped[block].append(node)
    for stage in ("UV", "COLOR", "MASK"):
        effects = sorted(
            (node for node in stage_of if stage_of[node] == stage),
            key=lambda item: (order_of.get(item, 0), item.name),
        )
        for index, node in enumerate(effects):
            label = str(node.label or fbp_effect_definition(_fbp_shader_effect_id(node)).get("label", "") or node.name)
            if bool(getattr(node, "mute", False)):
                label += " (hidden)"
            sections[stage].append((f"{index + 1} · {label}", grouped[node]))
    if grouped.get("IMAGE"):
        sections["IMAGE"].append(("Layer image", grouped["IMAGE"]))
    if leftovers["SOURCE"]:
        sections["SOURCE"].append(("Source", leftovers["SOURCE"]))
    if leftovers["MASK"]:
        sections["MASK"].append(("Combine masks", leftovers["MASK"]))
    if leftovers["OUTPUT"]:
        sections["OUTPUT"].append(("Output", leftovers["OUTPUT"]))
    return {key: value for key, value in sections.items() if value}


def fbp_tidy_layer_material(material, *, force=False, annotate=None):
    """Keep a layer material readable: effects in order, framed and labelled.

    Display only: nodes are moved and framed, never renamed or relinked. The
    check is a cheap signature, so calling this after every rebuild is fine.
    """
    tree = getattr(material, "node_tree", None)
    if tree is None:
        return False
    try:
        if not bool(material.get("fbp_effect_rig_owner", "")) and not any(
            _fbp_shader_effect_id(node) for node in tree.nodes
        ):
            return False
    except FBP_DATA_ERRORS:
        return False
    if annotate is None:
        annotate = node_view_annotations_enabled()
    if not force and node_view_is_current(tree, annotate=annotate):
        return True
    try:
        sections = fbp_layer_material_view_sections(material)
        return layout_layer_material(
            tree,
            sections,
            title=str(getattr(material, "name", "") or ""),
            annotate=annotate,
            force=True,
        )
    except FBP_DATA_ERRORS as exc:
        fbp_warn("Could not tidy the layer material's nodes", exc)
        return False


def fbp_tidy_effect_group(node_group, effect_id="", *, force=False, annotate=None):
    """Lay out one generated effect group (never a custom or user-edited one)."""
    if node_group is None:
        return False
    try:
        if bool(node_group.get("fbp_user_editable_effect_group", False)):
            return False
    except FBP_DATA_ERRORS:
        return False
    definition = fbp_effect_definition(effect_id) if effect_id else {}
    if bool(definition.get("custom", False)):
        return False
    title = str(definition.get("label", "") or "")
    description = str(definition.get("description", "") or "")
    asset_id = str(definition.get("asset_id", "") or "")
    if asset_id:
        # Some groups serve several effects (Mesh Wiggle and Wind Bender):
        # name them all and leave out a description that fits only one.
        sharing = [
            str(other.get("label", "") or key)
            for key, other in FBP_EFFECT_REGISTRY.items()
            if str(other.get("asset_id", "") or "") == asset_id
        ]
        if len(sharing) > 1:
            title = " / ".join(sharing[:3])
            description = "Shared by: " + ", ".join(sharing) + "."
    return tidy_effect_group(
        node_group,
        title=title,
        description=description,
        annotate=annotate,
        force=force,
    )


def fbp_tidy_all_node_views(*, force=True, annotate=None):
    """Re-tidy every generated layer material and effect group in the file."""
    count = 0
    for material in tuple(bpy.data.materials):
        try:
            if getattr(material, "library", None) is not None or material.node_tree is None:
                continue
        except FBP_DATA_ERRORS:
            continue
        if fbp_tidy_layer_material(material, force=force, annotate=annotate):
            count += 1
    for node_group in tuple(bpy.data.node_groups):
        try:
            if getattr(node_group, "library", None) is not None:
                continue
            effect_id = str(node_group.get("fbp_effect_id", "") or "")
            shell = bool(node_group.get("fbp_shell_group", False))
            if shell:
                from .effect_shells import fbp_tidy_shell_group
                if fbp_tidy_shell_group(node_group, force=force, annotate=annotate):
                    count += 1
                continue
            if not effect_id:
                continue
        except (ImportError, *FBP_DATA_ERRORS):
            continue
        if fbp_tidy_effect_group(node_group, effect_id, force=force, annotate=annotate):
            count += 1
    return count


def _fbp_rebuild_shader_stage_links(material, stage, source_override=None, target_override=None):
    if not material or not material.node_tree:
        return False
    effect_nodes = _fbp_stage_effect_nodes(material, stage)
    links = material.node_tree.links
    image_node = _fbp_shader_image_node(material)

    if stage == "UV":
        source = source_override or _fbp_stage_external_uv_source(material, image_node, effect_nodes)
        target = _fbp_material_uv_target(material)
        _fbp_remove_local_mask_helpers(material, kind="UV")
        _fbp_remove_stage_links(material, image_node, stage, effect_nodes)
        current = source
        anchor = image_node or _fbp_gradient_ramp_node(material)
        anchor_x = float(getattr(anchor, "location", (-80.0, 0.0))[0])
        anchor_y = float(getattr(anchor, "location", (0.0, 0.0))[1])
        rig = None
        try:
            owner_name = str(material.get("fbp_effect_rig_owner", "") or "")
            rig = bpy.data.objects.get(owner_name) if owner_name else None
        except FBP_DATA_ERRORS:
            rig = None
        local_masks_by_target = _fbp_local_masks_by_target(
            rig, _fbp_stage_effect_nodes(material, "MASK")
        )
        for index, node in enumerate(effect_nodes):
            effect_id = _fbp_shader_effect_id(node)
            definition = fbp_effect_definition(effect_id)
            input_socket = _fbp_node_socket(node.inputs, definition.get("input_socket", ""))
            output_socket = _fbp_node_socket(node.outputs, definition.get("output_socket", ""))
            previous = current
            if current and input_socket:
                _fbp_link_single(material.node_tree, current, input_socket)
            effect_output = output_socket or current
            node.location = (anchor_x - 360.0 + index * 220.0, anchor_y - 220.0)
            target_token = _fbp_effect_ref(
                effect_id,
                (
                    effect_instance_id(node)
                    if _fbp_effect_uses_multi_instances(effect_id)
                    else ""
                ),
            )
            masks = local_masks_by_target.get(target_token, ())
            if masks and previous is not None and effect_output is not None:
                _fbp_connect_local_mask_uv_inputs(material, masks, previous)
                factor = _fbp_combined_mask_factor(
                    material, masks, kind="UV",
                    x=float(node.location.x), y=float(node.location.y) - 120.0,
                )
                if factor is not None:
                    mixer = material.node_tree.nodes.new("ShaderNodeMixRGB")
                    mixer.blend_type = "MIX"
                    mixer.name = f"FBP UV Effect Mask Mix • {effect_id}"
                    mixer.label = "UV Effect Mask"
                    mixer.location = (float(node.location.x) + 150.0, float(node.location.y))
                    mixer["fbp_local_effect_mask_helper"] = True
                    mixer["fbp_local_effect_mask_kind"] = "UV"
                    mixer["fbp_local_effect_mask_target"] = target_token
                    links.new(factor, mixer.inputs[0])
                    links.new(previous, mixer.inputs[1])
                    links.new(effect_output, mixer.inputs[2])
                    current = mixer.outputs[0]
                else:
                    current = effect_output
            else:
                current = effect_output
        if current and target:
            _fbp_link_single(material.node_tree, current, target)
        _fbp_connect_color_aux_uv(material, image_node, current)
        # Removing the old UV stage links also detached mask UV inputs that
        # sampled the previous final UV; restore them from the new chain end.
        _fbp_connect_base_mask_uv_inputs(
            material, rig, _fbp_stage_effect_nodes(material, "MASK"), current
        )
        try:
            material["fbp_shader_chain_wiring_version"] = FBP_SHADER_CHAIN_WIRING_VERSION
        except FBP_DATA_ERRORS:
            pass
        return bool(current)

    if stage == "MASK":
        rig = None
        try:
            owner_name = str(material.get("fbp_effect_rig_owner", "") or "")
            rig = bpy.data.objects.get(owner_name) if owner_name else None
        except FBP_DATA_ERRORS:
            rig = None
        # A color-pass mask (Color Key) sits at the end of the color chain, so
        # adding, removing or retargeting it rewires the color stage too.
        color_pass = bool(_fbp_mask_color_pass_nodes(material, effect_nodes))
        try:
            color_pass = color_pass or bool(material.get("fbp_mask_color_pass", False))
        except FBP_DATA_ERRORS:
            pass
        if (
            (rig and bool(_fbp_mask_target_map(rig)))
            or bool(_fbp_local_mask_helper_nodes(material))
            or color_pass
        ):
            return _fbp_rebuild_local_mask_receivers(material)
        _fbp_remove_stage_links(material, image_node, stage, effect_nodes)
        layer_alpha = _fbp_material_layer_alpha_source(material, image_node)
        evaluation_nodes = _fbp_color_stage_evaluation_nodes(material, rig)
        return _fbp_relink_effect_alpha(material, evaluation_nodes, layer_alpha)

    if stage != "COLOR":
        return False

    source = _fbp_material_color_source(material, create=True)
    target = target_override or _fbp_stage_external_target(material, image_node, stage, effect_nodes)
    if source is None or target is None:
        return False
    _fbp_remove_local_mask_helpers(material, kind="COLOR")
    uv_source = _fbp_auxiliary_uv_source(material, image_node)
    layer_alpha = _fbp_material_layer_alpha_source(material, image_node)
    _fbp_remove_stage_links(material, image_node, stage, effect_nodes)
    current = source
    anchor = image_node or _fbp_gradient_ramp_node(material) or getattr(source, "node", None)
    anchor_x = float(getattr(anchor, "location", (-180.0, 0.0))[0])
    anchor_y = float(getattr(anchor, "location", (0.0, 0.0))[1])
    rig = None
    try:
        owner_name = str(material.get("fbp_effect_rig_owner", "") or "")
        rig = bpy.data.objects.get(owner_name) if owner_name else None
    except FBP_DATA_ERRORS:
        rig = None
    # Final Material is deliberately evaluated as a terminal pass. This keeps
    # the graph acyclic: normal Previous/Original effects build the regular
    # stack first, then every Final Material effect processes that completed
    # result in its relative stack order.
    evaluation_nodes = _fbp_color_stage_evaluation_nodes(material, rig)

    local_masks_by_target = _fbp_local_masks_by_target(
        rig, _fbp_stage_effect_nodes(material, "MASK")
    )
    for index, node in enumerate(evaluation_nodes):
        effect_id = _fbp_shader_effect_id(node)
        definition = fbp_effect_definition(effect_id)
        input_socket = _fbp_node_socket(node.inputs, definition.get("input_socket", ""))
        output_socket = _fbp_node_socket(node.outputs, definition.get("output_socket", ""))
        input_source = (
            fbp_effect_input_source(rig, effect_id, effect_instance_id(node))
            if rig else "PREVIOUS"
        )
        previous = current
        node_source = source if input_source == "ORIGINAL" else current
        if node_source and input_socket:
            # Every effect input owns exactly one upstream link. Clearing stale
            # links here is essential after add/reorder/undo and makes the real
            # stack deterministic for downstream effects such as Color Ramp.
            _fbp_link_single(material.node_tree, node_source, input_socket)
        if uv_source:
            uv_input = _fbp_node_socket(node.inputs, definition.get("uv_input_socket", ""))
            if uv_input:
                _fbp_link_single(material.node_tree, uv_source, uv_input)
        effect_output = output_socket or current
        node.location = (anchor_x + 120.0 + index * 240.0, anchor_y + 250.0)
        target_token = _fbp_effect_ref(
            effect_id,
            (
                effect_instance_id(node)
                if _fbp_effect_uses_multi_instances(effect_id)
                else ""
            ),
        )
        masks = local_masks_by_target.get(target_token, ())
        if masks and previous is not None and effect_output is not None:
            # Color effects do not alter the layer UV. Their masks therefore
            # sample the stable UV source, while the color blend still mixes
            # the previous and processed colors below.
            _fbp_connect_local_mask_uv_inputs(material, masks, uv_source)
            factor = _fbp_combined_mask_factor(
                material, masks, kind="COLOR", x=float(node.location.x), y=float(node.location.y)
            )
            if factor is not None:
                mixer = material.node_tree.nodes.new("ShaderNodeMixRGB")
                mixer.blend_type = "MIX"
                mixer.name = f"FBP Effect Mask Mix • {effect_id}"
                mixer.label = "Effect Mask"
                mixer.location = (float(node.location.x) + 150.0, float(node.location.y))
                mixer["fbp_local_effect_mask_helper"] = True
                mixer["fbp_local_effect_mask_kind"] = "COLOR"
                mixer["fbp_local_effect_mask_target"] = target_token
                links.new(factor, mixer.inputs[0])
                links.new(previous, mixer.inputs[1])
                links.new(effect_output, mixer.inputs[2])
                current = mixer.outputs[0]
            else:
                current = effect_output
        else:
            current = effect_output
    current = _fbp_apply_mask_color_passes(
        material,
        rig,
        _fbp_stage_effect_nodes(material, "MASK"),
        current,
    )
    current = _fbp_apply_local_mask_preview(
        material,
        rig,
        _fbp_stage_effect_nodes(material, "MASK"),
        current,
        x=anchor_x + 120.0 + max(1, len(evaluation_nodes)) * 240.0,
        y=anchor_y + 250.0,
    )
    if not _fbp_link_single(material.node_tree, current, target):
        try:
            already_linked = bool(
                len(target.links) == 1 and target.links[0].from_socket == current
            )
        except FBP_DATA_ERRORS:
            already_linked = False
        if not already_linked:
            return False
    _fbp_relink_effect_alpha(material, evaluation_nodes, layer_alpha)
    try:
        material["fbp_shader_chain_wiring_version"] = FBP_SHADER_CHAIN_WIRING_VERSION
    except FBP_DATA_ERRORS:
        pass
    return True


def _fbp_depth_blur_focus_distance(rig, scene=None):
    """Resolve the effective focus distance for the Depth Blur effect."""
    fallback = max(0.0, float(getattr(rig, "fbp_depth_blur_focus_distance", 10.0) or 10.0))
    if not bool(getattr(rig, "fbp_depth_blur_use_camera_focus", True)):
        return fallback
    scene = scene or getattr(bpy.context, "scene", None)
    camera = _fbp_scene_camera(scene)
    camera_data = getattr(camera, "data", None) if camera else None
    dof = getattr(camera_data, "dof", None) if camera_data else None
    if camera is None or dof is None:
        return fallback
    focus_object = getattr(dof, "focus_object", None)
    if focus_object is not None:
        try:
            local = camera.matrix_world.inverted_safe() @ focus_object.matrix_world.translation
            return max(0.0, abs(float(local.z)))
        except FBP_DATA_ERRORS:
            pass
    try:
        return max(0.0, float(getattr(dof, "focus_distance", fallback) or fallback))
    except FBP_DATA_ERRORS:
        return fallback


def _fbp_sync_source_texel_inputs(rig, node, material=None):
    """Push inverse source-image dimensions into image-aware sampling effects."""
    if not rig or not node:
        return False
    material = material or _fbp_material_for_shader_node(rig, node)
    source_node = _fbp_shader_image_node(material) if material else None
    source_image = getattr(source_node, "image", None) if source_node else None
    width = height = 1
    try:
        size = tuple(getattr(source_image, "size", (1, 1)) or (1, 1))
        width = max(1, int(size[0]))
        height = max(1, int(size[1]))
    except FBP_DATA_ERRORS:
        pass
    if source_image is None and _fbp_shader_effect_id(node) == FBP_EFFECT_DITHER:
        # Procedural Color/Gradient planes have no source image dimensions.
        # Give ordered dithering a stable virtual raster instead of collapsing
        # the whole plane into a single 1x1 cell.
        width = height = 1024
    changed = False
    for socket_name, value in (("Texel X", 1.0 / float(width)), ("Texel Y", 1.0 / float(height))):
        socket = _fbp_node_socket(getattr(node, "inputs", ()), socket_name)
        if socket is None or _fbp_effect_values_equal(getattr(socket, "default_value", None), value):
            continue
        try:
            socket.default_value = value
            changed = True
        except FBP_DATA_ERRORS:
            pass
    return changed


def _fbp_sync_depth_blur_runtime_inputs(rig, node, material=None, scene=None):
    """Push mode and camera focus into one private depth-blur node."""
    if not rig or not node:
        return False
    changed = False
    depth_mode = str(getattr(rig, "fbp_depth_blur_mode", "MANUAL") or "MANUAL") == "DEPTH"
    values = {
        "Mode": 1.0 if depth_mode else 0.0,
    }
    # Camera focus can change every frame, but it is irrelevant in Manual mode.
    # Avoid resolving camera/object matrices and touching the socket when the
    # effect uses a fixed radius.
    if depth_mode:
        values["Focus Distance"] = _fbp_depth_blur_focus_distance(rig, scene=scene)
    for socket_name, value in values.items():
        socket = _fbp_node_socket(getattr(node, "inputs", ()), socket_name)
        if socket is None or _fbp_effect_values_equal(getattr(socket, "default_value", None), value):
            continue
        try:
            socket.default_value = value
            changed = True
        except FBP_DATA_ERRORS:
            pass
    return changed


def _fbp_sync_gradient_light_ramp(rig, node, *, property_names=None):
    """Apply the compact Gradient controls to its editable native ramp."""
    requested = None if property_names is None else {
        str(name) for name in property_names if str(name or "")
    }
    color_property = "fbp_gradient_shadow_color"
    softness_property = "fbp_gradient_softness"
    if requested is not None and not requested.intersection(
        {color_property, softness_property}
    ):
        return False
    node_group = getattr(node, "node_tree", None)
    if node_group is None:
        return False
    ramp_node = None
    for candidate in tuple(getattr(node_group, "nodes", ()) or ()):
        try:
            if (
                getattr(candidate, "type", "") == "VALTORGB"
                and bool(candidate.get("fbp_effect_color_ramp", False))
                and str(candidate.get("fbp_effect_ramp_role", "") or "")
                == "GRADIENT_LIGHT"
            ):
                ramp_node = candidate
                break
        except FBP_DATA_ERRORS:
            continue
    color_ramp = getattr(ramp_node, "color_ramp", None)
    elements = sorted(
        tuple(getattr(color_ramp, "elements", ()) or ()),
        key=lambda item: float(getattr(item, "position", 0.0) or 0.0),
    )
    if len(elements) < 2:
        return False
    changed = False
    shadow, light = elements[0], elements[-1]
    if requested is None or color_property in requested:
        try:
            color = tuple(
                max(0.0, min(1.0, float(component)))
                for component in tuple(
                    getattr(rig, color_property, (0.0, 0.0, 0.05, 1.0))
                )[:4]
            )
            if len(color) == 4 and not _fbp_effect_values_equal(
                tuple(shadow.color), color
            ):
                shadow.color = color
                changed = True
        except FBP_DATA_ERRORS:
            pass
    if requested is None or softness_property in requested:
        try:
            softness = max(
                0.0,
                min(1.0, float(getattr(rig, softness_property, 0.5) or 0.0)),
            )
            half_width = max(0.0005, softness * 0.5)
            shadow_position = 0.5 - half_width
            light_position = 0.5 + half_width
            if not _fbp_effect_values_equal(shadow.position, shadow_position):
                shadow.position = shadow_position
                changed = True
            if not _fbp_effect_values_equal(light.position, light_position):
                light.position = light_position
                changed = True
        except FBP_DATA_ERRORS:
            pass
    return changed


def _fbp_set_shader_node_values(
    rig,
    effect_id,
    node,
    scene=None,
    *,
    property_names=None,
):
    """Update one shader effect node, optionally limiting writes to changed RNA properties."""
    definition = fbp_effect_definition(effect_id)
    requested = None if property_names is None else {
        str(name) for name in property_names if str(name or "")
    }
    full_update = requested is None
    changed = False

    # Image binding is structural state. It is synchronized on full updates and
    # by the frame-change hot path, not on every unrelated slider movement.
    if full_update and bool(definition.get("image_aware", False)):
        material = _fbp_material_for_shader_node(rig, node)
        has_image, source_changed = _fbp_sync_private_shader_source(
            material, getattr(node, "node_tree", None)
        )
        changed = source_changed or changed
        use_image = _fbp_node_socket(getattr(node, "inputs", ()), "Use Image Sample")
        if use_image is not None:
            value = 1.0 if has_image else 0.0
            if not _fbp_effect_values_equal(getattr(use_image, "default_value", None), value):
                try:
                    use_image.default_value = value
                    changed = True
                except FBP_DATA_ERRORS:
                    pass

    if full_update and bool(definition.get("uses_source_texel", False)):
        material = _fbp_material_for_shader_node(rig, node)
        changed = _fbp_sync_source_texel_inputs(rig, node, material=material) or changed

    mask_source_properties = {
        str(definition.get("mask_source_property", "") or ""),
        *(str(name or "") for name in definition.get("extra_properties", ()) or ()),
    }
    mask_source_properties.discard("")
    if bool(definition.get("mask_source_aware", False)) and (
        full_update or requested is None or bool(requested.intersection(mask_source_properties))
    ):
        _has_mask, mask_changed = _fbp_sync_mask_source(rig, effect_id, node)
        changed = mask_changed or changed

    if bool(definition.get("imported_mask_aware", False)):
        prefix = str(definition.get("imported_mask_prefix", "fbp_imported_mask") or "fbp_imported_mask")
        if full_update or requested is None or f"{prefix}_path" in requested:
            _has_imported_mask, imported_changed = _fbp_sync_imported_mask_image(rig, node, effect_id)
            changed = imported_changed or changed

    if effect_id == FBP_EFFECT_LAYER_BLEND and (
        full_update or requested is None or "fbp_layer_blend_mode" in requested
    ):
        changed = _fbp_sync_layer_blend_mode(rig, node) or changed

    if bool(definition.get("object_mask_aware", False)) and (
        full_update
        or requested is None
        or str(definition.get("object_mask_pointer_property", "") or "") in requested
    ):
        _has_object, object_changed = _fbp_sync_object_mask_helper(
            rig, effect_id, node, create=True
        )
        changed = object_changed or changed

    if effect_id == FBP_EFFECT_DEPTH_BLUR and (
        full_update or requested is None or requested & {
            "fbp_depth_blur_mode", "fbp_depth_blur_use_camera_focus",
            "fbp_depth_blur_focus_distance",
        }
    ):
        material = _fbp_material_for_shader_node(rig, node)
        changed = _fbp_sync_depth_blur_runtime_inputs(
            rig, node, material=material, scene=scene
        ) or changed

    if effect_id == FBP_EFFECT_GRADIENT_LIGHT:
        changed = _fbp_sync_gradient_light_ramp(
            rig, node, property_names=requested
        ) or changed

    for prop_name, socket_name in (definition.get("property_map", {}) or {}).items():
        if requested is not None and prop_name not in requested:
            continue
        input_socket = _fbp_node_socket(node.inputs, socket_name)
        if input_socket is None:
            continue
        try:
            instance_id = (
                effect_instance_id(node)
                if _fbp_effect_uses_multi_instances(effect_id) else ""
            )
            channel = (
                fbp_effect_instance_channel(
                    rig, effect_id, instance_id, prop_name, ensure=False
                )
                if instance_id else None
            )
            state = (
                fbp_read_effect_instance_animation_state(
                    rig, effect_id, instance_id
                )
                if instance_id else {}
            )
            speed_prop = str(definition.get("evolve_speed_property", "") or "")
            if channel is not None:
                value = fbp_effect_instance_channel_value(channel)
            elif instance_id and prop_name == speed_prop and state:
                value = state.get("speed", getattr(rig, prop_name))
            else:
                value = getattr(rig, prop_name)
            value = _fbp_effect_runtime_value(
                rig, effect_id, prop_name, value, scene=scene, node=node
            )
            value = _fbp_cast_effect_value(prop_name, value)
            value = tuple(value) if hasattr(value, "__len__") and not isinstance(value, str) else value
            if _fbp_effect_values_equal(getattr(input_socket, "default_value", None), value):
                continue
            input_socket.default_value = value
            changed = True
        except FBP_DATA_ERRORS:
            continue

    gates = _FBP_GATED_EFFECT_NODES.get(effect_id)
    if gates and (full_update or bool(requested & _fbp_gate_properties(definition, gates))):
        changed = _fbp_sync_gated_node_mutes(rig, node, gates) or changed

    if _fbp_definition_samples_property(definition) and (
        full_update or bool(requested & {_fbp_definition_samples_property(definition)})
    ):
        changed = _fbp_sync_sample_tap_mutes(rig, effect_id, node, definition) or changed

    debug_socket_name = str(definition.get("debug_socket", "") or "")
    if full_update and debug_socket_name:
        debug_socket = _fbp_node_socket(getattr(node, "inputs", ()), debug_socket_name)
        debug_value = _fbp_debug_mode_value(definition, fbp_effect_debug_mode(rig, effect_id))
        if debug_socket is not None and not _fbp_effect_values_equal(
            getattr(debug_socket, "default_value", None), debug_value
        ):
            try:
                debug_socket.default_value = debug_value
                changed = True
            except FBP_DATA_ERRORS:
                pass

    aspect_effects = {
        FBP_EFFECT_HALFTONE,
        FBP_EFFECT_DOT_MATRIX,
        FBP_EFFECT_ASCII_MATRIX,
        FBP_EFFECT_ASCII,
        FBP_EFFECT_NOISE_MASK,
        FBP_EFFECT_VORONOI_MASK,
        FBP_EFFECT_WAVE_MASK,
        FBP_EFFECT_GRADIENT_MASK,
    }
    # Aspect is derived from the current plane/UV contract rather than an RNA
    # property, so refresh it on every scoped update as well as full rebuilds.
    if effect_id in aspect_effects:
        aspect_socket = _fbp_node_socket(node.inputs, "Aspect Ratio")
        if aspect_socket is not None:
            aspect = 1.0
            aspect = _fbp_rig_plane_aspect(rig)
            if not _fbp_effect_values_equal(aspect_socket.default_value, aspect):
                try:
                    aspect_socket.default_value = aspect
                    changed = True
                except FBP_DATA_ERRORS:
                    pass

    if effect_id == FBP_EFFECT_PIXELATE:
        pixel_properties = {
            "fbp_pixelate_resolution",
            "fbp_pixelate_height",
            "fbp_pixelate_grid_mode",
            "fbp_pixelate_size",
            "fbp_pixelate_stretch",
        }
        if full_update or bool(requested & pixel_properties):
            pixels_x, pixels_y, _mode = _fbp_pixelate_grid(rig)
            for socket_name, value in (("Pixels X", float(pixels_x)), ("Pixels Y", float(pixels_y))):
                socket = _fbp_node_socket(node.inputs, socket_name)
                if socket is None or _fbp_effect_values_equal(socket.default_value, value):
                    continue
                try:
                    socket.default_value = value
                    changed = True
                except FBP_DATA_ERRORS:
                    pass

    if effect_id == FBP_EFFECT_ASCII_MATRIX:
        special_properties = {"fbp_ascii_charset", "fbp_ascii_character_count"}
        if full_update or bool(requested & special_properties):
            special_values = {
                "Charset Row": float(
                    ASCII_PRESET_ROWS.get(
                        str(getattr(rig, "fbp_ascii_charset", "CLASSIC")), 0
                    )
                ),
                "Character Count": float(
                    getattr(rig, "fbp_ascii_character_count", ASCII_ATLAS_COLUMNS)
                    or ASCII_ATLAS_COLUMNS
                ),
            }
            for socket_name, value in special_values.items():
                socket = _fbp_node_socket(node.inputs, socket_name)
                if socket is None or _fbp_effect_values_equal(socket.default_value, value):
                    continue
                try:
                    socket.default_value = value
                    changed = True
                except FBP_DATA_ERRORS:
                    pass
    return changed


def _fbp_rig_plane_aspect(rig):
    """Return physical canvas width/height, including cropped UV spans.

    Auto-cropped planes keep the original canvas pivot and a sub-rectangle of
    the source UV map. Measuring mesh bounds alone therefore turns circles into
    ellipses. Dividing each physical dimension by its active UV span restores
    the original pixel-space aspect while remaining correct for uncropped and
    extended meshes.
    """
    plane = _fbp_plane(rig)
    mesh = getattr(plane, "data", None) if plane else None
    try:
        vertices = iter(mesh.vertices)
        first = next(vertices)
        min_x = max_x = float(first.co.x)
        min_y = max_y = float(first.co.y)
        for vertex in vertices:
            x = float(vertex.co.x)
            y = float(vertex.co.y)
            min_x = min(min_x, x)
            max_x = max(max_x, x)
            min_y = min(min_y, y)
            max_y = max(max_y, y)
        width = max_x - min_x
        height = max_y - min_y
        if width <= 1e-8 or height <= 1e-8:
            return 1.0

        uv_span_x = uv_span_y = 1.0
        uv_layer = getattr(getattr(mesh, "uv_layers", None), "active", None)
        uv_data = getattr(uv_layer, "data", None)
        if uv_data:
            first_uv = uv_data[0].uv
            min_u = max_u = float(first_uv.x)
            min_v = max_v = float(first_uv.y)
            for loop_uv in uv_data[1:]:
                uv = loop_uv.uv
                u = float(uv.x)
                v = float(uv.y)
                min_u = min(min_u, u)
                max_u = max(max_u, u)
                min_v = min(min_v, v)
                max_v = max(max_v, v)
            uv_span_x = max(1e-8, max_u - min_u)
            uv_span_y = max(1e-8, max_v - min_v)

        physical_aspect = (width / uv_span_x) / (height / uv_span_y)
        return max(0.001, min(1000.0, float(physical_aspect)))
    except (AttributeError, IndexError, ReferenceError, RuntimeError, StopIteration, TypeError, ValueError):
        return 1.0

def _fbp_pixelate_grid(rig):
    """Return Pixelate's effective X by Y grid from one shared contract.

    Keeping this in one helper prevents the shader update, UI preview and
    Extrude dependency from drifting apart when Pixelate settings change.
    """
    try:
        mode = str(getattr(rig, "fbp_pixelate_grid_mode", "AUTO") or "AUTO")
        size = max(1.0, float(getattr(rig, "fbp_pixelate_size", 10.0) or 10.0))
        if mode == "EXACT":
            pixels_x = max(
                1, min(8192, int(getattr(rig, "fbp_pixelate_resolution", 64) or 64))
            )
            pixels_y = max(1, int(getattr(rig, "fbp_pixelate_height", 36) or 36))
        else:
            pixels_x = max(1, min(8192, int(round(640.0 / size))))
            aspect = max(0.001, float(_fbp_rig_plane_aspect(rig) or 1.0))
            stretch = max(0.05, float(getattr(rig, "fbp_pixelate_stretch", 1.0) or 1.0))
            pixels_y = max(1, int(round(float(pixels_x) / aspect / stretch)))
    except FBP_DATA_ERRORS:
        pixels_x, pixels_y, mode = 64, 36, "AUTO"
    return pixels_x, pixels_y, mode


_FBP_EXTRUDE_SAFE_SAMPLE_BUDGETS = {
    "PLAYBACK": 65_536,
    "VIEWPORT": 262_144,
    "RENDER": 1_048_576,
}


def _fbp_limit_extrude_grid(pixels_x, pixels_y, profile, enabled=True):
    """Return a proportional grid within the quality profile's safe budget."""
    pixels_x = max(1, min(4096, int(pixels_x or 1)))
    pixels_y = max(1, min(4096, int(pixels_y or 1)))
    if not enabled:
        return pixels_x, pixels_y, False
    budget = int(_FBP_EXTRUDE_SAFE_SAMPLE_BUDGETS.get(
        str(profile or "VIEWPORT").upper(),
        _FBP_EXTRUDE_SAFE_SAMPLE_BUDGETS["VIEWPORT"],
    ))
    samples = pixels_x * pixels_y
    if samples <= budget:
        return pixels_x, pixels_y, False
    scale = math.sqrt(float(budget) / float(samples))
    limited_x = max(1, min(pixels_x, int(math.floor(pixels_x * scale))))
    limited_y = max(1, min(pixels_y, int(math.floor(pixels_y * scale))))
    while limited_x * limited_y > budget:
        if limited_x >= limited_y and limited_x > 1:
            limited_x -= 1
        elif limited_y > 1:
            limited_y -= 1
        else:
            break
    return limited_x, limited_y, True


def _fbp_extrude_follows_pixelate(rig, profile="VIEWPORT"):
    """Return True when Extrude should mirror a visible Pixelate grid."""
    try:
        if not bool(getattr(rig, "fbp_thickness_follow_pixelate", True)):
            return False
        if FBP_EFFECT_PIXELATE not in _fbp_runtime_effect_ids(rig):
            return False
        if str(profile or "VIEWPORT").upper() == "RENDER":
            return _fbp_stored_effect_render_visibility(
                rig, FBP_EFFECT_PIXELATE, True
            )
        return _fbp_stored_effect_visibility(rig, FBP_EFFECT_PIXELATE, True)
    except FBP_DATA_ERRORS:
        return False


def _fbp_extrude_grid(rig, profile="VIEWPORT"):
    """Resolve Extrude's effective grid for viewport, playback or render.

    The requested grid remains stored on the rig, while Safe Grid Limits can
    proportionally reduce only the evaluated grid. This keeps files editable
    and prevents accidental multi-million-cell meshes during playback.
    """
    profile = str(profile or "VIEWPORT").upper()
    try:
        safe_grid = bool(getattr(rig, "fbp_thickness_safe_grid", True))
    except FBP_DATA_ERRORS:
        safe_grid = True

    if _fbp_extrude_follows_pixelate(rig, profile):
        pixels_x, pixels_y, _mode = _fbp_pixelate_grid(rig)
        pixels_x, pixels_y, limited = _fbp_limit_extrude_grid(
            pixels_x, pixels_y, profile, safe_grid
        )
        return pixels_x, pixels_y, "PIXELATE_LIMITED" if limited else "PIXELATE"

    properties = {
        "VIEWPORT": ("fbp_thickness_viewport_pixels_x", "fbp_thickness_viewport_pixels_y"),
        "PLAYBACK": ("fbp_thickness_playback_pixels_x", "fbp_thickness_playback_pixels_y"),
        "RENDER": ("fbp_thickness_render_pixels_x", "fbp_thickness_render_pixels_y"),
    }
    prop_x, prop_y = properties.get(profile, properties["VIEWPORT"])
    try:
        pixels_x = max(1, min(4096, int(getattr(rig, prop_x, 128) or 128)))
        mode = str(getattr(rig, "fbp_thickness_grid_mode", "AUTO") or "AUTO")
        if mode == "EXACT":
            pixels_y = max(1, min(4096, int(getattr(rig, prop_y, pixels_x) or pixels_x)))
        else:
            aspect = max(0.001, float(_fbp_rig_plane_aspect(rig) or 1.0))
            pixels_y = max(1, min(4096, int(round(float(pixels_x) / aspect))))
    except FBP_DATA_ERRORS:
        pixels_x, pixels_y, mode = 128, 128, "AUTO"
    pixels_x, pixels_y, limited = _fbp_limit_extrude_grid(
        pixels_x, pixels_y, profile, safe_grid
    )
    return pixels_x, pixels_y, f"{mode}_LIMITED" if limited else mode


def _fbp_refresh_extrude_pixel_dependency(
    rig, *, force=False, modifier=None, scene=None
):
    """Refresh only Extrude's two grid sockets after Pixelate changes."""
    if not rig:
        return False
    try:
        follows_setting = bool(
            getattr(rig, "fbp_thickness_follow_pixelate", True)
        )
    except FBP_DATA_ERRORS:
        follows_setting = False
    if not follows_setting:
        return False
    if not force and not _fbp_extrude_follows_pixelate(rig):
        return False
    if FBP_EFFECT_THICKNESS not in _fbp_runtime_effect_ids(rig):
        return False
    return bool(
        fbp_update_geometry_effect(
            rig,
            FBP_EFFECT_THICKNESS,
            modifier=modifier,
            scene=scene,
            sync_alpha=False,
            property_names={
                "fbp_thickness_viewport_pixels_x",
                "fbp_thickness_viewport_pixels_y",
            },
        )
    )


def fbp_refresh_plane_uv_geometry_sampling(rig):
    """Refresh image-aware Geometry Nodes after plane Crop / Extend changes.

    The mesh carries the transformed UVMap, while the material image node owns
    the Edge / Repeat / Mirror / Transparent sampling mode. Re-syncing with an
    empty property set updates only the image contract without rewriting
    unrelated effect controls.
    """
    if rig is None:
        return False
    changed = False
    for effect_id in _fbp_runtime_effect_ids(rig):
        definition = fbp_effect_definition(effect_id)
        if (
            definition.get("kind") != "GEOMETRY"
            or not bool(definition.get("image_aware", False))
        ):
            continue
        try:
            changed = bool(
                fbp_update_geometry_effect(
                    rig, effect_id, property_names=set(), sync_alpha=True
                )
            ) or changed
        except FBP_DATA_ERRORS:
            continue
    return changed


def fbp_refresh_aspect_dependent_effect_grids(rig):
    """Refresh Auto Height grids after Crop/Extend changes plane aspect.

    Pixelate and Extrude derive their vertical sample count from the local plane
    bounds. Updating only the UI after a mesh-bound change can leave the actual
    shader or Geometry Nodes sockets on the previous aspect ratio.
    """
    if rig is None:
        return False
    active_ids = _fbp_runtime_effect_ids(rig)
    changed = False
    if (
        FBP_EFFECT_PIXELATE in active_ids
        and str(getattr(rig, "fbp_pixelate_grid_mode", "AUTO") or "AUTO") == "AUTO"
    ):
        changed = bool(
            fbp_update_shader_effect(
                rig,
                FBP_EFFECT_PIXELATE,
                property_names={
                    "fbp_pixelate_resolution",
                    "fbp_pixelate_height",
                },
            )
        ) or changed
    for generated_mask_id in (
        FBP_EFFECT_NOISE_MASK,
        FBP_EFFECT_VORONOI_MASK,
        FBP_EFFECT_WAVE_MASK,
        FBP_EFFECT_GRADIENT_MASK,
    ):
        if generated_mask_id in active_ids:
            # No RNA property changed: an empty property set updates only the
            # derived Aspect Ratio socket through _fbp_set_shader_node_values.
            changed = bool(
                fbp_update_shader_effect(
                    rig, generated_mask_id, property_names=set()
                )
            ) or changed
    if FBP_EFFECT_THICKNESS in active_ids:
        follows_pixelate = _fbp_extrude_follows_pixelate(rig, "VIEWPORT")
        own_auto = (
            not follows_pixelate
            and str(getattr(rig, "fbp_thickness_grid_mode", "AUTO") or "AUTO")
            == "AUTO"
        )
        if follows_pixelate or own_auto:
            changed = bool(
                fbp_update_geometry_effect(
                    rig,
                    FBP_EFFECT_THICKNESS,
                    sync_alpha=False,
                    property_names={
                        "fbp_thickness_viewport_pixels_x",
                        "fbp_thickness_viewport_pixels_y",
                    },
                )
            ) or changed
    changed = fbp_refresh_plane_uv_geometry_sampling(rig) or changed
    return changed


def _fbp_material_for_shader_node(rig, node):
    node_tree = getattr(node, "id_data", None) if node else None
    for material in _fbp_plane_materials(rig):
        if getattr(material, "node_tree", None) is node_tree:
            return material
    return None


def _fbp_matrix_source_image_nodes(node_group):
    """Return live private image nodes, caching only stable node names.

    Caching RNA node wrappers across a group rebuild is unsafe in Blender 5.2:
    the Python object may survive after its C node is deleted. Re-resolving the
    cached names preserves most of the lookup benefit without stale pointers.
    """
    if not node_group:
        return ()
    try:
        cache_key = _fbp_node_group_cache_key(node_group)
        if cache_key is None:
            return ()
        signature = (len(node_group.nodes),)
        cached = _FBP_MATRIX_IMAGE_NODE_CACHE.get(cache_key)
        if cached and cached[0] == signature:
            live = tuple(
                node for name in cached[1]
                for node in (node_group.nodes.get(name),)
                if node is not None and bool(node.get("fbp_matrix_source_image_node", False))
            )
            if len(live) == len(cached[1]):
                return live
        names = tuple(
            str(node.name)
            for node in node_group.nodes
            if bool(node.get("fbp_matrix_source_image_node", False))
        )
        if len(_FBP_MATRIX_IMAGE_NODE_CACHE) >= 512 and cache_key not in _FBP_MATRIX_IMAGE_NODE_CACHE:
            _FBP_MATRIX_IMAGE_NODE_CACHE.clear()
        _FBP_MATRIX_IMAGE_NODE_CACHE[cache_key] = (signature, names)
        return tuple(
            node for name in names
            for node in (node_group.nodes.get(name),)
            if node is not None
        )
    except FBP_DATA_ERRORS:
        return ()


def _fbp_copy_shader_image_user(source_node, target_node):
    """Copy sequence timing without retaining or dereferencing stale RNA nodes.

    Blender 5.2 can leave a Python wrapper alive for a node that was removed while
    an effect group was rebuilt. Reading ``ImageUser`` through that wrapper may
    crash in C before Python can raise ``ReferenceError``. Only freshly resolved
    nodes reach this helper, and still images skip ImageUser access entirely.
    """
    if source_node is None or target_node is None:
        return False
    try:
        source_image = getattr(source_node, "image", None)
        source_kind = str(getattr(source_image, "source", "") or "").upper()
    except FBP_DATA_ERRORS:
        return False
    if source_kind not in {"SEQUENCE", "MOVIE"}:
        return False
    try:
        source_user = getattr(source_node, "image_user", None)
        target_user = getattr(target_node, "image_user", None)
        if source_user is None or target_user is None:
            return False
        snapshot = tuple(
            getattr(source_user, attr)
            for attr in (
                "frame_duration", "frame_start", "frame_offset",
                "use_cyclic", "use_auto_refresh",
            )
        )
    except FBP_DATA_ERRORS:
        return False
    changed = False
    for attr, value in zip(
        ("frame_duration", "frame_start", "frame_offset", "use_cyclic", "use_auto_refresh"),
        snapshot,
        strict=True,
    ):
        try:
            if getattr(target_user, attr) != value:
                setattr(target_user, attr, value)
                changed = True
        except FBP_DATA_ERRORS:
            continue
    return changed


_FBP_PRIVATE_OFFSET_ANIM_KEY = "fbp_private_offset_anim_signature"


def _fbp_frame_offset_curve(source_node):
    """Return the F-Curve that animates the native source ImageUser offset."""
    try:
        tree = getattr(source_node, "id_data", None)
        user = getattr(source_node, "image_user", None)
        if tree is None or user is None:
            return None
        return fbp_find_action_fcurve(tree, user.path_from_id("frame_offset"))
    except FBP_DATA_ERRORS:
        return None


def _fbp_frame_offset_curve_signature(curve):
    """Cheap identity of a timing curve: key count plus packed key data."""
    if curve is None:
        return ""
    try:
        points = curve.keyframe_points
        count = len(points)
        coords = array("f", [0.0]) * (2 * count)
        if count:
            points.foreach_get("co", coords)
        modes = array("i", [0]) * count
        if count:
            points.foreach_get("interpolation", modes)
        return "%d:%x:%x" % (count, hash(coords.tobytes()), hash(modes.tobytes()))
    except FBP_DATA_ERRORS:
        return None


def _fbp_private_offset_paths(image_nodes):
    paths = []
    for image_node in image_nodes:
        try:
            paths.append(image_node.image_user.path_from_id("frame_offset"))
        except FBP_DATA_ERRORS:
            continue
    return paths


def _fbp_clear_private_offset_animation(node_group, image_nodes):
    removed = 0
    for path in _fbp_private_offset_paths(image_nodes):
        removed += fbp_remove_action_fcurves(node_group, path)
    try:
        if _FBP_PRIVATE_OFFSET_ANIM_KEY in node_group:
            del node_group[_FBP_PRIVATE_OFFSET_ANIM_KEY]
    except FBP_DATA_ERRORS:
        pass
    return bool(removed)


def _fbp_mirror_private_offset_animation(source_node, source_curve, signature, node_group, image_nodes):
    """Give every private image sample the source timing curve.

    Blender then evaluates the sequence frame of each blur/edge sample
    natively during playback. Copying ``ImageUser.frame_offset`` from Python
    on every frame cost about a millisecond per sample and re-tagged the
    shader, which was the main source of playback lag for image effects.
    """
    try:
        animation_data = node_group.animation_data
        action = getattr(animation_data, "action", None) if animation_data else None
        if action is not None and int(getattr(action, "users", 1) or 1) > 1:
            # Copied stacks share the Action of the group they came from;
            # each layer needs its own timing.
            slot = getattr(animation_data, "action_slot", None)
            slot_identifier = str(getattr(slot, "identifier", "") or "")
            animation_data.action = action.copy()
            if getattr(animation_data, "action_slot", None) is None and slot_identifier:
                for candidate in animation_data.action.slots:
                    if candidate.identifier == slot_identifier:
                        animation_data.action_slot = candidate
                        break
        source_points = source_curve.keyframe_points
        count = len(source_points)
        if not count:
            return False
        # Bulk-copy the keys: long holds produce hundreds of them, and one
        # keyframe_insert plus an RNA write per key and per sample took seconds.
        coords = array("f", [0.0]) * (2 * count)
        left = array("f", [0.0]) * (2 * count)
        right = array("f", [0.0]) * (2 * count)
        modes = array("i", [0]) * count
        source_points.foreach_get("co", coords)
        source_points.foreach_get("handle_left", left)
        source_points.foreach_get("handle_right", right)
        source_points.foreach_get("interpolation", modes)
        current = int(getattr(source_node.image_user, "frame_offset", 0) or 0)
        for image_node in image_nodes:
            user = getattr(image_node, "image_user", None)
            if user is None:
                continue
            path = user.path_from_id("frame_offset")
            fbp_remove_action_fcurves(node_group, path)
            # One real insert creates the F-Curve in the group's action slot.
            user.frame_offset = int(round(float(coords[1])))
            node_group.keyframe_insert(data_path=path, frame=float(coords[0]))
            curve = fbp_find_action_fcurve(node_group, path)
            if curve is None:
                continue
            points = curve.keyframe_points
            if count > len(points):
                points.add(count - len(points))
            points.foreach_set("co", coords)
            points.foreach_set("handle_left", left)
            points.foreach_set("handle_right", right)
            points.foreach_set("interpolation", modes)
            try:
                curve.update()
            except FBP_DATA_ERRORS:
                pass
            user.frame_offset = current
        node_group[_FBP_PRIVATE_OFFSET_ANIM_KEY] = str(signature)
        return True
    except FBP_DATA_ERRORS as exc:
        fbp_warn("Could not give image samples the sequence timing", exc)
        return False


def _fbp_sync_private_offset_animation(source_node, node_group, image_nodes):
    """Return ``(animated, changed)`` after matching the private timing curves."""
    if source_node is None or node_group is None:
        return False, False
    try:
        source_kind = str(getattr(getattr(source_node, "image", None), "source", "") or "").upper()
    except FBP_DATA_ERRORS:
        source_kind = ""
    curve = _fbp_frame_offset_curve(source_node) if source_kind in {"SEQUENCE", "MOVIE"} else None
    signature = _fbp_frame_offset_curve_signature(curve) if curve is not None else ""
    try:
        stored = str(node_group.get(_FBP_PRIVATE_OFFSET_ANIM_KEY, "") or "")
    except FBP_DATA_ERRORS:
        stored = ""
    if not signature:
        if stored:
            return False, _fbp_clear_private_offset_animation(node_group, image_nodes)
        return False, False
    if stored == signature:
        return True, False
    return _fbp_mirror_private_offset_animation(
        source_node, curve, signature, node_group, image_nodes
    ), True


def _fbp_private_source_quick_signature(source_node, image_key, image_user, node_group):
    """Identity of everything a private sample copies, without its nodes.

    None when the timing curve and the samples' stored copy of it differ, so
    the caller runs the full validation that mirrors the new curve.
    """
    try:
        source_kind = str(getattr(getattr(source_node, "image", None), "source", "") or "").upper()
        curve = _fbp_frame_offset_curve(source_node) if source_kind in {"SEQUENCE", "MOVIE"} else None
        curve_signature = _fbp_frame_offset_curve_signature(curve) if curve is not None else ""
        if curve_signature is None:
            return None
        stored = str(node_group.get(_FBP_PRIVATE_OFFSET_ANIM_KEY, "") or "")
        if stored != curve_signature:
            return None
        user = tuple(
            "ANIMATED" if attr == "frame_offset" and curve_signature else getattr(image_user, attr, None)
            for attr in ("frame_duration", "frame_start", "frame_offset", "use_cyclic", "use_auto_refresh")
        )
        return (
            image_key,
            curve_signature,
            str(getattr(source_node, "projection", "FLAT") or "FLAT"),
            float(getattr(source_node, "projection_blend", 0.0) or 0.0),
            user,
            len(node_group.nodes),
        )
    except FBP_DATA_ERRORS:
        return None


def _fbp_sync_private_shader_source(material, node_group):
    """Synchronize private image samples with a bounded validation cache.

    A sequence image datablock advances internally; copying the same ImageUser
    values into every blur sample on every frame is unnecessary.  Revalidate
    periodically so external node edits still self-heal without imposing nine
    image-node comparisons per frame and per layer.
    """
    if not node_group:
        return False, False
    source_node = _fbp_shader_image_node(material)
    source_image = getattr(source_node, "image", None) if source_node else None
    try:
        group_key = _fbp_node_group_cache_key(node_group)
    except FBP_DATA_ERRORS:
        group_key = None
    try:
        image_key = fbp_obj_runtime_key(source_image) if source_image else None
    except FBP_DATA_ERRORS:
        image_key = None
    image_user = getattr(source_node, "image_user", None) if source_node else None
    now = time.monotonic()
    # Fast path for playback: with native sample timing nothing changes from
    # frame to frame, and resolving every private sample node by name (about
    # 25 lookups per blur) was most of this handler's cost. The quick
    # signature reads only the source node, the timing curve and the group's
    # node count; a full validation still runs at least every 2 seconds.
    cached = _FBP_PRIVATE_IMAGE_SOURCE_SYNC_CACHE.get(group_key) if group_key is not None else None
    if cached and len(cached) > 2 and now - float(cached[1]) < 2.0:
        quick = _fbp_private_source_quick_signature(
            source_node, image_key, image_user, node_group
        )
        if quick is not None and quick == cached[2]:
            return bool(source_image), False
    image_nodes = _fbp_matrix_source_image_nodes(node_group)
    if not image_nodes:
        return False, False
    # Sequence timing normally lives in an F-Curve on frame_offset. The private
    # samples get the same curve, so the per-frame offset leaves the signature
    # and playback no longer rewrites every sample through Python.
    offset_animated, offset_changed = _fbp_sync_private_offset_animation(
        source_node, node_group, image_nodes
    )
    user_signature = []
    for attr in ("frame_duration", "frame_start", "frame_offset", "use_cyclic", "use_auto_refresh"):
        if attr == "frame_offset" and offset_animated:
            user_signature.append("ANIMATED")
            continue
        try:
            user_signature.append(getattr(image_user, attr))
        except FBP_DATA_ERRORS:
            user_signature.append(None)
    try:
        source_signature = (
            image_key,
            str(getattr(source_node, "projection", "FLAT") or "FLAT"),
            float(getattr(source_node, "projection_blend", 0.0) or 0.0),
            tuple(user_signature),
            len(image_nodes),
        )
    except FBP_DATA_ERRORS:
        source_signature = (image_key, tuple(user_signature), len(image_nodes))
    if (
        not offset_changed
        and cached and cached[0] == source_signature and now - float(cached[1]) < 2.0
    ):
        return bool(source_image), False

    changed = offset_changed
    for image_node in image_nodes:
        try:
            if getattr(image_node, "image", None) is not source_image:
                image_node.image = source_image
                changed = True
            if source_node is not None:
                for attr in ("projection", "projection_blend"):
                    try:
                        value = getattr(source_node, attr)
                        if getattr(image_node, attr) != value:
                            setattr(image_node, attr, value)
                            changed = True
                    except FBP_DATA_ERRORS:
                        continue
                try:
                    desired_interpolation = str(
                        image_node.get("fbp_source_interpolation", "Closest") or "Closest"
                    )
                    desired_extension = str(
                        image_node.get("fbp_source_extension", "EXTEND") or "EXTEND"
                    ).upper()
                    if desired_extension not in {"REPEAT", "EXTEND", "CLIP", "MIRROR"}:
                        desired_extension = "EXTEND"
                    if image_node.interpolation != desired_interpolation:
                        image_node.interpolation = desired_interpolation
                        changed = True
                    if image_node.extension != desired_extension:
                        image_node.extension = desired_extension
                        changed = True
                except FBP_DATA_ERRORS:
                    pass
                changed = _fbp_copy_shader_image_user(source_node, image_node) or changed
        except FBP_DATA_ERRORS:
            continue
    if group_key is not None:
        if len(_FBP_PRIVATE_IMAGE_SOURCE_SYNC_CACHE) >= 512 and group_key not in _FBP_PRIVATE_IMAGE_SOURCE_SYNC_CACHE:
            _FBP_PRIVATE_IMAGE_SOURCE_SYNC_CACHE.clear()
        _FBP_PRIVATE_IMAGE_SOURCE_SYNC_CACHE[group_key] = (
            source_signature,
            now,
            _fbp_private_source_quick_signature(source_node, image_key, image_user, node_group),
        )
    if changed:
        try:
            node_group.update_tag()
        except FBP_DATA_ERRORS:
            pass
    return bool(source_image), changed


def _fbp_mask_source_image_nodes(node_group):
    """Resolve live mask image nodes on demand.

    Do not cache ``ShaderNodeTexImage`` Python objects here. A private Clipping
    Mask group may be replaced with the same node count, making a length-based
    cache return wrappers for deleted nodes and causing an access violation.
    """
    if not node_group:
        return ()
    try:
        return tuple(
            node for node in node_group.nodes
            if bool(node.get("fbp_mask_source_image_node", False))
        )
    except FBP_DATA_ERRORS:
        return ()


def _fbp_mask_source_coord_nodes(node_group):
    """Return Texture Coordinate nodes bound to a track-matte source plane."""
    if not node_group:
        return ()
    try:
        return tuple(
            node for node in node_group.nodes
            if bool(node.get("fbp_mask_source_coord_node", False))
        )
    except FBP_DATA_ERRORS:
        return ()


def _fbp_mask_camera_coord_nodes(node_group):
    """Return live Texture Coordinate nodes bound to the active camera object."""
    if not node_group:
        return ()
    try:
        return tuple(
            node for node in node_group.nodes
            if bool(node.get("fbp_mask_camera_coord_node", False))
        )
    except FBP_DATA_ERRORS:
        return ()


def _fbp_source_plane_bounds(source_rig):
    """Return source plane, cropped local bounds and matching source-image UV."""
    try:
        plane = getattr(source_rig, "fbp_plane_target", None) if source_rig else None
        if not plane:
            return None, (-1.0, 1.0, -1.0, 1.0), (0.0, 1.0, 0.0, 1.0)

        points = []
        try:
            from .builder import fbp_plane_reference_bounds
            _source_bounds, cropped_bounds, _extended_bounds, uv_bounds = (
                fbp_plane_reference_bounds(source_rig)
            )
            min_x, max_x, min_y, max_y = tuple(float(v) for v in cropped_bounds)
            uv_min_x, uv_max_x, uv_min_y, uv_max_y = tuple(float(v) for v in uv_bounds)
            if abs(max_x - min_x) >= 1.0e-8 and abs(max_y - min_y) >= 1.0e-8:
                return (
                    plane,
                    (min_x, max_x, min_y, max_y),
                    (uv_min_x, uv_max_x, uv_min_y, uv_max_y),
                )
        except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
            pass

        try:
            points.extend(
                (float(point[0]), float(point[1]))
                for point in tuple(getattr(plane, "bound_box", ()) or ())
                if len(point) >= 2
            )
        except (AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
            points = []
        if not points:
            mesh = getattr(plane, "data", None)
            vertices = tuple(getattr(mesh, "vertices", ()) or ()) if mesh else ()
            points = [(float(vertex.co.x), float(vertex.co.y)) for vertex in vertices]
        if not points:
            return plane, (-1.0, 1.0, -1.0, 1.0), (0.0, 1.0, 0.0, 1.0)
        xs = [point[0] for point in points]
        ys = [point[1] for point in points]
        min_x, max_x = min(xs), max(xs)
        min_y, max_y = min(ys), max(ys)
        if abs(max_x - min_x) < 1.0e-8:
            min_x, max_x = -1.0, 1.0
        if abs(max_y - min_y) < 1.0e-8:
            min_y, max_y = -1.0, 1.0
        return plane, (min_x, max_x, min_y, max_y), (0.0, 1.0, 0.0, 1.0)
    except FBP_DATA_ERRORS:
        return None, (-1.0, 1.0, -1.0, 1.0), (0.0, 1.0, 0.0, 1.0)


def _fbp_clipping_camera_matrix(scene, source_plane):
    """Return camera-local -> source-plane-local affine coefficients.

    The shader intersects each camera ray with the actual source plane.  Passing
    the real transform avoids fitting errors and remains exact with parented or
    non-uniformly scaled planes. Evaluated matrices are copied immediately so no
    temporary RNA wrapper survives the synchronization call.
    """
    camera = getattr(scene, "camera", None) if scene else None
    if camera is None or source_plane is None:
        return None
    try:
        camera_matrix = camera.matrix_world.copy()
        source_matrix = source_plane.matrix_world.copy()
        try:
            depsgraph = bpy.context.evaluated_depsgraph_get()
            camera_matrix = camera.evaluated_get(depsgraph).matrix_world.copy()
            source_matrix = source_plane.evaluated_get(depsgraph).matrix_world.copy()
        except (AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
            pass
        camera_to_source = source_matrix.inverted_safe() @ camera_matrix
        coefficients = tuple(
            float(camera_to_source[row][column])
            for row in range(3)
            for column in range(4)
        )
        if not all(math.isfinite(value) for value in coefficients):
            return None
        try:
            camera_type = str(getattr(getattr(camera, "data", None), "type", "PERSP") or "PERSP").upper()
        except FBP_DATA_ERRORS:
            camera_type = "PERSP"
        # Orthographic rays are parallel to camera -Z. If that direction lies
        # in the source plane, there is no unique intersection and the shader
        # should fall back to the ordinary source-transform mode.
        if camera_type == "ORTHO" and abs(coefficients[10]) < 1.0e-8:
            return None
        return coefficients
    except (AttributeError, ReferenceError, RuntimeError, TypeError, ValueError, ZeroDivisionError):
        return None



_FBP_CLIPPING_DRIVER_FUNCTION = "fbp_clipping_matrix_component_v1"
_FBP_CLIPPING_DRIVER_MARKER = "fbp_clip_matrix_driver"
_FBP_CLIPPING_DRIVER_SIGNATURE_KEY = "fbp_clipping_matrix_driver_signature"


def fbp_clipping_matrix_component_v1(
    row, column,
    cx, cy, cz, crx, cry, crz, csx, csy, csz,
    sx, sy, sz, srx, sry, srz, ssx, ssy, ssz,
):
    """Pure driver function for camera-local -> source-plane-local matrices.

    Only numeric transform variables are consumed. No RNA or datablock access is
    performed while Blender evaluates the driver, so camera animation cannot
    race Eevee material synchronization.
    """
    try:
        camera_matrix = Matrix.LocRotScale(
            Vector((float(cx), float(cy), float(cz))),
            Euler((float(crx), float(cry), float(crz)), "XYZ").to_quaternion(),
            Vector((
                float(csx) if abs(float(csx)) > 1.0e-12 else 1.0e-12,
                float(csy) if abs(float(csy)) > 1.0e-12 else 1.0e-12,
                float(csz) if abs(float(csz)) > 1.0e-12 else 1.0e-12,
            )),
        )
        source_matrix = Matrix.LocRotScale(
            Vector((float(sx), float(sy), float(sz))),
            Euler((float(srx), float(sry), float(srz)), "XYZ").to_quaternion(),
            Vector((
                float(ssx) if abs(float(ssx)) > 1.0e-12 else 1.0e-12,
                float(ssy) if abs(float(ssy)) > 1.0e-12 else 1.0e-12,
                float(ssz) if abs(float(ssz)) > 1.0e-12 else 1.0e-12,
            )),
        )
        matrix = source_matrix.inverted_safe() @ camera_matrix
        value = float(matrix[int(row)][int(column)])
        return value if math.isfinite(value) else 0.0
    except (IndexError, TypeError, ValueError, OverflowError):
        return 0.0


def register_clipping_matrix_driver_namespace():
    try:
        bpy.app.driver_namespace[_FBP_CLIPPING_DRIVER_FUNCTION] = (
            fbp_clipping_matrix_component_v1
        )
        return True
    except (AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
        return False


def unregister_clipping_matrix_driver_namespace():
    try:
        current = bpy.app.driver_namespace.get(_FBP_CLIPPING_DRIVER_FUNCTION)
        if current is fbp_clipping_matrix_component_v1:
            bpy.app.driver_namespace.pop(_FBP_CLIPPING_DRIVER_FUNCTION, None)
        return True
    except (AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
        return False


def _fbp_clipping_driver_curve(node_tree, data_path):
    try:
        return next(
            (
                curve for curve in tuple(
                    getattr(getattr(node_tree, "animation_data", None), "drivers", ()) or ()
                )
                if str(getattr(curve, "data_path", "") or "") == str(data_path)
            ),
            None,
        )
    except FBP_DATA_ERRORS:
        return None


def _fbp_clipping_driver_owned(curve):
    try:
        driver = getattr(curve, "driver", None)
        if driver is None:
            return False
        if str(getattr(driver, "expression", "") or "").startswith(
            f"{_FBP_CLIPPING_DRIVER_FUNCTION}("
        ):
            return True
        return any(
            str(getattr(variable, "name", "") or "").startswith(
                _FBP_CLIPPING_DRIVER_MARKER
            )
            for variable in tuple(getattr(driver, "variables", ()) or ())
        )
    except FBP_DATA_ERRORS:
        return False


def _fbp_remove_clipping_matrix_drivers(node):
    node_tree = getattr(node, "id_data", None) if node else None
    if node_tree is None:
        return False
    changed = False
    for row in range(3):
        for column in range(4):
            socket = _fbp_node_socket(
                getattr(node, "inputs", ()), f"Camera To Source M{row}{column}"
            )
            if socket is None:
                continue
            try:
                data_path = socket.path_from_id("default_value")
            except FBP_DATA_ERRORS:
                continue
            curve = _fbp_clipping_driver_curve(node_tree, data_path)
            if curve is None or not _fbp_clipping_driver_owned(curve):
                continue
            try:
                node_tree.driver_remove(data_path)
                changed = True
            except FBP_DATA_ERRORS:
                pass
    try:
        if _FBP_CLIPPING_DRIVER_SIGNATURE_KEY in node:
            del node[_FBP_CLIPPING_DRIVER_SIGNATURE_KEY]
            changed = True
    except FBP_DATA_ERRORS:
        pass
    return changed


def _fbp_clipping_matrix_driver_signature(camera, source_plane):
    def _identity(obj):
        try:
            return f"{getattr(obj, 'name_full', obj.name)}:{int(obj.as_pointer())}"
        except FBP_DATA_ERRORS:
            return ""
    return f"v1|{_identity(camera)}|{_identity(source_plane)}"


def fbp_bind_clipping_camera_matrix_drivers(node, camera, source_plane):
    """Bind Clipping Mask camera coefficients to depsgraph-native drivers."""
    if node is None or camera is None or source_plane is None:
        return False
    node_tree = getattr(node, "id_data", None)
    if node_tree is None or not register_clipping_matrix_driver_namespace():
        return False
    signature = _fbp_clipping_matrix_driver_signature(camera, source_plane)
    try:
        current_signature = str(
            node.get(_FBP_CLIPPING_DRIVER_SIGNATURE_KEY, "") or ""
        )
    except FBP_DATA_ERRORS:
        current_signature = ""
    paths = []
    complete = True
    for row in range(3):
        for column in range(4):
            socket = _fbp_node_socket(
                getattr(node, "inputs", ()), f"Camera To Source M{row}{column}"
            )
            if socket is None:
                complete = False
                continue
            try:
                data_path = socket.path_from_id("default_value")
            except FBP_DATA_ERRORS:
                complete = False
                continue
            paths.append((row, column, data_path))
            curve = _fbp_clipping_driver_curve(node_tree, data_path)
            if curve is None or not _fbp_clipping_driver_owned(curve):
                complete = False
    if current_signature == signature and complete and len(paths) == 12:
        return True

    # These sockets are private FBP implementation inputs. Replace only drivers
    # previously owned by FBP; an unexpected user driver aborts the repair.
    for _row, _column, data_path in paths:
        curve = _fbp_clipping_driver_curve(node_tree, data_path)
        if curve is not None and not _fbp_clipping_driver_owned(curve):
            return False
    _fbp_remove_clipping_matrix_drivers(node)

    specs = (
        ("cx", camera, "LOC_X"), ("cy", camera, "LOC_Y"), ("cz", camera, "LOC_Z"),
        ("crx", camera, "ROT_X"), ("cry", camera, "ROT_Y"), ("crz", camera, "ROT_Z"),
        ("csx", camera, "SCALE_X"), ("csy", camera, "SCALE_Y"), ("csz", camera, "SCALE_Z"),
        ("sx", source_plane, "LOC_X"), ("sy", source_plane, "LOC_Y"), ("sz", source_plane, "LOC_Z"),
        ("srx", source_plane, "ROT_X"), ("sry", source_plane, "ROT_Y"), ("srz", source_plane, "ROT_Z"),
        ("ssx", source_plane, "SCALE_X"), ("ssy", source_plane, "SCALE_Y"), ("ssz", source_plane, "SCALE_Z"),
    )
    created_paths = []
    try:
        for row, column, data_path in paths:
            curve = node_tree.driver_add(data_path)
            created_paths.append(data_path)
            driver = curve.driver
            driver.type = "SCRIPTED"
            while driver.variables:
                driver.variables.remove(driver.variables[0])
            for index, spec in enumerate(specs):
                name = spec[0]
                variable = _fbp_add_clipping_transform_variable(
                    driver, name, spec[1], spec[2]
                )
                if index == 0:
                    variable.name = f"{_FBP_CLIPPING_DRIVER_MARKER}_{name}"
            # Keep the marker variable usable in the expression under its
            # actual name and pass the remaining variables normally.
            expression_names = [f"{_FBP_CLIPPING_DRIVER_MARKER}_cx"] + [
                spec[0] for spec in specs[1:]
            ]
            driver.expression = (
                f"{_FBP_CLIPPING_DRIVER_FUNCTION}({row},{column},"
                + ",".join(expression_names)
                + ")"
            )
        node[_FBP_CLIPPING_DRIVER_SIGNATURE_KEY] = signature
        node_tree.update_tag()
        return True
    except FBP_DATA_ERRORS as exc:
        for data_path in created_paths:
            try:
                node_tree.driver_remove(data_path)
            except FBP_DATA_ERRORS:
                pass
        try:
            node.pop(_FBP_CLIPPING_DRIVER_SIGNATURE_KEY, None)
        except FBP_DATA_ERRORS:
            pass
        fbp_warn("Could not create native Clipping Mask camera drivers", exc)
        return False


def _fbp_camera_projection_signature(scene, source_plane, coefficients):
    camera = getattr(scene, "camera", None) if scene else None
    if camera is None or coefficients is None:
        return (None,)
    try:
        camera_data = getattr(camera, "data", None)
        return (
            fbp_obj_runtime_key(camera),
            tuple(round(float(value), 8) for row in camera.matrix_world for value in row),
            str(getattr(camera_data, "type", "") or ""),
            round(float(getattr(camera_data, "lens", 0.0)), 6),
            round(float(getattr(camera_data, "ortho_scale", 0.0)), 6),
            round(float(getattr(camera_data, "shift_x", 0.0)), 6),
            round(float(getattr(camera_data, "shift_y", 0.0)), 6),
            tuple(round(float(value), 9) for value in coefficients),
            fbp_obj_runtime_key(source_plane),
        )
    except FBP_DATA_ERRORS:
        return (None,)


def _fbp_objects_share_scene(first, second, scene=None):
    """Return whether two object datablocks are linked to the same live Scene."""
    if not first or not second:
        return False
    try:
        if scene is not None:
            return (
                scene.objects.get(first.name) is first
                and scene.objects.get(second.name) is second
            )
        first_scenes = tuple(getattr(first, "users_scene", ()) or ())
        second_scenes = tuple(getattr(second, "users_scene", ()) or ())
        if first_scenes and second_scenes:
            first_keys = {int(item.as_pointer()) for item in first_scenes}
            return any(int(item.as_pointer()) in first_keys for item in second_scenes)
    except FBP_DATA_ERRORS:
        return False
    # Temporarily unlinked objects can occur during import/Undo. Do not reject
    # them solely because Blender has not populated users_scene yet.
    return True

def _fbp_matte_visibility_request_for_source(source_rig, scene=None):
    """Return the least restrictive active display request for one matte source."""
    if not source_rig:
        return "NORMAL"
    try:
        from .layers import iter_scene_fbp_rigs
        scene = scene or getattr(bpy.context, "scene", None)
        rigs = iter_scene_fbp_rigs(scene) if scene is not None else ()
    except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
        rigs = ()
    requests = []
    contracts = (
        (FBP_EFFECT_ALPHA_MATTE, "fbp_alpha_matte_source", "fbp_alpha_matte_source_display"),
        (FBP_EFFECT_LUMA_MATTE, "fbp_luma_matte_source", "fbp_luma_matte_source_display"),
    )
    for target in rigs or ():
        for effect_id, source_prop, display_prop in contracts:
            try:
                if not fbp_effect_is_active(target, effect_id):
                    continue
                if getattr(target, source_prop, None) is not source_rig:
                    continue
                if not _fbp_objects_share_scene(target, source_rig, scene=scene):
                    continue
                requests.append(str(getattr(target, display_prop, "GUIDE") or "GUIDE").upper())
            except FBP_DATA_ERRORS:
                continue
    if "NORMAL" in requests:
        return "NORMAL"
    if "GUIDE" in requests:
        return "GUIDE"
    if "HIDDEN" in requests:
        return "HIDDEN"
    return "NORMAL"


def fbp_apply_matte_source_visibility(source_rig, scene=None, *, restore_normal=True, mode=None):
    """Apply Guide/Hidden display without changing the source layer's eye property."""
    if not source_rig:
        return False
    plane = getattr(source_rig, "fbp_plane_target", None)
    if not plane:
        return False
    mode = str(mode or _fbp_matte_visibility_request_for_source(source_rig, scene=scene) or "NORMAL").upper()
    if mode == "NORMAL":
        if not restore_normal:
            return False
        try:
            visible = bool(getattr(source_rig, "fbp_is_visible", True))
            viewport_hidden = not visible
            render_hidden = not visible
        except FBP_DATA_ERRORS:
            return False
    elif mode == "GUIDE":
        viewport_hidden = False
        render_hidden = True
    else:
        viewport_hidden = True
        render_hidden = True
    changed = False
    try:
        if bool(getattr(plane, "hide_viewport", False)) != viewport_hidden:
            plane.hide_viewport = viewport_hidden
            changed = True
        if bool(getattr(plane, "hide_render", False)) != render_hidden:
            plane.hide_render = render_hidden
            changed = True
    except FBP_DATA_ERRORS:
        return False
    return changed


def fbp_sync_matte_source_visibility(scene=None):
    """Reconcile source visibility in one O(layers) pass after structural changes."""
    try:
        from .layers import iter_scene_fbp_rigs
        scene = scene or getattr(bpy.context, "scene", None)
        rigs = tuple(iter_scene_fbp_rigs(scene)) if scene is not None else ()
    except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
        rigs = ()
    priority = {"HIDDEN": 1, "GUIDE": 2, "NORMAL": 3}
    requests = {}
    contracts = (
        (FBP_EFFECT_ALPHA_MATTE, "fbp_alpha_matte_source", "fbp_alpha_matte_source_display"),
        (FBP_EFFECT_LUMA_MATTE, "fbp_luma_matte_source", "fbp_luma_matte_source_display"),
    )
    for target in rigs:
        # Resolve the complete active stack once per rig. The runtime cache is
        # authoritative after external node edits and avoids two independent
        # material traversals for Alpha and Luma Matte checks.
        active_effect_ids = set(_fbp_runtime_effect_ids(target))
        for effect_id, source_prop, display_prop in contracts:
            try:
                if effect_id not in active_effect_ids:
                    continue
                source = getattr(target, source_prop, None)
                if (
                    not source
                    or source is target
                    or not bool(getattr(source, "is_fbp_control", False))
                    or bool(getattr(source, "fbp_is_color_plane", False))
                    or not _fbp_objects_share_scene(target, source, scene=scene)
                ):
                    continue
                mode = str(getattr(target, display_prop, "GUIDE") or "GUIDE").upper()
                key = fbp_obj_runtime_key(source)
                current = requests.get(key)
                if current is None or priority.get(mode, 2) > priority.get(current[1], 2):
                    requests[key] = (source, mode)
            except FBP_DATA_ERRORS:
                continue
    changed = False
    for rig in rigs:
        key = fbp_obj_runtime_key(rig)
        requested = requests.get(key)
        mode = requested[1] if requested else "NORMAL"
        changed = fbp_apply_matte_source_visibility(
            rig, scene=scene, mode=mode
        ) or changed
    return changed


def _fbp_scene_for_mask_rig(rig):
    """Resolve the scene that owns a mask rig without assuming active context."""
    try:
        scenes = tuple(getattr(rig, "users_scene", ()) or ()) if rig else ()
        if scenes:
            active = getattr(bpy.context, "scene", None)
            if active in scenes:
                return active
            return scenes[0]
    except FBP_DATA_ERRORS:
        pass
    return getattr(bpy.context, "scene", None)


def _fbp_set_group_input_value(node, socket_name, value):
    socket = _fbp_node_socket(getattr(node, "inputs", ()), socket_name)
    if socket is None:
        return False
    try:
        current = getattr(socket, "default_value", None)
        if _fbp_effect_values_equal(current, value):
            return False
        socket.default_value = value
        return True
    except FBP_DATA_ERRORS:
        return False


_FBP_SAMPLE_TAP_THRESHOLD_KEY = "fbp_sample_tap_threshold"
_FBP_SAMPLE_TAPS_INDEXED_KEY = "fbp_sample_taps_indexed"
_FBP_SAMPLE_TAP_STATE_KEY = "fbp_sample_tap_state"


def _fbp_auto_rows_label(rig, prop_name):
    """``Rows`` label that says when zero means automatic rows."""
    try:
        return "Rows (Auto)" if int(getattr(rig, prop_name, 0) or 0) <= 0 else "Rows"
    except (AttributeError, ReferenceError, TypeError, ValueError):
        return "Rows"


def fbp_effect_performance_hint(effect_id, definition=None):
    """Tooltip of a heavy effect: what it costs and which settings help."""
    definition = definition if definition is not None else (fbp_effect_definition(effect_id) or {})
    performance = str(definition.get("performance", "") or "").upper()
    lead = (
        "Very heavy effect: expect slow viewport playback"
        if performance == "VERY_HEAVY"
        else "Heavy effect: may slow viewport playback"
    )
    names = []
    keeps_render = False
    samples = _fbp_definition_samples_property(definition)
    if samples:
        names.append(samples)
    for contract in tuple(definition.get("quality_contracts", ()) or ()):
        for key in ("viewport_property", "playback_property"):
            name = str((contract or {}).get(key, "") or "")
            if name:
                names.append(name)
        keeps_render = keeps_render or bool((contract or {}).get("render_property"))
    labels = []
    for name in dict.fromkeys(names):
        label = str(_fbp_effect_property_label(definition, name, None) or "")
        if label and label not in labels:
            labels.append(label)
    if labels:
        tail = "; renders keep their own quality" if keeps_render else ""
        return f"{lead}. Lower {', '.join(labels)} for a faster preview{tail}"
    return f"{lead}. Hide it in the viewport while animating to keep playback smooth"


def _fbp_definition_samples_property(definition):
    """Return the RNA property driving a blur group's ``Samples`` socket."""
    for prop_name, socket_name in (definition.get("property_map", {}) or {}).items():
        if str(socket_name) == "Samples":
            return str(prop_name)
    return ""


def _fbp_index_sample_taps(node_tree):
    """Tag every image tap gated by ``Samples`` with its enabling threshold.

    Blur groups gate each tap with ``Samples > index + 0.5`` and multiply the
    tap by that weight. The GPU still fetched the texture of disabled taps.
    Tagging the Image Texture node of each tap lets the runtime mute exactly the
    taps whose weight is zero, so the result is identical and fetches scale
    with Samples. Works on generated and prebundled groups alike.
    """
    try:
        if bool(node_tree.get(_FBP_SAMPLE_TAPS_INDEXED_KEY, False)):
            return
    except FBP_DATA_ERRORS:
        return
    # ``NodeSocket.links`` scans every link of the tree on each access, which
    # made this pass quadratic in the size of large groups (Riso Print,
    # blurs). Index the links once by socket instead.
    links_to = {}
    links_from = {}
    try:
        for link in node_tree.links:
            links_to.setdefault(link.to_socket.as_pointer(), link)
            links_from.setdefault(link.from_socket.as_pointer(), []).append(link)
    except FBP_DATA_ERRORS:
        return

    def upstream(socket):
        # Follow one input link, skipping layout reroutes.
        for _guard in range(16):
            link = links_to.get(socket.as_pointer())
            if link is None:
                return None
            node = link.from_node
            if getattr(node, "type", "") != "REROUTE":
                return link.from_socket
            socket = node.inputs[0]
        return None

    def downstream(socket, depth=0):
        for link in links_from.get(socket.as_pointer(), ()):
            node = link.to_node
            if getattr(node, "type", "") == "REROUTE":
                if depth < 16:
                    yield from downstream(node.outputs[0], depth + 1)
                continue
            yield node

    tagged = 0
    try:
        for gate in node_tree.nodes:
            if getattr(gate, "type", "") != "MATH" or getattr(gate, "operation", "") != "GREATER_THAN":
                continue
            source = upstream(gate.inputs[0])
            if source is None:
                continue
            if getattr(source.node, "type", "") != "GROUP_INPUT" or source.name != "Samples":
                continue
            threshold = float(gate.inputs[1].default_value)
            for weight in downstream(gate.outputs[0]):
                if getattr(weight, "type", "") != "MATH" or weight.operation != "MULTIPLY":
                    continue
                for scale in downstream(weight.outputs[0]):
                    if getattr(scale, "type", "") != "VECT_MATH" or scale.operation != "SCALE":
                        continue
                    premultiplied = upstream(scale.inputs[0])
                    if premultiplied is None:
                        continue
                    image_socket = upstream(premultiplied.node.inputs[0])
                    image = image_socket.node if image_socket is not None else None
                    if getattr(image, "type", "") != "TEX_IMAGE":
                        continue
                    image[_FBP_SAMPLE_TAP_THRESHOLD_KEY] = threshold
                    tagged += 1
        node_tree[_FBP_SAMPLE_TAPS_INDEXED_KEY] = True
        node_tree["fbp_sample_tap_count"] = tagged
    except FBP_DATA_ERRORS:
        return


def _fbp_samples_property_is_animated(rig, effect_id, prop_name):
    try:
        profile = _fbp_effect_runtime_profile(rig)
    except FBP_DATA_ERRORS:
        return True
    if prop_name in (profile.get("animated_effect_properties", {}) or {}).get(effect_id, ()):
        return True
    for channel in profile.get("animated_instance_channels", ()) or ():
        try:
            channel_effect, _instance, channel_prop = _fbp_effect_instance_channel_identity(channel)
        except FBP_DATA_ERRORS:
            continue
        if channel_effect == effect_id and channel_prop == prop_name:
            return True
    return False


def _fbp_samples_link_is_dynamic(socket, plane):
    """True when a linked ``Samples`` socket can change without a Python update.

    A Modifiers-panel shell feeds the socket through an Object Attribute node;
    Frame By Plane mirrors its value into ``default_value`` on every edit, so
    the socket is only dynamic when that modifier input is animated or driven.
    Any other link (a user's own node) is treated as dynamic.
    """
    if not bool(getattr(socket, "is_linked", False)):
        return False
    try:
        source = socket.links[0].from_node
        if getattr(source, "type", "") != "ATTRIBUTE" or not source.get("fbp_shell_attribute"):
            return True
        path = str(getattr(source, "attribute_name", "") or "")
        owners = (plane,) if (path and plane is not None) else ()
        for owner in owners:
            animation_data = getattr(owner, "animation_data", None)
            if animation_data is None:
                continue
            curves = tuple(fbp_action_fcurves(owner) or ()) + tuple(animation_data.drivers or ())
            if any(str(getattr(curve, "data_path", "") or "") == path for curve in curves):
                return True
        return False
    except FBP_DATA_ERRORS:
        return True


# Texture nodes whose result an effect multiplies by one of its own inputs:
# while that input is exactly zero (and not keyed or driven) the nodes are
# muted, so the GPU skips them and the picture stays the same.
_FBP_GATED_EFFECT_NODES = {
    "RISO_PRINT": (
        ("Use Ink 3", ("Riso Ink 3 Source", "Riso Ink 3 Screen Phase", "Riso Ink 3 Dot Jitter", "Riso Ink 3 Grain")),
        ("Halftone", tuple(f"Riso Ink {ink} {part}" for ink in (1, 2, 3) for part in ("Screen Phase", "Dot Jitter"))),
        ("Grain", tuple(f"Riso Ink {ink} Grain" for ink in (1, 2, 3))),
    ),
}


def _fbp_gate_properties(definition, gates):
    sockets = {socket_name for socket_name, _prefixes in gates}
    return {
        str(prop_name)
        for prop_name, socket_name in (definition.get("property_map", {}) or {}).items()
        if str(socket_name) in sockets
    }


def _fbp_sync_gated_node_mutes(rig, node, gates):
    """Mute the texture nodes of ``gates`` whose controlling input is zero."""
    node_tree = getattr(node, "node_tree", None)
    if node_tree is None:
        return False
    plane = _fbp_plane(rig, repair=False)
    closed = []
    state_parts = []
    for socket_name, prefixes in gates:
        socket = _fbp_node_socket(getattr(node, "inputs", ()), socket_name)
        if socket is None:
            continue
        try:
            is_zero = (
                not _fbp_samples_link_is_dynamic(socket, plane)
                and float(socket.default_value) == 0.0
            )
        except FBP_DATA_ERRORS:
            is_zero = False
        state_parts.append("1" if is_zero else "0")
        if is_zero:
            closed.extend(prefixes)
    state = "".join(state_parts)
    try:
        if str(node_tree.get("fbp_gated_node_state", "")) == state:
            return False
        node_tree["fbp_gated_node_state"] = state
    except FBP_DATA_ERRORS:
        pass
    closed = tuple(closed)
    every = tuple(prefix for _socket_name, prefixes in gates for prefix in prefixes)
    changed = False
    try:
        for target in node_tree.nodes:
            name = str(getattr(target, "name", "") or "")
            if not name.startswith(every) or not str(getattr(target, "type", "")).startswith("TEX_"):
                continue
            mute = bool(closed) and name.startswith(closed)
            if bool(target.mute) != mute:
                target.mute = mute
                changed = True
    except FBP_DATA_ERRORS:
        return changed
    return changed


def _fbp_sync_runtime_mutes(rig, effect_id, node):
    """Re-evaluate every value-driven mute of one effect node (shell edits)."""
    changed = False
    gates = _FBP_GATED_EFFECT_NODES.get(fbp_normalize_effect_id(effect_id))
    if gates:
        changed = _fbp_sync_gated_node_mutes(rig, node, gates) or changed
    if _fbp_node_socket(getattr(node, "inputs", ()), "Samples") is not None:
        changed = _fbp_sync_sample_tap_mutes(rig, effect_id, node) or changed
    return changed


def _fbp_sync_sample_tap_mutes(rig, effect_id, node, definition=None):
    """Mute the image taps that the current ``Samples`` value already weights to zero."""
    node_tree = getattr(node, "node_tree", None)
    socket = _fbp_node_socket(getattr(node, "inputs", ()), "Samples")
    if node_tree is None or socket is None:
        return False
    definition = definition or fbp_effect_definition(effect_id)
    prop_name = _fbp_definition_samples_property(definition)
    _fbp_index_sample_taps(node_tree)
    # A shared group or animated/linked Samples needs every tap available.
    keep_all = (
        _fbp_samples_link_is_dynamic(socket, _fbp_plane(rig, repair=False))
        or not bool(definition.get("private_group", False))
        or (prop_name and _fbp_samples_property_is_animated(rig, effect_id, prop_name))
    )
    try:
        samples = float(socket.default_value)
    except FBP_DATA_ERRORS:
        keep_all = True
        samples = 0.0
    state = "ALL" if keep_all else f"{samples:g}"
    try:
        if str(node_tree.get(_FBP_SAMPLE_TAP_STATE_KEY, "")) == state:
            return False
        node_tree[_FBP_SAMPLE_TAP_STATE_KEY] = state
    except FBP_DATA_ERRORS:
        pass
    changed = False
    try:
        for image in node_tree.nodes:
            if getattr(image, "type", "") != "TEX_IMAGE":
                continue
            threshold = image.get(_FBP_SAMPLE_TAP_THRESHOLD_KEY)
            if threshold is None:
                continue
            mute = (not keep_all) and not (samples > float(threshold))
            if bool(image.mute) != mute:
                image.mute = mute
                changed = True
    except FBP_DATA_ERRORS:
        return changed
    return changed


def _fbp_sync_clipping_source_effect_inputs(rig, source_rig, node):
    """Mirror supported source effects into a Clipping Mask sampler.

    The Clipping Mask node samples the source layer from another material.  It
    cannot directly read that material's final alpha, so we mirror the source
    layer's lightweight alpha/UV-changing effects that affect the clipping
    silhouette.  This currently covers the common production path requested by
    users: Chroma Key transparency followed by Pixelate.
    """
    if not rig or not source_rig or not node:
        return False
    changed = False

    pixelate_enabled = bool(fbp_effect_is_active(source_rig, FBP_EFFECT_PIXELATE))
    changed = _fbp_set_group_input_value(node, "Use Source Pixelate", 1.0 if pixelate_enabled else 0.0) or changed
    if pixelate_enabled:
        effective_x, effective_y, _grid_mode = _fbp_pixelate_grid(source_rig)
        for attr, socket_name, fallback, override in (
            ("fbp_pixelate_resolution", "Source Pixels X", 64.0, effective_x),
            ("fbp_pixelate_height", "Source Pixels Y", 36.0, effective_y),
            ("fbp_pixelate_rotation", "Source Pixel Rotation", 0.0, None),
            ("fbp_pixelate_offset_x", "Source Pixel Offset X", 0.0, None),
            ("fbp_pixelate_offset_y", "Source Pixel Offset Y", 0.0, None),
        ):
            try:
                value = float(
                    override if override is not None else getattr(source_rig, attr, fallback)
                )
            except FBP_DATA_ERRORS:
                value = float(fallback)
            except Exception:
                value = float(fallback)
            changed = _fbp_set_group_input_value(node, socket_name, value) or changed

    key = _fbp_source_color_key_state(source_rig)
    changed = _fbp_set_group_input_value(node, "Use Source Chroma Key", 1.0 if key else 0.0) or changed
    if key:
        for socket_name, value in zip(
            ("Source Key Color", "Source Key Tolerance", "Source Key Softness", "Source Key Invert"),
            key,
        ):
            changed = _fbp_set_group_input_value(node, socket_name, value) or changed
    return changed


def _fbp_source_color_key_state(source_rig):
    """Return the source layer's Color Key as clipping-source key inputs.

    The clipping group keys the source with Chroma Key semantics: it removes
    pixels within ``tolerance +/- softness`` of the color unless inverted.
    Color Key ramps from ``tolerance`` to ``tolerance + softness`` and keeps
    the matched pixels unless inverted, so both are converted here. Returns
    ``None`` when no Layer-targeted Color Key is active.
    """
    if (
        source_rig is None
        or not fbp_effect_is_active(source_rig, FBP_EFFECT_COLOR_MASK)
        or fbp_effect_mask_raw_target_ref(source_rig, FBP_EFFECT_COLOR_MASK) not in {"", "LAYER"}
    ):
        return None
    try:
        color = tuple(float(v) for v in getattr(source_rig, "fbp_color_mask_color", (0.0, 1.0, 0.0, 1.0)))
        if len(color) == 3:
            color = (*color, 1.0)
        color = tuple(round(v, 6) for v in color[:4])
        tolerance = float(getattr(source_rig, "fbp_color_mask_tolerance", 0.12))
        softness = max(0.0, float(getattr(source_rig, "fbp_color_mask_softness", 0.08)))
        invert = bool(getattr(source_rig, "fbp_color_mask_invert", False))
    except FBP_DATA_ERRORS:
        return None
    half = softness * 0.5
    return (
        color,
        round(tolerance + half, 6),
        round(half, 6),
        0.0 if invert else 1.0,
    )


def _fbp_layer_blend_procedural_rgba(source_rig, scene=None):
    """Return the current flat Color Plane RGBA, or ``None`` if spatial.

    Transparent logical frames are valid sources with alpha zero. Gradient and
    Holdout frames return ``None`` because collapsing them to one color would
    make blend modes visually incorrect.
    """
    if not source_rig or not bool(getattr(source_rig, "fbp_is_color_plane", False)):
        return None
    plane = getattr(source_rig, "fbp_plane_target", None)
    mesh = getattr(plane, "data", None) if plane else None
    materials = getattr(mesh, "materials", None) if mesh else None
    if not materials or len(materials) == 0:
        return None
    try:
        from .core import fbp_sequence_index_at_frame
        from .layers import (
            fbp_procedural_kind_for_item,
            fbp_procedural_kind_from_material,
        )
        from .materials import fbp_material_color_value

        rows = getattr(source_rig, "fbp_images", ()) or ()
        if len(rows):
            scene = scene or _fbp_scene_for_mask_rig(source_rig)
            index = fbp_sequence_index_at_frame(
                source_rig, getattr(scene, "frame_current", 1) if scene else 1
            )
            if index < 0:
                return (0.0, 0.0, 0.0, 0.0)
            index = max(0, min(int(index), len(materials) - 1))
            item = rows[index] if index < len(rows) else None
            if fbp_procedural_kind_for_item(source_rig, index, "SOLID") != "SOLID":
                return None
            if item is not None and bool(getattr(item, "is_empty", False)):
                return (0.0, 0.0, 0.0, 0.0)
        else:
            index = 0
            if fbp_procedural_kind_from_material(
                materials[index],
                getattr(source_rig, "fbp_color_plane_mode", "SOLID"),
            ) != "SOLID":
                return None
        return tuple(
            float(value)
            for value in fbp_material_color_value(
                materials[index],
                tuple(getattr(source_rig, "fbp_color_plane_color", (1.0, 1.0, 1.0, 1.0))),
            )[:4]
        )
    except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError, IndexError):
        return None


def _fbp_sync_layer_blend_source(rig, node):
    """Bind Layer Blend through its compact image-or-RGBA v2 contract."""
    node_group = getattr(node, "node_tree", None) if node else None
    image_nodes = _fbp_mask_source_image_nodes(node_group)
    if not node_group or not image_nodes:
        return False, False
    try:
        source_rig = getattr(rig, "fbp_layer_blend_source", None)
    except FBP_DATA_ERRORS:
        source_rig = None
    if (
        source_rig is rig
        or not _fbp_objects_share_scene(rig, source_rig)
        or not bool(getattr(source_rig, "is_fbp_control", False))
    ):
        source_rig = None

    scene = _fbp_scene_for_mask_rig(rig)
    procedural_rgba = None
    source_material = None
    source_node = None
    source_image = None
    if source_rig is not None and bool(getattr(source_rig, "fbp_is_color_plane", False)):
        procedural_rgba = _fbp_layer_blend_procedural_rgba(source_rig, scene)
        try:
            source_plane = getattr(source_rig, "fbp_plane_target", None)
            source_mesh = getattr(source_plane, "data", None) if source_plane else None
            materials = getattr(source_mesh, "materials", None) if source_mesh else None
            if materials and len(materials):
                from .core import fbp_sequence_index_at_frame
                index = (
                    fbp_sequence_index_at_frame(source_rig, getattr(scene, "frame_current", 1))
                    if len(getattr(source_rig, "fbp_images", ()) or ())
                    else 0
                )
                if index >= 0:
                    source_material = materials[max(0, min(int(index), len(materials) - 1))]
        except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError, IndexError):
            source_material = None
    elif source_rig is not None:
        try:
            from .layers import fbp_layer_has_sampleable_image
            if fbp_layer_has_sampleable_image(source_rig):
                source_material, source_node = _fbp_material_image_node(source_rig)
                source_image = getattr(source_node, "image", None) if source_node else None
        except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
            source_material = source_node = source_image = None

    valid_source = bool(procedural_rgba is not None or source_image is not None)
    try:
        source_opacity = max(
            0.0, min(1.0, float(getattr(source_rig, "fbp_opacity", 1.0)))
        ) if source_rig is not None else 1.0
        if source_rig is not None and not bool(getattr(source_rig, "fbp_is_visible", True)):
            source_opacity = 0.0
    except FBP_DATA_ERRORS:
        source_opacity = 1.0

    desired_interpolation = "Linear"
    desired_extension = "CLIP"
    if source_node is not None:
        try:
            desired_interpolation = str(getattr(source_node, "interpolation", "Linear") or "Linear")
            desired_extension = str(getattr(source_node, "extension", "CLIP") or "CLIP").upper()
        except FBP_DATA_ERRORS:
            desired_interpolation, desired_extension = "Linear", "CLIP"
    if desired_extension not in {"REPEAT", "EXTEND", "CLIP", "MIRROR"}:
        desired_extension = "CLIP"
    rgba = tuple(procedural_rgba or (0.0, 0.0, 0.0, 0.0))
    source_user_signature = ()
    if source_node is not None:
        try:
            source_user = getattr(source_node, "image_user", None)
            source_user_signature = tuple(
                getattr(source_user, attr, None)
                for attr in (
                    "frame_duration",
                    "frame_start",
                    "frame_offset",
                    "use_cyclic",
                    "use_auto_refresh",
                )
            )
        except FBP_DATA_ERRORS:
            source_user_signature = ()
    try:
        group_key = _fbp_node_group_cache_key(node_group)
        signature = (
            "LAYER_BLEND_V2",
            fbp_obj_runtime_key(source_rig) if source_rig else None,
            fbp_obj_runtime_key(source_material) if source_material else None,
            fbp_obj_runtime_key(source_image) if source_image else None,
            source_user_signature,
            tuple(round(float(value), 7) for value in rgba),
            round(float(source_opacity), 6),
            desired_interpolation,
            desired_extension,
        )
    except FBP_DATA_ERRORS:
        group_key = None
        signature = (
            "LAYER_BLEND_V2", None, None, None, source_user_signature, rgba,
            round(float(source_opacity), 6), desired_interpolation, desired_extension,
        )
    if group_key is not None and _FBP_MASK_SOURCE_SYNC_CACHE.get(group_key) == signature:
        return valid_source, False

    changed = False
    for image_node in image_nodes:
        try:
            if getattr(image_node, "image", None) is not source_image:
                image_node.image = source_image
                changed = True
            if source_node is not None:
                changed = _fbp_copy_shader_image_user(source_node, image_node) or changed
            if image_node.interpolation != desired_interpolation:
                image_node.interpolation = desired_interpolation
                changed = True
            if image_node.extension != desired_extension:
                image_node.extension = desired_extension
                changed = True
        except FBP_DATA_ERRORS:
            continue
    changed = _fbp_set_group_input_value(node, "Source Color", rgba) or changed
    changed = _fbp_set_group_input_value(node, "Source Alpha", rgba[3]) or changed
    changed = _fbp_set_group_input_value(
        node, "Use Procedural Source", 1.0 if procedural_rgba is not None else 0.0
    ) or changed
    changed = _fbp_set_group_input_value(node, "Source Opacity", source_opacity) or changed
    changed = _fbp_set_group_input_value(
        node, "Use Source Sample", 1.0 if valid_source else 0.0
    ) or changed
    if group_key is not None:
        if len(_FBP_MASK_SOURCE_SYNC_CACHE) >= 256 and group_key not in _FBP_MASK_SOURCE_SYNC_CACHE:
            _FBP_MASK_SOURCE_SYNC_CACHE.clear()
        _FBP_MASK_SOURCE_SYNC_CACHE[group_key] = signature
    if changed:
        try:
            node_group.update_tag()
        except FBP_DATA_ERRORS:
            pass
    return valid_source, changed


def fbp_refresh_layer_blend_dependents(source_rig, scene=None):
    """Refresh only Layer Blend nodes that directly reference ``source_rig``."""
    if source_rig is None:
        return 0
    try:
        from .layers import (
            get_primary_fbp_collection,
            iter_fbp_rigs_in_collection,
            iter_scene_fbp_rigs,
        )
        scene = scene or _fbp_scene_for_mask_rig(source_rig)
        collection = get_primary_fbp_collection(source_rig)
        candidates = (
            tuple(iter_fbp_rigs_in_collection(collection, recursive=False))
            if collection is not None
            else tuple(iter_scene_fbp_rigs(scene))
        )
    except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
        return 0
    changed_count = 0
    for target in candidates:
        try:
            if getattr(target, "fbp_layer_blend_source", None) is not source_rig:
                continue
            for node in _fbp_find_shader_effect_nodes_for_rig(
                target, FBP_EFFECT_LAYER_BLEND
            ):
                _has_source, changed = _fbp_sync_layer_blend_source(target, node)
                changed_count += int(bool(changed))
        except FBP_DATA_ERRORS:
            continue
    return changed_count


def _fbp_sync_mask_source(rig, effect_id, node):
    """Bind a track-matte node group to another FBP layer's source media."""
    if effect_id == FBP_EFFECT_LAYER_BLEND:
        return _fbp_sync_layer_blend_source(rig, node)
    definition = fbp_effect_definition(effect_id)
    prop_name = str(definition.get("mask_source_property", "") or "")
    node_group = getattr(node, "node_tree", None) if node else None
    image_nodes = _fbp_mask_source_image_nodes(node_group)
    coord_nodes = _fbp_mask_source_coord_nodes(node_group)
    camera_coord_nodes = _fbp_mask_camera_coord_nodes(node_group)
    if not prop_name or not image_nodes:
        return False, False
    try:
        source_rig = getattr(rig, prop_name, None)
    except FBP_DATA_ERRORS:
        source_rig = None
    luma_external = False
    external_path = ""
    external_image = None
    if effect_id == FBP_EFFECT_LUMA_MATTE:
        try:
            luma_external = str(getattr(rig, "fbp_luma_matte_source_type", "FBP_SEQUENCE") or "FBP_SEQUENCE").upper() == "FILE"
            raw_path = str(getattr(rig, "fbp_luma_matte_path", "") or "")
            external_path = bpy.path.abspath(raw_path) if raw_path else ""
            external_path = os.path.normcase(os.path.realpath(external_path)) if external_path else ""
            external_image = getattr(rig, "fbp_luma_matte_image", None)
        except (AttributeError, OSError, ReferenceError, RuntimeError, TypeError, ValueError):
            luma_external = False
            external_path = ""
            external_image = None
        if luma_external:
            source_rig = None
            if external_path and os.path.isfile(external_path):
                try:
                    current_path = ""
                    if external_image is not None:
                        current_path = bpy.path.abspath(str(getattr(external_image, "filepath", "") or ""))
                        current_path = os.path.normcase(os.path.realpath(current_path)) if current_path else ""
                    if external_image is None or current_path != external_path:
                        external_image = bpy.data.images.load(external_path, check_existing=True)
                        fbp_set_rna_property_silent(rig, "fbp_luma_matte_image", external_image)
                except (OSError, ReferenceError, RuntimeError, TypeError, ValueError):
                    external_image = None
            else:
                external_image = None
    try:
        from .grease_pencil_bridge import is_gp_drawing_canvas, refresh_gp_mask
    except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
        is_gp_drawing_canvas = lambda _obj: False
        refresh_gp_mask = None

    source_is_gp = bool(source_rig and is_gp_drawing_canvas(source_rig))
    if source_rig is rig or not _fbp_objects_share_scene(rig, source_rig):
        source_rig = None
        source_is_gp = False
    elif not source_is_gp and (
        not bool(getattr(source_rig, "is_fbp_control", False))
        or bool(getattr(source_rig, "fbp_is_color_plane", False))
    ):
        source_rig = None
        source_is_gp = False

    if luma_external:
        _source_material, source_node = None, None
        source_image = external_image
    elif source_is_gp and source_rig is not None:
        _source_material, source_node = None, None
        source_image = getattr(source_rig, "fbp_gp_mask_image", None)
        if callable(refresh_gp_mask):
            try:
                source_image, _changed = refresh_gp_mask(source_rig, force=False, scene=_fbp_scene_for_mask_rig(rig))
            except FBP_DATA_ERRORS:
                source_image = getattr(source_rig, "fbp_gp_mask_image", None)
    else:
        _source_material, source_node = _fbp_material_image_node(source_rig) if source_rig else (None, None)
        source_image = getattr(source_node, "image", None) if source_node else None
    source_user = None
    try:
        if source_node is not None and str(getattr(source_image, "source", "") or "").upper() in {"SEQUENCE", "MOVIE"}:
            source_user = getattr(source_node, "image_user", None)
        elif luma_external and source_image is not None and image_nodes:
            source_user = getattr(image_nodes[0], "image_user", None)
    except FBP_DATA_ERRORS:
        source_user = None
    # Track mattes sample the source image in a private shader group. Crop and
    # Extend are encoded by UVs outside 0..1 plus the source Image Texture's
    # extension mode, so the private sampler must mirror that contract. External
    # Luma files and generated GP masks remain clipped because they have no FBP
    # plane border mode of their own.
    desired_interpolation = "Linear"
    desired_extension = "CLIP"
    if source_node is not None and source_image is not None:
        try:
            desired_interpolation = str(getattr(source_node, "interpolation", "Linear") or "Linear")
        except FBP_DATA_ERRORS:
            desired_interpolation = "Linear"
        try:
            desired_extension = str(getattr(source_node, "extension", "CLIP") or "CLIP").upper()
        except FBP_DATA_ERRORS:
            desired_extension = "CLIP"
    if desired_extension not in {"REPEAT", "EXTEND", "CLIP", "MIRROR"}:
        desired_extension = "CLIP"
    try:
        if source_is_gp and source_rig is not None:
            source_opacity = max(0.0, min(1.0, float(getattr(source_rig, "fbp_gp_canvas_opacity", 1.0))))
        else:
            source_opacity = (
                max(0.0, min(1.0, float(getattr(source_rig, "fbp_opacity", 1.0))))
                if source_rig else 1.0
            )
        if effect_id == FBP_EFFECT_CLIPPING_MASK and source_rig is not None:
            # A clipped layer follows the visible base, including Eye/Solo.
            # Keep the source bound and drive its alpha to zero rather than
            # treating a hidden source as missing (missing sources pass through).
            if source_is_gp:
                source_visible = bool(getattr(source_rig, "fbp_gp_canvas_visible", True)) and not bool(source_rig.hide_get())
            else:
                source_visible = bool(getattr(source_rig, "fbp_is_visible", True))
            source_opacity *= 1.0 if source_visible else 0.0
    except FBP_DATA_ERRORS:
        source_opacity = 1.0
    if source_is_gp and source_rig is not None:
        source_plane = source_rig
        source_bounds = (-1.0, 1.0, -1.0, 1.0)
        source_uv_bounds = (0.0, 1.0, 0.0, 1.0)
    else:
        source_plane, source_bounds, source_uv_bounds = _fbp_source_plane_bounds(source_rig)
    scene = _fbp_scene_for_mask_rig(rig)
    camera = getattr(scene, "camera", None) if scene is not None else None
    camera_requested = bool(
        effect_id == FBP_EFFECT_CLIPPING_MASK
        and getattr(rig, "fbp_clipping_mask_use_camera_projection", True)
    )
    camera_driver_bound = bool(
        camera_requested
        and camera is not None
        and source_plane is not None
        and fbp_bind_clipping_camera_matrix_drivers(node, camera, source_plane)
    )
    if not camera_driver_bound:
        _fbp_remove_clipping_matrix_drivers(node)
    camera_coefficients = (
        _fbp_clipping_camera_matrix(scene, source_plane)
        if camera_requested and source_plane is not None and not camera_driver_bound
        else None
    )
    camera_enabled = bool(
        camera_requested and (camera_driver_bound or camera_coefficients is not None)
    )
    try:
        camera_type = str(
            getattr(getattr(camera, "data", None), "type", "PERSP") or "PERSP"
        ).upper()
    except FBP_DATA_ERRORS:
        camera_type = "PERSP"
    camera_projection_signature = (
        "DRIVER_V1",
        fbp_obj_runtime_key(camera) if camera is not None else None,
        fbp_obj_runtime_key(source_plane) if source_plane is not None else None,
        camera_type,
    ) if camera_driver_bound else _fbp_camera_projection_signature(
        scene, source_plane, camera_coefficients
    )

    user_signature = []
    try:
        source_kind = str(getattr(source_image, "source", "") or "").upper()
    except FBP_DATA_ERRORS:
        source_kind = ""
    if source_kind in {"SEQUENCE", "MOVIE"} and source_user is not None:
        for attr in ("frame_duration", "frame_start", "frame_offset", "use_cyclic", "use_auto_refresh"):
            try:
                user_signature.append(getattr(source_user, attr))
            except FBP_DATA_ERRORS:
                user_signature.append(None)
    source_effect_signature = ()
    if effect_id == FBP_EFFECT_CLIPPING_MASK and source_rig is not None and not source_is_gp:
        effect_values = []
        try:
            effect_values.append((FBP_EFFECT_PIXELATE, bool(fbp_effect_is_active(source_rig, FBP_EFFECT_PIXELATE))))
            effective_pixel_x, effective_pixel_y, effective_pixel_mode = _fbp_pixelate_grid(
                source_rig
            )
            effect_values.extend((
                ("fbp_pixelate_effective_x", int(effective_pixel_x)),
                ("fbp_pixelate_effective_y", int(effective_pixel_y)),
                ("fbp_pixelate_grid_mode", str(effective_pixel_mode)),
            ))
            effect_values.extend(
                (attr, round(float(getattr(source_rig, attr, 0.0)), 6))
                for attr in (
                    "fbp_pixelate_size", "fbp_pixelate_stretch",
                    "fbp_pixelate_resolution", "fbp_pixelate_height", "fbp_pixelate_rotation",
                    "fbp_pixelate_offset_x", "fbp_pixelate_offset_y",
                )
            )
            effect_values.append((FBP_EFFECT_COLOR_MASK, _fbp_source_color_key_state(source_rig)))
        except FBP_DATA_ERRORS:
            effect_values = []
        except Exception:
            effect_values = []
        source_effect_signature = tuple(effect_values)
    try:
        group_key = _fbp_node_group_cache_key(node_group)
        signature = (
            "FILE" if luma_external else "FBP_SEQUENCE",
            external_path if luma_external else "",
            fbp_obj_runtime_key(source_rig) if source_rig else None,
            fbp_obj_runtime_key(source_image) if source_image else None,
            tuple(user_signature),
            fbp_obj_runtime_key(source_plane) if source_plane else None,
            tuple(round(float(value), 9) for value in source_bounds),
            tuple(round(float(value), 9) for value in source_uv_bounds),
            desired_interpolation,
            desired_extension,
            bool(camera_enabled),
            camera_projection_signature,
            round(float(source_opacity), 6),
            source_effect_signature,
        )
    except FBP_DATA_ERRORS:
        group_key = None
        signature = (
            "FILE" if luma_external else "FBP_SEQUENCE",
            external_path if luma_external else "",
            None, None, tuple(user_signature), None,
            tuple(source_bounds), tuple(source_uv_bounds),
            desired_interpolation, desired_extension,
            bool(camera_enabled), camera_projection_signature, round(float(source_opacity), 6),
            source_effect_signature,
        )
    cached = _FBP_MASK_SOURCE_SYNC_CACHE.get(group_key) if group_key is not None else None
    if cached == signature:
        return bool(source_image), False
    changed = False
    for image_node in image_nodes:
        try:
            if getattr(image_node, "image", None) is not source_image:
                image_node.image = source_image
                changed = True
            if source_node is not None:
                changed = _fbp_copy_shader_image_user(source_node, image_node) or changed
            elif luma_external and source_image is not None:
                image_user = getattr(image_node, "image_user", None)
                if image_user is not None:
                    try:
                        duration = max(1, int(getattr(source_image, "frame_duration", 1) or 1))
                        if int(getattr(image_user, "frame_duration", 1) or 1) != duration:
                            image_user.frame_duration = duration
                            changed = True
                        if not bool(getattr(image_user, "use_auto_refresh", False)):
                            image_user.use_auto_refresh = True
                            changed = True
                    except FBP_DATA_ERRORS:
                        pass
            if image_node.interpolation != desired_interpolation:
                image_node.interpolation = desired_interpolation
                changed = True
            if image_node.extension != desired_extension:
                image_node.extension = desired_extension
                changed = True
        except FBP_DATA_ERRORS:
            continue
    for coord_node in coord_nodes:
        try:
            if getattr(coord_node, "object", None) is not source_plane:
                coord_node.object = source_plane
                changed = True
        except FBP_DATA_ERRORS:
            continue
    for camera_coord_node in camera_coord_nodes:
        try:
            if getattr(camera_coord_node, "object", None) is not camera:
                camera_coord_node.object = camera
                changed = True
        except FBP_DATA_ERRORS:
            continue
    for socket_name, value in zip(
        (
            "Source Min X", "Source Max X", "Source Min Y", "Source Max Y",
            "Source UV Min X", "Source UV Max X", "Source UV Min Y", "Source UV Max Y",
        ),
        tuple(source_bounds) + tuple(source_uv_bounds),
        strict=True,
    ):
        socket = _fbp_node_socket(getattr(node, "inputs", ()), socket_name)
        if socket is not None and not _fbp_effect_values_equal(
            getattr(socket, "default_value", None), value
        ):
            try:
                socket.default_value = float(value)
                changed = True
            except FBP_DATA_ERRORS:
                pass
    camera_perspective_socket = _fbp_node_socket(
        getattr(node, "inputs", ()), "Camera Perspective"
    )
    if camera_perspective_socket is not None:
        camera_is_perspective = 0.0 if camera_type == "ORTHO" else 1.0
        if not _fbp_effect_values_equal(
            getattr(camera_perspective_socket, "default_value", None), camera_is_perspective
        ):
            try:
                camera_perspective_socket.default_value = camera_is_perspective
                changed = True
            except FBP_DATA_ERRORS:
                pass

    camera_projection_socket = _fbp_node_socket(
        getattr(node, "inputs", ()), "Use Camera Projection"
    )
    if camera_projection_socket is not None:
        desired_camera = 1.0 if camera_enabled else 0.0
        if not _fbp_effect_values_equal(
            getattr(camera_projection_socket, "default_value", None), desired_camera
        ):
            try:
                camera_projection_socket.default_value = desired_camera
                changed = True
            except FBP_DATA_ERRORS:
                pass
    if camera_coefficients is not None and not camera_driver_bound:
        for coefficient_name, value in zip(
            tuple(f"M{row}{column}" for row in range(3) for column in range(4)),
            camera_coefficients,
            strict=True,
        ):
            socket = _fbp_node_socket(
                getattr(node, "inputs", ()), f"Camera To Source {coefficient_name}"
            )
            if socket is not None and not _fbp_effect_values_equal(
                getattr(socket, "default_value", None), value
            ):
                try:
                    socket.default_value = float(value)
                    changed = True
                except FBP_DATA_ERRORS:
                    pass

    if effect_id == FBP_EFFECT_CLIPPING_MASK and source_rig is not None and not source_is_gp:
        changed = _fbp_sync_clipping_source_effect_inputs(rig, source_rig, node) or changed

    source_opacity_socket = _fbp_node_socket(getattr(node, "inputs", ()), "Source Opacity")
    if source_opacity_socket is not None and not _fbp_effect_values_equal(
        getattr(source_opacity_socket, "default_value", None), source_opacity
    ):
        try:
            source_opacity_socket.default_value = float(source_opacity)
            changed = True
        except FBP_DATA_ERRORS:
            pass

    use_socket_name = str(definition.get("mask_use_socket", "Use Mask Sample") or "Use Mask Sample")
    use_mask = _fbp_node_socket(getattr(node, "inputs", ()), use_socket_name)
    desired = 1.0 if source_image is not None else 0.0
    if use_mask is not None and not _fbp_effect_values_equal(
        getattr(use_mask, "default_value", None), desired
    ):
        try:
            use_mask.default_value = desired
            changed = True
        except FBP_DATA_ERRORS:
            pass
    if group_key is not None:
        if len(_FBP_MASK_SOURCE_SYNC_CACHE) >= 256 and group_key not in _FBP_MASK_SOURCE_SYNC_CACHE:
            _FBP_MASK_SOURCE_SYNC_CACHE.clear()
        _FBP_MASK_SOURCE_SYNC_CACHE[group_key] = signature
    if changed and node_group:
        try:
            node_group.update_tag()
        except FBP_DATA_ERRORS:
            pass
    return bool(source_image), changed


def _fbp_imported_mask_image_nodes(node_group):
    if not node_group:
        return ()
    try:
        return tuple(
            node for node in node_group.nodes
            if bool(node.get("fbp_imported_mask_image_node", False))
        )
    except FBP_DATA_ERRORS:
        return ()


def _fbp_sync_imported_mask_image(rig, node, effect_id=FBP_EFFECT_IMPORTED_MASK):
    """Bind either a file-backed or generated in-memory raster mask image."""
    node_group = getattr(node, "node_tree", None) if node else None
    image_nodes = _fbp_imported_mask_image_nodes(node_group)
    if not image_nodes:
        return False, False

    definition = fbp_effect_definition(effect_id) or {}
    prefix = str(definition.get("imported_mask_prefix", "fbp_imported_mask") or "fbp_imported_mask")
    try:
        source_type = str(getattr(rig, f"{prefix}_source_type", "FILE") or "FILE").upper()
        pointer_image = getattr(rig, f"{prefix}_image", None)
    except FBP_DATA_ERRORS:
        source_type = "FILE"
        pointer_image = None

    image = pointer_image if pointer_image is not None else None
    path = ""
    if image is None or source_type == "FILE":
        try:
            raw_path = str(getattr(rig, f"{prefix}_path", "") or "")
            path = bpy.path.abspath(raw_path) if raw_path else ""
            path = os.path.normcase(os.path.realpath(path)) if path else ""
        except (AttributeError, OSError, TypeError, ValueError):
            path = ""
        image = None
        if path and os.path.isfile(path):
            try:
                image = bpy.data.images.load(path, check_existing=True)
            except (OSError, RuntimeError, ValueError):
                image = None
    try:
        if image is not None and str(image.colorspace_settings.name or "") != "Non-Color":
            # Assigning a colorspace can reset generated image pixel buffers in
            # Blender. Grease Pencil masks are already created as Non-Color, so
            # avoid touching the setting on every structural synchronization.
            image.colorspace_settings.name = "Non-Color"
    except FBP_DATA_ERRORS:
        pass

    # Linear sampling with CLIP blends the border texels with transparent
    # black, which leaves a thin unmasked line where a Grease Pencil stroke
    # runs past the image edge. Generated GP rasters cover the whole image, so
    # their edge texels can be extended instead.
    try:
        extension = "EXTEND" if image is not None and "fbp_gp_mask_bounds" in image else "CLIP"
    except FBP_DATA_ERRORS:
        extension = "CLIP"
    try:
        group_key = _fbp_node_group_cache_key(node_group)
        signature = (
            extension,
            source_type,
            path,
            fbp_obj_runtime_key(image) if image else None,
            tuple(int(value) for value in image.size[:2]) if image else (),
            int(image.get("fbp_gp_mask_frame", -1)) if image else -1,
        )
    except FBP_DATA_ERRORS:
        group_key = None
        signature = (extension, source_type, path, None, (), -1)
    if group_key is not None and _FBP_IMPORTED_MASK_SYNC_CACHE.get(group_key) == signature:
        return bool(image), False

    changed = False
    for image_node in image_nodes:
        try:
            if getattr(image_node, "image", None) is not image:
                image_node.image = image
                changed = True
            if image_node.interpolation != "Linear":
                image_node.interpolation = "Linear"
                changed = True
            if image_node.extension != extension:
                image_node.extension = extension
                changed = True
        except FBP_DATA_ERRORS:
            continue
    use_sample = _fbp_node_socket(getattr(node, "inputs", ()), "Use Mask Sample")
    desired = 1.0 if image is not None else 0.0
    if use_sample is not None and not _fbp_effect_values_equal(
        getattr(use_sample, "default_value", None), desired
    ):
        try:
            use_sample.default_value = desired
            changed = True
        except FBP_DATA_ERRORS:
            pass
    if group_key is not None:
        if len(_FBP_IMPORTED_MASK_SYNC_CACHE) >= 256 and group_key not in _FBP_IMPORTED_MASK_SYNC_CACHE:
            _FBP_IMPORTED_MASK_SYNC_CACHE.clear()
        _FBP_IMPORTED_MASK_SYNC_CACHE[group_key] = signature
    if changed and node_group:
        try:
            node_group.update_tag()
        except FBP_DATA_ERRORS:
            pass
    return bool(image), changed


_FBP_LAYER_BLEND_NODE_TYPES = {
    "MULTIPLY": "MULTIPLY",
    "SCREEN": "SCREEN",
    "OVERLAY": "OVERLAY",
    "DARKEN": "DARKEN",
    "LIGHTEN": "LIGHTEN",
    "COLOR_DODGE": "DODGE",
    "DODGE": "DODGE",
    "COLOR_BURN": "BURN",
    "BURN": "BURN",
    "SOFT_LIGHT": "SOFT_LIGHT",
    "DIFFERENCE": "DIFFERENCE",
    "EXCLUSION": "EXCLUSION",
    "ADD": "ADD",
    "LINEAR_DODGE": "ADD",
    "SUBTRACT": "SUBTRACT",
    "DIVIDE": "DIVIDE",
    "HUE": "HUE",
    "SATURATION": "SATURATION",
    "COLOR": "COLOR",
    "LUMINOSITY": "VALUE",
    "VALUE": "VALUE",
    "LINEAR_LIGHT": "LINEAR_LIGHT",
}


def _fbp_sync_layer_blend_mode(rig, node):
    node_group = getattr(node, "node_tree", None) if node else None
    if not node_group:
        return False
    try:
        mode = str(getattr(rig, "fbp_layer_blend_mode", "MULTIPLY") or "MULTIPLY").upper()
    except FBP_DATA_ERRORS:
        mode = "MULTIPLY"
    hard_light = mode == "HARD_LIGHT"
    blend_type = _FBP_LAYER_BLEND_NODE_TYPES.get(mode, "MULTIPLY")
    changed = False
    try:
        for internal in node_group.nodes:
            if not bool(internal.get("fbp_layer_blend_mix_node", False)):
                continue
            if getattr(internal, "blend_type", None) != blend_type:
                internal.blend_type = blend_type
                changed = True
    except FBP_DATA_ERRORS:
        pass
    hard_socket = _fbp_node_socket(getattr(node, "inputs", ()), "Use Hard Light")
    desired = 1.0 if hard_light else 0.0
    if hard_socket is not None and not _fbp_effect_values_equal(getattr(hard_socket, "default_value", None), desired):
        try:
            hard_socket.default_value = desired
            changed = True
        except FBP_DATA_ERRORS:
            pass
    if changed:
        try:
            node_group.update_tag()
        except FBP_DATA_ERRORS:
            pass
    return changed


def _fbp_object_mask_coord_nodes(node_group):
    if not node_group:
        return ()
    try:
        return tuple(
            node for node in node_group.nodes
            if bool(node.get("fbp_object_mask_coord_node", False))
        )
    except FBP_DATA_ERRORS:
        return ()


def _fbp_object_mask_image_nodes(node_group):
    if not node_group:
        return ()
    try:
        return tuple(
            node for node in node_group.nodes
            if bool(node.get("fbp_object_mask_image_node", False))
        )
    except FBP_DATA_ERRORS:
        return ()


def _fbp_sync_object_mask_helper(rig, effect_id, node, *, create=True):
    definition = fbp_effect_definition(effect_id)
    if not bool(definition.get("object_mask_aware", False)):
        return False, False
    shape = str(definition.get("object_mask_shape", "SQUARE") or "SQUARE")
    pointer_prop = str(definition.get("object_mask_pointer_property", "") or "")
    mask_image = None
    bounds = (-1.0, 1.0, -1.0, 1.0)
    try:
        from .object_masks import (
            ensure_object_mask_helper,
            ensure_object_mask_image,
            find_object_mask_helper,
            object_mask_image_bounds,
        )
        helper = (
            ensure_object_mask_helper(rig, shape, context=bpy.context, select=False)
            if create else find_object_mask_helper(rig, shape)
        )
        if helper:
            mask_image, bounds, _geometry_changed = ensure_object_mask_image(helper, force=False)
            bounds = object_mask_image_bounds(helper, fallback=bounds)
    except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
        helper = getattr(rig, pointer_prop, None) if pointer_prop else None
    node_group = getattr(node, "node_tree", None) if node else None
    changed = False
    valid = bool(helper and mask_image and node_group)
    for coord in _fbp_object_mask_coord_nodes(node_group):
        try:
            if getattr(coord, "object", None) is not helper:
                coord.object = helper
                changed = True
        except FBP_DATA_ERRORS:
            continue
    for image_node in _fbp_object_mask_image_nodes(node_group):
        try:
            if getattr(image_node, "image", None) is not mask_image:
                image_node.image = mask_image
                changed = True
        except FBP_DATA_ERRORS:
            continue
    for socket_name, value in (
        ("Shape Min X", bounds[0]), ("Shape Max X", bounds[1]),
        ("Shape Min Y", bounds[2]), ("Shape Max Y", bounds[3]),
    ):
        socket = _fbp_node_socket(getattr(node, "inputs", ()), socket_name)
        if socket is None or _fbp_effect_values_equal(getattr(socket, "default_value", None), value):
            continue
        try:
            socket.default_value = float(value)
            changed = True
        except FBP_DATA_ERRORS:
            pass
    use_socket = _fbp_node_socket(getattr(node, "inputs", ()), "Use Mask Object")
    desired = 1.0 if valid else 0.0
    if use_socket is not None and not _fbp_effect_values_equal(getattr(use_socket, "default_value", None), desired):
        try:
            use_socket.default_value = desired
            changed = True
        except FBP_DATA_ERRORS:
            pass
    if changed and node_group:
        try:
            node_group.update_tag()
        except FBP_DATA_ERRORS:
            pass
    return valid, changed


def fbp_refresh_object_mask_binding(rig, effect_id):
    """Refresh only the shader bindings for one edited Shape Mask."""
    changed = False
    for node in _fbp_find_shader_effect_nodes_for_rig(rig, effect_id):
        _valid, node_changed = _fbp_sync_object_mask_helper(rig, effect_id, node, create=False)
        changed = node_changed or changed
    return changed


def fbp_object_mask_binding_issues(
    rig, effect_id, *, helper=None, mask_image=None, bounds=None
):
    """Return structural binding problems for one active editable Shape Mask.

    Supplying the helper/image contract keeps audit-only callers read-only.
    Interactive callers may omit them and use the normal discovery path.
    """
    definition = fbp_effect_definition(effect_id)
    if not bool(definition.get("object_mask_aware", False)):
        return ()
    shape = str(definition.get("object_mask_shape", "SQUARE") or "SQUARE")
    if bounds is None:
        try:
            from .object_masks import (
                find_object_mask_helper,
                object_mask_image,
                object_mask_image_bounds,
            )
            if helper is None:
                helper = find_object_mask_helper(rig, shape)
            if mask_image is None and helper is not None:
                mask_image = object_mask_image(helper)
            bounds = (
                object_mask_image_bounds(helper)
                if helper else (-1.0, 1.0, -1.0, 1.0)
            )
        except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
            helper = None
            mask_image = None
            bounds = (-1.0, 1.0, -1.0, 1.0)
    else:
        bounds = tuple(bounds)

    issues = []
    nodes = tuple(_fbp_find_shader_effect_nodes_for_rig(rig, effect_id))
    if not nodes:
        return ("active Shape Mask shader node is missing",)
    for index, node in enumerate(nodes, start=1):
        node_group = getattr(node, "node_tree", None)
        prefix = f"Shape Mask node {index}" if len(nodes) > 1 else "Shape Mask node"
        if node_group is None:
            issues.append(f"{prefix} has no node group")
            continue
        coord_nodes = _fbp_object_mask_coord_nodes(node_group)
        image_nodes = _fbp_object_mask_image_nodes(node_group)
        if not coord_nodes:
            issues.append(f"{prefix} has no tagged object-coordinate node")
        elif any(getattr(coord, "object", None) is not helper for coord in coord_nodes):
            issues.append(f"{prefix} is bound to the wrong helper object")
        if not image_nodes:
            issues.append(f"{prefix} has no tagged SDF image node")
        elif any(getattr(image_node, "image", None) is not mask_image for image_node in image_nodes):
            issues.append(f"{prefix} is bound to the wrong SDF image")
        use_socket = _fbp_node_socket(getattr(node, "inputs", ()), "Use Mask Object")
        expected_use = 1.0 if helper is not None and mask_image is not None else 0.0
        if use_socket is None:
            issues.append(f"{prefix} has no Use Mask Object input")
        elif not _fbp_effect_values_equal(
            getattr(use_socket, "default_value", None), expected_use
        ):
            issues.append(f"{prefix} has an invalid Use Mask Object state")
        for socket_name, expected in zip(
            ("Shape Min X", "Shape Max X", "Shape Min Y", "Shape Max Y"),
            bounds,
            strict=True,
        ):
            socket = _fbp_node_socket(getattr(node, "inputs", ()), socket_name)
            if socket is None:
                issues.append(f"{prefix} has no {socket_name} input")
            elif not _fbp_effect_values_equal(
                getattr(socket, "default_value", None), float(expected)
            ):
                issues.append(f"{prefix} has stale {socket_name} bounds")
    return tuple(issues)


def fbp_sync_object_mask_bindings(scene=None):
    """Repair active Shape Mask bindings after helper deletion or file load."""
    try:
        from .layers import iter_scene_fbp_rigs
        scene = scene or getattr(bpy.context, "scene", None)
        rigs = tuple(iter_scene_fbp_rigs(scene)) if scene is not None else ()
    except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
        return False
    changed = False
    for rig in rigs:
        for effect_id in (
            FBP_EFFECT_SQUARE_MASK,
            FBP_EFFECT_CIRCLE_MASK,
            FBP_EFFECT_TRIANGLE_MASK,
        ):
            if not fbp_effect_is_active(rig, effect_id):
                continue
            changed = fbp_refresh_object_mask_binding(rig, effect_id) or changed
    # Blender 5.2 Undo may still reference zero-user Image IDs from an older
    # material state. Never delete generated mask images from this automatic
    # timer-driven repair; mark them for explicit Orphan Purge instead.
    try:
        for image in tuple(bpy.data.images):
            if (
                int(getattr(image, "users", 0) or 0) == 0
                and bool(image.get("fbp_is_object_mask_image", False))
            ):
                image["fbp_orphan_candidate"] = True
    except FBP_DATA_ERRORS:
        pass
    return changed


def fbp_schedule_object_mask_binding_sync(scene=None):
    """Coalesce helper deletion/link changes into one safe binding repair."""
    try:
        from .safe_tasks import schedule_once
        scene_name = str(getattr(scene, "name", "") or "")

        def _sync():
            scenes = getattr(bpy.data, "scenes", None)
            target_scene = scenes.get(scene_name) if scene_name and scenes is not None else getattr(bpy.context, "scene", None)
            fbp_sync_object_mask_bindings(target_scene)

        schedule_once("fbp.sync_object_mask_bindings", _sync, first_interval=0.03)
        return True
    except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
        return fbp_sync_object_mask_bindings(scene)


def fbp_sync_clipping_masks(context=None, *, collections=None):
    """Bind active Clipping Masks to the physical layer directly below them.

    ``collections`` limits reorder-driven updates to the affected collection(s),
    avoiding a complete scene-wide shader scan after every Up, Down or Reverse
    action. Load, delete and repair paths continue to call the full-scene mode.
    """
    context = context or bpy.context
    scene = getattr(context, "scene", None)
    if scene is None:
        return False
    try:
        from .layers import (
            fbp_clipping_source_map,
            fbp_immediate_layer_below_map,
            get_primary_fbp_collection,
            iter_fbp_rigs_in_collection,
            iter_scene_fbp_rigs,
        )
        if collections is None:
            collection_scope = None
        else:
            unique_collections = []
            seen_collections = set()
            for collection in tuple(collections or ()):
                if collection is None:
                    continue
                try:
                    collection_key = int(collection.as_pointer())
                except FBP_DATA_ERRORS:
                    continue
                if collection_key in seen_collections:
                    continue
                seen_collections.add(collection_key)
                unique_collections.append(collection)
            collection_scope = tuple(unique_collections)
        if collection_scope is None:
            rigs = tuple(iter_scene_fbp_rigs(scene))
        else:
            scoped_rigs = []
            seen_rigs = set()
            for collection in collection_scope:
                for rig in iter_fbp_rigs_in_collection(collection, recursive=False):
                    try:
                        key = int(rig.as_pointer())
                    except FBP_DATA_ERRORS:
                        continue
                    if key in seen_rigs or get_primary_fbp_collection(rig) != collection:
                        continue
                    seen_rigs.add(key)
                    scoped_rigs.append(rig)
            rigs = tuple(scoped_rigs)
        if collection_scope is not None and not collection_scope:
            return False

        active_rigs = []
        relation_effects = (
            (FBP_EFFECT_CLIPPING_MASK, "fbp_clipping_mask_source"),
            (FBP_EFFECT_LAYER_BLEND, "fbp_layer_blend_source"),
        )
        for rig in rigs:
            has_relation_effect = False
            for relation_effect_id, _source_property in relation_effects:
                definition = fbp_effect_definition(relation_effect_id)
                enabled_key = str(definition.get("enabled_key", "") or "")
                try:
                    enabled_hint = bool(enabled_key and rig.get(enabled_key, False))
                except FBP_DATA_ERRORS:
                    enabled_hint = False
                runtime_active = fbp_effect_is_active(rig, relation_effect_id)
                if runtime_active and enabled_key and not enabled_hint:
                    # Quarantined private groups can survive while their persistent
                    # enabled hint is missing. Repair the hint before resolving
                    # stacked clipping chains, whose source map intentionally
                    # avoids expensive shader scans.
                    try:
                        rig[enabled_key] = True
                        enabled_hint = True
                    except FBP_DATA_ERRORS:
                        pass
                elif enabled_hint and not runtime_active:
                    # A stored enabled flag with a missing node is a recoverable
                    # partial rebuild, not a disabled effect. Restore the small
                    # relation group now while running in the deferred safe task.
                    try:
                        fbp_apply_shader_effect(
                            rig, relation_effect_id, rebuild=True, sync_items=False
                        )
                        runtime_active = fbp_effect_is_active(rig, relation_effect_id)
                    except FBP_DATA_ERRORS:
                        runtime_active = False
                if enabled_hint or runtime_active:
                    has_relation_effect = True
                else:
                    try:
                        if getattr(rig, _source_property, None) is not None:
                            has_relation_effect = True
                    except FBP_DATA_ERRORS:
                        pass
            if has_relation_effect:
                active_rigs.append(rig)
        if not active_rigs:
            return False
        clipping_source_map = fbp_clipping_source_map(
            context,
            rigs=rigs,
            collections=collection_scope,
        )
        blend_source_map = fbp_immediate_layer_below_map(
            context,
            rigs=rigs,
            collections=collection_scope,
        )
    except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
        return False
    changed = False
    relation_effects = (
        (FBP_EFFECT_CLIPPING_MASK, "fbp_clipping_mask_source"),
        (FBP_EFFECT_LAYER_BLEND, "fbp_layer_blend_source"),
    )
    for rig in active_rigs:
        for relation_effect_id, source_property in relation_effects:
            source = (
                clipping_source_map.get(rig)
                if relation_effect_id == FBP_EFFECT_CLIPPING_MASK
                else blend_source_map.get(rig)
            )
            if not fbp_effect_is_active(rig, relation_effect_id):
                # Disabled relations must not retain an apparently live source
                # pointer. Clearing it also prevents stale source references from
                # being serialized and later mistaken for an active chain.
                try:
                    if getattr(rig, source_property, None) is not None:
                        changed = bool(
                            fbp_set_rna_property_silent(rig, source_property, None)
                        ) or changed
                except FBP_DATA_ERRORS:
                    pass
                continue
            try:
                current_source = getattr(rig, source_property, None)
                pointer_changed = bool(
                    current_source is not source
                    and fbp_set_rna_property_silent(rig, source_property, source)
                )
            except FBP_DATA_ERRORS:
                pointer_changed = False
            if pointer_changed:
                changed = True
            relation_nodes = list(
                _fbp_find_shader_effect_nodes_for_rig(rig, relation_effect_id)
            )
            if relation_effect_id == FBP_EFFECT_CLIPPING_MASK:
                needs_rebuild = not relation_nodes
                if not needs_rebuild:
                    for relation_node in relation_nodes:
                        try:
                            relation_group = getattr(relation_node, "node_tree", None)
                            required_contract = int(
                                fbp_effect_definition(FBP_EFFECT_CLIPPING_MASK).get(
                                    "track_matte_contract_version", 10
                                ) or 10
                            )
                            if int(relation_group.get("fbp_track_matte_contract_version", 0) or 0) < required_contract:
                                needs_rebuild = True
                                break
                        except FBP_DATA_ERRORS:
                            needs_rebuild = True
                            break
                if needs_rebuild:
                    fbp_apply_shader_effect(
                        rig,
                        relation_effect_id,
                        rebuild=True,
                        sync_items=False,
                    )
                    relation_nodes = list(
                        _fbp_find_shader_effect_nodes_for_rig(rig, relation_effect_id)
                    )
                    changed = True
            for node in relation_nodes:
                _has_source, node_changed = _fbp_sync_mask_source(rig, relation_effect_id, node)
                if relation_effect_id == FBP_EFFECT_LAYER_BLEND:
                    node_changed = _fbp_sync_layer_blend_mode(rig, node) or node_changed
                changed = node_changed or changed
    return changed


def fbp_layer_relation_status(rig, effect_id):
    """Return a read-only health summary for Layer Blend or Clipping Mask.

    The draw path deliberately avoids rebuilding data or resolving the complete
    collection order. It only validates the persistent relation contract that
    should already have been produced by the deferred synchronizer.
    """
    effect_id = str(effect_id or "").upper()
    if effect_id not in {FBP_EFFECT_CLIPPING_MASK, FBP_EFFECT_LAYER_BLEND}:
        return "UNSUPPORTED", "Unsupported layer relation", "ERROR"
    if rig is None:
        return "INVALID_TARGET", "Layer is no longer available", "ERROR"

    definition = fbp_effect_definition(effect_id)
    enabled_key = str(definition.get("enabled_key", "") or "")
    source_property = str(definition.get("mask_source_property", "") or "")
    try:
        enabled_hint = bool(enabled_key and rig.get(enabled_key, False))
    except FBP_DATA_ERRORS:
        enabled_hint = False
    try:
        runtime_active = bool(fbp_effect_is_active(rig, effect_id))
    except FBP_DATA_ERRORS:
        runtime_active = False
    if not enabled_hint and not runtime_active:
        return "DISABLED", "Relation is disabled", "HIDE_ON"

    try:
        source = getattr(rig, source_property, None) if source_property else None
    except FBP_DATA_ERRORS:
        source = None
    if source is None:
        return "MISSING_SOURCE", "Source layer is missing or still pending", "ERROR"
    if source is rig:
        return "SELF_SOURCE", "Layer cannot use itself as the relation source", "ERROR"

    try:
        from .layers import (
            fbp_layer_has_sampleable_image,
            fbp_layer_is_blend_source,
            get_primary_fbp_collection,
            is_fbp_layer_object,
        )
        try:
            from .grease_pencil_bridge import is_gp_drawing_canvas
        except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
            is_gp_drawing_canvas = lambda _obj: False
        if not (is_fbp_layer_object(source) or is_gp_drawing_canvas(source)):
            return "INVALID_SOURCE", "Source is not a Frame By Plane layer or Drawing Plane", "ERROR"
        target_collection = get_primary_fbp_collection(rig)
        source_collection = get_primary_fbp_collection(source)
        if target_collection is None or source_collection is None or target_collection is not source_collection:
            return "WRONG_COLLECTION", "Source no longer belongs to the same layer collection", "ERROR"
        source_is_valid = (
            fbp_layer_is_blend_source(source)
            if effect_id == FBP_EFFECT_LAYER_BLEND
            else fbp_layer_has_sampleable_image(source)
        )
        if not source_is_valid:
            message = (
                "Layer Blend needs an Image or flat Color frame below"
                if effect_id == FBP_EFFECT_LAYER_BLEND
                else "Source layer has no sampleable image alpha"
            )
            return "UNSAMPLEABLE", message, "ERROR"
    except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
        return "INVALID_SOURCE", "Source layer could not be validated", "ERROR"

    nodes = tuple(_fbp_find_shader_effect_nodes_for_rig(rig, effect_id))
    if not nodes:
        return "MISSING_NODE", "Relation shader node is missing", "ERROR"
    if effect_id == FBP_EFFECT_CLIPPING_MASK:
        required_contract = int(definition.get("track_matte_contract_version", 0) or 0)
        for node in nodes:
            try:
                group = getattr(node, "node_tree", None)
                current_contract = int(group.get("fbp_track_matte_contract_version", 0) or 0) if group else 0
                if group is None or current_contract < required_contract:
                    return "OUTDATED_NODE", "Clipping shader contract needs repair", "FILE_REFRESH"
            except FBP_DATA_ERRORS:
                return "OUTDATED_NODE", "Clipping shader contract needs repair", "FILE_REFRESH"
    elif effect_id == FBP_EFFECT_LAYER_BLEND:
        required_contract = int(
            definition.get("layer_blend_contract_version", 2) or 2
        )
        for node in nodes:
            try:
                group = getattr(node, "node_tree", None)
                current_contract = int(
                    group.get("fbp_layer_blend_contract_version", 0) or 0
                ) if group else 0
                if group is None or current_contract < required_contract:
                    return "OUTDATED_NODE", "Layer Blend shader contract needs repair", "FILE_REFRESH"
            except FBP_DATA_ERRORS:
                return "OUTDATED_NODE", "Layer Blend shader contract needs repair", "FILE_REFRESH"

    source_name = str(getattr(source, "name", "Source Layer") or "Source Layer")
    return "OK", f"Relation ready — source: {source_name}", "CHECKMARK"

def fbp_schedule_clipping_mask_sync(
    scene=None, *, collections=None, camera_change=False
):
    """Coalesce Layer Blend and Clipping Mask source refreshes safely.

    Calls that know which collection changed merge into one scoped refresh.
    Passing ``collections=None`` requests a full active-scene refresh for
    discrete structural or active-camera changes. Continuous camera transforms
    are evaluated by native drivers and must not call this material rebinder.
    Pending scopes are stored separately per Scene so rapid edits in two scenes
    cannot silently replace one another.
    """
    try:
        from .safe_tasks import schedule_once
        scene = scene or getattr(bpy.context, "scene", None)
        scene_name = str(getattr(scene, "name", "") or "")
        scene_runtime_key = fbp_obj_runtime_key(scene)
        pending_key = f"{scene_name}:{scene_runtime_key}" if scene_runtime_key is not None else (scene_name or "__ACTIVE_SCENE__")

        record = _FBP_RELATION_SYNC_PENDING.get(pending_key)
        if not isinstance(record, dict):
            record = {"full": False, "collections": set(), "not_before": 0.0}
            _FBP_RELATION_SYNC_PENDING[pending_key] = record
        if camera_change:
            # Camera transforms can emit dozens of depsgraph updates while the
            # user drags keyframes. Drivers already update projection matrices;
            # this delayed pass is needed only if physical layer order changes.
            record["not_before"] = max(
                float(record.get("not_before", 0.0) or 0.0),
                time.monotonic() + 0.35,
            )
        if collections is None:
            record["full"] = True
            record["collections"] = set()
        elif not bool(record.get("full", False)):
            names = record.setdefault("collections", set())
            if not isinstance(names, set):
                names = set()
                record["collections"] = names
            for collection in tuple(collections or ()):
                try:
                    name = str(getattr(collection, "name", "") or "")
                except FBP_DATA_ERRORS:
                    name = ""
                if name:
                    names.add(name)

        def _sync():
            requested = _FBP_RELATION_SYNC_PENDING.get(pending_key)
            if not isinstance(requested, dict):
                return None
            try:
                remaining = float(requested.get("not_before", 0.0) or 0.0) - time.monotonic()
            except (TypeError, ValueError):
                remaining = 0.0
            if remaining > 0.0:
                return max(0.03, min(0.25, remaining))
            requested = _FBP_RELATION_SYNC_PENDING.pop(pending_key, None)
            if not isinstance(requested, dict):
                return None
            scenes = getattr(bpy.data, "scenes", None)
            target_scene = (
                scenes.get(scene_name)
                if scene_name and scenes is not None else getattr(bpy.context, "scene", None)
            )
            if target_scene is None and scene_runtime_key is not None:
                try:
                    target_scene = next(
                        candidate for candidate in tuple(scenes or ())
                        if fbp_obj_runtime_key(candidate) == scene_runtime_key
                    )
                except (StopIteration, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
                    target_scene = None
            context = bpy.context
            if target_scene is None or getattr(context, "scene", None) is not target_scene:
                return None
            if bool(requested.get("full", False)):
                fbp_sync_clipping_masks(context)
                return None
            requested_names = requested.get("collections", set())
            if not isinstance(requested_names, (set, tuple, list)):
                requested_names = ()
            resolved = tuple(
                collection
                for name in sorted(requested_names)
                for collection in (bpy.data.collections.get(name),)
                if collection is not None
            )
            if resolved:
                fbp_sync_clipping_masks(context, collections=resolved)
            elif requested_names:
                # A collection may have been renamed between the depsgraph
                # update and this safe timer. Fall back to a full refresh rather
                # than leaving one relation bound to a stale source.
                fbp_sync_clipping_masks(context)
            return None

        task_name = f"fbp.sync_layer_relations:{pending_key}"
        schedule_once(
            task_name,
            _sync,
            first_interval=0.12 if camera_change else 0.03,
        )
        return True
    except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
        # Never fall back to material mutation from a depsgraph/message-bus call.
        return False


def fbp_sync_mattes_for_source_bounds(source_rig, scene=None):
    """Refresh track-matte bounds and source image sampling after Crop/Extend."""
    if not source_rig:
        return False
    try:
        from .layers import iter_scene_fbp_rigs
        scene = scene or getattr(bpy.context, "scene", None)
        rigs = tuple(iter_scene_fbp_rigs(scene)) if scene is not None else ()
    except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
        rigs = ()
    changed = False
    contracts = (
        (FBP_EFFECT_ALPHA_MATTE, "fbp_alpha_matte_source"),
        (FBP_EFFECT_LUMA_MATTE, "fbp_luma_matte_source"),
        (FBP_EFFECT_CLIPPING_MASK, "fbp_clipping_mask_source"),
    )
    for target in rigs:
        for effect_id, source_prop in contracts:
            try:
                if getattr(target, source_prop, None) is not source_rig:
                    continue
                # Even when source-transform mapping is disabled, the private
                # matte image node must follow the source Image Texture's Extend
                # mode. Changed-only synchronization keeps Crop slider updates
                # cheap while ensuring Repeat/Mirror/Edge/Transparent propagate.
                for node in _fbp_find_shader_effect_nodes_for_rig(target, effect_id):
                    _has_source, node_changed = _fbp_sync_mask_source(target, effect_id, node)
                    changed = node_changed or changed
            except FBP_DATA_ERRORS:
                continue
    return changed


def _fbp_sync_shader_image_sources(
    rig,
    active_effect_ids=None,
    target_nodes=None,
    scene=None,
):
    """Refresh image-aware shader groups from the evaluated FBP material.

    ``target_nodes`` is the cached ``(material, node, effect_id)`` list produced
    by the runtime profile. The fallback traversal remains available for repair,
    file-load and direct API calls outside the frame handler.
    """
    active = (
        active_effect_ids
        if isinstance(active_effect_ids, (set, frozenset))
        else set(active_effect_ids or FBP_FRAME_SYNC_SHADER_EFFECT_IDS)
    )
    if target_nodes is None:
        resolved_targets = []
        for material in _fbp_plane_materials(rig):
            for node in _fbp_shader_effect_nodes(material):
                effect_id = _fbp_shader_effect_id(node)
                if effect_id in active and effect_id in FBP_FRAME_SYNC_SHADER_EFFECT_IDS:
                    resolved_targets.append((material, node, effect_id))
    else:
        resolved_targets = [
            (material, node, effect_id)
            for material, node, effect_id in (target_nodes or ())
            if effect_id in active and effect_id in FBP_FRAME_SYNC_SHADER_EFFECT_IDS
        ]

    changed = False
    for material, node, _effect_id in resolved_targets:
        try:
            definition = fbp_effect_definition(_effect_id)
            if bool(definition.get("mask_source_aware", False)):
                _has_image, source_changed = _fbp_sync_mask_source(
                    rig, _effect_id, node
                )
            else:
                has_image, source_changed = _fbp_sync_private_shader_source(
                    material, getattr(node, "node_tree", None)
                )
                use_image = _fbp_node_socket(getattr(node, "inputs", ()), "Use Image Sample")
                if use_image is not None:
                    desired = 1.0 if has_image else 0.0
                    if not _fbp_effect_values_equal(getattr(use_image, "default_value", None), desired):
                        use_image.default_value = desired
                        source_changed = True
            if bool(definition.get("uses_source_texel", False)):
                source_changed = _fbp_sync_source_texel_inputs(
                    rig, node, material=material
                ) or source_changed
            if _effect_id == FBP_EFFECT_DEPTH_BLUR:
                source_changed = _fbp_sync_depth_blur_runtime_inputs(
                    rig, node, material=material, scene=scene
                ) or source_changed
            changed = source_changed or changed
        except FBP_DATA_ERRORS:
            continue
    return changed


def _fbp_owned_shader_group(rig, material, effect_id, source_group, current=None):
    """Return a stable private shader group for image- or rig-owned state.

    Retired groups are re-adopted for the same owner/effect contract. This keeps
    Undo-safe IDs alive without creating one zero-user copy per add/remove cycle.
    """
    if not material or not source_group:
        return source_group
    effect_id = fbp_normalize_effect_id(effect_id)
    definition = fbp_effect_definition(effect_id)
    # Explicit node editing is a user customization boundary. Preserve an
    # editable per-layer copy even for lightweight effects that normally share
    # the canonical generated group.
    if current is not None:
        try:
            editable_owner = str(current.get("fbp_user_editable_owner", "") or "")
            rig_name = str(
                getattr(rig, "name_full", getattr(rig, "name", "")) or ""
            )
            if (
                bool(current.get("fbp_user_editable_effect_group", False))
                and fbp_normalize_effect_id(current.get("fbp_effect_id", "")) == effect_id
                and editable_owner == rig_name
                and _builtin_group_is_complete(current, definition)
            ):
                return current
        except FBP_DATA_ERRORS:
            pass
    if not bool(definition.get("private_group", False)):
        return source_group
    if bool(definition.get("image_aware", False)):
        source_node = _fbp_shader_image_node(material)
        if source_node is None or getattr(source_node, "image", None) is None:
            return source_group

    rig_private = bool(definition.get("rig_private_group", False))
    owner_object = rig if rig_private else material
    owner = str(getattr(owner_object, "name_full", getattr(owner_object, "name", "")) or "")
    owner_kind = "RIG" if rig_private else "MATERIAL"
    owner_id = (
        _fbp_effect_stack_owner_id(rig)
        if rig_private
        else _fbp_private_material_owner_id(rig, material)
    )
    asset_id = str(definition.get("asset_id", "") or "")
    desired_name = f"{source_group.name} • {owner}"

    def matches(candidate):
        if not candidate:
            return False
        try:
            stored_owner = str(
                candidate.get("fbp_effect_private_owner", "")
                or candidate.get("fbp_effect_material_owner", "")
                or ""
            )
            stored_kind = str(candidate.get("fbp_effect_private_owner_kind", "") or "")
            stored_owner_id = str(
                candidate.get(FBP_PRIVATE_EFFECT_OWNER_ID_KEY, "") or ""
            )
            owner_matches = (
                stored_owner_id == owner_id if stored_owner_id else stored_owner == owner
            )
            tagged_effect = fbp_normalize_effect_id(candidate.get("fbp_effect_id", ""))
            tagged_asset = str(candidate.get("fbp_effect_asset_id", "") or "")
            current_match = tagged_effect == effect_id and tagged_asset == asset_id
            quarantined_recovery = bool(candidate.get("fbp_quarantined", False)) and str(
                getattr(candidate, "name", "") or ""
            ).startswith(desired_name)
            return (
                bool(candidate.get("fbp_private_effect_group", False))
                and owner_matches
                and (not stored_kind or stored_kind == owner_kind)
                and (current_match or quarantined_recovery)
                and _builtin_group_is_complete(candidate, definition)
            )
        except FBP_DATA_ERRORS:
            return False

    candidate = current if matches(current) else None
    if candidate is None:
        for item in tuple(bpy.data.node_groups):
            if matches(item):
                candidate = item
                break
    if candidate is not None:
        if bool(candidate.get("fbp_quarantined", False)):
            candidate = _fbp_reactivate_private_effect_group(
                candidate,
                effect_id=effect_id,
                asset_id=asset_id,
                owner=owner,
                owner_id=owner_id,
                owner_kind=owner_kind,
                desired_name=desired_name,
            )
        if candidate is not None:
            _fbp_refresh_private_effect_group_identity(
                candidate,
                owner=owner,
                owner_id=owner_id,
                owner_kind=owner_kind,
                desired_name=desired_name,
            )
            return candidate

    try:
        private = source_group.copy()
        private.name = desired_name
        private.use_fake_user = False
        private["fbp_private_effect_group"] = True
        private["fbp_effect_id"] = effect_id
        private["fbp_effect_asset_id"] = asset_id
        private["fbp_effect_schema_version"] = FBP_EFFECT_SCHEMA_VERSION
        private["fbp_effect_private_owner"] = owner
        private[FBP_PRIVATE_EFFECT_OWNER_ID_KEY] = owner_id
        private["fbp_effect_private_owner_kind"] = owner_kind
        # Preserve the effect-level key as the current single-instance mirror.
        private["fbp_effect_material_owner"] = owner
        fbp_tidy_effect_group(private, effect_id)
        return private
    except FBP_DATA_ERRORS as exc:
        fbp_warn(f"Could not create private {definition.get('label', effect_id)} shader group", exc)
        return source_group

def _fbp_remove_unused_effect_group(node_group, keep=None):
    """Remove an unreferenced Frame by Plane node-group copy safely."""
    if not node_group or node_group == keep:
        return False
    try:
        if getattr(node_group, "library", None):
            return False
        tagged = bool(
            node_group.get("fbp_effect_id", "")
            or node_group.get("fbp_effect_asset_id", "")
            or node_group.get("fbp_shader_effect_id", "")
            or node_group.get("fbp_geometry_effect_id", "")
        )
        if not tagged:
            return False
        fake_user = bool(getattr(node_group, "use_fake_user", False))
        real_users = int(getattr(node_group, "users", 0) or 0) - int(fake_user)
        if real_users > 0:
            return False
        if fake_user:
            node_group.use_fake_user = False
        _fbp_remove_node_group(node_group)
        return True
    except FBP_DATA_ERRORS:
        return False


def _fbp_canonical_shader_effect_node(material, effect_id, node_group):
    """Return one canonical shader node and collapse duplicate nodes."""
    definition = fbp_effect_definition(effect_id)
    nodes = _fbp_shader_effect_nodes(material, effect_id=effect_id)
    if not nodes:
        return None, False

    if str(definition.get("instance_policy", "SINGLE") or "SINGLE").upper() == "MULTI":
        # MULTI effects intentionally retain repeated concrete nodes. Repair the
        # first matching node without collapsing its siblings.
        node = nodes[0]
        changed = False
        previous_group = getattr(node, "node_tree", None)
        if previous_group != node_group and node_group is not None:
            try:
                node.node_tree = node_group
                changed = True
            except FBP_DATA_ERRORS:
                pass
        try:
            node.label = str(definition.get("label", effect_id))
            node["fbp_shader_effect_id"] = effect_id
            ensure_effect_instance_id(node, effect_id)
        except FBP_DATA_ERRORS:
            pass
        return node, changed

    desired_asset = str(definition.get("asset_id", "") or "")

    def _priority(node):
        current_group = getattr(node, "node_tree", None)
        if current_group == node_group:
            return 0
        try:
            if str(current_group.get("fbp_effect_asset_id", "") or "") == desired_asset:
                return 1
        except FBP_DATA_ERRORS:
            pass
        return 2

    node = min(nodes, key=_priority)
    changed = False
    duplicate_groups = []
    for duplicate in list(nodes):
        if duplicate == node:
            continue
        duplicate_groups.append(getattr(duplicate, "node_tree", None))
        try:
            material.node_tree.nodes.remove(duplicate)
            changed = True
        except FBP_DATA_ERRORS:
            pass

    previous_group = getattr(node, "node_tree", None)
    if previous_group != node_group:
        try:
            node.node_tree = node_group
            changed = True
        except FBP_DATA_ERRORS:
            pass
    try:
        node.label = str(definition.get("label", effect_id))
        node["fbp_shader_effect_id"] = effect_id
        ensure_effect_instance_id(node, effect_id)
    except FBP_DATA_ERRORS:
        pass

    for old_group in duplicate_groups + [previous_group]:
        _fbp_remove_unused_effect_group(old_group, keep=node_group)
    return node, changed


def fbp_apply_shader_effect(rig, effect_id, *, rebuild=True, sync_items=True):
    effect_id = fbp_normalize_effect_id(effect_id)
    definition = fbp_effect_definition(effect_id)
    if definition.get("kind") != "SHADER":
        return False
    node_group = _fbp_load_effect_group(effect_id)
    if not node_group:
        return False
    materials = [
        mat for mat in _fbp_plane_materials(rig)
        if not bool(mat.get("fbp_holdout_material", False))
        and _fbp_material_color_source(mat, create=True) is not None
    ]
    if not materials:
        return False

    changed = False
    for material in materials:
        try:
            material["fbp_effect_rig_owner"] = str(getattr(rig, "name_full", getattr(rig, "name", "")) or "")
        except FBP_DATA_ERRORS:
            pass
        existing_nodes = _fbp_shader_effect_nodes(material, effect_id=effect_id)
        current_group = getattr(existing_nodes[0], "node_tree", None) if existing_nodes else None
        material_group = _fbp_owned_shader_group(
            rig, material, effect_id, node_group, current=current_group
        )
        node, repaired = _fbp_canonical_shader_effect_node(
            material, effect_id, material_group
        )
        changed = repaired or changed
        if node is None:
            try:
                node = material.node_tree.nodes.new("ShaderNodeGroup")
                node.node_tree = material_group
                node.name = f"FBP Effect • {definition.get('label', effect_id)}"
                node.label = str(definition.get("label", effect_id))
                node["fbp_shader_effect_id"] = effect_id
                ensure_effect_instance_id(node, effect_id)
                changed = True
            except FBP_DATA_ERRORS as exc:
                fbp_warn("Could not add shader effect node", exc)
                continue
        try:
            node_instance_id = effect_instance_id(node)
            storage_id = (
                effect_instance_token(effect_id, node_instance_id)
                if node_instance_id and str(definition.get("instance_policy", "SINGLE") or "SINGLE").upper() == "MULTI"
                else effect_id
            )
            muted = not _fbp_stored_effect_visibility(rig, storage_id, True)
            if bool(getattr(node, "mute", False)) != muted:
                node.mute = muted
                changed = True
        except FBP_DATA_ERRORS:
            pass
        stage = str(definition.get("stage", ""))
        order = _fbp_get_rig_shader_stage_order(rig, stage) or _fbp_get_shader_stage_order(material, stage)
        for active_id in _fbp_get_shader_stage_order(material, stage):
            if active_id not in order:
                order.append(active_id)
        node_token = _fbp_shader_node_token(node)
        order_key = (
            node_token
            if str(definition.get("instance_policy", "SINGLE") or "SINGLE").upper() == "MULTI"
            else effect_id
        )
        if order_key not in order:
            order.append(order_key)
        _fbp_set_rig_shader_stage_order(rig, stage, order)
        _fbp_set_shader_stage_order(material, stage, order)
        changed = _fbp_set_shader_node_values(rig, effect_id, node) or changed
        if rebuild:
            changed = _fbp_rebuild_shader_stage(material, stage) or changed
    _fbp_set_enabled(rig, effect_id, True)
    # MULTI instances keep their own groups; an effect-wide assignment would
    # pull every copy into the group of one of them.
    stored_group = (
        "" if _fbp_effect_uses_multi_instances(effect_id)
        else _fbp_stored_effect_group_id(rig, effect_id)
    )
    if stored_group:
        fbp_set_effect_group_id(rig, effect_id, stored_group)
    _fbp_invalidate_effect_ids_cache(rig)
    _fbp_refresh_geometry_source_materials(rig)
    if sync_items:
        fbp_sync_effect_items(rig)
    return changed or bool(materials)



def _fbp_copy_socket_default(source, target):
    """Copy one socket ``default_value`` only when it differs.

    Skipping identical writes avoids tagging the material for re-evaluation
    every time a composite or duplicate is refreshed from its source.
    """
    value = source.default_value
    if hasattr(value, "__len__") and not isinstance(value, str):
        value = tuple(value)
        current = tuple(target.default_value)
    else:
        current = target.default_value
    if current == value:
        return False
    target.default_value = value
    return True


def _fbp_copy_shader_instance_inputs(source_node, target_node):
    """Copy editable group-node input values without copying links."""
    if source_node is None or target_node is None:
        return False
    changed = False
    for target, source in _fbp_paired_sockets(
        getattr(source_node, "inputs", ()), getattr(target_node, "inputs", ())
    ):
        try:
            changed = _fbp_copy_socket_default(source, target) or changed
        except FBP_DATA_ERRORS:
            continue
    return changed


_FBP_INSTANCE_CHANNEL_VALUE_ATTRS = {
    "FLOAT": "float_value",
    "POSITIVE": "positive_value",
    "FACTOR": "factor_value",
    "ANGLE": "angle_value",
    "INT": "int_value",
    "BOOL": "bool_value",
}


def _fbp_instance_channel_value_attr(channel):
    return _FBP_INSTANCE_CHANNEL_VALUE_ATTRS.get(
        str(getattr(channel, "value_kind", "FLOAT") or "FLOAT").upper(),
        "float_value",
    )


def fbp_effect_instance_channel_value(channel):
    if channel is None:
        return None
    try:
        return getattr(channel, _fbp_instance_channel_value_attr(channel))
    except FBP_DATA_ERRORS:
        return None


def _fbp_effect_instance_channel_kind(rig, prop_name):
    try:
        rna = getattr(getattr(rig, "bl_rna", None), "properties", None)
        prop = rna.get(str(prop_name or "")) if rna is not None else None
        prop_type = str(getattr(prop, "type", "FLOAT") or "FLOAT").upper()
        subtype = str(getattr(prop, "subtype", "") or "").upper()
        hard_min = float(getattr(prop, "hard_min", -1000000.0))
        hard_max = float(getattr(prop, "hard_max", 1000000.0))
    except FBP_DATA_ERRORS:
        return "FLOAT"
    if prop_type == "BOOLEAN":
        return "BOOL"
    if prop_type == "INT":
        return "INT"
    if subtype == "ANGLE":
        return "ANGLE"
    if subtype == "FACTOR" or (hard_min >= 0.0 and hard_max <= 1.0):
        return "FACTOR"
    if hard_min >= 0.0:
        return "POSITIVE"
    return "FLOAT"


def _fbp_effect_instance_channel_identity(channel):
    try:
        return (
            fbp_normalize_effect_id(getattr(channel, "effect_id", "")),
            str(getattr(channel, "instance_id", "") or ""),
            str(getattr(channel, "property_name", "") or ""),
        )
    except FBP_DATA_ERRORS:
        return ("", "", "")


def fbp_effect_instance_channel(
    rig, effect_id, instance_id, prop_name, *, ensure=False, source_instance_id="",
    prefer_node=False,
):
    """Return one stable keyframe channel without reordering the collection."""
    if rig is None or not hasattr(rig, "fbp_effect_instance_channels"):
        return None
    effect_id = fbp_normalize_effect_id(effect_id)
    instance_id = str(instance_id or "")
    prop_name = str(prop_name or "")
    if not effect_id or not instance_id or not prop_name:
        return None
    inactive = None
    for channel in getattr(rig, "fbp_effect_instance_channels", ()):
        if _fbp_effect_instance_channel_identity(channel) != (effect_id, instance_id, prop_name):
            continue
        if bool(getattr(channel, "active", True)):
            return channel
        inactive = channel
        break
    if not ensure:
        return None
    definition = fbp_effect_definition(effect_id)
    socket_name = str((definition.get("property_map", {}) or {}).get(prop_name, "") or "")
    if not socket_name:
        return None
    channel = inactive or rig.fbp_effect_instance_channels.add()
    channel.active = True
    channel.effect_id = effect_id
    channel.instance_id = instance_id
    channel.property_name = prop_name
    channel.socket_name = socket_name
    channel.value_kind = _fbp_effect_instance_channel_kind(rig, prop_name)

    value = None
    if source_instance_id:
        source = fbp_effect_instance_channel(
            rig, effect_id, source_instance_id, prop_name, ensure=False
        )
        value = fbp_effect_instance_channel_value(source)
    if value is None and prefer_node:
        nodes = _fbp_find_shader_effect_nodes_for_rig(
            rig, effect_id, instance_id=instance_id
        )
        socket = _fbp_node_socket(getattr(nodes[0], "inputs", ()), socket_name) if nodes else None
        try:
            value = getattr(socket, "default_value") if socket is not None else None
        except FBP_DATA_ERRORS:
            value = None
    if value is None:
        try:
            value = getattr(rig, prop_name)
        except FBP_DATA_ERRORS:
            value = 0
    attr = _fbp_instance_channel_value_attr(channel)
    if str(getattr(channel, "value_kind", "")) == "INT":
        value = int(round(float(value)))
    elif str(getattr(channel, "value_kind", "")) == "BOOL":
        value = bool(value)
    else:
        value = float(value)
    fbp_set_rna_property_silent(channel, attr, value)
    return channel


def fbp_ensure_effect_instance_channels(
    rig, effect_id, instance_id, *, source_instance_id="", prefer_node=False,
):
    effect_id = fbp_normalize_effect_id(effect_id)
    definition = fbp_effect_definition(effect_id)
    if (
        rig is None or not instance_id
        or str(definition.get("instance_policy", "SINGLE") or "SINGLE").upper() != "MULTI"
        or definition.get("kind") != "SHADER"
    ):
        return ()
    speed_prop = str(definition.get("evolve_speed_property", "") or "")
    channels = []
    for prop_name in (definition.get("property_map", {}) or {}):
        if prop_name == speed_prop:
            continue
        channel = fbp_effect_instance_channel(
            rig, effect_id, instance_id, prop_name, ensure=True,
            source_instance_id=source_instance_id, prefer_node=prefer_node,
        )
        if channel is not None:
            channels.append(channel)
    return tuple(channels)


def fbp_effect_instance_animation_item(
    rig, effect_id, instance_id, *, ensure=False, source_instance_id="",
):
    if rig is None or not hasattr(rig, "fbp_effect_instance_animations"):
        return None
    effect_id = fbp_normalize_effect_id(effect_id)
    instance_id = str(instance_id or "")
    definition = fbp_effect_definition(effect_id)
    if not instance_id or not definition.get("evolve_property"):
        return None
    inactive = None
    for item in getattr(rig, "fbp_effect_instance_animations", ()):
        try:
            identity = (
                fbp_normalize_effect_id(getattr(item, "effect_id", "")),
                str(getattr(item, "instance_id", "") or ""),
            )
        except FBP_DATA_ERRORS:
            continue
        if identity != (effect_id, instance_id):
            continue
        if bool(getattr(item, "active", True)):
            return item
        inactive = item
        break
    if not ensure:
        return None
    item = inactive or rig.fbp_effect_instance_animations.add()
    item.active = True
    item.effect_id = effect_id
    item.instance_id = instance_id
    source = (
        fbp_effect_instance_animation_item(
            rig, effect_id, source_instance_id, ensure=False
        )
        if source_instance_id else None
    )
    state = (
        {name: getattr(source, name) for name in (
            "evolve", "speed", "step", "seed", "unique", "layer_seed", "amount"
        )}
        if source is not None else fbp_read_effect_animation_state(rig, effect_id)
    )
    defaults = _fbp_effect_animation_defaults(definition)
    for name in ("evolve", "speed", "step", "seed", "unique", "layer_seed", "amount"):
        default = defaults.get(name, (False if name in {"evolve", "unique"} else 0,))[0]
        value = state.get(name, default)
        fbp_set_rna_property_silent(item, name, value)
    return item


def fbp_read_effect_instance_animation_state(rig, effect_id, instance_id):
    item = fbp_effect_instance_animation_item(
        rig, effect_id, instance_id, ensure=False
    )
    if item is None or not bool(getattr(item, "active", True)):
        return {}
    result = {}
    for name in ("evolve", "speed", "step", "seed", "unique", "layer_seed", "amount"):
        try:
            result[name] = getattr(item, name)
        except FBP_DATA_ERRORS:
            pass
    return result


def fbp_ensure_effect_instance_state(
    rig, effect_id, instance_id, *, source_instance_id="", prefer_node=False,
):
    channels = fbp_ensure_effect_instance_channels(
        rig, effect_id, instance_id, source_instance_id=source_instance_id,
        prefer_node=prefer_node,
    )
    animation = fbp_effect_instance_animation_item(
        rig, effect_id, instance_id, ensure=True,
        source_instance_id=source_instance_id,
    )
    _fbp_invalidate_effect_runtime_profile(rig)
    return channels, animation


def _fbp_copy_effect_instance_fcurve(rig, source_owner, source_prop, target_owner, target_prop):
    """Copy scalar keyframes while preserving stable collection-owned paths."""
    if rig is None or source_owner is None or target_owner is None:
        return False
    try:
        source_path = str(source_owner.path_from_id(source_prop) or "")
        target_path = str(target_owner.path_from_id(target_prop) or "")
    except FBP_DATA_ERRORS:
        return False
    if not source_path or not target_path or source_path == target_path:
        return False
    source_curve = fbp_find_action_fcurve(rig, source_path)
    if source_curve is None:
        return False
    fbp_remove_action_fcurves(rig, target_path)
    try:
        restore_value = getattr(target_owner, target_prop)
    except FBP_DATA_ERRORS:
        restore_value = None
    copied = False
    try:
        for key in tuple(getattr(source_curve, "keyframe_points", ()) or ()):
            fbp_set_rna_property_silent(target_owner, target_prop, float(key.co.y))
            rig.keyframe_insert(data_path=target_path, frame=float(key.co.x))
        target_curve = fbp_find_action_fcurve(rig, target_path)
        if target_curve is not None:
            source_keys = tuple(getattr(source_curve, "keyframe_points", ()) or ())
            target_keys = tuple(getattr(target_curve, "keyframe_points", ()) or ())
            for source_key, target_key in zip(source_keys, target_keys, strict=False):
                for attribute in (
                    "interpolation", "easing", "handle_left_type", "handle_right_type",
                    "amplitude", "back", "period",
                ):
                    try:
                        setattr(target_key, attribute, getattr(source_key, attribute))
                    except FBP_DATA_ERRORS:
                        continue
                try:
                    target_key.handle_left = tuple(source_key.handle_left)
                    target_key.handle_right = tuple(source_key.handle_right)
                except FBP_DATA_ERRORS:
                    pass
            try:
                target_curve.color_mode = source_curve.color_mode
                target_curve.extrapolation = source_curve.extrapolation
                target_curve.update()
            except FBP_DATA_ERRORS:
                pass
        copied = True
    except FBP_DATA_ERRORS as exc:
        fbp_warn(
            "Could not duplicate effect-instance keyframes",
            exc,
            event="effects.instance.animation.copy",
        )
        fbp_remove_action_fcurves(rig, target_path)
    finally:
        if restore_value is not None:
            fbp_set_rna_property_silent(target_owner, target_prop, restore_value)
    return copied


def fbp_copy_effect_instance_animation(rig, effect_id, source_instance_id, target_instance_id):
    """Copy parameter and procedural keyframes to a new concrete instance."""
    effect_id = fbp_normalize_effect_id(effect_id)
    source_instance_id = str(source_instance_id or "")
    target_instance_id = str(target_instance_id or "")
    if not source_instance_id or not target_instance_id:
        return False
    changed = False
    definition = fbp_effect_definition(effect_id)
    for prop_name in (definition.get("property_map", {}) or {}):
        source = fbp_effect_instance_channel(
            rig, effect_id, source_instance_id, prop_name, ensure=False
        )
        target = fbp_effect_instance_channel(
            rig, effect_id, target_instance_id, prop_name, ensure=False
        )
        if source is None or target is None:
            continue
        changed = _fbp_copy_effect_instance_fcurve(
            rig,
            source,
            _fbp_instance_channel_value_attr(source),
            target,
            _fbp_instance_channel_value_attr(target),
        ) or changed
    source_animation = fbp_effect_instance_animation_item(
        rig, effect_id, source_instance_id, ensure=False
    )
    target_animation = fbp_effect_instance_animation_item(
        rig, effect_id, target_instance_id, ensure=False
    )
    if source_animation is not None and target_animation is not None:
        for prop_name in ("evolve", "speed", "step", "seed", "unique", "amount"):
            changed = _fbp_copy_effect_instance_fcurve(
                rig, source_animation, prop_name, target_animation, prop_name
            ) or changed
    if changed:
        _fbp_invalidate_effect_runtime_profile(rig)
    return changed


def fbp_retire_effect_instance_state(rig, effect_id, instance_id):
    changed = False
    effect_id = fbp_normalize_effect_id(effect_id)
    instance_id = str(instance_id or "")
    for channel in getattr(rig, "fbp_effect_instance_channels", ()):
        if _fbp_effect_instance_channel_identity(channel)[:2] == (effect_id, instance_id):
            try:
                fbp_remove_action_fcurves(
                    rig, channel.path_from_id(_fbp_instance_channel_value_attr(channel))
                )
            except FBP_DATA_ERRORS:
                pass
            changed = fbp_set_rna_property_silent(channel, "active", False) or changed
    for item in getattr(rig, "fbp_effect_instance_animations", ()):
        try:
            matches = (
                fbp_normalize_effect_id(getattr(item, "effect_id", "")) == effect_id
                and str(getattr(item, "instance_id", "") or "") == instance_id
            )
        except FBP_DATA_ERRORS:
            matches = False
        if matches:
            for prop_name in ("evolve", "speed", "step", "seed", "unique", "amount"):
                try:
                    fbp_remove_action_fcurves(rig, item.path_from_id(prop_name))
                except FBP_DATA_ERRORS:
                    continue
            changed = fbp_set_rna_property_silent(item, "active", False) or changed
    if changed:
        _fbp_invalidate_effect_runtime_profile(rig)
    return changed


def _fbp_apply_effect_instance_channel(rig, channel, *, scene=None):
    if rig is None or channel is None or not bool(getattr(channel, "active", True)):
        return False
    effect_id, instance_id, prop_name = _fbp_effect_instance_channel_identity(channel)
    definition = fbp_effect_definition(effect_id)
    if not effect_id or not instance_id or definition.get("kind") != "SHADER":
        return False
    socket_name = str(getattr(channel, "socket_name", "") or "")
    value = fbp_effect_instance_channel_value(channel)
    changed = False
    for node in _fbp_find_shader_effect_nodes_for_rig(
        rig, effect_id, instance_id=instance_id
    ):
        socket = _fbp_node_socket(getattr(node, "inputs", ()), socket_name)
        if socket is None:
            continue
        runtime_value = _fbp_effect_runtime_value(
            rig, effect_id, prop_name, value, scene=scene, node=node
        )
        runtime_value = _fbp_cast_effect_value(prop_name, runtime_value)
        if _fbp_effect_values_equal(getattr(socket, "default_value", None), runtime_value):
            continue
        try:
            socket.default_value = runtime_value
            changed = True
        except FBP_DATA_ERRORS:
            continue
    if changed:
        try:
            plane = _fbp_plane(rig)
            if plane is not None:
                plane.update_tag()
        except FBP_DATA_ERRORS:
            pass
    return changed


def update_effect_instance_channel_cb(self, context):
    rig = getattr(self, "id_data", None)
    if rig is None or fbp_is_silent_property_update(self):
        return False
    changed = _fbp_apply_effect_instance_channel(
        rig, self, scene=getattr(context, "scene", None) if context else None
    )
    effect_id, instance_id, prop_name = _fbp_effect_instance_channel_identity(self)
    if (
        fbp_active_effect_id(rig) == effect_id
        and fbp_active_effect_instance_id(rig) == instance_id
        and hasattr(rig, prop_name)
    ):
        fbp_set_rna_property_silent(
            rig, prop_name, fbp_effect_instance_channel_value(self)
        )
    _fbp_invalidate_effect_runtime_profile(rig)
    return changed


def update_effect_instance_animation_setting_cb(self, context, suffix):
    rig = getattr(self, "id_data", None)
    if rig is None or fbp_is_silent_property_update(self):
        return False
    effect_id = fbp_normalize_effect_id(getattr(self, "effect_id", ""))
    instance_id = str(getattr(self, "instance_id", "") or "")
    definition = fbp_effect_definition(effect_id)
    if not effect_id or not instance_id or not bool(getattr(self, "active", True)):
        return False
    if fbp_active_effect_id(rig) == effect_id and fbp_active_effect_instance_id(rig) == instance_id:
        editor_key = (
            _fbp_effect_evolution_speed_property(effect_id, definition)
            if suffix == "speed" else _fbp_animation_key(effect_id, suffix)
        )
        if hasattr(rig, editor_key):
            fbp_set_rna_property_silent(rig, editor_key, getattr(self, suffix))
    property_names = {str(definition.get("evolve_property", "") or "")}
    speed_prop = str(definition.get("evolve_speed_property", "") or "")
    if suffix == "speed" and speed_prop:
        property_names.add(speed_prop)
    property_names.discard("")
    changed = fbp_update_shader_effect(
        rig, effect_id, scene=getattr(context, "scene", None) if context else None,
        property_names=property_names or None, instance_id=instance_id,
    )
    _fbp_invalidate_effect_runtime_profile(rig)
    return changed


def fbp_load_effect_instance_settings(rig, effect_id, instance_id):
    """Load one concrete shader instance into its stable editor channels."""
    effect_id = fbp_normalize_effect_id(effect_id)
    instance_id = str(instance_id or "")
    definition = fbp_effect_definition(effect_id)
    if definition.get("kind") != "SHADER" or not instance_id:
        return False
    nodes = _fbp_find_shader_effect_nodes_for_rig(rig, effect_id, instance_id)
    if not nodes:
        return False
    channels, animation = fbp_ensure_effect_instance_state(
        rig, effect_id, instance_id, prefer_node=True
    )
    changed = False
    by_property = {
        str(getattr(channel, "property_name", "") or ""): channel
        for channel in channels
    }
    for prop_name in (definition.get("property_map", {}) or {}):
        channel = by_property.get(prop_name)
        if channel is None or not hasattr(rig, prop_name):
            continue
        value = fbp_effect_instance_channel_value(channel)
        changed = fbp_set_rna_property_silent(rig, prop_name, value) or changed
    if animation is not None:
        speed_prop = _fbp_effect_evolution_speed_property(effect_id, definition)
        if hasattr(rig, speed_prop):
            changed = fbp_set_rna_property_silent(
                rig, speed_prop, getattr(animation, "speed", 1.0)
            ) or changed
        for suffix in ("evolve", "step", "seed", "unique", "layer_seed", "amount"):
            key = _fbp_animation_key(effect_id, suffix)
            if hasattr(rig, key):
                changed = fbp_set_rna_property_silent(
                    rig, key, getattr(animation, suffix)
                ) or changed
    return changed


def fbp_load_active_effect_instance_settings(rig):
    """Refresh shared editor controls from the active concrete MULTI row."""
    effect_id = fbp_active_effect_id(rig)
    instance_id = fbp_active_effect_instance_id(rig)
    if not effect_id or not instance_id or not _fbp_effect_uses_multi_instances(effect_id):
        return False
    return fbp_load_effect_instance_settings(rig, effect_id, instance_id)


def _fbp_rollback_effect_duplicate_transaction(
    rig, effect_id, instance_id, stage, created, material_orders, rig_order, sync_items
):
    """Restore the exact shader stack after an interrupted duplication."""
    token = effect_instance_token(effect_id, instance_id)
    for material, node in reversed(tuple(created or ())):
        try:
            nodes = getattr(getattr(material, "node_tree", None), "nodes", None)
            if nodes is not None and node in nodes:
                nodes.remove(node)
        except FBP_DATA_ERRORS:
            pass
    for material, old_order in tuple(material_orders or ()):
        _fbp_set_shader_stage_order(material, stage, list(old_order or ()))
        _fbp_rebuild_shader_stage(material, stage)
    _fbp_set_rig_shader_stage_order(rig, stage, list(rig_order or ()))
    _fbp_clear_effect_visibility(rig, token)
    _fbp_clear_effect_render_visibility(rig, token)
    _fbp_clear_effect_input_source(rig, effect_id, instance_id)
    fbp_retire_effect_instance_state(rig, effect_id, instance_id)
    _fbp_invalidate_effect_ids_cache(rig)
    fbp_effect_instance_records_for_rig(rig, ensure=True, sync_storage=True)
    if sync_items:
        fbp_sync_effect_items(rig)
    return True


def fbp_duplicate_effect_instance(
    rig, effect_id, source_instance_id="", *, sync_items=True
):
    """Duplicate one supported MULTI shader effect atomically."""
    effect_id = fbp_normalize_effect_id(effect_id)
    source_instance_id = str(source_instance_id or "")
    definition = fbp_effect_definition(effect_id)
    if (
        definition.get("kind") != "SHADER"
        or not fbp_effect_multi_instance_enabled(effect_id)
    ):
        return ""
    materials = [
        material for material in _fbp_plane_materials(rig)
        if _fbp_shader_effect_nodes(material, effect_id=effect_id)
    ]
    if not materials:
        return ""
    owner_id = _fbp_effect_stack_owner_id(rig, ensure=True)
    new_instance_id = new_effect_instance_id(effect_id)
    created = []
    stage = str(definition.get("stage", "") or "")
    material_orders = [
        (material, tuple(_fbp_get_shader_stage_order(material, stage)))
        for material in materials
    ]
    rig_order_before = tuple(_fbp_get_rig_shader_stage_order(rig, stage))
    try:
        with FBPTransaction(
            f"Duplicate {definition.get('label', effect_id)}",
            kind="EFFECT_DUPLICATE",
            journal_owner=rig,
            context={
                "effect_id": effect_id,
                "instance_id": new_instance_id,
                "source_instance_id": source_instance_id,
            },
        ) as transaction:
            transaction.defer_rollback(
                _fbp_rollback_effect_duplicate_transaction,
                rig, effect_id, new_instance_id, stage, created,
                material_orders, rig_order_before, sync_items,
                label="restore shader effect stack",
            )
            for material_index, material in enumerate(materials):
                transaction.checkpoint(
                    "CREATE_NODE", material_index=material_index, material_count=len(materials)
                )
                sources = _fbp_shader_effect_nodes(
                    material, effect_id=effect_id, instance_id=source_instance_id
                )
                if not sources:
                    sources = _fbp_shader_effect_nodes(material, effect_id=effect_id)
                source = sources[0] if sources else None
                if source is None:
                    raise RuntimeError("Source effect instance is missing")
                node = material.node_tree.nodes.new("ShaderNodeGroup")
                node.node_tree = getattr(source, "node_tree", None) or _fbp_load_effect_group(effect_id)
                node.name = f"FBP Effect • {definition.get('label', effect_id)} • {new_instance_id[-6:]}"
                node.label = str(definition.get("label", effect_id))
                node["fbp_shader_effect_id"] = effect_id
                assign_effect_instance_id(
                    node,
                    effect_id,
                    new_instance_id,
                    f"{owner_id}:{effect_id}:{new_instance_id}",
                )
                _fbp_copy_shader_instance_inputs(source, node)
                try:
                    node.mute = bool(getattr(source, "mute", False))
                except FBP_DATA_ERRORS:
                    pass
                created.append((material, node))

                order = _fbp_get_shader_stage_order(material, stage)
                source_token = _fbp_shader_node_token(source)
                new_token = _fbp_shader_node_token(node)
                order = [token for token in order if token != new_token]
                insert_at = order.index(source_token) + 1 if source_token in order else len(order)
                order.insert(insert_at, new_token)
                _fbp_set_shader_stage_order(material, stage, order)
                _fbp_rebuild_shader_stage(material, stage)

            transaction.checkpoint("UPDATE_STACK")
            rig_order = _fbp_get_rig_shader_stage_order(rig, stage)
            source_token = effect_instance_token(effect_id, source_instance_id) if source_instance_id else ""
            new_token = effect_instance_token(effect_id, new_instance_id)
            rig_order = [token for token in rig_order if token != new_token]
            insert_at = rig_order.index(source_token) + 1 if source_token in rig_order else len(rig_order)
            rig_order.insert(insert_at, new_token)
            _fbp_set_rig_shader_stage_order(rig, stage, rig_order)
            _fbp_set_enabled(rig, effect_id, True)
            source_storage_token = (
                effect_instance_token(effect_id, source_instance_id)
                if source_instance_id else effect_id
            )
            source_visible = all(
                not bool(getattr(node, "mute", False))
                for _material, node in created
            )
            _fbp_store_effect_visibility(rig, new_token, source_visible)
            _fbp_store_effect_render_visibility(
                rig, new_token,
                _fbp_stored_effect_render_visibility(
                    rig, source_storage_token,
                    _fbp_stored_effect_render_visibility(rig, effect_id, True),
                ),
            )
            if definition.get("supports_input_source"):
                fbp_set_effect_input_source(
                    rig,
                    effect_id,
                    fbp_effect_input_source(rig, effect_id, source_instance_id),
                    instance_id=new_instance_id,
                )
            if source_instance_id:
                fbp_ensure_effect_instance_state(
                    rig, effect_id, source_instance_id, prefer_node=True
                )
            fbp_ensure_effect_instance_state(
                rig,
                effect_id,
                new_instance_id,
                source_instance_id=source_instance_id,
                prefer_node=True,
            )
            if source_instance_id:
                fbp_copy_effect_instance_animation(
                    rig, effect_id, source_instance_id, new_instance_id
                )
            _fbp_invalidate_effect_ids_cache(rig)
            # Show the copy directly above its source, as the stage order
            # above already evaluates it; otherwise the visible stack lists
            # it at the bottom and the next reorder would move it there.
            mixed = _fbp_mixed_effect_tokens(rig)
            new_ref = _fbp_effect_ref(effect_id, new_instance_id)
            source_ref = next(
                (
                    token for token in mixed
                    if _fbp_effect_ref_effect_id(token) == effect_id
                    and token != new_ref
                    and (
                        not source_instance_id
                        or _fbp_effect_ref_instance_id(token) == source_instance_id
                    )
                ),
                "",
            )
            desired = _fbp_relative_effect_order(rig, (new_ref,), source_ref, "BEFORE")
            if desired and tuple(desired) != tuple(mixed):
                _fbp_apply_mixed_effect_order(rig, desired)
            # The copy of a group member belongs to the same group.
            source_group_id = fbp_effect_group_id_for_rig(
                rig,
                effect_id,
                instance_id=_fbp_effect_ref_instance_id(source_ref),
                normalize=False,
            ) if source_ref else ""
            if source_group_id:
                fbp_set_effect_group_id(
                    rig, effect_id, source_group_id, instance_id=new_instance_id
                )
                fbp_sync_effect_groups(rig)
            fbp_effect_instance_records_for_rig(rig, ensure=True, sync_storage=True)
            # A mixed Image/Mesh stack needs a stage and composite materials
            # that include the new instance, exactly as after Add Effect.
            _fbp_refresh_mixed_pipeline(rig)
            if sync_items:
                fbp_sync_effect_items(rig)
                try:
                    for index, item in enumerate(rig.fbp_effects):
                        if str(getattr(item, "instance_id", "") or "") == new_instance_id:
                            rig.fbp_effects_index = index
                            break
                except FBP_DATA_ERRORS:
                    pass
            transaction.checkpoint("VALIDATED")
            if len(created) != len(materials):
                raise RuntimeError("Effect duplication did not reach every material")
            transaction.commit()
            return new_instance_id
    except (AttributeError, ReferenceError, RuntimeError, TypeError, ValueError, KeyError, IndexError) as exc:
        fbp_warn(
            "Could not duplicate effect instance",
            exc,
            event="effects.instance.duplicate",
            context={"effect_id": effect_id, "instance_id": new_instance_id},
        )
        return ""


def _fbp_capture_removed_shader_node(material, node):
    inputs = {}
    for socket in tuple(getattr(node, "inputs", ()) or ()):
        if not hasattr(socket, "default_value"):
            continue
        try:
            value = socket.default_value
            if hasattr(value, "__len__") and not isinstance(value, str):
                value = tuple(value)
            inputs[str(getattr(socket, "name", "") or "")] = value
        except FBP_DATA_ERRORS:
            continue
    try:
        location = tuple(node.location)
    except FBP_DATA_ERRORS:
        location = (0.0, 0.0)
    return {
        "material": material,
        "node_tree": getattr(node, "node_tree", None),
        "name": str(getattr(node, "name", "") or ""),
        "label": str(getattr(node, "label", "") or ""),
        "mute": bool(getattr(node, "mute", False)),
        "location": location,
        "width": float(getattr(node, "width", 140.0) or 140.0),
        "inputs": inputs,
    }


def _fbp_rollback_effect_remove_transaction(
    rig,
    effect_id,
    instance_id,
    snapshots,
    material_orders,
    rig_order,
    enabled_before,
    visible_before,
    render_visible_before,
    input_source_before,
    solo_view,
    solo_before,
    group_before,
    group_name_before,
    targeted_masks,
    sync_items,
):
    owner_id = _fbp_effect_stack_owner_id(rig, ensure=True)
    for snapshot in snapshots:
        material = snapshot.get("material")
        tree = getattr(material, "node_tree", None)
        if tree is None:
            continue
        existing = _fbp_shader_effect_nodes(
            material, effect_id=effect_id, instance_id=instance_id
        )
        node = existing[0] if existing else tree.nodes.new("ShaderNodeGroup")
        node.node_tree = snapshot.get("node_tree")
        node.name = snapshot.get("name") or f"FBP Effect • {effect_id}"
        node.label = snapshot.get("label") or str(
            fbp_effect_definition(effect_id).get("label", effect_id)
        )
        node["fbp_shader_effect_id"] = effect_id
        assign_effect_instance_id(
            node,
            effect_id,
            instance_id,
            f"{owner_id}:{effect_id}:{instance_id}",
        )
        try:
            node.mute = bool(snapshot.get("mute", False))
            node.location = tuple(snapshot.get("location", (0.0, 0.0)))
            node.width = float(snapshot.get("width", 140.0) or 140.0)
        except FBP_DATA_ERRORS:
            pass
        for socket_name, value in dict(snapshot.get("inputs", {}) or {}).items():
            socket = _fbp_node_socket(getattr(node, "inputs", ()), socket_name)
            if socket is None or not hasattr(socket, "default_value"):
                continue
            try:
                socket.default_value = value
            except FBP_DATA_ERRORS:
                continue
    stage = str(fbp_effect_definition(effect_id).get("stage", "") or "")
    for material, order in material_orders:
        _fbp_set_shader_stage_order(material, stage, tuple(order))
        _fbp_rebuild_shader_stage(material, stage)
    _fbp_set_rig_shader_stage_order(rig, stage, tuple(rig_order))
    _fbp_set_enabled(rig, effect_id, bool(enabled_before))
    token = effect_instance_token(effect_id, instance_id)
    _fbp_store_effect_visibility(rig, token, visible_before)
    _fbp_store_effect_render_visibility(rig, token, render_visible_before)
    if fbp_effect_definition(effect_id).get("supports_input_source"):
        fbp_set_effect_input_source(
            rig, effect_id, input_source_before, instance_id=instance_id
        )
    _fbp_store_effect_solo_ids(rig, solo_view, tuple(solo_before))
    if group_before:
        fbp_set_effect_group_id(
            rig,
            effect_id,
            group_before,
            instance_id=instance_id,
            group_name=group_name_before,
        )
    for mask_effect_id in tuple(targeted_masks or ()):
        fbp_set_effect_mask_target(rig, mask_effect_id, token)
    _fbp_invalidate_effect_ids_cache(rig)
    fbp_effect_instance_records_for_rig(rig, ensure=True, sync_storage=True)
    if sync_items:
        fbp_sync_effect_items(rig)
    return True


def fbp_remove_effect_instance(rig, effect_id, instance_id, *, sync_items=True):
    """Atomically remove one concrete MULTI shader instance."""
    effect_id = fbp_normalize_effect_id(effect_id)
    instance_id = str(instance_id or "")
    definition = fbp_effect_definition(effect_id)
    if definition.get("kind") != "SHADER" or not instance_id:
        return False
    nodes_by_material = []
    snapshots = []
    groups = []
    for material in _fbp_plane_materials(rig):
        nodes = _fbp_shader_effect_nodes(
            material, effect_id=effect_id, instance_id=instance_id
        )
        if not nodes:
            continue
        nodes_by_material.append((material, tuple(nodes)))
        for node in nodes:
            snapshots.append(_fbp_capture_removed_shader_node(material, node))
            group = getattr(node, "node_tree", None)
            if group is not None and group not in groups:
                groups.append(group)
    if not nodes_by_material:
        return False
    stage = str(definition.get("stage", "") or "")
    token = effect_instance_token(effect_id, instance_id)
    material_orders = tuple(
        (material, tuple(_fbp_get_shader_stage_order(material, stage)))
        for material, _nodes in nodes_by_material
    )
    rig_order_before = tuple(_fbp_get_rig_shader_stage_order(rig, stage))
    enabled_before = _fbp_is_enabled(rig, effect_id)
    visible_before = _fbp_stored_effect_visibility(rig, token, True)
    render_visible_before = _fbp_stored_effect_render_visibility(rig, token, True)
    input_source_before = fbp_effect_input_source(rig, effect_id, instance_id)
    solo_view = _fbp_effect_solo_view(effect_id)
    solo_before = tuple(fbp_effect_solo_ids(rig, solo_view))
    group_before = fbp_effect_group_id_for_rig(
        rig, effect_id, instance_id=instance_id
    )
    group_name_before = fbp_effect_group_name(rig, group_before)
    targeted_masks = tuple(
        fbp_masks_targeting_effect(rig, effect_id, instance_id)
    )
    removed_count = 0
    try:
        with FBPTransaction(
            f"Remove {definition.get('label', effect_id)} instance",
            kind="EFFECT_REMOVE",
            journal_owner=rig,
            context={"effect_id": effect_id, "instance_id": instance_id},
        ) as transaction:
            transaction.defer_rollback(
                _fbp_rollback_effect_remove_transaction,
                rig,
                effect_id,
                instance_id,
                tuple(snapshots),
                material_orders,
                rig_order_before,
                enabled_before,
                visible_before,
                render_visible_before,
                input_source_before,
                solo_view,
                solo_before,
                group_before,
                group_name_before,
                targeted_masks,
                sync_items,
                label="restore removed effect instance",
            )
            transaction.checkpoint("REMOVE_NODES", expected_nodes=len(snapshots))
            if group_before:
                fbp_set_effect_group_id(
                    rig, effect_id, "", instance_id=instance_id
                )
            for material, nodes in nodes_by_material:
                for node in nodes:
                    try:
                        material.node_tree.nodes.remove(node)
                        removed_count += 1
                    except FBP_DATA_ERRORS as exc:
                        raise RuntimeError("Could not remove every effect node") from exc
                order = [
                    item for item in _fbp_get_shader_stage_order(material, stage)
                    if item != token
                ]
                _fbp_set_shader_stage_order(material, stage, order)
                _fbp_rebuild_shader_stage(material, stage)
            if removed_count != len(snapshots):
                raise RuntimeError(
                    f"Removed {removed_count} nodes, expected {len(snapshots)}"
                )
            rig_order = [
                item for item in _fbp_get_rig_shader_stage_order(rig, stage)
                if item != token
            ]
            _fbp_set_rig_shader_stage_order(rig, stage, rig_order)
            if _fbp_find_shader_effect_nodes_for_rig(
                rig, effect_id, instance_id=instance_id
            ):
                raise RuntimeError("Effect instance is still present after removal")
            transaction.checkpoint("CLEAN_REFERENCES")
            _fbp_clear_effect_visibility(rig, token)
            _fbp_clear_effect_render_visibility(rig, token)
            _fbp_clear_effect_input_source(rig, effect_id, instance_id)
            _fbp_release_masks_targeting(rig, token, targeted_masks)
            _fbp_reconcile_effect_solo_after_removal(
                rig, effect_id, solo_before, removed_instance_id=instance_id
            )
            _fbp_invalidate_effect_ids_cache(rig)
            fbp_effect_instance_records_for_rig(
                rig, ensure=True, sync_storage=True
            )
            if sync_items:
                fbp_sync_effect_items(rig)
            transaction.checkpoint("VALIDATED", removed_nodes=removed_count)
            transaction.commit()
    except (AttributeError, ReferenceError, RuntimeError, TypeError, ValueError, KeyError, IndexError) as exc:
        fbp_warn(
            "Could not remove effect instance atomically",
            exc,
            event="effects.instance.remove",
            context={"effect_id": effect_id, "instance_id": instance_id},
        )
        return False

    for group in groups:
        _fbp_remove_unused_effect_group(group)
    remaining = _fbp_find_shader_effect_nodes_for_rig(rig, effect_id)
    if not remaining:
        _fbp_set_enabled(rig, effect_id, False)
        _fbp_clear_effect_visibility(rig, effect_id)
        _fbp_clear_effect_render_visibility(rig, effect_id)
        _fbp_clear_effect_auxiliary_state(rig, effect_id)
    fbp_retire_effect_instance_state(rig, effect_id, instance_id)
    _fbp_invalidate_effect_ids_cache(rig)
    fbp_effect_instance_records_for_rig(rig, ensure=True, sync_storage=True)
    # Drop the removed instance's mixed-stack stage and composite references.
    _fbp_refresh_mixed_pipeline(rig)
    if sync_items:
        fbp_sync_effect_items(rig)
    return True


def fbp_recover_effect_instance_removal(rig, effect_id, instance_id):
    """Idempotently complete an interrupted concrete instance removal."""
    effect_id = fbp_normalize_effect_id(effect_id)
    instance_id = str(instance_id or "")
    definition = fbp_effect_definition(effect_id)
    if definition.get("kind") != "SHADER" or not instance_id:
        return False
    if _fbp_find_shader_effect_nodes_for_rig(
        rig, effect_id, instance_id=instance_id
    ):
        return fbp_remove_effect_instance(
            rig, effect_id, instance_id, sync_items=True
        )
    token = effect_instance_token(effect_id, instance_id)
    stage = str(definition.get("stage", "") or "")
    for material in _fbp_plane_materials(rig):
        order = [
            item for item in _fbp_get_shader_stage_order(material, stage)
            if item != token
        ]
        _fbp_set_shader_stage_order(material, stage, order)
        _fbp_rebuild_shader_stage(material, stage)
    _fbp_set_rig_shader_stage_order(
        rig,
        stage,
        [item for item in _fbp_get_rig_shader_stage_order(rig, stage) if item != token],
    )
    fbp_set_effect_group_id(rig, effect_id, "", instance_id=instance_id)
    _fbp_release_masks_targeting(rig, token)
    solo_view = _fbp_effect_solo_view(effect_id)
    _fbp_store_effect_solo_ids(
        rig,
        solo_view,
        [item for item in fbp_effect_solo_ids(rig, solo_view) if item != token],
    )
    _fbp_clear_effect_visibility(rig, token)
    _fbp_clear_effect_render_visibility(rig, token)
    _fbp_clear_effect_input_source(rig, effect_id, instance_id)
    if not _fbp_find_shader_effect_nodes_for_rig(rig, effect_id):
        _fbp_set_enabled(rig, effect_id, False)
        _fbp_clear_effect_auxiliary_state(rig, effect_id)
    fbp_retire_effect_instance_state(rig, effect_id, instance_id)
    _fbp_invalidate_effect_ids_cache(rig)
    fbp_effect_instance_records_for_rig(rig, ensure=True, sync_storage=True)
    _fbp_refresh_mixed_pipeline(rig)
    fbp_sync_effect_items(rig)
    return not bool(
        _fbp_find_shader_effect_nodes_for_rig(
            rig, effect_id, instance_id=instance_id
        )
    )


def fbp_move_effect_instance(rig, effect_id, instance_id, direction, *, sync_items=True):
    """Move one concrete shader instance inside its evaluation stage."""
    effect_id = fbp_normalize_effect_id(effect_id)
    instance_id = str(instance_id or "")
    definition = fbp_effect_definition(effect_id)
    if definition.get("kind") != "SHADER" or not instance_id:
        return False
    stage = str(definition.get("stage", "") or "")
    token = effect_instance_token(effect_id, instance_id)
    order = _fbp_get_rig_shader_stage_order(rig, stage)
    if token not in order:
        materials = _fbp_plane_materials(rig)
        order = _fbp_get_shader_stage_order(materials[0], stage) if materials else []
    if token not in order:
        return False
    step = -1 if str(direction).upper() == "UP" else 1
    current = order.index(token)
    target = current + step
    if target < 0 or target >= len(order):
        return False
    order[current], order[target] = order[target], order[current]
    _fbp_set_rig_shader_stage_order(rig, stage, order)
    moved = True
    for material in _fbp_plane_materials(rig):
        active = _fbp_get_shader_stage_order(material, stage)
        material_order = [item for item in order if item in active]
        material_order.extend(item for item in active if item not in material_order)
        _fbp_set_shader_stage_order(material, stage, material_order)
        moved = _fbp_rebuild_shader_stage(material, stage) or moved
    if moved:
        fbp_effect_instance_records_for_rig(rig, ensure=True, sync_storage=True)
        if sync_items:
            fbp_sync_effect_items(rig)
    return moved

def fbp_remove_shader_effect(rig, effect_id, *, sync_items=True):
    effect_id = fbp_normalize_effect_id(effect_id)
    definition = fbp_effect_definition(effect_id)
    if definition.get("kind") != "SHADER":
        return False
    removed = False
    removed_instance_ids = {
        effect_instance_id(node)
        for node in _fbp_find_shader_effect_nodes_for_rig(rig, effect_id)
        if effect_instance_id(node)
    }
    for material in _fbp_plane_materials(rig):
        nodes = _fbp_shader_effect_nodes(material, effect_id=effect_id)
        if not nodes:
            continue
        stage = str(definition.get("stage", ""))
        image_node = _fbp_shader_image_node(material)
        stage_nodes = _fbp_stage_effect_nodes(material, stage)
        source_override = None
        target_override = None
        if stage == "UV":
            source_override = _fbp_stage_external_uv_source(
                material, image_node, stage_nodes
            )
        else:
            target_override = _fbp_stage_external_target(
                material, image_node, stage, stage_nodes
            )
        removed_groups = []
        for node in nodes:
            removed_groups.append(getattr(node, "node_tree", None))
            try:
                material.node_tree.nodes.remove(node)
                removed = True
            except FBP_DATA_ERRORS:
                pass
        for node_group in removed_groups:
            try:
                if node_group and bool(node_group.get("fbp_private_effect_group", False)):
                    _fbp_remove_unused_effect_group(node_group)
            except FBP_DATA_ERRORS:
                pass
        order = [
            item
            for item in (
                _fbp_get_rig_shader_stage_order(rig, stage)
                or _fbp_get_shader_stage_order(material, stage)
            )
            if _fbp_shader_token_effect_id(item) != effect_id
        ]
        _fbp_set_rig_shader_stage_order(rig, stage, order)
        _fbp_set_shader_stage_order(material, stage, order)
        _fbp_rebuild_shader_stage(
            material, stage,
            source_override=source_override,
            target_override=target_override,
        )
    cleaned = _fbp_set_enabled(rig, effect_id, False)
    cleaned = _fbp_clear_effect_visibility(rig, effect_id) or cleaned
    cleaned = _fbp_clear_effect_render_visibility(rig, effect_id) or cleaned
    if removed or cleaned:
        for instance_id in removed_instance_ids:
            token = effect_instance_token(effect_id, instance_id)
            _fbp_clear_effect_visibility(rig, token)
            _fbp_clear_effect_render_visibility(rig, token)
            _fbp_clear_effect_input_source(rig, effect_id, instance_id)
            fbp_retire_effect_instance_state(rig, effect_id, instance_id)
        _fbp_invalidate_effect_ids_cache(rig)
        _fbp_refresh_geometry_source_materials(rig)
    if sync_items:
        fbp_sync_effect_items(rig)
    return removed or cleaned


def fbp_update_shader_effect(
    rig,
    effect_id,
    scene=None,
    *,
    property_names=None,
    nodes=None,
    instance_id=None,
):
    """Update one concrete shader instance when the effect supports MULTI.

    SINGLE effects update every matching node. UI property
    callbacks resolve the active row automatically, while frame/runtime paths
    that already provide ``nodes`` remain explicit and allocation-free.
    """
    effect_id = fbp_normalize_effect_id(effect_id)
    definition = fbp_effect_definition(effect_id)
    resolved_instance_id = instance_id
    if (
        resolved_instance_id is None
        and nodes is None
        and str(definition.get("instance_policy", "SINGLE") or "SINGLE").upper() == "MULTI"
        and fbp_active_effect_id(rig) == effect_id
    ):
        resolved_instance_id = fbp_active_effect_instance_id(rig)
    resolved_instance_id = str(resolved_instance_id or "")
    explicit_nodes = nodes is not None
    nodes = (
        list(nodes)
        if explicit_nodes
        else _fbp_find_shader_effect_nodes_for_rig(
            rig, effect_id, instance_id=resolved_instance_id
        )
    )
    if (
        explicit_nodes
        and property_names
        and str(definition.get("instance_policy", "SINGLE") or "SINGLE").upper() == "MULTI"
        and len({effect_instance_id(node) for node in nodes if effect_instance_id(node)}) > 1
    ):
        # Object-level F-Curves remain effect-scoped. Never broadcast
        # them across mixed concrete nodes; instance channels always pass one
        # instance_id or one concrete node tuple into this function.
        return False
    repaired = bool(nodes) and any(
        not getattr(node, "node_tree", None)
        or not _fbp_group_matches(getattr(node, "node_tree", None), effect_id)
        for node in nodes
    )
    if not nodes and not resolved_instance_id:
        repaired = True
    if repaired:
        # Re-inject the bundled group before updating values. Targeted MULTI
        # updates never create a replacement instance implicitly.
        fbp_apply_shader_effect(
            rig, effect_id, rebuild=True, sync_items=False
        )
        nodes = _fbp_find_shader_effect_nodes_for_rig(
            rig, effect_id, instance_id=resolved_instance_id
        )
        property_names = None
    if not nodes:
        return False
    changed = False
    for node in nodes:
        changed = _fbp_set_shader_node_values(
            rig,
            effect_id,
            node,
            scene=scene,
            property_names=property_names,
        ) or changed
    if changed:
        if str(definition.get("instance_policy", "SINGLE") or "SINGLE").upper() == "MULTI":
            fbp_effect_instance_records_for_rig(rig, ensure=True, sync_storage=True)
        try:
            plane = _fbp_plane(rig)
            if plane:
                plane.update_tag()
        except FBP_DATA_ERRORS:
            pass
        _fbp_refresh_geometry_source_materials(rig)
        _fbp_sync_effect_shell_values(rig)
    return changed


def _fbp_material_base_alpha_source(material, image_node):
    """Return the alpha source *before* the optional layer-opacity node.

    Returning ``FBP_Opacity`` itself here creates a self-link on the next slider
    update (node output -> its own input). The base source must remain the image,
    native transparent-row mask, gradient ramp or procedural alpha value.
    """
    node_tree = getattr(material, "node_tree", None) if material else None
    if not node_tree:
        return None
    if image_node:
        native_mask = node_tree.nodes.get("FBP_Native_Frame_Alpha")
        if native_mask and getattr(native_mask, "type", "") == "MATH":
            output = _fbp_node_socket(native_mask.outputs, "Value", 0)
            if output:
                return output
        return _fbp_node_socket(image_node.outputs, "Alpha")

    ramp = _fbp_gradient_ramp_node(material)
    if ramp:
        return _fbp_node_socket(ramp.outputs, "Alpha")

    alpha = node_tree.nodes.get("FBP_Procedural_Alpha_Source")
    if not alpha or getattr(alpha, "type", "") != "VALUE":
        try:
            alpha = node_tree.nodes.new("ShaderNodeValue")
            alpha.name = "FBP_Procedural_Alpha_Source"
            alpha.label = "Frame by Plane Alpha Source"
            alpha.location = (-380.0, -80.0)
            alpha["fbp_procedural_alpha_source"] = True
        except FBP_DATA_ERRORS:
            return None
    value = 1.0
    try:
        color = tuple(material.get("fbp_color_value", (1.0, 1.0, 1.0, 1.0)))
        value = float(color[3]) if len(color) > 3 else 1.0
    except (AttributeError, ReferenceError, RuntimeError, TypeError, ValueError, IndexError):
        pass
    try:
        alpha.outputs[0].default_value = value
    except FBP_DATA_ERRORS:
        pass
    return _fbp_node_socket(alpha.outputs, "Value", 0)


def _fbp_material_layer_alpha_source(material, image_node):
    """Return alpha after the optional layer-opacity multiplier."""
    base_alpha = _fbp_material_base_alpha_source(material, image_node)
    node_tree = getattr(material, "node_tree", None) if material else None
    if not node_tree or base_alpha is None:
        return base_alpha
    try:
        opacity = node_tree.nodes.get("FBP_Opacity")
        if (
            opacity
            and getattr(opacity, "type", "") == "MATH"
            and str(getattr(opacity, "operation", "") or "") == "MULTIPLY"
            and len(opacity.inputs[0].links) == 1
            and opacity.inputs[0].links[0].from_socket == base_alpha
        ):
            return _fbp_node_socket(opacity.outputs, "Value", 0) or base_alpha
    except (AttributeError, ReferenceError, RuntimeError, TypeError, ValueError, IndexError):
        pass
    return base_alpha


def _fbp_active_surface_node(material):
    """Return the shader node connected to the active Material Output."""
    node_tree = getattr(material, "node_tree", None) if material else None
    if not node_tree:
        return None
    try:
        outputs = [
            node for node in node_tree.nodes
            if getattr(node, "type", "") == "OUTPUT_MATERIAL"
        ]
        output = next(
            (node for node in outputs if bool(getattr(node, "is_active_output", False))),
            outputs[0] if outputs else None,
        )
        surface = _fbp_node_socket(
            getattr(output, "inputs", ()), "Surface", 0
        ) if output else None
        if surface and surface.is_linked:
            return surface.links[0].from_node
    except (AttributeError, ReferenceError, RuntimeError, TypeError, ValueError, IndexError):
        return None
    return None


def _fbp_primary_color_shader(material):
    """Return the visible color shader below the active alpha mix, if present."""
    node = _fbp_active_surface_node(material)
    visited = set()
    while node and getattr(node, "type", "") == "MIX_SHADER":
        pointer = id(node)
        if pointer in visited:
            return None
        visited.add(pointer)
        next_node = None
        # FBP alpha mixes use shader 2 as the visible image branch. Fall back to
        # shader 1 for custom but still valid material layouts.
        for index in (2, 1):
            socket = _fbp_node_socket(node.inputs, "Shader", index)
            if socket and socket.is_linked:
                next_node = socket.links[0].from_node
                break
        node = next_node
    return node


def _fbp_material_alpha_targets(material):
    """Return alpha inputs from the shader that actually feeds Material Output.

    Restricting the search to the active surface chain prevents the layer-opacity
    slider from modifying unrelated Principled or Mix Shader nodes that a user may
    have added elsewhere in the Frame by Plane material.
    """
    node_tree = getattr(material, "node_tree", None) if material else None
    if not node_tree:
        return []
    try:
        shader_node = _fbp_active_surface_node(material)
        if shader_node is None:
            return []
        node_type = getattr(shader_node, "type", "")
        if node_type == "MIX_SHADER":
            target = _fbp_node_socket(shader_node.inputs, "Fac", 0)
            return [target] if target else []
        if node_type == "BSDF_PRINCIPLED":
            target = _fbp_node_socket(shader_node.inputs, "Alpha")
            return [target] if target else []
    except (AttributeError, ReferenceError, RuntimeError, TypeError, ValueError, IndexError):
        return []
    return []


def _fbp_ensure_effect_alpha_targets(material):
    """Create an alpha Mix Shader for opaque emission materials when required."""
    targets = _fbp_material_alpha_targets(material)
    if targets:
        return targets
    node_tree = getattr(material, "node_tree", None) if material else None
    if not node_tree:
        return []
    shader = _fbp_active_surface_node(material)
    if not shader or getattr(shader, "type", "") != "EMISSION":
        return []
    outputs = [
        node for node in node_tree.nodes
        if getattr(node, "type", "") == "OUTPUT_MATERIAL"
    ]
    output = next((node for node in outputs if bool(getattr(node, "is_active_output", False))), None)
    output = output or (outputs[0] if outputs else None)
    if output is None:
        return []
    try:
        transparent = node_tree.nodes.get("FBP_Effect_Transparent")
        if not transparent or getattr(transparent, "type", "") != "BSDF_TRANSPARENT":
            transparent = node_tree.nodes.new("ShaderNodeBsdfTransparent")
            transparent.name = "FBP_Effect_Transparent"
            transparent.label = "Frame by Plane Effect Transparency"
            transparent.location = (shader.location.x, shader.location.y - 180.0)
            transparent["fbp_effect_alpha_helper"] = True
        mix = node_tree.nodes.get("FBP_Effect_Alpha_Mix")
        if not mix or getattr(mix, "type", "") != "MIX_SHADER":
            mix = node_tree.nodes.new("ShaderNodeMixShader")
            mix.name = "FBP_Effect_Alpha_Mix"
            mix.label = "Frame by Plane Effect Alpha"
            mix.location = (shader.location.x + 220.0, shader.location.y)
            mix["fbp_effect_alpha_helper"] = True
        _fbp_link_single(node_tree, transparent.outputs[0], mix.inputs[1])
        _fbp_link_single(node_tree, shader.outputs[0], mix.inputs[2])
        _fbp_link_single(node_tree, mix.outputs[0], output.inputs[0])
        target = _fbp_node_socket(mix.inputs, "Fac", 0)
        return [target] if target else []
    except (AttributeError, ReferenceError, RuntimeError, TypeError, ValueError, IndexError):
        return []


def _fbp_link_single(node_tree, source, target):
    if not node_tree or not source or not target:
        return False
    try:
        if len(target.links) == 1 and target.links[0].from_socket == source:
            return False
        for link in list(target.links):
            node_tree.links.remove(link)
        node_tree.links.new(source, target)
        return True
    except FBP_DATA_ERRORS:
        return False


def _fbp_opacity_nodes(node_tree):
    """Return only opacity nodes explicitly owned by Frame By Plane."""
    if not node_tree:
        return []
    result = []
    for node in list(node_tree.nodes):
        try:
            if (
                getattr(node, "type", "") == "MATH"
                and bool(node.get("fbp_internal_opacity_node", False))
            ):
                result.append(node)
        except FBP_DATA_ERRORS:
            continue
    return result


def _fbp_prepare_opacity_node(node_tree):
    """Keep at most one Math opacity node and remove duplicates."""
    candidates = _fbp_opacity_nodes(node_tree)
    valid = [node for node in candidates if getattr(node, "type", "") == "MATH"]
    keep = next((node for node in valid if getattr(node, "name", "") == "FBP_Opacity"), None)
    keep = keep or (valid[0] if valid else None)
    changed = False
    for node in candidates:
        if node == keep:
            continue
        try:
            node_tree.nodes.remove(node)
            changed = True
        except FBP_DATA_ERRORS:
            pass
    if keep:
        try:
            keep.name = "FBP_Opacity"
            keep.label = "Layer Opacity"
            keep["fbp_internal_opacity_node"] = True
        except FBP_DATA_ERRORS:
            pass
    return keep, changed


def fbp_sync_layer_opacity_effect(rig, opacity=None):
    """Update one alpha Multiply node and remove it completely at 100%."""
    if not rig:
        return False
    try:
        opacity = float(getattr(rig, "fbp_opacity", 1.0) if opacity is None else opacity)
    except FBP_DATA_ERRORS:
        opacity = 1.0
    opacity = max(0.0, min(1.0, opacity))
    changed = False
    for material in _fbp_plane_materials(rig):
        node_tree = getattr(material, "node_tree", None)
        image_node = _fbp_shader_image_node(material)
        if not node_tree or not image_node:
            continue
        try:
            if abs(float(material.get("fbp_opacity", 1.0)) - opacity) > 1e-6:
                material["fbp_opacity"] = opacity
                changed = True
        except FBP_DATA_ERRORS:
            pass
        base_alpha = _fbp_material_base_alpha_source(material, image_node)
        if not base_alpha or not _fbp_material_alpha_targets(material):
            continue
        opacity_node, repaired = _fbp_prepare_opacity_node(node_tree)
        changed = repaired or changed
        if opacity < 0.999:
            if opacity_node is None:
                opacity_node = node_tree.nodes.new("ShaderNodeMath")
                opacity_node.name = "FBP_Opacity"
                opacity_node.label = "Layer Opacity"
                opacity_node["fbp_internal_opacity_node"] = True
                opacity_node.location = (image_node.location.x + 260.0, image_node.location.y - 220.0)
                changed = True
            opacity_node.operation = "MULTIPLY"
            if abs(float(opacity_node.inputs[1].default_value) - opacity) > 1e-6:
                opacity_node.inputs[1].default_value = opacity
                changed = True
            changed = _fbp_link_single(node_tree, base_alpha, opacity_node.inputs[0]) or changed
            alpha_output = _fbp_node_socket(opacity_node.outputs, "Value", 0)
        else:
            if opacity_node is not None:
                try:
                    node_tree.nodes.remove(opacity_node)
                    changed = True
                except FBP_DATA_ERRORS:
                    pass
            alpha_output = base_alpha

        evaluation_nodes = _fbp_color_stage_evaluation_nodes(material, rig)
        changed = _fbp_relink_effect_alpha(
            material, evaluation_nodes, alpha_output
        ) or changed
    return changed


# ---------------------------------------------------------------------------
# Generic effect stack state
# ---------------------------------------------------------------------------


def fbp_retag_effect_owners_after_layer_rename(rig, old_plane_name=""):
    """Update current name-based effect ownership markers after a layer rename.

    Effect datablocks are linked by pointers, but a few lightweight ownership
    tags intentionally store readable datablock names for repair and cleanup.
    Renaming a rig or its generated plane must update those tags atomically or
    later effect refreshes can treat valid data as foreign and duplicate it.
    """
    if not rig:
        return False
    plane = _fbp_plane(rig)
    if not plane:
        return False

    new_rig_name = str(getattr(rig, "name_full", getattr(rig, "name", "")) or "")
    new_plane_name = str(getattr(plane, "name_full", getattr(plane, "name", "")) or "")
    old_plane_name = str(old_plane_name or "")
    changed = False

    # Shader materials use the rig name to resolve input-source settings.
    for material in _fbp_plane_materials(rig):
        try:
            tagged_owner = str(material.get("fbp_effect_rig_owner", "") or "")
            has_effect_nodes = bool(_fbp_shader_effect_nodes(material))
            if has_effect_nodes and tagged_owner != new_rig_name:
                material["fbp_effect_rig_owner"] = new_rig_name
                changed = True
        except FBP_DATA_ERRORS:
            continue

    # Private Geometry Nodes groups use the generated plane name as owner.
    try:
        for modifier in list(getattr(plane, "modifiers", ()) or ()):
            group = getattr(modifier, "node_group", None)
            if not group or not str(group.get("fbp_effect_id", "") or ""):
                continue
            owner = str(group.get("fbp_effect_owner", "") or "")
            if owner == old_plane_name or (not owner and bool(group.get("fbp_private_effect_group", False))):
                group["fbp_effect_owner"] = new_plane_name
                changed = True
    except FBP_DATA_ERRORS:
        pass

    # Effect-owned side/back/text materials are not always in the plane slots.
    # Rename is a rare user action, so a bounded global material scan is safer
    # than leaving stale owners that later cleanup may misclassify.
    if old_plane_name and old_plane_name != new_plane_name:
        for material in list(bpy.data.materials):
            try:
                if str(material.get("fbp_effect_material_owner", "") or "") != old_plane_name:
                    continue
                material["fbp_effect_material_owner"] = new_plane_name
                role = str(material.get("fbp_effect_material_role", "") or "")
                expected_old = f"FBP {role} • {old_plane_name}" if role else ""
                if expected_old and material.name == expected_old:
                    material.name = f"FBP {role} • {new_plane_name}"
                changed = True
            except FBP_DATA_ERRORS:
                continue

    if changed:
        _FBP_EFFECT_HEALTH_CACHE.clear()
        try:
            plane.update_tag()
        except FBP_DATA_ERRORS:
            pass
    return changed


def fbp_effect_is_active(rig, effect_id):
    effect_id = fbp_normalize_effect_id(effect_id)
    definition = fbp_effect_definition(effect_id)
    if definition.get("kind") == "BASE":
        if effect_id == FBP_EFFECT_EMISSION:
            return bool(_fbp_is_enabled(rig, effect_id))
        if effect_id == FBP_EFFECT_MOTION:
            try:
                return bool(_fbp_is_enabled(rig, effect_id) or len(getattr(rig, "fbp_motions", ())) > 0)
            except FBP_DATA_ERRORS:
                return bool(_fbp_is_enabled(rig, effect_id))
        if effect_id == FBP_EFFECT_CAMERA_BILLBOARD:
            return bool(_fbp_is_enabled(rig, effect_id) and _fbp_track_to_camera_constraint(rig))
        if effect_id == FBP_EFFECT_LATTICE:
            plane = _fbp_plane(rig)
            # Keep corrupted or partially repaired cages visible in the Mesh
            # stack so the user can inspect, rebuild or remove them. Requiring a
            # perfect helper/modifier pair made the row disappear exactly when
            # recovery controls were needed most.
            return bool(
                _fbp_is_enabled(rig, effect_id)
                or _fbp_lattice_object(rig)
                or _fbp_lattice_modifier(plane)
            )
        if _fbp_is_enabled(rig, effect_id):
            return True
        properties = tuple(definition.get("property_map", {}))
        for prop_name in properties:
            if prop_name == "fbp_extend_mode":
                continue
            try:
                if abs(float(getattr(rig, prop_name, 0.0) or 0.0)) > 1e-6:
                    return True
            except FBP_DATA_ERRORS:
                continue
        return False
    if definition.get("kind") == "GEOMETRY":
        return fbp_find_effect_modifier(rig, effect_id) is not None
    if definition.get("kind") == "SHADER":
        return bool(_fbp_find_shader_effect_nodes_for_rig(rig, effect_id))
    return False


def _fbp_effect_ids_cache_key(rig):
    """Return a cache key resilient to rename, deletion and pointer reuse."""
    try:
        identity = fbp_obj_runtime_key(rig)
        name = str(getattr(rig, "name_full", getattr(rig, "name", "")) or "")
        return (identity, name) if identity is not None else (0, "")
    except FBP_DATA_ERRORS:
        return (0, "")


def _fbp_invalidate_effect_runtime_profile(rig=None):
    """Drop cached per-frame targets without retaining stale RNA references."""
    if rig is None:
        _FBP_EFFECT_RUNTIME_PROFILE_CACHE.clear()
        _FBP_EFFECT_EVOLVE_STEP_CACHE.clear()
        return
    key = _fbp_effect_ids_cache_key(rig)
    if key and key[0]:
        _FBP_EFFECT_RUNTIME_PROFILE_CACHE.pop(key, None)
        _FBP_EFFECT_EVOLVE_STEP_CACHE.pop(key, None)


def _fbp_invalidate_effect_ids_cache(rig=None):
    """Invalidate cached stack presence/order after a structural mutation."""
    if rig is None:
        _FBP_EFFECT_IDS_CACHE.clear()
        _FBP_EFFECT_IDS_CACHE_TIME.clear()
        _FBP_EFFECT_RUNTIME_PROFILE_CACHE.clear()
        _FBP_EFFECT_EVOLVE_STEP_CACHE.clear()
        _FBP_EFFECT_SCENE_RIG_CACHE.clear()
        return
    key = _fbp_effect_ids_cache_key(rig)
    if key and key[0]:
        _FBP_EFFECT_IDS_CACHE.pop(key, None)
        _FBP_EFFECT_IDS_CACHE_TIME.pop(key, None)
        _FBP_EFFECT_RUNTIME_PROFILE_CACHE.pop(key, None)
        _FBP_EFFECT_EVOLVE_STEP_CACHE.pop(key, None)
    _FBP_EFFECT_SCENE_RIG_CACHE.clear()


def _fbp_store_runtime_effect_ids(rig, effect_ids):
    key = _fbp_effect_ids_cache_key(rig)
    if not key or not key[0]:
        return tuple(effect_ids or ())
    normalized = tuple(
        effect_id
        for effect_id in (fbp_normalize_effect_id(item) for item in effect_ids or ())
        if effect_id in FBP_EFFECT_REGISTRY
    )
    # Discovery is the structural invalidation boundary only when the ordered
    # stack actually changes. Keeping the runtime profile alive for identical
    # IDs avoids rebuilding modifier/node target maps every TTL refresh during
    # playback. Explicit add/remove/rebuild paths still call the invalidators.
    previous = _FBP_EFFECT_IDS_CACHE.get(key)
    if previous != normalized:
        _FBP_EFFECT_RUNTIME_PROFILE_CACHE.pop(key, None)
        _FBP_EFFECT_EVOLVE_STEP_CACHE.pop(key, None)
        _FBP_EFFECT_SCENE_RIG_CACHE.clear()
    if len(_FBP_EFFECT_IDS_CACHE) >= 512 and key not in _FBP_EFFECT_IDS_CACHE:
        _FBP_EFFECT_IDS_CACHE.clear()
        _FBP_EFFECT_IDS_CACHE_TIME.clear()
        _FBP_EFFECT_RUNTIME_PROFILE_CACHE.clear()
        _FBP_EFFECT_SCENE_RIG_CACHE.clear()
    _FBP_EFFECT_IDS_CACHE[key] = normalized
    _FBP_EFFECT_IDS_CACHE_TIME[key] = time.monotonic()
    return normalized


def _fbp_runtime_effect_ids(rig, key=None):
    """Return the current effect stack for per-frame hot paths.

    ``Object.fbp_effects`` is a ``SKIP_SAVE`` UI mirror, so it is empty after a
    file load and may also be cleared by Undo. Treating that transient list as
    the source of truth silently disabled camera, quality and frame-sync work
    until the Effects panel happened to rebuild it. On a cache miss, inspect
    only the current effect modifiers/material nodes once, then keep the result
    in the bounded runtime cache. No schema conversion or asset rebuild occurs.
    ``key`` lets a caller that already built the cache key skip rebuilding it.
    """
    if key is None:
        key = _fbp_effect_ids_cache_key(rig)
    if not key or not key[0]:
        return ()
    cached = _FBP_EFFECT_IDS_CACHE.get(key)
    checked_at = float(_FBP_EFFECT_IDS_CACHE_TIME.get(key, 0.0) or 0.0)
    if (
        cached is not None
        and time.monotonic() - checked_at <= _FBP_EFFECT_IDS_CACHE_SECONDS
    ):
        return cached
    try:
        return tuple(fbp_effect_ids_for_rig(rig))
    except FBP_DATA_ERRORS:
        # Preserve the last known stack when Blender temporarily invalidates an
        # RNA reference during depsgraph evaluation. Back off until the next TTL
        # window instead of retrying the same failed scan on every frame.
        fallback = cached if cached is not None else ()
        _FBP_EFFECT_IDS_CACHE[key] = fallback
        _FBP_EFFECT_IDS_CACHE_TIME[key] = time.monotonic()
        return fallback


def _fbp_scene_effect_runtime_rigs(scene):
    """Return only rigs with active effects, using a self-healing scene index."""
    if scene is None:
        return ()
    try:
        scene_key = (
            fbp_obj_runtime_key(scene),
            str(getattr(scene, "name_full", getattr(scene, "name", "")) or ""),
        )
        object_count = len(scene.objects)
        layer_count = len(getattr(scene, "fbp_layers", ()) or ())
    except FBP_DATA_ERRORS:
        scene_key = (0, "")
        object_count = -1
        layer_count = -1
    now = time.monotonic()
    cached = _FBP_EFFECT_SCENE_RIG_CACHE.get(scene_key) if scene_key[0] else None
    if cached is not None:
        try:
            if (
                int(cached.get("object_count", -2)) == object_count
                and int(cached.get("layer_count", -2)) == layer_count
                and now - float(cached.get("checked_at", 0.0) or 0.0)
                <= _FBP_EFFECT_SCENE_CACHE_SECONDS
            ):
                names = tuple(cached.get("rig_names", ()) or ())
                # ``scene.objects.get`` walks the scene's object view for
                # every name, which made this per-frame lookup quadratic in
                # the layer count. One pass over the view resolves them all.
                wanted = frozenset(names)
                found = {}
                if wanted:
                    for obj in scene.objects:
                        obj_name = obj.name
                        if obj_name in wanted:
                            found[obj_name] = obj
                if len(found) == len(names):
                    return tuple(found[name] for name in names)
                _FBP_EFFECT_SCENE_RIG_CACHE.pop(scene_key, None)
        except FBP_DATA_ERRORS:
            pass

    try:
        from .layers import iter_scene_fbp_rigs
        rigs = tuple(
            rig for rig in iter_scene_fbp_rigs(scene)
            if tuple(_fbp_runtime_effect_ids(rig))
        )
    except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
        return ()
    if scene_key[0]:
        if len(_FBP_EFFECT_SCENE_RIG_CACHE) >= 32 and scene_key not in _FBP_EFFECT_SCENE_RIG_CACHE:
            _FBP_EFFECT_SCENE_RIG_CACHE.clear()
        _FBP_EFFECT_SCENE_RIG_CACHE[scene_key] = {
            "object_count": object_count,
            "layer_count": layer_count,
            "checked_at": now,
            "rig_names": tuple(
                str(getattr(rig, "name", "") or "") for rig in rigs if rig is not None
            ),
        }
    return rigs


def _fbp_effect_runtime_profile(rig):
    """Return cached targets and flags used by the frame-change hot path.

    Effect discovery already has an explicit cache. This second-level profile
    turns its ordered tuple into reusable sets and resolves Blender modifiers /
    shader nodes only when the current stack can actually need per-frame Python
    writes. This keeps idle scenes and static effects cheap during playback.
    """
    key = _fbp_effect_ids_cache_key(rig)
    if not key or not key[0]:
        return {
            "effect_ids": (), "active_ids": frozenset(),
            "geometry_source_sync": False, "shader_source_sync": False,
            "animated_effect_properties": {}, "animated_instance_channels": (),
            "instance_animation_pairs": (), "animated_instance_animation_pairs": (),
            "instance_speed_fcurve_pairs": (),
            "evolve_pairs": (), "procedural_frame_effects": (),
            "geometry_modifiers": {}, "shader_nodes": {},
            "shader_nodes_by_instance": {}, "frame_geometry_modifiers": (),
            "frame_shader_targets": (),
        }
    effect_ids = tuple(_fbp_runtime_effect_ids(rig, key))
    active_ids = frozenset(effect_ids)
    plane = _fbp_plane(rig)
    try:
        animation_data = getattr(rig, "animation_data", None)
        action = getattr(animation_data, "action", None) if animation_data else None
        slot = getattr(animation_data, "action_slot", None) if animation_data else None
        action_curves = tuple(fbp_action_fcurves(rig) or ()) if action else ()
        driver_curves = tuple(getattr(animation_data, "drivers", ()) or ()) if animation_data else ()
        curves = action_curves + tuple(
            curve for curve in driver_curves if curve not in action_curves
        )
        curve_paths = tuple(sorted(
            str(getattr(curve, "data_path", "") or "")
            for curve in curves
            if not bool(getattr(curve, "mute", False))
        ))
        animation_key = (
            fbp_rna_runtime_key(action) if action else 0,
            fbp_rna_runtime_key(slot) if slot else 0,
            tuple(
                fbp_rna_runtime_key(curve)
                for curve in curves
                if not bool(getattr(curve, "mute", False))
            ),
            curve_paths,
        )
    except FBP_DATA_ERRORS:
        curves = ()
        curve_paths = ()
        animation_key = (0, 0, (), ())
    try:
        plane_key = (
            fbp_obj_runtime_key(plane) if plane else 0,
            str(getattr(plane, "name_full", getattr(plane, "name", "")) or "") if plane else "",
        )
    except FBP_DATA_ERRORS:
        plane_key = (0, "")
    cached = _FBP_EFFECT_RUNTIME_PROFILE_CACHE.get(key)
    if (
        cached is not None
        and cached.get("effect_ids") == effect_ids
        and cached.get("plane_key") == plane_key
        and cached.get("animation_key") == animation_key
        and time.monotonic() - float(cached.get("built_at", 0.0) or 0.0)
        <= _FBP_EFFECT_PROFILE_CACHE_SECONDS
    ):
        return cached

    animated_effect_properties = {}
    try:
        for curve in curves or ():
            if bool(getattr(curve, "mute", False)):
                continue
            data_path = str(getattr(curve, "data_path", "") or "")
            for effect_id in FBP_ANIMATED_PROPERTY_EFFECTS.get(data_path, ()):
                if effect_id in active_ids:
                    animated_effect_properties.setdefault(effect_id, set()).add(data_path)
    except FBP_DATA_ERRORS:
        animated_effect_properties.clear()
    animated_effect_properties = {
        effect_id: frozenset(property_names)
        for effect_id, property_names in animated_effect_properties.items()
    }

    curve_path_set = set(curve_paths)
    animated_instance_channels = []
    for channel in getattr(rig, "fbp_effect_instance_channels", ()):
        try:
            if not bool(getattr(channel, "active", True)):
                continue
            effect_id, instance_id, prop_name = _fbp_effect_instance_channel_identity(channel)
            if effect_id not in active_ids or not instance_id:
                continue
            attr = _fbp_instance_channel_value_attr(channel)
            path = str(channel.path_from_id(attr) or "")
            if path in curve_path_set:
                animated_instance_channels.append(channel)
        except FBP_DATA_ERRORS:
            continue

    instance_animation_pairs = []
    animated_instance_animation_pairs = []
    instance_speed_fcurve_pairs = []
    for item in getattr(rig, "fbp_effect_instance_animations", ()):
        try:
            if not bool(getattr(item, "active", True)):
                continue
            effect_id = fbp_normalize_effect_id(getattr(item, "effect_id", ""))
            instance_id = str(getattr(item, "instance_id", "") or "")
            if effect_id not in active_ids or not instance_id:
                continue
            definition = fbp_effect_definition(effect_id)
            if not definition.get("evolve_property"):
                continue
            pair = (effect_id, instance_id, item)
            instance_animation_pairs.append(pair)
            animated_paths = {
                str(item.path_from_id(name) or "")
                for name in ("evolve", "speed", "step", "seed", "unique", "amount")
            }
            if animated_paths.intersection(curve_path_set):
                animated_instance_animation_pairs.append(pair)
            speed_path = str(item.path_from_id("speed") or "")
            if speed_path in curve_path_set:
                instance_speed_fcurve_pairs.append(pair)
        except FBP_DATA_ERRORS:
            continue
    instance_animation_effect_ids = frozenset(
        effect_id for effect_id, _instance_id, _item in instance_animation_pairs
    )

    evolve_pairs = tuple(
        (effect_id, property_key)
        for effect_id, property_key in FBP_EVOLVE_EFFECT_PROPERTIES
        if effect_id in active_ids and effect_id not in instance_animation_effect_ids
    )
    procedural_frame_effects = tuple(
        effect_id
        for effect_id in FBP_PROCEDURAL_FRAME_SYNC_EFFECT_IDS
        if effect_id in active_ids
    )

    active_frame_geometry = active_ids.intersection(FBP_FRAME_SYNC_GEOMETRY_EFFECT_ID_SET)
    active_frame_shader = active_ids.intersection(FBP_FRAME_SYNC_SHADER_EFFECT_ID_SET)
    geometry_source_sync = bool(active_frame_geometry and _fbp_geometry_source_requires_frame_sync(rig))
    shader_source_sync = bool(active_frame_shader and _fbp_shader_source_requires_frame_sync(rig, active_ids))

    animated_geometry_ids = FBP_GEOMETRY_EFFECT_ID_SET.intersection(animated_effect_properties)
    animated_shader_ids = FBP_SHADER_EFFECT_ID_SET.intersection(animated_effect_properties)
    evolve_geometry_ids = frozenset(
        effect_id for effect_id, _property_key in evolve_pairs
        if effect_id in FBP_GEOMETRY_EFFECT_ID_SET
    )
    evolve_shader_ids = frozenset(
        effect_id for effect_id, _property_key in evolve_pairs
        if effect_id in FBP_SHADER_EFFECT_ID_SET
    ).union(instance_animation_effect_ids)

    geometry_modifiers = {}
    frame_geometry_modifiers = []
    need_geometry_targets = bool(
        geometry_source_sync
        or procedural_frame_effects
        or animated_geometry_ids
        or evolve_geometry_ids
    )
    if need_geometry_targets and plane is not None:
        try:
            needed_geometry_ids = set(active_frame_geometry)
            needed_geometry_ids.update(procedural_frame_effects)
            needed_geometry_ids.update(animated_geometry_ids)
            needed_geometry_ids.update(evolve_geometry_ids)
            for modifier in plane.modifiers:
                if getattr(modifier, "type", "") != "NODES":
                    continue
                effect_id = _fbp_geometry_effect_id_for_modifier(modifier)
                if effect_id not in needed_geometry_ids or effect_id in geometry_modifiers:
                    continue
                geometry_modifiers[effect_id] = modifier
                if effect_id in FBP_FRAME_SYNC_GEOMETRY_EFFECT_ID_SET:
                    frame_geometry_modifiers.append(modifier)
        except FBP_DATA_ERRORS:
            geometry_modifiers.clear()
            frame_geometry_modifiers.clear()

    shader_nodes = {}
    shader_nodes_by_instance = {}
    frame_shader_targets = []
    need_shader_targets = bool(
        shader_source_sync or animated_shader_ids or evolve_shader_ids
        or animated_instance_channels or animated_instance_animation_pairs
    )
    if need_shader_targets:
        shader_node_lists = {}
        try:
            needed_shader_ids = set(active_frame_shader)
            needed_shader_ids.update(animated_shader_ids)
            needed_shader_ids.update(evolve_shader_ids)
            for material in _fbp_plane_materials(rig):
                for node in _fbp_shader_effect_nodes(material):
                    effect_id = _fbp_shader_effect_id(node)
                    if effect_id not in needed_shader_ids:
                        continue
                    shader_node_lists.setdefault(effect_id, []).append(node)
                    node_instance_id = effect_instance_id(node)
                    if node_instance_id:
                        shader_nodes_by_instance.setdefault(
                            effect_instance_token(effect_id, node_instance_id), []
                        ).append(node)
                    if effect_id in FBP_FRAME_SYNC_SHADER_EFFECT_ID_SET:
                        frame_shader_targets.append((material, node, effect_id))
        except FBP_DATA_ERRORS:
            shader_node_lists.clear()
            shader_nodes_by_instance.clear()
            frame_shader_targets.clear()
        shader_nodes = {
            effect_id: tuple(nodes) for effect_id, nodes in shader_node_lists.items()
        }
        shader_nodes_by_instance = {
            token: tuple(nodes) for token, nodes in shader_nodes_by_instance.items()
        }

    profile = {
        "effect_ids": effect_ids,
        "active_ids": active_ids,
        "plane_key": plane_key,
        "animation_key": animation_key,
        "built_at": time.monotonic(),
        "geometry_source_sync": geometry_source_sync,
        "shader_source_sync": shader_source_sync,
        "animated_effect_properties": animated_effect_properties,
        "animated_instance_channels": tuple(animated_instance_channels),
        "instance_animation_pairs": tuple(instance_animation_pairs),
        "animated_instance_animation_pairs": tuple(animated_instance_animation_pairs),
        "instance_speed_fcurve_pairs": tuple(instance_speed_fcurve_pairs),
        "evolve_pairs": evolve_pairs,
        "procedural_frame_effects": procedural_frame_effects,
        "geometry_modifiers": geometry_modifiers,
        "shader_nodes": shader_nodes,
        "shader_nodes_by_instance": shader_nodes_by_instance,
        "frame_geometry_modifiers": tuple(frame_geometry_modifiers),
        "frame_shader_targets": tuple(frame_shader_targets),
        # A stack with nothing that moves per frame: no source sync, no keyed
        # or driven setting, no Evolve-capable or procedural effect and no
        # live Lattice. The frame handler skips such layers outright. Evolve
        # toggles stay covered because ``evolve_pairs`` lists every
        # Evolve-capable effect whether or not Evolve is on.
        "frame_idle": not (
            geometry_source_sync
            or shader_source_sync
            or animated_effect_properties
            or animated_instance_channels
            or instance_animation_pairs
            or instance_speed_fcurve_pairs
            or evolve_pairs
            or procedural_frame_effects
            or FBP_EFFECT_LATTICE in active_ids
        ),
    }
    if len(_FBP_EFFECT_RUNTIME_PROFILE_CACHE) >= 512 and key not in _FBP_EFFECT_RUNTIME_PROFILE_CACHE:
        _FBP_EFFECT_RUNTIME_PROFILE_CACHE.clear()
    _FBP_EFFECT_RUNTIME_PROFILE_CACHE[key] = profile
    return profile


def fbp_effect_ids_for_rig(rig, *, refresh_custom=False):
    if refresh_custom:
        fbp_refresh_custom_effect_registry()
    plane = _fbp_plane(rig)
    if not plane:
        return []
    result = []
    seen = set()

    def append_once(effect_id):
        effect_id = fbp_normalize_effect_id(effect_id)
        if not effect_id or effect_id in seen or effect_id not in FBP_EFFECT_REGISTRY:
            return
        seen.add(effect_id)
        result.append(effect_id)

    # BASE effects exist in both Image and Mesh categories. Older builds only
    # enumerated the Image BASE order, so Lattice and camera layout effects could
    # be active in Blender while remaining absent from the Mesh stack and thus
    # impossible to select or remove from the Effects UI.
    base_effect_order = tuple(FBP_BASE_EFFECT_MENU_ORDER) + tuple(
        effect_id for effect_id in FBP_3D_EFFECT_MENU_ORDER
        if fbp_effect_definition(effect_id).get("kind") == "BASE"
    )
    # Scan the plane materials once. Shader rows of the base menu order are
    # active exactly when a tagged node exists, which fbp_effect_is_active
    # would otherwise find by rescanning every material node once per row.
    material_nodes = [
        (material, _fbp_shader_effect_nodes(material))
        for material in _fbp_plane_materials(rig)
    ]
    shader_ids_present = {
        _fbp_shader_effect_id(node)
        for _material, tagged_nodes in material_nodes
        for node in tagged_nodes
    }
    for effect_id in base_effect_order:
        if fbp_effect_definition(effect_id).get("kind") == "SHADER":
            if fbp_normalize_effect_id(effect_id) in shader_ids_present:
                append_once(effect_id)
        elif fbp_effect_is_active(rig, effect_id):
            append_once(effect_id)

    try:
        for modifier in plane.modifiers:
            append_once(_fbp_geometry_effect_id_for_modifier(modifier))
    except FBP_DATA_ERRORS:
        pass

    for material, tagged_nodes in material_nodes:
        tagged_ids = {_fbp_shader_effect_id(node) for node in tagged_nodes}
        for stage in ("UV", "COLOR", "MASK"):
            for effect_id in _fbp_get_shader_stage_order(material, stage):
                if effect_id in tagged_ids:
                    append_once(effect_id)
        # Keep the UI recoverable if a tagged effect node exists but its stored
        # order string was cleared or partially written. The node itself remains
        # the source of truth for effect presence.
        for node in tagged_nodes:
            append_once(_fbp_shader_effect_id(node))
    _fbp_store_runtime_effect_ids(rig, result)
    return result


def fbp_effect_presence(rigs, effect_id):
    rigs = [rig for rig in list(rigs or []) if rig]
    effect_id = fbp_normalize_effect_id(effect_id)
    count = sum(1 for rig in rigs if effect_id in _fbp_runtime_effect_ids(rig))
    return count, len(rigs)


def fbp_effect_source_rig(rigs, effect_id):
    effect_id = fbp_normalize_effect_id(effect_id)
    return next(
        (rig for rig in list(rigs or []) if rig and effect_id in _fbp_runtime_effect_ids(rig)),
        None,
    )


def fbp_effect_asset_health_signature(rig, *, force=False, effect_ids=None):
    """Describe whether active effects still reference their expected assets.

    UI draw calls may request this signature repeatedly. Cache only the resulting
    string for a fraction of a second; explicit synchronization forces a fresh
    check before attempting repairs.
    """
    rig_cache_key = _fbp_effect_ids_cache_key(rig)
    cache_key = (
        rig_cache_key,
        FBP_EFFECT_SCHEMA_VERSION,
        FBP_LOCAL_EFFECT_MASK_WIRING_VERSION,
        FBP_SHADER_CHAIN_WIRING_VERSION,
    )
    cacheable = bool(rig_cache_key and rig_cache_key[0])
    now = time.monotonic()
    if not force and cacheable:
        cached = _FBP_EFFECT_HEALTH_CACHE.get(cache_key)
        if cached and (now - float(cached[0])) < _FBP_EFFECT_HEALTH_CACHE_SECONDS:
            return str(cached[1])

    tokens = []
    active_ids = (
        tuple(effect_ids)
        if effect_ids is not None
        else tuple(fbp_effect_ids_for_rig(rig))
    )
    for effect_id in active_ids:
        definition = fbp_effect_definition(effect_id)
        if definition.get("kind") == "BASE":
            tokens.append(f"{effect_id}:ok")
            continue
        if definition.get("kind") == "GEOMETRY":
            modifier = fbp_find_effect_modifier(rig, effect_id)
            group = getattr(modifier, "node_group", None) if modifier else None
            healthy = bool(group and _fbp_group_matches(group, effect_id))
            if healthy and definition.get("alpha_aware"):
                try:
                    plane = _fbp_plane(rig)
                    owns_group = (
                        group.get("fbp_effect_owner", "")
                        == str(getattr(plane, "name", "") or "")
                    )
                    if bool(definition.get("requires_alpha_geometry_contract")):
                        alpha_contract = bool(
                            int(group.get("fbp_alpha_geometry_contract_version", 0) or 0) >= 1
                            and len(
                                [
                                    node for node in group.nodes
                                    if bool(node.get("fbp_alpha_image_node", False))
                                ]
                            ) == 1
                        )
                    else:
                        alpha_contract = bool(
                            int(group.get("fbp_alpha_mask_patch_version", 0) or 0)
                            >= FBP_ALPHA_MASK_PATCH_VERSION
                        )
                    healthy = bool(owns_group and alpha_contract)
                except FBP_DATA_ERRORS:
                    healthy = False
            tokens.append(f"{effect_id}:{'ok' if healthy else 'broken'}")
            continue

        nodes = _fbp_find_shader_effect_nodes_for_rig(rig, effect_id)
        healthy = bool(nodes)
        for node in nodes:
            group = getattr(node, "node_tree", None)
            if not group or not _fbp_group_matches(group, effect_id):
                healthy = False
                break
        tokens.append(f"{effect_id}:{'ok' if healthy else 'broken'}")

    shader_effect_active = any(
        fbp_effect_definition(effect_id).get("kind") == "SHADER"
        for effect_id in active_ids
    )
    if shader_effect_active:
        chain_healthy = True
        for material in _fbp_plane_materials(rig):
            try:
                if int(material.get("fbp_shader_chain_wiring_version", 0) or 0) < FBP_SHADER_CHAIN_WIRING_VERSION:
                    chain_healthy = False
                    break
            except FBP_DATA_ERRORS:
                chain_healthy = False
                break
        tokens.append(
            f"SHADER_CHAIN_WIRING:{'ok' if chain_healthy else 'broken'}"
        )

    if _fbp_mask_target_map(rig):
        wiring_healthy = True
        for material in _fbp_plane_materials(rig):
            try:
                if int(material.get("fbp_local_effect_mask_wiring_version", 0) or 0) < FBP_LOCAL_EFFECT_MASK_WIRING_VERSION:
                    wiring_healthy = False
                    break
            except FBP_DATA_ERRORS:
                wiring_healthy = False
                break
        tokens.append(
            f"LOCAL_MASK_WIRING:{'ok' if wiring_healthy else 'broken'}"
        )
    signature = ",".join(tokens)
    if cacheable:
        if len(_FBP_EFFECT_HEALTH_CACHE) >= 512 and cache_key not in _FBP_EFFECT_HEALTH_CACHE:
            _FBP_EFFECT_HEALTH_CACHE.clear()
        _FBP_EFFECT_HEALTH_CACHE[cache_key] = (now, signature)
    return signature


def fbp_repair_effect_assets(rig, *, effect_ids=None):
    """Re-inject missing bundled groups while preserving modifiers and keyframes.

    ``effect_ids`` lets callers reuse an existing stack discovery pass. Healthy
    stacks therefore avoid a second material/modifier traversal during UI sync.
    """
    if not rig:
        return False
    changed = False
    active_ids = (
        tuple(effect_ids)
        if effect_ids is not None
        else tuple(fbp_effect_ids_for_rig(rig))
    )
    for effect_id in active_ids:
        definition = fbp_effect_definition(effect_id)
        if definition.get("kind") == "BASE":
            continue
        if definition.get("kind") == "GEOMETRY":
            modifier = fbp_find_effect_modifier(rig, effect_id)
            if not modifier:
                continue
            previous = getattr(modifier, "node_group", None)
            group = _fbp_ensure_geometry_effect_group(rig, effect_id, modifier)
            if group and group != previous:
                changed = True
                changed = fbp_update_geometry_effect(
                    rig, effect_id, modifier
                ) or changed
            continue

        nodes = _fbp_find_shader_effect_nodes_for_rig(rig, effect_id)
        broken = not nodes or any(
            not getattr(node, "node_tree", None)
            or not _fbp_group_matches(getattr(node, "node_tree", None), effect_id)
            for node in nodes
        )
        if broken:
            changed = fbp_apply_shader_effect(
                rig, effect_id, rebuild=True, sync_items=False
            ) or changed

    # Rebuild incomplete shader stacks once. Every effect input
    # must have one deterministic upstream socket so stack order is real rather
    # than dependent on stale Blender links left by add/reorder/Undo operations.
    if any(
        fbp_effect_definition(effect_id).get("kind") == "SHADER"
        for effect_id in active_ids
    ):
        for material in _fbp_plane_materials(rig):
            try:
                version = int(material.get("fbp_shader_chain_wiring_version", 0) or 0)
            except FBP_DATA_ERRORS:
                version = 0
            if version < FBP_SHADER_CHAIN_WIRING_VERSION:
                changed = _fbp_rebuild_shader_stage(material, "UV") or changed
                changed = _fbp_rebuild_shader_stage(material, "COLOR") or changed

    # Damaged graphs can preserve invalid global
    # Alpha links after a mask was moved onto one effect. Rebuild once per
    # material and store a compact version so healthy files pay no recurring cost.
    if _fbp_mask_target_map(rig):
        for material in _fbp_plane_materials(rig):
            try:
                version = int(material.get("fbp_local_effect_mask_wiring_version", 0) or 0)
            except FBP_DATA_ERRORS:
                version = 0
            if version < FBP_LOCAL_EFFECT_MASK_WIRING_VERSION:
                changed = _fbp_rebuild_local_mask_receivers(material) or changed
    return changed


def _fbp_unique_live_rigs(rig, rigs=None):
    """Return valid rigs once, keeping active first and the remainder stable."""
    result = []
    seen = set()
    candidates = [rig]
    candidates.extend(tuple(rigs or ()))
    for candidate in candidates:
        if candidate is None:
            continue
        key = _fbp_effect_ids_cache_key(candidate)
        if not key[0] or key in seen:
            continue
        seen.add(key)
        result.append(candidate)
    if len(result) <= 2:
        return result

    def _sort_key(candidate):
        try:
            name = str(
                getattr(candidate, "name_full", getattr(candidate, "name", ""))
                or ""
            )
        except FBP_DATA_ERRORS:
            name = ""
        return (name.casefold(), repr(_fbp_effect_ids_cache_key(candidate)))

    return [result[0], *sorted(result[1:], key=_sort_key)]


FBP_EFFECT_STACK_OWNER_KEY = "fbp_effect_stack_owner_id"


def _fbp_effect_stack_owner_id(rig, *, force=False, ensure=True):
    """Return a persistent per-rig owner identity and repair copied IDs.

    Blender duplicates ID properties during Shift+D. The runtime owner index
    detects two live rigs claiming the same stack identity and gives the later
    claimant a fresh token without scanning every object in the project.
    """
    if rig is None:
        return ""
    rig_key = fbp_obj_runtime_key(rig)
    try:
        owner_id = str(rig.get(FBP_EFFECT_STACK_OWNER_KEY, "") or "")
    except FBP_DATA_ERRORS:
        return ""
    claimed_by = _FBP_EFFECT_STACK_OWNER_CACHE.get(owner_id) if owner_id else None
    needs_repair = bool(
        force or not owner_id or (
            claimed_by is not None and claimed_by != rig_key
        )
    )
    if needs_repair:
        if not ensure and not force:
            return owner_id
        owner_id = fbp_unique_token_hex()
        try:
            rig[FBP_EFFECT_STACK_OWNER_KEY] = owner_id
        except FBP_DATA_ERRORS:
            return ""
    if len(_FBP_EFFECT_STACK_OWNER_CACHE) >= 1024 and owner_id not in _FBP_EFFECT_STACK_OWNER_CACHE:
        _FBP_EFFECT_STACK_OWNER_CACHE.clear()
    _FBP_EFFECT_STACK_OWNER_CACHE[owner_id] = rig_key
    return owner_id


def _fbp_prepare_new_extrude(rig):
    """Apply the current defaults when Extrude is added for the first time."""
    if rig is None:
        return False
    changed = bool(
        fbp_set_rna_property_silent(rig, "fbp_thickness_grid_mode", "AUTO")
    )
    changed = bool(
        fbp_set_rna_property_silent(rig, "fbp_thickness_follow_pixelate", True)
    ) or changed
    changed = bool(
        fbp_set_rna_property_silent(rig, "fbp_thickness_safe_grid", True)
    ) or changed
    return changed


def fbp_ensure_extrude_effect_integrity(rig):
    """Keep the current Extrude modifier unique and on the latest node contract."""
    if rig is None or _fbp_plane(rig) is None:
        return False

    modifiers = _fbp_find_all_effect_modifiers(rig, FBP_EFFECT_THICKNESS)
    if not modifiers:
        return False

    changed = False
    keep = modifiers[0]
    if len(modifiers) > 1:
        _fbp_remove_duplicate_effect_modifiers(rig, FBP_EFFECT_THICKNESS, keep)
        changed = True

    current_group = getattr(keep, "node_group", None)
    stale_asset = not _fbp_group_matches(current_group, FBP_EFFECT_THICKNESS)
    if stale_asset or changed:
        changed = bool(
            fbp_update_geometry_effect(rig, FBP_EFFECT_THICKNESS, keep)
        ) or changed

    if changed:
        _fbp_invalidate_effect_runtime_profile(rig)
    return changed


def fbp_refresh_effect_instance_ids(rig, *, force=False, refresh_stack_owner=False):
    """Normalize logical effect-instance IDs for one Frame by Plane layer.

    All material copies of one shader effect share one instance ID. Geometry
    modifiers keep one ID each. Duplicated rigs receive a new stack owner and
    therefore cannot retain the source layer's persistent instance identities.
    """
    if rig is None:
        return False
    fbp_ensure_extrude_effect_integrity(rig)
    owner_id = _fbp_effect_stack_owner_id(
        rig, force=bool(force or refresh_stack_owner)
    )
    if not owner_id:
        return False
    changed = False
    plane = _fbp_plane(rig)
    if plane is not None:
        seen_geometry_instances = set()
        try:
            for modifier in plane.modifiers:
                effect_id = _fbp_geometry_effect_id_for_modifier(modifier)
                if not effect_id:
                    continue
                previous_instance = effect_instance_id(modifier)
                current_instance = _fbp_geometry_modifier_instance_id(
                    rig, modifier, effect_id, ensure=True, force=force
                )
                # Duplicating a modifier can copy its ID properties. Repair the
                # later owner immediately so concrete instances never alias.
                if current_instance in seen_geometry_instances:
                    current_instance = _fbp_geometry_modifier_instance_id(
                        rig, modifier, effect_id, ensure=True, force=True
                    )
                if current_instance:
                    seen_geometry_instances.add(current_instance)
                changed = bool(
                    current_instance and current_instance != previous_instance
                ) or changed
        except FBP_DATA_ERRORS:
            pass

    # Shader instances are paired across materials by concrete stack position.
    # All material copies of one logical instance share an ID, while repeated
    # instances of the same effect retain distinct identities.
    shader_slots = {}
    try:
        for material in _fbp_plane_materials(rig):
            occurrences = {}
            ordered_nodes = []
            for stage in ("UV", "COLOR", "MASK"):
                ordered_nodes.extend(_fbp_stage_effect_nodes(material, stage))
            for node in ordered_nodes:
                effect_id = _fbp_shader_effect_id(node)
                if not effect_id:
                    continue
                occurrence = occurrences.get(effect_id, 0)
                occurrences[effect_id] = occurrence + 1
                shader_slots.setdefault((effect_id, occurrence), []).append(node)
    except FBP_DATA_ERRORS:
        shader_slots.clear()
    for (effect_id, occurrence), owners in shader_slots.items():
        existing = tuple(dict.fromkeys(
            effect_instance_id(owner) for owner in owners if effect_instance_id(owner)
        ))
        instance_id = (
            new_effect_instance_id(effect_id)
            if force or len(existing) != 1 else existing[0]
        )
        owner_token = f"{owner_id}:{effect_id}:{occurrence}"
        for owner in owners:
            previous = effect_instance_id(owner)
            assigned = assign_effect_instance_id(
                owner, effect_id, instance_id, owner_token
            )
            changed = bool(assigned and assigned != previous) or changed
    return changed


def fbp_effect_instance_id_for_rig(rig, effect_id, *, ensure=True):
    """Return the logical identity of the concrete owner in the active stack."""
    definition = fbp_effect_definition(effect_id)
    if definition.get("kind") == "GEOMETRY":
        modifier = fbp_find_effect_modifier(rig, effect_id)
        if modifier:
            return _fbp_geometry_modifier_instance_id(
                rig, modifier, effect_id, ensure=ensure
            )
        return _fbp_stored_effect_instance_id(rig, effect_id)
    if definition.get("kind") == "SHADER":
        nodes = _fbp_find_shader_effect_nodes_for_rig(rig, effect_id)
        if nodes:
            return (
                ensure_effect_instance_id(nodes[0], effect_id)
                if ensure else effect_instance_id(nodes[0])
            )
    if definition.get("kind") == "BASE":
        return f"base:{fbp_normalize_effect_id(effect_id).lower()}"
    return ""


def _fbp_effect_instance_storage_key(effect_id):
    effect_id = fbp_normalize_effect_id(effect_id)
    return f"fbp_effect_instance::{effect_id}" if effect_id else ""


def _fbp_stored_effect_instance_id(rig, effect_id):
    key = _fbp_effect_instance_storage_key(effect_id)
    if rig is None or not key:
        return ""
    try:
        return str(rig.get(key, "") or "")
    except FBP_DATA_ERRORS:
        return ""


def _fbp_store_effect_instance_id(rig, effect_id, instance_id):
    key = _fbp_effect_instance_storage_key(effect_id)
    if rig is None or not key or not instance_id:
        return False
    try:
        current = str(rig.get(key, "") or "")
        if current == str(instance_id):
            return False
        rig[key] = str(instance_id)
        return True
    except FBP_DATA_ERRORS:
        return False


def _fbp_geometry_modifier_instance_id(
    rig, modifier, effect_id, *, ensure=True, force=False
):
    """Return the persistent identity stored on one Geometry Nodes modifier.

    Blender 5.2 modifiers expose ID-property storage through ``bpy_struct``.
    The concrete modifier is authoritative. A guarded rig mirror remains a
    current recovery path for linked or read-only data where modifier properties
    cannot be written.
    """
    effect_id = fbp_normalize_effect_id(effect_id)
    owner_id = _fbp_effect_stack_owner_id(
        rig, ensure=bool(ensure or force)
    )
    owner_token = f"{owner_id}:{effect_id}" if owner_id else effect_id
    current = ""
    if modifier is not None and not force:
        current = effect_instance_id(modifier)
    if not current and not force:
        current = _fbp_stored_effect_instance_id(rig, effect_id)
    if force or (ensure and not current):
        current = new_effect_instance_id(effect_id)
    if current and modifier is not None and (ensure or force):
        assigned = assign_effect_instance_id(
            modifier, effect_id, current, owner_token
        )
        if assigned:
            current = assigned
    if current and (ensure or force):
        # Keep the current recovery mirror, but never use it to collapse two
        # concrete modifiers in multi-instance execution.
        _fbp_store_effect_instance_id(rig, effect_id, current)
    return str(current or "")


def _fbp_effect_group_storage_key(effect_id, instance_id=""):
    token = _fbp_effect_ref(effect_id, instance_id)
    if not token:
        return ""
    return fbp_compact_idproperty_key(
        f"fbp_effect_group::{token}",
        namespace="fbp_effect_group",
    )



def _fbp_stored_effect_group_id(rig, effect_id, instance_id=""):
    key = _fbp_effect_group_storage_key(effect_id, instance_id)
    if not rig or not key:
        return ""
    try:
        return str(rig.get(key, "") or "")
    except FBP_DATA_ERRORS:
        return ""



def _fbp_store_effect_group_id(rig, effect_id, group_id, instance_id=""):
    key = _fbp_effect_group_storage_key(effect_id, instance_id)
    if not rig or not key:
        return False
    group_id = str(group_id or "")
    try:
        current = str(rig.get(key, "") or "")
        if group_id:
            if current == group_id:
                return False
            rig[key] = group_id
            return True
        if key in rig:
            del rig[key]
            return True
    except FBP_DATA_ERRORS:
        return False
    return False



def _fbp_effect_group_owners(rig, effect_id, instance_id=""):
    """Return concrete Blender owners for one logical or exact effect row."""
    effect_id = fbp_normalize_effect_id(effect_id)
    instance_id = str(instance_id or "")
    definition = fbp_effect_definition(effect_id)
    if definition.get("kind") == "GEOMETRY":
        modifier = fbp_find_effect_modifier(
            rig, effect_id, instance_id=instance_id
        )
        return [modifier] if modifier is not None else []
    if definition.get("kind") == "SHADER":
        return list(_fbp_find_shader_effect_nodes_for_rig(
            rig, effect_id, instance_id=instance_id
        ))
    return []



def _fbp_resolve_effect_group_id(
    rig, effect_id, owners, *, instance_id="", normalize=True
):
    """Resolve one exact group assignment without collapsing duplicate rows."""
    effect_id = fbp_normalize_effect_id(effect_id)
    instance_id = str(instance_id or "")
    owners = tuple(owner for owner in tuple(owners or ()) if owner is not None)
    stored = _fbp_stored_effect_group_id(rig, effect_id, instance_id)
    raw_owner_ids = [effect_group_id(owner) for owner in owners]
    owner_ids = list(dict.fromkeys(item for item in raw_owner_ids if item))
    owners_unanimous = bool(
        owners and owner_ids and all(item == owner_ids[0] for item in raw_owner_ids)
    )
    if stored and stored in owner_ids:
        group_id = stored
    elif stored and not owners_unanimous:
        group_id = stored
    elif owner_ids:
        group_id = owner_ids[0]
    else:
        group_id = stored
    if normalize:
        _fbp_store_effect_group_id(
            rig, effect_id, group_id, instance_id=instance_id
        )
        for owner in owners:
            assign_effect_group_id(owner, group_id)
    return group_id



def fbp_effect_group_id_for_rig(
    rig, effect_id, *, instance_id="", normalize=True
):
    """Return and optionally repair the group of one exact effect instance."""
    effect_id = fbp_normalize_effect_id(effect_id)
    instance_id = str(instance_id or "")
    owners = _fbp_effect_group_owners(rig, effect_id, instance_id)
    return _fbp_resolve_effect_group_id(
        rig, effect_id, owners,
        instance_id=instance_id,
        normalize=normalize,
    )



def _fbp_effect_group_record(rig, group_id):
    group_id = str(group_id or "")
    if not rig or not group_id or not hasattr(rig, "fbp_effect_groups"):
        return None
    try:
        return next(
            (item for item in rig.fbp_effect_groups
             if str(getattr(item, "group_id", "") or "") == group_id),
            None,
        )
    except FBP_DATA_ERRORS:
        return None


def _fbp_clean_effect_group_name(group_name):
    """Normalize one UI folder name before storing it in Blender RNA."""
    return " ".join(str(group_name or "").strip().split())[:64]


def _fbp_next_effect_group_name(rig):
    used = {
        _fbp_clean_effect_group_name(getattr(item, "group_name", ""))
        for item in getattr(rig, "fbp_effect_groups", ())
    } if rig else set()
    index = 1
    while f"Effect Group {index}" in used:
        index += 1
    return f"Effect Group {index}"


def fbp_ensure_effect_group_record(rig, group_id, group_name=""):
    """Ensure persistent per-rig metadata exists for one Effect Group."""
    group_id = str(group_id or "")
    if not rig or not group_id or not hasattr(rig, "fbp_effect_groups"):
        return None
    record = _fbp_effect_group_record(rig, group_id)
    clean_name = _fbp_clean_effect_group_name(group_name)
    if record is None:
        try:
            record = rig.fbp_effect_groups.add()
            record.group_id = group_id
            record.group_name = clean_name or _fbp_next_effect_group_name(rig)
        except FBP_DATA_ERRORS:
            return None
    elif clean_name and not _fbp_clean_effect_group_name(
        getattr(record, "group_name", "")
    ):
        try:
            record.group_name = clean_name
        except FBP_DATA_ERRORS:
            pass
    return record


def fbp_effect_group_name(rig, group_id):
    record = _fbp_effect_group_record(rig, group_id)
    return str(getattr(record, "group_name", "") or "") if record else ""


def fbp_effect_group_color_tag(rig, group_id):
    record = _fbp_effect_group_record(rig, group_id)
    return str(getattr(record, "color_tag", "NONE") or "NONE") if record else "NONE"


def fbp_effect_group_collapsed(rig, group_id):
    """Return the persistent UI collapse state for one Effect Group."""
    record = _fbp_effect_group_record(rig, group_id)
    return bool(getattr(record, "collapsed", False)) if record else False


def fbp_set_effect_group_name(rig, group_id, group_name):
    """Rename one existing group without changing membership or stack order."""
    group_id = str(group_id or "")
    group_name = _fbp_clean_effect_group_name(group_name)
    if not rig or not group_id or not group_name:
        return False
    record = _fbp_effect_group_record(rig, group_id)
    if record is None:
        return False
    current = str(getattr(record, "group_name", "") or "")
    if current == group_name:
        return True
    try:
        record.group_name = group_name
    except FBP_DATA_ERRORS:
        return False
    return str(getattr(record, "group_name", "") or "") == group_name


def fbp_set_effect_group_collapsed(rig, group_id, collapsed):
    """Persist a group collapse state while leaving effect data untouched."""
    record = _fbp_effect_group_record(rig, group_id)
    if record is None:
        return False
    collapsed = bool(collapsed)
    try:
        if bool(getattr(record, "collapsed", False)) == collapsed:
            return True
        record.collapsed = collapsed
    except FBP_DATA_ERRORS:
        return False
    return bool(getattr(record, "collapsed", False)) == collapsed


def fbp_set_effect_group_color_transactional(rigs, group_id, color_tag):
    """Assign one folder color to a shared Effect Group with rollback."""
    rigs = [rig for rig in tuple(rigs or ()) if rig]
    group_id = str(group_id or "")
    color_tag = str(color_tag or "NONE")
    valid_tags = {str(item[0]) for item in COLLECTION_COLOR_ENUM_ITEMS}
    if not rigs or not group_id or color_tag not in valid_tags:
        return False
    snapshots = {}
    for rig in rigs:
        record = _fbp_effect_group_record(rig, group_id)
        if record is None or not fbp_effect_group_members(rig, group_id):
            return False
        snapshots[rig] = str(getattr(record, "color_tag", "NONE") or "NONE")
    changed = False
    written = []
    for rig in rigs:
        record = _fbp_effect_group_record(rig, group_id)
        try:
            if str(getattr(record, "color_tag", "NONE") or "NONE") != color_tag:
                record.color_tag = color_tag
                changed = True
            written.append(rig)
        except FBP_DATA_ERRORS:
            for target in written:
                target_record = _fbp_effect_group_record(target, group_id)
                if target_record is not None:
                    try:
                        target_record.color_tag = snapshots[target]
                    except FBP_DATA_ERRORS:
                        pass
            return False
    for rig in rigs:
        fbp_sync_effect_items(rig, rigs if rig is rigs[0] else [rig])
    return changed or all(
        fbp_effect_group_color_tag(rig, group_id) == color_tag for rig in rigs
    )


def fbp_expand_effect_selection_to_groups(rig, effect_refs):
    """Expand touched concrete group members in stable stack order."""
    normalized = set(_fbp_normalize_effect_refs(effect_refs))
    if not rig or not normalized:
        return []
    groups = fbp_sync_effect_groups(rig)
    group_by_token = {
        token: group_id
        for group_id, members in groups.items()
        for token in members
    }
    touched_groups = {group_by_token.get(token, "") for token in normalized}
    touched_groups.discard("")
    for group_id in touched_groups:
        normalized.update(groups.get(group_id, ()))
    return [
        token
        for token in _fbp_mixed_effect_tokens(rig)
        if token in normalized
    ]



def fbp_rename_effect_group_transactional(rigs, group_id, group_name):
    """Rename a shared group on every selected layer with rollback."""
    rigs = [rig for rig in tuple(rigs or ()) if rig]
    group_id = str(group_id or "")
    group_name = _fbp_clean_effect_group_name(group_name)
    if not rigs or not group_id or not group_name:
        return False
    snapshots = {}
    for rig in rigs:
        record = _fbp_effect_group_record(rig, group_id)
        if record is None or not fbp_effect_group_members(rig, group_id):
            return False
        duplicate = any(
            str(getattr(item, "group_id", "") or "") != group_id
            and str(getattr(item, "group_name", "") or "").casefold() == group_name.casefold()
            for item in getattr(rig, "fbp_effect_groups", ())
        )
        if duplicate:
            return False
        snapshots[rig] = str(getattr(record, "group_name", "") or "")
    changed = []
    for rig in rigs:
        if fbp_set_effect_group_name(rig, group_id, group_name):
            changed.append(rig)
            continue
        for target in changed:
            fbp_set_effect_group_name(target, group_id, snapshots[target])
        return False
    for rig in rigs:
        fbp_sync_effect_items(rig, rigs if rig is rigs[0] else [rig])
    return True


def fbp_set_effect_group_id(
    rig, effect_id, group_id, *, instance_id="", group_name=""
):
    """Assign one exact effect row to a persistent organizational group."""
    effect_id = fbp_normalize_effect_id(effect_id)
    instance_id = str(instance_id or "")
    owners = _fbp_effect_group_owners(rig, effect_id, instance_id)
    if not owners:
        return False
    group_id = str(group_id or "")
    old_stored = _fbp_stored_effect_group_id(rig, effect_id, instance_id)
    old_owner_ids = [effect_group_id(owner) for owner in owners]
    _fbp_store_effect_group_id(
        rig, effect_id, group_id, instance_id=instance_id
    )
    for owner in owners:
        assign_effect_group_id(owner, group_id)
    consistent = (
        _fbp_stored_effect_group_id(rig, effect_id, instance_id) == group_id
        and all(effect_group_id(owner) == group_id for owner in owners)
    )
    if not consistent:
        _fbp_store_effect_group_id(
            rig, effect_id, old_stored, instance_id=instance_id
        )
        for owner, old_group_id in zip(owners, old_owner_ids, strict=True):
            assign_effect_group_id(owner, old_group_id)
        return False
    if group_id and fbp_ensure_effect_group_record(
        rig, group_id, group_name
    ) is None:
        _fbp_store_effect_group_id(
            rig, effect_id, old_stored, instance_id=instance_id
        )
        for owner, old_group_id in zip(owners, old_owner_ids, strict=True):
            assign_effect_group_id(owner, old_group_id)
        return False
    return True



def _fbp_read_effect_groups_fast(rig, effect_ids, instance_records=None):
    """Read valid concrete group blocks without mutating Blender data."""
    if not rig or not hasattr(rig, "fbp_effect_groups"):
        return {}
    records = {}
    try:
        for record in rig.fbp_effect_groups:
            group_id = str(getattr(record, "group_id", "") or "")
            if not group_id or group_id in records:
                return None
            records[group_id] = record
    except FBP_DATA_ERRORS:
        return None
    if instance_records is None:
        instance_records = fbp_effect_instance_records_for_rig(
            rig, effect_ids=effect_ids, ensure=False, sync_storage=False
        )
    groups = {}
    for item in tuple(instance_records or ()):
        effect_id = fbp_normalize_effect_id(item.get("effect_id", ""))
        if fbp_effect_definition(effect_id).get("kind") not in {"SHADER", "GEOMETRY"}:
            continue
        instance_id = (
            str(item.get("instance_id", "") or "")
            if _fbp_effect_uses_multi_instances(effect_id) else ""
        )
        group_id = str(item.get("group_id", "") or _fbp_stored_effect_group_id(
            rig, effect_id, instance_id
        ) or "")
        if not group_id:
            continue
        if group_id not in records:
            return None
        groups.setdefault(group_id, []).append(_fbp_effect_ref(effect_id, instance_id))
    if any(group_id not in groups for group_id in records):
        return None
    for _group_id, members in groups.items():
        chain_keys = {
            _fbp_effect_chain_key(_fbp_effect_ref_effect_id(token))
            for token in members
        }
        chain_keys.discard(("", ""))
        if len(chain_keys) != 1:
            return None
        order = _fbp_logical_effect_chain_tokens(
            rig, next(iter(chain_keys))
        )
        try:
            positions = [order.index(token) for token in members]
        except ValueError:
            return None
        if positions != list(range(min(positions), max(positions) + 1)):
            return None
    return {group_id: tuple(members) for group_id, members in groups.items()}



def fbp_sync_effect_groups(rig, effect_ids=None):
    """Repair concrete group membership and prune invalid folder metadata."""
    if not rig or not hasattr(rig, "fbp_effect_groups"):
        return {}
    raw_effect_ids = effect_ids if effect_ids is not None else fbp_effect_ids_for_rig(rig)
    effect_ids = tuple(dict.fromkeys(
        value for value in (fbp_normalize_effect_id(item) for item in tuple(raw_effect_ids or ()))
        if value
    ))
    instance_records = fbp_effect_instance_records_for_rig(
        rig, effect_ids=effect_ids, ensure=True, sync_storage=False
    )
    rows = []
    for record in instance_records:
        effect_id = fbp_normalize_effect_id(record.get("effect_id", ""))
        definition = fbp_effect_definition(effect_id)
        if definition.get("kind") not in {"SHADER", "GEOMETRY"}:
            continue
        instance_id = (
            str(record.get("instance_id", "") or "")
            if _fbp_effect_uses_multi_instances(effect_id) else ""
        )
        token = _fbp_effect_ref(effect_id, instance_id)
        if token:
            rows.append((token, effect_id, instance_id))
    active_effect_ids = {effect_id for _token, effect_id, _instance_id in rows}
    active_group_storage_keys = {
        _fbp_effect_group_storage_key(effect_id, instance_id)
        for _token, effect_id, instance_id in rows
    }
    active_group_storage_keys.update(
        _fbp_effect_group_storage_key(effect_id)
        for effect_id in active_effect_ids
    )
    try:
        for key in tuple(rig.keys()):
            key = str(key or "")
            if not key.startswith("fbp_effect_group"):
                continue
            if key not in active_group_storage_keys:
                del rig[key]
    except FBP_DATA_ERRORS:
        pass
    groups = {}
    owners_by_token = {}
    parts_by_token = {}
    for token, effect_id, instance_id in rows:
        owners = tuple(_fbp_effect_group_owners(rig, effect_id, instance_id))
        owners_by_token[token] = owners
        parts_by_token[token] = (effect_id, instance_id)
        group_id = _fbp_resolve_effect_group_id(
            rig, effect_id, owners,
            instance_id=instance_id,
            normalize=True,
        )
        if not group_id:
            continue
        record = fbp_ensure_effect_group_record(rig, group_id)
        if record is None:
            _fbp_store_effect_group_id(
                rig, effect_id, "", instance_id=instance_id
            )
            for owner in owners:
                assign_effect_group_id(owner, "")
            continue
        groups.setdefault(group_id, []).append(token)
    invalid_groups = set()
    group_by_token = {
        token: group_id for group_id, members in groups.items() for token in members
    }
    for group_id, members in tuple(groups.items()):
        chain_keys = {
            _fbp_effect_chain_key(_fbp_effect_ref_effect_id(token))
            for token in members
        }
        chain_keys.discard(("", ""))
        if len(chain_keys) != 1:
            invalid_groups.add(group_id)
            continue
        chain_key = next(iter(chain_keys))
        order = _fbp_logical_effect_chain_tokens(rig, chain_key)
        try:
            positions = [order.index(token) for token in members]
        except ValueError:
            invalid_groups.add(group_id)
            continue
        if not positions:
            invalid_groups.add(group_id)
            continue
        expected_positions = list(range(min(positions), max(positions) + 1))
        if positions == expected_positions:
            continue
        gap_tokens = [order[index] for index in expected_positions if index < len(order)]
        if any(group_by_token.get(token, "") not in {"", group_id} for token in gap_tokens):
            invalid_groups.add(group_id)
            continue
        for token in gap_tokens:
            if group_by_token.get(token, "") == group_id:
                continue
            effect_id, instance_id = _fbp_effect_ref_parts(token)
            owners = owners_by_token.get(token)
            if owners is None:
                owners = tuple(_fbp_effect_group_owners(rig, effect_id, instance_id))
                owners_by_token[token] = owners
            _fbp_store_effect_group_id(
                rig, effect_id, group_id, instance_id=instance_id
            )
            for owner in owners:
                assign_effect_group_id(owner, group_id)
            group_by_token[token] = group_id
        groups[group_id] = [token for token in order if group_by_token.get(token) == group_id]
    for group_id in invalid_groups:
        for token in groups.pop(group_id, ()):
            effect_id, instance_id = _fbp_effect_ref_parts(token)
            _fbp_store_effect_group_id(
                rig, effect_id, "", instance_id=instance_id
            )
            for owner in owners_by_token.get(token, ()):
                assign_effect_group_id(owner, "")
    try:
        canonical = {}
        remove_indices = []
        for index, record in enumerate(rig.fbp_effect_groups):
            group_id = str(getattr(record, "group_id", "") or "")
            if not group_id or group_id not in groups:
                remove_indices.append(index)
                continue
            first = canonical.get(group_id)
            if first is None:
                clean_name = _fbp_clean_effect_group_name(getattr(record, "group_name", ""))
                if str(getattr(record, "group_name", "") or "") != clean_name:
                    record.group_name = clean_name or _fbp_next_effect_group_name(rig)
                canonical[group_id] = record
                continue
            first_name = _fbp_clean_effect_group_name(getattr(first, "group_name", ""))
            duplicate_name = _fbp_clean_effect_group_name(getattr(record, "group_name", ""))
            if duplicate_name and (
                not first_name
                or (first_name.startswith("Effect Group ") and not duplicate_name.startswith("Effect Group "))
            ):
                first.group_name = duplicate_name
            if bool(getattr(record, "collapsed", False)):
                first.collapsed = True
            if str(getattr(first, "color_tag", "NONE") or "NONE") == "NONE":
                duplicate_color = str(getattr(record, "color_tag", "NONE") or "NONE")
                if duplicate_color != "NONE":
                    first.color_tag = duplicate_color
            remove_indices.append(index)
        for index in reversed(remove_indices):
            rig.fbp_effect_groups.remove(index)
    except FBP_DATA_ERRORS:
        pass
    return {group_id: tuple(members) for group_id, members in groups.items()}


def fbp_effect_group_members(rig, group_id, *, effect_ids=None):
    groups = fbp_sync_effect_groups(rig, effect_ids=effect_ids)
    return tuple(groups.get(str(group_id or ""), ()))


def fbp_effect_group_members_from_items(rig, group_id):
    """Read concrete group tokens from the transient UI mirror."""
    group_id = str(group_id or "")
    if not rig or not group_id or not hasattr(rig, "fbp_effects"):
        return ()
    result = []
    try:
        for item in rig.fbp_effects:
            if str(getattr(item, "group_id", "") or "") != group_id:
                continue
            effect_id = fbp_normalize_effect_id(getattr(item, "effect_id", ""))
            if not effect_id:
                continue
            instance_id = (
                str(getattr(item, "instance_id", "") or "")
                if _fbp_effect_uses_multi_instances(effect_id) else ""
            )
            result.append(_fbp_effect_ref(effect_id, instance_id))
    except FBP_DATA_ERRORS:
        return ()
    return tuple(result)



def _fbp_effect_group_state_signature(rig, effect_ids=()):
    """Return a compact signature of concrete group assignments."""
    if not rig:
        return ""
    records = {}
    try:
        records = {
            str(getattr(item, "group_id", "") or ""): (
                str(getattr(item, "group_name", "") or ""),
                bool(getattr(item, "collapsed", False)),
                str(getattr(item, "color_tag", "NONE") or "NONE"),
            )
            for item in getattr(rig, "fbp_effect_groups", ())
            if str(getattr(item, "group_id", "") or "")
        }
    except FBP_DATA_ERRORS:
        records = {}
    parts = []
    try:
        instances = fbp_effect_instance_records_for_rig(
            rig, effect_ids=effect_ids, ensure=False, sync_storage=False
        )
    except FBP_DATA_ERRORS:
        instances = ()
    for item in instances:
        effect_id = fbp_normalize_effect_id(item.get("effect_id", ""))
        if fbp_effect_definition(effect_id).get("kind") not in {"SHADER", "GEOMETRY"}:
            continue
        instance_id = (
            str(item.get("instance_id", "") or "")
            if _fbp_effect_uses_multi_instances(effect_id) else ""
        )
        group_id = _fbp_stored_effect_group_id(rig, effect_id, instance_id)
        name, collapsed, color_tag = records.get(group_id, ("", False, "NONE"))
        parts.append((_fbp_effect_ref(effect_id, instance_id), group_id, name, collapsed, color_tag))
    return repr(tuple(parts))




def _fbp_effect_stack_v2_raw(rig):
    if rig is None:
        return ""
    try:
        return str(rig.get(FBP_EFFECT_STACK_KEY, "") or "")
    except FBP_DATA_ERRORS:
        return ""


def _fbp_json_safe_effect_value(value):
    if isinstance(value, (bool, int, float, str)) or value is None:
        return value
    try:
        return [float(item) for item in value]
    except (TypeError, ValueError):
        return str(value)


def _fbp_capture_shader_instance_settings(node, definition):
    settings = {}
    for prop_name, socket_name in (definition.get("property_map", {}) or {}).items():
        socket = _fbp_node_socket(getattr(node, "inputs", ()), socket_name)
        if socket is None or not hasattr(socket, "default_value"):
            continue
        try:
            settings[str(prop_name)] = _fbp_json_safe_effect_value(socket.default_value)
        except FBP_DATA_ERRORS:
            continue
    return settings


def _fbp_discover_effect_instance_records(rig, effect_ids=None, *, ensure=True):
    """Describe concrete owners in current evaluated stack order."""
    if rig is None:
        return []
    effect_ids = tuple(effect_ids) if effect_ids is not None else tuple(
        fbp_effect_ids_for_rig(rig)
    )
    allowed = {fbp_normalize_effect_id(value) for value in effect_ids if value}
    records = []
    order = 0

    # Base effects remain one logical row per registry id.
    for effect_id in effect_ids:
        effect_id = fbp_normalize_effect_id(effect_id)
        definition = fbp_effect_definition(effect_id)
        if not effect_id or definition.get("kind") != "BASE":
            continue
        instance_id = fbp_effect_instance_id_for_rig(rig, effect_id, ensure=ensure)
        if not instance_id:
            continue
        records.append({
            "instance_id": instance_id,
            "effect_id": effect_id,
            "kind": "BASE",
            "instance_policy": "SINGLE",
            "order": order,
            "group_id": "",
            "label": "",
            "settings": {},
        })
        order += 1

    # Shader stack order is concrete and may contain repeated registry ids.
    materials = _fbp_plane_materials(rig)
    source_material = materials[0] if materials else None
    if source_material is not None:
        for stage in ("UV", "COLOR", "MASK"):
            for node in _fbp_stage_effect_nodes(source_material, stage):
                effect_id = _fbp_shader_effect_id(node)
                if not effect_id or (allowed and effect_id not in allowed):
                    continue
                definition = fbp_effect_definition(effect_id)
                instance_id = (
                    ensure_effect_instance_id(node, effect_id)
                    if ensure else effect_instance_id(node)
                )
                if not instance_id:
                    continue
                records.append({
                    "instance_id": instance_id,
                    "effect_id": effect_id,
                    "kind": "SHADER",
                    "instance_policy": str(definition.get("instance_policy", "SINGLE") or "SINGLE").upper(),
                    "order": order,
                    "group_id": fbp_effect_group_id_for_rig(
                        rig, effect_id, instance_id=instance_id, normalize=ensure
                    ),
                    "label": "",
                    "settings": _fbp_capture_shader_instance_settings(node, definition),
                })
                order += 1

    # Geometry modifiers are already concrete instances in modifier order.
    plane = _fbp_plane(rig, repair=False)
    if plane is not None:
        try:
            for modifier in plane.modifiers:
                effect_id = _fbp_geometry_effect_id_for_modifier(modifier)
                if not effect_id or (allowed and effect_id not in allowed):
                    continue
                definition = fbp_effect_definition(effect_id)
                instance_id = _fbp_geometry_modifier_instance_id(
                    rig, modifier, effect_id, ensure=ensure
                )
                if not instance_id:
                    continue
                records.append({
                    "instance_id": instance_id,
                    "effect_id": effect_id,
                    "kind": "GEOMETRY",
                    "instance_policy": str(definition.get("instance_policy", "SINGLE") or "SINGLE").upper(),
                    "order": order,
                    "group_id": fbp_effect_group_id_for_rig(
                        rig, effect_id, instance_id=instance_id, normalize=ensure
                    ),
                    "label": "",
                    "settings": {},
                })
                order += 1
        except FBP_DATA_ERRORS:
            pass
    return records


def fbp_effect_instance_records_for_rig(
    rig,
    *,
    effect_ids=None,
    refresh_custom=False,
    ensure=True,
    sync_storage=False,
):
    """Return canonical persistent instance records for one FBP layer.

    Runtime owners remain the source of truth for presence and order. Stored v2
    metadata preserves future per-instance settings and user labels across
    reload, rename and Undo/Redo. ``sync_storage`` must only be used from an
    operator, load repair or another mutation-safe boundary, never UI ``draw``.
    """
    if rig is None:
        return ()
    if refresh_custom:
        fbp_refresh_custom_effect_registry(force=False)
    if ensure:
        fbp_refresh_effect_instance_ids(rig)
    discovered = _fbp_discover_effect_instance_records(
        rig, effect_ids=effect_ids, ensure=ensure
    )
    owner_id = _fbp_effect_stack_owner_id(
        rig, ensure=bool(ensure or sync_storage)
    )
    payload = reconcile_effect_stack(
        _fbp_effect_stack_v2_raw(rig),
        discovered,
        owner_id=owner_id,
        definitions=fbp_effect_definition,
    )
    if sync_storage:
        encoded = encode_effect_stack(payload)
        try:
            if _fbp_effect_stack_v2_raw(rig) != encoded:
                rig[FBP_EFFECT_STACK_KEY] = encoded
            if int(rig.get(FBP_EFFECT_STACK_VERSION_KEY, 0) or 0) != FBP_EFFECT_DATA_MODEL_VERSION:
                rig[FBP_EFFECT_STACK_VERSION_KEY] = FBP_EFFECT_DATA_MODEL_VERSION
        except FBP_DATA_ERRORS as exc:
            fbp_warn(
                "Could not persist Effect Data Model v2",
                exc,
                event="effects.data_model.persist",
                context={"rig": getattr(rig, "name", "")},
            )
    return tuple(dict(item) for item in payload.get("instances", ()))


def fbp_effect_stack_v2_snapshot(rig, *, ensure=False):
    """Return a JSON-safe v2 payload for persistence and diagnostics."""
    records = fbp_effect_instance_records_for_rig(
        rig, ensure=ensure, sync_storage=False
    )
    return {
        "schema": FBP_EFFECT_DATA_MODEL_VERSION,
        "owner_id": _fbp_effect_stack_owner_id(rig, ensure=ensure),
        "instances": [dict(record) for record in records],
    }


def fbp_effect_stack_v2_report(rig, *, repair=False):
    """Compare persisted v2 metadata with concrete Blender owners."""
    if rig is None:
        return {
            "valid": False,
            "initialized": False,
            "repaired": False,
            "issues": ("Missing Frame By Plane rig",),
            "instance_count": 0,
            "digest": "",
        }
    raw = _fbp_effect_stack_v2_raw(rig)
    stored = decode_effect_stack(raw, definitions=fbp_effect_definition)
    records = fbp_effect_instance_records_for_rig(
        rig,
        ensure=bool(repair),
        sync_storage=False,
    )
    current = {
        "schema": FBP_EFFECT_DATA_MODEL_VERSION,
        "owner_id": _fbp_effect_stack_owner_id(rig, ensure=bool(repair)),
        "instances": [dict(record) for record in records],
    }
    issues = list(validate_effect_stack(current, definitions=fbp_effect_definition))
    stored_digest = effect_stack_digest(stored)
    current_digest = effect_stack_digest(current)
    initialized = bool(records and not raw)
    if raw and stored_digest != current_digest:
        issues.append("Persisted Effect Data Model v2 does not match runtime owners")
    repaired = False
    if repair and (initialized or issues):
        encoded = encode_effect_stack(current)
        try:
            if _fbp_effect_stack_v2_raw(rig) != encoded:
                rig[FBP_EFFECT_STACK_KEY] = encoded
                repaired = True
            if int(rig.get(FBP_EFFECT_STACK_VERSION_KEY, 0) or 0) != FBP_EFFECT_DATA_MODEL_VERSION:
                rig[FBP_EFFECT_STACK_VERSION_KEY] = FBP_EFFECT_DATA_MODEL_VERSION
                repaired = True
        except FBP_DATA_ERRORS as exc:
            fbp_warn(
                "Could not repair Effect Data Model v2",
                exc,
                event="effects.data_model.repair",
                context={"rig": getattr(rig, "name", "")},
            )
        if repaired:
            issues = list(validate_effect_stack(current, definitions=fbp_effect_definition))
    return {
        "valid": not issues,
        "initialized": initialized,
        "repaired": repaired,
        "issues": tuple(issues),
        "instance_count": len(records),
        "digest": current_digest,
    }


def fbp_persist_effect_stacks(rigs):
    """Write the reconciled Effect Data Model once per layer after a batch edit.

    Operators that mutate with ``sync_items=False`` finish with a fast UI
    sync, which never writes the persisted stack; without this call removed
    or added rows would stay out of date in the saved .blend.
    """
    for rig in tuple(rigs or ()):
        if rig is not None:
            fbp_effect_instance_records_for_rig(rig, ensure=True, sync_storage=True)


def fbp_sync_effect_items(
    rig, rigs=None, *, repair_assets=True, normalize_instance_ids=True
):
    if rig is None or not hasattr(rig, "fbp_effects"):
        return []
    target_rigs = _fbp_unique_live_rigs(rig, rigs)
    if not target_rigs:
        return []
    # Mask-target state is invalidated by the mutations that change it. Keeping
    # the cache across ordinary UI synchronizations avoids rebuilding the same
    # target map on every sidebar redraw; Undo and direct property edits still
    # self-heal through the bounded signature check in _fbp_mask_target_map().

    # Discover healthy stacks once. Repair receives the discovered IDs and only
    # triggers another traversal when it actually replaced a missing asset.
    ids_by_key = {}
    instances_by_key = {}
    groups_by_key = {}
    repaired_by_key = {}
    target_ids = []
    target_seen = set()
    for target_rig in target_rigs:
        target_key = _fbp_effect_ids_cache_key(target_rig)
        fast_ui_read = not repair_assets and not normalize_instance_ids
        effect_ids = tuple(
            _fbp_runtime_effect_ids(target_rig)
            if fast_ui_read else fbp_effect_ids_for_rig(target_rig)
        )
        repaired = False
        if repair_assets:
            health_before = fbp_effect_asset_health_signature(
                target_rig, force=False, effect_ids=effect_ids
            )
            if "broken" in health_before:
                repaired = bool(
                    fbp_repair_effect_assets(target_rig, effect_ids=effect_ids)
                )
        if normalize_instance_ids:
            fbp_refresh_effect_instance_ids(target_rig)
        if repaired:
            effect_ids = tuple(fbp_effect_ids_for_rig(target_rig))
        ids_by_key[target_key] = effect_ids
        repaired_by_key[target_key] = repaired
        instance_records = fbp_effect_instance_records_for_rig(
            target_rig,
            effect_ids=effect_ids,
            ensure=normalize_instance_ids,
            sync_storage=not fast_ui_read,
        )
        instances_by_key[target_key] = [
            dict(record) for record in instance_records
            if str(record.get("effect_id", "") or "")
        ]
        if not fast_ui_read:
            for record in instances_by_key[target_key]:
                effect_id = fbp_normalize_effect_id(record.get("effect_id", ""))
                instance_id = str(record.get("instance_id", "") or "")
                if instance_id and _fbp_effect_uses_multi_instances(effect_id):
                    fbp_ensure_effect_instance_state(
                        target_rig, effect_id, instance_id, prefer_node=True
                    )
        fast_groups = (
            _fbp_read_effect_groups_fast(
                target_rig, effect_ids,
                instance_records=instances_by_key.get(target_key, ()),
            )
            if fast_ui_read else None
        )
        groups_by_key[target_key] = (
            fast_groups
            if fast_groups is not None
            else fbp_sync_effect_groups(target_rig, effect_ids=effect_ids)
        )
        for effect_id in effect_ids:
            if effect_id in target_seen:
                continue
            target_seen.add(effect_id)
            target_ids.append(effect_id)

    names = []
    health = []
    group_signatures = []
    model_signatures = []
    for target_rig in target_rigs:
        target_key = _fbp_effect_ids_cache_key(target_rig)
        effect_ids = ids_by_key.get(target_key, ())
        try:
            names.append(
                str(
                    getattr(
                        target_rig,
                        "name_full",
                        getattr(target_rig, "name", ""),
                    )
                    or ""
                )
            )
            health.append(
                fbp_effect_asset_health_signature(
                    target_rig,
                    force=bool(repaired_by_key.get(target_key, False)),
                    effect_ids=effect_ids,
                )
                if repair_assets else "runtime"
            )
            group_signatures.append(
                _fbp_effect_group_state_signature(target_rig, effect_ids)
            )
            model_signatures.append(effect_stack_digest({
                "schema": FBP_EFFECT_DATA_MODEL_VERSION,
                "owner_id": _fbp_effect_stack_owner_id(
                    target_rig,
                    ensure=bool(repair_assets or normalize_instance_ids),
                ),
                "instances": list(instances_by_key.get(target_key, ())),
            }))
        except FBP_DATA_ERRORS:
            names.append("")
            health.append("broken" if repair_assets else "runtime")
            group_signatures.append("")
            model_signatures.append("")
    signature = repr(
        (
            tuple(target_ids),
            tuple(names),
            tuple(health),
            tuple(group_signatures),
            tuple(model_signatures),
            int(_FBP_EFFECT_UI_EPOCH),
        )
    )

    for target_rig in target_rigs:
        for effect_id in ids_by_key.get(_fbp_effect_ids_cache_key(target_rig), ()):
            viewport_key = _fbp_effect_visibility_key(effect_id)
            render_key = _fbp_effect_render_visibility_key(effect_id)
            try:
                if viewport_key not in target_rig:
                    _fbp_store_effect_visibility(
                        target_rig,
                        effect_id,
                        fbp_effect_visible_state(target_rig, effect_id),
                    )
                if render_key not in target_rig:
                    _fbp_store_effect_render_visibility(
                        target_rig,
                        effect_id,
                        fbp_effect_render_visible_state(target_rig, effect_id),
                    )
            except FBP_DATA_ERRORS:
                pass

    for target_rig in target_rigs:
        target_key = _fbp_effect_ids_cache_key(target_rig)
        for record in instances_by_key.get(target_key, ()):
            effect_id = fbp_normalize_effect_id(record.get("effect_id", ""))
            instance_id = str(record.get("instance_id", "") or "")
            definition = fbp_effect_definition(effect_id)
            if (
                not instance_id
                or str(definition.get("instance_policy", "SINGLE") or "SINGLE").upper() != "MULTI"
            ):
                continue
            token = effect_instance_token(effect_id, instance_id)
            viewport_key = _fbp_effect_visibility_key(token)
            render_key = _fbp_effect_render_visibility_key(token)
            try:
                if viewport_key not in target_rig:
                    _fbp_store_effect_visibility(
                        target_rig, token,
                        fbp_effect_visible_state(
                            target_rig, effect_id, instance_id=instance_id
                        ),
                    )
                if render_key not in target_rig:
                    _fbp_store_effect_render_visibility(
                        target_rig, token,
                        _fbp_stored_effect_render_visibility(
                            target_rig, effect_id, True
                        ),
                    )
            except FBP_DATA_ERRORS:
                continue

    try:
        active_index = int(getattr(rig, "fbp_effects_index", 0) or 0)
        active_token = ("EFFECT", "")
        if 0 <= active_index < len(rig.fbp_effects):
            active_item = rig.fbp_effects[active_index]
            active_type = str(getattr(active_item, "row_type", "EFFECT") or "EFFECT")
            active_value = (
                str(getattr(active_item, "group_id", "") or "")
                if active_type == "GROUP"
                else str(
                    getattr(active_item, "instance_id", "")
                    or fbp_normalize_effect_id(getattr(active_item, "effect_id", ""))
                )
            )
            active_token = (active_type, active_value)
        selected_tokens = {
            _fbp_effect_ref(
                getattr(item, "effect_id", ""),
                getattr(item, "instance_id", "") if _fbp_effect_uses_multi_instances(
                    getattr(item, "effect_id", "")
                ) else "",
            )
            for item in rig.fbp_effects
            if (
                str(getattr(item, "row_type", "EFFECT") or "EFFECT") == "EFFECT"
                and bool(getattr(item, "is_selected", False))
            )
        }

        active_groups = groups_by_key.get(_fbp_effect_ids_cache_key(rig), {})
        group_by_effect = {
            token: group_id
            for group_id, members in active_groups.items()
            for token in members
        }
        group_member_counts = {
            group_id: len(members) for group_id, members in active_groups.items()
        }
        group_records = {
            str(getattr(record, "group_id", "") or ""): (
                str(getattr(record, "group_name", "") or ""),
                bool(getattr(record, "collapsed", False)),
            )
            for record in getattr(rig, "fbp_effect_groups", ())
            if str(getattr(record, "group_id", "") or "")
        }

        active_instance_records = list(instances_by_key.get(
            _fbp_effect_ids_cache_key(rig), ()
        ))

        # Rows follow concrete instance order. Repeated MULTI effects therefore
        # remain independent in the UI instead of collapsing by registry id.
        target_rows = []
        emitted_groups = set()
        for instance_record in active_instance_records:
            effect_id = fbp_normalize_effect_id(instance_record.get("effect_id", ""))
            instance_id = str(instance_record.get("instance_id", "") or "")
            if not effect_id:
                continue
            instance_token = _fbp_effect_ref(
                effect_id,
                instance_id if _fbp_effect_uses_multi_instances(effect_id) else "",
            )
            group_id = str(
                instance_record.get("group_id", "")
                or group_by_effect.get(instance_token, "")
                or ""
            )
            if group_id and group_id not in emitted_groups:
                group_name, collapsed = group_records.get(group_id, ("Effect Group", False))
                target_rows.append((
                    "GROUP", "", "", group_id, group_name or "Effect Group",
                    bool(collapsed), int(group_member_counts.get(group_id, 0)),
                ))
                emitted_groups.add(group_id)
            group_name, collapsed = group_records.get(group_id, ("", False))
            target_rows.append((
                "EFFECT", effect_id, instance_id, group_id, group_name,
                bool(collapsed), int(group_member_counts.get(group_id, 0)),
            ))

        current_rows = tuple(
            (
                str(getattr(item, "row_type", "EFFECT") or "EFFECT"),
                str(getattr(item, "effect_id", "") or ""),
                str(getattr(item, "instance_id", "") or ""),
                str(getattr(item, "group_id", "") or ""),
            )
            for item in rig.fbp_effects
        )
        desired_rows = tuple(
            (row_type, effect_id, instance_id, group_id)
            for row_type, effect_id, instance_id, group_id, _name, _collapsed, _count in target_rows
        )
        if current_rows != desired_rows:
            rig.fbp_effects.clear()
            for row_type, effect_id, instance_id, group_id, group_name, collapsed, member_count in target_rows:
                item = rig.fbp_effects.add()
                item.row_type = row_type
                item.effect_id = effect_id
                item.group_id = group_id
                item.row_uid = (
                    f"GROUP:{group_id}" if row_type == "GROUP"
                    else f"EFFECT:{instance_id or effect_id}"
                )
                item.group_name = group_name
                item.group_is_first = row_type == "GROUP"
                item.group_collapsed = collapsed
                item.group_member_count = member_count
                if row_type == "GROUP":
                    item.label = group_name or "Effect Group"
                    item.instance_id = ""
                    item.is_selected = False
                else:
                    item.instance_id = instance_id
                    item.label = _fbp_effect_display_label(
                        effect_id, fbp_effect_definition(effect_id)
                    )
                    item.is_selected = _fbp_effect_ref(
                        effect_id,
                        instance_id if _fbp_effect_uses_multi_instances(effect_id) else "",
                    ) in selected_tokens
        else:
            for item, row_data in zip(rig.fbp_effects, target_rows, strict=True):
                row_type, effect_id, instance_id, group_id, group_name, collapsed, member_count = row_data
                item.row_type = row_type
                item.group_id = group_id
                item.row_uid = (
                    f"GROUP:{group_id}" if row_type == "GROUP"
                    else f"EFFECT:{instance_id or effect_id}"
                )
                item.group_name = group_name
                item.group_is_first = row_type == "GROUP"
                item.group_collapsed = collapsed
                item.group_member_count = member_count
                if row_type == "GROUP":
                    item.label = group_name or "Effect Group"
                    item.effect_id = ""
                    item.instance_id = ""
                else:
                    if str(getattr(item, "instance_id", "") or "") != instance_id:
                        item.instance_id = instance_id
                    item.label = _fbp_effect_display_label(
                        effect_id, fbp_effect_definition(effect_id)
                    )

        if target_rows:
            index_by_token = {
                (
                    (row_type, group_id)
                    if row_type == "GROUP"
                    else (row_type, instance_id or effect_id)
                ): index
                for index, (
                    row_type, effect_id, instance_id, group_id,
                    _name, _collapsed, _count,
                ) in enumerate(target_rows)
            }
            next_index = index_by_token.get(
                active_token, min(active_index, len(target_rows) - 1)
            )
        else:
            next_index = 0
        if int(getattr(rig, "fbp_effects_index", 0) or 0) != next_index:
            rig.fbp_effects_index = next_index
        if (
            hasattr(rig, "fbp_effects_signature")
            and str(getattr(rig, "fbp_effects_signature", "") or "") != signature
        ):
            rig.fbp_effects_signature = signature
        if repair_assets or normalize_instance_ids:
            fbp_load_active_effect_instance_settings(rig)
            _fbp_maintain_effect_shells(target_rigs)
    except FBP_DATA_ERRORS:
        return []
    return target_ids


def _fbp_maintain_effect_shells(rigs):
    """Keep native modifier rows (and preview shells) in step with the stack."""
    try:
        from .native_modifiers import fbp_native_after_stack_change
    except ImportError:
        return
    for target_rig in tuple(rigs or ()):
        try:
            fbp_native_after_stack_change(target_rig)
        except FBP_DATA_ERRORS as exc:
            fbp_warn("Could not refresh the effect rows in Modifiers", exc)


# The sidebar asks for each selected layer's group signature on every redraw.
# It only changes with an edit, and every edit ends in a depsgraph update, so
# the answer is kept for that update (and at most half a second).
_FBP_DRAW_GROUP_SIGNATURES = {}


def _fbp_draw_group_state_signature(rig, effect_ids):
    try:
        from . import runtime as _runtime
        key = (
            fbp_obj_runtime_key(rig),
            float(getattr(_runtime, "_FBP_LAST_DEPSGRAPH_ACTIVITY", 0.0) or 0.0),
            int(time.monotonic() * 2.0),
            tuple(effect_ids),
            _fbp_effect_stack_v2_raw(rig),
            len(getattr(rig, "fbp_effect_groups", ()) or ()),
        )
    except FBP_DATA_ERRORS:
        return _fbp_effect_group_state_signature(rig, effect_ids)
    cached = _FBP_DRAW_GROUP_SIGNATURES.get(key[0])
    if cached is not None and cached[0] == key:
        return cached[1]
    signature = _fbp_effect_group_state_signature(rig, effect_ids)
    if len(_FBP_DRAW_GROUP_SIGNATURES) > 256:
        _FBP_DRAW_GROUP_SIGNATURES.clear()
    _FBP_DRAW_GROUP_SIGNATURES[key[0]] = (key, signature)
    return signature


def fbp_schedule_effect_items_sync(rig, rigs=None):
    if rig is None or not hasattr(rig, "fbp_effects"):
        return []
    target_rigs = _fbp_unique_live_rigs(rig, rigs)
    if not target_rigs:
        return []
    target_ids = []
    target_seen = set()
    rig_names = []
    group_signatures = []
    for target_rig in target_rigs:
        try:
            rig_names.append(
                str(
                    getattr(
                        target_rig,
                        "name_full",
                        getattr(target_rig, "name", ""),
                    )
                    or ""
                )
            )
        except FBP_DATA_ERRORS:
            rig_names.append("")
        runtime_ids = tuple(_fbp_runtime_effect_ids(target_rig))
        group_signatures.append(
            _fbp_draw_group_state_signature(target_rig, runtime_ids)
        )
        for effect_id in runtime_ids:
            if effect_id in target_seen:
                continue
            target_seen.add(effect_id)
            target_ids.append(effect_id)
    # Build the UI-only signature from the same cached discovery pass instead
    # of walking every selected stack a second time.
    signature = repr(
        (
            tuple(target_ids),
            tuple(rig_names),
            tuple("runtime" for _item in target_rigs),
            tuple(group_signatures),
            int(_FBP_EFFECT_UI_EPOCH),
        )
    )
    try:
        current_ids = tuple(
            str(getattr(item, "effect_id", "") or "")
            for item in rig.fbp_effects
            if str(getattr(item, "row_type", "EFFECT") or "EFFECT") == "EFFECT"
        )
        if (
            current_ids == tuple(target_ids)
            and str(getattr(rig, "fbp_effects_signature", "") or "") == signature
        ):
            return target_ids
    except FBP_DATA_ERRORS:
        pass
    from . import safe_tasks as _safe_tasks
    rig_name = str(getattr(rig, "name", "") or "")
    rig_key = fbp_obj_runtime_key(rig)

    def _timer():
        retry_delay = ui_list_mutation_delay()
        if retry_delay > 0.0:
            return retry_delay
        active_rig = fbp_find_id_by_runtime_key(
            bpy.data.objects, rig_key, rig_name
        )
        if active_rig is None:
            return None
        current_rigs = _fbp_unique_live_rigs(
            active_rig,
            _fbp_selected_rigs(getattr(bpy, "context", None)),
        )
        # UI mirroring must stay lightweight. Structural repair is performed by
        # effect operators, Scene sync and explicit diagnostics, not every time
        # the sidebar needs to rebuild its transient list.
        fbp_sync_effect_items(
            active_rig,
            current_rigs,
            repair_assets=False,
            normalize_instance_ids=False,
        )
        return None

    _safe_tasks.schedule_once(
        f"ui.effect_stack.{rig_key}", _timer, first_interval=0.03
    )
    return target_ids


def fbp_active_effect_id(rig):
    if not rig or not hasattr(rig, "fbp_effects"):
        return ""
    try:
        index = int(getattr(rig, "fbp_effects_index", 0) or 0)
        if 0 <= index < len(rig.fbp_effects):
            item = rig.fbp_effects[index]
            if str(getattr(item, "row_type", "EFFECT") or "EFFECT") != "EFFECT":
                return ""
            return str(getattr(item, "effect_id", "") or "")
    except FBP_DATA_ERRORS:
        pass
    return ""


def fbp_active_effect_instance_id(rig):
    """Return the persistent identity of the active concrete effect row."""
    if not rig or not hasattr(rig, "fbp_effects"):
        return ""
    try:
        index = int(getattr(rig, "fbp_effects_index", 0) or 0)
        if 0 <= index < len(rig.fbp_effects):
            item = rig.fbp_effects[index]
            if str(getattr(item, "row_type", "EFFECT") or "EFFECT") != "EFFECT":
                return ""
            return str(getattr(item, "instance_id", "") or "")
    except FBP_DATA_ERRORS:
        pass
    return ""


def fbp_active_effect_group_id(rig):
    """Return the folder selected in the Effects UI, or the active effect folder."""
    if not rig or not hasattr(rig, "fbp_effects"):
        return ""
    try:
        index = int(getattr(rig, "fbp_effects_index", 0) or 0)
        if 0 <= index < len(rig.fbp_effects):
            item = rig.fbp_effects[index]
            group_id = str(getattr(item, "group_id", "") or "")
            if group_id:
                return group_id
    except FBP_DATA_ERRORS:
        pass
    return ""


def _fbp_effect_view_categories(context=None, *, effect_id=""):
    """Return categories for one effect, or every category in the mixed stack."""
    if effect_id:
        category = str(fbp_effect_definition(effect_id).get("category", "2D") or "2D")
        if category == "3D":
            return {"3D"}
        if category == "MASK":
            return {"MASK"}
        return {"BASE", "2D"}
    return {"BASE", "2D", "MASK", "3D"}


def _fbp_effect_uses_multi_instances(effect_id):
    return fbp_effect_multi_instance_enabled(effect_id)


def fbp_selected_effect_instances(
    rig, *, fallback_active=True, movable_only=False, categories=None
):
    """Return concrete checked effect rows as ``(effect_id, instance_id)``.

    Unlike :func:`fbp_selected_effect_ids`, repeated MULTI rows remain distinct.
    This is the safe input for instance-aware removal and visibility actions.
    """
    if not rig or not hasattr(rig, "fbp_effects"):
        return []
    category_filter = {str(value) for value in tuple(categories or ()) if value}
    selected = []
    seen = set()
    try:
        for item in rig.fbp_effects:
            if (
                str(getattr(item, "row_type", "EFFECT") or "EFFECT") != "EFFECT"
                or not bool(getattr(item, "is_selected", False))
            ):
                continue
            effect_id = fbp_normalize_effect_id(getattr(item, "effect_id", ""))
            definition = fbp_effect_definition(effect_id)
            category = str(definition.get("category", "2D") or "2D")
            if not effect_id or (category_filter and category not in category_filter):
                continue
            if movable_only and definition.get("kind") not in {"SHADER", "GEOMETRY"}:
                continue
            instance_id = (
                str(getattr(item, "instance_id", "") or "")
                if _fbp_effect_uses_multi_instances(effect_id)
                else ""
            )
            key = (effect_id, instance_id)
            if key not in seen:
                selected.append(key)
                seen.add(key)
    except FBP_DATA_ERRORS:
        selected = []
        seen = set()
    if not selected and fallback_active:
        active = fbp_active_effect_id(rig)
        definition = fbp_effect_definition(active)
        category = str(definition.get("category", "2D") or "2D")
        if (
            active
            and (not category_filter or category in category_filter)
            and (not movable_only or definition.get("kind") in {"SHADER", "GEOMETRY"})
        ):
            instance_id = (
                fbp_active_effect_instance_id(rig)
                if _fbp_effect_uses_multi_instances(active)
                else ""
            )
            selected.append((active, instance_id))
        elif not active:
            group_id = fbp_active_effect_group_id(rig)
            for member in fbp_effect_group_members_from_items(rig, group_id):
                member_effect, member_instance = _fbp_effect_ref_parts(member)
                member_definition = fbp_effect_definition(member_effect)
                member_category = str(member_definition.get("category", "2D") or "2D")
                if category_filter and member_category not in category_filter:
                    continue
                if movable_only and member_definition.get("kind") not in {"SHADER", "GEOMETRY"}:
                    continue
                selected.append((member_effect, member_instance))
    return selected


def fbp_selected_effect_ids(
    rig, *, fallback_active=True, movable_only=False, categories=None
):
    """Return checked effect rows in stack order, optionally limited by view.

    The active row is used as a fallback so all single-row operations
    keep working when no multi-selection checkbox is enabled.
    """
    if not rig or not hasattr(rig, "fbp_effects"):
        return []
    category_filter = {str(value) for value in tuple(categories or ()) if value}
    selected = []
    try:
        for item in rig.fbp_effects:
            if not bool(getattr(item, "is_selected", False)):
                continue
            effect_id = fbp_normalize_effect_id(getattr(item, "effect_id", ""))
            definition = fbp_effect_definition(effect_id)
            category = str(definition.get("category", "2D") or "2D")
            if not effect_id or (category_filter and category not in category_filter):
                continue
            if movable_only and definition.get("kind") not in {"SHADER", "GEOMETRY"}:
                continue
            if effect_id not in selected:
                selected.append(effect_id)
    except FBP_DATA_ERRORS:
        selected = []
    if not selected and fallback_active:
        active = fbp_active_effect_id(rig)
        definition = fbp_effect_definition(active)
        category = str(definition.get("category", "2D") or "2D")
        if (
            active
            and (not category_filter or category in category_filter)
            and (not movable_only or definition.get("kind") in {"SHADER", "GEOMETRY"})
        ):
            selected.append(active)
        elif not active:
            group_id = fbp_active_effect_group_id(rig)
            for member in fbp_effect_group_members_from_items(rig, group_id):
                member_effect = _fbp_effect_ref_effect_id(member)
                member_definition = fbp_effect_definition(member_effect)
                member_category = str(member_definition.get("category", "2D") or "2D")
                if category_filter and member_category not in category_filter:
                    continue
                if movable_only and member_definition.get("kind") not in {"SHADER", "GEOMETRY"}:
                    continue
                if member_effect not in selected:
                    selected.append(member_effect)
    return selected


def fbp_set_effect_selection(
    rig, effect_ids=(), *, mode="REPLACE", eligible_ids=None
):
    """Update transient concrete row selection without touching effect data."""
    if not rig or not hasattr(rig, "fbp_effects"):
        return False
    requested = {
        _fbp_effect_ref(*_fbp_effect_ref_parts(value))
        for value in effect_ids if value
    }
    eligible = None
    if eligible_ids is not None:
        eligible = {
            _fbp_effect_ref(*_fbp_effect_ref_parts(value))
            for value in eligible_ids if value
        }
    mode = str(mode or "REPLACE").upper()
    changed = False
    try:
        for item in rig.fbp_effects:
            if str(getattr(item, "row_type", "EFFECT") or "EFFECT") != "EFFECT":
                continue
            effect_id = fbp_normalize_effect_id(getattr(item, "effect_id", ""))
            instance_id = (
                str(getattr(item, "instance_id", "") or "")
                if _fbp_effect_uses_multi_instances(effect_id) else ""
            )
            token = _fbp_effect_ref(effect_id, instance_id)
            eligible_match = eligible is None or token in eligible or effect_id in eligible
            if not eligible_match:
                continue
            requested_match = token in requested or effect_id in requested
            current = bool(getattr(item, "is_selected", False))
            if mode == "ADD":
                target = current or requested_match
            elif mode == "REMOVE":
                target = current and not requested_match
            elif mode == "INVERT":
                target = not current
            else:
                target = requested_match
            if current != target:
                item.is_selected = target
                changed = True
    except FBP_DATA_ERRORS:
        return False
    return changed



def fbp_set_effect_instance_selection(
    rig, instance_tokens=(), *, mode="REPLACE", eligible_tokens=None
):
    """Update checkbox selection using concrete instance identities."""
    if not rig or not hasattr(rig, "fbp_effects"):
        return False
    requested = {str(value or "") for value in instance_tokens if str(value or "")}
    eligible = None if eligible_tokens is None else {
        str(value or "") for value in eligible_tokens if str(value or "")
    }
    mode = str(mode or "REPLACE").upper()
    changed = False
    try:
        for item in rig.fbp_effects:
            if str(getattr(item, "row_type", "EFFECT") or "EFFECT") != "EFFECT":
                continue
            effect_id = fbp_normalize_effect_id(getattr(item, "effect_id", ""))
            instance_id = str(getattr(item, "instance_id", "") or "")
            token = effect_instance_token(effect_id, instance_id) if instance_id else effect_id
            if eligible is not None and token not in eligible:
                continue
            current = bool(getattr(item, "is_selected", False))
            if mode == "ADD":
                target = current or token in requested
            elif mode == "REMOVE":
                target = current and token not in requested
            elif mode == "INVERT":
                target = not current
            else:
                target = token in requested
            if current != target:
                item.is_selected = target
                changed = True
    except FBP_DATA_ERRORS:
        return False
    return changed


def _fbp_select_effect_row(rig, effect_id, rigs=None, instance_id=""):
    """Select an exact effect instance in the transient runtime UI mirror."""
    effect_id = fbp_normalize_effect_id(effect_id)
    instance_id = str(instance_id or "")
    if not rig or not effect_id:
        return False
    fbp_sync_effect_items(rig, rigs)
    fallback_index = -1
    try:
        for index, item in enumerate(rig.fbp_effects):
            if (
                str(getattr(item, "row_type", "EFFECT") or "EFFECT") != "EFFECT"
                or fbp_normalize_effect_id(getattr(item, "effect_id", "")) != effect_id
            ):
                continue
            if fallback_index < 0:
                fallback_index = index
            if not instance_id or str(getattr(item, "instance_id", "") or "") == instance_id:
                rig.fbp_effects_index = index
                return True
        if fallback_index >= 0 and not instance_id:
            rig.fbp_effects_index = fallback_index
            return True
    except FBP_DATA_ERRORS:
        pass
    return False


def _fbp_select_effect_group_row(rig, group_id, rigs=None):
    """Select a real Effect Group folder row without selecting a member effect."""
    group_id = str(group_id or "")
    if not rig or not group_id:
        return False
    fbp_sync_effect_items(rig, rigs)
    try:
        for index, item in enumerate(rig.fbp_effects):
            if (
                str(getattr(item, "row_type", "EFFECT") or "EFFECT") == "GROUP"
                and str(getattr(item, "group_id", "") or "") == group_id
            ):
                rig.fbp_effects_index = index
                return True
    except FBP_DATA_ERRORS:
        pass
    return False


_FBP_EMISSION_PREV_USE_KEY = "fbp_emission_effect_previous_use_emission"
_FBP_EMISSION_PREV_COLOR_KEY = "fbp_emission_effect_previous_color_emission"
_FBP_EMISSION_PREV_STRENGTH_KEY = "fbp_emission_effect_previous_strength"


def _fbp_emission_shader_nodes(rig):
    """Yield the real Emission nodes that feed each owned layer material."""
    for material in _fbp_plane_materials(rig):
        if not material or not getattr(material, "node_tree", None):
            continue
        shader = _fbp_primary_color_shader(material)
        if shader is not None and str(getattr(shader, "type", "") or "") == "EMISSION":
            yield shader


def fbp_sync_emission_effect_surface(rig):
    """Apply the effect Strength directly to the active Emission shader nodes."""
    if not rig or not _fbp_is_enabled(rig, FBP_EFFECT_EMISSION):
        return False
    strength = max(0.0, float(getattr(rig, "fbp_emission_strength", 1.0) or 0.0))
    changed = False
    for shader in _fbp_emission_shader_nodes(rig):
        socket = _fbp_node_socket(getattr(shader, "inputs", ()), "Strength", 1)
        if socket is None:
            continue
        try:
            if abs(float(socket.default_value) - strength) > 1.0e-7:
                socket.default_value = strength
                changed = True
        except (AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
            continue
    plane = _fbp_plane(rig, repair=False)
    if plane is not None:
        try:
            if bool(getattr(plane, "visible_shadow", True)):
                plane.visible_shadow = False
                changed = True
        except FBP_DATA_ERRORS:
            pass
    return changed


def _fbp_apply_emission_effect(rig):
    """Switch owned materials to Emission once, preserving the previous mode."""
    if not rig:
        return False
    try:
        if _FBP_EMISSION_PREV_USE_KEY not in rig:
            rig[_FBP_EMISSION_PREV_USE_KEY] = bool(getattr(rig, "fbp_use_emission", True))
        if _FBP_EMISSION_PREV_COLOR_KEY not in rig:
            rig[_FBP_EMISSION_PREV_COLOR_KEY] = bool(getattr(rig, "fbp_color_plane_emission", True))
        if _FBP_EMISSION_PREV_STRENGTH_KEY not in rig:
            previous = next(iter(_fbp_emission_shader_nodes(rig)), None)
            previous_socket = _fbp_node_socket(getattr(previous, "inputs", ()), "Strength", 1) if previous else None
            rig[_FBP_EMISSION_PREV_STRENGTH_KEY] = float(getattr(previous_socket, "default_value", 1.0) or 1.0)
    except FBP_DATA_ERRORS:
        pass
    fbp_set_rna_property_silent(rig, "fbp_use_emission", True)
    if bool(getattr(rig, "fbp_is_color_plane", False)):
        fbp_set_rna_property_silent(rig, "fbp_color_plane_emission", True)
    try:
        from .materials import do_update_emission
        do_update_emission(rig)
    except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError) as exc:
        fbp_warn("Could not enable Emission effect", exc)
        return False
    return bool(tuple(_fbp_emission_shader_nodes(rig))) and (fbp_sync_emission_effect_surface(rig) or True)


def _fbp_remove_emission_effect(rig):
    """Restore the shader mode and strength that preceded the Emission effect."""
    if not rig:
        return False
    try:
        previous_use = bool(rig.get(_FBP_EMISSION_PREV_USE_KEY, True))
        previous_color = bool(rig.get(_FBP_EMISSION_PREV_COLOR_KEY, previous_use))
        previous_strength = float(rig.get(_FBP_EMISSION_PREV_STRENGTH_KEY, 1.0) or 1.0)
    except (ReferenceError, TypeError, ValueError):
        previous_use, previous_color, previous_strength = True, True, 1.0
    fbp_set_rna_property_silent(rig, "fbp_use_emission", previous_use)
    if bool(getattr(rig, "fbp_is_color_plane", False)):
        fbp_set_rna_property_silent(rig, "fbp_color_plane_emission", previous_color)
    try:
        from .materials import do_update_emission
        do_update_emission(rig)
    except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError) as exc:
        fbp_warn("Could not restore material after removing Emission", exc)
    if previous_use or (bool(getattr(rig, "fbp_is_color_plane", False)) and previous_color):
        for shader in _fbp_emission_shader_nodes(rig):
            socket = _fbp_node_socket(getattr(shader, "inputs", ()), "Strength", 1)
            if socket is not None:
                try:
                    socket.default_value = previous_strength
                except FBP_DATA_ERRORS:
                    pass
    for key in (_FBP_EMISSION_PREV_USE_KEY, _FBP_EMISSION_PREV_COLOR_KEY, _FBP_EMISSION_PREV_STRENGTH_KEY):
        try:
            if key in rig:
                del rig[key]
        except FBP_DATA_ERRORS:
            pass
    return True


def fbp_add_effect(
    rig,
    effect_id,
    *,
    select_object_mask_helper=True,
    inherit_active_group=True,
    sync_items=True,
    rebuild_shader=True,
):
    effect_id = fbp_normalize_effect_id(effect_id)
    definition = fbp_effect_definition(effect_id)
    if effect_id == FBP_EFFECT_LATTICE:
        lattice_issue = _fbp_lattice_compatibility_issue(rig)
        if lattice_issue:
            _fbp_set_lattice_error(rig, lattice_issue)
            return False
    elif not fbp_effect_supported_for_rig(rig, effect_id):
        return False
    was_active = (
        fbp_effect_is_active(rig, effect_id)
        if effect_id == FBP_EFFECT_THICKNESS else False
    )
    if effect_id == FBP_EFFECT_THICKNESS and not was_active:
        _fbp_prepare_new_extrude(rig)

    # Capture the active folder before applying the new nodes/modifier, because
    # the apply routines synchronize and select the new row.  User-created
    # effects inherit the open group they were added from when both effects
    # belong to the same real evaluation chain.
    group_anchor = ""
    inherited_group_id = ""
    inherited_group_name = ""
    inherited_group_color = "NONE"
    inherited_group_collapsed = False
    if inherit_active_group:
        active_effect_id = fbp_active_effect_id(rig)
        active_instance_id = (
            fbp_active_effect_instance_id(rig)
            if _fbp_effect_uses_multi_instances(active_effect_id) else ""
        )
        group_anchor = _fbp_effect_ref(active_effect_id, active_instance_id)
        inherited_group_id = fbp_active_effect_group_id(rig)
        if inherited_group_id and not group_anchor:
            # A selected folder inserts new compatible effects at the end of
            # that folder instead of treating one member as the container row.
            members = fbp_effect_group_members_from_items(rig, inherited_group_id)
            group_anchor = members[-1] if members else ""
        elif group_anchor and _fbp_effect_ref_effect_id(group_anchor) != effect_id:
            anchor_effect_id, anchor_instance_id = _fbp_effect_ref_parts(group_anchor)
            inherited_group_id = fbp_effect_group_id_for_rig(
                rig,
                anchor_effect_id,
                instance_id=anchor_instance_id,
                normalize=False,
            )
        if inherited_group_id:
            inherited_group_name = fbp_effect_group_name(
                rig, inherited_group_id
            )
            inherited_group_color = fbp_effect_group_color_tag(
                rig, inherited_group_id
            )
            inherited_group_collapsed = fbp_effect_group_collapsed(
                rig, inherited_group_id
            )
    tokens_before = (
        frozenset(_fbp_mixed_effect_tokens(rig)) if inherited_group_id else frozenset()
    )
    if definition.get("kind") == "BASE":
        changed = _fbp_set_enabled(rig, effect_id, True)
        if effect_id == FBP_EFFECT_EMISSION:
            applied = _fbp_apply_emission_effect(rig)
            if not applied:
                _fbp_set_enabled(rig, effect_id, False)
        elif effect_id == FBP_EFFECT_MOTION:
            applied = bool(changed or fbp_effect_is_active(rig, effect_id))
        elif effect_id == FBP_EFFECT_CAMERA_BILLBOARD:
            applied_constraint = _fbp_apply_track_to_camera_constraint(rig)
            applied = bool(applied_constraint or _fbp_track_to_camera_constraint(rig))
            if not applied:
                _fbp_set_enabled(rig, effect_id, False)
        elif effect_id == FBP_EFFECT_LATTICE:
            applied = _fbp_apply_lattice_effect(rig, select=False)
            if not applied:
                _fbp_set_enabled(rig, effect_id, False)
                _fbp_cleanup_incomplete_lattice_setup(rig)
        else:
            applied = changed or fbp_effect_is_active(rig, effect_id)
        if changed or applied:
            _fbp_invalidate_effect_ids_cache(rig)
        if sync_items:
            fbp_sync_effect_items(rig)
    elif definition.get("kind") == "GEOMETRY":
        applied = fbp_apply_geometry_effect(
            rig, effect_id, sync_items=sync_items
        )
    elif definition.get("kind") == "SHADER":
        applied = fbp_apply_shader_effect(
            rig,
            effect_id,
            rebuild=bool(rebuild_shader),
            sync_items=sync_items,
        )
    else:
        return False
    if applied and definition.get("evolve_property"):
        fbp_ensure_effect_animation_state(rig, effect_id)
    if applied and definition.get("mask_source_visibility_aware"):
        fbp_sync_matte_source_visibility(getattr(bpy.context, "scene", None))
    if applied and effect_id in {FBP_EFFECT_CLIPPING_MASK, FBP_EFFECT_LAYER_BLEND}:
        try:
            from .layers import get_primary_fbp_collection
            relation_collection = get_primary_fbp_collection(rig)
        except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
            relation_collection = None
        fbp_schedule_clipping_mask_sync(
            getattr(bpy.context, "scene", None),
            collections=(relation_collection,) if relation_collection is not None else None,
        )
    if applied:
        _fbp_invalidate_mask_target_cache(rig)
        if effect_id == FBP_EFFECT_PIXELATE:
            _fbp_refresh_extrude_pixel_dependency(rig)
    if applied and definition.get("object_mask_aware"):
        try:
            from .object_masks import ensure_object_mask_helper
            helper = ensure_object_mask_helper(
                rig,
                definition.get("object_mask_shape", "SQUARE"),
                context=bpy.context,
                select=bool(select_object_mask_helper),
            )
            for node in _fbp_find_shader_effect_nodes_for_rig(rig, effect_id):
                _fbp_sync_object_mask_helper(rig, effect_id, node, create=False)
            if not helper:
                fbp_remove_effect(rig, effect_id, sync_items=sync_items)
                applied = False
        except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError) as exc:
            fbp_warn("Could not create Shape Mask helper", exc)
            # Do not leave an active Shape Mask effect with no editable helper.
            try:
                fbp_remove_effect(rig, effect_id, sync_items=sync_items)
            except FBP_DATA_ERRORS:
                pass
            applied = False
    if (
        applied
        and inherited_group_id
        and _fbp_effect_chain_key(_fbp_effect_ref_effect_id(group_anchor)) == _fbp_effect_chain_key(effect_id)
    ):
        # Place the new effect directly after the active member, then attach it
        # to the same persistent folder.  If Blender cannot move it safely, the
        # effect remains valid and simply stays outside the group: a member
        # away from its folder would make the folder absorb the rows between.
        # Only a row created by this call joins the group: re-adding an
        # effect that is already on the layer must not move it.
        new_ref = next(
            (
                token for token in _fbp_mixed_effect_tokens(rig)
                if token not in tokens_before
                and _fbp_effect_ref_effect_id(token) == effect_id
            ),
            "",
        )
        if new_ref:
            fbp_move_effect_selection_relative_transactional(
                [rig], [new_ref], group_anchor, "AFTER"
            )
        order = list(_fbp_mixed_effect_tokens(rig))
        placed = (
            bool(new_ref)
            and new_ref in order
            and group_anchor in order
            and order.index(new_ref) == order.index(group_anchor) + 1
        )
        if placed and fbp_set_effect_group_id(
            rig,
            effect_id,
            inherited_group_id,
            instance_id=_fbp_effect_ref_instance_id(new_ref),
            group_name=inherited_group_name,
        ):
            record = _fbp_effect_group_record(rig, inherited_group_id)
            if record is not None:
                try:
                    record.color_tag = inherited_group_color
                    record.collapsed = inherited_group_collapsed
                except FBP_DATA_ERRORS:
                    pass
            fbp_sync_effect_groups(rig)
            if sync_items:
                fbp_sync_effect_items(rig)
    if applied and definition.get("kind") in {"SHADER", "GEOMETRY"}:
        mixed_order = _fbp_mixed_effect_tokens(rig)
        if mixed_order:
            _fbp_apply_mixed_effect_order(rig, mixed_order)
        else:
            _fbp_sync_mixed_effect_pipeline(rig)
    return bool(applied)


def _fbp_capture_multi_shader_effect_states(rig):
    """Capture concrete MULTI nodes before a material replacement destroys them."""
    if rig is None:
        return {}
    effects = {}
    materials = _fbp_plane_materials(rig)
    source_material = materials[0] if materials else None
    if source_material is not None:
        for stage in ("UV", "COLOR", "MASK"):
            for node in _fbp_stage_effect_nodes(source_material, stage):
                effect_id = _fbp_shader_effect_id(node)
                definition = fbp_effect_definition(effect_id)
                if (
                    not effect_id
                    or str(definition.get("instance_policy", "SINGLE") or "SINGLE").upper() != "MULTI"
                ):
                    continue
                instance_id = effect_instance_id(node)
                if not instance_id:
                    continue
                token = effect_instance_token(effect_id, instance_id)
                effects.setdefault(effect_id, []).append({
                    "instance_id": instance_id,
                    "settings": _fbp_capture_shader_instance_settings(node, definition),
                    "visible": not bool(getattr(node, "mute", False)),
                    "render_visible": _fbp_stored_effect_render_visibility(
                        rig, token,
                        _fbp_stored_effect_render_visibility(rig, effect_id, True),
                    ),
                })
    return {
        "effects": effects,
        "orders": {
            stage: list(_fbp_get_rig_shader_stage_order(rig, stage))
            for stage in ("UV", "COLOR", "MASK")
        },
    }


def _fbp_apply_shader_instance_settings(node, definition, settings):
    changed = False
    for prop_name, value in dict(settings or {}).items():
        socket_name = str((definition.get("property_map", {}) or {}).get(prop_name, "") or "")
        socket = _fbp_node_socket(getattr(node, "inputs", ()), socket_name)
        if socket is None or not hasattr(socket, "default_value"):
            continue
        try:
            if isinstance(getattr(socket, "default_value", None), (bool, int, float)):
                socket.default_value = value
            else:
                socket.default_value = tuple(value) if isinstance(value, list) else value
            changed = True
        except FBP_DATA_ERRORS:
            continue
    return changed


def _fbp_restore_multi_shader_effect_states(rig, effect_id, states):
    """Recreate exact concrete instances after owned materials were rebuilt."""
    effect_id = fbp_normalize_effect_id(effect_id)
    definition = fbp_effect_definition(effect_id)
    states = list(states or ())
    if (
        not states
        or definition.get("kind") != "SHADER"
        or str(definition.get("instance_policy", "SINGLE") or "SINGLE").upper() != "MULTI"
    ):
        return False
    materials = [
        material for material in _fbp_plane_materials(rig)
        if _fbp_shader_effect_nodes(material, effect_id=effect_id)
    ]
    if not materials:
        return False
    owner_id = _fbp_effect_stack_owner_id(rig, ensure=True)
    stage = str(definition.get("stage", "") or "")
    changed = False
    for material in materials:
        existing = _fbp_shader_effect_nodes(material, effect_id=effect_id)
        if not existing:
            continue
        keep = existing[0]
        for extra in existing[1:]:
            try:
                material.node_tree.nodes.remove(extra)
                changed = True
            except FBP_DATA_ERRORS:
                pass
        restored_nodes = []
        for index, state in enumerate(states):
            instance_id = str(state.get("instance_id", "") or "")
            if not instance_id:
                continue
            if index == 0:
                node = keep
            else:
                try:
                    node = material.node_tree.nodes.new("ShaderNodeGroup")
                    node.node_tree = getattr(keep, "node_tree", None)
                    node.name = f"FBP Effect • {definition.get('label', effect_id)} • {instance_id[-6:]}"
                    node.label = str(definition.get("label", effect_id))
                    node["fbp_shader_effect_id"] = effect_id
                    changed = True
                except FBP_DATA_ERRORS:
                    continue
            assign_effect_instance_id(
                node, effect_id, instance_id,
                f"{owner_id}:{effect_id}:{instance_id}",
            )
            changed = _fbp_apply_shader_instance_settings(
                node, definition, state.get("settings", {})
            ) or changed
            try:
                muted = not bool(state.get("visible", True))
                if bool(getattr(node, "mute", False)) != muted:
                    node.mute = muted
                    changed = True
            except FBP_DATA_ERRORS:
                pass
            token = effect_instance_token(effect_id, instance_id)
            _fbp_store_effect_visibility(rig, token, bool(state.get("visible", True)))
            _fbp_store_effect_render_visibility(
                rig, token, bool(state.get("render_visible", True))
            )
            restored_nodes.append(node)
        order = [_fbp_shader_node_token(node) for node in restored_nodes]
        _fbp_set_shader_stage_order(material, stage, order)
    return changed


def _fbp_restore_captured_shader_order(rig, payload):
    changed = False
    orders = dict((payload or {}).get("orders", {}) or {})
    for stage in ("UV", "COLOR", "MASK"):
        desired = [str(token or "") for token in orders.get(stage, ()) if str(token or "")]
        if desired:
            _fbp_set_rig_shader_stage_order(rig, stage, desired)
        else:
            desired = _fbp_get_rig_shader_stage_order(rig, stage)
        for material in _fbp_plane_materials(rig):
            active = _fbp_get_shader_stage_order(material, stage)
            order = [token for token in desired if token in active]
            order.extend(token for token in active if token not in order)
            _fbp_set_shader_stage_order(material, stage, order)
            changed = _fbp_rebuild_shader_stage(material, stage) or changed
    return changed


def fbp_capture_custom_shader_effect_states(rig):
    """Capture custom and concrete MULTI shader state before material rebuilds."""
    if not rig:
        return {}
    fbp_refresh_custom_effect_registry(force=False)
    states = {"__fbp_multi_instances__": _fbp_capture_multi_shader_effect_states(rig)}
    for effect_id, definition in tuple(FBP_EFFECT_REGISTRY.items()):
        if not bool(definition.get("custom", False)):
            continue
        if definition.get("kind") != "SHADER":
            continue
        if bool(definition.get("custom_invalid", False)):
            continue
        if not _fbp_find_shader_effect_nodes_for_rig(rig, effect_id):
            continue
        state = _fbp_capture_custom_effect_inputs(rig, effect_id)
        if state:
            states[effect_id] = state
    return states


def fbp_restore_enabled_shader_effects(rig, custom_states=None):
    """Restore shader nodes after a color/gradient material was rebuilt."""
    if not rig:
        return False
    changed = False
    custom_states = dict(custom_states or {})
    multi_payload = dict(custom_states.pop("__fbp_multi_instances__", {}) or {})
    multi_effects = dict(multi_payload.get("effects", {}) or {})
    fbp_refresh_custom_effect_registry(force=False)
    for effect_id, definition in FBP_EFFECT_REGISTRY.items():
        if definition.get("kind") != "SHADER":
            continue
        if not _fbp_is_enabled(rig, effect_id):
            continue
        if not fbp_effect_supported_for_rig(rig, effect_id):
            continue
        applied = fbp_apply_shader_effect(
            rig, effect_id, rebuild=False, sync_items=False
        )
        changed = applied or changed
        if applied and effect_id in multi_effects:
            changed = _fbp_restore_multi_shader_effect_states(
                rig, effect_id, multi_effects[effect_id]
            ) or changed
        if applied and effect_id in custom_states:
            changed = _fbp_apply_custom_effect_inputs(
                rig, effect_id, custom_states[effect_id]
            ) or changed
    changed = _fbp_restore_captured_shader_order(rig, multi_payload) or changed
    if fbp_effect_is_active(rig, FBP_EFFECT_PIXELATE):
        changed = _fbp_refresh_extrude_pixel_dependency(rig) or changed
    fbp_effect_instance_records_for_rig(rig, ensure=True, sync_storage=True)
    fbp_sync_effect_items(rig)
    return changed


def _fbp_clear_effect_auxiliary_state(rig, effect_id):
    changed = False
    for key in (
        _fbp_effect_state_key(effect_id, "input_source"),
        _fbp_effect_state_key(effect_id, "debug"),
        _fbp_effect_mask_target_key(effect_id),
    ):
        try:
            if key in rig:
                del rig[key]
                changed = True
        except (AttributeError, ReferenceError, RuntimeError, TypeError, ValueError, KeyError):
            pass
    if fbp_effect_definition(effect_id).get("evolve_property"):
        changed = fbp_reset_effect_animation_state(rig, effect_id) or changed
    return changed

def _fbp_remove_effect_viewport_controls(rig, effect_id):
    try:
        from .effect_controls import remove_effect_controls
        return bool(remove_effect_controls(rig, effect_id))
    except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
        return False


def fbp_migrate_chroma_key_to_color_key(rig):
    """Convert a pre-merge Chroma Key on ``rig`` into the Color Key mask.

    Chroma Key removed pixels within ``tolerance +/- softness`` of the key;
    Color Key ramps from ``tolerance`` to ``tolerance + softness`` and keeps
    the matched pixels unless inverted, so the values are translated and
    Invert is flipped. A layer that already uses Color Key keeps both: the
    legacy effect still renders and can be removed by hand.
    """
    if not rig or not fbp_effect_is_active(rig, FBP_EFFECT_CHROMA_KEY):
        return False
    if fbp_effect_is_active(rig, FBP_EFFECT_COLOR_MASK):
        return False
    try:
        color = tuple(getattr(rig, "fbp_chroma_key_color", (0.0, 1.0, 0.0, 1.0)))
        tolerance = float(getattr(rig, "fbp_chroma_key_tolerance", 0.20))
        softness = max(0.0, float(getattr(rig, "fbp_chroma_key_softness", 0.08)))
        despill = float(getattr(rig, "fbp_chroma_key_despill", 0.5))
        invert = bool(getattr(rig, "fbp_chroma_key_invert", False))
        visible = fbp_effect_visible_state(rig, FBP_EFFECT_CHROMA_KEY, "")
    except FBP_DATA_ERRORS:
        return False
    if not fbp_add_effect(rig, FBP_EFFECT_COLOR_MASK, inherit_active_group=False):
        return False
    for prop_name, value in (
        ("fbp_color_mask_color", color),
        ("fbp_color_mask_tolerance", max(0.0, tolerance - softness)),
        ("fbp_color_mask_softness", min(1.0, softness * 2.0)),
        ("fbp_color_mask_factor", 1.0),
        ("fbp_color_mask_invert", not invert),
        ("fbp_color_mask_despill", despill),
    ):
        try:
            setattr(rig, prop_name, value)
        except FBP_DATA_ERRORS:
            pass
    fbp_remove_effect(rig, FBP_EFFECT_CHROMA_KEY)
    if not visible:
        try:
            fbp_set_effect_visible(rig, FBP_EFFECT_COLOR_MASK, False)
        except FBP_DATA_ERRORS:
            pass
    fbp_update_shader_effect(rig, FBP_EFFECT_COLOR_MASK)
    return True


def fbp_migrate_chroma_key_scene_rigs():
    """Run the Chroma Key to Color Key migration on every loaded layer."""
    migrated = 0
    key = str(fbp_effect_definition(FBP_EFFECT_CHROMA_KEY).get("enabled_key", "") or "")
    for obj in tuple(getattr(bpy.data, "objects", ()) or ()):
        try:
            if not key or not obj.get(key, False):
                continue
        except FBP_DATA_ERRORS:
            continue
        if fbp_migrate_chroma_key_to_color_key(obj):
            migrated += 1
    return migrated


def fbp_resync_geometry_effects():
    """Push every layer's settings into its Geometry Nodes effect modifiers.

    A swapped effect group keeps the modifier's saved socket values by socket
    identifier, which no longer line up once the group interface changed.
    """
    synced = 0
    for obj in tuple(getattr(bpy.data, "objects", ()) or ()):
        for effect_id in FBP_GEOMETRY_EFFECT_ID_SET:
            key = str(fbp_effect_definition(effect_id).get("enabled_key", "") or "")
            try:
                if not key or not obj.get(key, False):
                    continue
            except FBP_DATA_ERRORS:
                break
            if fbp_update_geometry_effect(obj, effect_id):
                synced += 1
    return synced


def fbp_remove_effect(rig, effect_id, *, sync_items=True):
    effect_id = fbp_normalize_effect_id(effect_id)
    removed_gp_canvas = None
    removed_gp_contract = None
    if effect_id in GP_MASK_EFFECT_IDS:
        try:
            from .grease_pencil_bridge import gp_mask_slot_contract
            removed_gp_contract = gp_mask_slot_contract(effect_id)
            removed_gp_canvas = getattr(rig, removed_gp_contract["canvas"], None)
        except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
            removed_gp_canvas = None
            removed_gp_contract = None
    definition = fbp_effect_definition(effect_id)
    solo_before = (
        tuple(fbp_effect_solo_ids(rig, _fbp_effect_solo_view(effect_id)))
        if definition.get("kind") in {"SHADER", "GEOMETRY"} else ()
    )
    if definition.get("kind") == "BASE":
        if effect_id == FBP_EFFECT_EMISSION:
            changed = _fbp_set_enabled(rig, effect_id, False)
            changed = _fbp_remove_emission_effect(rig) or changed
            changed = _fbp_clear_effect_visibility(rig, effect_id) or changed
            changed = _fbp_clear_effect_render_visibility(rig, effect_id) or changed
            _fbp_clear_effect_auxiliary_state(rig, effect_id)
            _fbp_invalidate_effect_ids_cache(rig)
            if sync_items:
                fbp_sync_effect_items(rig)
            return changed
        if effect_id == FBP_EFFECT_MOTION:
            changed = False
            try:
                from .motion_runtime import remove_motion_effect
                changed = bool(remove_motion_effect(rig))
            except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
                pass
            changed = _fbp_set_enabled(rig, effect_id, False) or changed
            _fbp_invalidate_effect_ids_cache(rig)
            if sync_items:
                fbp_sync_effect_items(rig)
            return changed
        if effect_id == FBP_EFFECT_LATTICE:
            changed = _fbp_remove_lattice_effect(rig)
            changed = _fbp_set_enabled(rig, effect_id, False) or changed
            changed = _fbp_clear_effect_visibility(rig, effect_id) or changed
            changed = _fbp_clear_effect_render_visibility(rig, effect_id) or changed
            _fbp_clear_effect_auxiliary_state(rig, effect_id)
            _fbp_invalidate_effect_ids_cache(rig)
            if sync_items:
                fbp_sync_effect_items(rig)
            return changed
        if effect_id == FBP_EFFECT_CAMERA_BILLBOARD:
            changed = _fbp_remove_track_to_camera_constraint(rig)
            changed = _fbp_set_enabled(rig, effect_id, False) or changed
            changed = _fbp_clear_effect_visibility(rig, effect_id) or changed
            changed = _fbp_clear_effect_render_visibility(rig, effect_id) or changed
            _fbp_clear_effect_auxiliary_state(rig, effect_id)
            _fbp_invalidate_effect_ids_cache(rig)
            if changed:
                _fbp_remove_effect_viewport_controls(rig, effect_id)
            if sync_items:
                fbp_sync_effect_items(rig)
            return changed
        defaults = {
            "fbp_extend_mode": "MIRROR",
            "fbp_extend_top": 0.0, "fbp_extend_left": 0.0,
            "fbp_extend_right": 0.0, "fbp_extend_bottom": 0.0,
            "fbp_crop_top": 0.0, "fbp_crop_left": 0.0,
            "fbp_crop_right": 0.0, "fbp_crop_bottom": 0.0,
        }
        changed = False
        for prop_name in definition.get("property_map", {}):
            if not hasattr(rig, prop_name):
                continue
            changed = fbp_set_rna_property_silent(
                rig, prop_name, defaults.get(prop_name, 0.0)
            ) or changed
        changed = _fbp_set_enabled(rig, effect_id, False) or changed
        changed = _fbp_clear_effect_visibility(rig, effect_id) or changed
        changed = _fbp_clear_effect_render_visibility(rig, effect_id) or changed
        try:
            from .core import update_object_padding_cb
            update_object_padding_cb(rig, bpy.context)
        except FBP_DATA_ERRORS as exc:
            fbp_warn("Could not reset Crop / Extend geometry", exc)
        _fbp_clear_effect_auxiliary_state(rig, effect_id)
        if changed:
            _fbp_invalidate_effect_ids_cache(rig)
        if changed:
            _fbp_remove_effect_viewport_controls(rig, effect_id)
        if sync_items:
            fbp_sync_effect_items(rig)
        return changed
    if definition.get("kind") == "GEOMETRY":
        old_group = fbp_effect_group_id_for_rig(rig, effect_id)
        old_group_name = fbp_effect_group_name(rig, old_group)
        fbp_set_effect_group_id(rig, effect_id, "")
        changed = fbp_remove_geometry_effect(rig, effect_id, sync_items=sync_items)
        if changed:
            _fbp_clear_effect_auxiliary_state(rig, effect_id)
            _fbp_remove_effect_viewport_controls(rig, effect_id)
            _fbp_reconcile_effect_solo_after_removal(rig, effect_id, solo_before)
            mixed_order = _fbp_mixed_effect_tokens(rig)
            if mixed_order:
                _fbp_apply_mixed_effect_order(rig, mixed_order)
            else:
                _fbp_sync_mixed_effect_pipeline(rig)
        elif old_group:
            fbp_set_effect_group_id(
                rig, effect_id, old_group, group_name=old_group_name
            )
        return changed
    if definition.get("kind") == "SHADER":
        old_group = fbp_effect_group_id_for_rig(rig, effect_id)
        old_group_name = fbp_effect_group_name(rig, old_group)
        fbp_set_effect_group_id(rig, effect_id, "")
        changed = fbp_remove_shader_effect(rig, effect_id, sync_items=sync_items)
        if changed:
            _fbp_clear_effect_auxiliary_state(rig, effect_id)
            _fbp_remove_effect_viewport_controls(rig, effect_id)
            for mask_id in tuple(fbp_effect_ids_for_rig(rig)):
                if not _fbp_effect_is_local_mask(mask_id):
                    continue
                try:
                    raw_target = fbp_effect_mask_raw_target_ref(rig, mask_id)
                except FBP_DATA_ERRORS:
                    raw_target = "LAYER"
                if _fbp_effect_ref_effect_id(raw_target) == effect_id:
                    fbp_set_effect_mask_target(rig, mask_id, "LAYER")
            _fbp_reconcile_effect_solo_after_removal(rig, effect_id, solo_before)
            if definition.get("mask_source_aware"):
                source_prop = str(definition.get("mask_source_property", "") or "")
                if definition.get("layer_feature") and source_prop:
                    fbp_set_rna_property_silent(rig, source_prop, None)
                if definition.get("mask_source_visibility_aware"):
                    fbp_sync_matte_source_visibility(
                        getattr(bpy.context, "scene", None)
                    )
            if definition.get("object_mask_aware"):
                try:
                    from .object_masks import remove_object_mask_helper
                    remove_object_mask_helper(rig, definition.get("object_mask_shape", "SQUARE"))
                except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError) as exc:
                    fbp_warn("Could not remove Shape Mask helper", exc)
        elif old_group:
            fbp_set_effect_group_id(
                rig, effect_id, old_group, group_name=old_group_name
            )
        if changed:
            _fbp_invalidate_mask_target_cache(rig)
            if str(definition.get("stage", "") or "") == "MASK":
                mask_payload, _mask_error = _fbp_mask_stack_payload(rig)
                if mask_payload is not None:
                    operations = dict(
                        mask_payload.get("operations", {}) or {}
                    )
                    operations.pop(effect_id, None)
                    mask_payload["operations"] = operations
                    _fbp_store_mask_stack_payload(rig, mask_payload)
            if effect_id == FBP_EFFECT_PIXELATE:
                _fbp_refresh_extrude_pixel_dependency(rig, force=True)
            if removed_gp_contract is not None:
                try:
                    setattr(rig, removed_gp_contract["canvas"], None)
                    setattr(rig, removed_gp_contract["image"], None)
                    setattr(rig, removed_gp_contract["source_type"], "FILE")
                    setattr(rig, removed_gp_contract["path"], "")
                    from .grease_pencil_bridge import (
                        is_gp_mask_canvas, gp_mask_bindings, delete_gp_canvas,
                    )
                    deleting = bool(removed_gp_canvas.get("fbp_gp_deleting", False)) if removed_gp_canvas is not None else False
                    if (
                        is_gp_mask_canvas(removed_gp_canvas)
                        and not deleting
                        and not gp_mask_bindings(removed_gp_canvas)
                    ):
                        delete_gp_canvas(bpy.context, removed_gp_canvas)
                except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
                    pass
            mixed_order = _fbp_mixed_effect_tokens(rig)
            if mixed_order:
                _fbp_apply_mixed_effect_order(rig, mixed_order)
            else:
                _fbp_sync_mixed_effect_pipeline(rig)
        return changed
    return False


def _fbp_geometry_effect_id_for_modifier(modifier):
    if not modifier or getattr(modifier, "type", "") != "NODES":
        return ""
    node_group = getattr(modifier, "node_group", None)
    try:
        declared = fbp_normalize_effect_id(node_group.get("fbp_effect_id", "")) if node_group else ""
        if (
            declared in FBP_EFFECT_REGISTRY
            and fbp_effect_definition(declared).get("kind") == "GEOMETRY"
        ):
            return declared
    except FBP_DATA_ERRORS:
        pass
    if not node_group:
        return ""
    # Same rules as _fbp_group_matches, with the group tags read once instead
    # of once per registered Mesh effect for every unmanaged modifier.
    try:
        tagged_effect = fbp_normalize_effect_id(node_group.get("fbp_effect_id", ""))
        tagged_asset = str(node_group.get("fbp_effect_asset_id", "") or "")
        geometry_asset = _fbp_node_group_asset_id(node_group)
    except FBP_DATA_ERRORS:
        return ""
    if not (tagged_effect or tagged_asset or geometry_asset):
        return ""
    for effect_id, definition in FBP_EFFECT_REGISTRY.items():
        if definition.get("kind") != "GEOMETRY":
            continue
        asset_id = str(definition.get("asset_id", "") or "")
        if not asset_id:
            continue
        if tagged_asset == asset_id or geometry_asset == asset_id:
            return effect_id
        if not bool(definition.get("builtin", False)) and tagged_effect == effect_id:
            return effect_id
    return ""


def _fbp_modifier_pointer(modifier):
    try:
        return int(modifier.as_pointer())
    except FBP_DATA_ERRORS:
        return 0


def _fbp_apply_modifier_order_exact(plane, desired_order):
    """Apply an exact modifier order by identity, rolling back on failure."""
    original = list(getattr(plane, "modifiers", ()))
    desired_order = list(desired_order or ())
    original_keys = [_fbp_modifier_pointer(item) for item in original]
    desired_keys = [_fbp_modifier_pointer(item) for item in desired_order]
    if (
        len(original) != len(desired_order)
        or not all(original_keys)
        or sorted(original_keys) != sorted(desired_keys)
    ):
        return False
    if original_keys == desired_keys:
        return True

    def apply(order):
        for target_index, target_modifier in enumerate(order):
            target_key = _fbp_modifier_pointer(target_modifier)
            current_index = next(
                (
                    index for index, modifier in enumerate(plane.modifiers)
                    if _fbp_modifier_pointer(modifier) == target_key
                ),
                -1,
            )
            if current_index < 0:
                return False
            if current_index != target_index:
                plane.modifiers.move(current_index, target_index)
        return [
            _fbp_modifier_pointer(item) for item in plane.modifiers
        ] == [_fbp_modifier_pointer(item) for item in order]

    try:
        if not apply(desired_order):
            apply(original)
            return False
        plane.update_tag()
        return True
    except FBP_DATA_ERRORS:
        try:
            apply(original)
        except FBP_DATA_ERRORS:
            pass
        return False


def _fbp_reorder_geometry_effect_modifiers(plane, ordered_effect_modifiers):
    """Reorder only FBP Mesh-effect slots; unmanaged modifiers never change slots."""
    if plane is None:
        return False
    original = list(getattr(plane, "modifiers", ()))
    effect_slots = [
        index for index, modifier in enumerate(original)
        if _fbp_geometry_effect_id_for_modifier(modifier)
    ]
    current_effects = [original[index] for index in effect_slots]
    requested = []
    requested_keys = set()
    current_keys = {_fbp_modifier_pointer(item) for item in current_effects}
    for modifier in list(ordered_effect_modifiers or ()):
        key = _fbp_modifier_pointer(modifier)
        if key in current_keys and key not in requested_keys:
            requested.append(modifier)
            requested_keys.add(key)
    requested.extend(
        modifier for modifier in current_effects
        if _fbp_modifier_pointer(modifier) not in requested_keys
    )
    if len(requested) != len(effect_slots):
        return False
    desired = list(original)
    for slot, modifier in zip(effect_slots, requested, strict=False):
        desired[slot] = modifier
    return _fbp_apply_modifier_order_exact(plane, desired)


def _fbp_shader_order_token_for_effect(rig, effect_id, order):
    """Resolve one effect request to a concrete stage-order token.

    SINGLE effects keep their effect ID. A unique MULTI occurrence is safe to
    resolve automatically; repeated occurrences require the active instance.
    """
    effect_id = fbp_normalize_effect_id(effect_id)
    order = list(order or ())
    matches = [
        token for token in order
        if _fbp_shader_token_effect_id(token) == effect_id
    ]
    if not matches:
        return ""
    if len(matches) == 1:
        return matches[0]
    if fbp_active_effect_id(rig) == effect_id:
        active_token = effect_instance_token(
            effect_id, fbp_active_effect_instance_id(rig)
        )
        if active_token in matches:
            return active_token
    if effect_id in matches:
        return effect_id
    return ""


def _fbp_move_shader_effect_to_stage_edge(
    rig, effect_id, *, first=True, rebuild=True, sync_items=True
):
    """Move one shader effect to a stage edge without iterative rebuilds."""
    effect_id = fbp_normalize_effect_id(effect_id)
    definition = fbp_effect_definition(effect_id)
    if definition.get("kind") != "SHADER":
        return False
    stage = str(definition.get("stage", "") or "")
    materials = [
        material for material in _fbp_plane_materials(rig)
        if _fbp_shader_effect_nodes(material, effect_id=effect_id)
    ]
    if not materials:
        return False

    order = _fbp_get_rig_shader_stage_order(rig, stage)
    order_token = _fbp_shader_order_token_for_effect(rig, effect_id, order)
    if not order_token:
        order = _fbp_get_shader_stage_order(materials[0], stage)
        order_token = _fbp_shader_order_token_for_effect(rig, effect_id, order)
    if not order_token:
        return False

    desired = [item for item in order if item != order_token]
    if first:
        desired.insert(0, order_token)
    else:
        desired.append(order_token)
    if desired == order:
        return True

    _fbp_set_rig_shader_stage_order(rig, stage, desired)
    rebuilt = False
    for material in materials:
        active = _fbp_get_shader_stage_order(material, stage)
        material_order = [item for item in desired if item in active]
        material_order.extend(item for item in active if item not in material_order)
        _fbp_set_shader_stage_order(material, stage, material_order)
        if rebuild:
            rebuilt = _fbp_rebuild_shader_stage(material, stage) or rebuilt
        else:
            rebuilt = True
    if sync_items:
        fbp_sync_effect_items(rig)
    return rebuilt or bool(materials)


def fbp_move_effect(rig, effect_id, direction, *, sync_items=True):
    """Move an effect in its real Blender evaluation chain.

    ``sync_items=False`` is reserved for grouped transactions so several real
    Blender moves can be committed before rebuilding the transient UI mirror.
    """
    effect_id = fbp_normalize_effect_id(effect_id)
    definition = fbp_effect_definition(effect_id)
    direction = -1 if str(direction).upper() == "UP" else 1
    if definition.get("kind") == "GEOMETRY":
        plane = _fbp_plane(rig)
        modifier = fbp_find_effect_modifier(rig, effect_id)
        if not plane or not modifier:
            return False
        ordered = []
        try:
            for index, item in enumerate(plane.modifiers):
                item_effect = _fbp_geometry_effect_id_for_modifier(item)
                if item_effect:
                    ordered.append((index, item, item_effect))
        except FBP_DATA_ERRORS:
            return False
        current = next((index for index, data in enumerate(ordered) if data[1] == modifier), -1)
        target = current + direction
        if current < 0 or target < 0 or target >= len(ordered):
            return False
        try:
            requested = [data[1] for data in ordered]
            requested[current], requested[target] = requested[target], requested[current]
            if not _fbp_reorder_geometry_effect_modifiers(plane, requested):
                return False
            _fbp_invalidate_effect_ids_cache(rig)
            if sync_items:
                fbp_sync_effect_items(rig)
            return True
        except FBP_DATA_ERRORS:
            return False

    if definition.get("kind") == "SHADER":
        stage = str(definition.get("stage", ""))
        materials = [
            material for material in _fbp_plane_materials(rig)
            if _fbp_shader_effect_nodes(material, effect_id=effect_id)
        ]
        if not materials:
            return False

        # Compute the new order once and push it to every material. Procedural
        # frame materials can otherwise drift into different effect orders when
        # one material has a temporarily incomplete stored order.
        order = _fbp_get_rig_shader_stage_order(rig, stage)
        order_token = _fbp_shader_order_token_for_effect(rig, effect_id, order)
        if not order_token:
            order = _fbp_get_shader_stage_order(materials[0], stage)
            order_token = _fbp_shader_order_token_for_effect(rig, effect_id, order)
        if not order_token:
            return False
        current = order.index(order_token)
        target = current + direction
        if target < 0 or target >= len(order):
            return False
        order[current], order[target] = order[target], order[current]
        _fbp_set_rig_shader_stage_order(rig, stage, order)

        moved = False
        for material in materials:
            active = _fbp_get_shader_stage_order(material, stage)
            material_order = [item for item in order if item in active]
            material_order.extend(item for item in active if item not in material_order)
            _fbp_set_shader_stage_order(material, stage, material_order)
            moved = _fbp_rebuild_shader_stage(material, stage) or moved
        if moved:
            _fbp_invalidate_effect_ids_cache(rig)
            if sync_items:
                fbp_sync_effect_items(rig)
        return moved
    return False


def fbp_reapply_all_effects(rig, custom_states=None):
    """Restore shader routing and alpha images after an FBP material rebuild."""
    if not rig:
        return False
    changed = False
    custom_states = dict(custom_states or {})
    multi_payload = dict(custom_states.pop("__fbp_multi_instances__", {}) or {})
    multi_effects = dict(multi_payload.get("effects", {}) or {})
    fbp_refresh_custom_effect_registry(force=False)
    for effect_id, definition in FBP_EFFECT_REGISTRY.items():
        if definition.get("kind") == "SHADER" and (
            _fbp_is_enabled(rig, effect_id)
            or bool(_fbp_find_shader_effect_nodes_for_rig(rig, effect_id))
        ):
            applied = fbp_apply_shader_effect(
                rig, effect_id, rebuild=False, sync_items=False
            )
            changed = applied or changed
            if applied and effect_id in multi_effects:
                changed = _fbp_restore_multi_shader_effect_states(
                    rig, effect_id, multi_effects[effect_id]
                ) or changed
            if applied and effect_id in custom_states:
                changed = _fbp_apply_custom_effect_inputs(
                    rig, effect_id, custom_states[effect_id]
                ) or changed
    # Restore concrete instance order after a material rebuild.
    changed = _fbp_restore_captured_shader_order(rig, multi_payload) or changed
    for effect_id, definition in FBP_EFFECT_REGISTRY.items():
        if definition.get("kind") != "GEOMETRY":
            continue
        modifier = fbp_find_effect_modifier(rig, effect_id)
        if not modifier:
            continue
        _fbp_remove_duplicate_effect_modifiers(rig, effect_id, modifier)
        previous_group = getattr(modifier, "node_group", None)
        try:
            modifier.name = str(definition.get("modifier_name", definition.get("label", effect_id)))
        except FBP_DATA_ERRORS:
            pass
        source_group = (
            fbp_load_mesh_wiggle_group()
            if effect_id == FBP_EFFECT_MESH_WIGGLE
            else _fbp_load_effect_group(effect_id)
        )
        if definition.get("alpha_aware") or definition.get("private_group"):
            owned_group = _fbp_owned_geometry_group(
                rig, effect_id, source_group, previous_group
            )
            if owned_group and owned_group != previous_group:
                try:
                    modifier.node_group = owned_group
                    changed = True
                    if (
                        previous_group
                        and bool(previous_group.get("fbp_private_effect_group", False))
                        and previous_group.users == 0
                    ):
                        _fbp_remove_node_group(previous_group)
                except FBP_DATA_ERRORS:
                    pass
        elif source_group and previous_group != source_group:
            try:
                current_asset = str(previous_group.get("fbp_effect_asset_id", "") or "") if previous_group else ""
                desired_asset = str(definition.get("asset_id", "") or "")
                if current_asset != desired_asset:
                    modifier.node_group = source_group
                    changed = True
            except FBP_DATA_ERRORS:
                pass
        try:
            viewport_visible = _fbp_stored_effect_visibility(rig, effect_id, True)
            render_visible = _fbp_stored_effect_render_visibility(rig, effect_id, True)
            if bool(getattr(modifier, "show_viewport", True)) != viewport_visible:
                modifier.show_viewport = viewport_visible
                changed = True
            if bool(getattr(modifier, "show_render", True)) != render_visible:
                modifier.show_render = render_visible
                changed = True
        except FBP_DATA_ERRORS:
            pass
        changed = fbp_update_geometry_effect(rig, effect_id, modifier) or changed
    changed = fbp_sync_emission_effect_surface(rig) or changed
    changed = fbp_sync_layer_opacity_effect(rig) or changed
    fbp_effect_instance_records_for_rig(rig, ensure=True, sync_storage=True)
    fbp_sync_effect_items(rig)
    return changed


def _fbp_callback_targets(rig, context, *, effect_id=""):
    if rig is None:
        return []
    selected = _fbp_selected_rigs(context) if context is not None else []
    targets = selected if selected and rig in selected else [rig]
    if effect_id:
        effect_id = fbp_normalize_effect_id(effect_id)
        targets = [target for target in targets if fbp_effect_is_active(target, effect_id)]
    return targets


def update_text_matrix_grid_settings_cb(self, context):
    """Apply viewport grid changes once after a Text Matrix quality preset.

    The quality callback changes columns and resets rows to Auto silently. This
    wrapper mirrors those values to selected rigs and pushes both modifier
    sockets in a single Geometry Nodes update.
    """
    if fbp_is_silent_property_update(self):
        return
    names = (
        "fbp_text_matrix_quality",
        "fbp_text_matrix_viewport_columns",
        "fbp_text_matrix_viewport_rows",
        "fbp_text_matrix_render_columns",
        "fbp_text_matrix_render_rows",
    )
    targets = _fbp_callback_targets(self, context, effect_id=FBP_EFFECT_TEXT_MATRIX)
    for rig in targets:
        if rig != self:
            for name in names:
                try:
                    fbp_set_rna_property_silent(rig, name, getattr(self, name))
                except FBP_DATA_ERRORS:
                    continue
        fbp_update_geometry_effect(
            rig,
            FBP_EFFECT_TEXT_MATRIX,
            sync_alpha=False,
            property_names={
                "fbp_text_matrix_viewport_columns",
                "fbp_text_matrix_viewport_rows",
            },
        )


def _fbp_sanitize_mask_source_for_target(target, value, definition, scene=None):
    """Return a valid matte source for one target in a multi-edit transaction.

    A shared PointerProperty update can otherwise assign one selected layer as
    its own matte source. Keep the source for compatible targets, but clear it
    for the source layer itself or for targets from another Scene.
    """
    source_prop = str(definition.get("mask_source_property", "") or "")
    if not source_prop:
        return value
    source = value
    if not source or source is target:
        return None
    try:
        if not bool(getattr(source, "is_fbp_control", False)):
            return None
        if bool(getattr(source, "fbp_is_color_plane", False)):
            return None
        if not _fbp_objects_share_scene(target, source, scene=scene):
            return None
    except FBP_DATA_ERRORS:
        return None
    return source


_FBP_TEXT_MATRIX_MANUAL_GRID_PROPS = frozenset({
    "fbp_text_matrix_viewport_columns",
    "fbp_text_matrix_viewport_rows",
    "fbp_text_matrix_render_columns",
    "fbp_text_matrix_render_rows",
})
_FBP_TEXT_MATRIX_PLAYBACK_PROPS = frozenset({
    "fbp_text_matrix_auto_playback_limit",
    "fbp_text_matrix_playback_columns",
    "fbp_text_matrix_playback_rows",
})
def fbp_update_effect_instance_setting_value(
    rig, effect_id, instance_id, prop_name, value, *, scene=None
):
    """Apply one captured scalar edit to one concrete shader instance."""
    effect_id = fbp_normalize_effect_id(effect_id)
    instance_id = str(instance_id or "")
    definition = fbp_effect_definition(effect_id)
    if (
        rig is None or not instance_id
        or not fbp_effect_multi_instance_enabled(effect_id)
        or definition.get("kind") != "SHADER"
        or prop_name not in fbp_effect_allowed_property_names(effect_id)
    ):
        return False
    speed_prop = str(definition.get("evolve_speed_property", "") or "")
    if prop_name == speed_prop:
        animation = fbp_effect_instance_animation_item(
            rig, effect_id, instance_id, ensure=True
        )
        if animation is None:
            return False
        fbp_set_rna_property_silent(animation, "speed", value)
    else:
        channel = fbp_effect_instance_channel(
            rig, effect_id, instance_id, prop_name, ensure=True, prefer_node=True
        )
        if channel is None:
            return False
        fbp_set_rna_property_silent(
            channel, _fbp_instance_channel_value_attr(channel), value
        )
    changed = fbp_update_shader_effect(
        rig,
        effect_id,
        scene=scene,
        property_names={prop_name},
        instance_id=instance_id,
    )
    _fbp_invalidate_effect_runtime_profile(rig)
    return changed


def update_effect_setting_cb(self, context, effect_id, prop_name, instance_id=""):
    effect_id = fbp_normalize_effect_id(effect_id)
    if fbp_is_silent_property_update(self):
        return
    definition = fbp_effect_definition(effect_id)
    allowed = fbp_effect_allowed_property_names(effect_id)
    if prop_name not in allowed:
        return
    try:
        value = getattr(self, prop_name)
    except (AttributeError, ReferenceError):
        return
    instance_id = str(instance_id or "")
    if instance_id:
        return fbp_update_effect_instance_setting_value(
            self,
            effect_id,
            instance_id,
            prop_name,
            value,
            scene=getattr(context, "scene", None) if context else None,
        )
    if effect_id == FBP_EFFECT_SURFACE_CONFORM and prop_name == "fbp_surface_conform_target":
        plane = _fbp_plane(self, repair=False)
        if value is self or value is plane:
            value = None
            fbp_set_rna_property_silent(self, prop_name, None)
    targets = _fbp_callback_targets(self, context, effect_id=effect_id)
    text_matrix_manual_grid = _FBP_TEXT_MATRIX_MANUAL_GRID_PROPS
    text_matrix_playback_controls = _FBP_TEXT_MATRIX_PLAYBACK_PROPS
    scene = getattr(context, "scene", None) if context else None
    for rig in targets:
        target_value = value
        if prop_name == str(definition.get("mask_source_property", "") or ""):
            target_value = _fbp_sanitize_mask_source_for_target(
                rig, value, definition, scene=scene
            )
        if effect_id == FBP_EFFECT_SURFACE_CONFORM and prop_name == "fbp_surface_conform_target":
            plane = _fbp_plane(rig, repair=False)
            if value is rig or value is plane:
                target_value = None
        if rig != self or target_value is not value:
            fbp_set_rna_property_silent(rig, prop_name, target_value)
        instance_id = (
            fbp_active_effect_instance_id(rig)
            if _fbp_effect_uses_multi_instances(effect_id)
            and fbp_active_effect_id(rig) == effect_id
            else ""
        )
        if instance_id and definition.get("kind") == "SHADER":
            fbp_update_effect_instance_setting_value(
                rig, effect_id, instance_id, prop_name, target_value, scene=scene
            )
            continue
        if effect_id == FBP_EFFECT_TEXT_MATRIX and prop_name in text_matrix_manual_grid:
            fbp_set_rna_property_silent(rig, "fbp_text_matrix_quality", "CUSTOM")
        if effect_id == FBP_EFFECT_MESH_WIGGLE and bool(getattr(rig, "fbp_mesh_wiggle_unique_seed", False)):
            fbp_assign_mesh_wiggle_layer_seed(rig)
        if effect_id == FBP_EFFECT_EMISSION:
            fbp_sync_emission_effect_surface(rig)
        elif definition.get("kind") == "GEOMETRY":
            requested = {prop_name}
            if effect_id == FBP_EFFECT_THICKNESS and prop_name in {
                "fbp_thickness_grid_mode",
                "fbp_thickness_follow_pixelate",
                "fbp_thickness_safe_grid",
            }:
                requested = {
                    "fbp_thickness_viewport_pixels_x",
                    "fbp_thickness_viewport_pixels_y",
                }
            if effect_id == FBP_EFFECT_TEXT_MATRIX and prop_name in text_matrix_playback_controls:
                requested = {
                    "fbp_text_matrix_viewport_columns",
                    "fbp_text_matrix_viewport_rows",
                }
            for contract in _fbp_quality_contracts(definition):
                playback_property = str(contract.get("playback_property", ""))
                render_property = str(contract.get("render_property", ""))
                viewport_property = str(contract.get("viewport_property", ""))
                if prop_name == playback_property:
                    requested = {viewport_property} if _FBP_EFFECT_PLAYBACK_ACTIVE and viewport_property else set()
                    break
                if prop_name == render_property:
                    requested = set()
                    break
            if effect_id == FBP_EFFECT_THICKNESS and requested & {
                "fbp_thickness_viewport_pixels_x",
                "fbp_thickness_viewport_pixels_y",
            }:
                # Auto Height and Follow Pixelate make X and Y one logical
                # contract. Refresh both sockets after either axis changes so
                # the generated geometry cannot retain a stale vertical grid.
                requested = {
                    "fbp_thickness_viewport_pixels_x",
                    "fbp_thickness_viewport_pixels_y",
                }
            if requested:
                fbp_update_geometry_effect(
                    rig,
                    effect_id,
                    sync_alpha=False,
                    property_names=requested,
                )
        else:
            fbp_update_shader_effect(
                rig,
                effect_id,
                property_names={prop_name},
            )
            if effect_id == FBP_EFFECT_PIXELATE:
                _fbp_refresh_extrude_pixel_dependency(rig)
        if (
            prop_name == str(definition.get("evolve_speed_property", "") or "")
            and bool(fbp_read_effect_animation_state(rig, effect_id).get("evolve", False))
        ):
            evolve_property = str(definition.get("evolve_property", "") or "")
            if evolve_property:
                if definition.get("kind") == "GEOMETRY":
                    fbp_update_geometry_effect(
                        rig, effect_id, sync_alpha=False,
                        property_names={evolve_property},
                    )
                else:
                    fbp_update_shader_effect(
                        rig, effect_id, property_names={evolve_property}
                    )
    if definition.get("mask_source_visibility_aware") and prop_name in {
        definition.get("mask_source_property", ""),
        "fbp_alpha_matte_source_display",
        "fbp_luma_matte_source_display",
    }:
        fbp_sync_matte_source_visibility(scene)


def update_effect_animation_setting_cb(self, context, effect_id, suffix):
    effect_id = fbp_normalize_effect_id(effect_id)
    if fbp_is_silent_property_update(self):
        return
    definition = fbp_effect_definition(effect_id)
    key = (
        _fbp_effect_evolution_speed_property(effect_id, definition)
        if suffix == "speed" else _fbp_animation_key(effect_id, suffix)
    )
    try:
        value = getattr(self, key)
    except (AttributeError, ReferenceError):
        return
    targets = _fbp_callback_targets(self, context, effect_id=effect_id)
    for rig in targets:
        if rig != self and hasattr(rig, key):
            fbp_set_rna_property_silent(rig, key, value)
        state = fbp_ensure_effect_animation_state(rig, effect_id)
        if suffix == "evolve" or bool(state.get("evolve", False)):
            evolve_property = str(definition.get("evolve_property", "") or "")
            property_names = {evolve_property} if evolve_property else None
            if definition.get("kind") == "GEOMETRY":
                fbp_update_geometry_effect(
                    rig,
                    effect_id,
                    sync_alpha=False,
                    property_names=property_names,
                )
            else:
                fbp_update_shader_effect(
                    rig,
                    effect_id,
                    property_names=property_names,
                )


def update_mesh_wiggle_enabled_cb(self, context):
    if fbp_is_silent_property_update(self):
        return
    enabled = bool(getattr(self, "fbp_mesh_wiggle_enabled", False))
    for rig in _fbp_callback_targets(self, context):
        if rig != self:
            fbp_set_rna_property_silent(rig, "fbp_mesh_wiggle_enabled", enabled)
        if enabled:
            fbp_apply_mesh_wiggle(rig)
        else:
            fbp_remove_mesh_wiggle(rig)


def fbp_effect_visible_state(rig, effect_id, instance_id=""):
    effect_id = fbp_normalize_effect_id(effect_id)
    definition = fbp_effect_definition(effect_id)
    if effect_id == FBP_EFFECT_CAMERA_BILLBOARD:
        constraint = _fbp_track_to_camera_constraint(rig)
        return bool(
            fbp_effect_is_active(rig, effect_id)
            and constraint is not None
            and not bool(getattr(constraint, "mute", False))
        )
    if effect_id == FBP_EFFECT_LATTICE:
        plane = _fbp_plane(rig)
        modifier = _fbp_lattice_modifier(plane)
        detail = _fbp_lattice_detail_modifier(plane)
        return bool(
            fbp_effect_is_active(rig, effect_id)
            and modifier is not None
            and bool(getattr(modifier, "show_viewport", True))
            and (detail is None or bool(getattr(detail, "show_viewport", True)))
        )
    if definition.get("kind") == "BASE":
        return fbp_effect_is_active(rig, effect_id)
    profile = _fbp_effect_runtime_profile(rig)
    if effect_id not in profile.get("active_ids", ()):
        return False
    if definition.get("kind") == "GEOMETRY":
        modifier = profile.get("geometry_modifiers", {}).get(effect_id)
        if modifier is None:
            modifier = fbp_find_effect_modifier(rig, effect_id)
        if modifier is not None and not bool(getattr(modifier, "show_viewport", True)):
            # Paused by Light Playback only: the effect is still switched on.
            plane = _fbp_plane(rig, repair=False)
            if plane is not None and fbp_playback_suspended_modifier(plane, modifier.name):
                return True
        return bool(modifier and getattr(modifier, "show_viewport", True))
    instance_id = str(instance_id or "")
    nodes = (
        _fbp_find_shader_effect_nodes_for_rig(rig, effect_id, instance_id=instance_id)
        if instance_id else profile.get("shader_nodes", {}).get(effect_id, ())
    )
    if not nodes:
        nodes = _fbp_find_shader_effect_nodes_for_rig(
            rig, effect_id, instance_id=instance_id
        )
    return bool(nodes) and all(not bool(getattr(node, "mute", False)) for node in nodes)


def fbp_set_effect_visible(rig, effect_id, visible, instance_id="", *, refresh_mixed=True):
    effect_id = fbp_normalize_effect_id(effect_id)
    definition = fbp_effect_definition(effect_id)
    visible = bool(visible)
    if effect_id == FBP_EFFECT_CAMERA_BILLBOARD:
        changed = _fbp_store_effect_visibility(rig, effect_id, visible)
        constraint = _fbp_track_to_camera_constraint(rig)
        if constraint is not None and bool(getattr(constraint, "mute", False)) == visible:
            constraint.mute = not visible
            changed = True
        return changed
    if effect_id == FBP_EFFECT_LATTICE:
        changed = _fbp_store_effect_visibility(rig, effect_id, visible)
        plane = _fbp_plane(rig)
        modifier = _fbp_lattice_modifier(plane)
        detail = _fbp_lattice_detail_modifier(plane)
        for owned_modifier in (modifier, detail):
            if owned_modifier is not None and bool(getattr(owned_modifier, "show_viewport", True)) != visible:
                owned_modifier.show_viewport = visible
                changed = True
        helper = _fbp_lattice_object(rig)
        if helper is not None:
            try:
                show_cage = bool(getattr(rig, "fbp_lattice_show_cage", True))
                target_hide_viewport = not visible
                target_hidden = not bool(visible and show_cage)
                if bool(getattr(helper, "hide_viewport", False)) != target_hide_viewport:
                    helper.hide_viewport = target_hide_viewport
                    changed = True
                if bool(helper.hide_get()) != target_hidden:
                    helper.hide_set(target_hidden)
                    changed = True
            except FBP_DATA_ERRORS:
                pass
        return changed
    if definition.get("kind") == "BASE":
        return False
    instance_id = str(instance_id or "")
    visibility_key = effect_instance_token(effect_id, instance_id) if instance_id else effect_id
    stored_changed = _fbp_store_effect_visibility(rig, visibility_key, visible)
    if definition.get("kind") == "GEOMETRY":
        modifier = fbp_find_effect_modifier(rig, effect_id)
        if not modifier:
            return stored_changed
        changed = stored_changed
        plane = _fbp_plane(rig, repair=False)
        if plane is not None:
            fbp_forget_playback_suspended_modifier(plane, getattr(modifier, "name", ""))
        if bool(getattr(modifier, "show_viewport", True)) != visible:
            modifier.show_viewport = visible
            changed = True
        return changed
    nodes = _fbp_find_shader_effect_nodes_for_rig(
        rig, effect_id, instance_id=instance_id
    )
    if not nodes:
        return stored_changed
    muted = not visible
    changed = stored_changed
    for node in nodes:
        if bool(getattr(node, "mute", False)) != muted:
            node.mute = muted
            changed = True
    if changed and _fbp_effect_is_local_mask(effect_id):
        target_effect_id = fbp_effect_mask_target(rig, effect_id)
        if target_effect_id != "LAYER":
            for material in _fbp_plane_materials(rig):
                changed = _fbp_rebuild_mask_target_routing(
                    material, target_effect_id, target_effect_id
                ) or changed
    if changed and _fbp_effect_is_global_mask(rig, effect_id):
        # A muted group node passes its alpha input through, which would
        # multiply the layer alpha by itself. Rewire the Mask Stack instead.
        for material in _fbp_plane_materials(rig):
            _fbp_rebuild_shader_stage(material, "MASK")
    if changed and effect_id == FBP_EFFECT_PIXELATE:
        changed = _fbp_refresh_extrude_pixel_dependency(
            rig, force=True
        ) or changed
    if changed and refresh_mixed:
        # Mesh effects and mixed-stack stages read copied composite materials;
        # mirror the new mute state so hiding an effect is visible there too.
        _fbp_refresh_geometry_source_materials(rig)
    return changed


_FBP_EFFECT_SOLO_PROP_2D = "fbp_effect_solo_ids_2d"
_FBP_EFFECT_SOLO_PROP_MASK = "fbp_effect_solo_ids_mask"
_FBP_EFFECT_SOLO_PROP_3D = "fbp_effect_solo_ids_3d"


def _fbp_effect_solo_view(effect_id):
    category = str(fbp_effect_definition(effect_id).get("category", "2D") or "2D")
    if category == "3D":
        return "3D"
    if category == "MASK":
        return "MASK"
    return "2D"


def _fbp_effect_solo_prop(view):
    view = str(view or "2D")
    if view == "3D":
        return _FBP_EFFECT_SOLO_PROP_3D
    if view == "MASK":
        return _FBP_EFFECT_SOLO_PROP_MASK
    return _FBP_EFFECT_SOLO_PROP_2D


def _fbp_effect_solo_candidates(rig, view):
    """Return every concrete effect token eligible for one Solo view.

    The UI collection can temporarily lag behind the real shader/modifier stack
    after duplication, repair or Undo. Build from instance records first,
    then supplement it from the authoritative runtime effect IDs so Solo keeps
    working for every compatible effect represented in the list.
    """
    view = str(view or "2D")
    categories = {"3D"} if view == "3D" else ({"MASK"} if view == "MASK" else {"BASE", "2D"})
    result = []
    seen = set()

    def append_token(effect_id, instance_id=""):
        effect_id = fbp_normalize_effect_id(effect_id)
        definition = fbp_effect_definition(effect_id)
        if (
            not effect_id
            or str(definition.get("category", "2D") or "2D") not in categories
            or (
                definition.get("kind") not in {"SHADER", "GEOMETRY"}
                and effect_id != FBP_EFFECT_LATTICE
            )
        ):
            return
        if not _fbp_effect_uses_multi_instances(effect_id):
            instance_id = ""
        token = _fbp_effect_ref(effect_id, instance_id)
        if token and token not in seen and _fbp_effect_ref_is_active(rig, token):
            result.append(token)
            seen.add(token)

    try:
        records = fbp_effect_instance_records_for_rig(
            rig, ensure=False, sync_storage=False
        )
    except FBP_DATA_ERRORS:
        records = ()
    for record in records:
        append_token(record.get("effect_id", ""), record.get("instance_id", ""))

    try:
        runtime_ids = tuple(fbp_effect_ids_for_rig(rig))
    except FBP_DATA_ERRORS:
        runtime_ids = ()
    for effect_id in runtime_ids:
        if _fbp_effect_uses_multi_instances(effect_id):
            try:
                chain_tokens = _fbp_effect_chain_tokens(
                    rig, _fbp_effect_chain_key(effect_id)
                )
            except FBP_DATA_ERRORS:
                chain_tokens = ()
            matching = [
                token for token in chain_tokens
                if _fbp_effect_ref_effect_id(token) == effect_id
            ]
            if matching:
                for token in matching:
                    append_token(*_fbp_effect_ref_parts(token))
                continue
        append_token(effect_id)
    return tuple(result)



def fbp_effect_solo_ids(rig, view):
    """Return validated concrete Solo tokens for one Effects view."""
    key = _fbp_effect_solo_prop(view)
    try:
        raw = rig.get(key, "[]")
        values = json.loads(raw) if isinstance(raw, str) else list(raw or ())
    except (AttributeError, ReferenceError, TypeError, ValueError, json.JSONDecodeError):
        values = ()
    candidates = set(_fbp_effect_solo_candidates(rig, view))
    result = []
    seen = set()
    for value in values:
        effect_id, instance_id = _fbp_effect_ref_parts(value)
        token = _fbp_effect_ref(effect_id, instance_id)
        if token and token in candidates and token not in seen:
            result.append(token)
            seen.add(token)
    return tuple(result)



def fbp_effect_is_soloed(rig, effect_id, instance_id=""):
    token = _fbp_effect_ref(effect_id, instance_id)
    effect_id = fbp_normalize_effect_id(effect_id)
    return bool(
        token
        and token in fbp_effect_solo_ids(
            rig, _fbp_effect_solo_view(effect_id)
        )
    )



def _fbp_store_effect_solo_ids(rig, view, effect_ids):
    """Persist concrete Solo tokens without collapsing duplicate instances."""
    candidates = set(_fbp_effect_solo_candidates(rig, view))
    normalized = []
    seen = set()
    for value in tuple(effect_ids or ()):
        effect_id, instance_id = _fbp_effect_ref_parts(value)
        token = _fbp_effect_ref(effect_id, instance_id)
        if token and token in candidates and token not in seen:
            normalized.append(token)
            seen.add(token)
    encoded = json.dumps(tuple(normalized), separators=(",", ":"))
    key = _fbp_effect_solo_prop(view)
    try:
        previous = str(rig.get(key, "[]") or "[]")
        if previous == encoded:
            return False
        rig[key] = encoded
        return True
    except (AttributeError, ReferenceError, TypeError, ValueError):
        return False



def fbp_toggle_effect_solo(rig, target_ids):
    """Toggle one or more concrete effect instances in the viewport Solo set."""
    targets = []
    seen = set()
    for value in tuple(target_ids or ()):
        effect_id, instance_id = _fbp_effect_ref_parts(value)
        token = _fbp_effect_ref(effect_id, instance_id)
        if (
            token
            and token not in seen
            and _fbp_effect_ref_is_active(rig, token)
            and (
                fbp_effect_definition(effect_id).get("kind") in {"SHADER", "GEOMETRY"}
                or effect_id == FBP_EFFECT_LATTICE
            )
        ):
            targets.append(token)
            seen.add(token)
    if not targets:
        return False
    first_effect_id = _fbp_effect_ref_effect_id(targets[0])
    view = _fbp_effect_solo_view(first_effect_id)
    candidates = tuple(_fbp_effect_solo_candidates(rig, view))
    target_set = {token for token in targets if token in candidates}
    if not target_set:
        return False
    current = set(fbp_effect_solo_ids(rig, view))
    if target_set.issubset(current):
        current.difference_update(target_set)
    else:
        current.update(target_set)
    changed = False
    for token in candidates:
        effect_id, instance_id = _fbp_effect_ref_parts(token)
        state = token in current if current else True
        changed = fbp_set_effect_visible(
            rig, effect_id, state, instance_id=instance_id, refresh_mixed=False
        ) or changed
    if changed:
        _fbp_refresh_geometry_source_materials(rig)
    changed = _fbp_store_effect_solo_ids(rig, view, current) or changed
    return changed



def _fbp_reconcile_effect_solo_after_removal(
    rig, removed_effect_id, solo_before, removed_instance_id=""
):
    removed_effect_id = fbp_normalize_effect_id(removed_effect_id)
    removed_instance_id = str(removed_instance_id or "")
    removed_token = _fbp_effect_ref(removed_effect_id, removed_instance_id)
    previous = set(_fbp_normalize_effect_refs(solo_before))
    removed_tokens = {
        token for token in previous
        if token == removed_token
        or (not removed_instance_id and _fbp_effect_ref_effect_id(token) == removed_effect_id)
    }
    if not removed_tokens:
        return False
    view = _fbp_effect_solo_view(removed_effect_id)
    candidates = tuple(_fbp_effect_solo_candidates(rig, view))
    remaining = {
        token for token in previous
        if token not in removed_tokens and token in candidates
    }
    changed = False
    for token in candidates:
        effect_id, instance_id = _fbp_effect_ref_parts(token)
        changed = fbp_set_effect_visible(
            rig,
            effect_id,
            token in remaining if remaining else True,
            instance_id=instance_id,
        ) or changed
    changed = _fbp_store_effect_solo_ids(rig, view, remaining) or changed
    return changed


def fbp_effect_render_visible_state(rig, effect_id, instance_id=""):
    effect_id = fbp_normalize_effect_id(effect_id)
    definition = fbp_effect_definition(effect_id)
    if effect_id == FBP_EFFECT_CAMERA_BILLBOARD:
        return _fbp_stored_effect_render_visibility(rig, effect_id, True)
    if effect_id == FBP_EFFECT_LATTICE:
        plane = _fbp_plane(rig)
        modifier = _fbp_lattice_modifier(plane)
        detail = _fbp_lattice_detail_modifier(plane)
        if modifier is not None:
            return bool(
                getattr(modifier, "show_render", True)
                and (detail is None or getattr(detail, "show_render", True))
            )
        return _fbp_stored_effect_render_visibility(rig, effect_id, True)
    if definition.get("kind") == "BASE":
        return True
    if definition.get("kind") == "GEOMETRY":
        profile = _fbp_effect_runtime_profile(rig)
        modifier = profile.get("geometry_modifiers", {}).get(effect_id)
        if modifier is None and effect_id in profile.get("active_ids", ()):
            modifier = fbp_find_effect_modifier(rig, effect_id)
        if modifier is not None:
            return bool(getattr(modifier, "show_render", True))
        return _fbp_stored_effect_render_visibility(rig, effect_id, True)
    instance_id = str(instance_id or "")
    storage_id = effect_instance_token(effect_id, instance_id) if instance_id else effect_id
    return _fbp_stored_effect_render_visibility(rig, storage_id, True)


def fbp_set_effect_render_visible(rig, effect_id, visible, instance_id=""):
    effect_id = fbp_normalize_effect_id(effect_id)
    definition = fbp_effect_definition(effect_id)
    visible = bool(visible)
    if effect_id == FBP_EFFECT_CAMERA_BILLBOARD:
        return _fbp_store_effect_render_visibility(rig, effect_id, visible)
    if effect_id == FBP_EFFECT_LATTICE:
        changed = _fbp_store_effect_render_visibility(rig, effect_id, visible)
        plane = _fbp_plane(rig)
        modifier = _fbp_lattice_modifier(plane)
        detail = _fbp_lattice_detail_modifier(plane)
        for owned_modifier in (modifier, detail):
            if owned_modifier is not None and bool(getattr(owned_modifier, "show_render", True)) != visible:
                owned_modifier.show_render = visible
                changed = True
        return changed
    if definition.get("kind") == "BASE":
        return False
    instance_id = str(instance_id or "")
    storage_id = effect_instance_token(effect_id, instance_id) if instance_id else effect_id
    changed = _fbp_store_effect_render_visibility(rig, storage_id, visible)
    if not instance_id and _fbp_effect_uses_multi_instances(effect_id):
        # Renders read each instance's own state. A whole-effect toggle (multi
        # layer selection, Copy to Selected) must therefore reach every instance.
        for node in _fbp_find_shader_effect_nodes_for_rig(rig, effect_id):
            node_instance_id = effect_instance_id(node)
            if node_instance_id:
                changed = _fbp_store_effect_render_visibility(
                    rig, effect_instance_token(effect_id, node_instance_id), visible
                ) or changed
    if definition.get("kind") == "GEOMETRY":
        modifier = fbp_find_effect_modifier(rig, effect_id)
        if modifier and bool(getattr(modifier, "show_render", True)) != visible:
            modifier.show_render = visible
            changed = True
    return changed


def _fbp_render_backup_rig_locator(rig):
    try:
        return (
            fbp_obj_runtime_key(rig),
            str(getattr(rig, "name_full", getattr(rig, "name", "")) or ""),
        )
    except FBP_DATA_ERRORS:
        return (None, "")


def _fbp_render_backup_resolve_rig(rig_key, rig_name):
    return fbp_find_id_by_runtime_key(
        getattr(bpy.data, "objects", ()), rig_key, str(rig_name or "")
    )


def _fbp_render_backup_shader_node_locator(rig, node):
    """Return a stable material/node locator for one shader effect node."""
    node_name = str(getattr(node, "name", "") or "")
    if not node_name:
        return None
    for material in _fbp_plane_materials(rig):
        try:
            tree = getattr(material, "node_tree", None)
            current = tree.nodes.get(node_name) if tree is not None else None
            if current is node or (current is not None and current.as_pointer() == node.as_pointer()):
                return (
                    fbp_obj_runtime_key(material),
                    str(getattr(material, "name_full", getattr(material, "name", "")) or ""),
                    node_name,
                )
        except FBP_DATA_ERRORS:
            continue
    return None


def fbp_effect_render_guard_pre(scene=None, rigs=None):
    """Apply render-only states once and return enough data for a lossless restore."""
    backup = []
    if rigs is None:
        try:
            from .layers import iter_scene_fbp_rigs
            rigs = iter_scene_fbp_rigs(scene or getattr(bpy.context, "scene", None))
        except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
            rigs = ()
    for rig in rigs:
        if not bool(getattr(rig, "is_fbp_control", False)):
            continue
        # Render preflight is a correctness boundary: refresh discovery once,
        # which also invalidates stale profile targets after external node or
        # modifier edits, then reuse the rebuilt profile for every effect.
        fbp_effect_ids_for_rig(rig)
        profile = _fbp_effect_runtime_profile(rig)
        active_ids = profile.get("active_ids", frozenset())
        # Static image-aware effects no longer run a Python frame callback. Bind
        # their source once at render start so external material/image edits are
        # still repaired before the first sample. Animated sources continue to
        # use the managed per-frame path selected by the runtime profile.
        try:
            if active_ids.intersection(FBP_FRAME_SYNC_GEOMETRY_EFFECT_IDS):
                _fbp_sync_geometry_alpha_frame_offset(
                    rig,
                    scene=scene,
                    effect_modifiers=profile.get("frame_geometry_modifiers", ()),
                )
            if active_ids.intersection(FBP_FRAME_SYNC_SHADER_EFFECT_IDS):
                _fbp_sync_shader_image_sources(
                    rig,
                    active_ids,
                    target_nodes=profile.get("frame_shader_targets", ()),
                    scene=scene,
                )
        except FBP_DATA_ERRORS:
            _fbp_invalidate_effect_runtime_profile(rig)
        local_mask_target_ids = set()
        # The runtime profile only lists owners that need per-frame work, so
        # render visibility and render quality scan every effect owner here.
        shader_nodes = {}
        for material in _fbp_plane_materials(rig):
            for node in _fbp_shader_effect_nodes(material):
                shader_nodes.setdefault(_fbp_shader_effect_id(node), []).append(node)
        geometry_modifiers = {}
        plane = _fbp_plane(rig, repair=False)
        for modifier in tuple(getattr(plane, "modifiers", ()) or ()):
            modifier_effect_id = _fbp_geometry_effect_id_for_modifier(modifier)
            if modifier_effect_id:
                geometry_modifiers.setdefault(modifier_effect_id, modifier)
        muted_shader_nodes = False
        global_mask_muted = False
        for effect_id in profile.get("effect_ids", ()):
            definition = fbp_effect_definition(effect_id)
            if effect_id == FBP_EFFECT_CAMERA_BILLBOARD:
                constraint = _fbp_track_to_camera_constraint(rig)
                if constraint is not None:
                    try:
                        render_visible = _fbp_stored_effect_render_visibility(
                            rig, effect_id, True
                        )
                        target_mute = not render_visible
                        current_mute = bool(getattr(constraint, "mute", False))
                        if current_mute != target_mute:
                            rig_key, rig_name = _fbp_render_backup_rig_locator(rig)
                            backup.append((
                                "CONSTRAINT_MUTE_V2", rig_key, rig_name,
                                str(getattr(constraint, "name", "") or ""), current_mute,
                            ))
                            constraint.mute = target_mute
                    except FBP_DATA_ERRORS:
                        pass
                continue
            if definition.get("kind") == "SHADER":
                for node in shader_nodes.get(effect_id, ()):
                    try:
                        node_instance_id = effect_instance_id(node)
                        storage_id = (
                            effect_instance_token(effect_id, node_instance_id)
                            if node_instance_id
                            and str(definition.get("instance_policy", "SINGLE") or "SINGLE").upper() == "MULTI"
                            else effect_id
                        )
                        render_visible = _fbp_stored_effect_render_visibility(
                            rig, storage_id, True
                        )
                        target_mute = not render_visible
                        current_mute = bool(node.mute)
                        if current_mute != target_mute:
                            locator = _fbp_render_backup_shader_node_locator(rig, node)
                            if locator is not None:
                                backup.append(("NODE_MUTE_V2", *locator, current_mute))
                            node.mute = target_mute
                            muted_shader_nodes = True
                            if _fbp_effect_is_global_mask(rig, effect_id):
                                global_mask_muted = True
                            if _fbp_effect_is_local_mask(effect_id):
                                local_target = fbp_effect_mask_target(rig, effect_id)
                                if local_target != "LAYER":
                                    local_mask_target_ids.add(local_target)
                    except FBP_DATA_ERRORS:
                        pass
                continue
            contracts = _fbp_quality_contracts(definition)
            if not contracts:
                continue
            modifier = geometry_modifiers.get(effect_id)
            node_group = getattr(modifier, "node_group", None) if modifier else None
            if not modifier or not node_group:
                continue
            extrude_render_grid = (
                _fbp_extrude_grid(rig, "RENDER")
                if effect_id == FBP_EFFECT_THICKNESS else None
            )
            for contract in contracts:
                socket_name = str(contract.get("socket", ""))
                property_name = str(contract.get("render_property", ""))
                if not socket_name or not property_name:
                    continue
                identifier = _fbp_interface_input_identifier(node_group, socket_name)
                if not identifier:
                    continue
                if not _fbp_modifier_input_is_used(modifier, identifier):
                    continue
                try:
                    old_value = _fbp_modifier_input_get(modifier, identifier)
                    if extrude_render_grid is not None and socket_name in {"Pixels X", "Pixels Y"}:
                        render_value = (
                            extrude_render_grid[0]
                            if socket_name == "Pixels X" else extrude_render_grid[1]
                        )
                    else:
                        render_value = _fbp_quality_value(getattr(rig, property_name), contract)
                    if old_value != render_value:
                        rig_key, rig_name = _fbp_render_backup_rig_locator(rig)
                        backup.append((
                            "MODIFIER_INPUT_V2", rig_key, rig_name, effect_id,
                            identifier, old_value,
                        ))
                        _fbp_modifier_input_set(modifier, identifier, render_value)
                except FBP_DATA_ERRORS:
                    continue
            if effect_id == FBP_EFFECT_FRAME_STACK:
                # Render Slices and Detail change the stack image layout.
                try:
                    _fbp_sync_frame_stack_timing(rig, modifier, scene=scene)
                except FBP_DATA_ERRORS:
                    pass
        if local_mask_target_ids:
            for material in _fbp_plane_materials(rig):
                _fbp_rebuild_mask_target_batch(material, local_mask_target_ids)
            rig_key, rig_name = _fbp_render_backup_rig_locator(rig)
            backup.append((
                "LOCAL_MASK_REBUILD_V2", rig_key, rig_name,
                tuple(local_mask_target_ids),
            ))
        if global_mask_muted:
            for material in _fbp_plane_materials(rig):
                _fbp_rebuild_shader_stage(material, "MASK")
            rig_key, rig_name = _fbp_render_backup_rig_locator(rig)
            backup.append(("MASK_STAGE_REBUILD_V2", rig_key, rig_name))
        if muted_shader_nodes and geometry_modifiers:
            # Mesh effects read copied composite materials; mirror the render
            # mute state into them now and again after the mutes are restored.
            _fbp_refresh_geometry_source_materials(rig)
            rig_key, rig_name = _fbp_render_backup_rig_locator(rig)
            backup.append(("GEOMETRY_SOURCE_REFRESH_V2", rig_key, rig_name))
    return backup


def fbp_effect_render_guard_post(backup):
    """Restore render-only values using current Main datablocks only.

    V2 backup records contain primitive identities rather than RNA wrappers.
    This prevents a long Cycles animation from retaining node/modifier objects
    that may have been rebuilt before post-render notifier processing.
    """
    retry = []
    for item in list(backup or ()):
        try:
            tag = item[0]
            if tag == "NODE_MUTE_V2":
                _tag, material_key, material_name, node_name, muted = item
                material = fbp_find_id_by_runtime_key(
                    getattr(bpy.data, "materials", ()), material_key, material_name
                )
                tree = getattr(material, "node_tree", None) if material is not None else None
                node = tree.nodes.get(node_name) if tree is not None else None
                if node is not None and bool(getattr(node, "mute", False)) != bool(muted):
                    node.mute = bool(muted)
            elif tag == "CONSTRAINT_MUTE_V2":
                _tag, rig_key, rig_name, constraint_name, muted = item
                rig = _fbp_render_backup_resolve_rig(rig_key, rig_name)
                constraint = getattr(rig, "constraints", None).get(constraint_name) if rig is not None else None
                if constraint is not None and bool(getattr(constraint, "mute", False)) != bool(muted):
                    constraint.mute = bool(muted)
            elif tag == "MASK_STAGE_REBUILD_V2":
                _tag, rig_key, rig_name = item
                rig = _fbp_render_backup_resolve_rig(rig_key, rig_name)
                if rig is not None:
                    for material in _fbp_plane_materials(rig):
                        _fbp_rebuild_shader_stage(material, "MASK")
            elif tag == "GEOMETRY_SOURCE_REFRESH_V2":
                _tag, rig_key, rig_name = item
                rig = _fbp_render_backup_resolve_rig(rig_key, rig_name)
                if rig is not None:
                    _fbp_refresh_geometry_source_materials(rig)
            elif tag == "LOCAL_MASK_REBUILD_V2":
                _tag, rig_key, rig_name, target_ids = item
                rig = _fbp_render_backup_resolve_rig(rig_key, rig_name)
                if rig is not None:
                    for material in _fbp_plane_materials(rig):
                        _fbp_rebuild_mask_target_batch(material, target_ids)
            elif tag == "MODIFIER_INPUT_V2":
                _tag, rig_key, rig_name, effect_id, identifier, value = item
                rig = _fbp_render_backup_resolve_rig(rig_key, rig_name)
                modifier = fbp_find_effect_modifier(rig, effect_id) if rig is not None else None
                if modifier is None:
                    continue
                if value is None:
                    _fbp_modifier_input_unset(modifier, identifier)
                else:
                    current = _fbp_modifier_input_get(modifier, identifier)
                    if current != value:
                        _fbp_modifier_input_set(modifier, identifier, value)
                if effect_id == FBP_EFFECT_FRAME_STACK:
                    # Lay the stack image out again for the viewport Slices.
                    _fbp_sync_frame_stack_timing(rig, modifier)
        except RuntimeError:
            retry.append(item)
        except (AttributeError, ReferenceError, TypeError, ValueError):
            continue
    return retry


def fbp_effect_global_visible_state(rig, effect_id, instance_id=""):
    """Return the single user-facing visibility state for one effect.

    The unified eye is open only when both viewport and render channels are
    enabled, so the next click resolves any mismatch deterministically.
    """
    effect_id = fbp_normalize_effect_id(effect_id)
    return bool(
        fbp_effect_visible_state(rig, effect_id, instance_id=instance_id)
        and fbp_effect_render_visible_state(rig, effect_id, instance_id=instance_id)
    )


def fbp_set_effect_global_visible(rig, effect_id, visible, instance_id=""):
    """Apply one Hide/Show state to viewport and final render together."""
    effect_id = fbp_normalize_effect_id(effect_id)
    changed = fbp_set_effect_visible(
        rig, effect_id, visible, instance_id=instance_id
    )
    changed = fbp_set_effect_render_visible(
        rig, effect_id, visible, instance_id=instance_id
    ) or changed
    return changed


def fbp_effect_item_visible_get(rig, effect_id, instance_id=""):
    return fbp_effect_global_visible_state(
        rig, fbp_normalize_effect_id(effect_id), instance_id=instance_id
    )


def fbp_effect_item_visible_set(rig, effect_id, visible, instance_id=""):
    """Property callback used by UIList eye icons, including click-drag paint."""
    effect_id = fbp_normalize_effect_id(effect_id)
    if not rig or not effect_id:
        return False
    rigs = _fbp_selected_rigs(getattr(bpy, "context", None))
    if rig not in rigs:
        rigs = [rig]
    changed = False
    for target in rigs:
        if fbp_effect_is_active(target, effect_id):
            view = _fbp_effect_solo_view(effect_id)
            if fbp_effect_solo_ids(target, view):
                changed = _fbp_store_effect_solo_ids(target, view, ()) or changed
            target_instance_id = (
                str(instance_id or "") if len(rigs) == 1 and target is rig else ""
            )
            changed = fbp_set_effect_global_visible(
                target, effect_id, visible, instance_id=target_instance_id
            ) or changed
    return changed


def _fbp_custom_effect_reserved_socket_names(definition):
    return {
        str(definition.get(key, "") or "")
        for key in (
            "input_socket", "output_socket", "alpha_input_socket",
            "alpha_output_socket", "mask_output_socket", "uv_input_socket",
        )
        if str(definition.get(key, "") or "")
    }


def _fbp_runtime_rna_key(value):
    if value is None:
        return (0, "")
    try:
        return (
            int(fbp_obj_runtime_key(value) or 0),
            str(getattr(value, "name_full", getattr(value, "name", "")) or ""),
        )
    except FBP_DATA_ERRORS:
        return (0, "")


def _fbp_cache_custom_socket_descriptors(cache, key, value):
    if not key or not key[0]:
        return value
    if len(cache) >= 512 and key not in cache:
        for stale_key in tuple(cache)[:128]:
            cache.pop(stale_key, None)
    cache[key] = (time.monotonic(), value)
    return value


def _fbp_custom_geometry_value_sockets(node_group):
    """Return plain descriptors for editable custom Geometry Nodes inputs.

    The cache intentionally stores no RNA objects. Undo and file loading can
    replace every interface socket while a sidebar redraw is still queued.
    """
    interface = getattr(node_group, "interface", None) if node_group else None
    if interface is None:
        return []
    try:
        items = interface.items_tree
        item_count = len(items)
    except FBP_DATA_ERRORS:
        return []
    base_key = _fbp_node_group_cache_key(node_group)
    key = (base_key[0], base_key[1], item_count) if base_key else (0, "", item_count)
    cached = _FBP_CUSTOM_GEOMETRY_SOCKET_CACHE.get(key)
    if cached and time.monotonic() - float(cached[0]) <= _FBP_CUSTOM_SOCKET_CACHE_SECONDS:
        return cached[1]

    result = []
    for item in items:
        try:
            if getattr(item, "item_type", "") != "SOCKET":
                continue
            if getattr(item, "in_out", "") != "INPUT":
                continue
            if bool(getattr(item, "hide_in_modifier", False)):
                continue
            socket_type = str(
                getattr(item, "socket_type", "")
                or getattr(item, "bl_socket_idname", "")
                or ""
            )
            if socket_type in {"NodeSocketGeometry", "NodeSocketShader", "NodeSocketVirtual"}:
                continue
            name = str(getattr(item, "name", "") or "")
            identifier = str(getattr(item, "identifier", "") or "")
            if not name or not identifier:
                continue
            default_value = _fbp_serialize_value(getattr(item, "default_value", None))
            result.append((name, identifier, default_value))
        except FBP_DATA_ERRORS:
            continue
    return _fbp_cache_custom_socket_descriptors(
        _FBP_CUSTOM_GEOMETRY_SOCKET_CACHE, key, result
    )


def _fbp_custom_shader_socket_descriptors(node, definition):
    """Return cached plain descriptors for editable custom shader inputs."""
    reserved = _fbp_custom_effect_reserved_socket_names(definition)
    try:
        input_count = len(node.inputs)
    except FBP_DATA_ERRORS:
        return []
    node_key = _fbp_runtime_rna_key(node)
    group_key = _fbp_node_group_cache_key(getattr(node, "node_tree", None))
    key = (
        node_key[0], node_key[1],
        group_key[0] if group_key else 0,
        group_key[1] if group_key else "",
        input_count,
        tuple(sorted(reserved)),
    )
    cached = _FBP_CUSTOM_SHADER_SOCKET_CACHE.get(key)
    if cached and time.monotonic() - float(cached[0]) <= _FBP_CUSTOM_SOCKET_CACHE_SECONDS:
        return cached[1]

    result = []
    for socket in getattr(node, "inputs", ()):
        try:
            name = str(getattr(socket, "name", "") or "")
            identifier = str(getattr(socket, "identifier", "") or name)
            if not name or name in reserved:
                continue
            if bool(getattr(socket, "hide_value", False)):
                continue
            if not bool(getattr(socket, "enabled", True)):
                continue
            if bool(getattr(socket, "is_linked", False)):
                continue
            if not hasattr(socket, "default_value"):
                continue
            result.append((name, identifier))
        except FBP_DATA_ERRORS:
            continue
    return _fbp_cache_custom_socket_descriptors(
        _FBP_CUSTOM_SHADER_SOCKET_CACHE, key, result
    )


def _fbp_custom_shader_value_sockets(node, definition):
    """Resolve fresh shader socket RNA from cached string descriptors."""
    descriptors = _fbp_custom_shader_socket_descriptors(node, definition)
    if not descriptors:
        return []
    live = {}
    try:
        for socket in node.inputs:
            identifier = str(getattr(socket, "identifier", "") or getattr(socket, "name", "") or "")
            if identifier:
                live[identifier] = socket
    except FBP_DATA_ERRORS:
        return []
    return [
        (name, identifier, live[identifier])
        for name, identifier in descriptors
        if identifier in live
    ]


def _fbp_capture_custom_effect_inputs(rig, effect_id):
    definition = fbp_effect_definition(effect_id)
    if not bool(definition.get("custom", False)):
        return {}
    if definition.get("kind") == "GEOMETRY":
        modifier = fbp_find_effect_modifier(rig, effect_id)
        node_group = getattr(modifier, "node_group", None) if modifier else None
        if not modifier or not node_group:
            return {}
        values = {}
        for _name, identifier, default_serialized in _fbp_custom_geometry_value_sockets(node_group):
            try:
                default = _fbp_deserialize_value(default_serialized)
                values[identifier] = _fbp_serialize_value(
                    _fbp_modifier_input_get(modifier, identifier, default)
                )
            except FBP_DATA_ERRORS:
                continue
        return {"kind": "GEOMETRY", "values": values}

    nodes = _fbp_find_shader_effect_nodes_for_rig(rig, effect_id)
    node = nodes[0] if nodes else None
    if node is None:
        return {}
    values = {}
    for _name, identifier, socket in _fbp_custom_shader_value_sockets(
        node, definition
    ):
        try:
            values[identifier] = _fbp_serialize_value(socket.default_value)
        except FBP_DATA_ERRORS:
            continue
    return {"kind": "SHADER", "values": values}


def _fbp_custom_shader_nodes_need_sync(nodes, definition, master_state=None):
    """Return whether material instances differ from the master group node."""
    nodes = list(nodes or ())
    if len(nodes) < 2:
        return False
    values = dict((master_state or {}).get("values", {}) or {})
    if not values:
        for _name, identifier, socket in _fbp_custom_shader_value_sockets(
            nodes[0], definition
        ):
            try:
                values[identifier] = _fbp_serialize_value(socket.default_value)
            except FBP_DATA_ERRORS:
                continue
    if not values:
        return False
    for node in nodes[1:]:
        sockets = {
            identifier: socket
            for _name, identifier, socket
            in _fbp_custom_shader_value_sockets(node, definition)
        }
        for identifier, serialized in values.items():
            socket = sockets.get(identifier)
            if socket is None:
                continue
            value = _fbp_deserialize_value(serialized)
            if isinstance(value, list):
                value = tuple(value)
            try:
                if not _fbp_effect_values_equal(socket.default_value, value):
                    return True
            except FBP_DATA_ERRORS:
                continue
    return False


def _fbp_custom_shader_topology_signature(nodes):
    return tuple(_fbp_runtime_rna_key(node) for node in tuple(nodes or ()))


def _fbp_json_state_signature(state):
    try:
        return json.dumps(state or {}, sort_keys=True, separators=(",", ":"))
    except (TypeError, ValueError):
        return repr(state or {})


def _fbp_schedule_custom_shader_sync(rig, effect_id, nodes, definition):
    """Defer multi-material value propagation outside UI drawing.

    The master socket state is captured once per draw. A short-lived validated
    state cache avoids rescanning every secondary material while no value or
    node topology changed.
    """
    nodes = list(nodes or ())
    state = _fbp_capture_custom_effect_inputs(rig, effect_id)
    if not state:
        return False
    rig_key = fbp_obj_runtime_key(rig)
    if rig_key is None:
        return False
    key = (rig_key, str(effect_id or ""))
    topology = _fbp_custom_shader_topology_signature(nodes)
    state_signature = _fbp_json_state_signature(state)
    cached = _FBP_CUSTOM_SHADER_SYNC_STATE_CACHE.get(key)
    if (
        cached
        and cached[0] == topology
        and cached[1] == state_signature
        and time.monotonic() - float(cached[2]) <= _FBP_CUSTOM_SHADER_SYNC_CACHE_SECONDS
    ):
        return False
    if not _fbp_custom_shader_nodes_need_sync(
        nodes, definition, master_state=state
    ):
        _FBP_CUSTOM_SHADER_SYNC_STATE_CACHE[key] = (
            topology, state_signature, time.monotonic()
        )
        return False

    rig_name = str(getattr(rig, "name", "") or "")
    try:
        expected_instance = str(effect_instance_id(nodes[0]) or "") if nodes else ""
    except FBP_DATA_ERRORS:
        expected_instance = ""
    if not expected_instance:
        return False
    _FBP_CUSTOM_SHADER_SYNC_PENDING[key] = (
        rig_name, expected_instance, state, topology, state_signature
    )

    def _sync_latest():
        payload = _FBP_CUSTOM_SHADER_SYNC_PENDING.pop(key, None)
        if not payload:
            return None
        (
            stored_name, stored_instance, latest_state,
            _stored_topology, latest_signature,
        ) = payload
        target_rig = fbp_find_id_by_runtime_key(
            bpy.data.objects, rig_key, stored_name
        )
        if target_rig is not None:
            current_nodes = _fbp_find_shader_effect_nodes_for_rig(target_rig, effect_id)
            try:
                current_instance = (
                    str(effect_instance_id(current_nodes[0]) or "")
                    if current_nodes else ""
                )
            except FBP_DATA_ERRORS:
                current_instance = ""
            if current_instance == stored_instance:
                _fbp_apply_custom_effect_inputs(
                    target_rig, effect_id, latest_state
                )
                _FBP_CUSTOM_SHADER_SYNC_STATE_CACHE[key] = (
                    _fbp_custom_shader_topology_signature(current_nodes),
                    latest_signature,
                    time.monotonic(),
                )
        return None

    try:
        from .safe_tasks import schedule_once
        return schedule_once(
            f"fbp_custom_shader_sync:{key[0]}:{key[1]}",
            _sync_latest,
            first_interval=0.03,
        )
    except (ImportError, AttributeError, RuntimeError, TypeError, ValueError):
        _FBP_CUSTOM_SHADER_SYNC_PENDING.pop(key, None)
        return False


def _fbp_apply_custom_effect_inputs(rig, effect_id, state):
    definition = fbp_effect_definition(effect_id)
    values = dict((state or {}).get("values", {}) or {})
    if not bool(definition.get("custom", False)) or not values:
        return False
    changed = False
    if definition.get("kind") == "GEOMETRY":
        modifier = fbp_find_effect_modifier(rig, effect_id)
        node_group = getattr(modifier, "node_group", None) if modifier else None
        if not modifier or not node_group:
            return False
        by_identifier = {
            identifier
            for _name, identifier, _default
            in _fbp_custom_geometry_value_sockets(node_group)
        }
        for identifier, serialized in values.items():
            if identifier not in by_identifier:
                continue
            value = _fbp_deserialize_value(serialized)
            try:
                changed = _fbp_modifier_input_set(
                    modifier, identifier, value
                ) or changed
            except FBP_DATA_ERRORS:
                continue
        return changed

    for node in _fbp_find_shader_effect_nodes_for_rig(rig, effect_id):
        sockets = {
            identifier: socket
            for _name, identifier, socket
            in _fbp_custom_shader_value_sockets(node, definition)
        }
        for identifier, serialized in values.items():
            socket = sockets.get(identifier)
            if socket is None:
                continue
            value = _fbp_deserialize_value(serialized)
            try:
                if isinstance(value, list):
                    value = tuple(value)
                if _fbp_effect_values_equal(socket.default_value, value):
                    continue
                socket.default_value = value
                changed = True
            except FBP_DATA_ERRORS:
                continue
    return changed


def _fbp_reset_custom_effect_inputs(rig, effect_id):
    definition = fbp_effect_definition(effect_id)
    group = find_custom_effect_group(effect_id)
    if not bool(definition.get("custom", False)) or group is None:
        return False
    changed = False
    if definition.get("kind") == "GEOMETRY":
        modifier = fbp_find_effect_modifier(rig, effect_id)
        if modifier is None:
            return False
        for _name, identifier, default_serialized in _fbp_custom_geometry_value_sockets(group):
            try:
                value = _fbp_deserialize_value(default_serialized)
                if value is None or _fbp_effect_values_equal(
                    _fbp_modifier_input_get(modifier, identifier), value
                ):
                    continue
                changed = _fbp_modifier_input_set(
                    modifier, identifier, value
                ) or changed
            except FBP_DATA_ERRORS:
                continue
        return changed

    defaults = {
        str(getattr(item, "identifier", "") or getattr(item, "name", "") or ""):
            getattr(item, "default_value", None)
        for item in getattr(getattr(group, "interface", None), "items_tree", ())
        if getattr(item, "item_type", "") == "SOCKET"
        and getattr(item, "in_out", "") == "INPUT"
        and hasattr(item, "default_value")
    }
    for node in _fbp_find_shader_effect_nodes_for_rig(rig, effect_id):
        for _name, identifier, socket in _fbp_custom_shader_value_sockets(
            node, definition
        ):
            if identifier not in defaults or defaults[identifier] is None:
                continue
            value = defaults[identifier]
            try:
                if _fbp_effect_values_equal(socket.default_value, value):
                    continue
                socket.default_value = value
                changed = True
            except FBP_DATA_ERRORS:
                continue
    return changed


def _fbp_custom_geometry_missing_defaults(modifier, node_group):
    """Return serializable defaults that are not initialized on the modifier."""
    if not modifier or not node_group:
        return {}
    missing = {}
    for _name, identifier, default_serialized in _fbp_custom_geometry_value_sockets(node_group):
        try:
            if _fbp_modifier_input_has(modifier, identifier):
                continue
            if default_serialized is not None:
                missing[identifier] = default_serialized
        except FBP_DATA_ERRORS:
            continue
    return missing


def _fbp_initialize_custom_geometry_inputs(modifier, node_group):
    """Initialize missing custom GN inputs from their interface defaults.

    Call this only from operators, deferred safe tasks or other mutation-safe
    paths. UI draw callbacks must remain read-only.
    """
    changed = False
    for identifier, serialized in _fbp_custom_geometry_missing_defaults(
        modifier, node_group
    ).items():
        try:
            changed = _fbp_modifier_input_set(
                modifier, identifier, _fbp_deserialize_value(serialized)
            ) or changed
        except FBP_DATA_ERRORS:
            continue
    return changed


def _fbp_schedule_custom_geometry_init(rig, effect_id, modifier, node_group):
    """Repair newly exposed GN sockets outside panel drawing and Undo teardown."""
    defaults = _fbp_custom_geometry_missing_defaults(modifier, node_group)
    if not defaults:
        return False
    rig_key = fbp_obj_runtime_key(rig)
    if rig_key is None:
        return False
    rig_name = str(getattr(rig, "name", "") or "")
    try:
        expected_instance = _fbp_geometry_modifier_instance_id(
            rig, modifier, effect_id, ensure=False
        )
    except FBP_DATA_ERRORS:
        expected_instance = ""
    if not expected_instance:
        return False
    key = (rig_key, str(effect_id or ""))
    _FBP_CUSTOM_GEOMETRY_INIT_PENDING[key] = (
        rig_name, expected_instance, defaults
    )

    def _initialize_latest():
        payload = _FBP_CUSTOM_GEOMETRY_INIT_PENDING.pop(key, None)
        if not payload:
            return None
        stored_name, stored_instance, latest_defaults = payload
        target_rig = fbp_find_id_by_runtime_key(
            bpy.data.objects, rig_key, stored_name
        )
        target_modifier = (
            fbp_find_effect_modifier(target_rig, effect_id)
            if target_rig is not None else None
        )
        target_group = (
            getattr(target_modifier, "node_group", None)
            if target_modifier is not None else None
        )
        try:
            current_instance = _fbp_geometry_modifier_instance_id(
                target_rig, target_modifier, effect_id, ensure=False
            ) if target_modifier is not None else ""
        except FBP_DATA_ERRORS:
            current_instance = ""
        if (
            target_modifier is not None
            and target_group is not None
            and current_instance == stored_instance
        ):
            for identifier, serialized in latest_defaults.items():
                try:
                    if not _fbp_modifier_input_has(target_modifier, identifier):
                        _fbp_modifier_input_set(
                            target_modifier,
                            identifier,
                            _fbp_deserialize_value(serialized),
                        )
                except FBP_DATA_ERRORS:
                    continue
            try:
                from .core import fbp_tag_view3d_ui_redraw
                fbp_tag_view3d_ui_redraw()
            except (ImportError, AttributeError, RuntimeError, TypeError, ValueError):
                pass
        return None

    try:
        from .safe_tasks import schedule_once
        return schedule_once(
            f"fbp_custom_geometry_init:{key[0]}:{key[1]}",
            _initialize_latest,
            first_interval=0.03,
        )
    except (ImportError, AttributeError, RuntimeError, TypeError, ValueError):
        _FBP_CUSTOM_GEOMETRY_INIT_PENDING.pop(key, None)
        return False




def _fbp_draw_family_variant_operator(layout, rigs, source_effect_id, target_effect_id, label):
    row = layout.row(align=False)
    supported = all(
        fbp_effect_supported_for_rig(target_rig, target_effect_id)
        for target_rig in rigs
    )
    already_target_everywhere = bool(rigs) and all(
        fbp_effect_is_active(target_rig, target_effect_id)
        for target_rig in rigs
    )
    current = target_effect_id == source_effect_id
    row.enabled = supported and (current or not already_target_everywhere)
    op = row.operator(
        "fbp.set_effect_family_variant",
        text=str(label),
        icon="CHECKMARK" if current else "BLANK1",
        depress=current,
    )
    op.source_effect_id = source_effect_id
    op.target_effect_id = target_effect_id


_FBP_VARIANT_CONTEXT_KEY = "fbp_variant_effect"


def _fbp_variant_menu_effect(context, rig):
    """Effect whose variant dropdown opened the menu.

    The settings panel stores it on the dropdown's layout; without it the
    active Modifiers row decides, and only then the legacy active stack item.
    """
    try:
        effect_id = context.fbp_variant_effect
    except AttributeError:
        effect_id = ""
    effect_id = fbp_normalize_effect_id(effect_id or "")
    if effect_id:
        return effect_id
    try:
        from .ui import _fbp_native_active_effect
        native_effect, _instance = _fbp_native_active_effect(rig)
    except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
        native_effect = ""
    return fbp_normalize_effect_id(native_effect or fbp_active_effect_id(rig))


class FBP_MT_DuotoneVariants(Menu):
    bl_idname = "FBP_MT_duotone_variants"
    bl_label = "Duotone"

    def draw(self, context):
        layout = configure_layout(self.layout)
        rigs = _fbp_selected_rigs(context)
        if not rigs:
            layout.label(text="Select a Frame By Plane layer", icon="INFO")
            return
        effect_id = _fbp_variant_menu_effect(context, rigs[0])
        _fbp_draw_family_variant_operator(
            layout, rigs, effect_id, FBP_EFFECT_DUOTONE, "Duotone"
        )
        _fbp_draw_family_variant_operator(
            layout, rigs, effect_id, FBP_EFFECT_FALSE_COLOR, "False Color"
        )


class FBP_MT_EffectFamilyVariants(Menu):
    bl_idname = "FBP_MT_effect_family_variants"
    bl_label = "Effect Variant"

    def draw(self, context):
        layout = configure_layout(self.layout)
        rigs = _fbp_selected_rigs(context)
        if not rigs:
            layout.label(text="Select a Frame By Plane layer", icon="INFO")
            return
        effect_id = _fbp_variant_menu_effect(context, rigs[0])
        family_id = fbp_effect_family_id(effect_id)
        family = fbp_effect_family_definition(family_id)
        variants = tuple(family.get("variants", ()) or ())
        if not variants:
            layout.label(text="This effect has no variants", icon="INFO")
            return
        layout.label(text=str(family.get("label", "Variant") or "Variant"))
        layout.separator(type="LINE")
        for target_effect_id, label in variants:
            _fbp_draw_family_variant_operator(
                layout, rigs, effect_id, target_effect_id, label
            )


def _fbp_family_variant_ramp_key(effect_id):
    return f"fbp_family_variant_ramp::{fbp_normalize_effect_id(effect_id)}"


def _fbp_store_family_variant_ramp(rig, effect_id):
    state = _fbp_capture_effect_color_ramp(rig, effect_id)
    if state is None:
        return False
    try:
        rig[_fbp_family_variant_ramp_key(effect_id)] = json.dumps(
            state, sort_keys=True, separators=(",", ":")
        )
        return True
    except (AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
        return False


def _fbp_restore_family_variant_ramp(rig, effect_id):
    try:
        raw = rig.get(_fbp_family_variant_ramp_key(effect_id), "")
        state = json.loads(raw) if isinstance(raw, str) and raw else None
    except (AttributeError, ReferenceError, RuntimeError, TypeError, ValueError, json.JSONDecodeError):
        state = None
    return bool(state and _fbp_apply_effect_color_ramp(rig, effect_id, state))


def _fbp_copy_shared_family_properties(rig, source_effect_id, target_effect_id):
    """Copy shared and family-specific settings while switching variants."""
    source = fbp_effect_definition(source_effect_id)
    target = fbp_effect_definition(target_effect_id)
    source_by_socket = {
        str(socket): str(prop)
        for prop, socket in dict(source.get("property_map", {})).items()
    }
    target_by_socket = {
        str(socket): str(prop)
        for prop, socket in dict(target.get("property_map", {})).items()
    }

    def get_value(prop_name, default=None):
        try:
            return getattr(rig, prop_name) if hasattr(rig, prop_name) else default
        except FBP_DATA_ERRORS:
            return default

    def set_value(prop_name, value):
        if value is None or not hasattr(rig, prop_name):
            return False
        return fbp_set_rna_property_silent(rig, prop_name, value)

    copied = False
    for socket_name in sorted(set(source_by_socket) & set(target_by_socket)):
        source_prop = source_by_socket[socket_name]
        target_prop = target_by_socket[socket_name]
        copied = set_value(target_prop, get_value(source_prop)) or copied

    family_id = fbp_effect_family_id(source_effect_id)
    if family_id == "TINT":
        black = (0.0, 0.0, 0.0, 1.0)
        white = (1.0, 1.0, 1.0, 1.0)
        source_effect_id = fbp_normalize_effect_id(source_effect_id)
        target_effect_id = fbp_normalize_effect_id(target_effect_id)
        if source_effect_id == "SOLID_MASK":
            accent = tuple(get_value("fbp_solid_mask_color", white))
            shadows, midtones, highlights = black, accent, accent
            factor = get_value("fbp_solid_mask_factor", 1.0)
        elif source_effect_id == "DUOTONE":
            shadows = tuple(get_value("fbp_duotone_shadows", black))
            highlights = tuple(get_value("fbp_duotone_highlights", white))
            midtones = tuple((float(a) + float(b)) * 0.5 for a, b in zip(shadows, highlights, strict=False))
            factor = 1.0
        elif source_effect_id == "TRITONE":
            shadows = tuple(get_value("fbp_tritone_shadows", black))
            midtones = tuple(get_value("fbp_tritone_midtones", (0.5, 0.5, 0.5, 1.0)))
            highlights = tuple(get_value("fbp_tritone_highlights", white))
            factor = get_value("fbp_tritone_factor", 1.0)
        elif source_effect_id == "FALSE_COLOR":
            shadows = tuple(get_value("fbp_false_color_dark", black))
            highlights = tuple(get_value("fbp_false_color_light", white))
            midtones = tuple((float(a) + float(b)) * 0.5 for a, b in zip(shadows, highlights, strict=False))
            factor = get_value("fbp_false_color_factor", 1.0)
        else:
            shadows, midtones, highlights, factor = black, (0.5, 0.5, 0.5, 1.0), white, 1.0

        if target_effect_id == "SOLID_MASK":
            copied = set_value("fbp_solid_mask_color", highlights) or copied
            copied = set_value("fbp_solid_mask_factor", factor) or copied
        elif target_effect_id == "DUOTONE":
            copied = set_value("fbp_duotone_shadows", shadows) or copied
            copied = set_value("fbp_duotone_highlights", highlights) or copied
        elif target_effect_id == "TRITONE":
            copied = set_value("fbp_tritone_shadows", shadows) or copied
            copied = set_value("fbp_tritone_midtones", midtones) or copied
            copied = set_value("fbp_tritone_highlights", highlights) or copied
            copied = set_value("fbp_tritone_factor", factor) or copied
        elif target_effect_id == "FALSE_COLOR":
            copied = set_value("fbp_false_color_dark", shadows) or copied
            copied = set_value("fbp_false_color_light", highlights) or copied
            copied = set_value("fbp_false_color_factor", factor) or copied
        elif target_effect_id == "RECOLOR":
            copied = set_value("fbp_recolor_factor", factor) or copied

    elif family_id == "BLUR":
        radius_props = {
            "GAUSSIAN_BLUR": ("fbp_gaussian_blur_radius_x", "fbp_gaussian_blur_radius_y"),
            "DIRECTIONAL_BLUR": ("fbp_directional_blur_distance",),
            "DEPTH_BLUR": ("fbp_depth_blur_manual_radius",),
            "TRIANGLE_BLUR": ("fbp_triangle_blur_radius",),
            "TILT_SHIFT": ("fbp_tilt_shift_radius",),
        }
        sample_props = {
            "GAUSSIAN_BLUR": "fbp_gaussian_blur_samples",
            "DIRECTIONAL_BLUR": "fbp_directional_blur_samples",
            "TRIANGLE_BLUR": "fbp_triangle_blur_samples",
        }
        source_radius_values = [
            float(get_value(prop_name, 0.0) or 0.0)
            for prop_name in radius_props.get(fbp_normalize_effect_id(source_effect_id), ())
        ]
        radius = max(source_radius_values, default=0.0)
        for prop_name in radius_props.get(fbp_normalize_effect_id(target_effect_id), ()):
            copied = set_value(prop_name, radius) or copied
        source_samples = sample_props.get(fbp_normalize_effect_id(source_effect_id), "")
        target_samples = sample_props.get(fbp_normalize_effect_id(target_effect_id), "")
        if source_samples and target_samples:
            copied = set_value(target_samples, get_value(source_samples)) or copied

    elif family_id == "PIXELATE":
        grid_props = {
            "PIXELATE": ("fbp_pixelate_resolution", "fbp_pixelate_height"),
            "MOSAIC_JITTER": ("fbp_mosaic_jitter_cells_x", "fbp_mosaic_jitter_cells_y"),
            "HEX_PIXELATE": ("fbp_hex_pixelate_cells_x", "fbp_hex_pixelate_cells_y"),
        }
        source_grid = grid_props.get(fbp_normalize_effect_id(source_effect_id), ())
        target_grid = grid_props.get(fbp_normalize_effect_id(target_effect_id), ())
        if source_grid and target_grid:
            copied = set_value(target_grid[0], get_value(source_grid[0])) or copied
            copied = set_value(target_grid[1], get_value(source_grid[1])) or copied

    return copied


def fbp_switch_effect_family_variant(rig, source_effect_id, target_effect_id):
    source_effect_id = fbp_normalize_effect_id(source_effect_id)
    target_effect_id = fbp_normalize_effect_id(target_effect_id)
    if not rig or not source_effect_id or not target_effect_id:
        return False
    if source_effect_id == target_effect_id:
        return True
    if fbp_effect_family_id(source_effect_id) != fbp_effect_family_id(target_effect_id):
        return False
    if not fbp_effect_is_active(rig, source_effect_id):
        return False
    if fbp_effect_is_active(rig, target_effect_id):
        return False

    # A duplicated (MULTI) effect switches only the selected instance; its
    # other instances keep their own settings.
    source_instances = [
        _fbp_effect_ref_instance_id(token)
        for token in _fbp_mixed_effect_tokens(rig)
        if _fbp_effect_ref_effect_id(token) == source_effect_id
    ]
    source_instance = ""
    if _fbp_effect_uses_multi_instances(source_effect_id) and source_instances:
        active_instance = (
            fbp_active_effect_instance_id(rig)
            if fbp_active_effect_id(rig) == source_effect_id else ""
        )
        source_instance = (
            active_instance if active_instance in source_instances
            else source_instances[0]
        )
    partial = len(source_instances) > 1
    source_ref = _fbp_effect_ref(source_effect_id, source_instance)

    visible = fbp_effect_visible_state(rig, source_effect_id, source_instance)
    render_visible = fbp_effect_render_visible_state(
        rig, source_effect_id, source_instance
    )
    solo_view = _fbp_effect_solo_view(source_effect_id)
    solo_before = tuple(fbp_effect_solo_ids(rig, solo_view))
    source_was_soloed = source_effect_id in solo_before
    source_input = fbp_effect_input_source(rig, source_effect_id, source_instance)
    source_debug = fbp_effect_debug_mode(rig, source_effect_id)
    attached_masks = tuple(
        fbp_masks_targeting_effect(rig, source_effect_id, source_instance)
    )
    _fbp_store_family_variant_ramp(rig, source_effect_id)

    _fbp_select_effect_row(rig, source_effect_id, instance_id=source_instance)
    if not fbp_add_effect(
        rig, target_effect_id, sync_items=False, inherit_active_group=True
    ):
        return False
    # The variant takes over the source row's place in the stack.
    order = _fbp_mixed_effect_tokens(rig)
    target_ref = next(
        (token for token in order if _fbp_effect_ref_effect_id(token) == target_effect_id),
        "",
    )
    desired = _fbp_relative_effect_order(rig, (target_ref,), source_ref, "BEFORE")
    if desired and tuple(desired) != tuple(order):
        _fbp_apply_mixed_effect_order(rig, desired)
    _fbp_copy_shared_family_properties(rig, source_effect_id, target_effect_id)
    _fbp_restore_family_variant_ramp(rig, target_effect_id)
    fbp_set_effect_visible(rig, target_effect_id, visible)
    fbp_set_effect_render_visible(rig, target_effect_id, render_visible)
    if fbp_effect_definition(target_effect_id).get("supports_input_source"):
        fbp_set_effect_input_source(rig, target_effect_id, source_input)
    if tuple(fbp_effect_definition(target_effect_id).get("debug_modes", ()) or ()):
        fbp_set_effect_debug_mode(rig, target_effect_id, source_debug)
    for mask_effect_id in attached_masks:
        # Duplicable variants are addressed by their concrete instance.
        fbp_set_effect_mask_target(rig, mask_effect_id, target_ref or target_effect_id)

    removed = (
        fbp_remove_effect_instance(
            rig, source_effect_id, source_instance, sync_items=False
        )
        if partial
        else fbp_remove_effect(rig, source_effect_id, sync_items=False)
    )
    if not removed:
        fbp_remove_effect(rig, target_effect_id, sync_items=False)
        return False
    if source_was_soloed:
        desired_solo = {
            effect_id for effect_id in solo_before
            if (partial or effect_id != source_effect_id)
            and fbp_effect_is_active(rig, effect_id)
        }
        desired_solo.add(target_effect_id)
        for effect_id in _fbp_effect_solo_candidates(rig, solo_view):
            fbp_set_effect_visible(rig, effect_id, effect_id in desired_solo)
        _fbp_store_effect_solo_ids(rig, solo_view, desired_solo)
    fbp_sync_effect_items(rig)
    _fbp_select_effect_row(rig, target_effect_id)
    try:
        from .effect_controls import sync_active_effect_controls
        # Variant replacement is one UNDO operator: create any missing helper
        # synchronously so it belongs to the same transaction.
        sync_active_effect_controls(
            getattr(bpy, "context", None), create_missing=True
        )
    except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
        pass
    return True


class FBP_OT_SetEffectFamilyVariant(Operator):
    bl_idname = "fbp.set_effect_family_variant"
    bl_label = "Set Effect Variant"
    bl_description = "Replace the selected effect with another variant from the same family while preserving order, masks and shared settings"
    bl_options = {"REGISTER", "UNDO"}

    source_effect_id: StringProperty(description='Effect to replace', default="", options={"SKIP_SAVE"})
    target_effect_id: StringProperty(description='Variant to use', default="", options={"SKIP_SAVE"})

    @classmethod
    def poll(cls, context):
        return bool(_fbp_selected_rigs(context))

    def execute(self, context):
        rigs = _fbp_selected_rigs(context)
        family = fbp_effect_family_definition(self.source_effect_id)
        variants = tuple(family.get("variants", ()) or ())
        changed = 0
        for rig in rigs:
            if fbp_effect_is_active(rig, self.target_effect_id):
                continue
            # Replace the clicked row; other selected layers fall back to the
            # first active variant of the same family.
            source_effect_id = fbp_normalize_effect_id(self.source_effect_id)
            current_effect_id = source_effect_id if fbp_effect_is_active(
                rig, source_effect_id
            ) else next((
                effect_id for effect_id, _label in variants
                if fbp_effect_is_active(rig, effect_id)
            ), "")
            if current_effect_id and fbp_switch_effect_family_variant(
                rig, current_effect_id, self.target_effect_id
            ):
                changed += 1
        if not changed:
            self.report({"INFO"}, "The selected variant is already active")
            return {"CANCELLED"}
        fbp_sync_effect_items(rigs[0], rigs)
        return {"FINISHED"}


class FBP_OT_AddEffectFamily(Operator):
    bl_idname = "fbp.add_effect_family"
    bl_label = "Add Effect Family"
    bl_description = "Add the default variant of a unified Frame By Plane effect family"
    bl_options = {"REGISTER", "UNDO"}

    family_id: StringProperty(description='Family Id value used by the current effect-stack action. Changes are applied only to compatible Frame By Plane data.', default="", options={"SKIP_SAVE"})

    @classmethod
    def poll(cls, context):
        return bool(_fbp_selected_rigs(context))

    def execute(self, context):
        family = fbp_effect_family_definition(self.family_id)
        default_effect_id = str(family.get("default", "") or "")
        variants = tuple(family.get("variants", ()) or ())
        rigs = _fbp_selected_rigs(context)
        if not default_effect_id or not rigs:
            return {"CANCELLED"}
        common_variants = [
            effect_id for effect_id, _label in variants
            if all(fbp_effect_supported_for_rig(rig, effect_id) for rig in rigs)
        ]
        if not common_variants:
            self.report({"WARNING"}, "No variant in this family supports every selected layer")
            return {"CANCELLED"}
        target_effect_id = (
            default_effect_id if default_effect_id in common_variants
            else common_variants[0]
        )
        changed = 0
        already = 0
        failed = 0
        for rig in rigs:
            active_variant = next(
                (effect_id for effect_id, _label in variants if fbp_effect_is_active(rig, effect_id)),
                "",
            )
            if active_variant:
                already += 1
                continue
            if fbp_add_effect(rig, target_effect_id, sync_items=False):
                changed += 1
            else:
                failed += 1
        fbp_sync_effect_items(rigs[0], rigs)
        if not changed:
            if failed:
                self.report({"WARNING"}, f"Could not add {family.get('label', target_effect_id)} to the selected layer")
            else:
                self.report({"INFO"}, "This effect family is already present")
            return {"CANCELLED"}
        _fbp_select_effect_row(rigs[0], target_effect_id, rigs)
        label = str(family.get("label", target_effect_id) or target_effect_id)
        layer_word = "layer" if changed == 1 else "layers"
        message = f"Added {label} to {changed} {layer_word}"
        if already:
            message += f"; already present on {already}"
        if failed:
            message += f"; failed on {failed}"
        self.report({"WARNING"} if failed else {"INFO"}, message)
        return {"FINISHED"}


class FBP_MT_AddEffect(Menu):
    bl_idname = "FBP_MT_add_effect"
    bl_label = "Add Effect"
    bl_options = {"SEARCH_ON_KEY_PRESS"}

    def draw(self, context):
        layout = configure_layout(self.layout)
        if not _fbp_selected_rigs(context):
            layout.label(text="Select a Frame By Plane layer", icon="INFO")
            return
        layout.menu(
            "FBP_MT_object_effects_2d",
            text="Image Effects",
            icon="SHADERFX",
        )
        layout.menu(
            "FBP_MT_object_masks",
            text="Mask",
            icon="MOD_MASK",
        )
        # Mesh effects are real modifiers: they are added from Blender's own
        # Properties > Modifiers > Add Modifier > Mesh menu.


def _fbp_selected_generic_mesh_targets(context):
    """Return selected editable, local non-FBP mesh objects."""
    objects = tuple(getattr(context, "selected_objects", ()) or ()) if context else ()
    result = []
    for obj in objects:
        try:
            if str(getattr(obj, "type", "") or "") != "MESH":
                continue
            if bool(getattr(obj, "is_fbp_control", False)) or bool(getattr(obj, "is_fbp_plane", False)):
                continue
            if getattr(obj, "library", None) is not None or getattr(obj, "override_library", None) is not None:
                continue
            if getattr(getattr(obj, "data", None), "library", None) is not None:
                continue
            result.append(obj)
        except FBP_DATA_ERRORS:
            continue
    return result


_FBP_GENERIC_MESH_EFFECT_IDS_CACHE = None
_FBP_GENERIC_MESH_EFFECT_MATRIX_CACHE = None


def fbp_generic_mesh_effect_matrix():
    """Return a stable support matrix for every 3D menu effect."""
    global _FBP_GENERIC_MESH_EFFECT_MATRIX_CACHE
    if _FBP_GENERIC_MESH_EFFECT_MATRIX_CACHE is not None:
        return _FBP_GENERIC_MESH_EFFECT_MATRIX_CACHE
    records = []
    for effect_id in FBP_3D_EFFECT_MENU_ORDER:
        definition = fbp_effect_definition(effect_id) or {}
        kind = str(definition.get("kind", "") or "")
        alpha_aware = bool(definition.get("alpha_aware", False))
        if kind != "GEOMETRY":
            supported = False
            reason = "Not a Geometry Nodes effect"
        elif effect_id == FBP_EFFECT_LATTICE:
            supported = False
            reason = "Uses an editable Frame By Plane lattice cage and ownership contract"
        elif effect_id == FBP_EFFECT_MOTION:
            supported = False
            reason = "Motion is a transform system, not a mesh modifier"
        elif alpha_aware:
            supported = False
            reason = "Requires Frame By Plane image alpha and media metadata"
        elif bool(definition.get("camera_aware", False) or definition.get("camera_dependent", False)
                  or definition.get("camera_contract")):
            supported = False
            reason = "Requires a Frame By Plane camera contract"
        else:
            supported = True
            reason = "Pure Geometry Nodes backend"
        records.append({
            "effect_id": str(effect_id),
            "label": str(definition.get("label", effect_id.replace("_", " ").title())),
            "supported": supported,
            "reason": reason,
            "alpha_aware": alpha_aware,
        })
    _FBP_GENERIC_MESH_EFFECT_MATRIX_CACHE = tuple(records)
    return _FBP_GENERIC_MESH_EFFECT_MATRIX_CACHE


def fbp_generic_mesh_effect_support(effect_id):
    normalized = fbp_normalize_effect_id(effect_id)
    return next((item for item in fbp_generic_mesh_effect_matrix() if item["effect_id"] == normalized), None)


def _fbp_generic_mesh_effect_ids():
    global _FBP_GENERIC_MESH_EFFECT_IDS_CACHE
    if _FBP_GENERIC_MESH_EFFECT_IDS_CACHE is None:
        _FBP_GENERIC_MESH_EFFECT_IDS_CACHE = tuple(
            item["effect_id"] for item in fbp_generic_mesh_effect_matrix() if item["supported"]
        )
    return _FBP_GENERIC_MESH_EFFECT_IDS_CACHE


def _fbp_generic_mesh_modifier_snapshot(modifier):
    """Capture one modifier using short-lived Python values for rollback."""
    if modifier is None:
        return None
    inputs = {}
    for item in modifier.node_group.interface.items_tree:
        if getattr(item, "item_type", "") != "SOCKET" or item.in_out != "INPUT":
            continue
        handle = _fbp_modifier_input_handle(modifier, item.identifier)
        if handle is None:
            continue
        values = {}
        for attr in ("type", "attribute_name", "value"):
            if not hasattr(handle, attr):
                continue
            value = getattr(handle, attr)
            if getattr(handle.bl_rna.properties.get(attr), "is_array", False):
                value = tuple(value)
            values[attr] = value
        inputs[item.identifier] = values
    state = {
        "name": str(getattr(modifier, "name", "") or ""),
        "node_group": getattr(modifier, "node_group", None),
        "inputs": inputs,
        "metadata": mesh_modifier_metadata(modifier),
    }
    for attr in ("show_viewport", "show_render", "show_in_editmode", "show_on_cage"):
        try:
            state[attr] = bool(getattr(modifier, attr))
        except FBP_DATA_ERRORS:
            pass
    return state


def _fbp_restore_generic_mesh_modifier(modifier, state):
    if modifier is None or not state:
        return False
    try:
        modifier.name = str(state.get("name", modifier.name) or modifier.name)
        modifier.node_group = state.get("node_group")
        for identifier, values in state.get("inputs", {}).items():
            handle = _fbp_modifier_input_handle(modifier, identifier)
            if handle is None:
                return False
            for attr, value in values.items():
                setattr(handle, attr, value)
        set_mesh_modifier_metadata(modifier, state.get("metadata", {}))
        for attr in ("show_viewport", "show_render", "show_in_editmode", "show_on_cage"):
            if attr in state:
                try:
                    setattr(modifier, attr, bool(state[attr]))
                except FBP_DATA_ERRORS:
                    pass
        return True
    except FBP_DATA_ERRORS:
        return False



_FBP_GENERIC_MESH_FULL_COORDINATE_SCAN_LIMIT = 5_000_000
_FBP_GENERIC_MESH_PYTHON_SCAN_LIMIT = 250_000
_FBP_GENERIC_MESH_FULL_TOPOLOGY_LIMIT = 100_000
_FBP_NUMPY_MODULE = None
_FBP_NUMPY_PROBED = False


def _fbp_optional_numpy():
    global _FBP_NUMPY_MODULE, _FBP_NUMPY_PROBED
    if not _FBP_NUMPY_PROBED:
        _FBP_NUMPY_PROBED = True
        try:
            _FBP_NUMPY_MODULE = importlib.import_module("numpy")
        except (ImportError, RuntimeError, TypeError, ValueError):
            _FBP_NUMPY_MODULE = None
    return _FBP_NUMPY_MODULE


def _fbp_mesh_coordinate_scan(mesh, *, full_scan_limit=_FBP_GENERIC_MESH_FULL_COORDINATE_SCAN_LIMIT, sample_limit=8192):
    """Return a bounded primitive finite-coordinate audit for one Mesh.

    NumPy performs the ordinary full scan in native code.  If NumPy is not
    available, Python scans only moderate meshes completely and uses a
    deterministic stride for larger data instead of freezing Blender's UI.
    """
    result = {
        "vertices": 0, "checked_vertices": 0, "non_finite_vertices": 0,
        "complete": True, "mode": "EMPTY", "first_non_finite": -1,
    }
    if mesh is None:
        result.update({"complete": False, "mode": "UNAVAILABLE"})
        return result
    try:
        vertices = getattr(mesh, "vertices", ()) or ()
        count = len(vertices)
        result["vertices"] = int(count)
        if not count:
            return result
        full_scan_limit = max(0, int(full_scan_limit))
        if count <= full_scan_limit and hasattr(vertices, "foreach_get"):
            np = _fbp_optional_numpy()
            if np is not None:
                try:
                    coordinates = np.empty(count * 3, dtype=np.float32)
                    vertices.foreach_get("co", coordinates)
                    finite_rows = np.isfinite(coordinates.reshape((count, 3))).all(axis=1)
                    invalid_mask = ~finite_rows
                    invalid_count = int(np.count_nonzero(invalid_mask))
                    first_invalid = int(np.argmax(invalid_mask)) if invalid_count else -1
                    result.update({
                        "mode": "FULL_NUMPY",
                        "checked_vertices": int(count),
                        "non_finite_vertices": invalid_count,
                        "first_non_finite": first_invalid,
                    })
                    return result
                except (AttributeError, MemoryError, OverflowError, RuntimeError, TypeError, ValueError):
                    # Fall back to the bounded Python path instead of rejecting a
                    # valid mesh only because the optional acceleration failed.
                    pass
            if count <= _FBP_GENERIC_MESH_PYTHON_SCAN_LIMIT:
                coordinates = array("f", [0.0]) * (count * 3)
                vertices.foreach_get("co", coordinates)
                result.update({"mode": "FULL_PYTHON", "checked_vertices": int(count)})
                for index in range(count):
                    offset = index * 3
                    if not (
                        math.isfinite(float(coordinates[offset]))
                        and math.isfinite(float(coordinates[offset + 1]))
                        and math.isfinite(float(coordinates[offset + 2]))
                    ):
                        result["non_finite_vertices"] += 1
                        if result["first_non_finite"] < 0:
                            result["first_non_finite"] = int(index)
                return result

        step = max(1, int(math.ceil(count / max(1, int(sample_limit)))))
        result.update({"complete": step == 1, "mode": "FULL_PYTHON" if step == 1 else "STRIDED"})
        for index in range(0, count, step):
            result["checked_vertices"] += 1
            co = vertices[index].co
            if not all(math.isfinite(float(component)) for component in co):
                result["non_finite_vertices"] += 1
                if result["first_non_finite"] < 0:
                    result["first_non_finite"] = int(index)
        return result
    except (AttributeError, MemoryError, OverflowError, ReferenceError, RuntimeError, TypeError, ValueError):
        result.update({"complete": False, "mode": "FAILED"})
        return result


def fbp_generic_mesh_topology_profile(obj, *, sample_limit=8192):
    """Return a primitive topology profile for a Generic Mesh target.

    This is diagnostic rather than restrictive: open and non-manifold meshes
    remain valid targets, but their topology class is recorded for reports and
    regression tests. Non-finite source coordinates are always rejected.
    """
    profile = {
        "valid_target": False,
        "classification": "INVALID",
        "vertices": 0,
        "edges": 0,
        "polygons": 0,
        "materials": 0,
        "boundary_edges": 0,
        "non_manifold_edges": 0,
        "loose_edges": 0,
        "sampled_vertices": 0,
        "non_finite_vertices": 0,
        "coordinate_scan_complete": False,
        "coordinate_scan_mode": "UNAVAILABLE",
        "first_non_finite_vertex": -1,
        "topology_scan_complete": False,
        "topology_scan_mode": "UNAVAILABLE",
        "sampled_edges": 0,
        "sampled_polygons": 0,
    }
    if obj is None or str(getattr(obj, "type", "") or "") != "MESH":
        return profile
    try:
        mesh = getattr(obj, "data", None)
        if mesh is None:
            return profile
        vertices = getattr(mesh, "vertices", ()) or ()
        edges = getattr(mesh, "edges", ()) or ()
        polygons = getattr(mesh, "polygons", ()) or ()
        vertex_count = len(vertices)
        edge_count = len(edges)
        polygon_count = len(polygons)
        profile.update({
            "valid_target": True,
            "vertices": vertex_count,
            "edges": edge_count,
            "polygons": polygon_count,
            "materials": len(getattr(mesh, "materials", ()) or ()),
        })
        coordinate_scan = _fbp_mesh_coordinate_scan(mesh, sample_limit=sample_limit)
        profile["sampled_vertices"] = int(coordinate_scan.get("checked_vertices", 0) or 0)
        profile["non_finite_vertices"] = int(coordinate_scan.get("non_finite_vertices", 0) or 0)
        profile["coordinate_scan_complete"] = bool(coordinate_scan.get("complete", False))
        profile["coordinate_scan_mode"] = str(coordinate_scan.get("mode", "UNAVAILABLE") or "UNAVAILABLE")
        profile["first_non_finite_vertex"] = int(coordinate_scan.get("first_non_finite", -1))

        topology_size = int(edge_count) + int(polygon_count)
        if topology_size > _FBP_GENERIC_MESH_FULL_TOPOLOGY_LIMIT:
            profile["topology_scan_complete"] = False
            profile["topology_scan_mode"] = "BOUNDED"
            profile["classification"] = (
                "NON_FINITE" if profile["non_finite_vertices"] else
                "WIRE" if polygon_count == 0 and edge_count else
                "POINTS" if polygon_count == 0 and vertex_count else
                "EMPTY" if not vertex_count else
                "LARGE_SURFACE"
            )
            return profile
        profile["topology_scan_complete"] = True
        profile["topology_scan_mode"] = "FULL"
        profile["sampled_edges"] = int(edge_count)
        profile["sampled_polygons"] = int(polygon_count)

        face_use = {}
        for polygon in polygons:
            polygon_vertices = tuple(int(index) for index in polygon.vertices)
            if len(polygon_vertices) < 2:
                continue
            for index, vertex in enumerate(polygon_vertices):
                other = polygon_vertices[(index + 1) % len(polygon_vertices)]
                key = (vertex, other) if vertex <= other else (other, vertex)
                face_use[key] = face_use.get(key, 0) + 1

        edge_keys = set()
        for edge in edges:
            try:
                a, b = (int(value) for value in edge.vertices)
            except (AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
                continue
            edge_keys.add((a, b) if a <= b else (b, a))
        profile["loose_edges"] = sum(1 for key in edge_keys if face_use.get(key, 0) == 0)
        profile["boundary_edges"] = sum(1 for count in face_use.values() if count == 1)
        profile["non_manifold_edges"] = sum(1 for count in face_use.values() if count > 2)

        if profile["non_finite_vertices"]:
            profile["classification"] = "NON_FINITE"
        elif polygon_count == 0:
            profile["classification"] = "WIRE" if edge_count else "POINTS" if vertex_count else "EMPTY"
        elif profile["non_manifold_edges"]:
            profile["classification"] = "NON_MANIFOLD"
        elif profile["boundary_edges"]:
            profile["classification"] = "OPEN_SURFACE"
        elif profile["loose_edges"]:
            profile["classification"] = "LOOSE_GEOMETRY"
        else:
            profile["classification"] = "CLOSED_MANIFOLD"
    except FBP_DATA_ERRORS:
        profile["valid_target"] = False
        profile["classification"] = "UNREADABLE"
    return profile


def fbp_generic_mesh_preflight(obj):
    """Validate ownership and source geometry before adding a modifier."""
    if obj is None or str(getattr(obj, "type", "") or "") != "MESH":
        return False, "Target is not a Mesh object", fbp_generic_mesh_topology_profile(obj)
    try:
        data = getattr(obj, "data", None)
        if getattr(obj, "library", None) is not None or getattr(data, "library", None) is not None:
            return False, "Linked mesh data cannot be modified", fbp_generic_mesh_topology_profile(obj)
        if getattr(obj, "override_library", None) is not None:
            return False, "Library Override objects are not Generic Mesh targets", fbp_generic_mesh_topology_profile(obj)
    except FBP_DATA_ERRORS:
        return False, "Target ownership could not be resolved", fbp_generic_mesh_topology_profile(obj)
    profile = fbp_generic_mesh_topology_profile(obj)
    if not profile.get("valid_target", False):
        return False, "Mesh data is unavailable", profile
    if int(profile.get("non_finite_vertices", 0) or 0):
        return False, "Source mesh contains non-finite vertex coordinates", profile
    return True, str(profile.get("classification", "MESH") or "MESH"), profile


def fbp_validate_generic_mesh_object(obj, *, depsgraph=None, sample_limit=2048):
    """Evaluate a Generic Mesh result and reject invalid/non-finite geometry.

    The returned tuple contains only primitives and is safe for reports. Empty
    geometry is allowed because some artistic effects can intentionally remove
    all points; evaluation failures and NaN/Inf positions are not.
    """
    if obj is None or str(getattr(obj, "type", "") or "") != "MESH":
        return (False, "Target is not a Mesh object")
    evaluated = None
    mesh = None
    try:
        if depsgraph is None:
            depsgraph = bpy.context.evaluated_depsgraph_get()
        try:
            depsgraph.update()
        except FBP_DATA_ERRORS:
            pass
        evaluated = obj.evaluated_get(depsgraph)
        mesh = evaluated.to_mesh()
        if mesh is None:
            return (False, "Evaluated modifier stack returned no mesh")
        vertices = getattr(mesh, "vertices", ())
        count = len(vertices)
        scan = _fbp_mesh_coordinate_scan(mesh, sample_limit=sample_limit)
        if int(scan.get("non_finite_vertices", 0) or 0):
            return (False, f"Non-finite evaluated vertex coordinate at index {int(scan.get('first_non_finite', -1))}")
        if str(scan.get("mode", "")) == "FAILED":
            return (False, "Evaluated mesh coordinates could not be validated")
        topology = fbp_generic_mesh_topology_profile(obj)
        coverage = "full" if bool(scan.get("complete", False)) else f"sampled {int(scan.get('checked_vertices', 0) or 0)}"
        return (
            True,
            f"Evaluated {count} vertices ({coverage}) · {topology.get('classification', 'MESH')}",
        )
    except Exception as exc:
        return (False, f"Evaluation failed: {type(exc).__name__}: {exc}")
    finally:
        if evaluated is not None and mesh is not None:
            try:
                evaluated.to_mesh_clear()
            except FBP_DATA_ERRORS:
                pass


def fbp_generic_mesh_duplicate_effects(obj):
    """Return duplicate FBP-owned Generic Mesh effect counts by effect id."""
    counts = {}
    if obj is None or str(getattr(obj, "type", "") or "") != "MESH":
        return {}
    try:
        modifiers = tuple(getattr(obj, "modifiers", ()) or ())
    except FBP_DATA_ERRORS:
        return {}
    for modifier in modifiers:
        try:
            if not mesh_modifier_metadata(modifier).get("fbp_generic_mesh_effect", False):
                continue
            effect_id = fbp_normalize_effect_id(mesh_modifier_metadata(modifier).get("fbp_effect_id", ""))
            if effect_id:
                counts[effect_id] = counts.get(effect_id, 0) + 1
        except FBP_DATA_ERRORS:
            continue
    return {effect_id: count for effect_id, count in counts.items() if count > 1}


def fbp_repair_generic_mesh_duplicates(obj):
    """Keep the first owned instance of each effect and remove later duplicates."""
    if obj is None or str(getattr(obj, "type", "") or "") != "MESH":
        return 0
    seen = set()
    duplicates = []
    try:
        modifiers = tuple(getattr(obj, "modifiers", ()) or ())
    except FBP_DATA_ERRORS:
        return 0
    for modifier in modifiers:
        try:
            if not mesh_modifier_metadata(modifier).get("fbp_generic_mesh_effect", False):
                continue
            effect_id = fbp_normalize_effect_id(mesh_modifier_metadata(modifier).get("fbp_effect_id", ""))
            if not effect_id:
                continue
            if effect_id in seen:
                duplicates.append(modifier)
            else:
                seen.add(effect_id)
        except FBP_DATA_ERRORS:
            continue
    removed = 0
    for modifier in reversed(duplicates):
        try:
            remove_mesh_modifier(modifier)
            removed += 1
        except FBP_DATA_ERRORS:
            continue
    return removed


def _fbp_generic_mesh_owned_effect_modifiers(obj, effect_id):
    """Return short-lived owned modifiers for one normalized effect id."""
    effect_id = fbp_normalize_effect_id(effect_id)
    if obj is None or not effect_id:
        return ()
    found = []
    try:
        modifiers = tuple(getattr(obj, "modifiers", ()) or ())
    except FBP_DATA_ERRORS:
        return ()
    for index, modifier in enumerate(modifiers):
        try:
            if getattr(modifier, "type", "") != "NODES":
                continue
            if not mesh_modifier_metadata(modifier).get("fbp_generic_mesh_effect", False):
                continue
            if fbp_normalize_effect_id(mesh_modifier_metadata(modifier).get("fbp_effect_id", "")) != effect_id:
                continue
            found.append((int(index), modifier))
        except FBP_DATA_ERRORS:
            continue
    return tuple(found)


def _fbp_generic_mesh_effect_state(obj, effect_id):
    """Capture every owned instance so a multi-object operation can roll back."""
    snapshots = []
    for index, modifier in _fbp_generic_mesh_owned_effect_modifiers(obj, effect_id):
        state = _fbp_generic_mesh_modifier_snapshot(modifier)
        if state is not None:
            state["index"] = int(index)
            snapshots.append(state)
    return tuple(snapshots)


def _fbp_restore_generic_mesh_effect_state(obj, effect_id, snapshots):
    """Restore one effect exactly enough for an immediate transaction rollback."""
    if obj is None:
        return False
    effect_id = fbp_normalize_effect_id(effect_id)
    try:
        for _index, modifier in reversed(_fbp_generic_mesh_owned_effect_modifiers(obj, effect_id)):
            remove_mesh_modifier(modifier)
        for state in tuple(snapshots or ()):
            modifier = obj.modifiers.new(
                name=str(state.get("name", "Frame By Plane Mesh Effect") or "Frame By Plane Mesh Effect"),
                type="NODES",
            )
            if not _fbp_restore_generic_mesh_modifier(modifier, state):
                return False
            try:
                current_index = tuple(obj.modifiers).index(modifier)
                desired_index = max(0, min(int(state.get("index", current_index)), len(obj.modifiers) - 1))
                if current_index != desired_index and hasattr(obj.modifiers, "move"):
                    obj.modifiers.move(current_index, desired_index)
            except FBP_DATA_ERRORS:
                pass
        return True
    except FBP_DATA_ERRORS:
        return False


def fbp_apply_geometry_effect_to_mesh_object(obj, effect_id, *, scene=None):
    if not fbp_feature_enabled(scene, "generic_mesh_effects"):
        return False
    effect_id = fbp_normalize_effect_id(effect_id)
    definition = fbp_effect_definition(effect_id)
    if not obj or str(getattr(obj, "type", "") or "") != "MESH":
        return False
    if not definition or definition.get("kind") != "GEOMETRY":
        return False
    if effect_id not in _fbp_generic_mesh_effect_ids():
        return False
    preflight_ok, preflight_reason, topology = fbp_generic_mesh_preflight(obj)
    if not preflight_ok:
        fbp_warn(
            f"Generic Mesh preflight rejected {effect_id}",
            RuntimeError(preflight_reason),
        )
        return False
    source_group = fbp_load_mesh_wiggle_group() if effect_id == FBP_EFFECT_MESH_WIGGLE else _fbp_load_effect_group(effect_id)
    if not source_group:
        return False
    try:
        interface_inputs = _fbp_interface_inputs(source_group)
        has_geometry_input, has_geometry_output = _fbp_node_group_geometry_contract(source_group)
        if not has_geometry_input or not has_geometry_output:
            fbp_warn(
                f"Generic Mesh effect {effect_id} does not expose a complete geometry input/output contract"
            )
            return False
    except FBP_DATA_ERRORS:
        return False
    modifier_name = str(definition.get("modifier_name", definition.get("label", effect_id)))
    modifier = None
    created_modifier = False
    previous_modifier_state = None
    try:
        # Reuse only modifiers explicitly owned by Frame By Plane. An artist may
        # already use the same bundled node group manually; adopting and tagging
        # that modifier would make Remove FBP Mesh Effects delete artist work.
        for candidate in obj.modifiers:
            if getattr(candidate, "type", "") != "NODES":
                continue
            try:
                owned = bool(mesh_modifier_metadata(candidate).get("fbp_generic_mesh_effect", False))
                candidate_effect_id = fbp_normalize_effect_id(
                    mesh_modifier_metadata(candidate).get("fbp_effect_id", "")
                )
            except FBP_DATA_ERRORS:
                owned = False
                candidate_effect_id = ""
            if owned and candidate_effect_id == effect_id:
                modifier = candidate
                previous_modifier_state = _fbp_generic_mesh_modifier_snapshot(candidate)
                break
        if modifier is None:
            modifier = obj.modifiers.new(name=modifier_name, type="NODES")
            created_modifier = True
        modifier.name = modifier_name
        modifier.node_group = source_group
        set_mesh_modifier_metadata(modifier, {
            "fbp_generic_mesh_effect": True,
            "fbp_effect_id": str(effect_id),
            "fbp_effect_schema": 1,
            "fbp_input_topology": str(topology.get("classification", "MESH") or "MESH"),
            "fbp_input_vertices": int(topology.get("vertices", 0) or 0),
            "fbp_input_edges": int(topology.get("edges", 0) or 0),
            "fbp_input_polygons": int(topology.get("polygons", 0) or 0),
        })
        for prop_name, socket_name in (definition.get("property_map", {}) or {}).items():
            if not hasattr(obj, prop_name):
                continue
            value = _fbp_cast_effect_value(prop_name, getattr(obj, prop_name))
            _fbp_set_modifier_input(modifier, source_group, socket_name, value, interface_inputs)
            identifier = _fbp_interface_socket_for_name(interface_inputs, socket_name)
            if not _fbp_effect_values_equal(_fbp_modifier_input_get(modifier, identifier), value):
                raise RuntimeError(f"Generic Mesh input {socket_name} did not retain its requested value")
        valid, reason = fbp_validate_generic_mesh_object(obj)
        if not valid:
            if created_modifier:
                try:
                    remove_mesh_modifier(modifier)
                except FBP_DATA_ERRORS:
                    pass
            else:
                _fbp_restore_generic_mesh_modifier(modifier, previous_modifier_state)
            fbp_warn(
                f"Generic Mesh effect {definition.get('label', effect_id)} failed validation",
                RuntimeError(reason),
            )
            return False
        return True
    except FBP_DATA_ERRORS as exc:
        if created_modifier and modifier is not None:
            try:
                remove_mesh_modifier(modifier)
            except FBP_DATA_ERRORS:
                pass
        elif modifier is not None and previous_modifier_state is not None:
            _fbp_restore_generic_mesh_modifier(modifier, previous_modifier_state)
        fbp_warn(f"Could not add {definition.get('label', effect_id)} to mesh object", exc)
        return False


def fbp_apply_geometry_effect_to_mesh_objects(objects, effect_id, *, scene=None):
    """Apply one Generic Mesh effect atomically to a set of objects.

    A multi-selection operation must not leave half of the selection modified
    when evaluation fails on a later object. All previous objects are restored
    to their exact FBP-owned modifier state before the failure is reported.
    """
    effect_id = fbp_normalize_effect_id(effect_id)
    targets = []
    seen = set()
    for obj in tuple(objects or ()):
        try:
            pointer = int(obj.as_pointer())
        except FBP_DATA_ERRORS:
            pointer = id(obj)
        if pointer in seen:
            continue
        seen.add(pointer)
        targets.append(obj)
    if not targets or not effect_id:
        return 0, "No valid mesh targets"

    states = tuple((obj, _fbp_generic_mesh_effect_state(obj, effect_id)) for obj in targets)
    changed = 0
    for obj in targets:
        if fbp_apply_geometry_effect_to_mesh_object(obj, effect_id, scene=scene):
            changed += 1
            continue
        rollback_failures = []
        for rollback_obj, snapshots in states:
            if not _fbp_restore_generic_mesh_effect_state(rollback_obj, effect_id, snapshots):
                try:
                    rollback_failures.append(str(getattr(rollback_obj, "name", "Mesh") or "Mesh"))
                except FBP_DATA_ERRORS:
                    rollback_failures.append("Mesh")
        try:
            failed_name = str(getattr(obj, "name", "Mesh") or "Mesh")
        except FBP_DATA_ERRORS:
            failed_name = "Mesh"
        detail = f"Validation failed on {failed_name}; all selected objects were rolled back"
        if rollback_failures:
            detail += f"; rollback incomplete for {', '.join(rollback_failures)}"
        return 0, detail
    return changed, ""


class FBP_OT_AddGenericMeshEffect(Operator):
    bl_idname = "fbp.add_generic_mesh_effect"
    bl_label = "Add Frame By Plane Mesh Effect"
    bl_description = "Apply a Frame By Plane mesh/Geometry Nodes effect to ordinary selected mesh objects"
    bl_options = {"REGISTER", "UNDO"}

    effect_id: StringProperty(description="Frame By Plane mesh effect id", default="", options={"SKIP_SAVE"})

    @classmethod
    def poll(cls, context):
        return bool(
            fbp_feature_enabled(getattr(context, "scene", None), "generic_mesh_effects")
            and _fbp_selected_generic_mesh_targets(context)
        )

    def execute(self, context):
        if not fbp_feature_enabled(getattr(context, "scene", None), "generic_mesh_effects"):
            self.report({"WARNING"}, "Enable Generic Mesh Preview in Frame By Plane Preferences")
            return {"CANCELLED"}
        effect_id = fbp_normalize_effect_id(self.effect_id)
        definition = fbp_effect_definition(effect_id)
        support = fbp_generic_mesh_effect_support(effect_id)
        if not support or not support["supported"]:
            reason = support["reason"] if support else "Unknown effect"
            self.report({"ERROR"}, f"Generic Mesh unsupported: {reason}")
            return {"CANCELLED"}
        changed, failure = fbp_apply_geometry_effect_to_mesh_objects(
            _fbp_selected_generic_mesh_targets(context), effect_id, scene=context.scene
        )
        if not changed:
            self.report({"ERROR"}, failure or "Could not apply mesh effect to selected objects")
            return {"CANCELLED"}
        self.report({"INFO"}, f"Applied {definition.get('label', effect_id)} to {changed} object(s)")
        return {"FINISHED"}


class FBP_OT_RepairGenericMeshDuplicates(Operator):
    bl_idname = "fbp.repair_generic_mesh_duplicates"
    bl_label = "Repair Duplicate Frame By Plane Mesh Effects"
    bl_description = "Keep the first Frame By Plane instance of each Generic Mesh effect and remove only later FBP-owned duplicates"
    bl_options = {"REGISTER", "UNDO"}

    @classmethod
    def poll(cls, context):
        return bool(_fbp_selected_generic_mesh_targets(context))

    def execute(self, context):
        removed = sum(
            fbp_repair_generic_mesh_duplicates(obj)
            for obj in _fbp_selected_generic_mesh_targets(context)
        )
        if not removed:
            self.report({"INFO"}, "No duplicate Frame By Plane mesh effects found")
            return {"CANCELLED"}
        self.report({"INFO"}, f"Removed {removed} duplicate Generic Mesh effect(s)")
        return {"FINISHED"}


class FBP_OT_RemoveGenericMeshEffects(Operator):
    bl_idname = "fbp.remove_generic_mesh_effects"
    bl_label = "Remove Frame By Plane Mesh Effects"
    bl_description = "Remove only Frame By Plane generic-mesh Geometry Nodes modifiers from selected objects"
    bl_options = {"REGISTER", "UNDO"}

    @classmethod
    def poll(cls, context):
        return bool(_fbp_selected_generic_mesh_targets(context))

    def execute(self, context):
        removed = 0
        for obj in _fbp_selected_generic_mesh_targets(context):
            try:
                for modifier in tuple(obj.modifiers):
                    if mesh_modifier_metadata(modifier).get("fbp_generic_mesh_effect", False):
                        remove_mesh_modifier(modifier)
                        removed += 1
            except FBP_DATA_ERRORS:
                continue
        if not removed:
            self.report({"INFO"}, "No Frame By Plane generic mesh effects found")
            return {"CANCELLED"}
        self.report({"INFO"}, f"Removed {removed} generic mesh effect(s)")
        return {"FINISHED"}


class FBP_MT_GenericMeshEffects(Menu):
    bl_idname = "FBP_MT_generic_mesh_effects"
    bl_label = "Frame By Plane Mesh Effects"
    bl_options = {"SEARCH_ON_KEY_PRESS"}

    def draw(self, context):
        layout = configure_layout(self.layout)
        scope = layout.row(align=True)
        scope.alert = True
        scope.label(text="Generic Mesh Effects · Preview", icon="INFO")
        scope.operator("fbp.copy_preview_diagnostics", text="Copy Diagnostics", icon="COPYDOWN")
        layout.label(text="Outside the Frame By Plane 8 LTS stability promise")
        if not fbp_feature_enabled(getattr(context, "scene", None), "generic_mesh_effects"):
            layout.label(text="Generic Mesh Preview is disabled", icon="INFO")
            return
        if not _fbp_selected_generic_mesh_targets(context):
            layout.label(text="Select a non-FBP Mesh object", icon="MESH_DATA")
            return
        actions = layout.row(align=True)
        actions.operator("fbp.remove_generic_mesh_effects", text="Remove", icon="X")
        actions.operator("fbp.repair_generic_mesh_duplicates", text="Repair", icon="TOOL_SETTINGS")
        layout.separator()
        for effect_id in _fbp_generic_mesh_effect_ids():
            definition = fbp_effect_definition(effect_id)
            op = layout.operator(
                FBP_OT_AddGenericMeshEffect.bl_idname,
                text=str(definition.get("label", effect_id)),
                **effect_icon_kwargs(effect_id, definition.get("icon", "MODIFIER")),
            )
            op.effect_id = effect_id


